export default [{"id":1375,"title":"غزوة يمين الدَّولة الغزنوي بلاد الغور .","date":["العام الهجري :401","العام الميلادي :1010"],"text":"كانت بلادُ الغورِ تُجاوِرُ غزنةَ، وكان الغور يقطعونَ الطَّريقَ، ويُخيفونَ السَّبيلَ، وبلادُهم جِبالٌ وَعرةٌ، ومضايقُ غَلقةٌ، وكانوا يحتَمون بها، ويعتَصِمون بصعوبةِ مَسلَكِها، فلمَّا كَثُرَ ذلك منهم أنِفَ يمينُ الدَّولة محمودُ بنُ سبكتكين أن يكونَ مثل أولئك المُفسدينَ جِيرانَه، وهم على هذه الحالِ مِن الفَسادِ والكُفرِ، فجمَعَ العساكِرَ وسار إليهم، وعلى مُقَدِّمتِه التونتاش الحاجِبُ، صاحِبُ هراة، وأرسلان الجاذبُ صاحِبُ طوس، وهما أكبَرُ أُمرائه، فسارا فيمَن معهما حتى انتَهَوا إلى مَضيقٍ قد شُحِنَ بالمُقاتلةِ، فتناوشوا الحَربَ، وصبَرَ الفريقانِ، فسَمِعَ يمينُ الدَّولة الحالَ، فجَدَّ في السيرِ إليهم، ومَلَك عليهم مَسالِكَهم، فتفَرَّقوا، وساروا إلى عظيمِ الغوريَّة المعروف بابن سوري، فانتهوا إلى مدينتِه التي تُدعى اهنكران، فبَرَز مِن المدينةِ في عشرةِ آلافِ مُقاتلٍ، فقاتَلَهم المُسلِمونَ إلى أن انتَصَف النهار، فرأوا أشجَعَ النَّاسِ وأقواهم على القِتالِ، فأمَرَ يمينُ الدَّولة أن يُولُّوهم الأدبارَ على سبيلِ الاستدراجِ، ففعلوا، فلمَّا رأى الغوريَّةُ ذلك ظَنُّوه هزيمةً، فاتَّبَعوهم حتى أبعَدوا عن مدينتِهم، فحينئذ عطفَ المُسلِمونَ عليهم ووَضَعوا السُّيوفَ فيهم فأبادوهم قَتلًا وأسْرًا، وكان في الأسرى كبيرُهم وزعيمُهم ابنُ سوري، ودخل المُسلِمونَ المدينةَ ومَلَكوها، وغَنِموا ما فيها، وفَتَحوا تلك القِلاعَ والحُصونَ التي لهم جميعَها، فلمَّا عايَنَ ابنُ سوري ما فعل المسلمونَ بهم شَرِبَ سُمًّا كان معه، فمات وأظهَرَ يمينُ الدَّولة في تلك الأعمالِ شِعارَ الإسلامِ، وجعل عندهم مَن يُعَلِّمُهم شَرائِعَه، ثمَّ عاد إلى غزنة."},{"id":1376,"title":"وباءٌ عظيم وشدة غلاء في خراسان .","date":["العام الهجري :401","العام الميلادي :1010"],"text":"اشتَدَّ الغَلاءُ بخراسانَ جَميعِها، وعَدَمُ القُوتِ، حتى أكلَ النَّاسُ بعضُهم بعضًا، فكان الإنسانُ يصيحُ: الخبزَ الخبزَ! ويموت، ثم تَبِعَه وباءٌ عظيم حتى عَجَزَ النَّاسُ عن دَفنِ الموتى."},{"id":1377,"title":"وفاة أبي عبيد الهروي .","date":["العام الهجري :401","الشهر القمري : رجب","العام الميلادي :1011"],"text":"هو العلَّامةُ أبو عُبَيدٍ أحمَدُ بنُ محمَّد بن أبي عُبَيد العَبديُّ الهَرويُّ الشافعيُّ اللُّغويُّ المؤدِّبُ، صاحِبُ \"الغَريبَينِ\" اللُّغويُّ البارِعُ، كان مِن أعلَمِ النَّاسِ في الأدَبِ واللُّغة. وكتابه \"الغريبينِ في مَعرفةِ القُرآنِ والحديث\" يدلُّ على اطِّلاعِه وتبحَرُّه في هذا الشأنِ، وكان من تلامذةِ أبي منصورٍ الأزهريِّ. قال ابن خَلِّكانَ: \" سار كتابُه في الآفاقِ، وهو من الكتُبِ النافعةِ, وقيل: كان يحِبُّ البِذلةَ - البِذلةُ تركُ الاحتشامِ والتَّصوُّنِ، وتَدَنِّي السُّلوكِ- وكان يتناوَلُ في الخلوةِ، ويُعاشِرُ أهلَ الدبِّ في مجالِسِ اللَّذَّة والطَّرَب، عفا الله عنه وعنَّا, وأشار الباخرزي في ترجمة بعض أُدَباء خراسان إلى شَيءٍ مِن ذلك، والله أعلم \"."},{"id":1378,"title":"الخليفة العباسي القادر بالله يطعن في نسب العبيديين الفاطميين .","date":["العام الهجري :402","العام الميلادي :1011"],"text":"كُتِبَ ببغدادَ مَحضَرٌ يتضَمَّنُ الطَّعنَ والقَدحَ في نَسَبِ الفاطميِّينَ، وهم ملوكُ مِصرَ فليسُوا كذلك، وإنَّما نسَبُهم إلى عُبيدِ بنِ سَعدٍ الجَرميِّ، وكَتَب في ذلك جماعةٌ من العُلَماءِ والقُضاة والأشراف والعُدول، والصالحين والفُقهاء، والمحَدِّثين، وشَهِدوا جميعًا أنَّ الحاكِمَ بمِصرَ: منصورُ بنُ نِزارِ الملَقَّب بالحاكم- حَكَمَ اللهُ عليه بالبَوارِ والخِزيِ والدَّمارِ- بن مَعد بنِ إسماعيلَ بنِ عبد الله بن سعيد، لا أسعَدُه الله؛ فإنَّه لَمَّا صار إلى بلاد المغرِبِ تَسمَّى بعُبَيد الله، وتلَقَّب بالمهديِّ، وأنَّ مَن تقَدَّمَ مِن سَلَفِه أدعياءُ خوارِجُ، لا نسَبَ لهم في ولدِ عليِّ بنِ أبي طالبٍ، ولا يتعَلَّقونَ بسَببٍ، وأنَّه مُنَزَّهٌ عن باطلهم، وأنَّ الذي ادَّعَوه إليه باطِلٌ وزُورٌ، وأنَّهم لا يَعلَمونَ أحدًا مِن أهل بيوتاتِ عليِّ بنِ أبي طالب توقَّف عن إطلاقِ القَولِ في أنَّهم خوارِجُ كَذَبةٌ، وقد كان هذا الإنكارُ لباطِلِهم شائعًا في الحَرَمينِ، وفي أوَّلِ أمْرِهم بالمَغربِ مُنتشِرًا انتشارًا يمنع أن يُدَلَّسَ أمرُهم على أحدٍ، أو يذهَبَ وَهمٌ إلى تَصديقِهم فيما ادَّعوه، وأنَّ هذا الحاكِمَ بمِصرَ هو وسَلَفُه كُفَّارٌ فُسَّاقٌ فُجَّارٌ، مُلحِدون زنادِقة، مُعَطِّلون، وللإسلامِ جاحدون، ولِمَذهب المجوسيَّة والثنويَّة مُعتَقِدونَ، قد عطَّلوا الحُدودَ، وأباحوا الفُروجَ، وأحلُّوا الخَمرَ، وسَفَكوا الدِّماءَ، وسَبَوا الأنبياءَ، ولَعَنوا السَّلَف، وادَّعَوا الرُّبوبيَّة.وقد كتَبَ خَطَّه في المَحضَرِ خَلقٌ كَثيرٌ؛ فمِن العَلَويِّينَ: الشَّريفُ المُرتضى وأخوه الرَّضِي، وابن البطحاويِّ العَلَوي، وابن الأزرق المُوسَوي، والزكي أبو يعلى عمرُ بن محمد، ومن القُضاة: ابنُ الأكفاني، وابن الخرزي، وأبو العبَّاسِ الأبيوردي، وأبو عبدِ اللهِ بنُ النُّعمان، فقيه الشيعة، ومِن الفُقَهاءِ: أبو حامدٍ الإسفرايينيِّ، والكشفلي، والقُدوري، والصيمري، وأبو عبد الله بن البيضاوي، وأبو الفَضلِ النَّسَوي، ومن الشُّهودِ: أبو القاسِمِ التَّنوخيُّ في كثيرٍ منهم، وكَتَبَ فيه خلقٌ كثيرٌ غيرَهم. قال أبو الفرجِ بنُ الجوزي: \"وممَّا يدُلُّ على أنَّ هؤلاء أدعياءُ كَذَبةٌ، كما ذكَرَ هؤلاء السَّادة العُلَماء، والأئِمَّة الفُضَلاء، وأنَّهم لا نسَبَ لهم إلى عليِّ بن أبي طالب، ولا إلى فاطمةَ، كما يَزعُمونَ؛ قَولُ ابنِ عُمَرَ للحُسَينِ بنِ علي حين أراد الذَّهابَ إلى العراق، وذلك حين كتَبَ عَوامُّ أهلِ الكوفةِ بالبَيعةِ إليه، فقال له ابنُ عمر: لا تذهَبْ إليهم؛ فإني أخافُ عليك أن تُقتَلَ، وإنَّ جَدَّك قد خُيِّرَ بين الدنيا والآخرةِ فاختار الآخِرةَ على الدنيا، وأنت بَضعةٌ منه، وإنَّه- والله- لا تنالها لا أنت ولا أحَدٌ مِن خَلَفِك ولا مِن أهلِ بَيتِك، فهذا الكلامُ الحسَنُ الصَّحيحُ المتوَجِّه المعقول، من هذا الصَّحابيِّ الجليلِ، يقتضي أنَّه لا يلي الخلافةَ أحَدٌ مِن أهلِ البَيتِ إلَّا مُحمَّدُ بنُ عبد اللهِ المهديُّ الذي يكونُ في آخِرِ الزَّمانِ عندَ نُزولِ عيسى بنِ مريم؛ رغبةً بهم عن الدُّنيا، وألَّا يُدَنَّسوا بها. ومعلومٌ أنَّ هؤلاء قد مَلَكوا ديارَ مِصرَ مُدَّةً طَويلةً، فدَلَّ ذلك دَلالةً قَويَّةً ظاهِرةً على أنَّهم ليسوا مِن أهلِ البَيتِ، كما نَصَّ عليه سادةُ الفُقَهاءِ\". قال ابن كثير: \"وقد صَنَّف القاضي الباقلَّاني كتابًا في الردِّ على هؤلاء، وسَمَّاه: (كَشْف الأسرارِ وهَتْك الأستار) بيَّنَ فيه فضائِحَهم وقبائِحَهم، ووضَّحَ أمْرَهم لكُلِّ أحدٍ، ووضوحُ أمْرِهم يُنبئُ عن مطاوي أفعالِهم وأقوالِهم، وقد كان الباقلَّاني يقولُ في عبارته عنهم: هم قومٌ يُظهِرونَ الرَّفضَ، ويُبطِنونَ الكُفرَ المَحض\". قال شيخُ الإسلامِ ابنُ تيميَّةَ: \"وهؤلاء القومُ- يعني العُبَيديِّينَ- يَشهَدُ عليهم عُلَماءُ الأمَّةِ وأئمَّتُها وجماهيرُها أنَّهم كانوا مُنافِقينَ زَنادقةً، يُظهِرونَ الإسلامَ ويُبطِنونَ الكُفرَ, وقد عُلِمَ أنَّ جُمهورَ الأمَّة تَطعَنُ في نَسَبِهم، وَيذكُرونَ أنَّهم من أولادِ المجوسِ أو اليهودِ، هذا مشهورٌ مِن شهادةِ عُلَماءِ الطَّوائِفِ: من الحنفيَّة والمالكيَّة والشَّافعية والحنابلة وأهلِ الحديثِ، وأهلِ الكلامِ، وعُلَماءِ النَّسَبِ، والعامَّة وغيرهم, وهذا أمرٌ قد ذكَرَه عامَّةُ المُصَنِّفينَ لأخبارِ النَّاسِ وأيَّامِهم، حتى بعض مَن قد يتوقَّفُ في أمْرِهم، كابنِ الأثيرِ المَوصليِّ في تاريخِه، ونحوه؛ فإنَّه ذكَرَ ما كتَبَه عُلَماءُ المُسلِمينَ بخُطوطِهم في القَدحِ في نَسَبِهم\""},{"id":1379,"title":"وزيرُ بهاء الدَّولة البُويهيّ يأذن للرافضة بإظهار بدعهم في عاشوراء .","date":["العام الهجري :402","العام الميلادي :1011"],"text":"في هذه السَّنةِ أَذِنَ فَخرُ الملك وزيرُ بهاء الدَّولة البُويهيِّ للرَّوافِضِ أن يَعمَلوا بِدعَتَهم الشَّنعاءَ، والفضيحةَ الصَّلعاءَ، من الانتحابِ والنَّوحِ والبُكاءِ، وتعليقِ المُسوح، وأن تُغلَقَ الأسواقُ مِن الصَّباحِ إلى المَساء، وأن تدورَ النِّساءُ حاسراتٍ عن وُجوهِهنَّ ورُؤوسِهنَّ، يَلطِمنَ خُدودَهنَّ، كفِعلِ الجاهليَّةِ الجهلاءِ، على الحُسَينِ بنِ عليٍّ رَضِيَ الله عنه."},{"id":1380,"title":"غزو يمين الدَّولة الغزنوي قصدار في بلاد السند .","date":["العام الهجري :402","الشهر القمري : جمادى الأولى","العام الميلادي :1011"],"text":"كان مَلِكُ قصدار قد صالحَ يَمينَ الدَّولةِ محمودَ سبكتكين على مالٍ يُؤدِّيه إليه، ثمَّ قطَعَه اغتِرارًا بحَصانةِ بَلَدِه، وكَثرةِ المضايِقِ في الطريقِ، واحتمى بايلك الخان، وكان يمينُ الدَّولة يريدُ قَصْدَها، فيتَّقي ناحيةَ إيلك الخان، فلمَّا فَسَدَ ذاتُ بينهما صَمَّمَ العزمَ وقَصَدَها وتجَهَّزَ، وأظهَرَ أنَّه يريدُ هَراةَ، فسار مِن غزنةَ في جمادى الأولى، فلمَّا استَقَلَّ على الطريقِ، سار نحو قصدار، فسبَقَ خَبَرُه، وقطَعَ تلك المضايقَ والجبَل، فلم يشعُرْ صاحِبُها إلَّا وعسكَرُ يمينِ الدَّولة قد أحاط به ليلًا، فطلب الأمانَ فأجابه وأخَذَ منه المالَ الذي كان قد اجتمَعَ عنده، وأقَرَّه على ولايتِه وعاد."},{"id":1381,"title":"سقوط دولة بني زياد وقيام إمارة بني نجاح في اليمن .","date":["العام الهجري :403","العام الميلادي :1012"],"text":"تأسَّست إمارةُ بَني نجاح على أنقاضِ دولةِ بَني زيادٍ، أسَّسَها الأميرُ نجاحٌ، مَولى مُرجانَ الحَبشيِّ، حاجِبِ أميرِ بَني زيادٍ بعدَ انتهاءِ دولةِ بَني زيادٍ، فقَضى على مَولاه مُرجانَ وعلى مُنافِسِه نَفيسٍ، اللَّذيْنِ قتَلَا الأميرَ عبدَ اللهِ بنَ أبي الجيشِ آلَ زيادٍ. فأعلنَ نَفْسَه سُلطانًا على تِهامةَ، وضَبطَ الأميرُ نجاحٌ تِهامةَ ضَبطًا تامًّا، أمَّا الجبالُ التي كانت خاضِعةً لِأسلافِه فإنَّها أفلتت مِن يَدِه. وقامت صِراعاتٌ بينَ النَّجاحيِّينَ والصُّلَيحيِّينَ كثيرًا، وشرعَ نجاحٌ في مُراسلةِ الخَليفةِ العباسيِّ القادرِ باللهِ ببغدادَ مُعلنًا ولاءَه وطاعتَه لِلدولةِ العباسيةِ، فأجازَه بذلك ونعَتَه بالمُؤيَّدِ نَصيرِ الدِّينِ. وساعدَه في مُقاومةِ الصُّلَيحيِّينَ في الحُروبُ الطويلةِ والتقليديةِ التي قامت بينَ الدَّولتيْنِ طيلةَ عَهدَيْهما تقريبًا. وبعدَ مَقتَلِه بالسُّمِّ عامَ 452هـ عن طريقِ جاريةٍ جميلةٍ أهداها إليه علِيُّ بنُ محمدٍ الصُّلَيحيُّ استَولى بَنو صُلَيحٍ على المَدينةِ، وضَمُّوها إليهم حتى استرَدَّها سعيدُ بنُ نجاحٍ عامَ 473هـ-1080م. ولَمَّا كانَ أولادُ الأميرِ نجاحٍ عندَ مَوتِه دونَ البُلوغِ فإنَّه قامَ بالأمرِ عنهم مَولى أبيهم مُرجانُ الكَهلانيُّ."},{"id":1382,"title":"وفاة إيلك خان ملك الترك .","date":["العام الهجري :403","العام الميلادي :1012"],"text":"هو إيلك الخان عليُّ بنُ نصر أحدُ مُلوكِ الكرخانيين _ إيلك الخان: لَقَبُ ملوك الكرخانيِّين التركي- وكان أيلك خان خيِّرًا عادلًا محبًّا للدِّينِ وأهله. دخَلَت قبائِلُ الكرخانيِّينَ في الإسلامِ في نهاية القَرنِ الرَّابعِ، وقد تمكَّنَ إيلك الخان أن يأخُذَ بُخارى وسمرقند من السَّامانيِّين، ثمَّ حاول أن يتوسَّعَ في خُراسان، لكِنَّ السُّلطانَ محمودَ الغزنوي هَزَمَه في أكثَرَ مِن موقعة. توفِّيَ إيلك الخان وهو يتجهَّزُ للعَودِ إلى خراسان، ليأخُذَ بثأره من يمينِ الدَّولة الغزنويِّ، وكاتَبَ قدرخان وأخاه طغان خان ليُساعِداه على ذلك، فلمَّا توفِّيَ وَلِيَ بَعدَه أخوه طغان، فراسَلَ يَمينَ الدَّولة وصالَحَه، وقال له: المَصلحةُ للإسلامِ والمُسلِمينَ أن تشتَغِلَ أنت بغزوِ الهند، وأشتَغِلَ أنا بغزو التُّركِ، وأن يَترُكَ بَعضُنا بعضًا، فوافق ذلك هواه، فأجابه إليه، وزال الخِلافُ، واشتغلا بغَزوِ الكُفَّار."},{"id":1383,"title":"الخلاف بين أبناء البيت الأمويين بالأندلس  .","date":["العام الهجري :403","العام الميلادي :1012"],"text":"اجتمع البربَرُ فقَدَّموا على أنفُسِهم سُلَيمانَ بنَ الحَكَمِ بنِ سُلَيمانَ بنِ عبد الرحمن الناصرِ، فنهض بالبربَرِ إلى الثَّغرِ واستجاش بالنَّصارى وأتى بهم إلى بابِ قُرطبةَ فبرَزَ إليه جماعةُ أهلِ قُرطبةَ، فلم تكُنْ إلَّا ساعةٌ حتى قُتِلَ مِن أهلِ قُرطبةَ نَيِّفٌ وعشرونَ ألفَ رجُلٍ في جبَلٍ هنالك يُعرَفُ بجبلِ قنطش، وهي الوقعةُ المشهورة، ذهب فيها من الخِيارِ والفُقَهاءِ وأئمَّةِ المساجِدِ والمؤذِّنينَ خَلقٌ كثيرٌ، واستتَرَ مُحمَّدُ بنُ هشام المهديُّ أيامًا ثمَّ لحِقَ بطُلَيطِلة، وكانت الثغورُ كُلُّها من طرطوشة إلى الأشبونة باقيةً على طاعتِه ودَعوتِه، واستجاش بالإفرنجِ وأتى بهم إلى قُرطبةَ، فبَرَز إليه سُلَيمانُ بنُ الحَكَمِ مع البربر إلى موضعٍ بقُربِ قُرطُبةَ على نحوِ بضعةَ عشر ميلًا يُدعَى دارَ البَقَر، فانهزم سُلَيمانُ والبربَرُ، واستولى المهديُّ على قُرطُبةَ ثمَّ خرج بعد أيَّامٍ إلى قتالِ جمهورِ البربر، وكانوا قد عاثُوا بالجزيرةِ، فالتَقَوا بموضعٍ يُعرَفُ بوادي أره، فكانت الهزيمة على مُحمَّدِ بنِ هشامٍ المهديِّ، وانصرف إلى قُرطُبةَ، فوثب عليه العَبيدُ مع واضحٍ الصَّقلبيِّ فقتلوه ورَدُّوا هِشامًا المؤيَّدَ، فكانت مدَّةُ ولاية المهديِّ منذ قام إلى أن قُتِلَ سبعة عشر شهرًا مِن جُملتِها السِّتَّة الأشهر التي كان فيها سُلَيمانُ بقُرطُبة، وكان هو بالثَّغرِ، وانقَرَض عَقِبُه فلا عَقِبَ له، فقام سُلَيمانُ بنُ الحكم يوم الجمعة لسِتٍّ خَلَونَ مِن شَوَّال سنة 399هـ وتلقَّبَ بالمُستعين بالله، ثمَّ دخل قُرطُبةَ في ربيع الآخر سنة 400ه، فتلقَّبَ حينئذ بالظَّافِرِ بحَولِ الله، مضافًا إلى المستعين بالله، ثمَّ خرج عنها في شوال مِن السنة بعينها، فلم يزل يجول بعساكِرِ البربَرِ معه في بلاد الأندلُسِ يُفسِدُ وينهَبُ ويُقفِرُ المدائِنَ والقُرى بالسَّيف والغارةِ، لا يُبقي البربرُ معه على صغيرٍ ولا كبيرٍ، ولا امرأةٍ، إلى أن دخل قُرطبةَ في صدر شوال سنة 403، وأُحضِرَ هِشامٌ المُؤَيَّدُ فخَلَعَه من الخلافةِ، وأمره بمبايعتِه، فبويع لسليمانَ هذا، ثمَّ قَبَض على القائِدِ واضحٍ قائِدِ هِشامٍ المُؤَيَّدِ وقَتَلَه."},{"id":1384,"title":"قيام الدَّولة الأسدية غرب بغداد .","date":["العام الهجري :403","العام الميلادي :1012"],"text":"خلع سُلطانُ الدَّولةِ على أبي الحَسَنِ عليِّ بن مزيد الأسديِّ، وهو أوَّلُ مَن تقَدَّم من أهلِ بَيتِه؛ حيث أسنَدَ له إمارةَ الحلَّة، فكانت هذه بدايةَ دولتِهم التي استمَرَّت إلى عام 545هـ"},{"id":1385,"title":"وفاة أبي القاسم الزهراوي الطبيب  .","date":["العام الهجري :403","العام الميلادي :1012"],"text":"هو خَلَفُ بنُ عَبَّاس الزهراوي الأندلُسيُّ، طبيبٌ وعالمٌ وخبيرٌ بالأدويةِ المُفرَدة والمُرَكَّبة، وكان طبيبَ البَلاطِ في عهدِ الحُكمِ الثَّاني الأُمويِّ، كان مِن أهلِ الفَضلِ والدِّينِ والعِلمِ، وعِلمُه الذي سبَقَ عِلمَ الطِّبِّ, وله تصانيفُ مَشهورةٌ في صناعة الطب، أفضَلُها كتابُه الكبيرُ المعروف \"بالزهراوي\" وله كتابٌ كبيرٌ مَشهورٌ كبيرُ الفائدة، سمَّاه كتاب \"التَّصريف لِمَن عجَزَ عن التَّأليف\" في 30 جزءًا. ذكرَه ابنُ حَزمٍ وأثنى عليه، وقال: \"ولئِنْ قُلنْا: إنَّه لم يُؤَلَّفْ في الطِّبِّ أجمَعُ منه للقَولِ والعمَلِ في الطبائِعِ، لَنَصْدُقنَّ\". وكان أكبَرَ جرَّاحي زمانِه، وهو أوَّلُ مَن ألَّفَ في الجِراحةِ، وأوَّلُ مَن استعملَ رَبطَ الشِّريانِ بخَيطِ الحرير، له اهتمامٌ بجراحة العيونِ، اخترع كثيرًا من الأدواتِ الجراحيَّةِ، وكان له الفَضلُ في معرفة كيفيَّةِ جراحةِ كثيرٍ مِن العمَليَّات، وصناعة الأدواتِ المُساعدة، وكان بارعًا كذلك بصُنعِ العقاقيرِ والأدويةِ، تُرجِمَت كتُبُه، واقتَبَس منه أطبَّاءُ أوربَّا، وقد استفادوا مِن عِلمِه كثيرًا وخاصَّةً مُختَرعاتِه، بل إنَّ بَعضَ اختراعاتِه يُستعمَلُ إلى اليومِ كما هو، وبعضُها عُدِّلَ قليلًا بما يلائِمُ صناعاتِ اليوم، وقد اختُلِفَ في موتِه، والراجح موتُه في هذا العام عن 79 عامًا."},{"id":1386,"title":"وفاة بهاء الدَّولة بن بويه الشيعي وقيام ولده سلطان الدَّولة بعده .","date":["العام الهجري :403","الشهر القمري : جمادى الآخرة","العام الميلادي :1013"],"text":"هو بهاءُ الدَّولةِ أبو نَصرِ بنُ عَضدِ الدَّولة بنِ بُوَيه الديلميُّ الشيعيُّ، وهو المتحَكِّمُ حينئذٍ بالعراقِ، خلع بهاءُ الدَّولةِ الخليفةَ الطائِعَ للهِ، ونصَبَ القادرَ باللهِ مَكانَه. بينما كان هو خاضِعًا للسُّلطانِ محمودِ بنِ سبكتكين، مُداريًا له، مُؤثِرًا لمُصافاتِه بحُكمِ الجِوارِ. كان مرَضُه الذي مات فيه تتابع الصَّرَع مثل مرَضِ أبيه، وكان موتُه بأرجان، وحُمِلَ إلى مشهد أميرِ المؤمنين عليٍّ، فدُفِنَ عند أبيه عَضُدِ الدَّولة، وكان مُلكُه 24 سنة، وقيل 22 سنة، وعمره 42 سنة و9 أشهر، ولَمَّا توفِّيَ وَلِيَ المُلكَ بعده ابنُه سلطان الدَّولة أبو شُجاع، وسار من أرجان إلى شيراز، وولَّى أخاه جلالَ الدَّولةِ أبا طاهر بنَ بهاء الدَّولة البَصرةَ، وأخاه أبا الفوارِسِ كرمان. بقيَ أبو شجاعٍ في المُلكِ 12 سنة، وأَخَذَت الدَّولةُ البُويهيَّة تتناقَصُ خِلالَها."},{"id":1387,"title":"الفتنة بين المسلمين والنصارى ببغداد .","date":["العام الهجري :403","الشهر القمري : شوال","العام الميلادي :1013"],"text":"تُوفِّيَت زوجةُ بَعضِ رُؤَساءِ النصارى، فخَرَجَت النوائِحُ والصُّلبانُ معها جِهارًا، فأنكَرَ ذلك بعضُ الهاشميِّينَ، فضَرَبه بعضُ غِلمانِ ذلك الرَّئيسِ النصرانيِّ بدبوسٍ في رأسِه فشَجَّه، فثار المسلمونَ بهم فانهزموا حتى لجؤوا إلى كنيسةٍ لهم هناك، فدخَلَت العامَّةُ إليها فنَهَبوا ما فيها، وما قَرُب منها مِن دورِ النَّصارى، وتتَبَّعوا النصارى في البَلَدِ، وقصَدوا النَّاصِحَ وابن أبي إسرائيلَ فقاتَلَهم غِلمانُهما، وانتشرت الفتنةُ ببغداد، ورفَعَ المسلمونَ المصاحفَ في الأسواق، وعُطِّلَت الجمَعُ في بعضِ الأيَّام، واستعانوا بالخليفةِ، فأمر بإحضارِ ابنِ أبي إسرائيل فامتَنَع، فعزم الخليفةُ على الخروجِ مِن بغداد، وقَوِيَت الفتنةُ جِدًّا، ونُهِبَت دُورُ كثيرٍ مِن النصارى، ثمَّ أُحضِرَ ابنُ أبي إسرائيل، فبذل أموالًا جزيلة، فعفى عنه، وسكَنَت الفتنةُ."},{"id":1388,"title":"يَمينُ الدَّولةِ الغزنوي يغزو الهند ويفتح نادرين .","date":["العام الهجري :404","العام الميلادي :1013"],"text":"سار يَمينُ الدَّولةِ الغزنوي عندما خرج الشِّتاءُ غازيًا إلى الهندِ في جمعٍ عَظيمٍ وحَشدٍ كثيرٍ، وقصَدَ واسِطةَ البلادِ مِن الهند، فسار شَهرينِ، حتى قارَبَ مَقصِدَه، ورتَّب أصحابَه وعساكِرَه، فسَمِعَ عَظيمُ الهند به، فجَمَع مَن عِندَه مِن قُوَّادِه وأصحابِه، وبرز إلى جَبَلٍ هناك، صَعبِ المرتقى، ضَيِّقِ المسلَكِ، فاحتمى به، وكتَبَ إلى الهنودِ يستدعيهم مِن كُلِّ ناحية، فاجتمع عليه منهم كلُّ مَن يحمِلُ سلاحًا، فلمَّا تكامَلَت عِدَّتُه نزل مِن الجَبَل، وتصافَّ هو والمُسلِمونَ، واشتَدَّ القِتالُ وعَظُم الأمرُ، ثمَّ إنَّ الله تعالى منح المسلمينَ أكتافَهم فهَزَموهم، وأكثَروا القَتَل فيهم، وغَنِموا ما معهم من مالٍ وفيلٍ وسلاحٍ، وغير ذلك، وفتَحَ اللهُ نادرين, ووجد المسلمونَ في بَيتِ الصَّنَمِ حَجَرًا عظيمًا منقوشًا عليه، دلَّت كتابتُه على أنَّه مبنيٌّ منذ قرونٍ طويلة، فعَجِبَ المسلمونَ لقِلَّةِ عُقولِهم, فلمَّا فرغ الغزنويُّ مِن غَزوتِه عاد إلى غزنة، وأرسل إلى القادِرِ بالله يطلُبُ منه مَنشورًا، وعهدًا بخراسانَ وما بيده من المَمالِك، فكتب له بذلك، ولُقِّبَ نظامَ الدين."},{"id":1389,"title":"الحاكم العبيدي الفاطمي يأمر بحظر التجول على النساء .","date":["العام الهجري :404","العام الميلادي :1013"],"text":"منَعَ الحاكِمُ صاحِبُ مِصرَ النِّساءَ مِن الخروجِ مِن منازلهم، أو أن يَطَّلِعنَ مِن الأسطِحةِ أو الطَّاقاتِ، ومنَعَ الخَفَّافينَ مِن عَمَلِ الخِفافِ لهن، ومنَعَهنَّ مِن الخروجِ إلى الحَمَّامات، وقتَلَ خَلقًا مِن النساءِ على مخالفتِه في ذلك، وهدَمَ بَعضَ الحَمَّامات عليهنَّ، وجَهَّزَ نساءً عَجائِزَ كثيرةً يَستَعلِمنَ أحوالَ النِّساءِ لِمَن يَعشَقْنَ أو يَعشَقُهنَّ، بأسمائِهنَّ وأسماءِ مَن يتعَرَّضُ لهن، فمَن وجَدَ منهن كذلك أطفأها وأهلَكَها، ثم إنَّه أكثَرَ مِن الدورانِ بنَفسِه ليلًا ونهارًا في البلد، في طلَبِ ذلك، وقد أكَّدَ على هذا المرسومِ في العام التالي، وبقي على ذلك من المنعِ إلى هلاكِ الحاكِمِ."},{"id":1390,"title":"غزو تانشير بالهند .","date":["العام الهجري :405","العام الميلادي :1014"],"text":"ذُكِرَ ليَمينِ الدَّولة الغزنويِّ أنَّ بناحيةِ تانشير فِيَلةً مِن جنسِ فِيَلةِ الصيلمان الموصوفةِ في الحربِ، وأنَّ صاحِبَها غالٍ في الكُفرِ والطُّغيان، والعِنادِ للمُسلِمينَ، فعَزَم على غَزوِه في عُقرِ دارِه، فسار في الجنودِ والعساكِرِ والمتطَوِّعة، فلَقِيَ في طريقِه أوديةً بعيدةَ القَعرِ، وَعْرةَ المسالِك، وقِفارًا فسيحةَ الأقطارِ والأطراف، بعيدةَ الأكنافِ، والماءُ بها قليلٌ، فلَقُوا شِدَّةً، وقاسَوا مَشقَّةً إلى أن قطَعُوها، فلَمَّا قارَبوا مَقصِدَهم لَقُوا نهرًا شديدَ الجريةِ، صَعْبَ المخاضةِ، وقد وقف صاحِبُ تلك البلادِ على طَرفِه، يمنَعُ مِن عُبورِه، ومعه عساكِرُه، وفِيَلَتُه التي كان يتعالى بها. فأمر يمينُ الدَّولةِ شُجَعانَ عَسكَرِه بعبورِ النَّهرِ، وإشغالِ الكُفَّارِ بالقتالِ ليتمَكَّنَ باقي العسكَرِ مِن العبور، ففعلوا ذلك، وقاتلوا الهنودَ، وشَغَلوهم عن حِفظِ النَّهرِ، حتى عبَرَ سائِرُ العسكَرِ في المخاضات، وقاتلوهم من جميعِ جِهاتِهم إلى آخِرِ النَّهارِ، فانهزم الهِندُ، وظَفِرَ المُسلِمونَ، وغَنِموا ما معهم من أموالٍ وفِيَلةٍ، وعادوا إلى غزنةَ مُوفرينَ ظافِرينَ."},{"id":1391,"title":"قيام دولة بني حماد بالمغرب الأوسط .","date":["العام الهجري :405","العام الميلادي :1014"],"text":"في سنة 387ه عقَدَ باديسُ بنُ منصورِ بنِ بلكينَ صاحِبُ إفريقيَّةَ الوِلايةَ لِعَمِّه حمَّادِ بنِ بلكين على أشيرَ، فاتَّسَعَت ولايةُ حمَّاد وعَظُم وجمَعَ العساكرَ والأموال. وفي سنة 405ه أظهر حمَّادٌ الخلافَ على ابنِ أخيه باديس وخلَعَه واقتتلا في أوَّلِ جمُادى سنة 406ه، فانهزم حَمَّادٌ هزيمةً شَنيعةً بعد قتالٍ شديدٍ بين الفريقين والتجأ إلى قلعة مغلية، ثمَّ نَهَب دكمة ونقَلَ منها الزَّادَ إلى مغيلة وتحصَّنَ بها وباديس بقُربِه مُحاصِرٌ له إلى أن توفِّيَ باديس فجأةً في ذي القعدة سنة 406. وتولَّى المُعِزُّ بن باديس، واستمَرَّ حمَّادٌ على الخُلفِ معه حتى اقتتلا في سنة 408 عند نيني، موضعٍ، فانهزم حمَّادٌ فلم يعُدْ إلى قتالٍ بعدها، واصطلح مع المعِزِّ على أن يقتَصِرَ حمَّادٌ على ما بيده، وهو عَمَلُ ابنِ عليٍّ وما وراءَه مِن أشير وتاهرت، واستقَرَّ للقائد ابنِ حَمَّاد المسيلة، وطبنة، ومرسى الدجاج، وزواوة، ومقرة، ودكمة وغيرها، وبقي حمَّادٌ وابنُه كذلك حتى مات حمَّاد منتصف سنة 419. واستقَرَّ في المُلكِ بعده ابنُه القائد حتى توفِّي سنة 446. فمَلَك بعده ابنُه محسن بن القائد فأساء وخبطَ وقَتَل في أعمامِه، فقاتله ابنُ عَمِّه بلكين ومَلَك مَوضِعَه في ربيع الأول سنة 447 وبقِيَ حتى غدر ببلكينَ النَّاصِرُ بنُ علناس بن حمَّاد وأخذ منه المُلكَ في رجب سنة 454. واستقَرَّ النَّاصِرُ بن علناس حتى توفِّي سنة 481. ومَلَك بعده ابنُه المنصور بن الناصر إلى أن توفِّي سنة 498. وملَكَ بعده ابنُه باديس بن المنصور يسيرًا وتوفِّيَ."},{"id":1392,"title":"الحاكم العبيدي الفاطمي يغير أربعة وزراء في عام واحد ويقتل ثلاثة منهم .","date":["العام الهجري :405","العام الميلادي :1014"],"text":"رَكِبَ الحاكِمُ ومعه وزيرُه الحُسَينُ بنُ طاهر الوزَّان، على رَسمِه، فلمَّا انتهى إلى حارةِ كتامة خارِجَ بابِ القاهرة، أمَرَ بقَتلِه فضُرِبَت رقَبَتُه ودُفِنَ مكانَه. فكانت مُدَّةُ نظره في الوزارة سنتين وشهرين وعشرين يومًا، ثمَّ استوزَرَ مكانَه عبدَ الرَّحمنِ بنَ أبي السيد الذي لم يلبَثْ إلَّا قليلًا حتى قتَلَه الحاكِمُ فاستوزر مكانَه أبا العبَّاسِ الفَضلَ بنَ جَعفرِ بنِ الفراتِ، ثمَّ قَتَلَه الحاكِمُ أيضًا، واستوزر مكانَه أبا الحَسَنِ عليَّ بن جعفرِ بنِ فلاح الكتامي."},{"id":1393,"title":"قيام حرب بين علي بن مزيد الأسدي وبين بني دبيس .","date":["العام الهجري :405","الشهر القمري : محرم","العام الميلادي :1014"],"text":"كان بنو دبيس قد قَتَلوا أبا الغنائِمِ بنَ مزيدٍ أخا أبي الحَسَنِ في حربٍ بينهم وحالت الأيَّامُ بينه وبين الأخذِ بثَأرِه، ثم تجهَّزَ لِقَصدِهم بعد ذلك، وجمَعَ العَرَبَ، والشَّاذنجان، والجوانيَّة، وغيرَهما من الأكرادِ، وسار إليهم، فلمَّا قَرُبَ منهم خرَجَت زوجتُه ابنةُ دبيس وقَصدت أخاها مُضَرَ بنَ دبيس ليلًا، وقالت له: قد أتاكم ابنُ مزيد فيما لا قِبَلَ لكم به، وهو يَقنَعُ منكم بإبعادِ نبهان قاتِلِ أخيه، فأبعدوه، فأجابها أخوها مُضَرُ إلى ذلك، وامتَنَع أخوه حَسَّان. فلما سمِعَ ابنُ مزيد بما فعَلَتْه زوجتُه أنكره، وأراد طلاقَها، فقالت له: خِفتُ أن أكونَ في هذه الحَربِ بين فَقدِ أخٍ حَميمٍ، أو زوجٍ كَريمٍ، ففعَلْتُ ما فعلتُ رَجاءَ الصَّلاحِ، فزال ما عنده منها، وتقَدَّم إليهم، وتقَدَّموا إليه بالحُلَلِ والبيوت، فالتَقَوا واقتتلوا، واشتَدَّ القِتالُ بين الفريقين، فظَفِرَ ابنُ مزيد بهم، وهزَمَهم وقَتَلَ حَسَّان ونبهان ابني دبيس، واستولى على البيوتِ والأموال، ولَحِقَ مَن سَلِمَ مِنَ الهزيمة بالحويزة, ولَمَّا ظَفِرَ بهم رأى عندهم مكاتباتِ فَخرِ الملك يأمُرُهم بالجِدِّ في أمرِ ابن مزيد، ويَعِدُهم النُّصرة، فعاتبه على ذلك، وحصل بينهما نُفرةٌ، ودَعَت فخْرَ الملك الضَّرورةُ إلى تقليدِ ابنِ مزيد الجزيرةَ الدبيسيَّةَ، واستثنى مواضِعَ منها: الطيب وقرقوب وغيرهما، وبقي أبو الحسَنِ هناك إلى جُمادى الأولى, ثمَّ إنَّ مُضَرَ بنَ دبيسٍ جمع جمعًا، وكبس أبا الحَسَنِ ليلًا، فهرب في نفرٍ يسيرٍ، واستولى مُضَرُ على حُلَلِه وأمواله، وكلِّ ماله، ولَحِقَ أبو الحسن ببلدِ النيلِ مُنهَزِمًا."},{"id":1394,"title":"وفاة الحاكم النيسابوري صاحب المستدرك .","date":["العام الهجري :405","الشهر القمري : صفر","العام الميلادي :1014"],"text":"هو الإمامُ الحافِظُ، الناقِدُ العَلَّامة، شيخُ المُحَدِّثين، أبو عبدِ اللهِ مُحمَّدُ بنُ عبدِ الله بن محمَّد بن حمدويه بنِ نعيم بن الحكم، بن البيع الحاكم الضَّبِّي الطهماني النيسابوري، ويُعرَفُ بابن البيع، مِن أهل نيسابور. ولِدَ في يوم الاثنين, ثالثَ شهر ربيع الأول، سنة 321ه بنيسابور. قال الذهبي: \"طلب الحديثَ في صِغَرِه بعنايةِ والِدِه وخالِه، وأوَّلُ سَماِعِه كان في سنةِ ثلاثين، في التاسعة مِن عُمُرِه، وقد استملى على أبي حاتمِ بنِ حِبَّان في سنة 334ه وهو ابنُ ثلاث عشرة سنة. ولحِقَ الأسانيدَ العاليةَ بخُراسان والعراق وما وراء النَّهر، وسَمِعَ مِن نحو ألفَي شَيخٍ، ينقُصونَ أو يزيدون، فإنَّه سَمِعَ بنيسابورَ وَحدَها مِن ألفِ نَفسٍ، وارتحَلَ إلى العراقِ وهو ابنُ عشرينَ سنة\"، فكان من أهلِ العِلمِ والحِفظِ والحَديثِ، سَمِعَ الكثيرَ وطاف الآفاقَ، وصَنَّفَ الكُتُبَ الكِبارَ والصِّغارَ، أشهَرُها المُستَدرَكُ على الصَّحيحَينِ، وعلومُ الحديثِ، والإكليلُ، وتاريخُ نَيسابور، وقد روى عن خَلقٍ، ومن مشايخِه الدَّارَقُطنيُّ وابنُ أبي الفوارس وغيرهما، وقد كان مِن أهلِ الدِّينِ والأمانةِ والصِّيانةِ، والضَّبطِ والتَّجَرُّدِ والوَرَع، حدَّثَ عنه الدَّارَقُطنيُّ وأبو الفتحِ بنُ أبي الفوارسِ وهما من شيوخِه، قال الذهبيُّ عن الحاكم: \"صَنَّف وخَرَّج، وجرَحَ وعَدَّل، وصَحَّحَ وعَلَّل، وكان مِن بحورِ العِلمِ على تَشَيُّعٍ قليلٍ فيه\". وأكَّدَ الذهبيُّ أنَّ الحاكِمَ شِيعيٌّ وليس رافضيًّا، فقال: \"أمَّا انحرافُه عن خصومِ عليٍّ فظاهِرٌ، وأمَّا أمرُ الشَّيخَينِ فمُعظِّمٌ لهما بكلِّ حالٍ, فهو شِيعيٌّ لا رافِضيٌّ\" وقال: \"هو شيعيٌّ مشهورٌ بذلك, من غيرِ تعرُّضٍ للشَّيخَينِ\"  قال ابنُ خَلِّكان: \"تقَلَّدَ الحاكِمُ القضاءَ بنَيسابور في سنة 359ه في أيام الدَّولةِ السَّامانيَّة ووزراءِ أبي النَّصرِ مُحمَّدِ بن عبد الجبار العتيبي، وقُلِّدَ بعد ذلك قضاءَ جُرجان فامتنع، وكانوا يُنفِذونَه في الرَّسائِلِ إلى مُلوكِ بني بُوَيه, ثم قال: إنَّما عُرِفَ بالحاكِمِ لتقَلُّدِه القضاء \". دخل الحاكِمُ الحَمَّام، فاغتَسَل، وخرج. وقال: آه. وقُبِضَت روحُه وهو مُتَّزِرٌ لم يلبَسْ قَميصَه بعدُ، ودُفِنَ بعد عصرِ يوم الأربعاء، وصلَّى عليه القاضي أبو بكرٍ الحيري. توفِّي عن أربعٍ وثمانين سنةً."},{"id":1395,"title":"محمود بن سبكتكين يغزو الهند .","date":["العام الهجري :406","العام الميلادي :1015"],"text":"غزا محمودُ بنُ سبكتكين الهندَ على عادتِه، فَضَلَّ أدلَّاؤُه الطريقَ، ووقع هو وعسكَرُه في مياهٍ فاضَت من البَحرِ، فغَرِقَ كثيرٌ ممَّن معه، وخاض الماءَ بنَفسِه أيامًا حتى تخلَّصَ وعاد إلى خُراسان."},{"id":1396,"title":"وباء وكوارث بالعراق ومصر  .","date":["العام الهجري :406","العام الميلادي :1015"],"text":"أصاب البصرةَ بالعِراقِ وَباءٌ عَظيمٌ وطاعونٌ أعجَزَ الحفَّارينَ عن الدَّفنِ، وفيها زاد ماءُ النيلِ بمِصرَ وأغرق الضِّياعَ، وغَلَت الأسعارُ، وهَلَكت البساتينُ، وامتلأ كُلُّ مكانٍ مِن المدينة، وغَرِقَ المقياسُ وانتهت الزِّيادةُ إلى ثلاثِ أصابعَ من إحدى وعشرين ذراعًا، وبلغ الماءُ إلى نصفِ النَّخلِ مِمَّا يلي بركةَ الحَبش."},{"id":1397,"title":"فتنةٌ ببغدادَ بينَ أهل الكَرخِ وبين أهلِ بابِ الشَّعير .","date":["العام الهجري :406","العام الميلادي :1015"],"text":"وقَعَت فتنةٌ ببغدادَ بينَ أهل الكَرخِ وبين أهلِ بابِ الشَّعير، فأنكَرَ فَخرُ الملك على أهلِ الكرخ، ومنَعَهم من النَّوحِ يوم عاشوراء، ومِن تعليقِ المُسوحِ؛ مخافةَ زيادةِ الِفتنةِ."},{"id":1398,"title":"وفاة الشريف الرضي .","date":["العام الهجري :406","الشهر القمري : محرم","العام الميلادي :1015"],"text":"هو نقيبُ العَلَويِّينَ، أبو الحسَنِ محمَّدُ بنُ الحُسَينِ بنِ موسى بنِ مُحمَّد بنِ إبراهيم بن موسى الكاظمِ الحُسيني المُوسَوي البغدادي الشِّيعي، الشاعِرُ المُفلِق، الذي يقالُ: إنَّه أشعَرُ قُرَيشٍ، قال ابنُ خَلِّكانَ: \"هو أشعَرُ الطالبيِّينَ مَن مضى منهم ومَن غَبَر، على كثرةِ شُعَرائِهم المُفلِقينَ، ولو قُلتُ: إنَّه أشعَرُ قُرَيشٍ لم أُبعِدْ عن الصِّدقِ\". وُلِدَ ببغداد سنة 359ه، وتعلَّمَ فيها وبرَعَ في اللُّغةِ والأدَبِ والفِقهِ، وابتدأ بنَظمِ الشِّعرِ وله عشرُ سنين، وكان مُفرِطَ الذَّكاءِ، ولَّاه بهاءُ الدَّولة البُويهيُّ نقابةَ الطَّالبيِّينَ وسَمَّاه الشَّريفَ الرَّضيَّ، كان أبوه يتولَّى نقابةَ نُقَباءِ الطَّالبيِّينَ، ويحكُمُ فيهم أجمعين، والنَّظَر في المظالم، ثمَّ رُدَّت هذه الأعمالُ كُلُّها إلى ولَدِه الرَّضِيِّ في سنة 388 وأبوه حيٌّ. له أشعارٌ وتصانيفُ، منها: معاني القرآن، ومجاز القرآن، وهو الذي وضَعَ كتابَ نَهجِ البَلاغةِ الذي فيه الخُطَبُ التي تُنسَبُ لعليِّ بن أبي طالبٍ رَضيَ الله عنه، له ديوانٌ في أربَعِ مُجَلَّدات, توفِّيَ ببغداد عن 47 عامًا في الخامِسِ مِن مُحَرَّم، وكانت جنازتُه مشهودةً، ودُفِنَ بداره بمسجِدِ الأنباريِّ."},{"id":1399,"title":"وفاة باديس الصنهاجي وولاية ابنه المعز .","date":["العام الهجري :406","الشهر القمري : ذي القعدة","العام الميلادي :1016"],"text":"هو أبو مناد باديسُ بنُ مَنصورِ بنِ يُوسُفَ بلكين بن زيري بنِ مناد الحِمْيريُّ الصنهاجيُّ أمير إفريقيَّة نيابةً عن الحاكِمِ العُبيديِّ المُدَّعي الخلافةَ بمِصرَ، ولَقَّبَه الحاكِمُ نصيرَ الدَّولةِ، وُلِدَ بآشير سنة 374, وكانت ولايتُه بعد أبيه المنصور، سنة386، وكان باديس مَلِكًا كبيرًا، حازمَ الرأي، شديدَ البأس، إذا هَزَّ رُمحًا كَسَرَه. ‏ ووَلِيَ بعده إمرةَ إفريقيَّةَ ابنُه المعِزُّ بنُ باديس وعُمُره ثماني سنين، ووصلت إليه الخِلَعُ والتَّقليدُ مِن الحاكِمِ العَلَويِّ، ولَقَّبَه شَرَفَ الدَّولة. والمُعِزُّ بن باديس هذا هو الذي حمَلَ أهلَ المَغرِبِ على مَذهَبِ الإمامِ مالكٍ، وكانوا قبله على مَذهَبِ أبي حنيفةَ‏, وقضى على الشِّيعةِ أتْباعِ العُبَيديِّينَ في إفْريقيَّةَ.‏"},{"id":1400,"title":"تفرق المسلمين في الأندلس وظهور دول ملوك الطوائف .","date":["العام الهجري :407","العام الميلادي :1016"],"text":"اقتَسَم أصحابُ الأطرافِ والرُّؤَساءُ حُكمَ بلادِ الأندلُسِ، وصاروا طوائِفَ مُتناحِرةً، فقُرطبةُ استولى عليها أبو الحَسَنِ بنُ جهور، وكان مِن وزراء الدَّولة العامريَّة، وبقِيَ كذلك إلى أن مات سنةَ خمسٍ وثلاثين وأربعِمِئَة، وقام بأمِرِ قُرطبةَ بَعدَه ابنُه أبو الوليد مُحمَّدُ بنُ جهور، وأمَّا إشبيليَّةُ فاستولى عليها قاضيها أبو القاسمِ مُحمَّدُ بنُ إسماعيلَ بنِ عَبَّاد اللخمي. لَمَّا انقَسَمَت مملكةُ الأندلُسِ، شاع أنَّ المؤيَّدَ هشامَ بنَ الحَكَمِ الذي اختفى خبَرُه قد ظهر وسار إلى قلعةِ رباح، وأطاعه أهلُها، فاستدعاه ابنُ عَبَّاد إلى إشبيليَّة، فسار إليه وقام بنَصرِه، وأمَّا بطليوس فقام بها سابورُ الفتى العامريُّ، وتلقَّبَ سابور بالمنصورِ، ثم انتَقَلت من بعدِه إلى أبي بكر مُحمَّدِ بنِ عبدِ اللهِ بنِ مَسلَمةَ، المعروفِ بابنِ الأفطس، وتلَقَّبَ بالمظَفَّر، وأصلُ ابنِ الأفطَسِ مِن بربر مِكناسة، وأمَّا طُلَيطِلةُ فقام بأمْرِها ابنُ يعيشَ، ثمَّ صارت إلى إسماعيلَ بنِ عبدِ الرَّحمنِ بنِ عامر بنِ ذي النون، وتلَقَّب بالظَّافِرِ بحَولِ الله، وأصلُه من البربَرِ، ثمَّ ملَكَ بعدَه ولَدُه يحيى بنُ إسماعيلَ، ثُمَّ أخَذَت الفِرنجُ منه طُلَيطِلةَ في سنة 477، وصار هو ببلنسيَّة، وأقام هو بها إلى أن قتَلَه القاضي ابنُ جحاف الأحنف. وأمَّا سَرقَسطة والثَّغرُ الأعلى، فصارت في يدِ مُنذِرِ بنِ يحيى، ثمَّ صارت سَرقَسطة وما معها بعدَه لوَلَدِه يحيى بنِ مُنذِر بن يحيى، ثم صارت لسُليمانَ بنِ أحمَدَ بنِ مُحمَّد بن هود الجذاميِّ، وتلقَّبَ بالمُستعين بالله، وأمَّا طرطوشة فوَلِيَها لَبيبُ بنُ الفتى العامريِّ. وأمَّا بلنسيَّة فكان بها المنصورُ أبو الحَسَنِ عبدُ العزيز المغافري، ثم انضاف إليه المريةُ، ثمَّ مَلكَ بعدَه ابنُه مُحمَّدُ بنُ عبدِ العزيز، ثم غَدَرَ به صِهرُه المأمونُ بنُ ذي النُّون، وأخَذَ المُلكَ مِن محمَّدِ بنِ عبدِ العزيز في سنة 457. وأمَّا السَّهلةُ فمَلَكَها عَبُّود بنُ رزين، وأصلُه بربري. وأمَّا دانية والجزائرُ فكانت بيَدِ المُوفَّقِ بنِ أبي الحُسَينِ مُجاهِد العامريِّ. وأمَّا مرسيَّةُ فوَلِيَها بنو طاهرٍ، واستقامت لأبي عبدِ الرَّحمنِ منهم، إلى أن أخَذَها منه المُعتَمِدُ بنُ عباد. ثمَّ عصى بها نائبُها عليه، ثمَّ صارت للمُلَثَّمين. وأمَّا المرية فمَلَكَها خيران العامريُّ، ثم ملك المريةَ بعدَه زُهَيرٌ العامريُّ، واتسَعَ مُلكُه إلى شاطبة، ثمَّ قُتِلَ وصارت مملكَتُه إلى المنصورِ عبدِ العزيز بن عبد الرَّحمنِ المنصورِ بنِ أبي عامر، ثمَّ انتقَلَت حتى صارت للمُلَثَّمينَ, وأمَّا غِرناطةُ فمَلَكَها حبوسُ بنُ ماكس الصِّنهاجيُّ, وأمَّا مالقة فمَلَكَها بنو عليِّ بنِ حَمُّود العَلَويُّ، فلم تَزَلْ في مَملكةِ العَلَويِّينَ يُخطَبُ لهم فيها بالخِلافةِ، إلى أن أخَذَها منهم باديسُ بنُ حبوس صاحِبُ غرناطة. فهذه صورةُ تَفَرُّقِ ممالكِ الأندلُسِ، بعد ما كانت مُجتَمِعةً لخُلَفاءِ بني أمَيَّةَ."},{"id":1401,"title":"قتل الشيعة أتباع العبيديين بإفْريقيَّة أيام المعز بن باديس .","date":["العام الهجري :407","العام الميلادي :1016"],"text":"كان المعِزُّ بنُ باديس الصِّنهاجيُّ ناصِرًا للسُّنَّةِ وقامِعًا لبدعةِ الرَّفضِ الإسماعيليَّة العُبَيديَّة بإفْريقيَّةَ، وفي هذه السَّنَةِ قَتَل الرَّافِضةَ الإسماعيليَّةَ أتباعَ العُبَيديِّينَ في بلاد إفْريقيَّةَ، وبدايتُه أنَّ المُعِزَّ بنَ باديس رَكِبَ في عاشوراء ومشى في القيروانِ والنَّاسُ يُسَلِّمونَ عليه ويَدعُونَ له، فاجتاز بجَماعةٍ، فسأل عنهم، فقيل: هؤلاء رافِضةٌ يسُبُّونَ أبا بكرٍ وعُمَرَ، فقال: رَضِيَ اللهُ عن أبي بكرٍ وعُمَرَ، فانصرَفَت العامَّةُ مِن فَورِها إلى دَربِ المقلى من القيروانِ، وهو مكانٌ تجتَمِعُ به الشِّيعةُ، فقَتَلوا منهم، فقُتِلَ منهم خلقٌ كثيرٌ، وأُحرِقوا بالنَّارِ، ونُهِبَت ديارُهم، وقُتِلوا في جميعِ إفريقيَّةَ، واجتمَعَ جماعةٌ منهم إلى قصر المنصورِ قَريب القيروان، فتحَصَّنوا به، فحصَرَهم العامَّةُ وضَيَّقوا عليهم، فاشتَدَّ عليهم الجوعُ، فأقبلوا يَخرُجونَ والنَّاسُ يَقتُلونَهم حتى قُتِلوا عن آخِرِهم، ولجأ مَن كان منهم بالمهديَّةِ إلى الجامِعِ فقُتِلوا كُلُّهم، وكانت الشِّيعةُ تُسمَّى بالمغرب المشارِقةَ، نسبة إلى أبي عبدِ اللهِ الشِّيعيِّ، وكان مِن المَشرِقِ."},{"id":1402,"title":"احتراق جامع سامرا واجتماع عدة أمور مثلها في هذا العام .","date":["العام الهجري :407","العام الميلادي :1016"],"text":"احتَرَق مسجِدُ سامِرَّا المشهورُ بمِئذنتِه المُلتَوية، كما احتَرَق مَشهَدُ الحُسَينِ بنِ علي بكَربَلاءَ وأروقتُه، وكان سبَبُ ذلك أنَّ القومةَ أشعلوا شمعتينِ كَبيرتينِ، فمالتا في اللَّيلِ على التأزيرِ- الخشَبِ المُحيطِ بالشَّمعَتَينِ- ونَفِذَت النَّارُ منه إلى غيرِه حتى كان ما كان، ثمَّ بعد ذلك احتَرَقَت دارُ القطن ببغدادَ وأماكِنُ كثيرةٌ بباب البصرة، وفيها ورَدَ الخبَرُ بتشعيثِ الُّركنِ اليَمانيِّ من المسجِدِ الحرامِ، وسُقوطِ جِدارٍ بينَ يَدَي قَبرِ الرَّسولِ صلَّى اللهُ عليه وسلَّم بالمدينةِ، وأنَّه سَقَطَت القُبَّةُ الكبيرةُ على صَخرةِ بَيتِ المَقدِس، وهذا مِن أغرَبِ الاتِّفاقاتِ وأعجَبِها. العِبَر في خبَرِ مَن غَبَر (2/ 214)"},{"id":1403,"title":"فتح يمين الدَّولة الغزنوي كشمير ودخول أهلها في الإسلام  .","date":["العام الهجري :407","العام الميلادي :1016"],"text":"غزا يَمينُ الدَّولةِ بلادَ الهندِ، بعد فراغِه مِن خوارزم، فسار منها إلى غزنةَ، ومنها إلى الهندِ عازمًا على غَزوِ قَشمير (كشمير)؛ إذ كان قد استولى على بلادِ الهِندِ ما بينَه وبين قشمير، فلما بلغ دَربَ قَشميرَ أتاه صاحِبُها وأسلَمَ على يَدِه، وسار بينَ يديه إلى مَقصِدِه، فبلغ ماءَ جون في العشرينَ مِن رَجَب، وفتَحَ ما حولَها مِن الوِلاياتِ الفَسيحةِ والحُصونِ المَنيعةِ، حتى بلغ حِصنَ هودب، وهو آخِرُ مُلوكِ الهِندِ، فنظَرَ هودب من أعلى حِصنِه، فرأى مِن العساكِرِ ما هالَه ورَعَبه، وعَلِمَ أنَّه لا يُنجيه إلَّا الإسلامُ، فخرج في نحوِ عَشرةِ آلافٍ يُنادُونَ بكَلمةِ الإخلاصِ، فقَبِلَه يَمينُ الدَّولة، وسار عنه إلى قلعةِ كلجند، وهو من أعيانِ الهِندِ وشياطينِهم، وكان على طريقِه غِياضٌ مُلتَفَّة لا يَقدِرُ السَّالِكُ على قَطعِها إلَّا بمشَقَّة، فسَيَّرَ كلجند عساكِرَه وفُيولَه إلى أطرافِ تلك الغياضِ يَمنَعونَ مِن سُلوكِها، فتَرَك يمينُ الدَّولة عليهم من يقاتِلُهم، وسلك طريقًا مُختَصَرةً إلى الحِصنِ، فلم يشعُروا به إلَّا وهو معهم، فقاتَلَهم قتالًا شديدًا، فلم يُطيقوا الصَّبرَ على حَدِّ السُّيوفِ، فانهزموا، وغَنِمَ المُسلِمونَ أموالَه، ومَلَكوا حُصونَه، ثمَّ سار نحوَ بَيتِ مُتعَبَّدٍ لهم، وهو مهرة الهند، وهو مِن أحصَنِ الأبنيةِ على نَهرٍ، ولهم به من الأصنامِ كَثيرٌ، منها خمسةُ أصنامٍ مِن الذهَبِ الأحمَرِ المُرَصَّع بالجواهِرِ، وكان به من الأصنامِ المصوغةِ مِن النقرةِ نحو مِئَتي صنَمٍ، فأخذ يمينُ الدَّولة ذلك جميعَه، وأحرق الباقيَ، وسار نحو قنوج، وصاحِبُها راجيال، فوصل إليها في شَعبان، فرأى صاحِبَها قد فارَقَها، فأخَذَها يمينُ الدَّولة، وأخَذَ قلاعَها وأعمالَها، ثمَّ سار إلى قلعةِ البراهمة، فقاتَلوه وثَبَتوا، فلمَّا عَضَّهم السِّلاحُ عَلِموا أنَّهم لا طاقةَ لهم، فاستسلَموا للسَّيفِ فقُتِلوا، ولم ينجُ منهم إلا الشَّريدُ، ثمَّ سار نحو قلعةِ آسي، وصاحِبُها جند بال، فلمَّا قارَبَها هَرَب جند بال، وأخذ يمينُ الدَّولة حِصْنَه وما فيه، ثم سارَ إلى قلعة شروة، وصاحِبُها جندرآي، فلَمَّا قارَبَه نَقَلَ مالَه وفُيولَه نحو جبالٍ هناك منيعةٍ يحتمي بها، وعَمِيَ خَبَرُه فلم يُدْرَ أين هو، فنازَلَ يَمينُ الدَّولة حِصنَه فافتَتَحه وغَنِمَ ما فيه، وسار في طلَبِ جندرآي جريدةٌ -الجريدةُ: خَيْلٌ لا رَجَّالةَ فيها- وقد بلَغَه خبَرُه، فلَحِقَ به في آخِرِ شَعبانَ، فقاتَلَه، فقَتَل أكثَرَ جُندِ جندرآي، وأَسَرَ كثيرًا منهم، وغَنِمَ ما معه من مالٍ وفيلٍ، وهَرَب جندرآي في نفرٍ مِن أصحابِه فنجا، ثمَّ عاد إلى غزنة ظافرًا، ولَمَّا عاد من هذه الغزوةِ أمَرَ ببناءِ جامِعِ غزنة، فبُنِيَ بناء لم يُسمَعْ بمِثلِه، ووُسِّعَ فيه، وكان جامِعُها القديمُ صغيرًا، وأنفَقَ ما غَنِمَه في هذه الغزاةِ في بنائِه."},{"id":1404,"title":"محمود بن سبكتكين يسيطر على خوارزم .","date":["العام الهجري :407","العام الميلادي :1016"],"text":"قام أُمراءُ خوارزمَ بقَتلِ حاكِمِهم أبي العَبَّاسِ خوارزمشاه لَمَّا رأَوْا مِن مُوافَقَتِه ليَمينِ الدَّولةِ ودُعائِه له على المنابِرِ، فقَتَلوه غِيلةً وأجلَسوا مكانَه أحدَ أولادِه، وتعاهَدوا على مُقاتَلةِ يَمينِ الدَّولة ومُقارَعتِه، واتَّصَل الخبَرُ بيمينِ الدَّولة، فجمَعَ العساكِرَ وسار نحوَهم، فلمَّا قارَبَهم جَمَعَهم صاحِبُ جَيشِهم، ويُعرَفُ بالبتكين البخاري، وأمَرَهم بالخُروجِ إلى لِقاءِ مُقَدِّمةِ يَمينِ الدَّولةِ والإيقاعِ بمن فيها من الأجنادِ، فساروا معه وقاتَلوا مُقَدِّمةَ يَمينِ الدَّولة، واشتَدَّ القِتالُ بينهم، واتَّصَل الخبَرُ بيَمينِ الدَّولة، فتقَدَّمَ نَحوَهم في سائِرِ جُيوشِه، فلَحِقَهم وهم في الحَربِ، فثَبَت الخوارزميَّةُ إلى أن انتَصَف النَّهارُ، وأحسَنوا القِتالَ، ثمَّ إنَّهم انهزموا، ورَكِبَهم أصحابُ يمينِ الدَّولةِ يَقتُلونَ ويأسِرونَ، ولم يَسلَمْ إلَّا القليلُ، ثمَّ إنَّ البتكين رَكِبَ سفينةً لينجوَ فيها، فجرى بينه وبين مَن معه مُنافَرةٌ، فقاموا عليه وأوثقوه، ورَدُّوا السَّفينةَ إلى ناحيةِ يَمينِ الدَّولة، وسَلَّموه إليه، فأخَذَه وسائِرَ القُوَّادِ المأسورينَ معه، وصَلَبَهم عند قبرِ أبي العبَّاسِ خوارزمشاه، وأخذَ الباقينَ مِن الأسرى فسَيَّرَهم إلى غزنةَ فوجًا بعد فوجٍ، فلمَّا اجتَمَعوا بها أفرَجَ عنهم، وأجرى لهم الأرزاقَ، وسَيَّرَهم إلى أطرافِ بلادِه مِن أرضِ الهِندِ يَحمُونَها مِن الأعداءِ، ويَحفَظونَها من أهلِ الفَسادِ، وأخذ خوارزمَ واستنابَ بها حاجِبَه التونتاش."},{"id":1405,"title":"فِتنةٌ كَبيرةٌ بينَ السُّنَّةِ والشِّيعةِ بمدينة واسِط .","date":["العام الهجري :407","العام الميلادي :1016"],"text":"كانت فِتنةٌ كَبيرةٌ بينَ السُّنَّةِ والشِّيعةِ بواسِط، فانتصَرَ السُّنَّةُ وهَرَبَ وُجوهُ الشِّيعةِ والعَلَويِّينَ إلى عليِّ بنِ مزيد أميرِ جَزيرةِ الأسديَّةِ مِن قِبَلِ فخر الدَّولةِ البُويهيِّ، فاستَنصَروه."},{"id":1406,"title":"ابتداء الدَّولة الحمودية (العلويين) بالأندلس .","date":["العام الهجري :407","الشهر القمري : محرم","العام الميلادي :1016"],"text":"وَلِيَ الأندلُسَ عليُّ بنُ حَمُّود بنِ أبي العَيشِ بنِ ميمون بنِ أحمَدَ بنِ عليِّ بنِ عبد اللهِ بنِ عُمَرَ بنِ إدريس بن إدريسَ بن عبد الله بن الحسن بن الحسن بن علي بن أبي طالب، وقيل في نَسَبِه غيرُ ذلك، مع اتِّفاقٍ على صِحَّةِ نَسَبِه إلى أميرِ المؤمنينَ عليِّ بنِ أبي طالبٍ رَضِيَ الله عنه، وكان سَبَبُ تَوَلِّيه أنَّ الفتى خيرانَ العامريَّ لم يكُنْ راضيًا بولايةِ سُلَيمانَ بنِ الحاكِمِ الأُمويِّ؛ لأنَّه كان من أصحابِ المؤيَّدِ، فلمَّا مَلَك سُلَيمانُ قُرطُبةَ انهزم خيرانُ في جماعةٍ كثيرةٍ مِن الفتيان العامريِّينَ، ثمَّ هَرَب وقَوِيَ أمرُه، وكان عليُّ بنُ حمود بمدينةِ سبتة، وكان أخوه القاسمُ بنُ حمود بالجزيرةِ الخَضراءِ مُستَوليًا عليها، فحَدَثَ لعليِّ بنِ حمود طَمَعٌ في مُلكِ الأندلُسِ لِمَا رأى من الاختلافِ، وكان خيرانُ يُكاتِبُ النَّاسَ، ويأمُرُهم بالخُروجِ على سُلَيمانَ، فوافَقَه جَماعةٌ منهم عامِرُ بنُ فتوح وزيرُ المؤَيَّد، وهو بمالقةَ، وكاتَبوا عليَّ بنَ حَمُّود، وهو بسبتة؛ لِيَعبُرَ إليهم ليقوموا معه ويَسيروا إلى قُرطبة، فعَبَرَ إلى مالقة في سنة 405، ثم تجَهَّزوا وجَمَعوا مَن وافقهم، وساروا إلى قُرطبةَ وبايعوا عليًّا على طاعةِ المُؤَيَّد الأمويِّ، فلمَّا بلغوا غرناطةَ وافَقَهم أميرُها، وسار معهم إلى قُرطبة، فخرج سُلَيمانُ والبربَرُ إليهم، فالتَقَوا واقتتلوا، فانهزم سُلَيمانُ والبربَرُ، وقُتِلَ منهم خَلقٌ كثيرٌ، وأُخِذَ سُليمانَ أسيرًا، فحُمِلَ إلى عليِّ بنِ حمُّود ومعه أخوه وأبوه الحاكِمُ بنُ سُلَيمانَ بنِ عبدِ الرَّحمنِ الناصر، ودخَلَ عليُّ بنُ حمود قُرطُبةَ في المحَرَّم سنة 407 ودخل خيرانُ وغَيرُه إلى القَصرِ؛ طمعًا في أن يجدوا المؤيَّدَ حَيًّا، فلم يَجدِوه، فأَخَذَ عليُّ بنُ حَمُّود سليمانَ وقَتَلَه سابعَ المحَرَّم، وقتَلَ أباه وأخاه، واستولى عليُّ بنُ حمود على قُرطُبة، ودعا النَّاسَ إلى بيعتِه، فبُويِعَ، واجتَمَعَ له المُلْكُ، ولُقِّبَ المتوكِّلَ على الله."},{"id":1407,"title":"وفاة الوزير فخر الملك .","date":["العام الهجري :407","الشهر القمري : ربيع الأول","العام الميلادي :1016"],"text":"هو الوَزيرُ الكَبيرُ، أبو غالبٍ مُحمَّدُ بنُ عليِّ بنِ خَلَفِ بنِ الصيرفيِّ الشِّيعيِّ، المُلَقَّبُ فَخر الملك، وزيرُ بهاءِ الدَّولة أبي نصرِ بنِ عضُدِ الدَّولة بن بُوَيه، وبعد وفاتِه وَزَرَ لِوَلَدِه سُلطانِ الدَّولةِ أبي شُجاعٍ فناخِسرو. أصلُه مِن واسِط، وكان أبوه صيرفيًّا، وباسمِه صَنَّفَ كتاب \"الفخري\" في الجبرِ والمُقابلة. كان صدرًا مُعظَّمًا، جوادًا مُمَدَّحًا، مِن رجالِ الدَّهرِ، وكان مِن صِباه يتعانى المكارِمَ والأفضالَ، ويلَقِّبونَه بالوزيرِ الصَّغيرِ، وكان من أعظَمِ وُزراءِ آلِ بُوَيه على الإطلاقِ بعدَ أبي الفَضلِ مُحَمَّدِ بنِ العَميد والصَّاحِبِ بنِ عَبَّاد، وكان واسِعَ النِّعمةِ، فسيحَ مجالِ الهمَّة، جَمَّ الفضائِلِ، جَزيلَ العَطايا والنَّوال، وكان شَهمًا كافيًا، خبيرًا بالتصَرُّفِ، سديدَ التَّوقيعِ، طَلْقَ المُحَيَّا، يكاتِبُ مُلوكَ النواحي، ويهاديهم، وفيه عَدلٌ في الجُملةِ، عَمَرَت العراقُ في أيَّامِه، أنشأ بيَمارستانًا، ودارًا عَظيميَنِ ببَغداد, وكان من أثَرِ تَشَيُّعِه أنَّه أعاد اللَّطمَ يومَ عاشوراءَ، فثارت الفِتَنُ لذلك سنة406. كانت جوائِزُه متواترةً على العُلَماء والصُّلَحاء والشُّعَراء. وَلِيَ بعضَ الأعمال، وتنَقَّلَت به الأحوالُ إلى أن وَلِيَ ديوانَ واسط، ثم وزَرَ وناب للسُّلطانِ بهاءِ الدَّولة بفارِس، وافتتَحَ قِلاعًا، ثمَّ وَلِيَ العِراقَ بعد عميدِ الجيوش. لم يزَلْ فَخرُ الملك في عِزِّه وجاهِه وحُرمَتِه إلى أنْ نَقَم عليه سُلطانُ الدَّولة، فحَبَسَه ثمَّ قتلَه بسَفحِ جَبَلٍ قريبٍ مِن الأهواز لثلاثٍ بَقِينَ مِن شهرِ ربيع الأول سنة 407, وعاش ثلاثًا وخمسينَ سنةً."},{"id":1408,"title":"ذكر خروج الترك من الصين وموت طغان خان .","date":["العام الهجري :408","العام الميلادي :1017"],"text":"خرَجَ التُّركُ- وهم وثنيُّونَ- مِن الصِّينِ، وكان سبَبُ خُروجِهم أنَّ طغان خان مَلِكَ تُركستان التُّركي كان مُسلِمًا فاضِلًا يُحِبُّ أهلَ العِلمِ والدِّينِ. لَمَّا مَرِضَ مرضًا شديدًا، وطال به المَرَضُ، طَمِعوا في البلادِ لذلك، فساروا إليها ومَلَكوا بعضَها وغَنِموا وسَبَوا، وبَقِيَ بينهم وبين بلاساغون ثمانيةُ أيام، فلمَّا بلَغَه الخبَرُ كان بها مريضًا، فسألَ اللهَ تعالى أن يُعافِيَه لِينتَقِمَ مِن الكَفَرةِ، فاستجابَ اللهُ له وشفاه، فجمَعَ العساكِرَ، وكتب إلى سائِرِ بلادِ الإسلامِ يَستنفِرُ النَّاسَ، فاجتمع إليه من المتطَوِّعةِ مئةُ ألف وعِشرون ألفًا، فلمَّا بلغ التُّركَ خَبَرُ عافيتِه وجَمْعِه العساكِرَ وكَثرةُ مَن معه، عادوا إلى بلادِهم، فسار خَلْفَهم نحوَ ثلاثةِ أشهُرٍ حتى أدرَكَهم وهم آمنونَ لبُعدِ المسافةِ، فكبَسَهم وقَتَلَ منهم زيادةً على مِئَتي ألف رجلٍ، وأسَرَ نحوَ مئةِ ألف، وغَنِمَ مِن الدوابِّ وغير ذلك من الأواني الذهبيَّةِ والفضيَّة ومعمول الصينِ ما لا عهدَ لأحدٍ بمِثلِه، وعاد إلى بلاساغون، فلَمَّا بلَغَها عاوَدَه مَرَضُه فمات منه."},{"id":1409,"title":"الخليفة العباسي القادر بالله يستتيب فقهاء المعتزلة .","date":["العام الهجري :408","العام الميلادي :1017"],"text":"استتابَ القادِرُ باللهِ الخَليفةُ فُقَهاءَ المُعتَزِلةِ، فأظهروا الرُّجوعَ وتبَرَّؤوا من الاعتزالِ والرَّفضِ والمقالاتِ المُخالِفةِ للإسلام، وأُخِذَت خطوطُهم بذلك، وأنَّهم متى خالفوا أحلَّ فيهم مِن النَّكالِ والعُقوبةِ ما يَتَّعِظُ به أمثالُهم. قال ابن كثير: \"وامتَثَل محمودُ بنُ سبكتكين أمْرَ أميرِ المؤمنينَ في ذلك، واستَنَّ بسُنَّتِه في أعمالِه التي استخلَفَه عليها مِن بلادِ خُراسان وغيرها، في قَتلِ المُعتَزِلةِ والرَّافِضةِ، والإسماعيليَّةِ والقرامِطة، والجَهميَّة والمُشَبِّهة، وصَلَبَهم وحبَسَهم ونفاهم، وأمَرَ بلَعْنِهم على المنابِرِ، وأبعَدَ جَميعَ طوائِفِ أهلِ البِدَعِ، ونفاهم عن ديارِهم، وصار ذلك سُنَّةً في الإسلامِ\""},{"id":1410,"title":"ظهور المذهب الدرزي ودعوى ألوهية الحاكم .","date":["العام الهجري :408","العام الميلادي :1017"],"text":"قَدِمَ إلى مصرَ داعٍ عَجميٌّ اسمُه مُحَمَّدُ بنُ إسماعيلَ الدرزيُّ المعروفُ بأبي عبدِ اللهِ أنوشتكين النجري الدرزيِّ، وهو أوَّلُ رَجُلٍ تكَلَّمَ بدَعوى ألوهيَّةِ الحاكِمِ، وأمَرَ برَفعِ ما جاء به الشَّرعُ، وسيَّرَ مذهبَه إلى بلادِ الشَّامِ والسَّاحلِ، ولهم مذهَبٌ في كتمانِ السِّرِّ لا يُطلِعونَ عليه مَن ليس منهم, وكان الدرزيُّ يُبيحُ البَناتِ والأمَّهاتِ والأخواتِ, واتَّصَل بالحاكِمِ فأنعَمَ عليه، ودعا النَّاسَ إلى القَولِ بإلهيَّةِ الحاكِمِ، فأنكر النَّاسُ عليه ذلك، فقاموا عليه بمِصرَ فقَتَلوه، وَثَبَ به أحدُ الأتراكِ وهو في مَوكِبِ الحاكِمِ فقَتَلَه، وثارَت الفتنةُ، فنُهِبَت دارُه، وغُلِّقَت أبوابُ القاهرةِ، واستمَرَّت الفتنةُ ثلاثةَ أيَّامٍ، قُتِلَ فيها جماعةٌ مِن الدرزيَّة، وقُبِضَ على التركيِّ قاتِلِ الدرزيِّ وحُبِسَ ثمَّ قُتِل, وقُتِلَ معه سبعونَ رَجُلًا بالدرزيِّ، ثمَّ ظهَرَ داعٍ آخَرُ اسمُه حمزةُ بنُ أحمد، وتلَقَّب بالهادي، وأقام بمَسجدِ تبر خارِجَ القاهرة، ودعا إلى مقالةِ الدرزيِّ، وبثَّ دُعاتَه في أعمالِ مِصرَ والشَّامِ، وترخَّصَ في أعمالِ الشَّريعةِ، وأباح الأمَّهاتِ والبناتِ ونَحوَهنَّ، وأسقَطَ جميعَ التَّكاليفِ في الصَّلاةِ والصَّومِ ونحو ذلك، فاستجاب له خَلقٌ كَثيرٌ، فظهر مِن حينِئذٍ مَذهَبُ الدرزيَّةِ ببلادِ صِيدا وبيروت وساحِلِ الشام، وقيل: إنَّ حمزةَ هو الدرزيُّ، كان درازًا فنُسِبَ ذلك إليه مع أنَّ أصلَ الفِكرةِ مِن مُحمَّدِ بنِ إسماعيلَ، وقيل: قَدِمَ رَجُلٌ يقال له يحيى اللبَّاد، ويُعرَفُ بالزوزني الأخرم، فساعده على ذلك. ونَشِطَ اللبَّادُ وجَماعةٌ معه على الخروجِ عن الشَّريعةِ. فرَكِبَ يومًا من القاهرة في خمسينَ رجُلًا من أصحابِه إلى مصر، ودخل الجامِعَ بدابَّتِه، وأصحابُه كذلك، فسَلَّمَ إلى القاضي رُقعةً فيها باسمِ الحاكم الرحمن الرحيم، فأنكر القاضي ذلك، وثار النَّاسُ بهم وقَتَلوهم، وشاع هذا في النَّاسِ فلَعَنوه."},{"id":1411,"title":"قيام دولة عمران بن شاهين بالبطيحة في العراق ثم سقوطها .","date":["العام الهجري :408","الشهر القمري : جمادى الأولى","العام الميلادي :1017"],"text":"كان أوَّلَ مَن مَلَك البطيحةَ أو البطائح- تقَعُ بين واسِطَ والبصرةِ- عِمرانُ بنُ شاهينَ، أصلُه من الجامدة (من أعمالِ واسط) مجهولُ النَّسَبِ، سواديُّ المنشأِ، ينتَسِبُ إلى بني سُلَيم, كان عليه دِماءٌ فهَرَب إلى البطيحة, واحتمى بالآجامِ, يتصَيَّدُ السَّمَك والطَّيرَ, فرافقه صيَّادون, ثمَّ التَفَّ عليه لصوصٌ, ثمَّ استفحَلَ أمرُه, وكَثُرَ جَمعُه, فأنشأ معاقِلَ وتمَكَّنَ مِن البطيحة, فحارَبَه مُعِزُّ الدَّولة ثمَّ ابنُه عِزُّ الدَّولة غيرَ مَرَّة, ولم يظفروا به، وعجَزَ وُزَراءُ وقُوَّادُ بغداد عن إزالتِه عنها إلى أن مات على فراشِه سنة 369, وامتَدَّت دولتُه بعده أربعينَ سَنةً، حيث تعاقَبَ أولادُه بَعدَه على حُكمِ البطيحةِ، وفي هذه السَّنَةِ توُفِّيَ مُهَذَّب الدَّولة أبو الحَسَن عليُّ بنُ نصر آخِرُ حُكَّام دولة البطيحة، ثمَّ إنَّ ابنَ أخت مُهَذَّب الدَّولة، وهو أبو محمَّد عبدُ اللهِ بنُ يني، استدعى الديلمَ والأتراكَ، ورَغَّبَهم ووعَدَهم، واستحلَفَهم لنَفسِه، واتَّفَق معهم على تنحيةِ ولَدِ مُهَذَّب الدَّولة فقاموا بأخْذِه وحَبْسِه عند أبي محمَّدٍ، وولي الأمرَ أبو مُحمَّد، وتسَلَّمَ الأموالَ والبَلَد، وأمَرَ بضَربِ أبي الحُسَينِ بنِ مُهَذَّب الدَّولة، فضُرِبَ ضربًا شديدًا توفِّيَ منه بعدَ ثلاثةِ أيَّامٍ مِن موتِ أبيه، وبَقِيَ أبو محمَّد أميرًا إلى مُنتَصَف شعبان، وتوفِّيَ بالذبحة، فكان مُلكُه أقلَّ مِن ثلاثةِ أشهُرٍ، فلمَّا توفِّيَ اتَّفَق جماعةٌ على تأميرِ أبي عبدِ اللهِ الحُسَينِ بنِ بكرٍ الشرابي، وكان من خواصِّ مُهَذَّبِ الدَّولة، فصار أميرَ البطيحة، وبَذَل للمَلِكِ سُلطانِ الدَّولةِ بُذولًا، فأقَرَّه عليها, فآلت تلك البِلادُ بعد ذلك إلى سُلطانِ الدَّولةِ صاحِبِ بغداد."},{"id":1412,"title":"الخليفة العباسي القادر بالله يقرر كفر من قال بخلق القرآن .","date":["العام الهجري :409","العام الميلادي :1018"],"text":"أصدَرَ الخَليفةُ العباسيُّ القادِرُ باللهِ كِتابًا في مذهَبِ أهلِ السُّنَّةِ والجماعةِ في القُرآنِ الكريمِ، قُرِئَ بدارِ الخِلافةِ في الموكِبِ, وفيه: أنَّ مَن قال: القُرآنُ مَخلوقٌ، فهو كافِرٌ حلالُ الدَّمِ."},{"id":1413,"title":"غزو محمود بن سبكتكين بلاد الهند .","date":["العام الهجري :409","العام الميلادي :1018"],"text":"سار يمينُ الدَّولةِ إلى الهندِ غازيًا، واحتَشَد وجَمَع، واستَعَدَّ وأعَدَّ، وسبَبُ هذا أنَّ بيدا أكبَرَ مُلوكِ الهند قَوِيَ أمْرُه واستمال إليه كُلَّ مَن كان يمينُ الدَّولةِ قد هَزَمَهم ووعَدَهم بإعادةِ مُلكِهم لهم، فتجَهَّزَ يمينُ الدَّولة للغَزوِ، وقصَدَ بيدا، وابتدأ في طريقِه بالأفغانيَّةِ، وهم كُفَّارٌ، فغَنِمَ المُسلِمونَ مِن أموالِهم الكثيرُ، ثمَّ واصَلَ المَسيرَ، وبلَغَ إلى مكانٍ لم يَبلُغْه فيما تقَدَّمَ مِن غَزَواتِه، وعَبَرَ نَهرَ كنك، ولم يَعبُرْه قَبلَها، فأتاه في الطَّريقِ خَبَرُ مَلِكٍ مِن مُلوكِ الهِندِ يقال له تروجنبال قد سار مِن بينِ يديه مُلتَجِئًا إلى بيدا ليحتَمِيَ به عليه، فطوى المَراحِلَ، فلَحِقَ تروجنبال ومَن معه، رابِعَ عَشَرَ من شَعبان، فاقتتلوا وانهزم تروجنبال ومَن معه، وكَثُر فيه القَتلُ والأسْرُ، وأسلَموا أموالَهم وأهلِيهم، فغَنِمَها المسلمون، وانهزم مَلِكُهم جريحًا، وتحيَّرَ في أمْرِه، وأرسل إلى يمينِ الدَّولة يطلُبُ الأمانَ فلم يُؤَمِّنْه، ولم يقنَعْ منه إلَّا الإسلام، وقتَلَ مِن عساكِرِه ما لا يُحصى، وسار تروجنبال ليلحَقَ ببيدا، فانفَرَدَ به بعضُ الهنودِ فقَتَلَه. فلما رأى ملوكُ الهند ذلك تابعوا رسُلَهم إلى يمينِ الدَّولةِ يَبذُلونَ له الطاعةَ والإتاوةَ. وسار يمينُ الدَّولة بعد الوقعةِ إلى مدينة باري، وهي من أحصَنِ القِلاعِ والبِلادِ وأقواها، فرآها مِن سُكَّانِها خاليةً، وعلى عُروشِها خاويةً، فأمَرَ بهَدمِها وتخريبِها وعَشْر قِلاعٍ معها مُتَناهية الحَصانة، وقتَلَ مِن أهلِها خلقًا كثيرًا، وسار يطلُبُ بيدا المَلِك، فلَحِقَه وقد نزل إلى جانبِ نهرٍ، وأجرى الماءَ مِن بين يديه فصار وحْلًا، وتَرَك عن يمينِه وشماله طريقًا يَبسًا يقاتِلُ منه إذا أراد القِتالَ، وكان عِدَّةُ مَن معه ستَّةَ وخمسينَ ألف فارس، ومِئَةَ ألفٍ وأربعةً وثمانينَ ألفَ راجلٍ، وسبعَمئة وستةً وأربعين فيلًا، فأرسل يمينُ الدَّولة طائفةً من عَسكَرِه للقِتالِ، فأخرج إليهم بيدا مِثلَهم، ولم يزَلْ كُلُّ عَسكرٍ يَمُدُّ أصحابَه، حتى كثُرَ الجمعان، واشتَدَّ الضَّربُ والطعان، فأدرَكَهم اللَّيلُ وحجز بينهم، فلمَّا كان الغَدُ بكَّرَ يمينُ الدَّولة إليهم، فرأى الدِّيارَ منهم بلاقِعَ، ورَكِبَ كُلُّ فرقةٍ منهم طريقًا مخالِفًا لطريق الأخرى. ووجد خزائِنَ الأموالِ والسِّلاحِ بحالها، فغَنِموا الجميعَ، واقتفى آثارَ المُنهَزِمين، فلَحِقوهم في الغِياضِ والآجامِ، وأكثَروا فيهم القَتلَ والأسْرَ، ونجا بيدا فريدًا وحيدًا، وعاد يمينُ الدَّولة إلى غزنةَ مَنصورًا."},{"id":1414,"title":"مجاعة وغَلاء شديد بمِصرَ .","date":["العام الهجري :410","العام الميلادي :1019"],"text":"اشتَدَّ الغَلاءُ بديارِ مِصرَ حتى بِيعَ الدَّقيقُ رِطلًا بدِرهمٍ، واللَّحمُ أربعَ أواقٍ بدِرهَمٍ، ومات كثيرٌ مِن النَّاسِ بالجوعِ، وبلَغَت عِدَّةُ مَن مات في مُدَّةِ رَمَضانَ وشَوَّال وذي القَعدة، مِئَتي ألفٍ وسبعين ألفًا سوى الغُرَباءِ، وهم أكثَرُ مِن ذلك."},{"id":1415,"title":"وفاة ابن مردويه الكبير .","date":["العام الهجري :410","الشهر القمري : رمضان","العام الميلادي :1020"],"text":"هو الحافِظُ المُجَوِّدُ العلَّامة، مُحَدِّثُ أصبهان، أبو بكرٍ أحمَدُ بنُ موسى بن مَردَوَيهِ بنِ فَوْرَك بن موسى بن جعفر، الأصبهاني، المؤرِّخُ المُفَسِّرُ، مِن أهل أصبهان. مولِدُه سنة323. ويقالُ له ابنُ مَردَوَيهِ الكبير؛ لِيُمَيَّزَ عن حَفيدِه المحدِّثِ العالِمِ أبو بكرٍ أحمَدُ بنُ مُحمَّد بن أحمد بن مردويه. له عِدَّةُ تصانيفَ، منها: \"التفسير الكبير\"، و\"التاريخ\"، و\"الأمالي\" \"الثلاثمئة مجلس\"، و\"المسند\"، وكتاب \"المُستخرَج على صحيحِ البُخاري\"، بعُلُوٍّ في كثيرٍ مِن أحاديثِ الكِتابِ، حتى كأنَّه لَقِيَ البُخاريَّ. قال الذهبيُّ عنه: \"كان مِن فُرسانِ الحَديثِ، فَهِمًا يَقِظًا مُتقِنًا، كثيرَ الحَديثِ جِدًّا، ومن نظَرَ في تواليفِه، عَرَفَ مَحَلَّه مِن الحفظ\". قال أبو موسى: سَمِعتُ أبي يحكي عمَّن سَمِعَ أبا بكر بنَ مَرْدَوَيه يقول: \"ما كتبتُ بعد العَصرِ شيئًا قَطُّ، وعَمِيتُ قبلَ كُلِّ أحدٍ- يعني من أقرانِه، وسَمِعتُ أنَّه كان يُملي حِفظًا بعدما عَمِيَ. ثم قال: وسَمِعتُ الإمامَ إسماعيلَ يقول: لو كان ابنُ مَردَوَيه خُراسانيًّا، كان صِيتُه أكثَرَ مِن صِيتِ الحاكِمِ\". مات عن سبعٍ وثمانين سنةً"},{"id":1416,"title":"ذكر الفتنة بين الأتراك والأكراد بهمذان .","date":["العام الهجري :411","العام الميلادي :1020"],"text":"زاد شَغبُ الأتراكِ بهَمذانَ على صاحِبِهم شَمسِ الدَّولةِ بنِ فَخرِ الدَّولة، وكان قد تقَدَّمَ ذلك منهم غيرَ مَرَّة، وهو يحلُمُ عنهم بل يَعجِزُ، فقَوِيَ طمَعُهم، فزادوا في التوثُّبِ والشغبِ، وأرادوا إخراجَ القُوَّادِ القوهيَّة الأكرادِ مِن عنده، فلم يُجِبْهم إلى ذلك، فعَزَموا على الإيقاعِ بهم بغيرِ أمْرِه، فاعتَزَل الأكرادُ مع وزيرِه تاجِ الملك أبي نصر بنِ بهرامَ إلى قلعةِ برجين، فسار الأتراكُ إليهم فحَصَروهم، ولم يلتَفِتوا إلى شمسِ الدَّولة، فكتب الوزيرُ إلى أبي جعفرِ بنِ كاكويه، صاحبِ أصبهان، يستنجِدُه، وعَيَّنَ له ليلةً يكونُ قُدومُ العساكِرِ إليه فيها بغتةً، ليخرُجَ هو أيضًا تلك الليلةَ لِيَكبِسوا الأتراك. فعل أبو جعفرٍ ذلك، وسيَّرَ ألفَي فارس، وضَبَطوا الطرقَ لِئَلَّا يسبِقَهم الخبَرُ، وكبسوا الأتراك سَحَرًا على غفلةٍ، ونزل الوزيرُ والقوهيَّةُ من القلعةِ، فوضعوا فيهم السَّيفَ، فأكثَروا القَتلَ، وأخَذوا المالَ، ومَن سلِمَ مِن الأتراكِ نجا فقيرًا، وفعَلَ شَمسُ الدَّولة بمَن عندَه في همذان كذلك، وأخرَجَهم، فمضى ثلاثُمِئَة منهم إلى كرمان، وخدموا أبا الفوارِسِ بنَ بهاء الدَّولة صاحِبَها."},{"id":1417,"title":"الحاكم العبيدي يأمر بحرق القاهرة, ثم ادعائه الألوهية  .","date":["العام الهجري :411","الشهر القمري : شوال","العام الميلادي :1021"],"text":"كان الحاكِمُ العُبَيديُّ صاحِبُ مِصرَ يواصِلُ الرُّكوبَ وتتصَدَّى له العامَّةُ، فيَقِفُ عليهم ويسمَعُ منهم. وكان النَّاسُ في ضنكٍ مِن العَيشِ معه. فكانوا يدسُّونَ إليه الرِّقاعَ المختومةَ بالدُّعاءِ عليه والسَّبِّ له ولأسلافِه، حتى إنَّهم عَمِلوا تمثالَ امرأةٍ مِن كاغد بخُفٍّ وإزارٍ ثمَّ نَصَبوها له، وفي يَدِها قصَّةً. فأمَرَ بأخْذِها مِن يَدِها، ففتَحَها فرأى فيها العظائمَ، فقال: انظُروا مَن هذه. فإذا هي تمثالٌ مَصنوعٌ. فتقَدَّمَ بطَلَبِ الأمراءِ والعُرَفاء فحَضَروا، فأمَرَهم بالمصيرِ إلى مِصرَ لِنَهبِها وحَرقِها بالنَّارِ وقَتلِ أهلِها, فتوجَّهوا لذلك، فقاتل المصريونَ عن أنفُسِهم بحَسَبِ ما أمكَنَهم. ولحِقَ النَّهبُ والحريقُ الأطرافَ والنواحيَ التي لم يكُنْ لأهلِها قُوَّةٌ على امتناعٍ، ولا قدرةٌ على دفاعٍ. واستَمَرَّت الحربُ بين العبيدِ والرَّعيَّة ثلاثةَ أيام، وهو يركَبُ ويُشاهِدُ النَّارَ، ويَسمَعُ الصِّياح. فيَسأل عن ذلك، فيُقال له: العَبيدُ يَحرِقونَ مِصرَ. فيتوجَّعُ ويقولُ: مَن أمَرَهم بهذا؟ لعَنَهم اللهُ, فلما كان في اليومِ الثَّالثِ اجتمَعَ الأشرافُ والشُّيوخُ إلى الجامِعِ ورَفَعوا المصاحِفَ، وعَجَّ الخَلقُ بالبُكاءِ والاستغاثةِ بالله. فرَحِمَهم الأتراكُ وتقاطَروا إليهم وقاتَلوا معهم. وأرسلوا إلى الحاكِمِ يقولونَ له: نحن عبيدُك ومماليكُك، وهذه النَّارُ في بلَدِك وفيه حَرَمُنا وأولادُنا، وما عَلِمْنا أنَّ أهلَها جَنَوا جنايةً تَقتَضي هذا، فإن كان باطِنٌ لا نَعرِفُه عَرِّفْنا به، وانتَظِرْ حتى نُخرِجَ عيالَنا وأموالَنا، وإن كان ما عليه هؤلاء العَبيدُ مُخالِفًا لرأيِك أطلِقْنا في مُعامَلتِهم بما نعامِلُ به المُفسِدينَ. فأجابهم: إنِّي ما أردتُ ذلك ولا أَذِنتُ فيه، وقد أَذِنتُ لكم في الإيقاعِ بهم، وأرسل للعبيدِ سِرًّا بأنْ كونوا على أمْرِكم، وقَوَّاهم بالسِّلاحِ، فاقتَتَلوا وعاودوا الرِّسالةَ: إنَّا قد عَرَفْنا غَرَضَك، وإنَّه إهلاكُ البَلدِ، ولَوَّحوا بأنَّهم يَقصِدونَ القاهرةَ، فلما رآهم مُستَظهرينَ، رَكِبَ حِمارَه ووقف بين الفَريقينِ، وأومأ إلى العَبيدِ بالانصرافِ، وسَكَنَت الفتنةُ، وكان قَدْرُ ما أُحرِقَ مِن مِصرَ ثُلُثَها، ونُهِبَ نِصفُها. وتتَبَّع المِصريونَ مِن أَسَرَ الزَّوجاتِ والبَناتِ، فاشتَرَوهنَّ مِن العَبيدِ بعد أن اعتُدِيَ عليهنَّ، حتى قَتَل جماعةٌ أنفُسَهنَّ مِن العارِ. ثمَّ زاد ظُلمُ الحاكِمِ، وعَنَّ له أن يَدَّعي الرُّبوبيَّةَ، كما فعَلَ فِرعونُ، فصار قَومٌ مِن الجُهَّالِ إذا رأوه يقولونَ: يا واحد يا أحد، يا محيي يا مميت."},{"id":1418,"title":"وفاة الحاكم العبيدي الفاطمي وتولي ابنه الظاهر لإعزاز دين الله .","date":["العام الهجري :411","الشهر القمري : شوال","العام الميلادي :1021"],"text":"هو صاحِبُ مِصرَ الحاكِمُ بأمر الله، أبو عليٍّ منصورُ بنُ العزيز نزار بن المعِزِّ معد بن المنصور إسماعيل بن القائم محمد بن المهدي، العُبَيديُّ الإسماعيليُّ الزِّنديقُ المُدَّعي الرُّبوبيَّة. مولِدُه سنةَ 375. أقاموه في المُلكِ بعد أبيه، وله إحدى عشرةَ سنةً. حكى هو عن نَفسِه قال: \"ضَمَّني أبي وقَبَّلَني وهو عُريان، وقال: امْضِ فالعَبْ، فأنا في عافيةٍ. قال: ثمَّ توفِّيَ، فأتاني برجوان، وأنا على جميزةٍ في الدار. فقال: انزِلْ وَيحَك، اللهَ اللهَ فينا، فنَزَلْت، فوضَعَ العِمامةَ بالجوهَرِ على رأسي، وقبَّلَ الأرضَ، ثمَّ قال: السَّلامُ عليك يا أميرَ المُؤمنينَ، وخرج بي إلى النَّاسِ، فقَبَّلوا الأرضَ، وسَلَّموا عليَّ بالخِلافةِ\". قال الذهبيُّ: \"كان شَيطانًا مَريدًا جَبَّارًا عنيدًا، كثيرَ التلَوُّن، سَفَّاكًا للدِّماء، خبيثَ النِّحلةِ، عظيمَ المَكرِ، جَوادًا مُمَدَّحًا، له شأنٌ عجيبٌ، ونبأٌ غريبٌ، كان فرعونَ زَمانِه، يختَرِعُ كُلَّ وَقتٍ أحكامًا يُلزِمُ الرَّعيَّةَ بها، أمَرَ بسَبِّ الصَّحابةِ رَضِيَ الله عنهم، وبكتابةِ ذلك على أبوابِ المساجِدِ والشوارعِ، وأمَرَ عُمَّالَه بالسَّبِّ، وفي سنة 395 أمَرَ بقَتلِ الكِلابِ. وأبطَلَ بَيعَ الفَقعِ والمُلوخيَّة، وحَرَّم بيعَ السَّمَك بغيرِ قِشرٍ، ووقَعَ بباعةٍ لِشَيءٍ مِن ذلك فقَتَلَهم. وفي سنة 402 حَرَّمَ بيعَ الرُّطَب، وجمَعَ منه شيئًا عظيمًا فأحرَقَه، ومنَعَ مِن بَيعِ العِنَب، وأباد الكُرومَ. وأمر النَّصارى بتعليقِ صَليبٍ في رِقابِهم زِنَتُه رطلٌ وربعٌ بالدمشقيِّ، وألزم اليهودَ أن يُعَلِّقوا في أعناقِهم قرميَّةً في زنة الصَّليبِ إشارةً إلى رأسِ العِجلِ الذي عبدوه، وأن تكونَ عِمائِمُهم سُودًا، وأن يدخُلوا الحَمَّام بالصَّليبِ وبالقرمية، ثم أفرَدَ لهم حَمَّاماتٍ. وأمَرَ في العامِ بهَدمِ كَنيسةِ قمامة، وبهدمِ كَنائِسِ مِصرَ، فأسلَمَ عِدَّةٌ، ثمَّ إنه نهى عن تقبيلِ الأرضِ، وعن الدُّعاءِ له في الخُطَب وفي الكُتُب، وجعَلَ بدَلَه السَّلامُ عليه، ثمَّ إنَّ ابنَ باديس أميرَ المغربِ بَعَث ينقِمُ عليه أمورًا، فأراد أن يَستَميلَه، فأظهَرَ التفَقُّهَ، وحمَلَ في كُمِّه الدَّفاتر، ولَزِمَ التفَقُّهَ وأمَرَ الفُقَهاءَ بِبَثِّ مَذهَبِ مالكٍ، واتَّخَذ له مالكيَّينِ يُفَقِّهانِه، ثمَّ تغَيَّرَ فقَتَلَهما صبرًا\", وفي سنة 404 نفى المنَجِّمينَ مِن بلاده. ومنَعَ النِّساءَ مِن الخروجِ مِن البيوتِ، وأبطَلَ عَمَل الِخفافِ لهنَّ جُملةً، وما زِلنَ ممنوعاتٍ مِن الخروجِ سَبعَ سِنينَ وسَبعةَ أشهر. ثم بعد مُدَّةٍ أمَرَ بإنشاءِ ما هُدِمَ من الكنائِسِ، وأذِنَ للنَّصارى الذين أكرَهَهم في العَودِ إلى الكُفرِ، وخبَرُ هلاكِه أنه فُقِدَ في ليلةِ الاثنينِ لثلاثٍ بَقِينَ مِن شَوَّال، ولم يُعرَفْ له خبَرٌ، وكان سبَبُ فَقدِه أنَّه خرج يطوفُ ليلةً على رَسمِه، وأصبح عند قَبرِ الفقاعي، وتوجَّهَ إلى شرقي حُلوان ومعه ركابيَّان، فأعاد أحدَهما مع جماعةٍ مِن العرب إلى بيتِ المال، وأمر لهم بجائزةٍ، ثمَّ عاد الركابيُّ الآخر، وذكَرَ أنَّه خَلَّفَه عند العَينِ والمقصبة، وبقيَ النَّاسُ على رسمِهم يَخرُجونَ كُلَّ يومٍ يلتَمِسونَ رُجوعَه إلى آخر شوال، فلما كان ثالثُ ذي القعدة خرج مُظَفَّر الصقلبي وغَيرُه من خواصِّ الحاكِمِ، ومعهم القاضي، فبَلَغوا عسفان، ودخلوا في الجَبَلِ، فبَصُروا بالحِمارِ الذي كان عليه راكبًا، وقد ضُرِبَت يداه بسَيفٍ فأثَّرَ فيهما، وعليه سَرجُه ولِجامُه، فاتَّبَعوا الأثَرَ، فانتهوا به إلى البِركةِ التي شَرقيَّ حلوان، فرأوا ثيابَه، وهي سبعُ قِطَع صُوف، وهي مُزَرَّرة بحالِها لم تُحَلَّ، وفيها أثَرُ السَّكاكين، فعادوا ولم يَشُكُّوا في قَتلِه، وكان عُمُرُه 37 سنة، وولايته 25 سنة, وقيل: إنَّ سَبَبَ قَتلِه هو أنَّه كان كثيرَ الشَّتمِ والسَّبِّ لأختِه سِتِّ الملك، واتَّهَمَها بالفاحشة، فعَمِلَت على قتلِه، بحيث كانت تَعرِفُ يومَ خُروجِه إلى الجَبَلِ لينظُرَ في النجومِ، فتمالأت مع الوزيرِ وأرسلوا عبدينِ أسودَينِ، فلما كان من اللَّيلِ وسار إلى الجبَلِ وَحدَه، قتَلَه العبدانِ وأحضراه إلى أختِه التي دفنته في دارِه، وقَرَّرَت توليةَ وَلَدِه، وكان حينها بدمشقَ، فأخبَرَت النَّاسَ أنَّ الحاكِمَ سيَغيبُ سَبعةَ أيَّامٍ, وهذا لِيَسكُنَ النَّاسُ ويَحضُرَ ابنُه من دمشق، فلما حضَرَ جَهَّزَتْه وأخرَجَتْه للنَّاسِ، على أنَّه الحاكِمُ الجديدُ، وابنُه هو أبو الحسن علي، ولُقِّبَ الظاهِرَ لإعزاز دين الله، وأُخِذَت له البيعةُ."},{"id":1419,"title":"ذكر حماية محمود الغزنوي حجاج العراق .","date":["العام الهجري :412","العام الميلادي :1021"],"text":"لَمَّا توقَّفَ الحجُّ مِن العِراقِ عِدَّةَ سَنَواتٍ مُتَتالياتٍ خَوفًا مِن الأعرابِ قُطَّاعِ الطُّرُقِ، قَصَد النَّاسُ يَمينَ الدَّولةِ محمودَ بنَ سبكتكين وقالوا له: أنت سُلطانُ الإسلامِ وأعظَمُ مُلوكِ الأرض، وفي كلِّ سَنةٍ تَفتَحُ مِن بلادِ الكُفرِ ما تُحِبُّه، والثَّوابُ في فَتحِ طَريقِ الحَجِّ أعظَمُ، وقد كان الأميرُ بَدرُ بنُ حسنويه، وما في أمرائِك إلَّا مَن هو أكبَرُ منه شأنًا، يُسَيِّرُ الحاجَّ بمالِه وتدبيرِه عشرينَ سَنةً، فتقَدَّمَ ابنُ سبكتكين إلى قاضيه أبي مُحمَّدٍ الناصحي بالتأهُّبِ للحَجِّ، ونادى في أعمالِ خُراسان بالحَجِّ، وأطلق للعَرَبِ ثلاثينَ ألفَ دينارٍ سَلَّمَها إلى النَّاصحيِّ المذكورِ غيرَ ما للصَّدَقاتِ، فحَجَّ بالنَّاسِ أبو الحَسَن ِالأقساسي، فلمَّا بلغوا فيدَ حاصَرَتْهم العرَبُ، فبذل لهم القاضي النَّاصحي خمسةَ آلافِ دينارٍ، فلم يَقنَعوا وصَمَّموا على أخذِ الحافي، فرَكِبَ رأسَهم جَمَّازُ بنُ عديٍّ، وقد انضم عليه ألفا رجُلٍ مِن بني نبهان، وأخذ بِيَدِه رمحًا وجال حولَ الحاجِّ، وكان في السَّمَرْقنديِّينَ غُلامٌ يُعرَفُ بابنِ عَفَّان، فرماه بسَهمٍ فسَقَط منه مَيِّتًا وهَرَب جَمعُه، وعاد الحاجُّ في سلامةٍ."},{"id":1420,"title":"نهاية الدَّولة الزيادية في اليمن وقيام دولة بني نجاح .","date":["العام الهجري :412","العام الميلادي :1021"],"text":"لَمَّا توفِّيَ أبو الحَبشِ إسحاقُ بنُ إبراهيمَ حاكِمُ دَولةِ بني زيادٍ في اليَمَنِ سَنَةَ 371، وقد طالت مُدَّةُ حُكمِه وأسَنَّ؛ خَلَفَه طِفلٌ قيلَ اسمُه زيادُ بنُ أبي الحبش، وتولت أختُه هندُ بنت أبي الحبش، وتولى معها في تصريفِ شُؤونِ الدَّولةِ رشد، وهو عبدٌ لأبي الحبَشِ، وبقي رشدٌ على ولايتِه حتى مات، فتَولَّى عبدٌ لرشدٍ اسمُه حُسَينُ بن سلامة إدارةَ الدَّولةِ، وسلامة هي أمُّ حسين، ونشأ حسينٌ حازِمًا عفيفًا، وصار وزيرًا لهند ولأخيها زيادٍ حتى ماتا، ثم انتقل مُلكُ اليَمَنِ إلى طفلٍ من آلِ زيادٍ، وقامت بأمرِه عَمَّتُه وعبدٌ لحُسَينِ بنِ سلامة اسمُه مرجان، وكان لمرجان عبدانِ قد تغَلَّبا على أمورِه قَيسٌ ونجاح، ونجاحٌ جَدُّ ملوك زبيد، فتنافَسَ قيسٌ ونجاحٌ على الوَزارةِ، وكان قيسٌ عَسُوفًا ونجاحٌ رَؤوفًا، وسَيِّدهما مرجان يميلُ مع قيسٍ على نَجاحٍ، وعَمَّة الطفل تميلُ إلى نجاح، فشكا ذلك قيسٌ إلى مولاه مرجان، فقبض مرجان على المَلِك واسمُه إبراهيم- وقيل: عبد الله- وعلى عَمَّتِه، وسلَّمَهما إلى قيسٍ، فبنى عليهما جدارًا وخَتَمه حتى ماتا، وإبراهيمُ آخِرُ مُلوكِ اليمَنِ من بني زياد، ومُدَّةُ مُلكِ بني زياد اليَمَن مائتان وأربع سنين، وانتقل مُلكُهم إلى عَبيدِ عَبيدِ (بني زياد)؛ لأنَّ المُلكَ صار لنَجاحٍ."},{"id":1421,"title":"أهل العراق يعودون للحج بعد أن توقف سنوات خوفاً من الأعراب .","date":["العام الهجري :413","العام الميلادي :1022"],"text":"حجَّ النَّاسُ مِن العراقِ بعد أن توقَّفَ الحَجُّ مِن جِهةِ العِراقِ والشَّامِ وما وراءَ النَّهرِ؛ خوفًا من الأعرابِ الذين كانوا يَقطَعونَ الحَجَّ ويَنهَبونَ ويَقتُلونَ الحُجَّاجَ؛ حيث بقِيَ الأمرُ على ذلك عِدَّةَ سَنَواتٍ تُقارِبُ العَشرَ، لا يخرُجُ وَفدُ حَجٍّ مِن هذه المناطِقِ إلَّا من مصرَ والمغربِ واليمَنِ أحيانًا."},{"id":1422,"title":"رجل من أتباع الباطنية يطعن الحجر الأسود ثلاث ضربات .","date":["العام الهجري :413","العام الميلادي :1022"],"text":"اتَّفَق أحَدُ المِصريِّينَ مِن أصحابِ الحاكِمِ مع جماعةٍ مِن الحُجَّاجِ المصريِّينَ على أمرٍ سُوءٍ، وذلك أنَّه لَمَّا كان يومُ النَّفرِ الأوَّلِ، طاف هذا الرجُلُ بالبَيتِ، فلما انتهى إلى الحَجَرِ الأسودِ جاء ليُقَبِّلَه فضَرَبه بدبوسٍ كان معه ثلاثَ ضَرَباتٍ مُتَوالياتٍ، وقال: إلى متى نعبُدُ هذا الحجَرَ؟ ولا مُحمَّدٌ ولا عليٌّ يَمنَعُني ممَّا أفعله، فإنِّي أهدم اليومَ هذا البيتَ، وجعل يرتَعِدُ، فاتَّقاه أكثَرُ الحاضرينَ وتأخَّروا عنه؛ وذلك لأنَّه كان رجُلًا طُوالًا جَسيمًا، وعلى باب المسجِدِ الحَرامِ جَماعةٌ مِن الفُرسان وُقوفٌ لِيَمنعوه ممَّن يريدُ مَنْعَه من هذا الفِعلِ وأراده بسُوءٍ، فتقَدَّمَ إليه رجلٌ مِن أهلِ اليَمَنِ معه خِنجَرٌ فوَجَأَه به، وتكاثَرَ النَّاسُ عليه فقَتَلوه وقَطَّعوه قِطَعًا، وحَرَّقوه بالنَّارِ، وتَتَّبَعوا أصحابَه فقتلوا منهم جماعةً، ونَهَبَت أهلُ مَكَّةَ الرَّكبَ المصريَّ، وتعدَّى النَّهبُ إلى غيرهم، وجَرَت خبطةٌ عَظيمةٌ، وفِتنةٌ كبيرةٌ جِدًّا، ثم سكَنَ الحالُ بعد أن تُتُّبِعَ أولئك النَّفَرُ الذين تمالَؤوا على الإلحادِ في أشرَفِ البلادِ، غيرَ أنَّه قد سقط من الحَجَرِ ثلاثُ فِلَقٍ مِثل الأظفارِ، وبدا ما تحتَها أسمَرَ يَضرِبُ إلى صُفرةٍ، مُحَبَّبًا مثل الخَشخاشِ، فأخذ بنو شيبةَ تلك الفِلَقَ فعَجَنوها بالمِسْكِ وحَشَوا بها تلك الشُّقوقَ التي بَدَت، فاستمسَكَ الحَجَرُ."},{"id":1423,"title":"وفاة الشيخ المفيد ابن المعلم شيخ الإمامية الرافضة .","date":["العام الهجري :413","العام الميلادي :1022"],"text":"عالمُ الرَّافِضةِ، صاحِبُ التَّصانيفِ: أبو عبدِ اللهِ مُحمَّدُ بنُ محمد بن القاضي النعمان البغدادي الكَرْخي بن محمد المغربي، المعروفُ بابنِ المعَلِّم أو الشَّيخ المُفيد شيخ الإماميَّة الرَّوافض، والمُصَنِّف لهم، والمُحامي عن حوزتِهم، صاحِب فُنونٍ وبحوثٍ وكلام، واعتزالٍ وأدبٍ. قال الذهبي: \"ذكَرَه ابن أبي طي في \"تاريخ الإماميَّة\"، فأطنب وأسهب، وقال: كان أوحَدَ في جميعِ فُنونِ العلم: الأصلينِ، والفِقه، والأخبار، ومعرفة الرِّجال، والتفسير، والنحو، والشعر\". كانت له وَجاهةٌ عند ملوك الأطرافِ، وكان مَجلِسُه يَحضُرُه خَلقٌ كَثيرٌ مِن العُلَماءِ مِن سائر الطوائِفِ، وكان من جُملةِ تلاميذِه الشَّريفُ الرَّضِيُّ، والمرتضى، له تصانيفُ؛ منها: الإرشادُ، والرسالة المُقنِعة، والإعلام فيما اتَّفَقَت عليه الإماميَّة من الأحكامِ وغيرها. كان يُناظِرُ أهلَ كُلِّ عقيدةٍ مع ما له من العَظَمةِ في الدَّولة البُويهيَّة، والرُّتبة الجَسيمة عند الخُلَفاء، وكان قويَّ النَّفسِ، كثيرَ البِرِّ، عظيمَ الخُشوعِ، كثيرَ الصَّلاة والصَّوم، يَلبَسُ الخَشِنَ من الثياب، وكان مُديًما للمطالعةِ والتَّعليمِ، ومن أحفَظِ الناس. قيل: \"إنَّه ما ترك للمُخالفينَ كِتابًا إلَّا وحَفِظَه، وبهذا قَدَرَ على حَلِّ شُبَهِ القَومِ، وكان مِن أحرَصِ النَّاسِ على التَّعليم؛ يدورُ على المَكاتبِ وحوانيتِ الحاكَةِ، فيتلَمَّحُ الصبيَّ الفَطِنَ، فيستأجرُه من أبويه- يعني فيُضِلُّه- وبذلك كَثُر تلامِذتُه\". ربما زاره عَضُدُ الدَّولة، وكان يقضي حوائجَه ويقول له: اشفَعْ تُشَفَّع، وكان يقومُ لتلامذتِه بكُلِّ ما يحتاجونَ إليه. وكان الشَّيخُ المفيد ربعةً نحيفًا، أسمرَ، وما استغلَقَ عليه جوابٌ إلَّا فَزِعَ إلى الصلاة، ثم يسألُ اللهَ فيُيَسِّرُ له الجواب. عاش ستًّا وسبعين سنة، وصَنَّف أكثَرَ من مِئَتي مُصَنَّف، وشَيَّعَه ثمانون ألفًا، وكانت جنازتُه مشهودة. قال الذهبي: \"بلَغَت تواليفُه مِئَتين، لم أقِفْ على شيءٍ منها، ولله الحَمدُ\""},{"id":1424,"title":"وفاة ابن البواب الكاتب المشهور .","date":["العام الهجري :413","الشهر القمري : جمادى الأولى","العام الميلادي :1022"],"text":"الكاتِبُ المَشهورُ صاحِبُ الخَطِّ المنسوبِ أبو الحَسَنِ عليُّ بنُ هلالٍ البَغداديُّ، المعروف بابنِ البَوَّاب؛ ويقال له \"ابن الستري\" أيضًا؛ لأنَّ أباه كان بوَّابًا، والبَوَّاب ملازِمٌ سِترَ البابِ، فلهذا نُسِبَ إليهما. كان شَيخُه في الكتابةِ ابنَ أسَدٍ الكاتِبَ المَشهورَ، وهو أبو عبدِ اللهِ مُحمَّدُ بنُ أسدِ بنِ عليِّ بنِ سَعيدٍ القارئ الكاتب البزَّاز البغدادي. قال ابن كثيرٍ: \"وقد أثنى على ابنِ البوَّابِ غَيرُ واحد في دينِه وأمانته، وأمَّا خَطُّه وطريقتُه، فهي أشهرُ مِن أن نُنَبِّهَ عليها، وخَطُّه أوضَحُ تعريبًا من خط الوزيرِ أبي عليِّ بنِ مُقلةَ الكاتبِ المَشهورِ، ولم يكُنْ بعدَ ابنِ مُقلةَ أكتَبُ منه، وعلى طريقتِه النَّاسُ اليومَ في سائِرِ الأقاليمِ إلَّا القَليلَ\". قال ابنُ خَلِّكانَ: \"لم يوجَدْ في المتقَدِّمينَ ولا المتأخِّرينَ مَن كَتَبَ مِثلَه ولا قارَبَه، وإن كان أبو عليٍّ ابنُ مُقلةَ الوزيرُ أوَّلَ مَن نَقَل هذه الطريقةَ مِن خَطِّ الكوفيِّينَ، وأبرَزَها في هذه الصُّورةِ، وله بذلك فضيلةُ السَّبقِ، وخَطُّه أيضًا في نهايةِ الحُسنِ، لكِنَّ ابنَ البوَّابِ هَذَّبَ طريقةَ ابنِ مُقلةَ ونَقَّحَها وكَساها طلاوةً وبَهجةً. والكُلُّ مُعتَرِفٌ لابنِ البوَّابِ بالتفَرُّد، وعلى منوالِه يَنسجونَ، وليس فيهم من يَلحَقُ شَأوَه ولا يَدَّعي ذلك، مع أنَّ في الخَلقِ مَن يدَّعي ما ليس فيه، ومع هذا فما رأَينا ولا سَمِعْنا أنَّ أحدًا ادَّعى ذلك، بل الجميعُ أقَرُّوا له بالسَّابقةِ وعَدَمِ المشاركة\". توفِّي ابنُ البوَّاب ببغداد، ودُفِنَ جوارَ الإمامِ أحمدَ بنِ حنبلٍ."},{"id":1425,"title":"نهاية حكم بني حمود الطالبيين في الأندلس .","date":["العام الهجري :414","العام الميلادي :1023"],"text":"كان القاسِمُ بنُ حَمُّود بقُرطبةَ تَولَّى الحُكمَ بعد أخيه عليِّ بنِ حَمُّود, ثمَّ قام عليه ابنُ أخيه يحيى بنُ علي بن حمود بمالقةَ، فهرب القاسِمُ مِن قُرطبةَ بلا قتالٍ، وصار بأشبيليَّةَ، ثم عاد إليها مرَّةً أخرى، فبقي القاسِمُ بقُرطبةَ شُهورًا واضطَرَب أمرُه، وغَلَب ابنُ أخيه يحيى على المدينةِ المعروفةِ بالجزيرةِ الخضراءِ، وهي كانت مَعقِلَ القاسِمِ، وبها كانت امرأتُه وذخائِرُه، وغلب ابنُ أخيه الثاني إدريسُ بنُ علي صاحِبُ سبتةَ على طنجةَ، وهي كانت عُدَّةُ القاسِمِ يلجأُ إليها إن رأى ما يخافُه بالأندلس، ثمَّ إنَّ أهلَ قُرطبةَ زَحَفوا إلى البربرِ، فانهزم البربرُ عن القاسمِ وخَرَجوا من الأرباضِ كُلِّها في شعبان سنة 414، ولَحِقَت كلُّ طائفةٍ مِن البربرِ ببلَدٍ غَلَبَت عليه، وقصَدَ القاسِمُ أشبيليَّةَ وبها كان ابناه محمَّدٌ والحسن, فلمَّا عَرَفَ أهلُ أشبيليَّةَ خُروجَه عن قُرطُبة ومَجيئَه إليهم، طردوا ابنَيه ومن كان معهما مِن البربرِ وضَبَطوا البلَدَ وقَدَّموا على أنفُسِهم ثلاثةً مِن أكابِرِ البَلَدِ. لَحِقَ القاسِمُ بشَرِيش، واجتَمَعَ البَربرُ على تقديمِ ابنِ أخيه يحيى، فزَحَفوا إلى القاسِمِ فحاصروه حتى صار في قبضةِ ابنِ أخيه، وانفرَدَ ابنُ أخيه يحيى بولايةِ البربر. وبَقِيَ القاسِمُ أسيرًا عنده وعند أخيه إدريسَ بعده إلى أن مات إدريسُ، فقُتِلَ القاسمُ خَنقًا سنة 431، وحُمِلَ إلى ابنه محمَّدِ بنِ القاسم بالجزيرة، فدَفَنَه هناك. فكانت ولايةُ القاسِمِ منذ تسمَّى بالخلافةِ بقُرطبةَ إلى أن أسَرَه ابنُ أخيه سِتَّةَ أعوامٍ، ثم كان مقبوضًا عليه ستَّ عشرةَ سَنةً عند ابني أخيه يحيى وإدريس، إلى أن قُتِلَ. مات القاسِمُ وله ثمانون سنة، وله مِن الولد محمد والحسن، أمُّهما أميرةُ بنتُ الحَسَنِ بن قَنُّون بن إبراهيم بن محمد بن القاسم بن إدريس بن إدريس بن عبد الله بن الحسن بن الحسن بن علي بن أبي طالب."},{"id":1426,"title":"وفاة الفيلسوف الصوفي أبو حيان التوحيدي .","date":["العام الهجري :414","العام الميلادي :1023"],"text":"هو أبو حيَّانَ عليُّ بن محمَّد بن العبَّاس البغدادي، الصوفي، صاحِبُ التَّصانيفِ، له مصنَّفاتٌ عديدةٌ في الأدبِ والفصاحةِ والفلسفةِ، له مصنَّفٌ كبيرٌ في تصوُّفِ الحكماءِ، وزهَّاد الفلاسفة، وكتابٌ سمَّاه البصائرَ والذخائرَ, وكان سيئَ الاعتقادِ، نفاه الوزيرُ أبو محمد المهلبي. ذكر ابن بابي في كتاب الخريدة والفريدة: \"كان أبو حيان كذَّابًا، قليلَ الدين والوَرَع عن القَذفِ والمجاهَرة بالبُهتان، تعرَّضَ لأمور جِسامٍ من القَدحِ في الشريعة والقَولِ بالتعطيل، ولقد وقف سيدُنا الصاحِبُ كافي الكُفاة على بعضِ ما كان يدغلُه ويُخفيه من سوء الاعتقادِ، فطلبه ليقتُلَه، فهرب والتجأ إلى أعدائه، ونفَق عليهم بزُخرفه وإفكِه، ثم عثَروا منه على قبيحِ دخلته وسوء عقيدته وما يُبطِنُه من الإلحاد ويرومُه في الإسلام من الفساد، وما يُلصِقُه بأعلام الصَّحابة من القبائِحِ، ويضيفُه إلى السلف الصالح من الفضائح، فطلبه الوزيرُ المهلبي فاستتر منه، ومات في الاستتار، وأراح الله منه، ولم تؤثَرْ عنه إلا مَثلبةٌ أو مخزيةٌ. \""},{"id":1427,"title":"مسير السلطان مشرّف الدَّولة إلى بغداد\n  .","date":["العام الهجري :414","الشهر القمري : صفر","العام الميلادي :1023"],"text":"سار السُّلطانُ مُشرفُ الدَّولة مُصعِدًا إلى بغداد من ناحيِة واسط، ورُوسِلَ القادِرُ باللهِ في البروزِ لتَلَقِّيه، فتلقَّاه من الزلاقة، ولم يكن تلقَّى أحدًا من الملوكِ قَبلَه. فرَكِبَ في الطيار، وعن جانبه الأيمَنِ الأميرُ أبو جعفر، وعن يسارِه الأميرُ أبو القاسمِ، وبين يديه أبو الحسَنِ عليُّ بنُ عبد العزيز، وحوالي القُبَّة الشريف أبو القاسم المرتضي، وأبو الحَسَن الزينبي، وقاضي القُضاة ابنُ أبي الشوارب، وفي الزبازب المسَوِّدة من العباسيِّين، والقضاة، والقُرَّاء، والعلماء، ونزل مُشرفُ الدَّولة في زبزبه بخواصِّه، وصعد إلى الطيار، فقَبَّلَ الأرض، وأُجلِسَ على كرسيٍّ، وسأله الخليفةُ عن خبره وكيف حالُه، والعسكَرُ واقِفٌ بأسره على شاطئِ دِجلةَ، والعامَّةُ في الجانبين. ثم قام مشرف الدَّولة فنزل إلى زبزبه، وأصعد الطيار."},{"id":1428,"title":"محمود بن سبكتكين يفتح قلعة بالهند .","date":["العام الهجري :414","الشهر القمري : صفر","العام الميلادي :1023"],"text":"أوغلَ يَمينُ الدَّولة محمودُ بنُ سبكتكين في بلاد الهندِ، فغَنِمَ وقَتَل، حتى وصل إلى قلعةٍ على رأس جبَلٍ منيعٍ، ليس له مَصعدٌ إلَّا من موضعٍ واحدٍ، وهي كبيرةٌ تَسَعُ خلقًا، وبها خمسُمِئَة فيل، وفي رأسِ الجَبَلِ من الغَلَّات والمياه، وجميعِ ما يحتاجُ الناسُ إليه، فحصرهم يمينُ الدَّولة، وأدام الحِصارَ، وضَيَّق عليهم، واستمَرَّ القتال، فقُتِل منهم كثيرٌ، فلما رأَوا ما حلَّ بهم أذعنوا له، وطلبوا الأمان، فأمَّنَهم وأقَرَّ مَلِكَهم فيها على خراجٍ يأخُذُه منه، وأُهديَ له هدايا كثيرةٌ، منها طائِرٌ على هيئة القمريِّ مِن خاصيَّتِه إذا أُحضِرَ الطَّعامُ وفيه سُمٌّ دَمِعَت عينا هذا الطائِرِ وجرى منهما ماءٌ، ثم يتحَجَّرُ، فإذا حُكَّ وجُعِلَ على الجِراحاتِ الواسعةِ ألحَمَها."},{"id":1429,"title":"عودة الحكم إلى بني أمية في الأندلس ثم صراعهم عليه .","date":["العام الهجري :414","الشهر القمري : رمضان","العام الميلادي :1023"],"text":"لَمَّا انهَزَم البربر عن قُرطُبةَ مع أبي القاسِمِ، اتَّفَق رأيُ أهل قُرطُبة على رَدِّ الأمرِ إلى بني أميَّة، فاختاروا منهم ثلاثةً، وهم: عبدُ الرَّحمنِ بنُ هِشامِ بنِ عبد الجبَّار بن عبد الرَّحمن الناصر أخو المهديِّ، وسُليمانُ بنُ المرتضى، ومحمَّدُ بنُ عبد الرحمن بن هشام بن سليمان القائمُ على المهدي بن الناصر، ثم استقَرَّ الأمر لعبدِ الرَّحمنِ بن هشامِ بنِ عبد الجبَّار، فبويع بالخلافةِ لثلاثَ عَشرةَ ليلةً خلت لرمضان سنة 414هـ، وله اثنتان وعشرون سنةً، وتلَقَّبَ بالمُستَظهر، ثم قام عليه أبو عبدِ الرَّحمنِ مُحمَّدُ بن عبد الرحمن بن عبيد الله بن عبد الرحمن الناصر مع طائفةٍ مِن أراذِلِ العَوامِّ فقُتِلَ عبدُ الرَّحمنِ بنُ هشام، وذلك لثلاثٍ بَقِينَ مِن ذي القَعدةِ سَنةَ 414هـ، وتلَقَّب محمَّدُ بنُ عبد الرحمن هذا بالمُستكفي، وبويعَ له بالخِلافةِ."},{"id":1430,"title":"تجديد البيعة لمشرف الدَّولة البويهي .","date":["العام الهجري :415","العام الميلادي :1024"],"text":"ألزم الوزيرُ أبو القاسِمِ المَغربيُّ الأتراكَ والمولَّدينَ لِيَحلِفوا لمُشَرف الدَّولةِ البويهي، وكَلَّف مُشرف الدَّولة المُرتضى ونِظام الحضرتَينِ أبا الحَسَن الزينبي، وقاضي القضاة، وأبا الحَسَن بن أبي الشوارب، وجماعةً مِن الشهود بالحضور، فظَنَّ الخليفةُ القادِرُ بالله أنَّ التحالُفَ لِنيَّةٍ مَدخولةٍ في حَقِّه، فبعث من دارِ الخليفةِ مَن منع الباقينَ بأن يحلِفوا، وأنكر على المُرتَضى والزينبي وقاضي القُضاة حُضورَهم بلا إذنٍ، واستُدْعُوا إلى دارِ الخلافة، وأُظهِرَ عَزمُ الخليفة على الرُّكوبِ, وبلغ ذلك إلى مُشرف الدَّولة، وانزعج منه، فتردَّدَت الرسائلُ بين الخليفةِ ومُشرف الدَّولة باستحالةِ أن يكون هذا الحَلِفُ ضِدَّه، وانتهى الأمرُ إلى أن حلَفَ مُشرف الدَّولة على الطَّاعةِ والمُخالَصة للخَليفةِ، وكان وقوعُ اليَمينِ في يومِ الخميسِ الحاديَ عَشَر من صفَر، وتولى أخْذَها واستيفاءَها القاضي أبو جعفرٍ السمناني، ثم حلَفَ الخليفةُ لِمُشرف الدَّولة."},{"id":1431,"title":"فتنة بالكوفة بين العلويين والعباسيين .","date":["العام الهجري :415","العام الميلادي :1024"],"text":"وقَعَت بين المُختارِ أبي عليِّ بنِ عبيد الله العَلَويِّ وبين الزكيِّ أبي علي النهرسابسي، وأبي الحَسَن عليِّ بنِ أبي طالب بن عمر مُباينةٌ، فاعتضَدَ المُختارُ بالعباسيِّينَ، فساروا إلى بغدادَ، وشَكَوا ما يَفعَلُ بهم النهرسابسي، فتقَدَّمَ الخليفةُ القادِرُ باللهِ بالإصلاح بينهم مراعاةً لأبي القاسمِ الوَزيرِ المغربيِّ؛ لأنَّ النهرسابسي كان صديقَه، وابنُ أبي طالبٍ كان صِهرَه، فعادوا، واستعان كلُّ فريق ببني خفاجةَ، فأعان كلُّ فَريقٍ مِن الكوفيِّينَ طائفةً مِن خفاجة، فجرى بينهم قتالٌ، فظهر العَلويُّونَ، وقُتِلَ مِن العباسيِّينَ سِتَّةُ نَفَر، وأُحرِقَت دُورُهم ونُهِبَت، فعادوا إلى بغداد، ومَنَعوا من الخُطبةِ يومَ الجمعة، وثاروا، وقَتَلوا ابنَ أبي العبَّاس العلَويِّ وقالوا: إنَّ أخاه كان في جُملةِ الفَتَكة بالكوفة، فبرَز أمرُ الخليفةِ إلى المرتضى يأمُرُه بصرفِ ابنِ أبي طالب عن نقابةِ الكُوفةِ، ورَدِّها إلى المختارِ، فأنكر الوزيرُ المغربيُّ ما يجري على صِهرِه ابنِ أبي طالبٍ مِن العزل، وكان عند قرواش صاحبِ المَوصِل, فأرسلَ الخليفةُ القاضيَ أبا جعفرٍ السمناني في رسالةٍ إلى قرواش يأمُرُه بإبعادِ المغربيِّ عنه، ففعل، فسار المغربيُّ إلى ابنِ مَروانَ بديارِ بكرٍ، وغَضِبَ الخليفةُ على النهرسابسي، وبَقِيَ تحت السَّخَط إلى سنة ثماني عشرة وأربعمِئَة، فشَفِعَ فيه الأتراكُ وغَيرُهم، فرَضِيَ عنه، وحَلَّفَه على الطاعةِ فحَلَف."},{"id":1432,"title":"المُعِزُّ بنُ باديس الصنهاجيُّ يقضي على فتنة زناتة بإفريقيَّةَ .","date":["العام الهجري :415","العام الميلادي :1024"],"text":"خرجَ بإفريقيَّةَ جَمعٌ كثيرٌ مِن زناتة -قبيلة أمازيغية-، فقَطَعوا الطَّريقَ، وأفسَدوا بقسطيلية ونفزاوة، وأغاروا وغَنِموا، واشتَدَّت شَوكتُهم، وكَثُرَ جَمعُهم، فسَيَّرَ إليهم المُعِزُّ بنُ باديس الصنهاجيُّ- صاحِبُ إفريقيَّة- جيشًا، وأمَرَهم أن يَجِدُّوا السَّيرَ ويَسبِقوا أخبارَهم، ففَعَلوا ذلك، وكَتَموا خبرهم، وطَوَوا المراحِلَ حتى أدرَكوهم وهم آمِنونَ مِن الطَّلَبِ، فوضعوا فيهم السَّيفَ، فقُتِلَ منهم خلقٌ كثيرٌ، وعُلِّقَ خَمسُمئة رأسٍ في أعناقِ الخُيولِ وسُيِّرَت إلى المعز، وكان يومُ دخولِها يومًا مَشهودًا."},{"id":1433,"title":"قيام الدَّولة المرداسية في حلب .","date":["العام الهجري :415","العام الميلادي :1024"],"text":"مؤسِّسُ الدَّولةِ المرداسيَّة في حلَبٍ هو صالِحُ بنُ مرداس الذي لُقِّبَ أسدَ الدَّولة. وهو من بني كلابٍ، القبيلةِ العربيَّةِ التي كانت تَنزِلُ ضِفافَ الفُراتِ والجزيرة, وكان بالرَّحبةِ رَجلٌ مِن أهلها يُعرَفُ بابنِ محكان، فمَلَك البلدَ، واحتاجَ إلى من يجعَلُه ظَهرَه، ويستعينُ به على مَن يَطمَعُ فيه، فكاتَبَ صالِحَ بنَ مِرداس الكلابيَّ، فقَدِمَ عليه وأقام عنده مُدَّةً، ثمَّ إنَّ صالحًا عدا على ابنِ محكان فقتَلَه ومَلَك الرَّحبة, وفي سنة 399 كانت وقعةٌ بين أبي نصرِ بنِ لؤلؤٍ صاحِبِ حَلَب، وصالحِ بنِ مرِداس، وكان ابنُ لؤلؤ من موالي بنِي حمدان، فقَوِيَ على ولَدِ سَعدِ الدَّولة يخطُبُ للحاكِمِ صاحِبِ مِصرَ، ثمَّ فسد ما بينه وبين الحاكِمِ، فطَمِعَ فيه ابنُ مرداس، وبنو كلاب، وكانوا يطالِبونَه بالصِّلاتِ والخِلَع، ثمَّ إنهم اجتَمَعوا في خمسمِئَة فارس، ودخلوا مدينةَ حَلَب، فأمر ابنُ لؤلؤ بإغلاقِ الأبوابِ والقَبضِ عليهم، فقُبِضَ على مِئَة وعشرينَ رَجُلًا، منهم صالحُ بنُ مرداس، وحَبَسهم، وقتَلَ مِئَتين, وبَقِيَ صالِحُ بنُ مِرداسَ في الحَبسِ، حتى صَعِدَ مِن السور وألقى نفسَه مِن أعلى القلعةِ إلى تَلِّها, وسار بقَيدِه ولبنةِ حديدٍ في رِجلَيه، حتى وصل قريةً تُعرَفُ بالياسريَّة، فرأى ناسًا من العربِ فعَرَفوه وحَمَلوه إلى أهلِه بمرج دابق، فجمَعَ ألفَي فارسٍ وقصَدَ حَلَب وحاصَرَها اثنين وثلاثين يومًا، فخرجَ إليه ابنُ لؤلؤ، فقاتَلَه، فهَزَمَهم صالحٌ وأسَرَ ابنَ لؤلؤ، وقيَّدَه بقَيدِه الذي كان في رِجلِه ولَبِنَتِه. ثمَّ إنَّ ابنَ لؤلؤٍ بذَلَ لابنِ مرداسٍ مالًا على أن يُطلِقَه، فلمَّا استقَرَّ الحالُ بينهما أخذ رهائِنَه وأطلقَه، فلمَّا قُتِلَ الحاكِمُ العُبَيديُّ صاحِبُ مِصرَ، اجتمع حَسَّان أميرُ بني طي، وصالحُ بنُ مرداس أميرُ بني كلاب، وسِنانُ بنُ عليان، وتحالفوا، واتَّفَقوا على أن يكونَ مِن حَلَب إلى عانة لصالحٍ، ومِنَ الرَّملةِ إلى مصرَ لحَسَّان، ودمشقُ لسنان، فسار حسَّان إلى الرملةِ وأخَذَها من أنوشتكين نائِبِ الحاكِمِ، وقصَدَ صالِحٌ حَلَب، وبها إنسانٌ يُعرَفُ بابن ثعبان يتولَّى أمْرَها للمِصريِّينَ، وبالقلعةِ خادِمٌ يُعرَفُ بمَوصوفٍ، فأمَّا أهلُ البلدِ فسَلَّموه إلى صالحٍ؛ لإحسانِه إليهم، ولِسُوءِ سِيرةِ المِصريِّينَ معهم، وصَعِدَ ابنُ ثعبان إلى القلعةِ، فحَصَره صالحٌ بالقلعةِ، فغار الماءُ الذي بها، فلم يبقَ لهم ما يَشرَبونَ، فسَلَّمَ الجُندُ القلعةَ إليه، وذلك سنة 414، ومَلَك مِن بَعْلَبَكَّ إلى عانة، وأقام بحَلَب سِتَّ سنين إلى أن قُتِلَ على يدِ المِصريِّينَ سنة 420."},{"id":1434,"title":"وفاة ابن النقيب مِن أئمَّةِ أهل السُّنَّة .","date":["العام الهجري :415","الشهر القمري : شعبان","العام الميلادي :1024"],"text":"هو عُبَيدُ اللهِ بنُ عَبدِ اللهِ بنِ الحُسَين أبو القاسِمِ الخَفَّاف، المعروف بابنِ النَّقيبِ. كان مِن أئمَّةِ السُّنَّة، قال الخطيبُ: \"سألتُه عن مولِدِه فقال في سنة 305، وأذكُرُ مِن الخُلَفاءِ: المُقتَدِر، والقاهِرَ، والرضيَّ، والمُتَّقيَ لله، والمُستكفيَ، والمُطيع، والطَّائِعَ، والقادِرَ، والغالِبَ بالله، الذي خطَبَ له بولايةِ العَهدِ\". وقيل إنَّه مَكَث دَهرًا طَويلًا يُصَلِّي الفجرَ بوُضوءِ العِشاءِ. كان شديدًا في السُّنَّةِ، حين بلَغَه مَوتُ ابنِ المُعَلِّم فَقيهِ الشِّيعةِ، سجَدَ لله شُكرًا وجلَسَ للتَّهنئةِ، وقال: \"ما أبالي أيَّ وقتٍ مِتُّ بعد أن شاهَدْتُ مَوتَ ابنِ المُعَلِّم\". توفِّيَ عن مِئَة وعشر سنينَ."},{"id":1435,"title":"وفاة سلطان الدَّولة أبي شجاع بن بهاء الدَّولة البويهي .","date":["العام الهجري :415","الشهر القمري : شوال","العام الميلادي :1025"],"text":"هو مَلِكُ العِراقِ وفارس، سُلطانُ الدَّولة، أبو شُجاع، فناخِسرو بنُ بهاءِ الدَّولةِ خُرَّة فيروز بن عَضُد الدَّولة أبي شُجاع بن رُكنِ الدَّولة حسن بن بُوَيه الديلميُّ الشِّيعيُّ. وَلِيَ إمرةَ واسط لأبيه وبرَعَ في الأدبِ والأخبار والعربيَّة، وأكَبَّ على اللَّهوِ والخَلاعةِ. تملَّك بعد أبيه سنة 403، وهو صبيٌّ، فقُرئَ عَهدُ أبي شجاع من القادِرِ بالله، ولَقَّبه سُلطانَ الدَّولة, ثم أُحضِرَت الخِلَعُ وهي سبعٌ على العادة: عِمامةٌ سَوداءُ، وتاجٌ مُرصَّعٌ، وسَيفٌ، وسِواران، وطَوْق، وفَرَسان، ولِواءان عَقَدَهما القادِرُ بِيَدِه، وتلَفَّظَ بالحَلِفِ له بمَسمعٍ مِن الوزير أبي غالبٍ، وكبار الدَّولة, ووزَرَ لسُلطانِ الدَّولة فَخرُ الملك أبو غالب، واستخلَفَ ببغداد أخاه مُشرف الدَّولة أبا علي، وجعَلَ إليه إمارةَ الأتراك خاصَّةً، فحَسَّنوا له العِصيانَ، فاستولى مُشَرف الدَّولة على بغداد وواسط، وترَدَّد الأتراكُ إلى الديوان، فأمَرَ بقَطعِ الخُطبة لأخيه سُلطان الدَّولة، وأن يُخطَبَ له. ثمَّ تناقَضَت أمورٌ على سلطان الدَّولة، فكان يواصِلُ الشُّربَ حتى فسَدَ خُلُقُه، وطلب طبيبًا لفَصدِه، ففَصَده، ونَفذ قَضاءُ الله فيه، فمات بشيراز في شوال سنة 415 وله ثلاث وعشرون سنة، وكانت مُدَّة ملكه اثنتي عشرةَ سنة وأشهرًا, ولَمَّا مات، نَهَبَت الديلمُ ما قَدَروا عليه، وأشار عليهم الأوحَدُ بابنِه أبي كاليجار، فخُطِبَ له بخوزستان."},{"id":1436,"title":"وفاة القاضي المعتزلي عبد الجبار .","date":["العام الهجري :415","الشهر القمري : ذي القعدة","العام الميلادي :1025"],"text":"القاضي أبو الحَسَنِ عبدُ الجَبَّار بنُ أحمدَ بنِ عبدِ الجَبَّار الهمذانيُّ شَيخُ المُعتَزِلة في عَصرِه، وَلِيَ القَضاءَ في الريِّ، وعُرِفَ بقاضي القُضاة، صاحِبُ التصانيفِ، مِن كبارِ فُقَهاءِ الشَّافعيَّة. كان مُنافِحًا عن المُعتَزِلة، وألَّفَ الكثيرَ في نُصرةِ مَذهَبِهم، مثل: كتاب التوحيد، والعدل، وله دلائلُ النبوة، والأمالي، وتنزيه القرآن، توفِّيَ في الرَّيِّ وقد ناهز التسعينَ عامًا."},{"id":1437,"title":"الظاهر الفاطمي ينفي علماء المالكية وينشر مذهب الرافضة .","date":["العام الهجري :416","العام الميلادي :1025"],"text":"أمَرَ الظَّاهِرُ بنُ الحاكِمِ العُبَيديُّ حاكِمُ مِصرَ بنَفيِ مَن وُجِدَ مِن الفُقَهاءِ المالكيَّة وغيرِهم. وأمَرَ الدُّعاةَ أن يُحفِّظوا النَّاسَ كِتابَ دعائِمِ الإسلامِ لابنِ بابويهِ القُمِّي الرَّافضي، وكتاب الوزير يعقوبَ بنِ كلس في الفقهِ على مذهَبِ آلِ البَيتِ، وفرَضَ الظَّاهِرُ لِمَن يحفَظُ ذلك مالًا، وجلسَ الدُّعاةُ بالجامِعِ للمُناظرة."},{"id":1438,"title":"بداية هجوم الروم على جزيرة صقلية لأخذها من المسلمين .","date":["العام الهجري :416","العام الميلادي :1025"],"text":"خرج الرُّومُ إلى جَزيرةِ صقليَّةَ في جمعٍ كثير، ومَلَكوا ما كان للمُسلمين في جزيرة قلورية، وهي مجاوِرةٌ لجزيرةِ صقليَّة، وشرعوا في بناءِ المساكِنِ يَنتَظِرونَ وُصولَ مراكِبِهم وجُموعِهم مع ابنِ أخت الملك، فبلغ ذلك المُعِزَّ بنَ باديس، فجهَّزَ أسطولًا كبيرًا أربعمِئَة قطعةٍ، وحَشَد فيها، وجمع خلقًا كثيرًا، وتطَوَّعَ جَمعٌ كثير بالجهاد؛ رغبةً في الأجرِ، فسار الأسطولُ حتى قَرُبَ مِن جزيرة قوصرة، وهي قَريبةٌ مِن بَرِّ إفْريقيَّة، فخَرَجَت عليهم ريحٌ شديدة، ونَوءٌ عظيمٌ، فغَرِقَ أكثَرُهم، ولم ينجُ إلا اليَسيرُ."},{"id":1439,"title":"وفاة مشرف الدَّولة بن بويه ونهب بغداد .","date":["العام الهجري :416","الشهر القمري : ربيع الأول","العام الميلادي :1025"],"text":"هو المَلِك مُشرف الدَّولة أبو عليٍّ بنُ بهاءِ الدَّولة بنِ عَضُدِ الدَّولةِ بنِ بُوَيهِ الديلميُّ الشِّيعيُّ. كان فيه عَدلٌ في الجُملةِ. وكان له العِراقُ في وقتٍ وشيراز وكرمان، ولأخيه سُلطانِ الدَّولةِ صاحِبِ فارِسَ بُخارى ثمَّ اصطلحا. وتمَلَّكَ بعد مُشرف الدَّولة أخوه جلالُ الدَّولة ببغداد. توفِّيَ مُشرف الدَّولة بمرضٍ حادٍّ، وله أربعٌ وعشرون سنة، وكان مُلكُه خَمسَ سِنينَ وخمسة وعشرين يومًا، واستقَرَّ الأمرُ على توليةِ أخيه جلالِ الدَّولة أبي طاهرٍ، فخُطِبَ له على المنابِرِ، وهو بالبصرة. فخُلِعَ على شَرفِ الملك أبي سعدِ بنِ ماكولا وزيره، ولَقَّبَه علم الدين سعد الدَّولة، أمين الملة، شرف الملك، ثمَّ إنَّ الجُندَ عَدَلوا إلى الملك أبي كاليجار بن سلطان الدَّولةِ بنِ بهاء الدَّولة ونوَّهوا باسمه، وكان وليَّ عهدِ أبيه سلطانِ الدَّولة الذي استخلَفَه بهاءُ الدَّولة عليهم، فخُطِبَ لهذا ببغداد، وكوتِبَ جَلالُ الدَّولة بذلك، فأُصعِدَ مِن واسط."},{"id":1440,"title":"كسر صنم الهنود الأعظم سومنات في الهند .","date":["العام الهجري :416","الشهر القمري : شعبان","العام الميلادي :1025"],"text":"كان لأهلِ الهندِ صَنمٌ مَعروفٌ بسومنات يُعَظِّمونَه أشَدَّ التَّعظيمِ، ويقَدِّمونَ له مِن القَرابينِ ما لا يُقَدَّمُ لصَنَمٍ غَيرِه، وكان يمينُ الدَّولة كلَّما فتَحَ مِن الهندِ فتحًا، وكسَرَ صنمًا يقولُ الهنود: إنَّ هذه الأصنامَ قد سَخِطَ عليها سومنات، ولو أنَّه راضٍ عنها لأهلَكَ مَن تقَصَّدَها بسُوءٍ، وقد كانوا يَفِدونَ إليه مِن كُلِّ فَجٍّ عَميقٍ، كما يفِدُ النَّاسُ إلى الكعبةِ بالبيتِ الحَرامِ، ويُنفِقونَ عنده النَّفَقاتِ والأموالَ الكثيرةَ التي لا تُوصَفُ ولا تُعَدُّ، وكان عليه من الأوقافِ عَشرةُ آلافِ قَريةٍ ومدينةٍ مشهورةٍ، وقد امتلأت خزائِنُه أموالًا، وعنده ألفُ رجُلٍ يَخدُمونَه، ومئاتُ الرِّجالِ يَحلِقونَ رُؤوسَ حَجيجِه، وكان عنده من المجاورينَ ألوفٌ يأكُلونَ مِن أوقافِه، فلَمَّا بلغ خبَرُ هذا الصَّنمِ وعُبَّادِه السُّلطانَ يَمينَ الدَّولةِ محمودَ الغَزنويَّ، عَزَمَ على غَزوِه وإهلاكِه, فاستخار اللهَ لِما بلَغَه مِن كَثرةِ الهُنودِ في طريقِه، والمفاوِز المُهلِكة، والأرض الخَطِرة، في تجَشُّم ذلك في جَيشِه، وعليه أن يقطَعَ تلك الأهوالَ، فانتَدَب معه ثلاثون ألفًا مِن المُقاتِلة مِمَّن اختارهم لذلك سِوى المتطَوِّعةِ، فسَلَّمَهم اللهُ حتى انتَهَوا إلى بلدِ هذا الوَثَن، ونزلوا بساحةِ عُبَّادِه، فإذا هو بمكانٍ بقَدرِ المدينةِ العظيمة، فما أسرَعَ أن مَلَكَه، وقتَلَ مِن أهله خمسينَ ألفًا وقلَعَ الوَثَن وأوقد تحته النَّارَ. قال ابنُ كثير: \"ذكر غيرُ واحدٍ أنَّ الهنودَ بَذَلوا للسُّلطانِ مَحمود أموالًا جزيلةً لِيَترُكَ لهم هذا الصَّنمَ الأعظَمَ، فأشار من أشار مِن الأمراءِ على السلطان محمود بأخذِ الأموالِ وإبقاءِ هذا الصَّنَم لهم، فقال: حتى أستخيرَ اللهَ عَزَّ وجَلَّ، فلمَّا أصبَحَ قال: إنِّي فكَّرتُ في الأمرِ الذي ذُكِرَ، فرأيتُ أنَّه إذا نودِيتُ يومَ القيامةِ أين محمود الذي كسَرَ الصَّنَم، أحَبُّ إليَّ مَن أن يقالَ: الذي ترَكَ الصَّنَمَ لأجْلِ ما ينالُه من الدُّنيا! ثمَّ عَزَم رَحِمَه اللهُ فكَسَرَه، فوجد عليه وفيه مِن الجواهِرِ واللآلئِ والذَّهَبِ والجواهِرِ النَّفيسة ما يُنَيِّفُ على ما بَذَلوه له بأضعافٍ مُضاعَفةٍ، ونرجو مِن اللهِ له في الآخرةِ الثَّوابَ الجَزيلَ الذي مِثقالُ دانقٍ منه خيرٌ مِن الدنيا وما فيها، مع ما حصَلَ له من الثَّناءِ الجَميلِ الدُّنيوي، فرَحِمَه اللهُ وأكرَمَ مَثواه\", ثمَّ رحَلَ يَمينُ الدَّولة عائدًا إلى غزنة، فوصَلَها عاشِرَ صَفَر سنة 417."},{"id":1441,"title":"تسلط الأتراك والعيارين ببغداد .","date":["العام الهجري :417","العام الميلادي :1026"],"text":"كَثُرَ تسَلُّطُ الأتراك الجُندِ ببغداد، فأكثَروا مُصادراتِ النَّاسِ، وأخذوا الأموالَ، حتى إنَّهم فَرَضوا على الكَرخِ خاصَّةً مِئَة ألف دينار، وعَظُم الخَطبُ، وزاد الشَّرُّ، وأُحرِقَت المنازِلُ والدُّروبُ والأسواقُ، ودخل في الطَّمَعِ العامَّةُ والعيَّارون- والعَيَّارون: لصوصٌ يَمتَهِنونَ النَّهبَ والدعارةَ -، فكانوا يدخُلونَ على الرَّجُلِ فيُطالِبونَه بذخائِرِه، كما يفعَلُ السُّلطانُ بمن يُصادِرُه، فعَمِلَ النَّاسُ الأبوابَ على الدروب، فلم تغْنِ شيئًا، ووقَعَت الحربُ بين الجُندِ والعامَّةِ، فظَفِرَ الجُندُ التُّركُ، ونَهَبوا الكرخَ وغَيرَه، فأُخِذَ منه مالٌ جليلٌ، وهلك أهلُ السِّترِ والخَيرِ، فلمَّا رأى القُوَّادُ وعُقَلاءُ الجُندِ أنَّ المَلِكَ أبا كاليجار لا يَصِلُ إليهم، وأنَّ البلادَ قد خَرِبَت، وطَمِعَ فيهم المُجاوِرونَ مِن العَرَب والأكراد، راسَلوا جلالَ الدَّولة في الحضورِ إلى بغداد، فحَضَر في السَّنةِ التالية."},{"id":1442,"title":"الصلح بإفريقية بين كتامة وزناتة وبين المعز بن باديس الصنهاجي .","date":["العام الهجري :417","العام الميلادي :1026"],"text":"ورَدَت رُسُلُ زناتة وكتامة إلى المعِزِّ بنِ باديس الصِّنهاجيِّ، صاحِبِ إفريقيَّةَ، يَطلُبونَ منه الصُّلحَ، وأن يَقبَلَ منهم الطَّاعةَ والدُّخولَ تحت حُكمِه، وشَرَطوا أنَّهم يَحفَظونَ الطَّريقَ، وأعطَوا على ذلك عُهودَهم ومواثيقَهم، فأجابهم إلى ما سألوا، وجاءت مَشيخةُ زناتة وكتامة إليه، فقَبِلَهم وأنزلهم ووصَلَهم، وبذَلَ لهم أموالًا جليلةً."},{"id":1443,"title":"الهدنة بين الظاهر العبيدي الفاطمي حاكم مصر والروم .","date":["العام الهجري :418","العام الميلادي :1027"],"text":"وقَعَت الهُدنةُ بينَ مَلِك الروم قسطنطين الثَّامِن، والظَّاهِرِ العُبَيديِّ الفاطميِّ حاكِمِ مصرَ عن ديارِ مِصرَ والشام، وكُتِبَ بينهما كِتابٌ، وتفَرَّدَت الخُطبةُ للظاهِرِ ببلاد الرومِ، وفُتِحَ الجامِعُ الذي بقُسطنطينيَّة، وعُمِلَ له الحُصُر والقناديلُ، وأقيم به مؤذِّنٌ، وعند ذلك أذِنَ الظَّاهِرُ في فتحِ كَنيسةِ القمامة التي بالقُدسِ، وسَمَحَ لهم بإعادةِ بنائها، فحَمَلَ إليها ملوكُ النصارى الأموالَ والآلاتِ، وأعادوها، وارتَدَّ إلى دينِ النَّصرانيَّةِ كثيرٌ ممَّن أسلَمَ كَرْهًا في أيَّامٍ الحاكمِ العُبَيديِّ، كما سَمِحَ لهم بإعادةِ بناءِ الكنائِسِ التي هُدِّمَت في أيَّامِ الحاكِمِ، إلَّا التي تحوَّلَت إلى مساجِدَ، كما تضَمَّنَت المُعاهَدةُ إطلاقَ أسرى والمَنْع من إعانةِ حَسَّان بن مفرج الجَرَّاح صاحِبِ الرَّملة الذي خرج على الظَّاهِرِ الفاطميِّ."},{"id":1444,"title":"وفاة أبي إسحاق الإسفراييني .","date":["العام الهجري :418","العام الميلادي :1027"],"text":"هو الإمامُ العَلَّامةُ الأستاذُ، رُكنُ الدِّينِ، الفَقيهُ الشافعيُّ، الشيخُ أبو إسحاقَ، إبراهيمُ بنُ مُحَمَّد بنِ إبراهيم بنِ مَهران الإسفرايينيِّ, مِن أئمَّةِ الشَّافعيَّة, متكَلِّمٌ أصوليٌّ بارِعٌ، وأحَدُ الأئمَّةِ المُجتَهِدينَ في عَصرِه. صاحِبُ التَّصانيفِ الباهرةِ، والتَّعليقاتِ النَّافِعةِ في أصولِ الفِقهِ، لُقِّبَ برُكنِ الدِّينِ، وهو أوَّلُ مَن تلَقَّبَ مِن الفُقَهاءِ على طريقةِ ألقابِ الحُكَّام، درَّسَ في نَيسابورَ واشتهَرَ فيها, وبُنِيَت له فيها مدرسةٌ مَشهورةٌ، حيث درَسَ عليه عامَّةُ شُيوخِها، له مُصَنَّفاتٌ عَديدةٌ، منها: الجامِعُ في أصولِ الدِّينِ، والرَّدُّ على المُلحِدينَ، ورسالةٌ في أصولِ الفِقهِ، له مناظَراتٌ معروفةٌ مع المعتزلةِ، توفِّيَ يومَ عاشوراءَ بنَيسابورَ، ونُقِلَ إلى إسْفرايين ودُفِنَ بها."},{"id":1445,"title":"تنصيب هشام الثالث آخر الأمراء الأمويين في الأندلس .","date":["العام الهجري :418","الشهر القمري : ربيع الأول","العام الميلادي :1027"],"text":"لَمَّا انقَطَعَت دعوةُ يحيى بنِ عليٍّ الفاطميِّ عن قُرطُبةَ، أجمَعَ رأيُ أهلِ قُرطبةَ على ردِّ الأمرِ إلى بني أمَيَّة، وكان عَميدُهم في ذلك والذي تولَّى مُعظَمَه وسعى في تمامِه الوَزير أبا الحَزمِ جهور بنَ مُحمَّد بن جهور بن عبيد الله بن محمَّد بن الغمر بن يحيى بن عبد الغافر بن أبي عبدة، وقد كان ذهَبَ كُلُّ مَن يُنافِسُ في الرِّياسةِ في الفِتنةِ بقُرطُبةَ، فراسَلَ جهور من كان معه على رأيِه مِن أهلِ الثُّغورِ والمتَغَلِّبينَ هنالك على الأمورِ وداخلهم في هذا الأمرِ، فاتَّفَقوا بعد مُدَّةٍ طويلةٍ على تقديمِ أبي بكر هِشامِ بنِ مُحَمَّد بنِ عبد الملك بنِ عبدِ الرَّحمنِ الناصر، وهو أخو المرتضى، وكان هِشامٌ هذا مقيمًا بحِصنٍ في الثُّغورِ يُدعى ألبنت تحتَ إمرةِ أبي عبدِ اللهِ مُحَمَّد بن عبد الله بن قاسم القائِد المتغَلِّب بها، فبايعوه وتلَقَّبَ بالمعتَدِّ بالله."},{"id":1446,"title":"وفاة الإمام اللالكائي .","date":["العام الهجري :418","الشهر القمري : رمضان","العام الميلادي :1027"],"text":"هو الإمامُ الحافِظُ المُجَوِّد، المُفتي: أبو القاسِمِ هِبةُ اللهِ بنُ الحَسَنِ بنِ مَنصورٍ، الطَّبريُّ الرازيُّ، الشَّافعيُّ اللَّالَكائي، مفيدُ بغدادَ في وقته. وهو طبَريُّ الأصل، أحدُ تلامذةِ الشيخِ أبي حامدٍ الإسْفِرايينيِّ، كان يَفهَمُ ويَحفَظُ، وعُنِيَ بالحديثِ فصَنَّفَ فيه أشياءَ كثيرةً، ولكِنْ عاجَلَتْه المنيَّةُ قبل أن تشتَهِرَ كُتُبُه، وله كتابٌ في العقيدةِ على مَنهَجِ السَّلَفِ، وهو كتابُ: شَرح أصولِ اعتقادِ أهلِ السُّنَّة والجماعة، توفِّي بالدِّينَوَر."},{"id":1447,"title":"شغب الجند الأتراك ببغداد على جلال الدَّولة .","date":["العام الهجري :419","العام الميلادي :1028"],"text":"ثار الجُندُ الأتراكُ ببغداد على جَلالِ الدَّولة البُويهيِّ الشِّيعيِّ، وشَغَّبوا، وطالبوا الوزيرَ أبا علي بنَ ماكولا بما لهم من العلوفةِ والأدرار، ونَهَبوا دارَه ودُورَ كُتَّاب المَلِك وحواشيه، حتى المُغَنِّينَ والمُخَنَّثين، ونَهَبوا صياغاتٍ أخرَجَها جلالُ الدَّولة لتُضرَبَ دنانيرَ ودراهِمَ، وتُفَرَّق فيهم، وحَصَروا جلالَ الدَّولة في داره، ومَنَعوه الطَّعامَ والماءَ، حتى شَرِبَ أهلُه ماءَ البئر، وأكَلوا ثمرةَ البُستانِ، فسألهم أن يُمَكِّنوه من الانحدارِ، فاستأجروا له ولأهلِه وأثقالِه سُفُنًا، فجَعَل بين الدارِ والسُّفُن سُرادقًا لتجتازَ حَرَمُه فيه، لئلَّا يراهم العامَّةُ والأجنادُ، فقصَدَ بعضُ الأتراكِ السُّرادِقَ، فظَنَّ جلالُ الدَّولة أنَّهم يريدونَ الحَرَم، فصاح بهم يقولُ لهم: بلَغَ أمرُكم إلى الحَرَمِ! وتقَدَّم إليهم فصاح صِغارُ الغِلمانِ والعامَّة: جلالُ الدَّولة يا منصورُ، ونزل أحدُهم عن فَرَسِه وأركَبَه إيَّاه، وقَبَّلوا الأرضَ بين يَدَيه، فلمَّا رأى قُوَّادُ الأتراك ذلك هربوا إلى خيامِهم بالرَّملة، وخافوا على نُفوسِهم، وكان في الخِزانةِ سِلاحٌ كثيرٌ، فأعطاه جلالُ الدَّولة أصاغِرَ الغِلمانِ وجعَلَهم عنده، ثمَّ أرسل إلى الخليفةِ ليُصلِحَ الأمرَ مع أولئك القُوَّاد، فأرسَلَ إليهم الخليفةُ القادِرُ بالله، فأصلح بينهم وبين جلالِ الدَّولة، وحَلَفوا، فقَبَّلوا الأرضَ بينَ يَدَيه، ورَجَعوا إلى منازِلِهم، فلم يمضِ غيرُ أيَّامٍ حتى عادوا إلى الشَّغبِ، فباع جلالُ الدَّولةِ فُرُشَه وثيابَه وخِيَمَه وفَرَّقَ ثَمَنَه فيهم حتى سَكَنوا."},{"id":1448,"title":"الاختلاف بين الديلم والأتراك بالبصرة .","date":["العام الهجري :419","العام الميلادي :1028"],"text":"وَلِيَ النَّفيسُ أبو الفتحِ مُحمَّدُ بنُ أردشير البَصرةَ، استعمَلَه عليها جلالُ الدَّولة البُويهيُّ، فلمَّا وَصَل إلى المشان مُنحَدِرًا إليها، وقع بينه وبين الديلمِ الذين بالمشان وقعةٌ، فاستظهر عليهم وقَتَل منهم، وكانت الفِتَنُ بالبصرةِ بين الأتراك والديلم، وبها المَلِكُ العزيزُ أبو منصور بن جلال الدَّولة، فقَوِيَ الأتراكُ بها، فأخرجوا الدَّيلمَ، فمَضَوا إلى الأبلَّة، وصاروا مع بختيار بنِ عليٍّ، فسار إليهم المَلِكُ العَزيزُ بالأبلَّة ليُعيدَهم ويُصلِحَ بينهم وبين الأتراكِ، فكاشَفوه وحَمَلوا عليه، ونادَوا بشِعارِ أبي كاليجار، فعاد مُنهَزِمًا في الماءِ إلى البَصرةِ، ونَهَب بختيار نَهرَ الديرِ والأبلَّة وغيرهما من السَّوادِ، وأعانه الدَّيلمُ، ونَهَب الأتراك أيضًا، وارتكبوا المحظورَ، ونَهَبوا دارَ بنتِ الأوحَدِ بنِ مُكرم زوجةِ جلالِ الدَّولة."},{"id":1449,"title":"وفاة قوام الدَّولة أبو الفوارس البويهي الشيعي صاحب كرمان .","date":["العام الهجري :419","الشهر القمري : ذي القعدة","العام الميلادي :1028"],"text":"هو قوام الدَّولة أبو الفوارِسِ بنُ بَهاءِ الدَّولة البُويهيُّ الدَّيلميُّ الشِّيعيُّ، صاحِبُ كرمان. في سنة410 قُرِئَ عَهدُ أبي الفوارس ولُقِّبَ قوام الدَّولة، وخُلِعَ عليه خِلَعًا حُمِلَت إليه بوِلايةِ كرمان. كان أبو الفوارِسِ قد تجَهَّزَ لِقَصدِ بلاد فارس، وجَمَع عسكرًا كثيرًا، فأدرَكَه أجَلُه، فلمَّا توفِّيَ نادى أصحابُه بشعارِ ابنِ أخيه المَلِك أبي كاليجار، وأرسلوا إليه يَطلُبونَه إليهم، فسار مُجِدًّا، ومَلَك البلادَ بغَيرِ حَربٍ ولا قتالٍ، وأمِنَ النَّاسُ معه، وكانوا يكرهونَ عمَّه أبا الفوارِسِ لظُلمِه وسُوءِ سِيرتِه، وكان إذا شَرِبَ ضَرَبَ أصحابَه، وضَرَب وزيرَه يومًا مِئَتي مقرعةٍ، وحَلَّفَه بالطَّلاقِ أنَّه لا يتأوَّهُ، ولا يخبِرُ بذلك أحدًا، فقيلَ إنَّهم سَمُّوه فمات."},{"id":1450,"title":"كتاب محمود بن سبكتكين بما فعله بالباطنية وغلاة الرافضة .","date":["العام الهجري :420","العام الميلادي :1029"],"text":"وردَ إلى الخليفةِ القادِرِ بالله كِتابٌ مِن الأميرِ يَمينِ الدَّولة محمود بنِ سبكتكين الغزنوي أنَّه أحَلَّ بطائفةٍ مِن أهلِ الرَّيِّ مِن الباطنيَّة وغُلاة الرَّوافِضِ قَتلًا ذريعًا، وصَلبًا شَنيعًا، وأنَّه انتَهَب أموالَ رَئيسِهم رستُم بن علي الديلمي، فحصَلَ منها ما يُقارِبُ ألف ألف دينار، وقد كان في حيازتِه نحوٌ مِن خمسين امرأةً حُرَّة، وقد وَلَدْنَ له ثلاثًا وثلاثين ولدًا بين ذكَرٍ وأنثى، وكانوا يَرَونَ إباحةَ ذلك. وقد جاء في الكِتابِ: \"إنَّ كِتابَ العَبدِ صَدَر مِن مُعسكَرِه بظاهِرِ الرَّيِّ غُرَّةَ جُمادى الآخرة سنة 420، وقد أزال اللهُ عن هذه البُقعةِ أيديَ الظَّلَمةِ وطَهَّرَها من دعوةِ الباطنيَّةِ الكَفَرة والمُبتَدِعة الفَجَرة، وقد كانت مدينةُ الرَّيِّ مَخصوصةً بالْتِجائِهم إليها وإعلانِهم بالدُّعاءِ إلى كُفرِهم، فيها يَختَلِطونَ بالمُعتَزِلة المُبتَدِعة، والغاليةِ مِن الرَّوافِضِ المُخالفةِ لِكِتابِ اللهِ والسُّنَّة، يتجاهرون بشَتمِ الصَّحابةِ ويُسِرُّونَ اعتقادَ الكُفرِ ومَذهَب الإباحة، وكان زعيمُهم رُستُم بنُ عليٍّ الدَّيلميُّ، فعطَفَ العَبدُ عِنانَه بالعساكرِ فطَلَع بجُرجان وتوقَّفَ بها إلى انصرافِ الشِّتاءِ، ثمَّ دَلَف منها إلى دامغان، ووجَّه عَلِيًّا الحاجب في مقَدِّمة العسكَرِ إلى الري، فبرز رُستُم بن علي على حُكمِ الاستسلامِ والاضطرارِ، فقُبِضَ عليه وعلى أعيانِ الباطنيَّةِ مِن قُوَّادِه, ثمَّ خرج الدَّيالِمة مُعتَرِفينَ بذُنوبِهم شاهِدينَ بالكُفرِ والرَّفضِ على نُفوسِهم، فرُجِعَ إلى الفُقَهاءِ في تعَرُّفِ أحوالهم، فاتَّفَقوا على أنَّهم خارِجونَ عن الطَّاعةِ وداخِلونَ في أهل الفَسادِ، مُستَمِرُّونَ على العنادِ، فيَجِبُ عليهم القَتلُ والقَطعُ والنَّفيُ على مراتِبِ جِناياتِهم، وذَكَر هؤلاء الفُقَهاءُ أنَّ أكثَرَ القَومِ لا يُقيمونَ الصَّلاةَ، ولا يُؤتُونَ الزَّكاةَ، ولا يَعرِفونَ شَرائِطَ الإسلامِ، ولا يُمَيِّزونَ بين الحلالِ والحرامِ، بل يجاهِرونَ بالقَذفِ وشَتمِ الصَّحابةِ، ويعتَقِدونَ ذلك ديانةً، والأمثَلُ منهم يتقَلَّدُ مذهَبَ الاعتزالِ، والباطِنيَّةُ منهم لا يُؤمِنونَ باللَّهِ عَزَّ وجَلَّ وملائكتِه وكُتُبِه ورُسُلِه واليومِ الآخر، وأنَّهم يَعُدُّونَ جَميعَ المِلَلِ مَخاريقَ الحُكَماءِ، ويَعتَقِدونَ مَذهَبَ المَزدكيَّةِ: الإباحةَ في الأموالِ والفُروجِ والدِّماءِ، يَدَّعونَ الإسلامَ بإعلانِ الشَّهادةِ، ثمَّ يُجاهِرونَ بتَركِ الصَّلاةِ والزَّكاةِ، والصَّومِ والغُسلِ، وأكْلِ المَيتةِ، فقضى الانتصارُ لدينِ اللهِ تعالى بتَميُّزِ هؤلاء الباطنيَّةِ عنهم، فصُلِبوا على شارِعِ مدينةٍ طالَما تمَلَّكوها غَصبًا، واقتسموا أموالها نهبًا، وقد كانوا بذلوا أموالًا جَمَّةً يَفتَدونَ بها نُفوسَهم، وضَمَّ إليهم أعيانَ المُعتَزِلة والغُلاة مِن الرَّوافِضِ؛ ليتخَلَّصَ النَّاسُ من فِتنَتِهم، ثمَّ نَظَرَ فيما اختَزَنَه رُستم بن علي فعَثَر على أموالٍ طائلةٍ وأثاثٍ عظيمٍ. ومن الكُتُب خمسون حِملًا ما خلا كتُبَ المُعتَزِلة والفَلاسِفة والرَّوافِض، فأُحرِقَت تحت جُذوعِ المَصلوبين؛ إذ كانت أصولَ البِدَع، فخَلَت هذه البُقعةُ مِن دُعاةِ الباطنيَّةِ وأعيانِ المُعتَزِلة وغُلاةِ الرَّوافِضِ، وانتَصَرت السُّنَّة، فطالَعَ العبدُ بحقيقةِ ما يَسَّرَه اللهُ تعالى لأنصارِ الدَّولةِ القاهرةِ\"."},{"id":1451,"title":"وقعة الأقحوانة بين الظاهر (الفاطمي) وبين حسان بن الجراح .","date":["العام الهجري :420","العام الميلادي :1029"],"text":"كان حَسَّانُ بنُ الجَرَّاح قد خرج على الحاكِمِ، وأمَدَّه الرُّومُ، ثمَّ إنَّ الظاهِرَ لَمَّا عقَدَ المُعاهَدةَ مع الرُّومِ كان منها عدَمُ إمدادِ حَسَّان، فلمَّا كانت هذه السَّنَةُ أرسل الظَّاهِرُ الفاطميُّ جَيشًا بقيادةِ أنوشتكين التركي لَمَّا بلَغَه أنَّ حَسَّان وسِنان بن عليان أميرَ بني كلابٍ وصالِحَ بنَ مرداس أميرَ حَلَب اتَّفَقوا على إخراجِ الفاطميِّينَ مِن الشَّامِ واقتسامِها بينهم، فكانت الحَربُ بين جيشِ الفاطميِّينَ وبينهم في موقِعٍ يُدعى الأُقحُوانة عند طبَريَّة، وكان من نتائِجِ الحَربِ مَقتَلُ صالحِ بنِ مِرداس وهُروب حسَّان ولجوئِه إلى الرُّوم."},{"id":1452,"title":"الخليفة العباسي القادر يقرر مذهب اعتقاد أهل السنة والجماعة .","date":["العام الهجري :420","الشهر القمري : رجب","العام الميلادي :1029"],"text":"في الثَّامِنَ عَشَر مِن رَجَب جُمِعَ القُضاةُ والعُلَماءُ في دارِ الخلافة، وقُرِئَ عليهم كتابٌ كان القادِرُ بالله قد جمع فيه مواعِظَ وتفاصيلَ مذاهِبِ أهلِ البَصرةِ، وفيه الرَّدُّ على أهلِ البِدَع، وتَفسيقُ مَن قال بخَلقِ القُرآنِ، وصِفةُ ما وقع بين بِشرٍ المِريسيِّ وعبد العزيز بن يحيى الكِناني من المناظرة، ثمَّ خُتِمَ القَولُ بالمواعِظِ والقَولِ بالمعروفِ، والنَّهيِ عن المُنكَرِ، وأخَذَ خُطوطَ الحاضرينَ بالمُوافقةِ على ما سَمِعوه، وفي يومِ الاثنينِ غُرَّةَ ذي القَعدةِ جُمِعوا أيضًا كُلُّهم، وقُرِئَ عليهم كتابٌ آخَرُ طويلٌ يتضَمَّنُ بيانَ السُّنَّة، والرَّدَّ على أهلِ البِدَعِ، ومُناظرةَ بِشرٍ المِريسي والكناني أيضًا، والأمر بالمعروفِ والنَّهي عن المنكر، وفَضْل الصحابة، وذِكْر فضائلِ أبي بكرٍ الصِّديقِ وعُمَرَ بنِ الخطَّابِ رَضِيَ الله عنهما، ولم يَفرُغوا منه إلَّا بعد العَتَمةِ، وأُخِذَت خُطوطُهم بموافقةِ ما سَمِعوه، وعَزَلَ خُطَباءَ الشِّيعةِ، وولَّى خُطَباءَ السُّنَّة، وجَرَت فِتنةٌ بمَسجدِ براثا، وضَرَبَ الشِّيعةُ الخطيبَ السُّنِّيَّ بالآجُرِّ، حتى كَسَروا أنفَه وخَلَعوا كَتِفَه، فانتصر له الخليفةُ، وأهانَ الشِّيعةَ وأذَلَّهم، حتى جاؤُوا يَعتَذِرونَ ممَّا صنعوا، وأنَّ ذلك إنَّما تعاطاه السُّفَهاءُ منهم."},{"id":1453,"title":"سير قسطنطين ملك الروم إلى الشام وهلاك معظم جيشه بالعطش .","date":["العام الهجري :421","العام الميلادي :1030"],"text":"خرج مَلِكُ الرُّومِ مِن القُسطنطينيَّةِ في ثلاثمِئَة ألفِ مقاتلٍ إلى الشام، فلم يَزَلْ بعساكِرِه حتى بلغوا قريبَ حَلَب، وصاحِبُها شبل الدَّولةِ نَصرُ بنُ صالحِ بنِ مرداس، فنزلوا على يومٍ منها، فلَحِقَهم عطَشٌ شَديدٌ، وكان الزَّمانُ صَيفًا، وكان أصحابُه مختَلِفينَ عليه، فمِنهم من يحسُدُه، ومنهم من يَكرَهُه، وممَّن كان معه ابنُ الدوقس، ومِن أكابِرِهم، وكان يريدُ هلاكَ المَلِك لِيَملِكَ بعده، فقال المَلِكُ: الرأيُ أن نقيمَ حتى تجيءَ الأمطارُ وتَكثُرَ المياه. فقَبَّحَ ابنُ الدوقس هذا الرأيَ، وأشار بالإسراعِ قَصدًا لشَرٍّ يتطَرَّقُ إليه، ولتدبيرٍ كان قد دبَّرَه عليه. فسار، ففارَقَه ابنُ الدوقس وابنُ لؤلؤٍ في عشرة آلافِ فارسٍ، وسلكوا طريقًا آخَرَ، فخَلا بالمَلِك بعضُ أصحابِه وأعلَمَه أنَّ ابنَ الدَّوقس وابنَ لؤلؤ قد حالفا أربعينَ رَجُلًا، هو أحدُهم، على الفَتكِ به، واستشعَرَ مِن ذلك وخاف، ورحَلَ مِن يومِه راجعًا، ولَحِقَه ابنُ الدوقس، وسأله عن السَّبَبِ الذي أوجَبَ عَودَه، فقال له: قد اجتمَعَت علينا العَرَبُ وقَرُبوا منا، وقَبَضَ في الحالِ على ابنِ الدَّوقسِ وابنِ لؤلؤ وجماعةٍ معهما، فاضطرب النَّاسُ واختلفوا، ورحَلَ المَلِكُ، وتَبِعَهم العَرَبُ وأهلُ السوادِ حتى الأرمن يقتُلونَ ويَنهَبونَ، وأخذوا من المَلِكِ أربعَمِئَة بغلٍ مُحَمَّلة مالًا وثيابًا، وهَلَك كثيرٌ مِن الرومِ عَطَشًا، ونجا المَلِكُ وحده، ولم يَسلَمْ معه من أموالِه وخزائِنِه شيءٌ البتَّةَ، {وَكَفَى اللَّهُ الْمُؤْمِنِينَ الْقِتَالَ وَكَانَ اللَّهُ قَوِيًّا عَزِيزًا}، وقيلَ في عودِه غيرُ ذلك، وهو أنَّ جَمعًا من العَرَبِ ليس بالكثيرِ عَبَرَ على عَسكَرِه، وظَنَّ الرُّومُ أنَّها كبسةٌ، فلم يَدرُوا ما يفعلونَ، حتى إنَّ مَلِكَهم لَبِسَ خُفًّا أسودَ، وعادةُ مُلوكِهم لُبسُ الخُفِّ الأحمَرِ، فتَرَكه ولَبِسَ الأسودَ لِيُعَمِّيَ خَبَرَه على مَن يريدُه، وانهزموا، وغَنِمَ المسلمونَ جميعَ ما كان معهم."},{"id":1454,"title":"وفاة يمين الدَّولة محمود بن سبكتكين الغزنوي وعهده إلى ابنه محمد  .","date":["العام الهجري :421","الشهر القمري : ربيع الآخر","العام الميلادي :1030"],"text":"هو يَمينُ الدَّولةِ، فاتِحُ الهِندِ: أبو القاسِمِ، المَلِكُ السُّلطانُ مَحمودُ بنُ سَيِّد الأمراءِ ناصِر الدَّولةِ سبكتكين، التُّركيُّ، صاحِبُ خُراسان والهِند. وُلِدَ في غزنة سنةَ 361. كان- رحمه الله- صادِقَ النِّيَّة في إعلاءِ الدِّينِ، مُظَفَّرًا كثيرَ الغَزوِ، وكان ذكيًّا بعيدَ الغَورِ، صائِبَ الرَّأيِ، وكان مَجلِسُه مَورِدَ العُلَماءِ. كان والِدُه أبو منصورٍ سبكتكين قد تولَّى إمرةَ غزنة بعد وفاةِ واليها ابنِ السكين, فتمكَّنَ فيها وعَظُمَ أمْرُه، ثمَّ أخَذَ يُغيرُ على أطرافِ الهِندِ، وافتتح قِلاعًا، وتَمَّت له ملاحِمُ مع الهنودِ، وافتَتَح ناحيةَ بُست، وكان سبكتكين ناصِرًا للسُّنَّة وقامِعًا للبِدعةِ, ولَمَّا مات سنة 387، تولَّى حُكم غزنةَ ابنُه محمود بعد نزاعٍ مع أخيه إسماعيلَ الذي كان والدُهما عَهِدَ له مِن بعده. حارب محمودٌ النوَّابَ السامانيِّينَ، وخافَتْه الملوكُ. وضَمَّ إقليمَ خُراسان، ونفَّذ إليه الخَليفةُ العباسيُّ القادِرُ بالله خِلَعَ السَّلْطنةِ، ولَقَّبَه يمينَ الدَّولة، وفَرَضَ على نفسِه كُلَّ سَنةٍ غَزوَ الهندِ، فافتتح بلادًا شاسعةً منها، وكسَّرَ أصنامَ الهندِ، وأعظَمُها عند الهُنودِ سومنات. كان السُّلطانُ محمود رَبعةً، فيه سِمَنٌ وشُقرةٌ، ولحيتُه مُستديرةٌ، غَليظَ الصَّوتِ، وفي عارِضَيه شَيبٌ, وكان مُكْرِمًا لأمرائِه وأصحابِه، وإذا نَقِمَ عاجَلَ، وكان لا يَفتُرُ ولا يكادُ يَقِرُّ. كان يعتَقِدُ في الخليفة العباسيِّ القادِرِ بالله، ويخضَعُ لجَلالِه، ويحمِلُ إليه قناطيرَ مِن الذَّهَب، وكان إلبًا على القرامِطةِ والإسماعيليَّةِ، والفلاسِفةِ المتكَلِّمةِ، وكان فيه شِدَّةُ وطأةٍ على الرعيَّة؛ لكِنْ كانوا في أمنٍ وإقامةِ سياسةٍ. من سلاطينِ ومُلوك الإسلامِ الذين كان لهم دَورٌ عَظيمٌ في نَشرِ السُّنَّةِ وقَمعِ البِدعةِ, قال ابنُ كثير: \"في سنة 408 استتاب القادِرُ باللهِ الخَليفةُ فُقَهاءَ المُعتَزِلة، فأظهروا الرُّجوعَ وتبَرَّؤوا من الاعتزالِ والرَّفضِ والمقالاتِ المُخالِفةِ للإسلامِ، وأمَرَ عُمَّالَه بالمِثلِ, فامتَثَلَ محمودُ بنُ سبكتكين أمْرَ أميرِ المؤمنين في ذلك, واستَنَّ بسُنَّتِه في أعمالِه التي استخلَفَه عليها من بلادِ خُراسانَ وغَيرِها في قَتلِ المُعتَزِلة والرَّافِضةِ والإسماعيليَّةِ والقَرامطة، والجَهميَّة والمُشَبِّهة، وصَلَبَهم وحَبَسَهم, ونفاهم وأمَرَ بلَعنِهم على المنابِرِ, وأبعَدَ جَميعَ طوائفِ أهلِ البِدَعِ، ونفاهم عن ديارِهم، وصار ذلك سُنَّةً في الإسلامِ\" قال شيخُ الإسلامِ ابنُ تيميَّة: \"لَمَّا كانت مملكةُ مَحمودِ بنِ سبكتكين من أحسَنِ ممالِكِ بني جِنسِه، كان الإسلامُ والسُّنَّة في مملكَتِه أعَزَّ؛ فإنَّه غزا المُشرِكينَ مِن أهلِ الِهندِ، ونشَرَ مِن العدلِ ما لم ينشُرْه مِثلُه، فكانت السُّنَّةُ في أيامِه ظاهِرةً، والبِدَعُ في أيَّامِه مَقموعةً\". قال ابنُ كثير: \"كان يمينُ الدَّولة يخطُبُ في سائِرِ ممالِكِه للخليفةِ القادر بالله، وكانت رسُلُ الفاطميِّينَ مِن مصر تَفِدُ إليه بالكُتُبِ والهدايا لأجلِ أن يكونَ مِن جِهَتِهم، فيحرِقُ بهم ويحرِقُ كتُبَهم وهداياهم، وفتَحَ في بلاد الكُفَّارِ مِن الهند فتوحاتٍ هائلةً، لم يتَّفِقْ لغَيرِه من الملوكِ، لا قَبلَه ولا بعده، وغَنِمَ منهم مغانمَ كثيرةً لا تَنحَصِرُ ولا تنضَبِطُ، مِن الذَّهَب والمجوهرات، والسَّبْي، وكسَرَ مِن أصنامِهم شيئًا كثيرًا، وأخذ مِن حِليَتِها, ومِن جملةِ ما بلغ تَحصيلُه مِن سومنات أعظَمِ أصنامِهم مِن حُلِيِّ الذَّهَبِ عشرون ألف ألف دينار، وكَسَرَ مَلِكَ الهِندِ الأكبَر الذي يُقالُ له صينال، وقهَرَ مَلِكَ التُّركِ الأعظَم الذي يقال له إيلك الخان، وأباد مُلْكَ السَّامانيَّة، الذين ملكوا العالَمَ في بلاد سمرقند وما حولها، وبنى على جيحون جسرًا عظيمًا أنفَقَ عليه ألفي ألف دينار، وهذا شيءٌ لم يتَّفِقْ لغيره، وكان في جيشِه أربعُمِئَة فيلٍ تُقاتِلُ معه، وهذا شيءٌ عظيمٌ وهائِلٌ، وكان مع هذا في غايةِ الدِّيانةِ والصِّيانةِ وكراهةِ المعاصي وأهلِها، لا يحِبُّ منها شيئًا، ولا يألَفُه، ولا أن يَسمَعَ بها، ولا يَجسرُ أحَدٌ أن يُظهِرَ مَعصيةً ولا خَمرًا في مملَكتِه، ولا غير ذلك، ولا يُحِبُّ الملاهيَ ولا أهلَها، وكان يحِبُّ العُلَماءَ والمُحَدِّثين ويُكرِمُهم ويُجالِسُهم، ويحِبُّ أهلَ الخيرِ والدِّينِ والصَّلاح، ويُحسِنُ إليهم، وكان حنفيًّا ثمَّ صار شافعيًّا على يدي أبي بكرٍ القَفَّال الصغيرِ على ما ذكره إمامُ الحَرَمينِ وغَيرُه\". ثمَّ إنَّه مَلَك سجستان سنة 393، بدخُولِ قُوَّادها وولاةِ أمورِها في طاعتِه مِن غَيرِ قِتالٍ, ولم يَزَلْ يفتَحُ بلادَ الهِندِ إلى أن انتهى إلى حيثُ لم تَبلُغْه في الإسلامِ رايةٌ، ولم تُتْلَ به سورةٌ قَطُّ ولا آية، فدحَضَ عنها أدناسَ الشِّركِ، وبنى بها مساجِدَ وجوامِعَ. توفِّيَ يمينُ الدَّولةِ أبو القاسِمِ محمودُ بنُ سبكتكين في ربيعٍ الآخِرِ، وقيل: في أحدَ عَشَر صَفَر، وكان مرضُه سوءَ مزاجٍ وإسهالًا، وبقي كذلك نحو سنتينِ، فلم يزَلْ كذلك حتى توفِّيَ قاعِدًا، فلمَّا حَضَره الموتُ أوصى بالمُلْك لابنِه مُحمَّد، وهو ببَلْخ، وكان أصغَرَ مِن مَسعود، إلَّا أنَّه كان مُعرِضًا عن مسعود؛ لأنَّ أمْرَه لم يكن عنده نافِذًا، وسعى بينهما أصحابُ الأغراضِ، فزادوا أباه نُفورًا عنه، فلَمَّا وصَّى بالمُلْكِ لولَدِه مُحَمَّد توفِّيَ، خُطِبَ لمحَمَّد من أقاصي الهندِ إلى نَيسابور، وكان لَقَبُه جلالَ الدَّولةِ، وأرسَلَ إليه أعيانُ دَولةِ أبيه يُخبِرونَه بموت أبيه ووصِيَّتِه له بالمُلك، ويَستَدعونَه، ويَحُثُّونَه على السُّرعةِ، ويُخَوِّفونَه مِن أخيه مسعود، فحين بلَغَه الخبَرُ سار إلى غزنة، فوصلها بعد موتِ أبيه بأربعينَ يومًا، فاجتَمَعَت العساكِرُ على طاعتِه، وفَرَّقَ فيهم الأموالَ والخِلَعَ النَّفيسةَ، فأسرف في ذلك. لكِنَّ أخاه مسعودًا نازَعَه الحُكمَ فانتزَعَه منه."},{"id":1455,"title":"البيعة لأبي جعفر عبد الله بن القادر بالله بولاية العهد  .","date":["العام الهجري :421","الشهر القمري : جمادى الأولى","العام الميلادي :1030"],"text":"مَرِضَ الخليفةُ القادِرُ باللهِ، وأُرجِفَ بمَوتِه، فجلَسَ جُلوسًا عامًّا وأذِنَ للخاصَّةِ والعامَّةِ فوَصَلوا إليه، فلما اجتَمَعوا قام الصاحِبُ أبو الغنائِمِ مُحَمَّدُ بنُ أحمد فقال: خَدَمُ مولانا أميرِ المؤمنينَ داعُونَ له بإطالةِ البَقاءِ، وشاكِرونَ لِما بلَغَهم مِن نَظَرِه لهم وللمُسلِمينَ، باختيارِ الأميرِ أبي جَعفرٍ عَبدِ اللهِ بنِ القادِرِ لولايةِ العَهدِ، فقال الخليفةُ للنَّاسِ: قد أذِنَّا في العَهدِ له، وكان أراد أن يُبايِعَ له قبل ذلك، فثَناه عنه أبو الحسَنِ بنُ حاجِبِ النعمان، فلمَّا عَهِدَ إليه أُلقِيَت السِّتارةُ، وقعَدَ أبو جعفرٍ على السَّريرِ الذي كان قائمًا عليه، وخَدَمُه الحاضِرونَ وهنَّؤوه، وتقَدَّم أبو الحَسَن بنُ حاجِبِ النعمان فقَبَّل يَدَه وهَنَّأه، ودُعِيَ له على المنابِرِ يومَ الجمعة لتسعٍ بَقِينَ من جُمادى الأولى."},{"id":1456,"title":"تغلب مسعود بن محمود بن سبكتكين على أخيه محمد .","date":["العام الهجري :421","الشهر القمري : ذي القعدة","العام الميلادي :1030"],"text":"لَمَّا توفِّيَ يَمينُ الدَّولة وكان قد عَهِدَ لابنه محمَّدٍ دون مسعودٍ، وكان ابنُه مَسعودٌ بأصبهان، فلمَّا بلَغَه الخبَرُ سار إلى خراسان، واستخلف بأصبهانَ بَعضَ أصحابِه في طائفةٍ مِن العسكر، فحين فارَقَها ثار أهلُها بالوالي عليهم فقَتَلوه، وقَتَلوا مَن معه من الجُندِ، وأتى مسعودًا الخبَرُ، فعاد إليها وحَصَرها، وفتَحَها عَنوةً، وقَتَل فيها فأكثَرَ، ونهبَ الأموالَ، واستخلف فيها رجُلًا كافيًا، وكَتَب إلى أخيه محمَّدٍ يُعلِمُه بذلك، وأنَّه لا يريدُ مِن البلادِ التي وصَّى له أبوه بها شيئًا، وأنَّه يكتفي بما فتَحَه من بلاد طبرستان، وبلَد الجبل، وأصبهان، وغيرها، ويطلُبُ منه المُوافَقةَ، وأن يُقَدِّمَه في الخُطبةِ على نَفسِه، فأجابه محمَّدٌ جَوابَ مُغالِطٍ، وكان مسعودٌ قد وصلَ إلى الريِّ، فأحسَنَ إلى أهلِها، وسار منها إلى نَيسابور، ففعل مثل ذلك، وأمَّا مُحمَّدُ فإنه أخذَ على عَسكَرِه العهودَ والمواثيقَ على المُناصَحةِ له، والشَّدِّ منه، وسار في عساكِرِه إلى أخيه مسعودٍ مُحاربًا له، وكان بعضُ عساكِرِه يَميلُ إلى أخيه مسعودٍ لِكِبَرِه وشجاعتِه، ولأنَّه قد اعتاد التقَدُّمَ على الجيوشِ، وفَتْح البلاد، وبعضُهم يخافُه لقُوَّةِ نَفسِه، وكان محمَّدٌ قد جعَلَ مُقَدَّمَ جَيشِه عَمَّه يوسُفَ بن سبكتكين، وكان من أعيانِ أصحابِ أبيه محمودٍ مِمَّن أشار عليه بموافقةِ أخيه وترْكِ مخالفته، فلم يُصْغِ إلى قوله، وسار فوصَلَ إلى تكناباذ أوَّلَ يوم من رمضان، وأقام إلى العيدِ، فعَيَّدَ هناك، فلمَّا كان ليلةُ الثلاثاء ثالثَ شَوَّال ثار به جُندُه، فأخذوه وقَيَّدوه وحَبَسوه، وكان مشغولًا بالشَّرابِ واللَّعِبِ عن تدبيرِ المَملكةِ، والنَّظَر في أحوال الجُندِ والرعايا، فلمَّا قَبَضوا عليه نادوا بشِعارِ أخيه مسعود، ورفعوا محمدًا إلى قلعةِ تكناباذ، وكتبوا إلى مسعودٍ بالحال. فكان اجتماعُ المُلْكِ له واتِّفاقُ الكَلِمةِ عليه في ذي القَعدةِ، وكان وصولُ مسعودٍ إلى غزنةَ ثامنَ جُمادى الآخرة من سنة 422، فلما وصلَ إليها وثَبَّتَ مُلكَه بها أتَتْه رُسُلُ الملوكِ مِن سائِرِ الأقطار إلى بابه، واجتمَعَ له مُلْكُ خُراسانَ، وغزنة، وبلاد الهند والسند، وسجستان، وكرمان، ومكران، والري، وأصبهان، وبلد الجبل، وغير ذلك، وعَظُم سلطانُه وخِيفُ جانِبُه."},{"id":1457,"title":"استيلاء الروم على الرها (مدينة في الجزيرة الفراتية) .","date":["العام الهجري :422","العام الميلادي :1030"],"text":"كانت الرَّها بيدِ نَصرِ الدَّولة بن مروان، فلمَّا قُتِلَ عَطير الذي كان صاحِبَها، شَفَعَ صالحُ بنُ مرداس، صاحِبُ حَلَب، إلى نَصرِ الدَّولة ليُعيدَ الرَّها إلى ابنِ عطير، وإلى ابنِ شبلٍ، بينهما نِصفَينِ، فقَبِلَ شَفاعَتَه، وسَلَّمَها إليهما، وكان في الرَّها برجانِ حَصينانِ أحَدُهما أكبَرُ من الآخر، فتَسَلَّمَ ابنُ عطير الكبير، وابنُ شبل الصَّغيرَ، وبَقِيَت المدينةُ معهما إلى هذه السَّنة، فراسل ابنُ عطير أرمانوس مَلِكَ الروم، وباعَه حِصَّتَه من الرَّها بعشرينَ ألف دينار، وعِدَّة قُرًى من جملتِها قريةٌ تُعرَفُ إلى الآن بسن ابن عطير، وتسَلَّموا البرُجَ الذي له، ودخلوا البلَدَ فمَلَكوه، وهرب أصحابُ ابنِ شبل من البُرجِ الآخَر، وقَتَل الرُّومُ المُسلِمين، وخَرَّبوا المساجِدَ، وسَمِعَ نَصرُ الدَّولة الخبَرَ، فسَيَّرَ جيشًا إلى الرها، فحصَروها وفتَحوها عَنوةً، واعتصم مَن بها مِن الرُّومِ بالبُرجَينِ، واحتمى النَّصارى بالبيعةِ التي لهم، وهي من أكبَرِ البِيَعِ وأحسَنِها عِمارةً، فحَصَرهم المسلمونَ بها، وأخرَجوهم، وقَتَلوا أكثَرَهم، ونَهَبوا البلدَ، وبَقِيَ الرومُ في البرجين، وسَيَّرَ إليهم عسكرًا نحو عشرةِ آلاف مقاتل، فانهزم أصحابُ ابنِ مَروانَ مِن بينِ أيديهم، ودخَلوا البلدَ وما جاوَرَهم من بلادِ المُسلِمينَ، وصالحهم ابنُ وَثَّاب النميري على حَرَّان وسروج وحمَلَ إليهم خراجًا."},{"id":1458,"title":"الروم يسيطرون على قلعة أفامية بالشام .","date":["العام الهجري :422","العام الميلادي :1030"],"text":"سيَّرَ الظَّاهِرُ حاكِمُ مِصرَ العُبَيديُّ إلى الشَّامِ الدزبريَّ وزيرَه، فملَّكه، وقَصَد حسَّانَ بنَ المفرج الطائي، فألحَّ في طلَبِه، فهَرَب منه، ودخل بلدَ الرُّومِ ولَبِسَ خِلعةَ مَلِكِهم، وخرج مِن عِندِه وعلى رأسِه عَلَمٌ فيه صليبٌ، ومعه عسكَرٌ كثيرٌ، فسار إلى أفامية فكَبَسَها، وغَنِمَ ما فيها، وسبى أهلَها، وأسَرَهم، وسيَّرَ الدزبري إلى البلادِ يستنفِرُ النَّاسَ للغزو وخرج فخافه نصرُ بن صالح وقَرَّرَ لِمَلِك الرومِ على نفسِه خَمسَمِئَة ألف درهم، صرف ستين درهمًا بدينار، على أن يحميَه، وذلك في جُمادى الأولى؛ فاتَّفَقَ مَرَضُ الدزبري بدمشق، وأُرجِفَ به، ثم عوفيَ."},{"id":1459,"title":"نهاية الدَّولة الأموية بالأندلس وقيام الدَّولة الجهورية في قُرطُبة .","date":["العام الهجري :422","العام الميلادي :1030"],"text":"كان المُعتَدُّ بالله أبو بكر هِشامُ بنُ مُحمَّدِ بنِ عبدِ المَلِك بن عبد الرحمن النَّاصر الأمويُّ أميرَ قُرطُبةَ، لكنَّه لم يَقُمْ بها إلا يسيرًا حتى قامت عليه طائفةٌ مِن الجُندِ فخُلِعَ، وجَرَت أمورٌ مِن جُملتِها إخراجُ المُعتَدِّ بالله مِن قَصرِه هو وحشَمُه والنِّساءُ حاسراتٍ عن أوجُهِهنَّ حافيةً أقدامُهنَّ إلى أن أُدخِلوا الجامِعَ الأعظَمَ على هيئةِ السَّبايا، فأقاموا هنالك أيامًا يُتعَطَّفُ عليهم بالطَّعامِ والشَّرابِ إلى أن أُخرِجوا عن قُرطُبةَ، ولَحِقَ هِشامٌ ومَن معه بالثُّغورِ بعد اعتقاله بقُرطُبةَ، فلم يزَلْ يجولُ في الثغور إلى أن لَحِقَ بابن هود المتغَلِّب على مدينة لاردة وسرقسطة وأفراغة وطرطوشة وما والى تلك الجهاتِ، فأقام عنده هشامٌ إلى أن مات في سنة 427 ولا عَقِبَ له، فهِشامٌ هذا آخِرُ مُلوكِ بني أميَّة بالأندلُسِ، وبخَلْعِه انقطَعَت الدَّعوةُ لبني أميَّةَ وذِكرُهم على المنابِرِ بجَميعِ أقطارِ الأندلس، ولَمَّا انقَطَعَت دعوةُ بني أمية استولى على تدبيرِ مُلكِ قُرطُبةَ أبو الحزم جهورُ بنُ مُحمَّدِ بنِ جهور وهو قديمُ الرِّياسةِ شَريفُ البيتِ، كان آباؤه وزراءَ الدَّولةِ الحَكَميَّة والعامريَّة، فلمَّا خلا له الجوُّ وأصفَرَ الفِناءُ وأقفَرَ النادي من الرُّؤساءِ وأمكَنَتْه الفرصةُ؛ وثَبَ عليها فتولى أمْرَها واضطلَعَ بحِمايتِها، ولم ينتَقِلْ إلى رتبةِ الإمارةِ ظاهرًا بل دَبَّرَها تدبيرًا لم يُسبَقْ إليه؛ وذلك أنَّه جعَلَ نَفسَه مُمسِكًا للمَوضِعِ إلى أن يجيءَ مَن يتَّفِقُ النَّاسُ على إمارتِه فيُسَلِّم إليه ذلك، ورتَّبَ البوَّابينَ والحَشَم على تلك القُصورِ على ما كانت عليه أيامَ الدَّولةِ، ولم يتحَوَّلْ عن دارِه إليها، وجعَلَ ما يرتَفِعُ مِن الأموالِ السُّلطانيَّةِ بأيدي رجالٍ رَتَّبَهم لذلك، وهو المُشرِفُ عليهم، وصَيَّرَ أهلَ الأسواقِ جُندًا له وجَعَلَ أرزاقَهم رُؤوسَ أموالٍ تكونُ بأيديهم مُحصاةً عليهم، يأخذونَ رِبحَها، ورُؤوسُ الأموالِ باقيةٌ مَحفوظةٌ يُؤخَذونَ بها ويُراعَونَ في كُلِّ وَقتٍ كيف حِفظُهم لها، وفَرَّقَ السِّلاحَ عليهم واستمَرَّ أمْرُه على ذلك إلى أن مات في غُرَّةِ صَفَر سَنةَ 435، ثم ولِيَ ما كان يتولَّى مِن أمر قُرطُبةَ بَعدَه ابنُه أبو الوليدِ مُحَمَّدُ بنُ جهور فجرى في السياسةِ وحُسنِ التدبيرِ على سَنَنِ أبيه غيرَ مُخِلٍّ بشيءٍ مِن ذلك إلى أن مات أبو الوليدِ في شوَّال من سنة 443."},{"id":1460,"title":"تجدد الفتنة بين السنة والشيعة ببغداد .","date":["العام الهجري :422","الشهر القمري : ربيع الأول","العام الميلادي :1031"],"text":"تجَدَّدَت الفِتنةُ ببغدادَ بينَ السُّنَّة والشِّيعة، وكان سبَبُ ذلك أنَّ الوزيرَ أبا القاسم عليَّ بنَ أحمد الملَقَّب بالمذكور أظهَرَ العَزمَ على الغَزاة، واستأذن الخليفةَ في ذلك، فأَذِنَ له، وكُتِبَ له منشورٌ من دار الخلافة، وأعطى عَلَمًا، فاجتمَعَ له لفيفٌ كثيرٌ، فسار واجتاز ببابِ الشعير، وطاق الحراني، وبين يديه الرِّجالُ بالسِّلاحِ، فصاحوا بذِكرِ أبي بكرٍ وعُمَرَ، رَضِيَ الله عنهما، وقالوا: هذا يومُ مُعاوية، فنافَرَهم أهلُ الكَرخِ ورَمَوهم، وثارت الفِتنةُ، ونُهِبَت دورُ اليَهودِ؛ لأنَّهم قيل عنهم إنَّهم أعانوا أهلَ الكَرخِ، فلمَّا كان الغدُ اجتمع السُّنَّةُ من الجانِبَينِ، ومعهم كثيرٌ مِن الأتراكِ، وقصدوا الكَرخَ، فأحرقوا وهَدَّموا الأسواق، وأشرف أهلُ الكَرخِ على خُطَّةٍ عظيمة. وأنكَرَ الخليفةُ ذلك إنكارًا شديدًا، ونَسَب إليهم تخريقَ عَلامتِه التي مع الغزاةِ، فركب الوزيرُ فوَقَعَت في صَدرِه آجُرَّة، فسَقَطَت عِمامَتُه، وقُتِلَ مِن أهل الكرخِ جماعةٌ، وأُحرِقَ وخُرِّبَ في هذه الفتنةِ سُوقُ العَروسِ، وسوقُ الصَّفَّارين، وسوقُ الأنماط، وسوق الدقَّاقين، وغيرها، واشتد الأمرُ، ووقع القتالُ في أصقاع البلَدِ مِن جانبيه، وقَتَلَ أهلَ الكَرخِ، ونهر طابق، والقَلَّائين– صَنعتُهم القَليُ-، وباب البصرة، وفي الجانب الشَّرقيِّ أهل سوقِ الثلاثاء، وسُوق يحيى، وباب الطاق، والأساكفة، والرهادرة، ودرب سليمان، فقُطِعَ الجِسرُ ليُفَرَّقَ بين الفريقين، ودخل العَيَّارون– والعيارون: لُصوصٌ يَمتَهِنونَ النَّهبَ والدعارةَ - البلدَ، وكَثُرَ الاستقفاءُ بها ليلًا ونهارًا. وأظهر الجندُ كراهةَ المَلِك جلالِ الدَّولة، وأرادوا قَطعَ خُطبتِه، ففَرَّقَ فيهم مالًا وحَلَفَ لهم فسَكَنوا، ثم عاودوا الشَّكوى إلى الخليفةِ منه، وطَلَبوا أن يأمُرَ بقَطعِ خُطبتِه، فلم يُجِبْهم إلى ذلك، فامتنع حينئذ جلالُ الدَّولة من الجلوس، ودامت هذه الحالُ إلى عيدِ الفِطرِ، ثمَّ حدث في شوال فتنةٌ بين أصحابِ الأكْيِسة وأصحابِ الخِلعانِ، وهما شيعةٌ، وزاد الشَّرُّ، ودام إلى ذي الحِجَّة، فنودي في الكَرخِ بإخراجِ العَيَّارين، فخرجوا، واعتَرَض أهلُ باب البصرة قومًا مِن قُمٍّ أرادوا زيارةَ مَشهدِ عليٍّ والحُسَين، فقَتَلوا منهم ثلاثةَ نَفَر، وامتنَعَت زيارةُ مَشهَدِ موسى بنِ جَعفَر."},{"id":1461,"title":"وفاة الخليفة العباسي القادر بالله وتولي ابنه القائم بأمر الله الخلافة .","date":["العام الهجري :422","الشهر القمري : ذي الحجة","العام الميلادي :1031"],"text":"هو الخليفةُ أبو العَبَّاسِ أحمَدُ بنُ الأميرِ إسحاقَ بنِ المُقتَدِرِ جَعفرِ بنِ المُعتَضِدِ العباسيِّ البغداديِّ. ولِدَ سنة 336. وأمُّه اسمُها: تمني, ماتت في دولتِه، وكان أبيضَ كَثَّ اللِّحيةِ يَخضِبُ, دَيِّنًا عالِمًا متعَبِّدًا وقورًا، مِن جِلَّةِ الخُلفاءِ وأمثَلِهم. عَدَّه ابنُ الصَّلاحِ في الشَّافعيَّة؛ فقد تفَقَّه على أبي بشرٍ أحمَدُ بنُ محمَّدٍ الهَرَويِّ. قال الخطيبُ البغدادي: \"كان القادِرُ باللهِ مِن السِّترِ والدِّيانةِ، وإدامةِ التهَجُّدِ باللَّيلِ وكثرةِ البِرِّ والصَّدَقات على صِفةٍ اشتُهِرَت عنه\" وكان قد صَنَّفَ كِتابًا في الأصولِ ذكر فيه فضائِلَ الصَّحابةِ على ترتيبِ مَذهَبِ أهل الحديث, وأورد في كتابِه فضائِلَ عُمَرَ بنِ عبد العزيز، وإكفارَ المُعتَزِلة والقائلينَ بخَلقِ القُرآنِ, وكان الكِتابُ يُقرأُ كُلَّ جُمعةٍ في حلقةِ أصحابِ الحديث. قال شيخُ الإسلامِ ابنُ تيميَّةَ: \"كان في أيَّامِ المتوكِّلِ قد عَزَّ الإسلامُ حتى ألزَمَ أهلَ الذِّمَّةِ بالشُّروطِ العُمَرِيَّة وألزموا الصِّغارَ، فعَزَّت السُّنَّة والجماعة, وقُمِعَت الجَهميَّةُ والرَّافِضةُ ونحوهم، وكذلك في أيَّامِ المُعتَضِد، والمُهتدي، والقادرِ بالله، وغيرِهم من الخُلفاِء الذين كانوا أحمَدَ سِيرةً وأحسَنَ طريقةً مِن غَيرِهم, وكان الإسلامُ في زَمَنِهم أعَزَّ، وكانت السُّنَّةُ بحَسَبِ ذلك\" أمَرَ القادِرُ باللهِ بعَمَلِ مَحضَرٍ يتضَمَّنُ القَدحَ في نَسَبِ العُبَيديَّة، وأنَّهم منسوبونَ إلى ديصان بنِ سعيدٍ الخرَّميِّ، أخذَ عليه خُطوطَ العُلَماءِ والقُضاة والطَّالبيِّينَ، كما استتابَ فُقَهاءَ المُعتَزِلة، فأظهروا الرُّجوعَ وتبَرَّؤوا من الاعتزالِ والرَّفضِ والمقالاتِ المخالفةِ للإسلامِ. تُوفِّيَ القادِرُ بالله وكانت خلافتُه إحدى وأربعينَ سَنةً وثلاثةَ أشهُرٍ وعشرين يومًا، وكانت الخلافةُ قَبلَه قد طَمِعَ فيها الديلَمُ والأتراك، فلَمَّا وَلِيَها القادِرُ بالله أعاد جِدَّتَها، وجَدَّد ناموسَها، وألقى اللهُ هَيبَتَه في قلوبِ الخَلقِ، فأطاعوه أحسَنَ طاعةٍ وأتَمَّها، فلمَّا مات القادِرُ بالله جلَسَ ابنُه القائِمُ بأمرِ الله أبو جعفرٍ عبدُ الله، وجُدِّدَت له البيعةُ، وكان أبوه قد بايَعَ له بولايةِ العهدِ سنةَ 421، واستقَرَّت الخلافةُ له، وأوَّلُ مَن بايَعَه الشَّريفُ أبو القاسِمِ المرتضى، وأرسل القائِمُ بأمرِ اللهِ قاضيَ القُضاةِ أبا الحسَن الماوَرديَّ إلى المَلِك أبي كاليجار؛ ليَأخُذَ عليه البَيعةَ، ويَخطُبَ له في بلادِه، فأجابَ وبايَعَ، وخَطَب له في بلادِه."},{"id":1462,"title":"طاعون جارف امتد من الهند إلى بلاد العجم والعراق .","date":["العام الهجري :423","العام الميلادي :1031"],"text":"كان الطَّاعونُ ببِلادِ الهِندِ والعَجَمِ، وعَظُمَ إلى الغاية، وكان أكثَرُه بغُزنة وخراسان وجرجان والريِّ وأصبهان ونواحي الجَبَل إلى حلوان، وامتَدَّ إلى المَوصِل والجزيرة وبغداد، ثمَّ امتَدَّ إلى شيراز، وتَبِعَه غلاءٌ شديد، واستسقى النَّاسُ فلم يُسْقَوا، وكان عامًّا في جميعِ البلادِ، وكَثُرَ المَوتُ، فدُفِنَ في أصبهانَ في عِدَّةِ أيَّامٍ أربعونَ ألفَ مَيِّتٍ، وكَثُرَ الجُدريُّ في النَّاسِ فأُحصي بالموصِلِ أنَّه مات به أربعةُ آلاف صبي، ولم تخْلُ دارٌ مِن مصيبةٍ لعُمومِ المصائِبِ وكثرةِ الموت، وممَّن أُصيبَ بالجُدريِّ الخليفةُ القائِمُ بأمرِ اللهِ ثمَّ سَلِمَ."},{"id":1463,"title":"هزيمة الأرمن على يد نائب نصر الدَّولة بن مروان .","date":["العام الهجري :423","العام الميلادي :1031"],"text":"جمَعَ نائِبُ نَصرِ الدَّولة بنِ مَروان بالجزيرة جمعًا يُنَيِّفُ على عشرةِ آلافِ رَجُلٍ، وغزا مَن يُقارِبُه مِن الأرمن، وأوقع بهم وأثخَنَ فيهم، وغَنِمَ وسَبى كثيرًا، وعاد ظافرًا مَنصورًا"},{"id":1464,"title":"وقوع فتنة بين أهل تونس من إفريقية .","date":["العام الهجري :423","العام الميلادي :1031"],"text":"كان بين أهلِ تونُسَ مِن إفريقيَّةَ خِلافٌ، فسار المُعِزُّ بنُ باديس صاحِبُ إفْريقيَّةَ إليهم بنَفسِه، فأصلحَ بينهم، وسَكَنَت الفتنةُ وعاد."},{"id":1465,"title":"ثورة الشيعة في إفْريقيَّة وقمعهم .","date":["العام الهجري :423","العام الميلادي :1031"],"text":"اجتمع ناسٌ كثيرٌ مِن الشِّيعةِ بإفريقيَّةَ، وساروا إلى أعمالِ نفطة، فاستولوا على بلدٍ منها وسكنوه، فجَرَّد إليهم المعِزُّ بنُ باديس صاحِبُ إفْريقيَّة عسكرًا، فدخلوا البلادَ وحاربوا الشيعةَ وقتلوهم أجمعين."},{"id":1466,"title":"عدم تمكن أهل العراق من الحج بسبب قطاع الطرق .","date":["العام الهجري :423","العام الميلادي :1031"],"text":"خرَجَت العرَبُ على حُجَّاجِ البَصرةِ ونَهَبوهم، وحَجَّ النَّاسُ مِن سائِرِ البلادِ إلَّا من العراقِ."},{"id":1467,"title":"تجدد الفتنة بين جلال الدَّولة البويهي وبين الأتراك ببغداد .","date":["العام الهجري :423","الشهر القمري : ربيع الأول","العام الميلادي :1032"],"text":"تجدَّدت الفِتنةُ بين جلالِ الدَّولةِ البُويهي وبين الأتراك، فأغلَقَ بابه، فجاءت الأتراكُ ونهبوا دارَه، وسلبوا الكُتَّابَ وأربابَ الديوانِ ثيابَهم، وطلبوا الوزيرَ أبا إسحاقَ السهلي، فهرب إلى حلةِ كمال الدَّولةِ غريب بن محمد، وخرج جلالُ الدَّولة إلى عكبرا في شهرِ ربيعٍ الآخر، وخطب الأتراكُ ببغداد للمَلِك أبي كاليجار، وأرسلوا إليه يطلبونَه وهو بالأهواز، فمَنَعه العادلُ بن مافنة عن الإصعادِ إلى أن يحضُرَ بعضُ قوادهم، فلمَّا رأوا امتناعَه من الوصول إليهم، أعادوا خُطبةَ جلال الدَّولة، وساروا إليه، وسألوه العَودَ إلى بغداد، واعتذروا، فعاد إليها بعدَ ثلاثة وأربعينَ يومًا."},{"id":1468,"title":"ثورة الأتراك على الملك جلال الدَّولة البويهي .","date":["العام الهجري :424","العام الميلادي :1032"],"text":"ثارت الأتراك بالمَلِك جلالِ الدَّولة البويهي ليأخُذوا أرزاقَهم، وأخرجوه من دارِه، ورسَموا عليه في المسجِدِ، وأُخرِجَت حريمُه، فذهب في اللَّيلِ إلى دار الشَّريفِ المرتضى فنزلها، ثمَّ اصطلحت الأتراكُ عليه وحَلَفوا له بالسَّمعِ والطاعة، وردُّوه إلى دارِه."},{"id":1469,"title":"ثورة العيارين ببغداد .","date":["العام الهجري :424","العام الميلادي :1032"],"text":"ثار العَيَّارون ببغداد -والعَيَّارون لصوصٌ يَمتَهِنونَ النَّهبَ والدعارةَ - وأخذوا أموالَ النَّاسِ ظاهرًا، وعَظُم الأمرُ على أهلِ البَلَدِ، وطَمِعَ المُفسِدونَ إلى حَدِّ أنَّ بعضَ القُوَّادِ الكِبارِ أخَذَ أربعةً مِن العيَّارينَ، فجاء عقيدُهم وأخذَ مِن أصحابِ القائِدِ أربعةً، وحضر بابَ دارِه ودقَّ عليه الباب، فكَلَّمَه من داخل، فقال العقيدُ: قد أخذتُ مِن أصحابِك أربعةً، فإنْ أطلقْتَ مَن عندَك أطلقتُ مَن عندي، وإلَّا قَتلْتُهم، وأحرَقْتُ دارَك! فأطلَقَهم القائد."},{"id":1470,"title":"مسعود بن سبكتكين يتولى تدبير شؤون الدولة الغزنوية .","date":["العام الهجري :424","الشهر القمري : رجب","العام الميلادي :1033"],"text":"لَمَّا استقَرَّ المُلكُ لمسعود بن سبكتكين بعد أبيه أقرَّ بما كان قد فتَحَه أبوه من الهندِ نائبًا يُسمَّى أحمد ينالتكين، وقد كان أبوه محمَّد استنابه بها ثقةً بجَلَدِه ونَهضَتِه، فرَسَخت قَدَمُه فيها، وظَهَرت كِفايته. ثمَّ إنَّ مسعودًا بعد فراغِه مِن تقرير قواعِدِ المُلك، والقَبضِ على عَمِّه يوسف والمخالفين له، سار إلى خراسان عازمًا على قَصدِ العراق، فلمَّا أبعد عصى ذلك النائِبُ بالهند، فاضطُرَّ مسعودٌ إلى العودة، فأرسَلَ إلى علاء الدَّولة بنِ كاكويه. وأمَّرَه على أصبهان على مالٍ يؤدِّيه إليه كلَّ سنة، وكان علاء الدَّولة قد أرسل يطلُبُ ذلك، فأجابه إليه، وأقَرَّ ابنَ قابوس بن وشمكير على جرجان وطبرستان على مالٍ يؤدِّيه إليه، وسَيَّرَ أبا سهل الحمدوني إلى الرَّيِّ للنظَرِ في أمورِ هذه البلاد الجبليَّة، والقيامِ بحفظها، ولَمَّا سار أبو سهل إلى الريِّ أحسَنَ إلى النَّاسِ، وأظهَرَ العدل، فأزال الأقساطَ والمصادراتِ، وكان تاش فراش والي الرَّيِّ السابقِ قد ملأ البلادَ ظُلمًا وجَورًا، حتى تمنَّى الناسُ الخلاصَ منه ومِن دولة ابن سبكتكين، وخَرِبت البلادُ، وتفَرَّق أهلُها، فلمَّا وَلِيَ الحمدوني، وأحسن وعَدَل، عادت البلادُ فعَمَرت، والرَّعيَّة أمِنَت، وكان الإرجافُ شديدًا بالعراق لَمَّا كان المَلِك مسعود بنيسابور، فلمَّا عاد سكن النَّاس واطمأنُّوا."},{"id":1471,"title":"مسعود بن محمود الغزنوي يفتح قلعة سرستي في الهند .","date":["العام الهجري :425","العام الميلادي :1033"],"text":"فتح السُّلطانُ مسعود بن محمود بن سبكتكين قلعةَ سرستي وما جاورها من بلاد الهندِ، وكان سبَبُ ذلك عصيانَ نائِبِه بالهند أحمد ينالتكين عليه ومَسيره إليه، فلمَّا عاد أحمد إلى طاعتِه أقام بتلك البلادِ طويلًا حتى أَمِنَت واستقَرَّت، وقصد قلعةَ سرستي، وهي مِن أمنَعِ حُصون الهند وأحصَنِها، فحَصَرها، وقد كان أبوه حَصَرها غيرَ مَرَّة، فلم يتهيَّأْ له فتحُها، فلمَّا حَصَرها مسعود راسلَه صاحِبُها، وبذل له مالًا على الصُّلحِ، فأجابه إلى ذلك وكان فيها قومٌ من التجَّار المسلمين، فعَزَم صاحِبُها على أخذِ أموالهم وحَمْلها إلى مسعودٍ من جملة القرارِ عليه، فكتب التجَّار رقعةً في نشابة ورموا إليه يُعَرِّفونه فيها ضَعفَ الهنود بها، وأنَّه إن صابَرَهم مَلَكَهم، فرجع عن الصُّلحِ إلى الحَربِ، وطَمَّ خَندقَها بالشَّجَر وقَصَبِ السكر وغيره، وفتح اللهُ عليه، وقَتَل كلَّ من فيها، وسبى ذراريَّهم، وأخذ ما جاورها من البلادِ، وكان عازمًا على طولِ المقامِ والجهاد، فأتاه من خراسان خبَرُ اجتياح الغز التركمان بلادَه، فعاد إلى غزنة."},{"id":1472,"title":"استيلاء الروم على قلعةُ بركوي المتاخِمةُ للأرمن .","date":["العام الهجري :425","العام الميلادي :1033"],"text":"كانت قلعةُ بركوي المتاخِمةُ للأرمن في يَدِ أبي الهيجاء بن ربيب الدَّولة، ابنِ أخت وهسوذان بن مملان، فتنافَرَ هو وخاله، فأرسل خالُه إلى الرومِ فأطمعهم فيها، فسَيَّرَ مَلِكُ الروم إليها جمعًا كثيرًا فمَلَكوها، فبلغ الخبَرُ إلى الخليفة العباسي القائمِ بأمرِ الله، فأرسل إلى أبي الهيجاءِ وخالِه مَن يُصلِحُ بينهما ليتَّفِقا على استعادةِ القلعةِ، فاصطلحا، ولم يتمَكَّنا من استعادتِها، واجتمع إليهما خلقٌ كثيرٌ مِن المتطَوِّعة، فلم يقدروا على ذلك؛ لثباتِ قَدَمِ الرُّومِ بها."},{"id":1473,"title":"استعانة ابنُ وثَّاب النميري بالروم ضد المسلمين .","date":["العام الهجري :426","العام الميلادي :1034"],"text":"جمع ابنُ وثَّاب النميري جمعًا كثيرًا من العَرَبِ وغيرِهم، واستعان بمَن بالرَّها مِن الرُّومِ على المُسلِمينَ، فسار معه منهم جيشٌ كثيفٌ، وقصَدَ بلَدَ نصرِ الدَّولة أحمدَ بنِ مروان الكردي صاحِبِ ديارِ بكر، ونهب وأخرب. فجمَع ابنُ مروان جموعَه وعساكِرَه واستمَدَّ قرواشًا أميرَ بني عقيلٍ وغَيرَه، وأتته الجنودُ مِن كلِّ ناحية، فلما رأى ابنُ وثاب ذلك وأنَّه لا يتِمُّ له غَرَضٌ عاد عن بلادِه، وأرسل ابنُ مروان إلى ملِك الرُّومِ يعاتِبُه على نَقضِ الهُدنةِ وفَسْخِ الصُّلحِ الذي كان بينهما، وراسل أصحابَ الأطرافِ يَستنجِدُهم للغَزاة، فكَثُر جمعُه من الجند والمتطَوِّعة، وعزم على قَصْدِ الرَّها ومحاصَرتِها، فوردت رسُلُ ملك الروم يعتَذِرُ، ويحلِفُ أنَّه لم يعلمْ بما كان، وأرسَلَ إلى عسكَرِه الذين بالرَّها والمُقَدَّم عليهم يُنكِرُ ذلك، وأهدى إلى نصرِ الدَّولة هديةً سَنِيَّةً، فترك ما كان عازمًا عليه من الغَزوِ، وفرَّق العساكِرَ المجتَمِعةَ عنده."},{"id":1474,"title":"وهن أمر الخلافة ببغداد .","date":["العام الهجري :426","الشهر القمري : محرم","العام الميلادي :1034"],"text":"وَهَن أمرُ الخلافةِ والسَّلطَنةِ ببغداد، حتى إنَّ بَعضَ الجُندِ خَرَجوا إلى قريةِ يحيى، فلَقِيَهم أكراد، فأخَذوا دوابَّهم، فعادوا إلى حَقلِ الخليفةِ القائِمِ بأمر الله، فنَهَبوا شيئًا من ثَمَرتِه، وقالوا للعاملينَ فيه: أنتم عَرَفتم حالَ الأكرادِ ولم تُعلِمونا، فسَمِعَ الخليفةُ الحالَ، فعَظُمَ عليه، ولم يَقدِرْ جلال الدَّولة البويهيُّ على أخذِ أولئك الأكراد لعَجزِه ووَهَنِه، واجتهدَ في تسليمِ الجُندِ إلى نائبِ الخليفة، فلم يُمكِنْه ذلك، فتقَدَّم الخليفةُ إلى القُضاةِ بتَركِ القَضاءِ والامتناعِ عنه، وإلى الشُّهودِ بتَركِ الشهادةِ، وإلى الفُقَهاءِ بترك الفتوى، فلمَّا رأى جلالُ الدَّولة ذلك سأل أولئك الأجنادَ ليُجيبوه إلى أن يحمِلَهم إلى ديوانِ الخلافة، ففعلوا، فلمَّا وصلوا إلى دار الخلافةِ أُطلِقوا، وعَظُمَ أمرُ العيَّارين– العَيَّارون لصوصٌ يَمتَهِنونَ النَّهبَ والدعارةَ - وصاروا يأخُذونَ الأموالَ ليلًا ونهارًا، ولا مانِعَ لهم؛ لأنَّ الجُندَ يَحمونَهم على السُّلطانِ ونُوَّابه، والسلطان عاجِزٌ عن قَهرِهم، وانتشر العربُ في البلادِ فنهبوا النواحيَ، وقطعوا الطريقَ، وبلغوا إلى أطرافِ بغداد، حتى وصلوا إلى جامِعِ المنصور، وأخذوا ثيابَ النساءِ مِن المقابرِ."},{"id":1475,"title":"مَسعودُ الغزنوي يسيطر على مدينة جرجان وطبرستان .","date":["العام الهجري :426","الشهر القمري : شعبان","العام الميلادي :1035"],"text":"كان مَسعودُ الغزنوي قد أقرَّ دارا بن منوجهر بن قابوس على جرجانَ وطبرستان، وتزوَّج أيضًا بابنةِ أبي كاليجار القوهي، مقدَّم جيشِ دارا، فلمَّا سار إلى الهند منعوا ما كان استقَرَّ عليهم من المال، وراسلوا علاءَ الدَّولة بن كاكويه وفرهاذ بالاجتماعِ على العصيان والمخالفة، وقَوِيَ عزمُهم على ذلك ما بلَغَهم من خروج الغز بخراسان، فلما عاد مسعودٌ من الهند وأجلى الغزَّ وهَزَمهم سار إلى جرجان فاستولى عليها وملَكَها، وسار إلى آمل طبرستان، وقد فارقها أصحابُها، واجتمعوا بالغياضِ والأشجارِ الملتَفَّةِ، الضيَّقة المدخَل، الوَعرةِ المسلَكِ، فسار إليهم واقتحَمَها عليهم فهَزَمهم وأسَرَ منهم وقتل، ثم راسَلَه دارا وأبو كاليجار، وطلبوا منه العَفوَ وتقريرَ البلاد عليهم، فأجابَهم إلى ذلك، وحملوا من الأموالِ ما  كان عليهم، وعاد إلى خراسان."},{"id":1476,"title":"ثورة الجند على الوزير جلال الدَّولة البويهي الشيعي .","date":["العام الهجري :427","العام الميلادي :1035"],"text":"ثار الجُندُ الأتراكُ ببغدادَ على جلالِ الدَّولةِ البُويهيِّ الشيعيِّ، وأرادوا إخراجَه منها، فاستنظَرَهم ثلاثة أيام، فلم يُنظِروه، ورَمَوه بالآجُرِّ، فأصابه بعضُهم، واجتمع الغِلمانُ فرَدُّوهم عنه، فخرَجَ من بابٍ لطيفٍ في سميرية- نوعٍ مِن السفُنِ- مُتنكِّرًا، وصَعِدَ راجلًا منها إلى دارِ المرتضى بالكرخ، وخرج من دار المرتضى، وسار إلى رافعِ بنِ الحُسَين بن مقن بتكريت، وكسَر الأتراكُ أبوابَ داره ودخلوها ونَهَبوها، وقلعوا كثيرًا من ساجِها وأبوابِها، فأرسل الخليفةُ إليه، وقرَّرَ أمرَ الجندِ وأعاده إلى بغداد."},{"id":1477,"title":"وقعة الجفنة بين جماعة زناتة والمعز بن باديس صاحب إفْريقيَّة .","date":["العام الهجري :427","العام الميلادي :1035"],"text":"اجتَمَعت زناتة بإفريقيَّة، وزحَفَت في خيلِها ورَجِلِها يريدونَ مدينة المنصورة، فلَقِيَتهم جيوشُ المعز بن باديس، صاحِبِ إفْريقيَّة، بموضعٍ يقال له الجفنة قريبٍ من القيروان، فاقتتلوا قتالًا شديدًا، وانهزمت عساكرُ المعِزِّ، ففارقت المعركةَ، وهم على حامية، ثم عاودوا القتالَ، وحَرَّض بعضُهم بعضًا فصَبَرت صنهاجة، وانهزمت زناتة هزيمةً قبيحة، وقُتِلَ منهم عددٌ كثير، وأُسِرَ خَلقٌ عظيمٌ، وتُعرَف هذه الوقعةُ بوقعة الجفنة، وهي مشهورةٌ لعِظَمِها عندهم."},{"id":1478,"title":"قيام دولة ذي النون بطليطلة .","date":["العام الهجري :427","العام الميلادي :1035"],"text":"لَمَّا نَشَبت فتنةٌ في طُلَيطلة قام أهلُها بإنهاء حُكمِ ابنِ يعيش، واستدعوا عبد الرَّحمن بن ذي النون أميرَ شنتمرية لتولِّي رئاسة مدينتهم، فأرسل ابنَه إسماعيل فكان أوَّلَ مَن حكم طُلَيطلة من بني ذي النُّونِ، فأحسن إدارتَها إلى أن مات، فتولَّى بعده ابنُه المأمون. هذه بدايةُ قيام دولةِ ذي النون في طُلَيطلة."},{"id":1479,"title":"المسلمون يفتحون السويداء وربض الرها .","date":["العام الهجري :427","الشهر القمري : رجب","العام الميلادي :1036"],"text":"اجتمع ابنُ وثَّاب النميري صاحِبُ حران وقريبُه ابن عطير النميري، وأمدَّهما نصر الدَّولة بنُ مروان بعسكرٍ كثيف، فساروا جميعُهم إلى السُّويداء جنوب دمشق، وكان الرومُ قد أحدثوا عمارتَها في ذلك الوقت، واجتمع إليها أهلُ القرى المجاورةِ لها، فحصرها المسلمون وفتحوها عَنوةً، وقتلوا فيها ثلاثةَ آلاف وخمسَمِئَة من الرومِ، وغَنِموا ما فيها، وسَبَوا خلقًا كثيرًا، وقَصَدوا الرَّها فحصروها، وقطعوا الميرةَ عنها، حتى بلغ مكوكُ الحنطة دينارًا، واشتَدَّ الأمر، فخرج البطريقُ الذي فيها متخفِّيًا، ولحق بمَلِك الرومِ، وعَرَّفه الحالَ، فسَيَّرَ معه خمسةَ آلاف فارس، فعاد بهم، فعَرَف ابن وثاب ومُقَدَّم عساكر نصر الدَّولة الحالَ، فكَمَنا لهم، فلمَّا قاربوهم خرج الكمينُ عليهم، فقُتِلَ من الروم خلقٌ كثير، وأُسِرَ مِثلُهم، وأُسِرَ البطريقُ وحُمِلَ إلى باب الرَّها، وقالوا لِمَن فيها إمَّا أن تفتحوا البلدَ لنا، وإمَّا قتَلْنا البطريقَ والأسرى الذين معه. ففتحوا البلدَ للعجزِ عن حفظه، وتحصَّن أجنادُ الروم بالقلعةِ، ودخل المسلمون الرَّها، وغَنِموا ما فيها، وامتلأت أيديهم من الغنائمِ والسَّبيِ، وأكثروا القتلَ، وأرسل ابنُ وثاب إلى آمد مِئَة وستين راحلةً عليها رؤوسُ القتلى وأقام مُحاصِرًا للقلعة، ثمَّ إنَّ حسَّان بن الجرَّاح الطائي سار في خمسةِ آلاف فارس من العرَبِ والروم نجدةً لِمَن بالرَّها، فسَمِعَ ابن وثاب بقربه، فسار إليه مجِدًّا ليلقاه قبل وصوله، فخرج من الرَّها الروم إلى حران، فقاتَلَهم أهلها، وسَمِعَ ابن وثاب الخبر فعاد مسرعًا، فوقع على الرومِ، فقتل منهم كثيرًا، وعاد المنهزِمونَ إلى الرَّها."},{"id":1480,"title":"وفاة الظاهر لإعزاز دين الله الفاطمي وتولي ابنه المستنصر الحكم .","date":["العام الهجري :427","الشهر القمري : شعبان","العام الميلادي :1036"],"text":"هو الظاهِرُ لإعزازِ دينِ الله أبو الحَسَن عليُّ بن أبي علي المنصور الحاكم الفاطمي العُبيدي الإسماعيليُّ الباطنيُّ, أمُّه أم ولد تدعى رقية، وُلِدَ بالقاهرة سنة 395، وبويع بالحُكمِ بعد أبيه في يوم عيد الأضحى سنة 411، وله من العمرِ 16 سنة و3 أشهر، وكان له مِصرُ، والشام، والخطبة له بإفريقيَّة، وكان جميلَ السِّيرةِ، حَسَن السياسةِ، مُنصِفًا للرعية، إلَّا أنَّه مُشتَغِلٌ بلذَّاته محِبٌّ للدَّعَة والراحة، قد فوَّض الأمورَ إلى وزيره أبي القاسِمِ عليِّ بنِ أحمد الجرجرائي- وكان مقطوعَ اليدينِ مِن المِرفَقينِ-  لِمَعرفته بكفايته وأمانته، في سنة ثماني عشرة، فاستمَرَّ في الوزارة مدةَ ولايةِ الظاهر، ثمَّ لوَلَده المُستنصِر، توفِّي الظاهِرُ في منتصف شعبان بمصر وكان عمُره ثلاثًا وثلاثين سنة، وكانت مُدَّة حُكمِه خَمسَ عشرة سنة وتسعةَ أشهر وسبعة عشر يومًا، ولَمَّا مات الظاهِرُ ولِيَ بعده ابنُه تميم معد، ولقب المستنصر بالله، وتكَفَّل بأعباء المملكة بين يديه الأفضَلُ أميرُ الجيوش، واسمُه بدر بن عبد الله الجمالي، وكان عمرُ المستنصرِ يومَ نُصِّبَ حاكِمًا سبعَ سنينَ وعِدَّة أشهر، وبقي حاكمًا أكثَرَ مِن ستين سنةً."},{"id":1481,"title":"الخليفة العباسي يأذن لحاكِمُ مصر العُبَيديّ بإصلاح نهر الكوفة .","date":["العام الهجري :428","العام الميلادي :1036"],"text":"بعث حاكِمُ مصر العُبَيديُّ بمال لإصلاحٍ نهر بالكوفة إن أذِنَ الخليفةُ العباسيُّ في ذلك، فجمع الخليفةُ الفُقَهاءَ وسألهم عن هذا المالِ فأفتَوا بأنَّ هذا المالَ فَيءٌ للمسلمين، يُصرَفُ في مصالِحِهم، فأذِنَ في صَرفِه في مصالحِ المُسلِمينَ"},{"id":1482,"title":"وفاة أبي الحسين القدوري الحنفي .","date":["العام الهجري :428","الشهر القمري : رجب","العام الميلادي :1037"],"text":"هو العلَّامة أبو الحُسَين أحمدُ بنُ محمد بن أحمد بن جعفر بن حمدان الحنفيُّ الفقيهُ البغدادي المشهورُ بالقُدوري. ولِدَ ببغداد سنة 362. قال أبو بكر الخطيب: \"لم يحدِّثْ إلَّا شيئًا يسيرًا، وكان صَدوقًا، انتهت إليه بالعراقِ رياسةُ أصحابِ أبي حنيفة، وعَظُم عندهم قَدرُه وارتفع جاهُه، وكان حسَنَ العبارةِ في النَّظَرِ، جريءَ اللسان، مُديمًا للتلاوة\"، وهو مُصَنِّف مُختَصَر القُدوري في فقه الحنفيَّة، ويُعتَبَر من أشهَرِ المُختَصَرات في الفقهِ الحَنَفي، وشَرَح مُختَصَر الكَرخيِّ في عدَّة مجلدات، وأملى التجريدَ في الخلافيَّات سنة خمس وأربعمِئَة، وأبان فيه عن حِفظِه لِما عند الدارقطني من أحاديثِ الأحكام وعِلَلِها، وصَنَّف كتابَ التَّقريب الأوَّل في الفقهِ في خلافِ أبي حنيفة وأصحابِه في مجلد، والتَّقريب الثاني في عِدَّة مجلدات. قال ابنُ كثير عنه: \"كان إمامًا بارعًا عالِمًا، وثَبتًا مناظِرًا، وهو الذي تولَّى مناظرةَ الشَّيخِ أبي حامدٍ الإسفرايينيِّ مِن الحنفيَّة\" كانت وفاتُه ببغداد في الخامِسِ مِن رجب وله ستونَ سنة, ودُفِنَ إلى جانب الفقيه أبي بكرٍ الخوارزميِّ الحنَفيِّ."},{"id":1483,"title":"وفاة ابن سينا الطبيب الفيلسوف .","date":["العام الهجري :428","الشهر القمري : رمضان","العام الميلادي :1037"],"text":"هو الفيلسوف الشَّهيرُ، الرَّئيسُ أبو علي الحُسَين بنُ عبدِ الله بن الحَسَن بن علي بن سينا البلخي ثم البخاري، صاحِبُ التصانيف في الطبِّ والفلسفة والمنطق. الحكيمُ المشهور، كان بارعًا في الطبِّ في زمانه، وكان أبوه من أهلِ بلخ، وانتقل إلى بخارى، وهو من العُمَّال فيها، ومن دعاة الإسماعيليَّة، تولَّى العملَ بقرية من ضياعِ بخارى يقال لها خرميثنا، وُلِدَ ابنُ سينا بها سنة 370، واسم أمِّه ستارة. تعلَّم بها فقرأ القرآنَ وأتقَنَه، وهو ابنُ عشر سنين، وأتقن الحسابَ والجبر والمقابلة، ثم اشتغلَ على أبي عبد الله الناتلي الحكيم، فقرأ عليه كتابَ إيساغوجي، وأحكم على يديه عِلمَ المنطقِ وإقليدس والمجسطي، وفاقَه أضعافًا كثيرةً، فبرع فيه وَفاقَ أهلَ زَمانِه في ذلك، كذلك تفَقَّه على كُتُبِ الفارابي، قال ابن كثير في الفارابي الذي تتلمذ ابنُ سينا على كتُبِه: \"تفَقَّه ابنُ سينا على كتب أبي نصرٍ الفارابي التركيِّ الفيلسوف، الذي كان حاذقًا في الفلسفة، ويقول: بالمعادِ الروحاني لا الجُثَماني، ويَخصُص بالمعادِ الأرواحَ العالِمة لا الجاهلةَ، وله مذاهِبُ في ذلك يخالِفُ المسلمينَ والفلاسفةَ مِن سَلَفِه الأقدمين، فعليه- إن كان مات على ذلك- لعنةُ رَبِّ العالمينَ\". وتردَّد النَّاسُ على ابنِ سينا واشتغلوا عليه، وهو ابنُ سِتَّ عشرة سنة، وعالج بعضَ الملوك السامانيَّة، وهو الأميرُ نوح بن نصر، فأعطاه جائزةً سَنيَّةً، وحَكَّمَه في خِزانةِ كُتُبِه، فرأى فيها مِن العجائب والمحاسِن ما لا يوجَدُ في غيرِها قبل أن تحتَرق، فيقال إنَّه عزا بعضَ تلك الكتب إلى نَفسِه، وله في الإلهيَّات والطبيعيَّات كتبٌ كثيرة. قال ابن سينا: \"كان أبي تولى التصرُّفَ بقريةٍ كبيرة، وهو ممَّن آخى داعيَ المصريين، ويُعَدُّ من الإسماعيليَّة. ثمَّ نزل بخارى، فقرأت القُرآنَ وكثيرًا مِن الأدبِ ولي عَشرٌ، ثم رَغِبتُ في الطبِّ، وبَرَزتُ فيه، وقرؤوا عليَّ، وأنا مع ذلك أختَلِفُ إلى الفقه، وأناظِرُ ولي ستَّ عشرة سنة. ثم قرأت جميعَ أجزاء الفلسفة، وكنتُ كلمَّا أتحير في مسألة، أو لم أظفَرْ بالحد الأوسط في قياسٍ، تردَّدتُ إلى الجامِعِ، وصَلَّيتُ، وابتهلتُ إلى مُبدعِ الكُلِّ حتى فُتِح لي المنغَلِقُ منه، وكنت أسهَرُ، فمهما غلبني النومُ، شَربتُ قدحًا, حتى استحكم معي جميع العلوم، وقرأتُ كتاب \"ما بعد الطبيعة\"، فأشكَلَ عليَّ حتى أعدتُ قراءتَه أربعينَ مَرَّة، فحَفِظتُه ولا أفهَمُه، فأَيِستُ, ثمَّ وقع لي مجلدٌ لأبي نصر الفارابي في أغراضِ كتاب \"ما بعد الحكمة الطبيعية\"، ففَتَحَ عليَّ أغراضَ الكتب، ففَرِحتُ، وتصَدَّقتُ بشيء كثير, واتَّفَق لسلطانِ بخارى نوح مَرَضٌ صَعبٌ، فأُحضِرْتُ مع الأطباء، وشاركتُهم في مداواته، فسألت إذنًا في نَظَرِ خزانة كتبه، فدخلت فإذا كتُبٌ لا تُحصى في كلِّ فنٍّ، فظَفِرتُ بفوائدَ, فلما بلَغتُ ثمانية عشر عامًا، فَرَغتُ من هذه العلوم كلِّها، وكنت إذ ذاك للعِلمِ أحفَظَ، ولكنَّه معي اليومَ أنضجُ\". صنَّف ابنُ سينا كتبًا كثيرة نحوًا من مِئَة مُصَنَّف، صغار وكبار، منها \"الإنصاف\" عشرون مجلَّدًا، \"البر والإثم\" مجلدان، \"الشفاء\" ثمانية عشر مجلدًا، \"القانون\" مجلدات، \"الإرصاد\" مجلَّد، \"النجاة\" ثلاث مجلدات، \"الإشارات\" مجلد، \"القولنج\" مجلد، \"اللغة\" عشر مجلدات، \"أدوية القلب\" مجلد، \"الموجز\" مجلد، \"المعاد\" مجلد، وسلامان، وإنسان، وحي بن يقظان، وأشياء كثيرة، ورسائل. قال ابن كثير: \"حصر الغزاليُّ كلامَه في مقاصِدِ الفلاسفةِ، ثمَّ رَدَّ عليه في تهافُتِ الفلاسفة في عشرينَ مجلِسًا له، كَفَّرَه في ثلاثٍ منها، وهي قوله بقِدَمِ العالمِ، وعدمِ المعادِ الجُثماني، وأنَّ اللهَ لا يعلمُ الجزئيات، وبَدَّعَه في البواقي، ويقالُ: إنه تاب عند الموت، فالله أعلم\". وذُكِرَ أنه مات بدمشق بالقولنج في همذان، وقيل بأصبهان، والأول أصحُّ، يوم الجمعة في شهر رمضان منها، عن 58 سنة، قال ابن كثير: \"ولم أر الحافِظَ ابنَ عساكر ذكَرَ ابن سينا في تاريخه; لِنَتنِه وقباحَتِه, فالله أعلم\"."},{"id":1484,"title":"مَلِكُ الأبخاز (القوقاز) يحاصر مدينة تفليس .","date":["العام الهجري :429","العام الميلادي :1037"],"text":"حصَرَ مَلِكُ الأبخاز- القوقاز- مدينة تفليس – عاصِمةَ جورجيا الآن، وتسمى تبليسي- وامتنع أهلُها عليه، فأقام عليهم محاصِرًا ومُضَيِّقًا، فنَفِدَت الأقوات، وانقطعت الميرةُ، فأنفذ أهلُها إلى أذربيجان يَستنفرون المسلمينَ، ويسألونهم إعانَتَهم، فلمَّا وصل الغز إلى أذربيجان، وسَمِعَ الأبخاز بقربهم، وبما فعلوا بالأرمن، رحلوا عن تفليس مُجفِلين خائفين. ولَمَّا رأى وهسوذان صاحِبُ أذربيجان قُوَّةَ الغز، وأنَّه لا طاقة له بهم، لاطَفَهم وصاهَرَهم واستعان بهم."},{"id":1485,"title":"ابتداء ظهور السلاجقة الغز قبل إسلامهم .","date":["العام الهجري :429","العام الميلادي :1037"],"text":"دخلَ رُكنُ الدين أبو طالبٍ طغرلبك محمد بن ميكائيل بن سلجوق مدينةَ نيسابور -شمال غرب أفغانستان- مالِكًا لها، وكان سببُ ذلك أنَّ الغزَّ السلجقيَّة لَمَّا ظهروا بخراسان أفسدوا، ونهبوا، وخرَّبوا البلاد، وسَبَوا، وسَمِعَ الملك مسعودُ بنُ محمود بن سبكتكين بخَبَرِهم، فسَيَّرَ إليهم حاجِبَه سباشي في ثلاثين ألف مقاتلٍ، فسار إليهم من غزنة، فلما بلغ خراسانَ أقام مدَّة سنة على المدافعة والمُطاولة، كان سباشي يَتْبعُ أثَرَهم إذا بعدوا، ويَرجِعُ عنهم إذا أقبلوا استعمالًا للمحاجزة، وإشفاقًا من المحاربة، حتى إذا كان في هذه السَّنة، وهو بقريةٍ بظاهر سرخس، والغز بظاهر مروٍ مع طغرلبك، وقد بلغَهم خبَرُه، فقاتلوه يومَ وصَلوا، فلما جنَّهم الليلُ أخذ سباشي ما خَفَّ مِن مالٍ وهَرَب في خواصِّه، وترك خِيَمَه ونيرانَه على حالها، قيل فعَلَ ذلك مواطأةً للغز (التركمان) على الهزيمةِ، فلمَّا أسفر الصبح عرف الباقونَ مِن عَسكَرِه خَبَرَه، فانهزموا، واستولى الغزُّ على ما وجدوه في مُعَسكرِهم مِن سوادهم، وقتلوا من الهنودِ الذين تخلَّفوا مقتلةً عظيمة، وأسرى داود أخو طغرلبك، وهو والِدُ السلطان ألب أرسلان، إلى نيسابور، وسَمِعَ أبو سهل الحمدوني ومن معه بها، ففارقوها، ووصل داود ومَن معه إليها، فدخلوها بغير قتال، ولم يُغَيِّروا شيئًا من أمورِها، ووصل بعدَهم طغرلبك ثمَّ وصَلَت إليهم رسُلُ الخليفةِ في ذلك الوقت، وكان قد أرسَلَ إليهم وإلى الذين بالريِّ وهمذان وبلد الجبل ينهاهم عن النَّهبِ والقتل والإخراب، فكَفُّوا عن ذلك، ثم استولَوا على سائِرِ بلاد خراسان سوى بلخٍ، وأقام طغرلبك بدارِ الإمارة، وجلس على سريرِ المَلِك مسعود، وصار يقعُدُ للمظالم يومينِ في الأسبوع على قاعدةِ ولاة خراسان, وكانوا يخطُبونَ للمَلِك مسعودٍ على سبيلِ المغالطة، وكانوا ثلاثة إخوة: طغرلبك، وداود، وبيغو، وكان ينال- واسمه إبراهيم- أخا طغرلبك وداودَ لأمِّهما."},{"id":1486,"title":"جلال الدَّولة البويهي يتسمى بـملك الملوك والعلماء ينكرون عليه .","date":["العام الهجري :429","العام الميلادي :1037"],"text":"سأل جلالُ الدَّولةِ البويهيُّ الشيعيُّ الخليفةَ القائمَ بأمرِ الله ليخاطَبَ بشاهِنشاه أي: ملك الملوك، فامتنع، ثمَّ أجاب إليه؛ إذ أفتى الفقهاءُ بجَوازِه، فكتب فتوى إلى الفُقَهاءِ في ذلك، فأفتى القاضي أبو الطيِّب الطبري، والقاضي أبو عبد الله الصيمري، والقاضي ابن البيضاوي، وأبو القاسم الكرخي بجوازِه، وامتنع منه قاضي القضاة أبو الحَسَن الماوردي، وجرى بينه وبين من أفتى بجوازه مراجعاتٌ، وخُطِبَ لجلالِ الدَّولة بمَلِك الملوك، وكان الماورديُّ مِن أخَصِّ الناسِ بجلال الدَّولة، وكان يتردَّدُ إلى دار المملكة كلَّ يوم، فلما أفتى بهذه الفُتيا انقطَعَ ولَزِمَ بيته خائِفًا، وأقام منقطعًا مِن شَهرِ رمضان إلى يوم عيدِ النحر، فاستدعاه جلالُ الدَّولة، فحضر خائفًا، فأدخله وَحْدَه وقال له: قد عَلِمَ كُلُّ أحد أنَّك من أكثَرِ الفقهاءِ مالًا وجاهًا وقربًا منا، وقد خالفْتَهم فيما خالفَ هوايَ، ولم تفعلْ ذلك إلَّا لعدمِ المحاباةِ منك، واتِّباعِ الحَقِّ، وقد بان لي مَوضِعُك من الدِّين، ومكانُك من العلمِ، وجعلتُ جزاءَ ذلك إكرامَك بأن أدخلتُك إليَّ، وجعلْتُ أذن الحاضرين إليك؛ ليتحَقَّقوا عودي إلى ما تحِبُّ، فشكره ودعا له."},{"id":1487,"title":"الفاطميون يهزمون شبل الدَّولةِ بن مرداس ويسيطرون على حلب .","date":["العام الهجري :429","العام الميلادي :1037"],"text":"عَهِدَ المُستنصر الفاطميُّ إلى القائد أنوشتكين الدزبري أميرِ دمشقَ بالاستيلاء على حَلَب وأخذها مِن شبل الدَّولةِ نصرِ بنِ صالح بن مرداس، فاستأذنَ الرومَ لحربهِ؛ لأنَّ شبلَ الدَّولة كان حليفًا للروم على دَفْعِ أتاوة سنويةٍ لهم، فتعهَّد أنوشتكين بدَفعِ نَفسِ الأتاوة للرُّومِ، إن هم أذنوا له بحَربِه، فأذنوا له فقام بالسَّيرِ إلى شبل الدَّولةِ وهَزَمه واستولى على حلَب، وقَتَل شبلَ الدَّولة."},{"id":1488,"title":"قيام دولة الصليحيين باليمن .","date":["العام الهجري :429","العام الميلادي :1037"],"text":"قامَت الدعوةُ الصُّلَيحيَّة باليمنِ والتي أصلها إسماعيليٌّ عن طريق علي بن محمد الصليحي. كانت الدعوةُ الإسماعيليَّةُ قد انقطعت في اليمَنِ بعد اختلافِ عليِّ بن الفضل وابن حوشب؛ إذ سيطَرَ الأوَّلَ على المنطقةِ وأعلن كُفرَه الصَّريحِ حتى مات مسمومًا عام 303هـ على حين اعتزل ابن حوشب في مغارب اليمن. حتى قامت الدعوةُ مُجدَّدًا على يدِ عليٍّ الصليحيِّ الذي كان أبوه محمَّدٌ مِن قضاة اليمن سُنِّي المذهب, وكان داعي الباطنيَّة عامِرُ بنُ عبد الله الزواخي يتردَّدُ على القاضي محمَّد الصليحي؛ لِمَنزلتِه وسُؤدَدِه، وكان عليٌّ حَدَثًا فتفَرَّس به عامِرٌ النجابةَ فاستمال قلبَه وشَوقَّه للمال والحُكمَ، وأسَرَّ إليه أمورًا سِرًّا من أبيه وأهله وهو لا يزالُ حدثًا, ثم لم ينشبْ عامر أنْ هلك فأوصى بكُتُبِه لعلي، فعكف الصليحي على دراستِها ومطالعتها، وكان ذكيًّا, ففقِه وتميَّزَ في رأي العُبَيدين الإسماعيليَّة، ومهر في تأويلاتهم، وقَلْبِهم للحقائقِ, ولَمَّا كان في سنة 429 ثار في رأس مسار، وهو أعلى ذروةٍ في جبال اليمن، وكان معه ستونَ رجلًا قد حالَفَهم بمكة في موسم سنة 428 على الموت والقيامِ بالدعوة، وما منهم إلَّا مَن هو مِن قَومِه وعشائِرِه في مَنعةٍ وعددٍ كثيرٍ، ولم يكنْ برأس الجبل المذكور بناءٌ، فقط كان فيه قلعةٌ منيعة عالية، ولم تمضِ عليه أشهرٌ حتى بناه وحَصَّنه وأتقَنَه. واستفحل أمرُ الصليحيِّ شيئًا فشيئًا، وكان يدعو للمستنصرِ صاحِبِ مصر، ويخافُ من نجاح صاحِبِ تهامةَ، وظلَّ يلاطِفُه ويستكينُ لأمره، وفي الباطِنِ يَعمَلُ الحيلةَ في قتله، ولم يَزَل به حتى قَتَله بالسُّمِّ."},{"id":1489,"title":"الخطبة العباسية بحران والرقة .","date":["العام الهجري :430","العام الميلادي :1038"],"text":"خطبَ شبيب بن وثاب النميريُّ، صاحِبُ حران والرَّقَّة، للخليفةِ القائم بأمر الله، وقطَعَ خُطبةَ المستنصر بالله العُبَيديُّ، وكان سببُها أنَّ نَصرَ الدَّولة بنُ مروان كان قد بلغه عن الدزبري نائبُ العلويين بالشام أنَّه يتهَدَّده، ويريد قصدَ بلاده، فراسل ابنُ مروان قرواشًا، صاحِبَ الموصل، وطلب منه عسكرًا، وراسل أيضًا شبيبًا النميري يدعوه إلى المُوافقة، ويُحَذِّرُه من المغاربةِ العُبَيديِّين، فأجابه إلى ذلك، وقطعَ الخُطبةَ العَلَويَّة، وأقام الخُطبةَ العباسيَّة، فأرسل الدزبري إلى شبيب يتهدَّدُه، ثم أعاد الخطبةَ العَلَوية بحرَّانَ في ذي الحجَّة من السَّنة."},{"id":1490,"title":"وفاة الحافظ أبي نعيم الأصبهاني .","date":["العام الهجري :430","الشهر القمري : محرم","العام الميلادي :1038"],"text":"هو الإمامُ الثِّقةُ العلَّامة، شيخُ الإسلامِ: أبو نُعَيم، أحمدُ بنُ عبدِ اللهِ بنِ أحمد بن إسحاقَ بنِ موسى بن مهران، الأصبهاني الحافظ المشهور، الصوفيُّ، الأحول، سبطُ الزاهد محمد بن يوسف البنَّاء، وصاحب \"الحِلْية\". وُلِدَ سنة ست وثلاثين وثلاثمِئَة. كان أبوه من عُلَماءِ الحديثِ والرحَّالين، من أعلامِ المحدِّثين وأكابِرِ الثقاتِ الحُفَّاظ، رحلَ إلى العراقِ والحجاز وأصفهان، قال أحمدُ بنُ محمد بن مردويه: \"كان أبو نُعَيم في وقته مرحولًا إليه، ولم يكُنْ في أفُقْ مِن الآفاقِ أسنَدُ ولا أحفَظُ منه، كان حُفَّاظُ الدنيا قد اجتمعوا عنده، فكان كلَّ يومٍ نَوبةُ واحد منهم يقرأُ ما يريده إلى قُريبِ الظَّهر، فإذا قام إلى داره، ربما كان يُقرأُ عليه في الطريق جزءٌ، وكان لا يضجَرُ، لم يكن له غداءٌ سوى التصنيف والتسميع\". وقال حمزةُ بنُ العباس العلوي: \"كان أصحابُ الحديثِ يقولون: بقيَ أبو نُعَيم أربعَ عشرةَ سنةً بلا نظيرٍ، لا يوجَدُ شَرقًا ولا غربًا أعلى منه إسنادًا، ولا أحفَظَ منه\". أشهَرُ مُصنَّفاته (حِليةُ الأولياء) وله (مُعجم الصحابة) وغيرها من الكتب، توفِّي في أصبهان عن 96 عامًا."},{"id":1491,"title":"دخول السلاجقة في الإسلام .","date":["العام الهجري :430","الشهر القمري : جمادى الآخرة","العام الميلادي :1039"],"text":"كان جَدُّ السلاجقةِ بغاق من مشايخِ التُّركِ القُدَماء، الذين لهم رأيٌ ومَكيدة ومكانةٌ عند مَلِكهم الأعظَم، ونشأ ولدُه سلجوق نجيبًا شَهمًا، فقَدَّمه المَلِك ولقَّبه شباسي، فأطاعَتْه الجيوشُ وانقاد له النَّاسُ بحيث تخوَّفَ منه المَلِك وأراد قَتْلَه، فهرب منه إلى بلادِ المسلمين، فلمَّا خالط المسلمينَ أسلم فازداد عِزًّا وعلُوًّا، ثم توفِّيَ عن مِئَة وسبع سنين، وخلَّف من الأبناء أرسلان وميكائيل وموسى، فأمَّا ميكائيل فإنه اعتنى بقتالِ الكُفَّار من الأتراك، حتى قُتِلَ شَهيدًا، وخَلَّفَ ولديه طغرلبك محمد، وجعفر بك داود، فعَظُم شأنُهما في بني عَمِّهما، واجتمع عليهما التركُ مِن المؤمنين، وهم تُركُ الإيمانِ الذين يقول لهم النَّاسُ ترُكمان، وهم السَّلاجقة بنو سلجوق."},{"id":1492,"title":"الملك مسعود الغزنوي يَهزم الملك طغرلبك السلجوقي .","date":["العام الهجري :430","الشهر القمري : شعبان","العام الميلادي :1039"],"text":"في صَفَر مِن هذه السنة وصَلَ المَلِك مسعود إلى بلْخ من غزنة، فجمع أصحابَه، ولقِيَ إسماعيلَ شاه مَلِكَ خوارزم، وقاتله، ودامت الحربُ بينهما مُدَّةَ شَهر، وانهزم إسماعيلُ، والتجأ إلى طغرلبك وأخيه داود السلجقيَّة، ثم سار مسعودُ بن سبكتكين من بلخ بنفسِه، وقصد سرخس، فتجَنَّب الغزُّ لقاءه، وعدلوا إلى المُراوغة والمُخاتلة، وأظهر الغُزُّ العزمَ على دخول المفازة التي بين مروٍ وخوارزمَ، فبينما عساكِرُ مسعودٍ تَتْبَعُهم وتَطلُبُهم إذ لَقُوا طائفةً منهم، فقاتلوهم وظَفِروا بهم وقتلوا منهم، ثمَّ إنه واقعهم بنفسه في شعبان من هذه السنة وقعةً استظهَرَ فيها عليهم، فأبعدوا عنه، ثم عاودوا القُربَ منه بنواحي مرو، فواقعوهم وقعةً أخرى قُتِلَ مِن الغز التركمان فيها نحوُ ألف وخمسمِئَة قتيل، وهرب الباقون فدخلوا البرِّيَّة التي يحتَمون بها، وثار أهلُ نيسابور بمن عندهم منهم، فقَتَلوا بعضًا، وانهزم الباقونَ إلى أصحابِهم بالبرِّيَّة وعدل مسعودٌ إلى هراة؛ ليتأهَّبَ في العساكِرِ للمسير خلْفَهم وطَلَبِهم أينما كانوا، فعاد طغرلبك إلى الأطرافِ النائية عن مسعود، فنهَبَها وأثخنَ فيها، فحينئذ سار مسعودٌ يَطلُبُه، فلما قاربَه انزاح طغرلبك من بينِ يديه إلى أستوا وأقام بها، وكان الزمانُ شِتاءً، ظنًّا منه أنَّ الثَّلجَ والبردَ يَمنَعُ عنه، فطلبه مسعودٌ إليها، ففارقه طغرلبك وسلك الطريقَ على طوس، واحتمى بجبالٍ منيعة، ومضايقَ صَعبةِ المسلك، فسَيَّرَ مسعود في طلبه وزيرَه أحمد بن محمد بن عبد الصمد في عساكِرَ كثيرة، فطوى المراحِلَ إليه جريدةً- الجريدة: خَيْلٌ لا رَجَّالةَ فيها-, فواقعوهم الغُزُّ وانتصروا على الوزير وعسكَرِه، واستأمن من أصحابِه جماعةً كثيرةً، ورأى الوزيرُ الطلَبَ له من كل جانبٍ، فعاود دخولَ المفازة إلى خوارزمَ وأوغل فيها، فلمَّا فارق الغز خراسان قصد مسعود جبلًا مِن جبال طوس منيعًا لا يُرام، وكان أهلُ الجبل قد وافقوا الغُزَّ وأفسدوا معهم، فلمَّا فارق الغزُّ تلك البلاد تحصَّنَ هؤلاء بجَبَلِهم ثقةً منهم بحصانتِه وامتناعه، فسرى مسعود إليهم جريدةً، فلم يَرُعْهم إلَّا وقد خالطهم، فتركوا أهلَهم وأموالَهم وصَعِدوا إلى قِمَّة الجبَلِ واعتَصَموا بها وامتَنَعوا، وغَنِمَ عسكَرُ مسعود أموالَهم وما ادَّخَروه. ثمَّ أمر مسعودٌ أصحابَه أن يزحَفوا إليهم في قمَّة الجبل، وباشَرَ هو القتالَ بنَفسِه، فزحَفَ النَّاسُ إليهم، وقاتلوهم قتالًا لم يَرَوا مثله، وكان الزمانُ شتاءً، والثلجُ على الجبلِ كثيرًا، فهلك من العسكر في مخارمِ الجَبَلِ وشِعابِه كثيرٌ، ثمَّ إنهم ظَفِروا بعسكر طغرلبك وأكثَروا فيهم القتلَ والأسرَ، وفرَغوا منهم، وأراحوا المسلمينَ مِن شَرِّهم. ثمَّ سار مسعود إلى نيسابور في جمادى الأولى سنة 431، ليريحَ ويستريحَ، وينتظِرَ الربيعَ ليسيرَ خَلْفَ الغز، ويطلُبَهم في المفاوزِ التي احتَمَوا بها."},{"id":1493,"title":"ما جرى بعُمان بعد موت أبي القاسم بن مكرم .","date":["العام الهجري :431","العام الميلادي :1039"],"text":"لَمَّا توفِّيَ أبو القاسمِ بنُ مكرم صاحِبُ عُمان خلَّف أربعةَ بنينَ، وهم أبو الجيش، والمهذَّب، وأبو محمد، وآخرُ صغيرٌ، فوَلِيَ بعده ابنُه أبو الجيش، وأقَرَّ عليَّ بن هطال المنوجاني، صاحِبَ جيش أبيه، وكان المهذَّب، يَطعنُ على ابنِ هطال، وبلغه ذلك، فأضمَرَ له سوءًا، فجهَّزَ له مكيدةً وجعله يكتُبُ بخَطِّه ما أظهَرَه ابنُ هطال عند أبي الجيش، وقال له: إنَّ أخاك كان قد أفسد كثيرًا من أصحابِك عليك، وتحَدَّث معي، واستمالني فلم أوافِقْه؛ فلهذا كان يذمُّني، ويقع فيَّ، وهذا خَطُّه بما استقَرَّ- يعني من أنَّه سيمنَحُه الوَزارةَ وغَيرَها إن مَكَّنَه من الأمرِ- فلمَّا رأى خطَّ أخيه أمَرَه بالقبض عليه، ففعل ذلك واعتقَلَه، ثمَّ وضَعَ عليه من خنَقَه وألقى جُثَّتَه إلى مُنخَفضٍ مِن الأرض، وأظهَرَ أنَّه سقط فمات، ثم توفِّي أبو الجيشِ بعد ذلك بيسيرٍ، وأراد ابن هطال أن يأخُذَ أخاه أبا محمَّدٍ فيولِّيَه عمان ثمَّ يقتُلَه، فلم تُخرِجْه إليه والدتُه، وقالت له: أنت تتولَّى الأمور، وهذا صغيرٌ لا يَصلُحُ لها. ففعل ذلك، وأساء السِّيرةَ، وصادر التجَّار، وأخذ الأموالَ، وبلغ ما كان منه مع بني مكرم إلى المَلِك أبي كاليجار البويهي، والعادِل أبي منصور ابنِ مافنة، فأعظما الأمر واستكبَراه، وشَدَّ العادِلُ في الأمر، وكاتَبَ نائبًا كان لأبي القاسِمِ بنِ مكرم بجبالِ عُمان يُقالُ له المرتضى، وأمَرَه بقصد ابن هطال، وجَهَّز العساكِرَ مِن البصرة لتسيرَ إلى مساعدةِ المرتضى، فجمَعَ المرتضى الخَلقَ، وتسارعوا إليه وخرجوا عن طاعةِ ابن هطال، وضَعُف أمرُه، واستولى المرتضى على أكثَرِ البلاد، ثمَّ وضعوا خادمًا كان لابنِ مكرم، وقد التحَقَ بابنِ هطال؛ لقَتْلِه، وساعَدَه على ذلك فَرَّاش كان له، فلمَّا سمع العادل بقَتلِ ابن هطال سيَّرَ إلى عُمان من أخرج أبا محمد بن مكرم، ورتبَه في الإمارةِ، وكان قد استقَرَّ أنَّ الأمر لأبي محمد في هذه السَّنة."},{"id":1494,"title":"شغب الأتراك على جلال الدَّولة البويهي .","date":["العام الهجري :431","العام الميلادي :1039"],"text":"شَغبَ الأتراكُ على الملك جلال الدَّولة البويهي ببغداد، وأخرجوا خيامَهم إلى ظاهِرِ البلد، ثمَّ أوقعوا النَّهبَ في عِدَّةِ مواضِعَ، فخافهم جلالُ الدَّولة، فغَيَّرَ خيامَه إلى الجانبِ الغربيِّ، وتردَّدَت الرسُلُ بينهم في الصُّلحِ، وأراد الرَّحيلَ عن بغداد، فمنَعَه أصحابُه، فراسل دبيس بن مزيد، وقرواشًا صاحِبَ الموصل، وغيرهما، وجمع عنده العساكِرَ، فاستقَرَّت القواعِدُ بينهم وعاد إلى داره، وطَمِعَ الأتراك، وآذَوُا النَّاسَ، ونهبوا وقتلوا، وفسَدَت الأمورُ بالكليَّةِ إلى حَدٍّ لا يُرجى صلاحُه."},{"id":1495,"title":"وفاة محمد بن حسن بن الهيثم  .","date":["العام الهجري :431","العام الميلادي :1039"],"text":"هو الفيلسوفُ أبو عليٍّ محمَّدُ بنُ الحَسَن بن الهيثم البصري أصلُه بصري، سكن الديارَ المصريَّةَ إلى أن مات. كان من أذكياءِ بني آدم، عديمَ النظيرِ في عَصرِه في العلمِ الرياضي. وكان متزهِّدًا زُهدَ الفلاسفة. لخَّص كثيرًا من كتُبِ جالينوس، وكثيرًا مِن كتب أرسطوطاليس. وكان رأسًا في أصول الطبِّ وكليَّاتِه. وكان قد وَزَر في أوَّل أمرِه، ثمَّ تزهَّد وأظهر الجنونَ، وكان مليحَ الخطِّ يَنسَخُ في بعضِ السَّنةِ ما يكفيه لعامِه من إقليدس والمجسطي. قال عنه الذهبي: \"صاحِبُ المصنَّفات الكثيرةِ في علوم الأوائِلِ، وكان مقيمًا بالجامِعِ الأزهر, وهو على اعتقادِ الأوائِلِ لا رَحِمَهم الله, وقد صَرَّحَ بذلك نسألُ اللهَ العافيةَ\" وله مُصَنَّفات كثيرة مُعظَمُها في الرياضيَّات والهندسة، وباقيها في الإلهيَّات، وعامتها مقالاتٌ صغار. قال ابن خلدون: \" أشهَرُ مَن ألَّف في عِلمِ المناظرةِ مِن فروعِ الهندسة ابنُ الهيثم, وهو عِلمٌ يتبيَّنُ به أسبابُ الغلَطِ في الإدراك البصريِّ بمعرفةِ كيفيَّة وقوعِها بناءً على أنَّ إدراكَ البصر يكون بمخروط شعاعيٍّ رأسُه نقطةُ الباصِرِ وقاعدتُه المرئيُّ. ثمَّ يقع الغلَطُ كثيرًا في رؤية القريبِ كبيرًا والبعيدِ صغيرًا. وكذا رؤية الأشباح الصَّغيرة تحت الماء ووراء الأجسامِ الشَّفَّافةِ كبيرةً، ورؤيةُ النُّقطة النَّازلة من المطَرِ خطًّا مستقيمًا والسّلقة دائرة وأمثال ذلك. فيتبيَّنُ في هذا العلم أسبابُ ذلك وكيفيَّاته بالبراهينِ الهندسيَّة، ويتبيَّن به أيضًا اختلافُ المنظَرِ في القمَرِ باختلاف العَروضِ الذي يُبنى عليه معرفةُ رؤية الأهِلَّة وحصول الكُسوفات.\"."},{"id":1496,"title":"انتصار السلاجقة على جيش الدَّولة الغزنوية في معركة دندانكان .","date":["العام الهجري :431","الشهر القمري : رمضان","العام الميلادي :1040"],"text":"انتصرَ السُّلطانُ السلجوقيُّ طغرلبك على جيشِ الدَّولة الغزنويَّة في معركةِ دندانكان، واستولى على خراسان، وأجبَرَ الغزنويِّينَ على الاعترافِ بالدَّولة السلجوقيَّةِ كأكبَرِ وأقوى دولةٍ في المنطقةِ."},{"id":1497,"title":"ابتداء ملك السلاجقة .","date":["العام الهجري :432","العام الميلادي :1040"],"text":"عَظُمَ شأنُ السلجوقيَّة، وارتفع شأنُ مَلِكِهم طغرلبك، وأخيه داود، وهما ابنا ميكائيلَ بنِ سلجوق بن بغاق، بعد أن أسلموا ووالاهم من أسلَمَ مِن التُّركِ فأخذوا بلاد خراسانَ بكمالها بعد موتِ محمودِ بنِ سبكتكين، وقد كان يتخَوَّف منهم محمود بعضَ التخَوُّف، فلمَّا مات وقام ولَدُه مسعودٌ بعده قاتَلَهم وقاتلوه مرارًا، فكانوا يَهزِمونَه في أكثَرِ المواقف، واستكمل لهم مُلكُ خراسان بأسرِها، وكَمَل لهم جميعُ ما أمَّلوه، ثمَّ كان مِن سعادتِهم ما حصل مِن قَتلِ مسعودِ بنِ محمود الغزنويِّ وتولِّي أخيه محمَّد، ثم القتال الذي حصل بين الإخوةِ والعَمِّ، فكان هذا من جملةِ ما وطَّدَ لِمُلك السلاجقةِ في المنطقة."},{"id":1498,"title":"مقتل الملك مسعود الغزنوي وتولي أخيه محمد من بعده .","date":["العام الهجري :432","العام الميلادي :1040"],"text":"سار مسعودٌ يريدُ بلادَ الهندِ لِيشْتُوا بها، فلمَّا سار أخَذَ معه أخاه محمَّدًا مسمولَ العينينِ، واستصحَبَ الخزائِنَ، وكان عازمًا على الاستنجادِ بالهندِ على قتال السلجوقيَّة ثِقةً بعهودهم. فلمَّا عَبَرَ سيحون- وهو نهرٌ كبيرٌ نحو دِجلة- وعبَرَ بعض الخزائِنِ، اجتمع أنوشتكين البلخي وجمعٌ من الغلمانِ الداريَّةِ ونهبوا ما تخلَّفَ من الخزانةِ، وأقاموا أخاه محمَّدًا 13 ربيع الآخر، وسَلَّموا عليه بالإمارةِ، فامتنع من قَبولِ ذلك، فتهَدَّدوه وأكرهوه، فأجاب وبَقِيَ مسعودٌ فيمن معه من العسكَرِ وحَفِظَ نَفسَه، فالتقى الجمعانِ مُنتصَفَ ربيعٍ الآخر، فاقتتلوا، وعَظُمَ الخطبُ على الطائفتينِ، ثم انهزمَ عسكَرُ مسعود، وتحصَّن هو في رباطِ ماريكلة، فحصره أخوه، فامتنع عليه، فقالت له أمُّه: إنَّ مكانَك لا يَعصِمُك، ولَأنْ تخرُجَ إليهم بعهدٍ خَيرٌ من أن يأخذوك قهرًا. فخرج إليهم، فقَبَضوا عليه، فقال له أخوه محمد: واللهِ لا قابلْتُك على فِعلِك بي-  كان مسعودٌ قد سمَلَ عينيه ونزع منه الحُكمَ-، ولا عامَلتُك إلَّا بالجميلِ، فانظُرْ أين تريدُ أن تقيمَ حتى أحمِلَك إليه ومعك أولادُك وحرَمُك. فاختار قلعة كيكي، فأنفذه إليها محفوظًا، وأمر بإكرامِه وصيانتِه، ثمَّ إن محمدًا فوَّضَ أمرَ دولتِه إلى ولَدِه أحمد، وكان فيه خبطٌ وهَوجٌ، فاتَّفق هو وابنُ عمه يوسف بن سبكتكين وابنُ علي خويشاوند على قَتلِ مسعود ليصفُوَ المُلكُ له ولوالِدِه، فقتلوه، فلمَّا عَلِمَ محمَّد بذلك ساءه، وشَقَّ عليه وأنكره، وقيل إنَّ محمَّدًا أغراه ولَدُه أحمد بقَتلِ عَمِّه مسعود، فأمر بذلك، وأرسل إليه مَن قتَلَه وألقاه في بئرٍ وسَدَّ رأسَها، وقيل: بل أُلقِيَ في بئرٍ حيًّا وسُدَّ رأسُها فمات، فلمَّا مات كتب محمَّدٌ إلى ابن أخيه مودود، وهو بخراسان، يقول: إنَّ والدك قُتِلَ قِصاصًا، قتله أولادُ أحمد ينالتكين بلا رضًا مني، وطَمِعَ جندُ محمد فيه، وزالت عنهم هيبتُه، فمَدُّوا أيديَهم إلى أموالِ الرَّعايا فنهبوها، فخَرِبَت البلاد، فلمَّا قُتِلَ الملكُ مسعود وصل الخبَرُ إلى ابنه مودود، وهو بخراسان، فعاد مجِدًّا في عساكِرِه إلى غزنةَ، فتصافَّ هو وعَمُّه محمد في ثالث شعبان، فانهزم محمَّدٌ وعسكَرِه وقُبِضَ عليه وعلى ولدِه أحمد، وأنوشتكين الخصِيِّ البلخي، وابنِ علي خويشاوند، فقَتَلَهم، وقتَلَ أولادَ عَمِّه جميعَهم إلَّا عبد الرحيم, وبنى موضِعَ الوقعةِ قريةً ورِباطًا، وسمَّاها فتح آباذ، وعاد إلى غُزنةَ فدخلها في ثالث وعشرين شعبان، وكان داودُ أخو طغرلبك قد ملك مدينةَ بلخ، واستباحها، فلمَّا تجدَّدَ هذا الظَّفَرُ لمودود ثار أهلُ هراة بمن عندهم من الغزِّ السلجوقيَّة، فأخرجوهم وحَفِظوها لمودود، واستقَرَّ الأمرُ لمودود بغزنةَ، ولم يبقَ له همٌّ إلا أمرُ أخيه مجدود؛ فإنَّ أباه قد سيَّرَه إلى الهند سنةَ ستٍّ وعشرين وأربعمِئَة، فخاف أن يخالِفَ عليه، فأتاه خبَرُه أنَّه قصَدَ لهاوور، وملتان، فملكهما، وأخذ الأموالَ، وجمع بها العساكِرَ، وأظهر الخلافَ على أخيه، فندب إليه مودودٌ جيشًا ليمنعوه ويقاتِلوه، وعَرَض مجدودٌ عَسكَرَه للمَسيرِ، وحضر عيدُ الأضحى، فبَقِيَ بعده ثلاثة أيام، وأصبح ميتًا بلهاوور لا يُدرى كيف كان مَوتُه، وأطاعت البلادُ بأسرِها مودودًا، ورَسَت قدمُه، وثَبَت مُلكُه، ولَمَّا سَمِعَت الغز السلجوقيَّةُ ذلك خافوه، واستشعروا منه، وراسله مَلِكُ التُّركِ بما وراء النَّهرِ بالانقيادِ والمتابعة."},{"id":1499,"title":"قتال الروم مع عساكر مصر .","date":["العام الهجري :432","العام الميلادي :1040"],"text":"كان مَلِكُ الرومِ قد هادنَه المُستَنصِرُ بالله الفاطميُّ صاحِبُ مصر، ثمَّ أخذ يراسِلُ ابنَ صالحِ بن مرداس ويستميلُه، وراسله قبله صالحٌ ليتقَوَّى به على الدزبري صاحب دمشق للفاطميين؛ خوفًا أن يأخُذَ منه الرقَّةَ، فبلغ ذلك الدزبري فتهَدَّد ابنَ صالح فاعتذر وجَحَد، ثمَّ إنَّ جمعًا من بني جعفرِ بنِ كلاب دخلوا ولايةَ أفامية، فعاثوا فيها، ونهَبوا عدَّةَ قُرًى، فخرج عليهم جمعٌ مِن الروم فقاتَلوهم وأوقعوا بهم، ونكَّلوا فيهم، وأزالوهم عن بلادِهم، وبلغ ذلك الناظِرَ بحَلَب، فأخرج مَن بها من تجَّار الفرنج، وأرسلَ إلى المتولِّي بأنطاكيةَ يأمُرُه بإخراجِ مَن عِندَهم مِن تجَّار المسلمين، فأغلظ للرَّسولِ، وأراد قتْلَه، ثمَّ ترَكَه، فأرسل الناظِرُ بحَلَب إلى الدزبري يعَرِّفُه الحال، وأنَّ القومَ على التجهُّزِ لقصد البلاد، فجَهَّزَ الدزبري جيشًا وسيَّرَه على مقَدِّمته، فاتَّفَق أنَّهم لقُوا جيشًا للرُّوم وقد خرجوا لِمثلِ ما خرج إليه هؤلاء، والتقى الفريقانِ بين مدينة حماة وأفامية، واشتَدَّ القتالُ بينهم، ثمَّ إنَّ الله نصرَ المسلمينَ، وأذلَّ الكافرين، فانهزموا وقُتِلَ منهم عِدَّةٌ كثيرة، وأُسِرَ ابنُ عمٍّ للمَلِك، بذلوا في فدائِه مالًا جزيلًا، وعِدَّةً وافرةً مِن أسرى المسلمين، وانكَفَّ الرومُ عن الأذى بعدها."},{"id":1500,"title":"طغرلبك السلجوقي يسيطر على مدينة جرجان وطبرستان .","date":["العام الهجري :433","العام الميلادي :1041"],"text":"ملَكَ طغرلبك السلجوقي جرجان وطبرستان، وسبَبُ ذلك أنَّ أنوشروان ابنَ منوجهر بن قابوس بن وشمكير صاحبها، قبض على أبي كاليجار بن ويهان القوهي، صاحِبِ جيشِه، وزَوجِ أمِّه بمساعدةِ أمِّه عليه، فعَلِمَ حينئذ طغرلبك أنَّ البلادَ لا مانع له عنها، فسار إليها، وقصَدَ جرجان ومعه مرداويج بن بسو، فلمَّا نازلها فتح له المقيمُ بها، فدخلها وقرَّرَ على أهلِها مِئَة ألف دينار صُلحًا، وسَلَّمَها إلى مرداويج بن بسو، وقرَّرَ عليه خمسين ألف دينار كل سنةٍ عن جميعِ الأعمال، وعاد إلى نيسابور، وقصَدَ مرداويج أنوشروان بسارية، وكان بها، فاصطَلَحا على أنْ ضَمِنَ أنوشروان له ثلاثينَ ألف دينار، وأُقيمَت الخُطبةُ لطغرلبك في البلادِ كلِّها، وتزوَّج مرداويج بوالدة أنوشروان، وبقي أنوشروان يتصَرَّف بأمرِ مرداويج لا يخالِفُه في شيءٍ البتَّة."},{"id":1501,"title":"معز الدَّولة الكلابي ينتزع الشام من يد العبيديين (الفاطميين) .","date":["العام الهجري :433","العام الميلادي :1041"],"text":"فسَدَ أمرُ أنوشتكين الدزبري، نائبِ المستنصِرِ بالله الفاطميِّ، صاحِبِ مصر، بالشَّام، وكان الوزيرُ أبو القاسم الجرجرائي يقصِدُه ويَحسدُه، إلَّا أنَّه لا يجِدُ طريقًا إلى الوقيعةِ فيه، وأحسَّ الدزبري بما يجري، فأظهر ما في نفسِه، وأحضر نائبَ الجرجرائي عنده، وأمر بإهانتِه وضَرْبِه، ثمَّ إنه أطلق لطائفةٍ مِن العسكَرِ يَلزَمونَ خِدمَتَه أرزاقَهم، ومنع الباقينَ، فحَرَّك ما في نُفوسِهم، وقوِيَ طَمَعُهم فيه، بما كوتبوا به من مِصرَ، فأظهروا الشَّغبَ عليه، وقصَدوا قصْرَه، وهو بظاهِرِ البلد، وتَبِعَهم من العامَّة من يريد النَّهبَ، فاقتتلوا، فعَلِمَ الدزبري ضَعْفَه وعَجْزَه عنهم، ففارق مكانَه، وسار إلى بعلبك، فمنعه مستحفِظُها، وأخذ ما أمكَنَه أخذُه مِن مال الدزبري، وتَبِعَه طائفةٌ من الجند يَقفُونَ أثره، وينهبون ما يَقدِرونَ عليه، وسار الدزبري إلى مدينةِ حماة، فمُنِعَ عنها، وقُوتِلَ، وكاتب المقَلَّد الكناني الكفرطابي، واستدعاه، فأجابه وحضر عنده في نحو ألفَي رجلٍ مِن كفرطاب وغيرها، فاحتمى به، وسار إلى حلب، ودخلها، وأقام بها مُدَّةً، وتوفي في منتصَفِ جمادى الأولى من هذه السنة، فلما توفِّيَ فسدَ أمر بلاد الشام، وزال النِّظامُ، وطَمِعَت العرب، وخرجوا في نواحيه، فخرج حَسَّان بن المفرج الطائي بفلسطين، وخرج مُعِزُّ الدَّولة بن صالح الكلابي بحَلَب، وقصَدَها وحصرها، ومَلَك المدينةَ، وامتنع أصحابُ الدزبري بالقلعة، وكتبوا إلى مصرَ يَطلُبونَ النجدة، فلم يفعلوا، واشتغَلَ عَساكِرُ دمشق ومُقَدَّمُهم الحسين بن أحمد الذي ولي أمرَ دمشق، بعد الدزبري، بحَربِ حسَّان، ووقع الموت في الذين في القَلعةِ، فسَلَّموها إلى مُعِزِّ الدَّولة بالأمانِ."},{"id":1502,"title":"وفاة حمزة الزوزني كبير مؤسسي الدعوة الدرزية .","date":["العام الهجري :433","العام الميلادي :1041"],"text":"هو حَمزةُ بنُ عليِّ بنِ أحمد الفارسي الزوزني، مِن كبارِ الباطنيَّة، ويُعتبَرُ مُؤَسِّسَ المذهَبِ الدرزي وواضِعَ أُسُسِه وعقائِدِه، اتَّصَل بمصرَ برجالِ الدعوة السِّرِّية من شيعة الحاكِمِ بأمر الله الفاطمي العُبَيدي، نادى بالتقَمُّص والحلول مع محمد بن إسماعيلَ الدرزي، أظهر الدعوةَ بألوهيَّةِ الحاكم وأنَّ الإلهَ قد حلَّ فيه، جعله الحاكِمُ داعيَ الدُّعاة، ولَمَّا قُتِلَ الحاكِمُ غادر حمزةُ مصر إلى الشام ونشر فيها مذهَبَه، فعُرِفَ أتباعُه بالدروز ويتَسَمَّونَ بالموحِّدين أيضًا، ويُعتبَرُ حَمزةُ هذا هو قائِمَ الزمانِ وآخِرَ من حل فيه العقلُ الإلهيُّ وهو الواضِعُ لأركان الدينِ عندهم."},{"id":1503,"title":"استيلاء طغرلبك على البلدان الشرقية خوارزم وما جاورها .","date":["العام الهجري :434","العام الميلادي :1042"],"text":"سار طغرلبك إلى خوارزم فحصرها وملكها واستولى عليها، وانهزم شاه ملك بين يديه، واستصحَبَ أموالَه وذخائِرَه، ومضى في المفازةِ إلى دهستان، ثم انتَقَل عنها إلى طبس، ثمَّ إلى أطراف كرمان، ثمَّ إلى عمال التيز ومكران، فلمَّا وصَلَ إلى هناك عَلِمَ خلاصَه ببُعدِه، وأمِنَ في نفسه، ثمَّ خرجَ طغرلبك من خراسانَ إلى الريِّ بعد فراغِه مِن خوارزم، وجرجان، وطبرستان، فلمَّا سَمِعَ أخوه إبراهيمُ ينال بقدومِه سار إليه فلَقِيَه، وتسَلَّم طغرلبك الريَّ منه، وتسَلَّمَ غيرَها من بلد الجبل وسار إبراهيمُ إلى سجستان، وأخذ طغرلبك أيضًا قلعةَ طبرك من مجدِ الدَّولة بن بُوَيه، وأقام عنده مُكَرَّمًا، وأمَرَ طغرلبك بعمارةِ الرَّيِّ وكانت قد خَرِبَت، ثمَّ ساروا إلى قزوين، فامتنعَ عليه أهلُها، فزحف إليهم ورماهم بالسِّهامِ والحجارة، فلم يَقدِروا أن يَقِفوا على السورِ، وقُتِلَ مِن أهل البلد برشق، وأخذ ثلاثَمِئَة وخمسين رجلًا، فلمَّا رأى كامرو ومرداويج بن بسو ذلك خافوا أن يملِكَ البلد عَنوةً ويَنهَب، فمنعوا الناسَ مِن القتال، وأصلحوا الحالَ على ثمانينَ ألف دينار، وصار صاحبُها في طاعته، ثمَّ إنه أرسل إلى كوكتاش وبوقا وغيرهما من أمراء الغز، الذين تقَدَّم خروجُهم، يُمَنِّيهم ويدعوهم إلى الحضورِ في خدمته، وأرسل طغرلبك إلى ملك الديلمِ يدعوه إلى الطاعة، ويطلُبُ منه مالًا، ففعل ذلك، وحَمَل إليه مالًا وعُروضًا، وأرسل أيضًا إلى سلار الطرم يدعوه إلى خدمتِه، ويطالبُه بحمل مِئَتي ألفِ دينار، فاستَقَرَّ الحالُ بينهما على الطاعةِ وشَيءٍ مِن المال. وأرسلَ سَريَّةً إلى أصبهان، وبها أبو منصور فرامرز بن علاء الدَّولة، فأغارت على أعمالِها وعادت سالِمةً، وخرج طغرلبك من الريِّ، وأظهر قصدَ أصبهان، فراسلَه فرامرز، وصانَعَه بمالٍ، فعاد عنه وسار إلى همذان فمَلَكَها من صاحِبِها كرشاسف بن علاء الدَّولة، ثمَّ عاد إلى الريِّ، واستناب بهمذان ناصرًا العَلويَّ، وسَيَّرَ طغرلبك طائفةً من أصحابِه إلى كرمان مع أخيه إبراهيم ينال، بعد أن دخل الريَّ، وقيل إنَّ إبراهيمَ لم يقصِدْ كرمان، وإنَّما قصد سجستان، وكان مُقَدَّم العساكِرِ التي سارت إلى كرمان غيره، فلما وصلوا إلى أطراف كرمان نَهَبوا، ولم يُقدِموا على التوغُّلِ فيها، فلم يَرَوا من العساكِرِ مَن يَكُفُّهم، فتوسَّطوا ومَلَكوا عِدَّةَ مواضعَ منها ونَهَبوها، فبلغ الخبَرُ إلى الملك أبي كاليجار، صاحِبِها، فسَيَّرَ وزيرَه مُهذَّب الدَّولة في العساكِرِ الكثيرة، فخرجت الغزُّ إلى الجِمالِ والبغال والميرة ليأخُذوها، وسَمِعَ مهذَّب الدَّولة ذلك، فسيَّرَ طائفةً مِن العسكر لمنعِهم، فتواقعوا واقتَتلوا، وتكاثرَ الغز، فسَمِعَ مُهَذَّب الدَّولة الخبَرَ، فسار في العساكِرِ إلى المعركة، وهم يقتَتِلون، وقد ثبَتَت كل طائفة لصاحبتِها واشتَدَّ القتال، فلما وصل مهذَّب الدَّولة إلى المعركة انهزم الغُزُّ وتركوا ما كانوا ينهَبونَه، ودخلوا المفازةَ، وتَبِعَهم الديلم إلى رأسِ الحدِّ، وعادوا إلى كرمان فأصلحوا ما فسَدَ منها."},{"id":1504,"title":"خلاف بين الخليفة القائم بأمرِ الله وجلال الدَّولة البويهي .","date":["العام الهجري :434","العام الميلادي :1042"],"text":"افتُتِحَت الجوالي –أموال الجزية- في المحَرَّم ببغداد، فأنفذ الملِكُ جلال الدَّولة البويهي فأخذ ما تحصَّلَ منها، وكانت العادةُ أن يُحمَلَ منها إلى الخُلفاءِ لا تُعارِضُهم فيها الملوك، فلمَّا فَعَل جلالُ الدَّولة ذلك، عَظُمَ الأمرُ فيه على القائِمِ بأمرِ الله واشتَدَّ عليه، وأرسَلَ مع أقضى القُضاة أبي الحسن الماوَردي في ذلك، وتكَرَّرت الرَّسائلُ، فلم يُصْغِ جلالُ الدَّولة لذلك، وأخذ الجواليَ، فجمع الخليفةُ الهاشميِّينَ بالدارِ والرجَّالة، وأرسل إلى أصحابِ الأطرافِ والقُضاة بما عزَمَ عليه، وأظهر العَزمَ على مفارقةِ بغداد، فلم يتِمَّ ذلك، وحدث وحشةٌ مِن الجِهَتينِ، فاقتَضَت الحالُ أنَّ المَلِك يتركُ معارضةَ النوَّاب الإماميَّة فيها في السنةِ الآتيةِ."},{"id":1505,"title":"خروج رجل بمصر ادعى أنه الحاكم بأمر الله .","date":["العام الهجري :434","الشهر القمري : رجب","العام الميلادي :1043"],"text":"خرج بمِصرَ إنسانٌ اسمُه سكين وقيل سُليمان، كان يُشبِهُ الحاكِمَ صاحِبَ مِصرَ، فادَّعى أنَّه الحاكِمُ، وقد رجعَ بعد موتِه، فاتَّبَعه جمعٌ مِمَّن يعتَقِدُ رَجعةَ الحاكِمِ، فاغتنموا خُلوَّ دار الخليفةِ بمصرَ مِن الجند وقصَدوها معه نِصفَ النَّهار، فدخلوا الدهليز، فوثَبَ من هناك من الجندِ، فقال لهم أصحابُه: إنَّه الحاكِمُ، فارتاعوا لذلك، ثمَّ ارتابوا به، فقَبَضوا عليه، واقتَتلوا، فتراجع الجندُ إلى القصرِ، والحَربُ قائمة، فقُتِلَ من أصحابه جماعة، وأُسِرَ الباقون وصُلِبوا أحياءً، ورماهم الجندُ بالنشابِ حتى ماتوا."},{"id":1506,"title":"قتال بين مودود الغزنوي وعسكر ألب أرسلان السلجوقي .","date":["العام الهجري :435","العام الميلادي :1043"],"text":"سيَّرَ المَلِكُ أبو الفتح مودود بنُ مسعود بن سبكتكين عَسكَرًا مع حاجِبٍ له إلى نواحي خراسان، فأرسل إليهم داود أخو طغرلبك- وهو صاحِبُ خراسان- ولَدَه ألب أرسلان في عسكرٍ، فالتَقَوا واقتتلوا فكان الظَّفَرُ للمَلِك ألب أرسلان، وعاد عسكَرُ غزنة مُنهَزمًا، وفي صَفَر سار جمعٌ مِن الغز إلى نواحي بست، وفعلوا ما عُرِفَ منهم من النَّهبِ والشَّرِّ، فسَيَّرَ إليهم أبو الفتح مودود عسكرًا، فالتَقَوا بولاية بست، واقتتلوا قتالًا شديدًا انهزم الغزُّ فيه، وظَفِرَ عسكر مودود، وأكثروا فيهم القَتلَ والأَسْر."},{"id":1507,"title":"مودود الغزنوي يهزم الهنود ويتملك عدة حصون .","date":["العام الهجري :435","العام الميلادي :1043"],"text":"اجتمع ثلاثةُ مُلوكٍ مِن ملوك الهند، وقَصَدوا لاهور وحَصَروها، فجمع مُقَدَّم العساكر الإسلامية بتلك الديار مَن عندَه منهم، وأرسل إلى صاحِبِه مودود يستنجِدُه، فسَيَّرَ إليه العساكِرَ فاتَّفَقَ أنَّ بعض أولئك الملوك فارَقَهم وعاد إلى طاعةِ مودود، فرحل الملكانِ الآخران إلى بلادِهما، فسارت العساكرُ الإسلاميَّة إلى أحدهما، ويُعرَفُ بدوبال هرباته، فانهزم منهم، وصَعِدَ إلى قلعةٍ له منيعةٍ هو وعساكِرُه، فاحتَمَوا بها، وكانوا خمسةَ آلاف فارس وسبعين ألف راجلٍ، وحصرهم المسلمونَ وضَيَّقوا عليهم، وأكثروا القتلَ فيهم، فطلب الهنودُ الأمانَ على تسليم الحِصنِ، فامتنع المسلمونَ مِن إجابتِهم إلى ذلك إلَّا بعد أن يُضيفوا إليه باقيَ حصونِ ذلك المَلِك الذي لهم، فحَمَلهم الخوفُ وعدمُ الأقواتِ على إجابتِهم إلى ما طلبوا وتسَلَّموا الجميع، وغَنمَ المسلمونَ الأموال، وأطلقوا ما في الحصونِ مِن أسرى المسلمين، وكانوا نحو خمسةِ آلاف، فلمَّا فَرَغوا من هذه الناحية قَصَدوا ولايةَ المَلِك الثاني، واسمه تابت، بالرَّيِّ، فتقدم إليهم ولَقِيَهم، فاقتَتَلوا قتالًا شديدًا، وانهزمت الهنودُ، وأجْلَت المعركةُ عن قتلِ مَلِكِهم وخمسةِ آلاف قتيل، وجُرِحَ وأُسِرَ ضِعفُهم، وغَنِمَ المسلمونَ أموالهم وسلاحَهم ودوابَّهم. فلما رأى باقي الملوكِ مِن الهند ما لقي هؤلاء أذعنوا بالطاعةِ، وحملوا الأموالَ، وطَلَبوا الأمانَ والإقرارَ على بلادهم، فأُجيبوا إلى ذلك."},{"id":1508,"title":"إخراج المسلمين والنصارى من القسطنطينية .","date":["العام الهجري :435","العام الميلادي :1043"],"text":"وقع خبَرٌ بالقُسْطَنطينيَّة أنَّ قُسْطَنطين قتَلَ ابنَتَي الملك اللَّتين قد صار المُلكُ فيهما, فاجتمَعَ أهل البلد وأثاروا الفتنةَ، وطَمِعوا في النَّهبِ، فأشرف عليهم قُسْطَنطين، وسألهم عن السَّبَبِ في ذلك، فقالوا: قتلْتَ الملِكَتَين، وأفسَدْتَ المُلْكَ، فقال: ما قتَلْتُهما، وأخرَجَهما حتى رآهما النَّاسُ، فسكنوا، ثمَّ إنَّه سأل عن سبب ذلك، فقيل له: إنَّه فِعلُ الغُرَباءِ، وأشاروا بإبعادِهم، وأَمَرَ فنُودي ألَّا يُقيمَ أحدٌ وَرَدَ البلد منذ ثلاثينَ سَنةً، فمن أقام بعد ثلاثةِ أيَّامٍ سُمِلَت عيناه، فخرج منها أكثَرُ من مِئَة ألفِ إنسان، ولم يبقَ بها أكثَرُ من اثني عشَرَ نَفسًا، ضَمِنَهم الرومُ فتَرَكَهم."},{"id":1509,"title":"المعز بن باديس يظهر الولاء للعباسيين واستقلاله عن الفاطميين .","date":["العام الهجري :435","العام الميلادي :1043"],"text":"أظهَرَ المُعِزُّ بنُ باديس صاحِبُ إفريقيَّةَ الدُّعاءَ للدَّولةِ العباسيَّة، وخطب للإمامِ القائِمِ بأمرِ الله، أميرِ المؤمنين، وورَدَت عليه الخِلَعُ والتقليدُ ببلادِ إفريقيَّةَ وجميعِ ما يفتَحُه، وأُرسِلَ إليه سيفٌ وفَرَسٌ وأعلامٌ على طريقِ القُسطَنْطينيَّة، فوصل ذلك يومَ الجمعة، فدُخِلَ به إلى الجامِعِ، والخطيبُ ابنُ الفاكاة على المنبر يخطُبُ الخُطبةَ الثانيةَ، فدخلت الأعلامُ، فقال: هذا لواءُ الحَمدِ يَجمَعُكم، وهذا مُعِزُّ الدينِ يَسمَعُكم، وأستَغفِرُ اللهَ لي ولكم، وقُطِعَت الخُطبةُ للعَلَويِّينَ من ذلك الوقتِ، وأُحرِقَت أعلامُهم."},{"id":1510,"title":"إسلام الترك بما وراء النهر .","date":["العام الهجري :435","الشهر القمري : صفر","العام الميلادي :1043"],"text":"أسلَمَ مِن كُفَّارِ التُّركِ الذين كانوا يَطرُقونَ بلاد الإسلامِ بنواحي بلاساغون وكاشغر، ويُغيرون ويَعيثونَ، عشرةُ آلافِ خركاة، وضَحَّوا يومَ عيد الأضحى بعشرين ألفَ رأس غنم، وكفى اللهُ المسلمينَ شَرَّهم، وكانوا يصيِّفونَ بنواحي بلغار، ويَشتُون بنواحي بلاساغون، فلما أسلموا تفَرَّقوا في البلادِ، فكان في كُلِّ ناحيةٍ ألفُ خركاة، وأقَلُّ وأكثَرُ لأمنِهم؛ فإنَّهم إنما كانوا يجتَمِعونَ ليحميَ بَعضُهم بعضًا من المسلمين، وبقِيَ من الأتراك مَن لم يسلِمُ تَتَرٌ وخطا، وهم بنواحي الصين، وكان صاحِبُ بلاساغون، وبلاد الترك، شَرَف الدَّولة، وفيه دِينٌ، وقد أقنع من إخوتِه وأقاربه بالطَّاعة، وقسَّمَ البلاد بينهم، فأعطى أخاه أصلان تكين كثيرًا مِن بلاد الترك، وأعطى أخاه بغراجان طراز وأسبيجاب، وأعطى عَمَّه طغاخان، فرغانةَ بأسْرِها، وأعطى ابنَ علي تكين بخارى وسمرقند وغيرهما، وقنع هو ببلاساغون وكاشغر."},{"id":1511,"title":"الحرب بين الروم والروس .","date":["العام الهجري :435","الشهر القمري : صفر","العام الميلادي :1043"],"text":"ورد إلى القُسطَنطينية عددٌ كثيرٌ مِن الرُّوسِ في البحر، وراسَلوا قسطنطين مَلِكَ الروم بما لم تجْرِ به عادتُهم، فاجتمعت الرومُ على حَربِهم، وكان بعضُهم قد فارق المراكِبَ إلى البَرِّ، وبعضُهم فيها، فألقى الرومُ في مراكِبِهم النَّار، فلم يهتدوا إلى إطفائها، فهلك كثيرٌ منهم بالحَرْق والغَرَق، وأمَّا الذين على البَرِّ فقاتلوا، وصَبَروا، ثم انهزموا، فلم يكن لهم ملجأٌ، فمن استسلم أولًا استُرِقَّ وسَلِمَ، ومن امتنَعَ حتى أُخِذَ قهرًا قطع الرومُ أيمانَهم، وطِيفَ بهم في البلَدِ، ولم يَسلَمْ منهم إلَّا اليسيرُ مع ابنِ مَلِك الرُّوس، وكُفِيَ الرُّومُ شَرَّهم."},{"id":1512,"title":"وفاة جلال الدَّولة البويهي الشيعي وتولي أبي كاليجار بعده .","date":["العام الهجري :435","الشهر القمري : شعبان","العام الميلادي :1044"],"text":"هو صاحِبُ العِراقِ، المَلِك جلالُ الدَّولة، أبو طاهر بن بهاء الدَّولة بن عضد الدَّولة بن ركن الدَّولة بن بُوَيه، الديلمي. تمَلَّك سبع عشرة سنة، وكانت دولتُه ليِّنةً، وتمَلَّك بعده ابنُه المَلِك العزيزُ أبو منصور، فكانت أمورُه واهيةً كأبيه. وكان جلالُ الدَّولة شيعيًّا كأهلِ بَيتِه وفيه جُبنٌ، وعَسكَرُه مع قِلَّتِهم طامعون فيه. عاش نيفًا وخمسين سنة، وذاق نكدًا كثيرًا, وإنما كان سلطانَ العَصرِ ابنُ سبكتكين. توفِّيَ المَلِك جلالُ الدَّولة ببغداد، وكان مَرَضُه ورمًا في كَبِده، وبَقِيَ عدَّةَ أيام مريضًا حتى توفِّيَ ودُفِنَ بداره، ولَمَّا تُوفِّيَ غُلِّقَت الأبواب، ونظَرَ أولادُه من الروشن إلى الأتراك، وقالوا: أنتم أصحابُنا ومشايخُ دَولتِنا وفي مقامِ والِدِنا، فارعَوا حُقوقَنا، وصونوا حريمَنا، فبَكَوا وقَبَّلوا الأرضَ, ولَمَّا توفِّيَ انتقل الوزيرُ كمال الملك بن عبد الرحيم وأصحابُ المَلِك الأكابر إلى باب المراتِبِ، وحريم دار الخلافة، خوفًا من نَهبِ الأتراكِ والعامَّةِ دُورَهم، فاجتمع قوَّادُ العَسكَرِ تحت دار المملكة، ومَنَعوا النَّاسَ من نهبِها، ولَمَّا توفِّيَ كان ولده الأكبَرُ الملك العزيزُ أبو منصور بواسط، على عادته، فكاتبه الأجنادُ بالطاعة، وشَرَطوا عليه تعجيلَ ما جَرَت به العادة من حَقِّ البيعة، فتردَّدَت المراسلاتُ بينهم في مقداره وتأخيرِه لفَقْدِه، وبلغ موتُه إلى الملك أبي كاليجار بن سلطان الدَّولة بن بهاء الدَّولة، فكاتب القوَّاد والأجناد، ورغَّبَهم في المال وكثرته وتعجيلِه، فمالوا إليه وعَدَلوا عن الملك العزيز، وأمَّا المَلِك العزيزُ فإنه أصعد إلى بغداد لَمَّا قَرُب الملك أبو كاليجار منها، عازمًا على قَصدِ بغداد ومعه عسكَرُه، فلما بلغ النعمانية غدَرَ به عسكَرُه ورجعوا إلى واسط، وخطبوا لأبي كاليجار، ولم تَزَل الرسُلُ تتردَّدُ بينه وبين عسكَرِ بغداد، حتى استقَرَّ الأمرُ له، وحَلَفوا، وخَطَبوا له ببغداد في صَفَر من سنة 436."},{"id":1513,"title":"وفاة الإمام أبي ذر الهروي .","date":["العام الهجري :435","الشهر القمري : ذي القعدة","العام الميلادي :1044"],"text":"هو الحافِظُ الإمامُ المُجَوِّد العَلَّامة شيخُ الحرم: أبو ذر عبدُ اللهِ بنُ أحمدَ بنِ مُحمَّد بن عبد الله بن غفير بن محمد، الأنصاريُّ الخُراساني الهَرَوي المالكي، صاحِبُ التصانيفِ، وراوي الصَّحيحِ عن الثلاثة: المستملي، والحَمَوي، والكشميهني. وُلِد سنة 355. سمع الكثيرَ ورحل إلى الأقاليم، وسكن مكَّة، ثمَّ تزوَّجَ في العرب، وكان يحُجُّ كلَّ سنة ويقيمُ بمكَّةَ أيَّام الموسم ويسمعُ النَّاس، ومنه أخذَ المغاربةُ مذهبَ الأشعريِّ عنه، وكان يقولُ إنَّه أخذ مذهَبَ مالكٍ عن الباقِلَّاني، كان حافِظًا، له تصانيفُ منها: تفسير القرآن، وله مُستدرَك على الصحيحين. قال أبو بكر الخطيب: \"قَدِمَ أبو ذر بغداد، وحَدَّث بها وأنا غائب، وخرج إلى مكَّة، وجاور، ثم تزوَّجَ في العرب، وأقام بالسرواتِ، فكان يحُجُّ كل عام، ويحَدِّثُ، ثمَّ يرجع إلى أهله، وكان ثقةً ضابطًا دَيِّنًا، مات بمكَّةَ\""},{"id":1514,"title":"القضاء على الإسماعيلية في بلاد ما وراء النهر .","date":["العام الهجري :436","العام الميلادي :1044"],"text":"قصَدَ نَفَرٌ مِن الإسماعيليَّةِ ما وراء النَّهرِ، ودعوا إلى طاعةِ المستنصِرِ بالله الفاطميِّ صاحبِ مِصرَ، فتَبِعَهم جمعٌ كثير وأظهروا مذاهِبَ أنكرها أهلُ تلك البلاد، وسَمِعَ ملكها بغراخان خبَرَهم، وأراد الإيقاعَ بهم، فخاف أن يسلَمَ منه بعضُ من أجابَهم من أهل تلك البلاد، فأظهر لبَعضِهم أنَّه يميلُ إليهم، ويريدُ الدخولَ في مذاهِبِهم، وأعلَمَهم ذلك، وأحضَرَهم مجالِسَه، ولم يزَلْ حتى عَلِمَ جميعَ مَن أجابهم إلى مَقالتِهم، فحينئذ قَتَل من بحضرتِه منهم، وكتَبَ إلى سائِرِ البلادِ بقَتلِ مَن فيها، ففُعِلَ بهم ما أمَرَ به، وسَلِمَت البلادُ منهم."},{"id":1515,"title":"وفاة أبي القاسم الجرجرائي .","date":["العام الهجري :436","العام الميلادي :1044"],"text":"هو الوزيرُ الكامِلُ نجيب الدَّولة، أبو القاسِمُ علي بن أحمد الجرجرائي، وزيرُ الديار المصريَّة للظاهِرِ العُبَيدي، وكان مِن دُهاة الملوك، خدم الحاكِمَ، فغَضِبَ عليه، فقطع يديه مِن مِرفَقَيه في سنة 404؛ لكونه خان في مباشرةِ الديوان، ثمَّ رَضِيَ عنه في سنة 409، فولَّاه ديوان النَّفَقات، ثم عَظُمَ أمرُه إلى أن وزَرَ في سنة 418 للظاهِرِ بنِ الحاكم. وهو مقطوعُ اليدينِ مِن المرفقين، فاستمَرَّ في الوزارة مدَّةَ وِلايةِ الظاهرِ، ثمَّ لوَلَدِه المُستنصِر، حتى توفِّيَ في هذه السنة، وكان شهمًا كافيًا سائسًا، ذا أمانةٍ وعِفَّةٍ عظيمةٍ."},{"id":1516,"title":"الخطبة للملك أبي كاليجار البويهي وإصعاده إلى بغداد .","date":["العام الهجري :436","الشهر القمري : صفر","العام الميلادي :1044"],"text":"لَمَّا توفِّي المَلِكُ جلال الدَّولة، راسل الجندُ، الملكَ أبا كاليجار مرزبان بنَ سلطان الدَّولة البويهي وخَطَبوا له. فلمَّا استَقَرَّت القواعِدُ بينه وبينهم أرسل أموالًا فُرِّقَت على الجُندِ ببغداد، وعلى أولادهم، وأرسل عشرةَ آلاف دينار للخليفةِ ومعها هدايا كثيرة، فخطبَ به ببغداد في صفر، وخَطَب له أيضًا أبو الشوك في بلادِه، ودبيس بن مزيد ببلادِه، ونصر الدَّولة بن مروان بديار بكرٍ، ولَقَّبَه الخليفةُ محيي الدِّينِ، وسار إلى بغدادَ في مِئَة فارسٍ مِن أصحابه لئلَّا تخافَه الأتراكُ، فلمَّا وصل إلى النُّعمانية لَقِيَه دبيس بن مزيد، ودخل إلى بغدادَ في شهرِ رمضان. ومعه وزيرُه ذو السَّعادات أبو الفرج محمد بن جعفر بن محمد بن فسانجس، ووعده الخليفةُ القائِمُ بأمر الله أن يستقبِلَه، فاستعفى من ذلك، وأخرج عميدَ الدَّولة أبا سعدِ بن عبد الرحيم وأخاه كمالَ الملك وزيرَي جلال الدَّولة من بغداد، فمضى أبو سعدٍ إلى تكريت، وزُيِّنَت بغداد لقدومه، وأمَرَ فخُلِعَ على أصحاب الجيوش، وهم: البساسيري، والنشاوري، والهمام أبو اللقاء، وجرى من ولاةِ العَرضِ تقديمٌ لبعض الجند وتأخير، فشَغَّب بعضهم، وقتلوا واحدًا من ولاة العرضِ بمرأًى من الملك أبي كاليجار، فنزل في سميرية- نوع من السفن- بكنكور، وانحدر خوفًا من انخراقِ الهَيبةِ."},{"id":1517,"title":"وفاة الشريف المرتضى .","date":["العام الهجري :436","الشهر القمري : ربيع الأول","العام الميلادي :1044"],"text":"هو أبو القاسِمِ عليُّ بنُ الحُسَين بن موسى بن محمد بن موسى الكاظم بن جعفر الصادق بن محمد الباقر بن علي زين العابدين بن الحسين بن علي بن أبي طالب، الشَّريفُ الموسويُّ، المُلَقَّب بالمرتضى، ذي المجدين، كان نقيبَ الطالبيِّينَ وكان إمامًا في عِلمِ الكلامِ والأدبِ وجيد الشعر. وُلِدَ سنة 355, وكان أكبَرَ مِن أخيه ذي الحَسَبين الشريف الرضي، كان على مذهَبِ الإماميَّةِ والاعتزال، يُناظِرُ على ذلك، وكان يُناظِرُ عنده في كل المذاهب، وله تصانيفُ في التشيُّعِ، أصولًا وفروعًا. قال الذهبي عنه: \" هو جامِعُ كتاب \"نهج البلاغة\"، المنسوبةِ ألفاظُه إلى عليِّ بنِ أبي طالب ولا أسانيدَ لذلك، وبعضُها باطِلٌ، وفيه حَقٌّ ولكِنَّ فيه موضوعاتٍ حاشا الإمامَ مِن النطق بها، ولكنْ أين المُنصِفُ?! وقيل: بل جَمْعُ أخيه الشَّريف الرضي, ثم قال: وكان من الأذكياءِ الأولياءِ المتبَحِّرينَ في الكلامِ والاعتزالِ، والأدبِ والشِّعرِ، لكنَّه إماميٌّ جَلْدٌ. نسأل الله العفو.\". قال ابن كثير: \"وقد نقل ابنُ الجوزي أشياءَ مِن تفرُّداتِه في التشَيُّع، فمِن ذلك أنَّه لا يصِحُّ السجودُ إلَّا على الأرضِ أو ما كان مِن جِنسِها، وأنَّ الاستجمارَ إنمَّا يُجزِئُ في الغائطِ لا في البولِ، وأنَّ الكتابيَّاتِ حَرامٌ، وكذا ذبائِحُ أهل الكتاب، وأنَّ المرأة إذا جَزَّت شَعْرَها يجب عليها كَفَّارة قتل الخطأ، وغير ذلك كثيرٌ، وأعجَبُ منها ذَمُّ الصحابةِ رَضِيَ الله عنهم، ثمَّ سَرَدَ من كلامِه شيئًا قبيحًا في تكفيرِ عُمَرَ بنِ الخطاب وعثمانَ وعائشة وحفصة رضي الله عنهم\". قال ابنُ حزم: الإماميَّةُ كلُّهم على أنَّ القُرآنَ مُبَدَّلٌ، وفيه زيادةٌ ونَقصٌ سوى المرتضى، فإنَّه كفَّرَ مَن قال ذلك. قال الذهبيُّ مُعَلِّقًا على كلامِ ابنِ حزم، قلتُ: وفي تواليفِه سَبُّ أصحاب رسولِ الله صلَّى اللهُ عليه وسلَّم، فنعوذُ باللهِ مِن عِلمٍ لا ينفَعُ\". ولم يتكَلَّمْ فيه وفي أخيه الرضي كثيرٌ مِن المؤرخين رعايةً لِشَرَفِ نَسَبِهم، وإلَّا فإنهم كانوا على مذهَبِ الرَّفضِ والاعتزال، توفِّيَ في يوم الأحد الخامس والعشرين من شهر ربيع الأول."},{"id":1518,"title":"وفاة أبي الحسين محمد بن علي الطيب البصري شيخ المعتزلة .","date":["العام الهجري :436","الشهر القمري : ربيع الآخر","العام الميلادي :1044"],"text":"هو أبو الحُسَين محمَّد بن علي بن الطيب البصري المتكلِّم، صاحِبُ التَّصانيفِ الكلاميَّة، شيخُ المعتزلة والمُنتَصِر لهم، والمحامي عن ذمِّهم بالتصانيفِ الكثيرة، كان فصيحًا بليغًا، عَذْبَ العبارة، يتوقَّدُ ذَكاءً, وله اطِّلاعٌ كبير. توفِّيَ ببغداد بعد أن شاخ عُمُرُه, وصلَّى عليه القاضي أبو عبد الله الصيمري، ودُفِنَ في الشونيزي، ولم يَرْوِ من الحديثِ سوى حديثٍ واحدٍ، هو \"إنَّ ممَّا أدرك النَّاس مِن كلامِ النبوَّةِ إذا لم تستحِ فاصنَعْ ما شئتَ\"، له عِدَّةُ مُصَنَّفات أجَلُّها المُعتَمَدُ في أصول الفِقهِ، ومنه أخذ الفَخرُ الرازي كتابَ المحصول، وله كتابُ تصفُّح الأدلَّة وشرح الأصولِ الخَمسة يعني أصولَ المعتزلة، وكتابُ الإمامةِ."},{"id":1519,"title":"تملك السلاجقة لبلاد الجبل والدينور .","date":["العام الهجري :437","العام الميلادي :1045"],"text":"أمر السُّلطانُ طغرلبك السلجوقيُّ أخاه إبراهيم ينال بالخروجِ إلى بلد الجَبَل وملكها، فسار إليها من كرمان، وقصد همذان، وبها كرشاسف بن علاء الدَّولة، ففارقها خوفًا، ودخلها ينال فمَلَكها، والتحَقَ كرشاسف بالأكراد الجوزقان، وكان أبو الشوك حينئذ بالدينورِ، فسار عنها إلى قرميسين خَوفًا وإشفاقًا مِنْ ينال، فقَوِيَ طَمَعُ ينال حينئذ في البلادِ، وسار الدينور فمَلَكَها ورتَّبَ أمورَها، وسار منها يطلُبُ قرميسين، فلما سَمِعَ أبو الشوك به سار إلى حلوان وترك بقرميسين مَن في عسكَرِه من الديلم، والأكراد الشاذنجان؛ ليمنعوها ويحفظوها، فقاتلوا ينال، فدفعوه عنها، فانصرف عنهم وعاد بحلله، فقاتلوه، فضَعُفوا عنه وعَجَزوا عن منعه، فملك ينال البلَدَ في رجب عَنوةً، وقتل من العساكر جماعةً كثيرة، وأخذ أموالَ مَن سَلِمَ مِن القتل، وسلاحِهَم، وطَرَدَهم، ولحقوا بأبي الشوك، ونهَبَ البلدَ وقتل وسبى كثيرًا مِن أهله، ولَمَّا سَمِعَ أبو الشوك ذلك سيَّرَ أهله وأمواله وسلاحَه من حلوان إلى قلعة السيروان، وأقام جريدة -الجريدة خَيْلٌ لا رَجَّالةَ فيها- في عسكَرِه، ثمَّ إنَّ ينال سار إلى الصيمرة في شعبان، فملكها ونهَبَها، وأوقع بالأكرادِ المجاورين لها من الجوزقان، فانهزموا، وكان كرشاسف بن علاء الدَّولة نازلًا عندهم، فسار هو وهم إلى بلدِ شِهابِ الدَّولة أبي الفوارس منصور بن الحسين، ثم إنَّ إبراهيم ينال سار إلى حلوان، وقد فارقها أبو الشوك، ولحِقَ بقلعة السيروان، فوصل إليها إبراهيمُ آخِرَ شعبان، وقد جلا أهلُها عنها، وتفَرَّقوا في البلاد، فنَهَبها وأحرَقَها، وأحرق دار أبي الشوك، وانصرف بعد أن اجتاحها ودرَسَها، وتوجَّه طائفةٌ مِن الغز إلى خانقين في أثَرِ جماعةٍ مِن أهل حلوان كانوا ساروا بأهليهم وأولادهم وأموالهم، فأدركوهم وظَفِروا بهم وغَنِموا ما معهم، وانتشر الغزُّ في تلك النواحي، فبلغوا مايدشت وما يليها، فنهبوها وأغاروا عليها."},{"id":1520,"title":"أبو كاليجار سلطان الدَّولة البويهي يتجهز لقتال السلاجقة السنة .","date":["العام الهجري :437","العام الميلادي :1045"],"text":"لما رأى أبو كاليجار البويهيُّ الشيعيُّ- وكان بخوزستان- ما تمَلَّكه السَّلاجقةُ مِن الجَبَل والدينور، وأصبح شأنُهم في علوٍّ وقوَّةٍ، تَجهَّزَ لقتال السلاجقةِ الذين تعَدَّوا على أتباعِه، فلم يمكِنْه ذلك لقِلَّةِ الظهر، وذلك أنَّ الآفةَ اعتَرَت في هذه السَّنةِ الخيلَ، فمات له فيها نحوٌ مِن اثني عشر ألفَ فَرَس، بحيث جافَت بغدادُ مِن جِيَف الخَيلِ."},{"id":1521,"title":"مهلهل بن عناز يسيطر على مدينتي قرميسين والدينور بإيران .","date":["العام الهجري :438","العام الميلادي :1046"],"text":"مَلَكَ مُهلهَل بن محمد بن عناز مدينة قرميسين والدينور، وسبَبُ ذلك أنَّ إبراهيمَ ينال السلجوقي كان قد استعمل عند عودِه من حلوان على قرميسين بدرَ بنَ طاهر بن هلال، فلما ملَكَ مُهلهَل بعد موت أخيه أبي الشوك الذي كان يحكُمُ الدينور، سار إلى مايدشت، ونزل بها ثم توجَّهَ نحو قرميسين، فانصرَفَ عنها بدر فملكها مهلهل، وسيَّرَ ابنه محمدًا إلى الدينور، وبها عساكِرُ ينال، فاقتتلوا، فقُتِلَ بين الفريقينِ جماعة، وانهزم أصحاب ينال، وملَكَ محمَّدٌ البلد."},{"id":1522,"title":"طغرلبك السلجوقي يحاصر مدينة أصبهان .","date":["العام الهجري :438","العام الميلادي :1046"],"text":"حصر طغرلبك مدينة أصبهان، وبها صاحِبُها أبو منصور فرامرز بن علاء الدَّولة، فضَيَّق عليه، ولم يظفَرْ من البلد بطائل، ثمَّ اصطلحوا على مالٍ يحملُه فرامرز بن علاء الدَّولة لطغرلبك، وخطب له بأصبهان وأعمالِها."},{"id":1523,"title":"أبناء أمير سرقسطة بالأندلس يتنازعون السلطة بعد وفاة والدهم .","date":["العام الهجري :438","العام الميلادي :1046"],"text":"توفِّيَ سُلَيمانُ بنُ هود المستعين أميرُ سرقسطة ولاردة والثغر الأعلى، وكان قبل موته قد قسمَ سرقسطة بين أولادِه فخَصَّ أحمد بولاية سرقسطة العاصمة، وخَصَّ يوسُفَ بلاردة، وخَصَّ لب بوشقة، وخص المنذر بتطيلة، وخص محمدًا بقلعة أيوب، ثمَّ بعد وفاته تنازع الإخوةُ فيما بينهم، فقام أحمد الذي لَقَّبَ نفسَه بالمقتَدِر وانتزع مِن لب والمنذر ومحمَّد ما بأيديهم واستولى على مدُنِهم بعد أن سجَنَهم وسمَلَ أعينَهم، فلمَّا رأى النَّاسُ ما فعله أحمد بإخوته كرهوه ومالوا إلى أخيه يوسفَ في لاردة الذي تلقَّبَ بالمظفَّر, فلما رأى أحمد ميلَ الناس له نَقِمَ عليه وتواطأ مع أحدِ أمراء النصارى ابن ردمير صاحِبِ بلادٍ نصرانيَّةٍ مجاوِرةٍ له على أخيه مقابِلَ مالٍ يُرسِلُه له، فلما وصل ابن ردمير المالُ، سار بجيشه فغار على الأخوينِ فأكثَرَ فيهما القتلَ والأسرَ، وأخذ معظَمَ أراضيهما"},{"id":1524,"title":"وفاة الشيخ أبي محمد (الجويني) .","date":["العام الهجري :438","الشهر القمري : ذي القعدة","العام الميلادي :1047"],"text":"هو الشَّيخُ أبو محمَّد الجُوَينيُّ إمامُ الشافعيَّة عبد الله بن يوسف بن محمد بن حيويه الجويني الطَّائي السنبسي، كان فقيهًا مُدَقِّقًا مُحَقِّقًا، نحويًّا مفسِّرًا، وهو والد إمامِ الحَرَمين، وأصلُه من قبيلة يقال لها سنبس، وجُوَين من نواحي نيسابور، سمِعَ الحديث من بلادٍ شَتَّى على جماعة، وقرأ الأدبَ على أبيه، وتفَقَّه بأبي الطيِّبِ سهلِ بنِ محمد الصعلوكي، ثمَّ خرج إلى مروٍ إلى أبي بكر عبدِ الله بن أحمد القَفَّال واشتغل عليه بمروٍ، ولازمه واستفاد منه وانتفع به، وأتقن عليه المذهَبَ والخِلافَ، وقرأ عليه طريقَتَه وأحكَمَها، فلما تخرَّجَ عليه عاد إلى نيسابور سنة 407 وتصدَّر للتدريس والفتوى، وعقَدَ مجلِسَ المُناظرة، فتخرَّج عليه خلقٌ كثيرٌ، منهم ولده إمامُ الحَرَمينِ، وصنف التصانيفَ الكثيرةَ في أنواعٍ مِن العلومِ، وكان زاهدًا شديدَ الاحتياطِ لدينِه، حتى ربما أخرج الزَّكاةَ مَرَّتين، صَنَّف التفسيرَ الكبير المشتَمِلَ على أنواعِ العلومِ، وله في الفِقهِ التَّبصِرةُ والتذكرة، وصنَّف مُختَصَر المُختَصَر، والفَرْق والجمع، والسِّلسلة وغير ذلك، وكان إمامًا في الفقهِ والأصولِ، والأدبِ والعربيَّة، توفِّي في هذه السنة، وقيل سنة 434."},{"id":1525,"title":"وفاة عبد الله بن قحطان آخر حكام بني يعفر وقيام الدولة الصليحية .","date":["العام الهجري :439","العام الميلادي :1047"],"text":"مع وفاةِ عبدِ اللهِ بنِ قَحطانَ آخِرِ حُكَّامِ بَني يَعفُرَ، انتَهى حُكمُهم، وظلَّت البِلادُ في حالةِ فَوضى سياسيةٍ، إلى أنْ جاء إلى الحُكمِ بنو الصُّلَيحيِّ عامَ 1047م/439هـ. ومِن أبرَزِ حُكَّامِ هذه الأُسرةِ الملكةُ الحُرَّةُ أرْوى بِنتُ الصُّلَيحِ. وظلت البِلادُ مُنقَسمةً على بَعضِها، وفي هذا العَصرِ جاءَ سَلاطِنةُ هَمَدانَ لتوَلِّي السُّلطةِ في صَنعاءَ عامَ 1088م/481هـ، واستَمرَّت السُّلطةُ تنتقلُ بينَ أفرادِ الأُسرةِ الصُّلَيحيَّةِ حتى بدأ العصرُ الأيُّوبيُّ عامَ 1173م/569هـ."},{"id":1526,"title":"مسير إبراهيم ينال السلجوقي إلى قلعة كنكور .","date":["العام الهجري :439","العام الميلادي :1047"],"text":"سار إبراهيم ينال إلى قلعة كنكور، وبها عكبر بن فارس- صاحِبُ كرشاسف بن علاء الدَّولة- يحفَظُها له، فامتنع عكبر بها إلى أن فَنِيَت ذخائره، وكانت قليلةً، فلمَّا نَفِدَت الذخائِرُ عَمِلَ حيلة وطلب الأمانَ على تسليمِ القلعةِ، ثمَّ لَمَّا تسلَّمَها إبراهيمُ، صَعِدَ إلى القلعة فانكشفت الحيلة، فسار عكبر بمن معه إلى قلعة سرماج، وصَعِدَ إليها، ولَمَّا ملك ينال كنكور عاد إلى همذان، فسَيَّرَ جيشًا لأخذ قلاعِ سرخاب، واستعمل عليهم نَسيبًا له اسمُه أحمد، وسَلَّمَ إليه سرخابًا ليفتح به قلاعَه، فسار به إلى قلعة كلكان، فامتنعت عليه، فساروا إلى قلعةِ دزديلويه فحصَروها، وسارت طائفةٌ منهم إلى أبي الفتح بن ورام، الذي قاتَلَهم، فظَفِرَ بهم، وقتل وأسَرَ جماعةً منهم، وغَنِمَ ما معهم، ورجع الباقون، وأرسل إلى بغدادَ يطلُبُ نجدةً خَوفًا من عَودِهم، فلم يُنجِدوه لعدم الهَيبةِ وقلَّة إمساكِ الأمر، فعبَرَ بنو ورام دجلةَ إلى الجانب الغربي، ثمَّ إنَّ الغز أسْرَوا إلى سعدي بن أبي الشوك في رجب، وهو نازِلٌ على فرسخين من باحسري، وكبسوه، فانهزم وقُتِلَ منهم خلقٌ كثير، وغَنِمَ الغزُّ أموالَهم، ونجا سعدي من الوقعةِ بجريعة الذقنِ، ونهب الغزُّ الدسكرة، وباجسري، والهارونية، وقصر سابور وجميع تلك الأعمال، ووصلَ الخبَرُ إلى بغداد بأنَّ إبراهيم ينال عازِمٌ على قصد بغداد، فارتاع النَّاسُ، واجتمع الأمراءُ والقُوَّاد إلى الأميرِ أبي منصور ابنِ المَلِك أبي كاليجار البويهي؛ ليجتمعوا ويسيروا إليه ويمنَعوه، واتَّفَقوا على ذلك، فلم يخرجْ غيرُ الأميرِ أبي منصور والوزير ونفر يسيرٍ، وتخلَّف الباقون، وهَلَك مِن أهل تلك النواحي المنهوبة خلقٌ كثيرٌ، ثمَّ إنَّ إبراهيم ينال سار إلى السيروان، فحصر القلعةَ، وضَيَّقَ على من بها، وأرسل سريَّةً نَهَبَت البلاد، وانتَهَت إلى مكانٍ بينه وبين تكريت عشرةُ فراسخ، ودخل بغدادَ مِن أهل طريق خراسان خلقٌ كثير، وذَكَروا مِن حالهم ما أبكى العُيونَ، ثُمَّ سلَّمَها إليه مُستحفَظُها، بعد أن أمَّنَه على نفسِه وماله، وأخذ منها ينالُ مِن بقايا ما خَلَّفَه سعدي شيئًا كثيرًا، ولَمَّا فتحها استخلف فيها مُقَدَّمًا كبيرًا من أصحابِه يقال له سخت كمان، وانصرف إلى حلوان، وعاد منها إلى همذان ومعه بدر ومالك ابنا مهلهل فأكرَمَهما."},{"id":1527,"title":"الأصفر التغلبي يغزو بلاد الروم .","date":["العام الهجري :439","العام الميلادي :1047"],"text":"ظهر الأصفَرُ التغلبيُّ برأس عين -مدينة سورية تقع على الحدود التركية السورية-، وادَّعى أنَّه من المذكورينَ في الكتب، واستغوى قومًا بمَخاريقَ، وجمع جمعًا وغزا نواحيَ الروم، فظَفِرَ وغَنِمَ وعاد، وظهَرَ حَديثُه، وقوِيَ ناموسُه، وعاودوا الغزوَ في عدد أكثَرَ مِن العدد الأول، ودخل نواحيَ الروم وأوغل، وغَنِمَ أضعافَ ما غَنِمَه أولًا، وتسامع النَّاسُ به فقصدوه، وكثُرَ جَمعُه، واشتَدَّت شوكتُه، وثقُلَت على الروم وطأتُه، فأرسل ملك الروم إلى نصرِ الدَّولة بن مروان صاحِبِ ديارِ بكرٍ يقول له: إنَّك عالمٌ بما بيننا من المُوادَعة، وقد فعل هذا الرجلُ هذه الأفاعيل، فإن كنتَ قد رجعتَ عن المهادنةِ فعَرِّفْنا لنُدَبِّرَ أمْرَنا بحَسَبِه، واتَّفَق في ذلك الوقتِ أنْ وَصَل رسولٌ مِن الأصفَرِ إلى نصر الدَّولة أيضًا، يُنكِرُ عليه تركَ الغَزوِ والميلَ إلى الدعة، فساءه ذلك أيضًا، واستدعى قومًا مِن بني نمير وقال لهم: إنَّ هذا الرجلَ قد أثار الرومَ علينا، ولا قُدرةَ لنا عليهم، وبذَلَ لهم مالًا على الفتك به، فساروا إليه، فقَرَّبَهم، ولازَموه، فرَكِبَ يومًا غير متحَرِّز، فأبعد وهم معه، فعَطَفوا عليه وأخذوه وحَمَلوه إلى نصر الدَّولة بن مروان، فاعتقَلَه وسَدَّ عليه باب السِّجنِ، وتلافى أمرَ الرومِ."},{"id":1528,"title":"الوباء والغلاء بالعراق .","date":["العام الهجري :439","العام الميلادي :1047"],"text":"كان ببغداد والمَوصِل، وسائِرِ البلاد العراقيَّة والجزيرة، غلاءٌ عظيم، حتى أكَلَ النَّاسُ المَيتةَ، وتَبِعَه وَباءٌ شَديدٌ مات فيه كثيرٌ مِن الناس، حتى خَلَت الأسواق، وزادت أثمانُ ما يَحتاجُ إليه المرضى، كما حدث وباءٌ شديد بالعراق والجزيرة، بسبب جِيَفِ الدوابِّ التي ماتت، فمات فيها خلقٌ كثيرٌ، حتى خَلَت الأسواقُ وقَلَّت الأشياءُ التي يحتاجُ إليها المرضى."},{"id":1529,"title":"الصلح بين طغرلبك السلجوقي وأبي كاليجار سلطان الدَّولة البويهي .","date":["العام الهجري :439","الشهر القمري : ربيع الآخر","العام الميلادي :1047"],"text":"أرسل الملك أبو كاليجار البويهيُّ إلى السُّلطانِ رُكنِ الدين طغرلبك في الصُّلح، فأجابه إليه، واصطلحا، وكتَبَ طغرلبك إلى أخيه ينال يأمُرُه بالكَفِّ عَمَّا وراء ما بيده، واستقَرَّ الحالُ بينهما أن يتزوَّجَ طغرلبك بابنةِ أبي كاليجار، ويتزوَّج الأميرُ أبو منصور بن أبي كاليجار بابنةِ الملك داود أخي طغرلبك، وتمَّ العَقدُ."},{"id":1530,"title":"غزو إبراهيم ينال الروم .","date":["العام الهجري :440","العام الميلادي :1048"],"text":"غزا الرُّومَ إبراهيم ينال أخو طغرل بك لأمه وأحد قادة السلاجقة، فظَفِرَ بهم وغَنِمَ، وكان سببُ ذلك أنَّ خلقًا كثيرًا من الغزِّ بما وراء النهر قَدِموا عليه، فقال لهم: بلادي تضيقُ عن مُقامِكم والقيامِ بما تحتاجون إليه، والرأيُ أن تَمضُوا إلى غَزوِ الروم، وتُجاهِدوا في سبيل الله، وتغنَموا، وأنا سائِرٌ على أثَرِكم، ومساعِدٌ لكم على أمْرِكم. ففعلوا، وساروا بين يديه، وتَبِعَهم، فوصلوا إلى ملازكرد، وأرزن الروم، وقاليقلا، وبلغوا طرابزون وتلك النواحيَ كلَّها، ولَقِيَهم عسكَرُ عَظيمِ الروم والأبخاز يبلغونَ خمسين ألفًا، فاقتتلوا، واشتد القتالُ بينهم، وكانت بينهم عِدَّةُ وقائِعَ، تارةً يظفَرُ هؤلاء، وتارة هؤلاء، وكان آخِرَ الأمر الظَّفَرُ للمسلمين، فأكثروا القتلَ في الروم وهزموهم، وأسَروا جماعةً كثيرةً مِن بطارقتهم، وممَّن أُسِرَ قاريط ملِكُ الأبخاز، فبذل في نفسِه ثلاثَمِئَة ألف دينار، وهدايا بمِئَة ألفٍ، فلم يجبه ينال إلى ذلك، ولم يَجُس تلك البلادَ وينهَبْها إلى أن انهزموا وبَقِيَ بينه وبين القُسْطَنطينية خمسةَ عشر يومًا، واستولى المسلمونَ على تلك النواحي فنهبوها، وغَنِموا ما فيها، وسَبَوا أكثَرَ مِن مِئَة ألف رأس، وأخذوا من الدوابِّ والبغالِ والغنائم والأموال ما لا يقَعُ عليه الإحصاءُ، وقيل: إن الغنائِمَ حُمِلَت على عشرة آلاف عجلة، وإنَّ في جملة الغنيمةِ تِسعةَ عشر ألف درع، وكان قد دخل بلدَ الروم جمعٌ مِن الغز يَقدُمُهم نسيب طغرلبك، فلم يؤثِّرْ كَبيرَ أثَرٍ، وقُتِلَ من أصحابه جماعة، وعاد، ودخل بعده إبراهيم ينال، فانتصر عليهم."},{"id":1531,"title":"دولة بني مزين في الأندلس .","date":["العام الهجري :440","العام الميلادي :1048"],"text":"لم يبقَ مِن إماراتِ الغَربِ بعد سُقوطِ لبلةَ وشلطيش وشنتمريَّة في يدِ المُعتَضِد بن عبَّاد سوى إمارةِ شلب، وكانت هذه الإمارةُ مِن أهَمِّ إماراتِ الغرب بعد إشبيليَّةَ وكانت تشمَلُ كورة شلب وكورة باجة، وكان الحاجِبُ عيسى بن محمد قد تغَلَّب في أعقابِ الفِتنةِ على هذه المنطقةِ النائيةِ وأقام بها دولةً، واستمَرَّ مُسيطرًا عليها حتى توفِّيَ سنة 432 هـ فخَلَفه في حُكمِها ولَدُه مُحمَّدُ بنُ عيسي الملقَّب عميد الدَّولة، واضطُرَّ عميد الدَّولة في اتِّقاءٍ لعُدوانِ المُعتَضِد بن عبَّاد أن ينزِلَ له عن مدينة باجة، وأن يكتفي بحكم شلب، وكان ابن عبَّاد قد استولى قبل ذلك على ميرتلة قاعدتِها الجنوبيَّةِ مِن يدِ صاحِبِها ابنِ طيفور في سنة 436 هـ، وأصبَحَت باجة تحت رَحمتِه، واستمَرَّ عميد الدَّولة في حُكمِ شلب حتى توفِّيَ في سنة 440هـ وعندئذ ثار بها القاضي عيسى بنُ أبي بكر بن مزين، وكان شهمًا جَزلًا في سائِرِ أمورِه، فلما رأى اختلالَ الأمورِ ثار بها فبايعه أهلُها وبسَطَ حُكمَه عليها، وتلقَّب بالمُظَفَّر واستمَرَّ حكمُه خمس سنوات، وابنُ عباد دائِبٌ على مهاجمتِه وشَنِّ الغارات عليه وهو يَرُدُّه ما استطاع، حتى قُتِلَ في أواخر سنة 445 هـ مدافعًا عن مدينته، فخلفه ولدُه محمد بن عيسى، وتلقَّب بالنَّاصِرِ وحَكَم حتى توفي في سنة 450هـ، فخلفه ولدُه عيسى وتلقَّبَ بالمُظَفَّر وبدأ المعتَضِدُ في تكرار حملاته على شلب، ثم ضرب الحصارَ حولها وقطعَ عنها سائرَ الإمدادِ حتى اشتَدَّ الأمرُ على أهلِها وانتهى بأن اقتحَمَها بعد أن هدم أسوارَها، ودخل القصرَ وقتل عيسى المظفر، وذلك في شوال من سنة 455هـ، وهكذا استطاع المعتضد بن عباد القضاءَ على دولةِ بني مزين."},{"id":1532,"title":"وفاة الملك أبي كاليجار البويهي الشيعي وولي بعده ابنه أبو نصر .","date":["العام الهجري :440","الشهر القمري : جمادى الأولى","العام الميلادي :1048"],"text":"هو السُّلطانُ صاحِبُ العراق، المَلِك أبو كاليجار المرزبان بنُ سلطان الدَّولة بن بهاء الدَّولة بن عضد الدَّولة بن بُوَيه الديلمي الشيعي. تمَلَّك بعد ابنِ عَمِّه جلال الدَّولة، وجرَت له خطوبٌ وحُروب، وعاش نيِّفًا وأربعين سنة، وقهر ابنَ عَمِّه الملك العزيز، توفِّيَ رابع جمادى الأولى، بمدينة جناب من كرمان، ولما توفِّيَ نَهَب الأتراكُ مِن العسكر الخزائِنَ والسلاحَ والدوابَّ، وكانت ولايتُه على العراق أربع سنين وشهرين وأيامًا، ومدَّة ولايته على فارس والأهواز خمسًا وعشرين سنةً، وانتقل ولدُه أبو منصور فلاستون إلى مخيَّم الوزير أبي منصور، وكانت مُنفَرِدةً عن العسكر، فأقام عنده، وأراد الأتراكُ نَهبَ الوزير والأمير، فمَنَعَهم الديلم، وعادوا إلى شيراز، فمَلَكَها الأميرُ أبو منصور، واستشعر الوزيرُ، فصَعِدَ إلى قلعة خرمة فامتنع بها، فلمَّا وصل خبر وفاته إلى بغداد، وبها ولَدُه الملك الرحيم أبو نصر خرة فيروز، أحضَرَ الجُندَ واستحلفهم، وراسل الخليفةَ القائِمَ بأمر الله في معنى الخطبة له، وتلقيبِه بالملك الرحيم، وتردَّدَت الرسُلُ بينهم في ذلك إلى أن أُجيبَ إلى مُلتَمِسه سوى الملك الرحيم؛ فإنَّ الخليفةَ امتنع من إجابته وقال: لا يجوز أن يُلَقَّب بأخَصِّ صفاتِ الله تعالى، واستقَرَّ مُلكُه بالعراق، وخوزستان، والبصرة، وكان بالبصرةِ أخوه أبو علي بن أبي كاليجار، وخلف أبو كاليجار من الأولاد الملك الرحيم، والأمير أبا منصور فلاستون، وأبا طالب كامرو، وأبا المظفر بهرام، وأبا علي كيخسرو، وأبا سعد خسروشاه، وثلاثة بنين أصاغر، فاستولى ابنُه أبو منصور على شيراز، فسيَّرَ إليه الملك الرحيم أخاه أبا سعد في عسكرٍ، فملكوا شيراز، وخطبوا للملك الرحيم، وقبَضوا على الأمير أبي منصورٍ ووالدته، وكان ذلك في شوال. ووَلَّت دولةُ بني بُوَيه في أيَّام الملك الرحيم، وقامت دولةُ بني سُلجوق."},{"id":1533,"title":"محاصرة العساكر المصرية العبيدية مدينة حلب .","date":["العام الهجري :440","الشهر القمري : جمادى الآخرة","العام الميلادي :1048"],"text":"وصلت عساكِرُ مِصرَ العُبَيديَّة إلى حَلَب في جمعٍ كثيرٍ فحَصَروها، وبها مُعِزُّ الدَّولة أبو علوان ثمال بن صالح الكلابي، فجمع جمعًا كثيرًا بلغوا خمسةَ آلاف فارس وراجل، فلمَّا نزلوا على حلب خرج إليهم ثمال وقاتلهم قِتالًا شديدًا صبَرَ فيه لهم إلى الليل، ثم دخل البلدَ، فلمَّا كان الغد اقتتلوا إلى آخِرِ النهار، وصبر أيضًا ثمال، وكذلك أيضًا اليوم الثالث، فلما رأى المصريُّونَ صَبْرَ ثمال، وكانوا يظنُّونَ أنَّ أحدًا لا يقوم بين أيديهم رحلوا عن البلد، فاتَّفَق أن جاء مطر عظيمٌ تلك الليلة لم يَرَ النَّاسُ مثله، وجاءت المدودُ إلى منزل، فبلغ الماءُ ما يقارب قامتين، ولو بَقُوا لغرقوا، لكنهم رحلوا إلى الشامِ الأعلى."},{"id":1534,"title":"وفاة الفيلسوف المؤرخ الموسوعي البيروني .","date":["العام الهجري :440","الشهر القمري : رجب","العام الميلادي :1049"],"text":"هو الفيلسوفُ المُنَجِّم مُحمَّد بنُ أحمد أبو الريحان البيروني الخوارزمي مُؤرخٌ مُحَقِّقٌ وجغرافيٌّ مُدقِّق، وفلَكيٌّ نابِهٌ، ورياضيٌّ أصيلٌ، وفيزيائيٌّ راسخٌ، ومترجِمٌ متمَكِّنٌ، مِن بلادِ السندِ، ومن أعيان الفلاسفة. عاصر الرَّئيسَ ابن سينا وجَرَت بينهما حوارات وأسئلةٌ وجوابات، وكان عالِمًا في الهيئة والنجوم، خبيرًا بالطبِّ. وُلد في بيرون إحدى ضواحي خوارزم، وهو مجهولُ النَسَب؛ فقد قال عن نفسِه في شعر: إذ لستُ أعرِفُ جَدِّي حقَّ مَعرفةٍ وكيف أعرِفُ جدي إذ جَهِلتُ أبيأبي أبو لهبٍ شَيخٌ بلا أدَبِ نَعَم ووالدتي حمَّالةُ الحَطَب يقول ياقوت الحموي\" \"بيرون بالفارسية معناه برّا، وسألتُ بعض الفضلاءِ عن ذلك فزعَم أنَّ مقام البيروني بخوارزم كان قليلًا، وأهلُ خوارزم يسمُّونَ الغريبَ بهذا الاسم، كأنَّه لَمَّا طالت غربتُه عنهم صار غريبًا، وما أظنُّه يُرادُ به إلَّا أنَّه من أهل الرستاق، يعني أنَّه من برّا البلد\". كتب في كلِّ ما كان معروفًا مِن علومِ عَصرِه، وهو بذلك يُعدُّ أحدَ الموسوعيِّينَ. قال ياقوت الحموي: \" وأما سائِرُ كُتُبِه في علومِ النُّجومِ والهيئةِ والمَنطِقِ والحكمةِ؛ فإنَّها تفوق الحَصرَ، رأيتُ فَهرسَتَها في وقْفِ الجامع بمرو في نحوِ الستين ورقةً بخط مكتنز\". لَمَّا صَنَّف القانونَ المسعودي أجازه السلطانُ مسعود بن محمود الغزنوي بحَملِ فيلٍ مِن نقدِه الفِضِّي إليه، فردَّه إلى الخزانةِ بعُذرِ الاستغناء عنه، وكان مُكِبًّا على تحصيلِ العلوم مُنصَبًّا إلى تصنيف الكتُبِ، يفتَحُ أبوابها، ويُحيطُ شواكِلَها وأقرابَها، ولا يكاد يفارِقُ يدَه القلمُ وعَينَه النَّظرُ وقَلْبَه الفِكَرُ إلَّا في يومَيِ النيروز والمهرجان من السَّنة، ثمَّ هِجِّيراه في سائر الأيَّام من السَّنَةِ عِلمٌ يُسفِرُ عن وجهه قِناعَ الأشكال ويحسِرُ عن ذراعيه كمامَ الأغلاق. وأمَّا نباهةُ قَدرِه ومكانته عند الملوك فقد بلغ من حظوتِه لديهم أنَّ شمس المعالي قابوس بن وشمكير أراد أن يستخلِصَه لصُحبتِه ويرتبِطَه في دارِه على أن تكونَ له الإمرةُ المطاعةُ في جميع ما يحويه مُلكُه، فأبى عليه ولم يطاوِعْه، ولَمَّا أسمَحَت نفسُه بمثل ذلك لخوارزم شاه آواه في داره وأنزله معه في قَصرِه، لَمَّا استولى السُّلطانُ محمود على خوارزم قَبَضَ على البيروني وعلى أستاذِه عبد الصمد أول بن عبد الصمد الحكيم واتَّهَمه بالقَرمطةِ والكُفرِ، فأذاقه الحِمامَ، وهمَّ أن يُلحِقَ به أبا الرَّيحان البيروني، فقيل له إنَّه إمامُ وَقتِه في علمِ النُّجومِ، وإنَّ الملوكَ لا يَستَغنونَ عن مِثلِه، فأخَذَه معه، ودخل إلى بلادِ الهندِ وأقام بينهم وتعلَّم لُغتَهم واقتبس علومَهم، ثمَّ أقام بغُزنة حتى مات بها, وعلى الرغمِ مِن أنَّ البيروني لم يكن عربيًّا إلَّا أنَّه كان مُقتَنِعًا بأنَّ اللغةَ العربيَّةَ هي اللُّغةُ الوحيدةُ الجديرةُ بأن تكونَ لغةَ العِلمِ، وقد نُسِبَ إليه أنَّه قال: الهجوُ بالعربيَّةِ أحَبُّ إليَّ من المدحِ بالفارسيَّة. ومن أشهر كتب البيروني: الآثارُ الباقية عن القرون الخالية، وهو من أبرَزِ كُتُبِ التقاويم، القانونُ المسعودي في علمِ الفلك والجغرافيا والهندسة، الاستيعابُ في صنعة الأسطرلاب، الصَّيدنَة في الطب, تحديدُ نهايات الأماكن لتصحيح مسافات المساكن، تحقيقُ ما للهند من مقولةٍ مقبولة في العقل أو مرذولة، التفهيمُ لصناعة التنجيم. وغيرها كثير، وللبَيروني لَمَحاتٌ علميَّةٌ سبق بها عصرَه، منها قولُه بأن واديَ السِّندِ كان يومًا قاعَ بحرٍ ثم غطَّتْه الرواسِبُ الفَيضيَّة بالتدريج، والقولُ بدوران الأرضِ حول محْورِها، والقول بجاذبيَّة الأرض, وله في الرياضيَّات السبقُ الذي لم يشقَّ المُحضرون غبارَه، ولم يلحق المُضمِّرون المُجيدون مِضمارَه. توفي في غزنة (كابول الآن)."},{"id":1535,"title":"الفتنة بين السنة والشيعة في الكرخ ببغداد .","date":["العام الهجري :441","العام الميلادي :1049"],"text":"مُنِعَ أهلُ الكرخ في بغداد من النَّوحِ وفِعلِ ما جَرَت عادتُهم بفعله يومَ عاشوراء، فلم يَقبَلوا وفعلوا ذلك، فجرى بينهم وبين السُّنَّة فِتنةٌ عظيمة قُتِلَ فيها وجُرِحَ كثيرٌ من الناس، ولم ينفَصِل الشَّرُّ بينهم حتى عبَرَ الأتراك وضربوا خيامَهم عندهم، فكَفُّوا حينئذ، ثم شرع أهلُ الكرخ في بناء سورٍ على الكرخ، فلمَّا رآهم السنَّةُ من القلَّائين – صَنعَتُهم القَليُ- ومَن يجري مجراهم، شرعوا في بناءِ سُورٍ على سوق القلَّائين، وأخرج الطائِفتانِ في العمارةِ مالًا جليلًا، وجَرَت بينهما فِتَنٌ كثيرة، وبَطَلَت الأسواق، وزاد الشَّرُّ، حتى انتقل كثيرٌ من الجانب الغربي إلى الجانِبِ الشرقيِّ فأقاموا به، وتقدَّمَ الخليفة إلى أبي مُحمَّد بن النسوي بالعبور وإصلاحِ الحالِ وكفِّ الشَّرِّ، فسَمِعَ أهل الجانب الغربي ذلك، فاجتمع السُّنَّةُ والشيعة على المنعِ منه، وأَذَّنوا في القلَّائينَ وغيرِها بحيَّ على خيرِ العمل، وأَذَّنوا في الكرخ الصلاةُ خَيرٌ من النوم، وأظهروا الترَحُّمَ على الصحابةِ."},{"id":1536,"title":"فتنة بين الملك طغرلبك وبين أخيه إبراهيم ينال .","date":["العام الهجري :441","العام الميلادي :1049"],"text":"سببُ ذلك أنَّ طغرلبك طلَبَ مِن إبراهيم ينال أن يُسَلِّمَ إليه مدينة همذان والقلاعَ التي بيده من بلدِ الجبل، فامتنَعَ مِن ذلك، واتَّهَم وزيرَه أبا عليٍّ بالسعيِ بينهما في الفَسادِ، فقَبَض عليه، وأمَرَ به فضُرِبَ بين يديه، وسَمَل إحدى عينيه، وقطَعَ شَفَتَيه، فسار إلى طغرلبك، وجمع جمعًا مِن عَسكَرِه، والتقيا، وكان بين العسكرين قتالٌ شديدٌ انهزم ينال وعاد مُنهَزِمًا، فسار طغرلبك في أثَرِه، فملك قلاعَه وبلادَه جَميعَها، وتحصَّنَ إبراهيمُ ينال بقلعة سرماج، وامتنع على أخيه، فحَصَره طغرلبك فيها، وكانت عساكِرُه قد بلغت مِئَة ألف من أنواع العَسكَر، وقاتَلَه، فملكها في أربعةِ أيام، وهي من أحصَنِ القلاع وأمنَعِها، واستنزل ينال منها مَقهورًا، وأرسل إلى نصر الدَّولة بن مروان يطلُبُ منه إقامةَ الخُطبة له في بلاده، فأطاعه وخطَبَ له في سائر ديار بكر، وراسل مَلِكُ الرومِ طغرلبك، وأرسل إليه هديَّةً عظيمةً، وطلب منه المُعاهَدة، فأجابه إلى ذلك، وعَمَروا مسجِدَ القُسْطنطينيَّة، وأقاموا فيه الصَّلاةَ والخطبة لطغرلبك، ودان حينئذٍ النَّاسُ كُلُّهم له، وعَظُمَ شأنُه وتمكَّن مُلكُه وثبت، ولَمَّا نزل ينال إلى طغرلبك أكرَمَه وأحسن إليه، وردَّ عليه كثيرًا ممَّا أخذ منه، وخيَّرَه بين أن يُقطِعَه بلادًا يسير إليها، وبين أن يقيمَ معه، فاختار المقامَ معه."},{"id":1537,"title":"وفاة الحافظ أبي عبد الله محمد بن علي الصوري .","date":["العام الهجري :441","الشهر القمري : جمادى الآخرة","العام الميلادي :1049"],"text":"هو الحافِظُ أبو عبد الله مُحمَّدُ بنُ عليِّ بنِ عبد الله بن محمد الصوري، أحَدُ علماء الحديثِ؛ طلب الحديثَ بنَفسِه على الكِبَرِ، ورحَلَ في طلبه إلى الآفاق. كان من أعظَمِ أهل الحديث هِمَّةً في الطلب وهو شابٌّ، ثم كان من أقوى النَّاسِ على العمَلِ الصالحِ عزيمةً في حالِ كِبَرِه. كان صوَّامًا يَسرِدُ الصومَ إلَّا يومَيِ العيدينِ وأيام التشريق، وكان مع ذلك حَسَن الخُلُق جميلَ المعاشرة، محبًّا للشِّعرِ، وقد ذهبت إحدى عَينيه، وكان يكتُبُ بالأخرى المجَلَّدَ في جزءٍ. قال أبو الحسن الطيوري: \"يقال إنَّ عامَّةَ كُتُبِ الخطيبِ سوى التاريخِ مُستفادةٌ مِن كُتُبِ أبي عبد الله الصوري، لَمَّا مات ترك كتبَه اثني عشر عِدلًا عند أخيه، فأخذ الخطيبُ بعض تلك الكتب فحوَلَّها في كتُبِه\", وكان سبَبُ مَوتِه أنَّه افتصد فوَرِمَت يدُه، وقيل إنَّ ريشةَ الفاصد كانت مسمومةً لِغَيره فغَلِطَ ففَصَده بها، فكانت فيها منيَّتُه، فحُمِلَ إلى المارستان فمات به، ودُفِنَ بمقبرة جامع المدينة، وقد نَيَّف على الستين."},{"id":1538,"title":"وفاة مودود الغزنويّ وقيام عمه عبد الرشيد بالأمر بعده .","date":["العام الهجري :441","الشهر القمري : رجب","العام الميلادي :1049"],"text":"هو أبو الفَتحِ مَودود بن مسعود بن محمود بن سبكتكين الغزنويُّ، صاحِبُ غزنة، لَمَّا ملَكَ مودودٌ قَبَض على عمِّه عبدِ الرَّشيدِ بنِ محمود وسَجَنَه في قلعة ميدين، بطريقِ بست، وكاتَبَ أصحابَ الأطرافِ ودعاهم إلى نُصْرَتِه، وبذل لهم الأموالَ والإمرةَ على بلادِ خُراسان فأجابوه، منهم: أبو كاليجار صاحِبُ أصبهان، فإنَّه سار بجيوشِه في المفازة فهلك كثيرٌ مِن عسكره، ومَرِضَ هو ورجع، ومنهم خاقان التُّرك فإنَّه أتى ترمذ فنهَبَ وخَرَّب وصادَرَ، وسار مودودٌ مِن غزنة فاعتراه قولنج، فرجع وبَعَث وزيرَه لأخذ سجستان من الغز، وكان مَوتُه بغزنة, ومُدَّةُ مُلكِه تِسعَ سنين وعشرة أشهر،، ثم قام في المُلكِ بعده ولَدُه، فبقي خمسة أيام ثمَّ عَدَل النَّاسُ عنه إلى عَمِّه علي بن مسعود، فنزل عبدُ الرشيد إلى العَسكَرِ ودعاهم إلى طاعته، فأجابوه وعادوا معه إلى غزنة، فلمَّا قارَبَها هرب عنها عليُّ بنُ مسعود، ومَلَك عبد الرشيد، واستقَرَّ الأمر له، ولُقِّبَ شمس دين الله سيف الدَّولة، وقيل جمال الدَّولة، ودفع اللهُ شَرَّ مودود عن داود."},{"id":1539,"title":"الخوارج يستولون على عمان .","date":["العام الهجري :442","العام الميلادي :1050"],"text":"استولى الخوارجُ المُقيمونَ بجبال عُمان على مدينةِ الولاية، وسبَبُ ذلك أنَّ صاحِبَها الأمير أبا المُظَفَّر ابن الملك أبي كاليجار كان مُقيمًا بها، ومعه خادِمٌ له قد استولى على الأمورِ، وحَكَم على البلاد، وأساء السيرةَ في أهلها، فأخذ أموالَهم، فنفروا منه وأبغَضوه، وعَرَفَ إنسانٌ من الخوارجِ- يقالُ له ابنُ راشدٍ- الحالَ، فجمع مَن عنده منهم فقَصَد المدينةَ، فخرج إليه الأميرُ أبو المُظَفَّر في عساكِرِه، فالتَقَوا واقتَتَلوا، فانهزمت الخوارجُ وعادوا إلى موضِعِهم، وأقام ابنُ راشد مدَّةً يجمَعُ ويحتَشِدُ، ثم سار ثانيًا، وقاتله الديلم فأعانه أهلُ البلد لسوءِ سِيرةِ الديلم فيهم، فانهزم الديلم، وملَكَ ابنُ راشد البلد وقتل الخادِمَ وكثيرًا من الديلم، وقبض على الأميرِ أبي المظفَّر وسَيَّرَه إلى جباله مُستَظهرًا عليه، وسَجَن معه كُلَّ مَن خَطَّ بقلمٍ مِن الديلم، وأصحابَ الأعمال، وأخرب دارَ الإمارة، وقال: هذه أحقُّ دارٍ بالخراب، وأظهَرَ العدل، وأسقَطَ المكوسَ، واقتصر على رَفعِ عُشرِ ما يَرِدُ إليهم، وخطَبَ لنَفسِه، وتلقَّبَ بالراشد بالله، ولَبِسَ الصوف، وبنى موضعًا على شَكلِ مسجد، وقد كان هذا الرجلُ تَحَرَّك أيضًا أيامَ أبي القاسم بن مكرم، فسَيَّرَ إليه أبو القاسِمِ مَن منعه وحصَرَه وأزال طَمَعَه."},{"id":1540,"title":"محاولة المستنصر العبيدي الفاطمي استعادة نفوذه في إفْريقيَّة .","date":["العام الهجري :442","العام الميلادي :1050"],"text":"لَمَّا قطَعَ المُعِزُّ بنُ باديس الخطبةَ للفاطميِّينَ وخطَبَ للعباسيِّينَ، وأعلن بذلك انشقاقَه عن الفاطميِّينَ وولاءَه للعباسيِّينَ، كاد له المستنصِرُ الفاطميُّ حاكِمُ مِصرَ لَمَّا عجز عنه بنَفسِه وجَيشِه عن قَهرِه، أرسل إليه جموعًا مِن العرب الهلاليَّة مِن بني زغبة ورياح، وهم بطونُ بني عدي الأثبج، وكانوا يسكُنونَ على الضَّفَّة الشرقيَّة من صعيد مصر بعد قُدومِهم من نجد، وكان المستنصِرُ قد عقد لرؤسائِهم ورجالاتِهم على أمصارِ البلاد المغربيَّة وثُغورِها، وقلَّدَهم كثيرًا من الأعمال والولاياتِ؛ كلُّ ذلك انتقامًا مِن المعِزِّ بن باديس، فخرجت في هذه السَّنةِ أوَّلُ حملةٍ بنحوِ أربعمِئَة ألف شَخصٍ، فساروا حتى نزلوا بُرقةَ وأغاروا على طرابلس والقيروان ونَهَبوا وقطعوا الطريقَ، وصَدُّوا جميع الحَمَلاتِ التي سَيَّرَها المعِزُّ ضِدَّهم؛ مما اضطرَّ المعِزَّ للتحَوُّلِ إلى المهدية، ثم تلَتْها حَملاتٌ أخرى عُرِفَت في التاريخِ والقِصَص بتغريبةِ بني هلالٍ."},{"id":1541,"title":"فَتحُ طُغرلبك بِلادَ أصبهان .","date":["العام الهجري :442","الشهر القمري : محرم","العام الميلادي :1050"],"text":"كان أبو منصورِ بن عَلاءِ الدَّولةِ، صاحبُ أصبهان، غيرَ ثابتٍ على طَريقةٍ واحدةٍ مع السُّلطانِ طغرلبك، كان يُكثِر التَّلَوُّنَ معه، تارةً يُطيعُه ويَنحازُ إليه، وتارةً يَنحرِف عنه ويُطيعُ المَلِكَ الرَّحيمَ البويهي، فأضمر له طُغرلبك سُوءًا، فلما عاد من خُراسان لِأَخذِ البلادِ الجَبليَّةِ من أَخيهِ إبراهيمَ ينال، واستولى عليها عَدَلَ إلى أصبهان عازِمًا على أَخذِها من أبي منصورٍ، الذي سَمِع بالخبرِ، فتَحَصَّن بِبَلدِه، واحتَمَى بِأَسوارِه، ونازَلَهُ طُغرلبك في المُحَرَّم، وأقام على مُحاصَرتِه نحوَ سَنَةٍ، وكَثُرَت الحروبُ بينهما، إلا أنَّ طُغرلبك قد استولى على سَوادِ البلدِ، وأَرسلَ سَرِيَّةً من عَسكرِه نحوَ فارس، فبلغوا إلى البَيضاء، فأغاروا على السَّوادِ هناك وعادوا غانِمينَ، ولمَّا طال الحِصارُ على أصبهان، وأخرَبَ أَعماَلها، ضاق الأمرُ بصاحبِها وأَهلِها، وأرسلوا إليه يَبذُلون له الطَّاعةَ والمالَ، فلم يُجِبهُم إلى ذلك، ولم يَقنَع منهم إلا بِتَسليمِ البلدِ، فصَبَروا حتى نَفَدَت الأقواتُ، ونَفَدَ الصَّبرُ، وانقطعت المَوادُّ، وسَلَّموا البلدَ إليه، فدَخَله وأَخرَج أجنادَه منه وأَقطَعَهم في بلادِ الجبلِ، وأَحسنَ إلى الرَّعِيَّة، وأَقطعَ صاحبَها أبا منصورٍ ناحيتي يزد وأبرقوية، وتَمَكَّن من أصبهان ودَخَلها في المُحَرَّم من سنة 443هـ واستَطابَها، وأقام فيها."},{"id":1542,"title":"استيلاءُ الغُزِّ السلاجقة على مَدينةِ فَسا .","date":["العام الهجري :442","الشهر القمري : جمادى الأولى","العام الميلادي :1050"],"text":"سار المَلِكُ أَلب أَرسلان بن داودَ ابن أخي طُغرلبك من مدينةِ مَرو بخُراسان، وقَصَد بِلادَ فارس في المَفازَة، فلم يَعلَم به أحدٌ، ولا أَعلَم عَمَّهُ طُغرلبك، فوَصَل إلى مَدينةِ فَسا، فانصرف النَّائِبُ بها من بين يديه، ودَخلَها أَلبُ أَرسلان فقَتَل من الدَّيلم بها ألفَ رَجُل، وعددًا كثيرًا من العامَّةِ، ونَهبوا ما قَدرُه ألف ألف دينار، وأسروا ثلاثةَ آلافِ إنسانٍ، وكان الأمرُ عظيمًا. فلمَّا فَرغوا من ذلك عادوا إلى خُراسان، ولم يَلبَثوا خَوفًا من طُغرلبك أن يُرسِل إليهم، ويأخُذ ما غَنموهُ منهم."},{"id":1543,"title":"فِتنةٌ عَظيمةٌ بين السُّنَّةِ والشِّيعَةِ ببغداد .","date":["العام الهجري :443","العام الميلادي :1051"],"text":"تَجدَّدت الفِتنةُ ببغداد بين السُّنَّةِ والشِّيعَة، وعَظُمَت أضعافَ ما كانت عليه قديمًا، وكان سببُ هذه الفِتنَة أنَّ أهلَ الكَرخ عَمِلوا أَبراجًا كَتَبوا عليها بالذَّهَبِ: محمدٌ وعَلِيٌّ خَيرُ البَشَرِ. وأَنكرَ السُّنَّةُ ذلك، وادَّعوا أنَّ المكتوبَ: محمدٌ وعَلِيٌّ خَيرُ البَشَرِ، فمَن رَضِيَ فقد شَكَر، ومَن أَبَى فقد كَفَر. وأَنكَر أهلُ الكَرخ الزِّيادةَ وقالوا: ما تَجاوَزنا ما جَرَتْ به عادتُنا فيما نَكتُبه على مساجِدِنا. فأَرسَل الخليفةُ القائمُ بأَمرِ الله أبا تَمَّام، نَقِيبَ العبَّاسِيِّين ونَقِيبَ العَلَوِيِّين، وهو عَدنان بن الرَّضي، لِكَشفِ الحالِ وإنهائِه، فكَتَبا بِتَصديقِ قَولِ الكَرخِيِّين، فأَمَرَ حينئذ الخليفةُ ونُوَّابُ المَلِكِ الرَّحيم البويهي بِكَفِّ القِتالِ، فلم يَقبَلوا، فأَمسَك نُوَّابُ المَلِكِ الرَّحيم عن كَفِّهِم غَيْظًا من رَئيسِ الرُّؤساءِ لِمَيْلِه إلى الحَنابِلَة، وتَشَدَّدَ رَئيسُ الرُّؤساءِ على الشِّيعَةِ، فمَحَوْا: خَيرَ البَشَر. وكتبوا: عليهما السَّلامُ. فقالت السُّنَّةُ: لا نرضى إلا أن يُقلَع الآجُرُّ، وأن لا يُؤَذَّنَ: حَيَّ على خَيرِ العَمَل. وامتَنَع الشِّيعَةُ من ذلك، ودام القِتالُ إلى ثالِثِ ربيعٍ الأوَّل، وقُتِلَ فيه رَجلٌ هاشِمِيٌّ مِن السُّنَّةِ، فحَمَلهُ أَهلُه على نَعْشٍ، وطافوا به في الحربِيَّة، وبابِ البَصرَةِ، وسائرِ مَحالِّ السُّنَّةِ، واسْتَنْفَروا النَّاسَ للأَخْذِ بِثَأْرِهِ، ثم دَفنوهُ عند أحمد بن حَنبل، وقد اجتمع معهم خَلْقٌ كَثيرٌ أضعافَ ما تَقدَّم. فلمَّا رجعوا من دَفنِه قَصَدوا مَشهدَ بابِ التِّبْنِ فأُغْلِقَ بابُه، فنَقَبوا في سُورِهِ وتَهَدَّدوا البَوَّابَ، فخافَهُم وفَتحَ البابَ فدخلوا ونَهَبوا ما في المَشهَدِ من قَناديلَ ومَحارِيبَ ذَهَبٍ وفِضَّةٍ وسُتُورٍ وغيرِ ذلك، ونَهَبوا ما في التُّربِ والدُّورِ، وأَدرَكهم اللَّيلُ فعادوا، فلمَّا كان الغَدُ كَثُرَ الجَمْعُ، فقَصَدوا المَشهَد، وأحرقوا جميعَ التُّربِ والآزاجِ، واحتَرقَ ضَريحُ موسى، وضَريحُ ابنِ ابنِه محمدِ بن عَلِيٍّ، والجوار، والقُبَّتانِ السَّاج اللَّتانِ عليهما، واحتَرَق ما يُقابِلهما ويُجاوِرهما من قُبورِ مُلوكِ بني بُويه الشِّيعَة، مُعِزِّ الدَّولَة، وجَلالِ الدَّولَة، ومن قُبورِ الوُزراءِ والرُّؤساءِ، وقَبرُ جَعفرِ بن أبي جَعفرِ المنصور، وقَبرُ الأمير محمدِ بن الرَّشيد، وقَبرُ أُمِّهِ زُبيدَة، فلمَّا كان الغَدُ خامِس الشَّهر عادوا وحَفَروا قَبرَ موسى بن جَعفرِ ومحمدِ بن عَلِيٍّ لِيَنقُلوهما إلى مَقبرَة أحمد بن حَنبل، فحال الهَدْمُ بينهم وبين مَعرفَة القَبرِ، فجاء الحَفرُ إلى جانِبِه، وسَمِعَ أبو تَمَّام نَقيبُ العبَّاسِيِّين وغَيرُه من الهاشِمِيِّين السُّنَّة الخَبَرَ، فجاؤوا ومَنَعوا عن ذلك، وقَصَد أهلُ الكَرخِ الشِّيعَة إلى خان الفُقهاءِ الحَنفِيِّين فنَهَبوه، وقَتَلوا مُدَرِّسَ الحَنفِيَّة أبا سعد السَّرخسي، وأحرقوا الخانَ ودُورَ الفُقهاءِ، وتَعَدَّت الفِتنةُ إلى الجانبِ الشَّرقيِّ، فاقْتَتَلَ أهلُ بابِ الطَّاقِ وسُوق بَجٍّ، والأساكِفَةُ -صُنَّاع الأحذية- وغَيرُهم، ولمَّا انتهى خَبَرُ إحراقِ المَشهَد إلى نُورِ الدَّولة دُبَيْسِ بن مَزْيَد عَظُم عليه واشتَدَّ وبَلَغ منه كُلَّ مَبلَغ؛ لأنَّه وأهلَ بَيتِه وسائِرَ أَعمالِه من النيل وتلك الوِلايَة كُلُّهم شِيعَة، فقُطِعَت في أَعمالِه خُطبةُ الإمامِ القائمِ بِأَمرِ الله، فرُوسِلَ في ذلك وعُوتِبَ، فاعتَذرَ بأنَّ أهلَ وِلايتِه شِيعَة، واتَّفَقوا على ذلك، فلم يُمكِنهُ أن يَشُقَّ عليهم، كما أنَّ الخليفةَ لم يُمكِنهُ كَفُّ السُّفَهاء الذين فعلوا بالمَشهدِ ما فعلوا، وأعاد الخُطبةَ إلى حالِها، ثم تَجدَّدَت هذه الفِتنةُ في السَّنَةِ التَّاليةِ في ذي القعدة."},{"id":1544,"title":"ابن أبى كاليجار البويهي يسيطر على بلاد إصطخر وشيراز .","date":["العام الهجري :443","العام الميلادي :1051"],"text":"سَيَّرَ المَلِكُ الرَّحيمُ ابن أبى كاليجار البويهي الشِّيعي أخاهُ الأميرَ أبا سعد في جَيشٍ إلى بلادِ فارس، وكان سببُ ذلك أنَّ المُقيمَ في قَلعةِ إصطخر، وهو أبو نصر بن خسرو، وكان له أَخَوان قَبَضَ عليهما هزارسبُ بن بنكير بِأَمْرِ الأَميرِ أبي منصور بن المَلِكِ أبي كاليجار، فكتَبَ إلى المَلِكِ الرَّحيم البويهي الشِّيعي يَبذُل له الطَّاعة والمُساعَدة، ويَطلُب أن يُسَيِّر إليه أخاهُ لِيُمَلِّكَهُ بلادَ فارس، فسَيَّرَ إليه أخاهُ أبا سعد في جَيشٍ، فوصَلَ إلى دولةِ أباذ، فأتاه كَثيرٌ مِن عَساكر فارس: الدَّيلمِ، والتُّرْكِ، والعَرَبِ، والأَكرادِ، وسار منها إلى قَلعةِ إصطخر، فنزل إليه صاحبُها أبو نصر، فلَقِيَهُ وأَصعدَهُ إلى القَلعةِ، وحمَلَ له وللعَساكر التي معه الإقامات والخِلَعِ وغيرها، ثم ساروا منها إلى قَلعةِ بهندر فحَصَروها، وأتاهُ كُتُبُ بعضِ مُستَحفِظي البلادِ الفارسيَّة بالطَّاعةِ، منها مُستَحفِظ درابجرد وغيرها، ثم سار إلى شيراز فمَلكَها في رمضان، فلمَّا سَمِعَ أخوهُ الأميرُ أبو منصور، وهزارسب، ومنصور بن الحسين الأسديُّ ذلك ساروا في عَسكرِهم إلى المَلِكِ الرَّحيم فهَزَموه، وفارَق الأهوازَ إلى واسط، ثم عَطَفوا من الأهوازِ إلى شِيراز لِإجلاءِ الأميرِ أبي سعدٍ عنها، فلمَّا قاربوها لَقِيَهم أبو سعدٍ وقاتَلَهم فهَزمَهم، فالتجَأُوا إلى جبلِ قَلعةِ بهندر، وتَكرَّرت الحروبُ بين الطائِفَتينِ إلى مُنتصفِ شَوَّال، فتَقدَّمت طائفةٌ من عَسكرِ أبي سعدٍ فاقتَتَلوا عامَّة النَّهارِ ثم عادوا، فلمَّا كان الغدُ التقى العَسكرانِ جميعًا واقتَتَلوا، فانهَزمَ عَسكرُ الأميرِ أبي منصور، وظَفَر أبو سعدٍ، وقَتَل منهم خَلْقًا كَثيرًا، واستَأمَن إليه كثيرٌ منهم، وصعد أبو منصور إلى قَلعةِ بهندر واحتَمَى بها، وأقام إلى أن عاد إلى مُلكِه، ولما فارَق الأميرُ أبو منصور الأهوازَ أُعيدَت الخطبة للمَلِكِ الرَّحيم، وأَرسلَ مَن بها مِن الجُندِ يَستدعونَه إليهم."},{"id":1545,"title":"وفاة صاحبِ المَوصِل أَميرِ بني عُقيلٍ، وقيام إمارة قُريشِ بن بَدران .","date":["العام الهجري :443","الشهر القمري : رمضان","العام الميلادي :1052"],"text":"زَعيمُ الدَّولة، أبو كامل، بَرَكَة بن المُقَلِّد، أميرُ بني عُقيلٍ، وصاحبُ المَوصِل بن المُسيبِ بن رافِع بن المُقلِّد بن جعفرِ بن عَمروِ بن المُهَنَّا بن عبدِ الرَّحمن بن بُرَيد -مُصغَّرًا- يَنتهِي إلى هوازن العُقَيلي، هو من بَيتٍ كَبيرٍ في الإمرَةِ. كان بَركةُ بن المُقلِّد قد غَلَب على المَوصِل وغَيرِها، وقَهَر أخاهُ قرواشا، وعاثَ وأَفسَد وعَسَف، وفي هذه السَّنَةِ انحدَر إلى تكريت في حُلَلِهِ قاصدًا نحوَ العِراق لِيُنازِعَ النُّوَّاب به عن المَلِكِ الرَّحيم، ويَنهَب البِلادَ، فلمَّا بَلغَها انتَقضَ عليه جُرحٌ كان أصابهُ من الغُزِّ لمَّا مَلَكوا المَوصِل، فتُوفِّي، ودُفِنَ بتكريت. واجتمعت العربُ من أصحابِه على تَأميرِ عَلَمِ الدِّين أبي المعالي قُريشِ بن بَدران بن المُقلِّد، فعاد بالحُلَلِ والعربِ إلى المَوصِل وأَرسَل إلى عَمِّه قِرواش، وهو تحت الاعتقالِ يُعلِمُه بوَفاةِ زَعيمِ الدَّولةِ، وقِيامِه بالإمارة، وأنَّه يَتَصرَّف على اختِيارِه، ويقوم بالأَمرِ نِيابةً عنه. فلمَّا وصل قُريشٌ إلى المَوصِل جَرى بينهُ وبين عَمِّه قِرواش مُنازَعة، ضَعُفَ فيها قِرواش، وقَوِيَ ابنُ أخيهِ، ومالت العربُ إليه، واستقَرَّت الإمارةُ له، وعاد عَمُّه إلى ما كان عليه من الاعتقالِ، ثم نَقلَهُ إلى قَلعةِ الجَرَّاحِيَّة مِن أَعمالِ المَوصِل، فاعتُقِلَ بها."},{"id":1546,"title":"أهل بغداد يقَدْحُون في نَسَبِ العُبيديِّين (الفاطميِّين) .","date":["العام الهجري :444","العام الميلادي :1052"],"text":"عُمِلَ مَحضَرٌ ببغداد يتضمن القَدْحَ في نَسَبِ العَلويِّين أصحاب مصر، وأنهم كاذبون في ادعائهِم النَّسَبَ إلى عَلِيِّ بن أبي طالبٍ، وعَزُوهُم فيه إلى الدَّيْصانِيَّة مِن المَجوس، والقَدَّاحِيَّة مِن اليهود، وكَتَبَ فيه العَلويُّون، والعبَّاسِيُّون، والفُقهاء، والقُضاة، والشُّهود، وعُمِلَ به عِدُّة نُسَخٍ، وسُيِّرَ في البِلادِ، وشِيعَ بين الحاضرِ والبادي."},{"id":1547,"title":"وَفاةُ عبدِ الرَّشيد بن محمود بن سُبُكْتِكِين صاحب غَزْنَة .","date":["العام الهجري :444","العام الميلادي :1052"],"text":"هو عبدُ الرَّشيد بن محمود بن سُبُكْتِكِين، مِن مُلوكِ الدَّولة الغَزْنويَّة، كان ابنُ أخيهِ مَوْدودُ بن مسعود قد حَبسَهُ في قَلعةِ ميدين، ولما تُوفِّي مَودود سنة 441هـ خَلَفَهُ وَلدٌ له، فبَقِيَ خَمسةَ أيَّامٍ ثم قَصدَ بعضُ النَّاسِ القَلعةَ وأَخرَجوا عبدَ الرَّشييد وبايعوه ودَخلوا معه غَزنَة، ولَقَّبوهُ شَمسَ دِين الله، وكان ضَعيفًا قَليلَ الحِيلَة، فلم يَطُل عَهدُه, فقد قَتلَهُ حاجبٌ لِمَودود اسمهُ طُغْرُل، وكان مَودود قد قَدَّمَهُ، ونَوَّه باسمِه، وزَوَّجَهُ أُختَه، فلمَّا تُوفِّي مَودود ومَلَكَ عبدُ الرَّشيد أَجرَى طُغرُل على عادتِه في تَقدُّمِه، وجَعلهُ حاجبَ حُجَّابِه، فأشار عليه طُغرُل بِقَصدِ الغُزِّ وإجلائهِم مِن خُراسان، فسَيَّرَهُ إليها، فقَوِيَ أَمرُ طُغرُل هذا إلى أن حَدَّثَتهُ نَفسُه بِمُلْكِ غَزْنَة بدل عبدِ الرَّشيد، فأَعمَل الحِيلةَ وعاد بالجُيوش التي كانت معه، وقَتَلَ عبدَ الرَّشيد وتَزوَّج أُختَه كُرْهًا ومَلَكَ البَلدَ."},{"id":1548,"title":"وُصولِ الغُزِّ السَّلاجِقَة إلى فارس وانهزامُهم عنها .","date":["العام الهجري :444","العام الميلادي :1052"],"text":"وَصلَ أَصحابُ السُّلطان طُغرُلبك إلى فارس، وبلغوا إلى شيراز، ونزلوا بالبَيضاءَ، واجتمع معهم العادلُ أبو منصور الذي كان وزيرَ المَلِكِ أبي كاليجار، ودَبَّرَ أَمرَهم، فقَبَضوا عليه وأخذوا منه ثلاثَ قِلاعٍ، وهي: قَلعةُ كَبْزَة، وقَلعةُ جُوَيْم، وقَلعةُ بَهَنْدَر، فأقاموا بها، وسار مِن الغُزِّ نحو مائتي رَجُلٍ إلى الأَميرِ أبي سعدٍ، أخي المَلِكِ الرَّحيم، وصاروا معه، وراسَل أبو سعدٍ الذي بالقِلاعِ المذكورةِ، فاستَمالَهم فأطاعوه وسَلَّموهُ القِلاعَ، إليه وصاروا في خِدمتهِ، واجتمع العَسكرُ الشيرازي، وعليهم الظَّهيرُ أبو نَصرٍ، وأوقعوا بالغُزِّ ببابِ شيراز، فانهزم الغُزُّ، وأُسِرَ تاجُ الدِّين نَصرُ بن هبة الله بن أحمد، وكان من المُقَدَّمين عند الغُزِّ، فلمَّا انهزم الغُزُّ سار العَسكرُ الشيرازي إلى فَسا، وكان قد تَغلَّب عليها بعضُ السَّفِل، وقَوِيَ أَمرُه لاشتغالِ العَساكرِ بالغُزِّ، فأزالوا المُتَغَلِّب عليها واستَعادُوها."},{"id":1549,"title":"ذِكرُ دُخولِ العَربِ إلى إفريقية بتَحريضٍ مِن حاكم مصر العُبيدِي\n  .","date":["العام الهجري :444","العام الميلادي :1052"],"text":"في هذه السَّنَةِ دَخلتْ العَربُ إلى إفريقية, وسببُ ذلك أنَّ المُعِزَّ بن باديس كان خَطَبَ للقائم بأَمرِ الله الخليفة العبَّاسي، وقَطَع خُطبةَ المُستَنصِر العُبيدي الفاطمي صاحب مصر، فلمَّا فعل ذلك كَتَب إليه المُستَنصِر العَلويُّ يَتَهدَّدهُ، فأَغلظَ المُعِزُّ في الجوابِ، ثم شَرعَ المُستَنصِرُ ووَزيرهُ الحسنُ بن عَليٍّ اليازوري في إرسالِ العَربِ إلى أفريقية، وأصلحوا بني زُغْبَة ورِياحٍ، وكان بينهم حُروبٌ وحُقودٌ، وأعطوهم مالًا، وأَمروهُم بِقَصدِ بِلادِ القَيروان، ومَلَّكوهُم كُلَّ ما يَفتحونَه، ووَعَدوهُم بالمَدَدِ والعُدَدِ. فدَخلتْ العربُ إلى إفريقية، وكَتَب اليازوري إلى المُعِزِّ وكان حاقدا عليه: \"أمَّا بعدُ، فقد أرسلنا إليكم خُيولًا فُحولًا، وحَملنا عليها رِجالًا كُهولًا، ليقضي الله أمرًا كان مَفعولًا\". فاحلوا فلمَّا حَلُّوا أرضَ بَرْقَة وما والاها ووجدوا بِلادًا كَثيرةَ المَرْعَى خالِيَة مِن الأَهلِ، فأَقامَت العَربُ بها واستَوطَنَتها، وعاثوا في أَطرافِ البِلادِ, وبَلَغ ذلك المُعِزَّ فاحتَقَرهُم, وكانت عَربُ زُغبَة قد مَلكَت مَدينةَ طرابلس سنة 446هـ، فتَتابَعَت رِياحٌ والأثبجُ وبنو عَدِيٍّ إلى إفريقية، وقَطَعوا السَّبيلَ وعاثوا في الأرضِ، وأرادوا الوصولَ إلى القَيروان، فقال مُؤْنِسُ بن يحيى المِرداسيُّ: \"ليس المُبادرَة عندي بِرَأيٍ. فقالوا: كيف تُحِبُّ أن تَصنعَ؟ قال: خُذوا شيئًا فشَيئًا حتى لا يَبقَى إلَّا القَيروان، فخُذوها حينئذٍ. فقالوا: أنت المُقَدَّمُ علينا، ولَسْنَا نَقطعُ أَمرًا دُونك\". ثم قَدِم أُمراءُ العَربِ إلى المُعِزِّ فأَكرَمَهم وبَذَل لهم شيئًا كَثيرًا، فلمَّا خَرجوا مِن عِندِه لم يُجازُوهُ بما فَعلَ مِن الإحسانِ، بل شَنُّوا الغاراتِ، وقَطَعوا الطَّريقَ، وأَفسَدوا الزُّروعَ، وقَطَّعوا الثِّمارَ، وحاصَروا المُدُنَ، فضاق بالنَّاسِ الأَمرُ، وساءَت أَحوالُهم، وانقَطعَت أَسفارُهم، ونَزلَ بإفريقية بَلاءٌ لم يَنزِل بها مِثلُه قط، فحينئذٍ احتَفلَ المُعِزُّ وجَمعَ عَساكرَه، فكانوا ثلاثين ألف فارس، ومِثلَها رَجَّالَة، وسار حتى أَتَى جَنْدِران، وهو جَبَلٌ بينه وبين القَيروان ثلاثةُ أيَّامٍ، وكانت عُدَّةُ العَربِ ثَلاثةُ آلافِ فارس، فلمَّا رَأَتْ العَربُ عساكِر صنهاجة والعَبيدَ مع المُعِزِّ هالَهُم ذلك، وعَظُمَ عليهم، فقال لهم مُؤْنِسُ بن يحيى: ما هذا يوم فِرارٍ. والتَحَم القِتالُ واشتَدَّتْ الحَربُ، فاتَّفقَت صِنهاجَة على الهزيمةِ وتَرْكِ المُعِزِّ مع العَبيدِ حتى يَرَى فِعلَهم، ويُقتَل أَكثرُهم، فعند ذلك يَرجِعون على العَربِ، فانهَزمتْ صِنهاجَة وثَبَتَ العَبيدُ مع المُعِزِّ، فكَثُرَ القَتلُ فيهم، فقُتِلَ منهم خَلْقٌ كَثيرٌ، وأرادت صِنهاجة الرُّجوعَ على العَربِ فلم يُمكِنهُم ذلك، واستَمرَّت الهَزيمةُ، وقُتِلَ مِن صِنهاجة أُمَّةٌ عَظيمَة، ودَخلَ المُعِزُّ القَيروانَ مَهزومًا، على كَثرَةِ مَن معه، وأَخذتْ العَربُ الخَيْلَ والخِيامَ وما فيها مِن مالٍ وغَيرِه. ولمَّا كان يومُ النَّحْرِ من هذه السَّنَةِ جَمعَ المُعِزُّ سَبعةً وعِشرينَ ألف فارس، وسار إلى العَربِ جَرِيدَةً -الجريدة خَيْلٌ لا رَجَّالة فيها- وسَبَقَ خَبرُه، وهَجَم عليهم وهُم في صَلاةِ العِيد، فرَكِبَت العَربُ خُيولَهم وحَملَت، فانهَزَمت صِنهاجة، فقُتِلَ منهم عالَمٌ كَثيرٌ. ثم جَمعَ المُعِزُّ وخَرجَ بِنَفسِه في صِنهاجة وزِناتَة في جَمعٍ كَثيرٍ، فلمَّا أَشرفَ على بُيوتِ العَربِ، انتَشَب القِتالُ، واشتَعَلت نِيرانُ الحَربِ، وكانت العَربُ سَبعةَ آلافِ فارس، فانهَزَمت صِنهاجة، وزِناتَة، وثَبَتَ المُعِزُّ فيمَن معه من عَبيدِه ثَباتًا عَظيمًا لم يُسمَع بمِثلِه، ثم انهَزَم وعاد إلى المَنصوريَّة. وأحصي مَن قُتِلَ مِن صنهاجة ذلك اليوم، فكانوا ثلاثةَ آلاف وثلاثمائة. ثم أَقبلَت العَربُ حتى نَزلَت بمُصَلَّى القَيروان، ووَقعَت الحَربُ، فقُتِلَ مِن المَنصوريَّة ورقادة خَلْقٌ كَثيٌر، فلمَّا رأى ذلك المُعِزُّ أَباحَهم دُخولَ القَيروان لِمَا يحتاجون إليه مِن بَيعٍ وشِراءٍ، فلمَّا دخلوا استَطالَت عليهم العامَّةُ، ووَقعَت بينهم حَربٌ كان سَببُها فِتنةً بين إنسانٍ عَربيٍّ وآخرَ عامِيٍّ، وكانت الغَلَبةُ للعَربِ. وفي سنة 444هـ بُنِيَ سورُ زويلة والقَيروان، وفي سنة 446هـ حاصرت العَربُ القَيروانَ، ومَلَكَ مُؤنِسُ بن يحيى مدينةَ باجَة، وأَشارَ المُعِزُّ على الرَّعِيَّة بالانتقالِ إلى المَهديَّة لِعَجزِه عن حمايتهم من العَربِ. وشَرعَت العَربُ في هَدمِ الحُصونِ والقُصورِ، وقَطَّعوا الثِّمارَ، وخَرَّبوا الأَنهارَ، وأَقامَ المُعِزُّ والناسُ يَنتَقِلون إلى المَهديَّة إلى سَنةِ تِسعٍ وأربعين، فعندها انتَقلَ المُعِزُّ إلى المَهديَّة في شعبان، فتَلقَّاهُ ابنُه تَميمٌ، ومَشَى بين يَديهِ، وكان أَبوهُ قد وَلَّاهُ المَهديَّة سَنةَ خَمسٍ وأربعين، وفي رمضان من سَنةِ تِسعٍ وأربعين نَهبَت العَربُ القَيروانَ, وهكذا تَتابَعت هَزائمُ المُعِزِّ وعَسكرِه على يَدِ العَربِ بِدَعمٍ مِن المُستَنصِر العُبيدي حاكم مصر."},{"id":1550,"title":"وَفاةُ أبي عَمرٍو الدَّاني .","date":["العام الهجري :444","الشهر القمري : شوال","العام الميلادي :1053"],"text":"الإمامُ، الحافظُ، المُجَوِّدُ، المُقرِئُ، الحاذِقُ، عَالِمُ الأندلُس، أبو عَمرٍو عُثمانُ بن سَعيدِ بن عُثمان الدَّاني، المعروف بابنِ الصَّيْرَفِيِّ، وبأبي عَمرٍو الدَّاني، مالِكي المَذهَب، وُلِدَ سنة 371هـ بدأ بِطَلَبِ العِلمِ في قُرطبة سَنةَ 386هـ, ثم رَحلَ إلى المَشرِق وسَمِعَ الحَديثَ في القَيروان ومصر، وهو أَحدُ الأَئِمَّة في عِلمِ القُرآن رِواياتِه، وقِراءاتِه، وتَفسيرِه، ومَعانِيه، وطُرُقِه، وإعرابِه، وإليه انتهى عِلمُ القِراءات وإتقانُ القُرآن، وجَمعَ في ذلك كُلِّهِ تَواليفَ حِسانًا مُفيدةً، وله مَعرِفَة بالحَديثِ وطُرُقِه، وأسماء رِجالِه ونَقَلَتِهِ، وكان حَسَنَ الخَطِّ، جَيِّدَ الضَّبطِ، مِن أهلِ الذَّكاءِ والحِفظِ، والتَّفنُّنِ في العِلمِ، دَيِّنًا فاضِلًا، وَرِعًا مُجابَ الدَّعوةِ. لم يكُن في عَصرِه ولا بَعدَ عَصرِه أحدٌ يُضاهيهِ في حِفظهِ وتَحقيقِه، وكان يقول: \"ما رأيتُ شَيئًا قط إلا كَتبتُه، ولا كَتبتُه إلا وحَفِظتُه، ولا حَفِظتُه فنَسيتُه\". وكان يُسألُ عن المَسأَلةِ مما يَتعلَّق بالآثارِ وكلامِ السَّلفِ، فيُورِدها بجميعِ ما فيها مُسنَدَةً من شُيوخِه إلى قائلِها. وله مُؤلَّفاتٌ تُعتَبر هي المرجِعُ في القِراءات مثل: ((التَّيسير في القِراءاتِ السَّبْعِ))، و((المقنع في رَسْمِ المصاحِف)) و((المُحكَم في نَقْطِ المصاحِف)) و((الاهتداء في الوقفِ والابتداء)) وغيرها، قال الذهبي: \" كان بين أبي عَمرٍو الدَّاني، وبين أبي محمد بن حَزمٍ وَحشَةٌ ومُنافرَةٌ شَديدةٌ، أَفضَت بهما إلى التَّهاجي، وهذا مَذمومٌ مِن الأَقرانِ، مَوفورُ الوُجودِ، نَسألُ اللهَ الصَّفحَ, وأبو عَمرٍو أَقْوَمُ قِيلًا، وأَتْبَعُ للسُّنَّةِ، ولكنَّ أبا مُحمدٍ أَوسعُ دَائِرةً في العُلومِ، بَلغَت تَواليفُ أبي عَمرٍو مائةً وعِشرين كِتابًا\". تُوفِّي في الأَندلُس عن 73 عامًا. ودُفِنَ ليومِه بعدَ العَصرِ بِمَقبرةٍ دانِيَةٍ، ومَشى سُلطانُ البَلدِ أمامَ نَعشِه، وشَيَّعَهُ خَلْقٌ عَظيمٌ."},{"id":1551,"title":"عَودةُ الفِتنَة بين السُّنَّةِ والشِّيعَة في الكَرخِ .","date":["العام الهجري :445","الشهر القمري : محرم","العام الميلادي :1053"],"text":"زادت الفِتنةُ بين شِيعَةٍ مِن أَهلِ الكَرخِ وغَيرهِم مِن أَهلِ السُّنَّةِ، وكان ابتِداؤُها أواخرَ سَنَةِ أربعٍ وأربعين في ذي القعدة، فلمَّا كان الآن عَظُمَ الشَّرُّ، واطَّرَحَت المُراقبَة للسُّلطان، واختَلطَ بالفَريقينِ طوائفُ مِن الأتراكِ، فلمَّا اشتَدَّ الأمرُ اجتمع القُوَّادُ واتَّفَقوا على الرُّكوبِ إلى المَحالِّ، وإقامةِ السِّياسةِ بأهلِ الشَّرِّ والفَسادِ، وأَخَذوا مِن الكَرخِ إِنسانًا عَلويًّا وقَتلوهُ، فَثارَ نِساؤُه، ونَشَرْنَ شُعورَهُنَّ واسْتَغَثْنَ، فتَبِعَهُنَّ العامَّةُ من أهلِ الكَرخِ، وجَرى بينهم وبين القُوَّاد ومن معهم من العامَّةِ قِتالٌ شَديدٌ، وطَرحَ الأتراكُ النَّارَ في أَسواقِ الكَرخ، فاحتَرقَ كَثيرٌ منها، وأَلحَقَتها بالأرضِ، وانتَقَل كَثيرٌ من الكَرخِ إلى غَيرِها من المَحالِّ، ونَدِمَ القُوَّادُ على ما فَعلوهُ، وأَنكرَ الخَليفةُ القائمُ بأَمرِ الله ذلك، وصَلُحَ الحالُ، وعاد النَّاسُ إلى الكَرخِ، بعد أن استَقرَّت القاعدةُ بالدِّيوان بِكَفِّ الأتراكِ أَيديَهم عنهم."},{"id":1552,"title":"استِيلاءُ المَلِكِ الرَّحيم البُويهي الشِّيعي على أرجان .","date":["العام الهجري :445","الشهر القمري : جمادى الأولى","العام الميلادي :1053"],"text":"استولى المَلِكُ الرَّحيم البويهي  الدَّيلمي الشِّيعي على مَدينةِ أرجان، وأَطاعهُ مَن كان بها مِن الجُندِ، وكان المُقَدَّمُ عليهم فولاذ بن خُسرو الدَّيلمي، وكان قد تَغلَّب على جِوارِها مِن البِلادِ إِنسانٌ مُتَغَلِّبٌ يُسمَّى خشنام، فأَنفذَ إليه فولاذ جَيشًا فأَوقَعوا به وأَجْلَوْهُ عن تلك النَّواحي، واستَضافوا إلى طَاعةِ المَلِكِ الرَّحيم، وخاف هزارسب بن بنكير من ذلك لأنَّه كان مُبايِنًا للمَلِكِ الرَّحيم، فأَرسلَ يَتَضرَّع ويَتَقرَّب، ويَسأَل التَّقَدُّمَ إلى فولاذ بإحسانِ مُجاورَتِه، فأُجِيبَ إلى ذلك."},{"id":1553,"title":"إِيقاعُ البساسيري بِقُطَّاعِ الطَّريقِ مِن الأَكرادِ والأَعرابِ .","date":["العام الهجري :445","الشهر القمري : شوال","العام الميلادي :1054"],"text":"وَصلَ الخَبرُ إلى بغداد بأنَّ جَمْعًا من الأَكرادِ والأَعرابِ قد أَفسَدوا في البلادِ، وقَطَعوا الطَّريقَ، ونَهَبوا القُرى، طَمعًا في السَّلْطَنَةِ بسَببِ الغُزِّ، فسار إليهم البساسيري -وكان مملوكاً تركياً من مماليك بهاء الدولة بن عضد الدولة- وتَبِعَهُم إلى البَوازيج -بلد قُربَ تكريت-، فأَوقعَ بِطَوائفَ كَثيرةٍ منهم، وقَتَّلَ فيهم، وغَنِمَ أَموالَهم، وانهَزمَ بعضُهم فعَبَروا الزَّابَ عند البَوازيج فلم يُدرِكهُم، وأَرادَ العُبورَ إليهم، وهُم بالجانبِ الآخر، وكان الماءُ زائدًا، فلم يَتمكَّن من عُبورهِ، فنَجَوْا."},{"id":1554,"title":"الأَميرُ أبو مَنصور البويهي  الشِّيعي يَستَولي على شيراز .","date":["العام الهجري :445","الشهر القمري : شوال","العام الميلادي :1054"],"text":"عاد الأميرُ أبو منصور فولاستون ابن المَلِكِ أبي كاليجار البويهي  الدَّيلمي الشِّيعي إلى شيراز مُستَولِيًا عليها، وفارَقَها أخوهُ الأميرُ أبو سعدٍ، وكان سببُ ذلك أنَّ الأميرَ أبا سعدٍ كان قد تَقدَّم معه في دَولتِه إنسانٌ يُعرفُ بعَميدِ الدِّين أبي نصرِ بن الظَّهير، فتَحَكَّم معه، واطَّرحَ الأجنادَ واستَخَفَّ بهم، وأَوحشَ أبا نصرِ بن خسرو، صاحب قَلعةِ إصطخر، الذي كان قد استَدعَى الأميرَ أبا سعدٍ ومَلَّكَهُ، فلمَّا فعل ذلك اجتمعوا على مُخالَفَتِه وتَأَلَّبوا عليه، وأَحضرَ أبو نَصرِ بن خسرو الأميرَ أبا منصور بن أبي كاليجار إليه! وسَعى في اجتماعِ الكَلمةِ عليه، فأجابه كثيرٌ من الأجنادِ لِكَراهتهِم لعَميدِ الدِّين، فقَبَضوا عليه، ونادوا بِشِعارِ الأميرِ أبي منصور، وأَظهروا طاعتَه، وأَخرَجوا الأميرَ أبا سعدٍ عنهم، فعاد إلى الأهوازِ في نَفَرٍ يَسيرٍ، ودخلَ الأميرُ أبو منصور إلى شيراز مالِكًا لها، مُستَولِيًا عليها، وخَطَب فيها لطُغرلبك، وللمَلِكِ الرَّحيم، ولِنَفسِه بعدهما."},{"id":1555,"title":"غَزوُ السُّلطانِ طُغرلبك أذربيجان ثم الرُّومِ .","date":["العام الهجري :446","العام الميلادي :1054"],"text":"سار طُغرلبك إلى أذربيجان، فقَصدَ تبريزَ، وصاحبُها الأميرُ أبو منصور وهسوذان بن محمد الرَّوادي، فأَطاعَه وخَطَب له وحَمَلَ إليه ما أَرضاهُ به، وأَعطاهُ وَلَدَهُ رَهينةً، فسار طُغرلبك عنه إلى الأميرِ أبي الأسوارِ، صاحبِ جنزة - بَلدَة من بلادِ أذربيجان- فأَطاعَهُ أيضًا وخَطَب له، وكذلك سائرُ تلك النَّواحي أَرسَلوا إليه يَبذُلون الطَّاعةَ والخُطبةَ، وانقادَت العَساكرُ إليه، فأَبقَى بِلادَهم عليهم، وأَخذَ رَهائِنَهم وسار إلى أَرمينية، وقَصدَ ملازكرد، وهي للرُّومِ، فحَصَرها وضَيَّقَ على أَهلِها، ونَهبَ ما جاوَرَها من البلادِ وأَخرَبَها، وهي مدينةٌ حَصينَة، فأَرسلَ إليه نَصرُ الدَّولةِ بن مَروان، صاحبُ دِيارِ بَكْرٍ، الهدايا الكثيرة والعَساكِر، وقد كان خَطَبَ له قبلَ هذا الوَقتِ وأَطاعَهُ، وأَثَّرَ السُّلطانُ طُغرلبك في غَزْوِ الرُّومِ آثارًا عظيمةً، ونال منهم مِن النَّهْبِ والقَتْلِ والأَسْرِ شَيئًا كثيرًا، وبلغَ في غَزوتِه هذه إلى أرزن الرُّومِ، وعاد إلى أذربيجان، لمَّا هَجمَ الشِّتاءُ، من غير أن يَملِك ملازكرد، وأَظهَر أنَّه يُقيم إلى أن يَنقَضي الشِّتاءُ، ويَعودُ يُتِمُّ غَزاتِه، ثم تَوجَّه إلى الرَّيِّ فأقامَ بها إلى أن دخلت سَنةُ سَبعٍ وأربعين وعاد نحوَ العراق."},{"id":1556,"title":"مُعاهدةٌ بين العُبيديِّينَ الفاطِميِّينَ والرُّومِ .","date":["العام الهجري :446","العام الميلادي :1054"],"text":"أُصيبَت مِصرُ بِقَحْطٍ شَديدٍ وغَلاءٍ شَديدٍ كاد يُهلِكُهم، فعَقدَ المُستنصِرُ الفاطِميُّ مع الإمبراطورِ البيزنطي قُسطنطين التاسِع مُعاهدةً مُوجِبُها أن يَمُدَّ الرُّومُ مِصرَ بالغِلالِ والأَقواتِ لِتَجاوُزِ المَجاعةِ التي حَلَّت بهم، لكنَّ إمبراطورَ الرُّومِ يَموتُ قبلَ الوَفاءِ بالمُعاهدةِ، ويَتولَّى أَمرَ الرُّومِ الإمبراطورة تيودورا فاشتَرطَت أن يَتَعهَّدَ الفاطِميونَ الدِّفاعَ عن الرُّومِ في حالِ التَّعَدِّي عليهم لِتُنَفِّذَ هذه المُعاهدة السَّابقة؛ لكنَّ المُستنصِرَ لم يَرضَ بهذا الشَّرْطِ، عِلْمًا أنَّ الرُّومَ كانوا قد أَرسَلوا هَدايا قبلَ ذلك منها كَثيرٌ مِن القَمحِ والغَلَّاتِ التي ساعدت في هذه المَجاعةِ، كما حَصَلَ قِتالٌ بين الرُّومِ وبين بَعضِ الجُيوشِ المُتاخِمَةِ لهم."},{"id":1557,"title":"فِتنةُ الجُندِ الأَتراكِ ببغداد .","date":["العام الهجري :446","الشهر القمري : محرم","العام الميلادي :1054"],"text":"كانت فِتنةُ الجُندِ الأَتراكِ ببغداد، وكان سَببُها أنهم تَخَلَّفَ لهم على الوزيرِ الذي للمَلِكِ الرَّحيم مَبلَغٌ كَثيرٌ مِن رُسومِهم، فطالبوهُ، وأَلَحُّوا عليه، فاختَفَى في دارِ الخِلافةِ، فحَضَر الأتراكُ بالدِّيوانِ وطالبوهُ، وشَكَوْا ما يَلقَوْنَه منه من المَطْلِ بمالِهم، فلم يُجابوا إلى إظهارهِ، فعَدَلوا عن الشَّكوَى منه إلى الشَّكوَى من الدِّيوان، وقالوا: إنَّ أربابَ المُعاملات قد سَكَنوا بالحَريمِ، وأَخَذوا الأموالَ، وإذا طَلَبناهُم بها يَمتَنِعون بالمَقامِ بالحَريمِ، وانتَصَب الوَزيرُ والخَليفةُ لِمَنعِنا عنهم، وقد هَلكنا، فتَردَّد الخِطابُ منهم، والجوابُ عنه، فقاموا نافِرينَ، فلمَّا كان الغَدُ ظَهَرَ الخَبَرُ أنَّهم على عَزْمِ حَصْرِ دارِ الخِلافةِ، فانزَعَج النَّاسُ لذلك، وأَخْفَوْا أَموالَهم، وحَضرَ البساسيري دارَ الخِلافةِ، وتَوصَّل إلى مَعرفةِ خَبرِ الوَزيرِ، فلم يَظهَر له على خَبرٍ، فطُلِبَ من دارهِ ودُورِ مَن يُتَّهَمُ به، وكُبِسَت الدُّور، فلم يَظهَروا له على خَبرٍ، ورَكِبَ جَماعةٌ مِن الأَتراكِ إلى دارِ الرُّومِ فنَهبوها، وأَحرَقوا البِيَعَ والقَلَّايات، ونَهَبوا فيها دارَ أبي الحسنِ بن عُبيدٍ، وَزير البساسيري، ونَهبَ الأَتراكُ كُلَّ مَن وَرَدَ إلى بغداد، فغَلَت الأَسعارُ، وعُدِمَت الأَقواتُ، وأَرسلَ إليهم الخَليفةُ يَنهاهُم، فلم يَنتَهوا، فأَظهَر أنَّه يُريدُ الانتِقالِ عن بغداد، فلم يُزجَرُوا، هذا جَميعهُ والبساسيري غيرُ راضٍ بِفِعلِهم، وهو مُقيمٌ بدارِ الخليفةِ، وتَردَّدَ الأمرُ إلى أن ظَهرَ الوَزيرُ، وقام لهم الباقي بالباقي مِن مالِهم مِن مالِه، وأَثمانِ دَوابِّهِ، وغَيرِها، ولم يَزالوا في خَبْطٍ وعَسَفٍ، فعاد طَمَعُ الأَكرادِ والأَعرابِ أَشَدَّ منه أَوَّلًا، وعاوَدوا الغارةَ والنَّهْبَ والقَتْلَ، فخُرِّبَت البلادُ وتَفَرَّق أَهلُها، فازداد خَوفُ النَّاسِ من العامَّةِ والأَتراكِ، وعَظُمَ انحلالُ أَمرُ السَّلطَنةِ بالكُلِّيَّةِ، وهذا من ضَررِ الخِلاف."},{"id":1558,"title":"ابْتِداءُ الوَحشَةِ بين البساسيري التُّركي وبين الخَليفَةِ العبَّاسي .","date":["العام الهجري :446","الشهر القمري : رمضان","العام الميلادي :1054"],"text":"ابتَدأَت الوَحشةُ بين الخَليفةِ وأَرسِلان التُّركي المعروف بالبساسيري الذي قد عَظُمَ أَمرُه واستَفحَل، واستَولَى على البلادِ وطار اسمُه، وخافَتهُ أُمراءُ العَربِ والعَجَمِ، ودُعِيَ له على كَثيرٍ من المَنابِر العِراقيَّة والأهوازِ ونَواحِيها، ولم يكُن للخَليفَةِ قَطْعٌ ولا وَصْلٌ دُونَه، ثم صَحَّ عند الخَليفةِ سُوءُ عَقيدَتِه، وشَهِدَ عنده جَماعةٌ مِن الأَتراكِ أنَّه عازمٌ على نَهْبِ دارِ الخِلافَةِ، وأنَّه يُريدُ القَبضَ على الخَليفةِ، فعند ذلك كاتَبَ الخَليفةُ محمدَ بن ميكائيل بن سلجوق المُلَقَّبَ بطُغرلبك يَسْتَنْهِضَهُ على المَسيرِ إلى العراقِ، فانْفَضَّ أَكثرُ مَن كان مع البساسيري وعادوا إلى بغداد سريعًا، ثم أَجمعَ رَأيُهم على قَصْدِ دارِ البساسيري وهي في الجانب الغربي فأَحرَقوها، وهَدَموا أَبنِيَتَها."},{"id":1559,"title":"ابتِداءُ الوَحشَةِ بين الرُّومِ والعُبيدِيِّين (الفاطِميِّين) .","date":["العام الهجري :447","العام الميلادي :1055"],"text":"كان القاضي أبو عبدِ الله القضاعي قد تَوَجَّه من عند المُستَنصِر حاكم مصر العُبيدي برِسالةٍ إلى مُتَمَلِّكِ الرُّومِ، فقَدِمَ وهو بالقُسطنطينيَّة رَسولُ السُّلطانِ طُغرلبك بن سلجوق يَلتَمِس من المَلِكَة تيودورا أن تُمَكِّنَ رَسولَه مِن الصَّلاةِ في جامعِ قُسطنطينيَّة، فأَذِنَت له في ذلك؛ فدَخلَ إليه وصَلَّى به، وخَطَبَ للخَليفةِ القائمِ بأَمرِ الله العبَّاسي. فبَعَثَ القَضاعيُّ بذلك إلى المُستنصِر، فأحاط المُستنصِر بما في بِيعَةِ قُمامَة وأَخذَهُ، وأَخرجَ البِطْرَكَ منها إلى دارِ مُفرَدَةٍ؛ وأَغلقَ أَبوابَ كنائِس مصر والشام، وطالَب الرُّهبانَ بالجِزيَةِ لأَربعِ سِنين، وزاد على النَّصارى في الجِزيَة. وكان هذا ابتداءُ فَسادِ ما بين الرُّومِ والمِصريِّين."},{"id":1560,"title":"استِيلاءُ المَلِكِ الرَّحيم البويهي  الشِّيعي على شيراز .","date":["العام الهجري :447","الشهر القمري : محرم","العام الميلادي :1055"],"text":"سار قائدٌ كبيرٌ من الدَّيلمِ، يُسمَّى فولاذ، وهو صاحبُ قَلعةِ إصطخر، إلى شيراز، فدَخلَها وأَخرجَ عنها الأَميرَ أبا منصور فولاستون، ابنَ المَلِكِ أبي كاليجار، فقَصدَ فيروزآباذ وأَقامَ بها، وقَطعَ فولاذ خُطبةَ السُّلطانِ طُغرلبك في شيراز، وخَطبَ للمَلِكِ الرَّحيمِ، ولأَخيهِ أبي سعدٍ، وكاتَبَهُما يُظهِر لهُما الطَّاعةَ، فعَلِمَا أنَّه يَخدَعهُما بذلك، فسار إليه أبو سعدٍ، وكان بأرجان، ومعه عَساكرُ كثيرةٌ، واجتمع هو وأَخوهُ الأَميرُ أبو منصور على قَصْدِ شيراز ومُحاصرتِها بَعدَ أن اتَّفَقَا على طَاعةِ أَخيهِما المَلِكِ الرَّحيم، فتَوَجَّهَا نَحوَها فيمَن معهما مِن العَساكِر، وحَصَرَا فولاذ فيها، وطال الحِصارُ إلى أن عُدِمَ القُوتُ فيها، وبَلَغَ سِعرُ سَبعةِ أَرطالٍ حِنطَة بدِينار ومات أَهلُها جُوعًا، وكان مَن بَقِيَ فيها نحوَ أَلفِ إنسانٍ، وتَعَذَّرَ المُقامُ في البَلدِ على فولاذ، فخَرَجَ هاربًا مع مَن في صُحبَتِه من الديلم إلى نَواحي البَيضاءِ وقَلعةِ إصطخر، ودَخَل الأَميرُ أبو سعدٍ، والأميرُ أبو منصور شيراز، وعَساكِرُهما، ومَلَكوها، وأَقاموا بها."},{"id":1561,"title":"السلاجقة يدخلون العراقِ وانتهاءُ حُكمِ البُويهيِّين .","date":["العام الهجري :447","الشهر القمري : رمضان","العام الميلادي :1055"],"text":"كان سببُ ذلك أن أبا المُظفَّر أبا الحارث أرسلان التُّركي المعروف بالبساسيري كان قد عَظُمَ شَأنُه بالعراقِ، واستَفحَل أَمرُه، وبَعُدَ صِيتُه، وعَظُمَت هَيبتُه في النُّفوسِ، وخُطِبَ له على المنابرِ، وصار هو الكُلَّ، ولم يَبْقَ للمَلِكِ الرَّحيمِ ابن بُويه معه إلا مُجرَّد الاسمِ. ثم إنَّه بَلَغَ أَميرَ المؤمنين القائم أنَّ البساسيري قد عَزَمَ على نَهْبِ دارِ الخِلافَة والقَبضِ على الخَليفةِ، فكاتَبَ الخَليفةُ القائمُ السُّلطانَ طُغرلبك بن ميكائيل بن سلجوق يَستَنجِد به، ويَعِدُهُ بالسَّلطَنَةِ، ويَحُضُّهُ على القُدومِ، وكان طُغرلبك بالرَّيِّ، وكان قد استولى على المَمالِك الخُراسانيَّة وغَيرِها، وكان البساسيري يومئذٍ بواسِط ومعه أَصحابُه، ففارَقَهُ طائِفةٌ منهم ورَجَعوا إلى بغداد، فوَثَبوا على دارِ البساسيري فنَهَبوها وأَحرَقوها، وذلك برَأيِ رَئيسِ الرُّؤساءِ وسَعيِه. ثم أَبخَسَهُ عند القائمِ بأنَّه يُكاتِب المِصريِّين، وكاتَبَ المَلِكَ الرَّحيم يَأمرُهُ بإبعادِ البساسيري فأَبعدَهُ، وكانت هذه الحَركةُ مِن أَعظمِ الأَسبابِ في استِيلاءِ طُغرلبك على العراقِ. فقَدِمَ السُّلطانُ طُغرلبك في شَهرِ رمضان بجُيوشِه، فذَهبَ البساسيري من العراقِ وقَصدَ الشَّامَ، ووَصلَ إلى الرَّحبَةِ، وكاتَبَ المُستَنصِرَ العُبيديَّ صاحبَ مصر، واستولى على الرَّحبةِ وخَطَبَ للمُستَنصِر بها فأَمَدَّهُ المُستَنصِر بالأَموالِ. وأما بغداد فخطب بها للسُّلطانِ طُغرلبك بعدَ القائمِ، ثم ذكر بعده المَلِكَ الرَّحيم وذلك بِشَفاعةِ القائمِ فيه إلى السُّلطان. ثم إنَّ السُّلطانَ قَبَضَ على المَلِكِ الرَّحيمِ بعدَ أيَّامٍ، وقُطِعَت خُطبتُه في آخر رمضان، وانقَرضَت دَولةُ بني بُويه، وكانت مُدَّتُها 127 سَنَة، وقامت دَولةُ بني سلجوق، ودخل طُغرلبك بغداد في تَجَمُّلٍ عَظيمٍ، وكان يومًا مَشهودًا دخل معه ثمانية عشر فِيلًا، ونزَلَ بِدارِ المَملكةِ."},{"id":1562,"title":"الخَليفةُ العبَّاسي يَأمُر بِتلاوَةِ الخُطبةِ في بغداد للسُّلطانِ السلجوقي .","date":["العام الهجري :447","الشهر القمري : رمضان","العام الميلادي :1055"],"text":"أَمَرَ الخَليفةُ العبَّاسيُّ بِتلاوَةِ خُطبةِ الجُمعةِ في بغداد باسمِ السُّلطانِ السَّلجوقي طُغرل بك، وكان ذلك اعتِرافًا صَريحًا من العبَّاسيِّين بنُفوذِ السَّلاجِقَة في الخِلافَةِ العبَّاسيَّة."},{"id":1563,"title":"قِيامُ دَولَةِ المُرابِطينَ في المَغرِب وشَمالِ أفريقيا .","date":["العام الهجري :448","العام الميلادي :1056"],"text":"كان ابتِداءُ أَمرِ المُلَثَّمِينَ، وهُم عِدَّةُ قَبائلَ يُنسَبون إلى حِمْيَر، أَشهرُها: لَمْتُونَة، ومنها أَميرُ المُسلمين يُوسف بن تاشفين، وجدالة ولمطة، وكان أوَّلُ مَسيرِهم مِن اليَمنِ، أيَّامَ أبي بكرٍ الصِّدِّيق رضي الله عنه، فسَيَّرَهُم إلى الشَّامِ وانتَقَلوا إلى مصر، ودَخَلوا المغربَ مع موسى بن نُصير، وتَوجَّهوا مع طارقِ إلى طَنجة، فأَحَبُّوا الانفِرادَ، فدَخلوا الصَّحراءَ واستَوطَنوها، فلمَّا كان هذه السَّنَة تَوجَّه رجلٌ منهم، اسمُه الجوهر -من قَبيلةِ جدالة- إلى إفريقية طالِبًا للحَجِّ، وكان مُحِبًّا للدِّينِ وأَهلِه، فلمَّا انصَرَف مِن الحَجِّ قال للفَقيهِ: ابعَثْ معي مَن يُعَلِّمُهم شَرائعَ الإسلام. يعني قَومَه في الصَّحراء، فأَرسَل معه رَجُلًا اسمُه: عبدُ الله بن ياسين الكزولي، وكان فَقِيهًا صالحًا، فلم يَقبَلوهُ فرَحَلَا عنهم، فانتهى الجوهرُ وابنُ ياسين إلى جدالة -قَبيلةِ الجوهر- فدَعاهُم عبدُ الله بن ياسين والقَبائلَ الذين يُجاوِرُونَهم إلى حُكمِ الشَّريعةِ، فمِنهم مَن أَطاعَ، ومِنهم مَن أَعرضَ وعَصى، ثم إنَّ المُخالِفين لهم تَحيَّزوا وتَجمَّعوا، فقال ابنُ ياسين للذين أطاعوا: قد وجَبَ عليكم أن تُقاتِلوا هؤلاء الذين خالَفوا الحَقَّ، وأَنكَروا شَرائعَ الإسلامِ، واسْتَعَدُّوا لِقِتالِكُم، فأَقِيموا لكم رايَةً، وقَدِّموا عليكم أَميرًا. فأَتَيَا أبا بكرِ بن عُمرَ، فعَقَدوا له البَيْعَةَ، وسَمَّاهُ ابنُ ياسين أَميرَ المُسلِمين، وعادوا إلى جدالة، وجَمَعوا إليهم مَن حَسُنَ إِسلامُه، وحَرَّضَهم عبدُ الله بن ياسين على الجِهادِ في سَبيلِ الله، وسَمَّاهُم مُرابِطين، وتَجَمَّع عليهم مَن خالَفَهُم، فلم يُقاتِلهُم المُرابِطون؛ بل استعان ابنُ ياسين وأبو بكرِ بن عُمرَ على أولئك الأَشرارِ بالمُصلِحينَ مِن قَبائلِهم، فاستَمالُوهم وقَرَّبوهُم حتى حَصَّلُوا منهم نحوَ ألفي رَجُلٍ مِن أَهلِ البَغْيِ والفَسادِ، فتَركُوهم في مَكانٍ، وخَنْدَقوا عليهم، وحَفَظوهُم، ثم أَخرجوهُم قَومًا بعدَ قَومٍ، فقَتَلوهُم، فحينئذٍ دانت لهم أَكثرُ قَبائلِ الصَّحراءِ، وهابوهُم، فقَوِيَت شَوكةُ المُرابِطين."},{"id":1564,"title":"مُوالاةُ السَّلاجِقَة لأَهلِ السُّنَّةِ وصَدُّهُم للرَّافِضَة .","date":["العام الهجري :448","العام الميلادي :1056"],"text":"أُلْزِمَ الرَّوافِضُ بِتَركِ الأذانِ بحَيّ على خَيرِ العَملِ، وأُمِروا أن يُنادِي مُؤذِّنُهم في أذانِ الصُّبحِ، وبعدَ حَيَّ على الفَلاحِ: الصَّلاةُ خَيرٌ مِن النَّوْم. مَرَّتينِ، وأُزِيلَ ما كان على أَبوابِ المساجدِ ومَساجِدِهم مِن كتابة: محمدٌ وعَلِيٌّ خَيرُ البَشرِ. ودَخلَ المُنشِدونَ من بابِ البَصرَةِ إلى بابِ الكَرخِ، يُنشِدونَ بالقَصائدِ التي فيها مَدحُ الصَّحابَةِ، وذلك أنَّ نَجْمَ الرَّافِضَة اضْمَحَلَّ، لأنَّ بني بُويه كانوا حُكَّامًا، وكانوا يُقَوُّونَهُم ويَنصُرونَهُم، فزالوا وبادوا، وذَهبَت دَولتُهم، وجاء بَعدَهم قَومٌ آخرون مِن الأَتراكِ السَّلجوقِيَّة الذين يُحِبُّونَ أَهلَ السُّنَّةِ ويُوالونَهُم ويَرفَعون قَدرَهُم، واللهُ المَحمودُ أبدًا على طُولِ المَدَى. وأَمَرَ رَئيسُ الرُّؤساءِ الوالي بِقَتلِ أبي عبدِ الله بن الجَلَّابِ شَيخِ الرَّوافِض، لِمَا كان تَظاهَر به من الرَّفْضِ والغُلُوِّ فيه، فقُتِلَ على بابِ دُكَّانِه، وهَرَب أبو جَعفرٍ الطُّوسيُّ ونُهِبَت دارُه."},{"id":1565,"title":"احتِلالُ البساسيري للمَوصِل .","date":["العام الهجري :448","العام الميلادي :1056"],"text":"جاء البساسيري إلى المَوصِل ومعه نورُ الدَّولةِ دُبيس في جَيشٍ كَثيفٍ، فاقتَتَل مع صاحبِها قُريشِ بن بَدران ونَصرَهُ قُتلمشُ ابنُ عَمِّ طُغرلبك، وهو جَدُّ مُلوكِ الرُّومِ، فهَزمَهما البساسيري، وأَخذَ البَلدَ قَهْرًا، فخُطِبَ بها للعُبيديين  بمصر، وكذلك خُطِبَ للمِصريِّين فيها بالكوفَةِ وواسِط وغَيرِها من البِلادِ، وعَزَمَ طُغرلبك على المَسيرِ إلى المَوصِل لِمُناجَزَةِ البساسيري فنَهاهُ الخَليفةُ عن ذلك لِضِيقِ الحالِ وغَلاءِ الأَسعارِ، فلم يَقبَل فخَرجَ بِجَيشهِ قاصِدًا المَوصِل بجَحافِلَ عَظيمةٍ، ومعهُ الفِيَلَةُ والمَنْجَنِيقَاتُ، وكان جَيشُه لِكَثرتِهم يَنهَبون القُرى، وربَّما سَطَوْا على بَعضِ الحَريمِ، فكتَبَ الخَليفةُ إلى السُّلطانِ يَنهاهُ عن ذلك، فبَعثَ إليه يَعتَذِر لِكَثرةِ مَن معهُ. ولمَّا اقتَربَ طُغرلبك مِن المَوصِل فتَحَ دُونَها بِلادًا، ثم فَتحَها وسَلَّمَها إلى أَخيهِ داودَ، ثم سار منها إلى بِلادِ بَكْرٍ ففَتحَ أَماكنَ كَثيرةً هناك."},{"id":1566,"title":"وَباءٌ وقَحْطٌ عامٌّ ينتشر في البلدان .","date":["العام الهجري :448","العام الميلادي :1056"],"text":"عَمَّ الوَباءُ والقَحْطُ بغدادَ والشامَ ومِصرَ ومَكَّةَ والحِجازَ ودِيارَ بَكْرٍ والمَوْصِلَ وبِلادَ الرُّومِ وخُراسان والجِبالَ؛ وكان النَّاسُ يأكلون المَيْتَةَ، وانقَطعَ ماءُ النِّيلِ بمصر، وكان يموتُ بها في كلِّ يَومٍ عَشرةُ آلافِ إنسانٍ، ووقع بمصر أنَّ ثَلاثةَ لُصوصٍ نَقَبُوا نَقْبًا فوُجِدُوا عند الصَّباحِ مَوْتَى: أَحدُهم على بابِ النَّقْبِ، والثَّاني على رَأسِ الدَّرَجَةِ، والثَّالثُ على الكارَّةِ التي سَرقَها."},{"id":1567,"title":"قِيامُ وَقعةٍ بين البساسيري وقُريشٍ بن بدران .","date":["العام الهجري :448","الشهر القمري : شوال","العام الميلادي :1057"],"text":"نَشبَت مَعركةٌ بين البساسيري ومعه نورُ الدَّولةِ دُبيس بن مَزْيَد، وبين قُريشِ بن بَدران، صاحبِ المَوصِل، ومعه قُتلمش، وهو ابنُ عَمِّ السُّلطانِ طُغرلبك، وهو جَدُّ هؤلاء المُلوكِ أَولادِ قِلج أرسلان، ومعه أيضًا سَهمُ الدَّولةِ أبو الفَتحِ بن عَمرٍو، وكانت الحَربُ عند سنجار، فاقتَتَلوا، فاشتَدَّ القِتالُ بينهم، فانهَزَم قُريشٌ وقُتلمش، وقُتِلَ مِن أَصحابِهما الكَثيرُ, ولَقِيَ قُتلمش مِن أَهلِ سنجار العَنَتَ، وبالغوا في أَذاهُ وأَذَى أَصحابِه، وجُرِحَ ابنُ بَدران، وأَتَى إلى نُورِ الدَّولةِ جَريحًا، فأَعطاهُ خِلْعَةً كانت قد نُفِّذَت مِن مصر، فلَبِسَها وصار في جُملتِهم، وساروا إلى المَوصِل، وخَطَبوا للحاكِم العُبيديِّ بمصر، وهو المُستَنصِر، وكانوا قد كاتَبوهُ بِطاعَتِهم له، فأَرسلَ إليهم الخِلَعَ مِن مصر للبساسيري، ولِنُورِ الدَّولةِ دُبيس بن مَزْيَد، ولِجابرِ بن ناشبٍ، ولِمُقبِل بن بَدران أخي قُريشٍ، ولأبي الفَتحِ بن ورام، ونُصير بن عُمَرَ، وأبي الحسنِ بن عبدِ الرَّحيم، ومحمدِ بن حمَّاد، وانضاف إليهم قُريشُ بن بَدران."},{"id":1568,"title":"طاعونٌ عَظيمٌ في بلاد بُخارَى .","date":["العام الهجري :449","العام الميلادي :1057"],"text":"وقعَ غَلاءٌ وفَناءٌ عَظيمان ببغداد وغَيرِها مِن البلادِ، بحيث خَلَتْ أَكثرُ الدُّورِ وَسُدَّتْ على أَهلِها أَبوابُها بما فيها، وأَهلُها مَوتى فيها، ثم صار المارُ في الطَّريقِ لا يَلقى الواحدَ بعدَ الواحدِ، وأكلَ النَّاسُ الجِيَفَ والنَّتَنَ مِن قِلَّةِ الطَّعامِ، ووُجِدَ مع امرأةٍ فَخِذُ كَلْبٍ قد اخْضَرَّ, وشَوَى رَجلٌ صَبِيَّةً في الأَتُونِ وأَكَلَها، وسَقطَ طائرٌ مَيِّتٌ مِن حائطٍ فاحْتَوَشَتْهُ خمسُ أَنفُسٍ فاقتَسموهُ وأَكلوهُ. قال ابنُ الجوزي يَصِفُ خبرَ هذا الوباءِ: \" في جُمادى الآخِرة: وَردَ كِتابٌ مِن تُجَّارِ ما وَراءَ النَّهرِ قد وقع في هذه الدِّيارِ وَباءٌ عَظيمٌ مُسرِفٌ زَائِدٌ عن الحَدِّ، حتى أنَّه خَرجَ من هذا الإقليمِ في يَومٍ واحدٍ ثمانية عشر ألف جِنازةٍ، وأحصى مَن مات إلى أن كُتِبَ هذا الكِتاب فكانوا ألف ألف وستمائة ألف وخمسين ألفًا، والنَّاسُ يَمُرُّون في هذه البلادِ فلا يَرونَ إلَّا أسواقًا فارغةً، وطُرقاتٍ خاليةً، وأبوابًا مُغلقةً، حتى إنَّ البَقرَ نَفَقَت. وجاء الخَبرُ من أذربيجان وتلك البلادِ بالوباءِ العظيمِ، وأنَّه لم يَسْلَم من تلك البلادِ إلا العَددُ اليَسيرُ جدًّا. وَقعَ وباءٌ بالأهواز وبواط وأَعمالِها وغَيرِها، حتى طَبَقَ البلادَ، وكان أكثرَ سَببِ ذلك الجوعُ، كان الفقراءُ يَشوون الكِلابَ، ويَنبُشون القُبورَ، ويَشوون المَوتى ويَأكلُونهم، وليس للناسِ شُغلٌ في اللَّيلِ والنَّهارِ إلا غَسلُ الأمواتِ وتَجهيزُهُم ودَفنُهُم، فكان يُحفَر الحُفَير فيُدفَن فيه العشرون والثلاثون، وكان الإنسانُ بينما هو جالس إذ انشَقَّ قَلبُه عن دَمِ المُهْجَةِ، فيَخرُج منه إلى الفَمِ قَطرةٌ فيموتُ الإنسانُ مِن وَقتِه، وتاب النَّاسُ، وتَصدَّقوا بأَكثرِ أَموالِهم فلم يَجِدوا أحدًا يَقبَل منهم، وكان الفَقيرُ تُعرَض عليه الدَّنانيرُ الكَثيرة والدَّراهِم والثِّياب فيقول: أنا أُريدُ كَسرةً، أُريدُ ما يَسُدُّ جُوعي. فلا يجد ذلك، وأَراقَ النَّاسُ الخُمورَ وكَسَروا آلات اللَّهوِ، ولَزِموا المساجِدَ للعِبادةِ وقِراءةِ القُرآن, وفي يومِ الأربعاءِ لِسَبعٍ بَقِينَ مِن جُمادى الآخرة احتَرقَت قَطِيعةُ عيسى، وسُوقُ الطَّعامِ، والكَنِيسُ، وأَصحابُ السَّقْطِ، وبابُ الشَّعيرِ، وسُوقُ العَطَّارين، وسُوقُ العَروسِ، والأَنماطِيِّين، والخَشَّابين، والجَزَّارين، والتَّمَّارين، والقَطيعَةُ، وسُوقُ مُخَوَّل، ونَهرُ الزُّجاجِ، وسُوَيْقَةُ غالبٍ، والصَّفَّارين، والصَّبَّاغين، وغَيرُ ذلك مِن المواضع، وهذه مُصيبةٌ أُخرى إلى ما بالنَّاسِ مِن الجُوعِ والغَلاءِ والفَناءِ، فضَعُفَ النَّاسُ حتى طَغَت النَّارُ فعَمِلَت أَعمَالَها، فإنَّا لله وإنَّا إليه راجعون\"."},{"id":1569,"title":"وَفاةُ أبي العَلاءِ المَعَرِّي الشاعر .","date":["العام الهجري :449","الشهر القمري : ربيع الأول","العام الميلادي :1057"],"text":"هو شَيخُ الآدابِ، أبو العلاء أَحمدُ بن عبدِ الله بن سُليمانَ المَعَرِّي التَّنوخي الشاعر، اللُّغويُّ، صاحبُ الدَّواوين والمُصَنَّفات في الشِّعرِ واللُّغةِ، المشهور بالزَّندقَةِ، وُلِدَ سنة 363هـ, وأصابهُ جُدَري وله أربعُ سِنين أو سَبع، فذَهبَ بَصرهُ، وقال الشِّعْرَ وله إحدى أو ثنتا عشرة سَنة، ودخلَ بغداد سنةَ تِسعٍ وتسعين وثلاثمائة، فأقام بها سنةً وسبعةَ أَشهُر، ثم خَرجَ منها طَريدًا مُنهزِمًا، لمَّا عَزَم الفُقهاءُ على أَخذِه ببَعضِ أَشعارهِ الدَّالةِ على فِسْقِه، هَرَب ورَجَع إلى بَلدِه، ولَزِمَ مَنزِلَه فكان لا يَخرُج منه، وسَمَّى نَفسَه: رَهينَ المَحْبَسَينِ لذلك ولِذهابِ بَصرِه, وقد كان المَعَرِّي غايةً في الذَّكاءِ المُفرِط، ومَكَثَ المَعَرِّي خمسًا وأربعين سنةً من عُمُرِه لا يأكلُ اللَّحمَ ولا اللَّبَنَ ولا البَيْضَ، ولا شيئًا مِن حَيوانٍ، على طَريقَةِ البَراهِمَة الفَلاسِفَة، ويُقال: \"إنَّه اجتَمَع بِراهبٍ في بَعضِ الصَّوامِع في مَجيئِه من بَعضِ السَّواحِل آواهُ اللَّيلَ عنده، فشَكَّكَهُ في دِينِ الإسلام\" فكان لا يَتَقَوَّتُ إلَّا بالنَّباتِ وغَيرِه، وأَكثرُ ما كان يأكلُ العَدسَ، ويَتَحَلَّى بالدِّبْسِ وبالتِّينِ، وكان لا يأكل بِحَضرَةِ أَحدٍ، ويقول: أَكْلُ الأعمى عَورةٌ وسَترُه واجب. قال ابنُ كَثيرٍ: \"كان  ذَكِيًّا ولم يكن زَكِيًّا، وله مُصنفاتٌ كَثيرةٌ أَكثرُها في الشِّعْرِ، وفي بَعضِ أَشعارِه ما يَدلُّ على زَندَقتِه، وانحِلالِه مِن الدِّين، ومن الناسِ مَن يَعتَذِر عنه ويقول: إنَّه إنمَّا كان يقول ذلك مُجونًا ولَعِبًا، ويقول بلِسانِه ما ليس في قَلبِه، وقد كان باطنُه مُسلِمًا\"، قال أبو الوفاء ابن عَقيلٍ شيخُ الحنابلة: \"مِن العجائبِ أنَّ المَعَرِّي أَظهرَ ما أَظهرَ مِن الكُفرِ الباردِ، وسَقَطَ مِن عُيونِ الكُلِّ، ثم اُعتُذِرَ بأن لِقَولهِ باطِنًا، وأنَّه مُسلمٌ في الباطنِ، فلا عَقلَ له ولا دِينَ، لأنَّه تَظاهَر بالكُفرِ وزَعَم أنَّه مُسلمٌ في الباطنِ، وهذا عَكسُ قضايا المُنافِقين والزَّنادِقة، حيث تَظاهَروا بالإسلامِ وأَبطَنوا الكُفرَ، فهل كان في بلادِ الكُفَّارِ حتى يحتاج إلى أن يُبطِنَ الإسلام، فلا أَسخَف عَقلًا ممَن سَلكَ هذه الطَّريقَة التي هي أَخَسُّ مِن طَريقةِ الزَّنادِقة والمُنافِقين، إذا كان المُتَدَيِّن يَطلُب نَجاةَ الآخِرةِ، والزِّنديق يَطلُب النَّجاةَ في الدُّنيا، وهو جَعلَ نَفسَه عُرضةً لإهلاكِها في الدنيا حين طَعَنَ في الإسلامِ في بلادِ الإسلامِ، وأَبطَن الكُفرَ، وأَهلكَ نَفسَه في المَعادِ، فلا عَقلَ له ولا دِينَ\" قال ابنُ الجوزيُّ: \"وقد رَأيتُ لأبي العَلاءِ المَعَرِّي كِتابًا سَمَّاهُ (الفُصول والغايات)، يُعارض به السِّور والآيات، وهو كَلامٌ في نِهايةِ الرَّكَّةِ والبُرودةِ، فسبحان مَن أَعمَى بَصرَهُ وبَصيرتَهُ، وقد ذَكرهُ على حُروفِ المُعجَم في آخرِ كِلماتِه\"، قال ابنُ كَثيرٍ: \"وقد أَورَد ابنُ الجوزي من أَشعارِه الدَّالَّةِ على استِهتارِه بِدِينِ الإسلامِ أَشياءً كَثيرةً تَدُلُّ على كُفرِه؛ بل كلُّ واحدةٍ مِن هذه الأشياءِ تَدُلُّ على كُفرِه وزَندقَتِه وانحِلالِه، وقد زَعمَ بعضُهم أنَّه أَقلَع عن هذا كُلِّه وتاب منه وأنَّه قال قَصيدةً يَعتذِر فيها مِن ذلك كُلِّه، ويَتنَصَّل منه، ومنهم مَن قال: بل كلُّ ذلك مَدسوسٌ عليه مِن قِبَلِ حُسَّادِه وَهُم كُثُر. بل أَلَّفَ ابنُ العديم كِتابًا في الدِّفاعِ عنه، وللمَعَرِّي (دِيوانُ اللُّزومِيَّات)، و(سِقْطُ الزَّنْدِ) و(رِسالةُ الغُفران)\"، قال الباخرزي: \"أبو العلاء ضَريرٌ ما له ضَريبٌ، طال في ظِلِّ الإسلامِ آناؤهُ، ورَشَحَ بالإلحاد إناؤهُ، وعندنا خَبرُ بَصرِه، والله العالم بِبَصيرَتِه والمُطَّلِع على سَريرَتِه، وإنمَّا تَحدَّثت الأَلسُنُ بإساءتِه بكِتابِه الذي عارَضَ به القُرآنَ، وعَنْوَنَهُ: (الفُصولُ والغايات في مُحاذاةِ السُّوَرِ والآيات)\", وقال غَرسُ النِّعمَة محمدُ بن هلالِ بن المُحسِن بن إبراهيمَ الصابئ عنه: \"له شِعْرٌ كَثيرٌ، وأَدَبٌ غَزيرٌ، ويُرمَى بالإلحادِ، وأَشعارُه دَالَّةٌ على ما يُتَّهَمُ به\" قال أبو زكريا التِّبريزي: \"لمَّا قَرأتُ على أبي العَلاءِ بالمَعَرَّةِ قوله:تَناقُضٌ ما لنا إلَّا السُّكوتُ له وأن نَعوذُ بمولانا مِن النَّارِيَدٌ بِخَمسِ مِئٍ مِن عَسْجَدٍ وُدِيَتما بالُها قُطِعَت في رُبعِ دِينارِ؟سَألتُه، فقال: هذا كَقولِ الفُقهاءِ: عِبادَةٌ لا يُعقَل مَعناها\". قال الذَّهبيُّ: لو أراد ذلك؛ لقال: تَعَبُّد، ولَمَا قال: تَناقُض, ولِمَا أَردَفهُ ببَيتٍ آخرَ يَعترِض على رَبِّه, وبإسنادي قال السَّلفيُّ: إن كان قاله مُعتَقِدًا مَعناهُ، فالنَّارُ مَأْواهُ، وليس له في الإسلامِ نَصيبٌ\". تُوفِّي في المَعَرَّةِ مَعَرَّةِ النُّعمانِ، وفيها دُفِنَ عن عُمُرٍ 86 عامًا."},{"id":1570,"title":"استِيلاءُ البساسيري على المَوصِل ثم خُروجُه منها .","date":["العام الهجري :450","العام الميلادي :1058"],"text":"فارَقَ إبراهيمُ ينال المَوصِل نحوَ بلادِ الجَبلِ، فنَسَبَ السُّلطانُ طُغرلبك رَحيلَه إلى العِصيانِ، فأَرسَل إليه رَسولًا يَستَدعِيه، وكَتبَ الخَليفةُ إليه أيضًا كِتابًا في المعنى، فرَجعَ إبراهيمُ إلى السُّلطانِ، وهو ببغداد، ولمَّا فارَق إبراهيمُ المَوصِل قَصدَها البساسيري، وقُريشُ بن بَدران، وحاصَراها، فمَلَكا البلدَ, وبَقِيَت القَلعةُ، وبها الخازِنُ، وأردمُ، وجماعةٌ مِن العَسكرِ، فحاصَراها أَربعةَ أَشهُر حتى أَكلَ مَن فيها دَوابَّهُم، فخاطَب ابنُ موسك صاحبُ إربل قُريشًا حتى أَمَّنَهم فخَرَجوا، فهَدَم البساسيري القَلعةَ، وعَفَى أَثرَها، وكان طُغرلبك قد فَرَّقَ عَسكرَه في النوروز، وبَقِيَ جَريدةً -الجريدة خَيْلٌ لا رَجَّالة فيها- في ألفي فارسٍ حين بَلغهُ الخَبرُ، فسار إلى المَوصِل فلم يجد بها أَحدًا، وكان قُريشٌ والبساسيري قد فارَقاها، فسار طُغرلبك إلى نُصَيبين لِيَتَتَبَّع آثارَهم ويُخرِجَهم من البلادِ، ففارَقه أَخوهُ إبراهيمُ ينال، وسار نحوَ همذان، فوَصَلها في السادسِ والعشرين من رمضان سنة 450هـ، وكان قد قِيلَ: إنَّ المِصريِّين كاتَبوهُ والبساسيري قد استَمالهُ وأَطمعَهُ في السَّلطَنةِ والبلادِ، فلمَّا عاد إلى همذان سار طُغرلبك في أَثَرِه."},{"id":1571,"title":"وَفاةُ القاضي الماوَردِي .","date":["العام الهجري :450","الشهر القمري : ربيع الأول","العام الميلادي :1058"],"text":"هو الإمامُ العَلَّامةُ، أَقضى القُضاةِ، أبو الحسنِ عَلِيُّ بن محمدِ بن حَبيبٍ، المَاوَردِي البَصري، شَيخُ الشَّافعيَّة، كان من وُجوهِ الفُقهاءِ الشَّافعيَّة ومن كِبارِهم، أَخذَ الفِقهَ عن أبي القاسم الصيمري بالبَصرةِ، ثم عن الشيخ أبي حامِد الإسفرايني ببغداد، صاحبِ التَّصانيفِ الكَثيرةِ في الأُصولِ والفُروعِ والتَّفسيرِ والأَحكامِ السُّلطانيَّة، وأَدَبِ الدُّنيا والدِّين، قال الماوردي: \"بَسَطتُ الفِقهَ في أَربعةِ آلافِ وَرقةٍ وقد اختَصرتُه في أَربعينَ\" قال ابنُ الجوزي: \"يُريدُ بالمَبسوطِ الحاويَ، وبالمُختَصَرِ الإقناعَ\" كان أَديبًا حَليمًا وَقورًا، مُتَأَدِّبًا لم يَرَ أَصحابُه ذِراعَه يومًا من الدَّهرِ مِن شِدَّةِ تَحَرُّزِهِ وأَدبِه، وكان ثِقةً صالحًا، حافظًا للمَذهَبِ وله فيه كتاب \"الحاوي الكبير\" الذي لم يُطالِعهُ أَحدٌ إلا وشَهِدَ له بالتَّبَحُّرِ والمَعرفةِ التَّامَّةِ بالمَذهبِ. وفُوِّضَ إليه القَضاءُ بِبُلدانٍ كَثيرةٍ، واستَوطَن بغداد في دَربِ الزَّعفراني، ورَوى عنه الخَطيبُ أبو بكرٍ صاحبُ \"تاريخ بغداد\" وقال: كان ثِقةً. وله من التَّصانيف غير \"الحاوي\" \"تفسير القرآن الكريم\"  و\"النُّكَت والعُيون\" و\"أدب الدِّين والدنيا\" و\"الأحكام السلطانية\" و\"قانون الوزارة\" و\"سياسة المُلْكِ\" و\"الإقناع\" في المَذهَب، وهو مُختصَر، وغير ذلك، وصَنَّفَ في أُصولِ الفِقهِ والأَدبِ وانتفع النَّاسُ به. وقد وَلِيَ الحُكمَ في بلادٍ كَثيرةٍ، وكان ذا حَظوَةٍ عند الخَليفةِ وعند بني بُويه، توفِّي عن سِتٍّ وثمانين سَنةٍ، ودُفِنَ ببابِ حَربٍ."},{"id":1572,"title":"وُقوعُ زَلزلةٍ عَظيمةٍ بالعِراقِ، والمَوصِل .","date":["العام الهجري :450","الشهر القمري : شوال","العام الميلادي :1058"],"text":"وَقعَت زَلزلةٌ عَظيمةٌ بالعراقِ والمَوصِل ووَصلَت إلى همذان، ولَبِثَت ساعةً، فخَرَّبَت كثيرًا مِن الدُّورِ، وهَلَكَ فيها جَمٌّ غَفيرٌ."},{"id":1573,"title":"دُخولُ البساسيري إلى بغداد والخُطبةُ فيها للعُبيديِّين (الفاطِميِّين) .","date":["العام الهجري :450","الشهر القمري : ذي القعدة","العام الميلادي :1059"],"text":"لمَّا خَرجَ طُغرلبك من بغداد خَلْفَ أَخيهِ إبراهيمَ ينال استَغلَّ الفُرصةَ البساسيري، فلمَّا كان يومُ الأحدِ الثامن من ذي القعدة جاء إلى بغداد ومعه الرَّاياتُ البِيضُ المِصريَّةُ العُبيدِيَّةُ، وعلى رَأسِه أَعلامٌ مَكتوبٌ عليها اسمُ المُستَنصِر بالله أبو تَميمٍ مَعَدُّ، أَميرُ المؤمنين، فتَلقَّاهُ أَهلُ الكَرخِ الرَّافِضَةُ وسَألوهُ أن يَجتازَ من عندهم، فدَخلَ الكَرخَ وخَرجَ إلى مشرعةِ الزَّاويا، فخَيَّمَ بها والنَّاسُ إذ ذاك في مَجاعةٍ وضُرٍّ شَديدٍ، ونَزلَ قُريشُ بن بَدران وهو شَريكُ البساسيري في هذه الفِتنةِ، في نحوٍ مِن مائتي فارسٍ على مشرعةِ بابِ البَصرةِ، وكان البساسيري قد جَمعَ العَيَّارِينَ وأَطمَعَهُم في نَهبِ دارِ الخِلافةِ، ونَهَبَ أَهلُ الكَرخِ مِن الشِّيعةِ دُورَ أَهلِ السُّنَّةِ ببابِ البَصرةِ، ونُهِبَت دارُ قاضي القُضاة الدَّامغاني، وتملك وهلك أَكثرُ السِّجِلَّاتِ والكُتبِ الحُكمِيَّة، وبِيعَت للعطَّارِين، ونُهِبَت دُورُ المُتعلِّقِين بخِدمةِ الخَليفةِ، وأَعادَت الرَّوافضُ الأذانَ بحيَّ على خَيرِ العَملِ، وأُذِّنَ به في سائرِ نواحي بغداد في الجُمُعاتِ والجَماعاتِ وخُطِبَ ببغداد للمُستَنصِر العُبيدي على مَنابِرِها، وضُربَت له السِّكَّةُ على الذَّهَبِ والفِضَّةِ، وحُوصِرَت دارُ الخِلافةِ، فدافَع الوزيرُ أبو القاسم بن المسلمة المُلَقَّب برَئيسِ الرُّؤساءِ، بمن معه من المُستَخدِمين دون دارِ الخِلافةِ, فلم يُفِد ذلك شيئًا، فرَكِبَ الخَليفةُ بالسَّوادِ والبُردَةِ، وعلى رَأسِه اللِّواءُ وبِيَدِه سَيفٌ مُصَلَّتٌ، وحولَه زُمرةٌ مِن العبَّاسيِّين والجواري حاسِراتٌ عن وُجوهِهنَّ، ناشِراتٌ شُعورِهِنَّ، ومَعهُنَّ المصاحِفُ على رُؤوسِ الرِّماحِ، وبين يَديهِ الخَدَمُ بالسُّيوفِ، ثم إنَّ الخَليفةَ أَخذَ ذِمامًا من أَميرِ العَربِ قُريشٍ لِيَمنَعهُ وأَهلَهُ ووَزيرَهُ ابن المسلمة، فأَمَّنَهُ على ذلك كُلِّه، وأَنزلَه في خَيمةٍ، فلامَهُ البساسيري على ذلك، وقال: قد عَلِمتَ ما كان وقعَ الاتفاقُ عليه بيني وبينك، من أنَّك لا تَبُتَّ برَأيٍ دُوني، ولا أنا دُونكَ، ومهما مَلكْنَا بيني وبينك. ثم إن البساسيري أخذَ القاسمَ بن مَسلمةَ فوَبَّخَهُ تَوبيخًا مُفضِحًا، ولامَهُ لَومًا شَديدًا ثم ضَربهُ ضَربًا مُبرِحًا، واعتَقلهُ مُهانًا عنده، ونَهبَت العامَّةُ دارَ الخِلافةِ، ثم اتَّفقَ رأيُ البساسيري وقُريشٍ على أن يُسَيِّروا الخليفةَ إلى أَميرِ حَديثَةِ عانَة، وهو مهارش بن مجلي النَّدوي، وهو مِن بني عَمِّ قُريشِ بن بدران، وكان رجلًا فيه دِينٌ وله مُروءةٌ، فلمَّا بلغ ذلك الخَليفةَ دَخلَ على قُريشٍ أن لا يخرج من بغداد فلم يَفِد ذلك شيئًا، وسَيَّرَهُ مع أَصحابِهما في هَودَج إلى حَديثَةِ عانَة، فكان عند مهارش حَولًا كامِلًا، وليس معه أَحدٌ من أَهلِه، وأما البساسيري، وما اعتَمدَهُ في بغداد، فإنَّه رَكِبَ يومَ عيدِ الأضحى وأَلبَس الخُطباءَ والمُؤذِّنينَ البَياضَ، وكذلك أَصحابَه، وعلى رَأسِه الأَلوِيَةُ العُبيديَّة المِصريَّة، وخَطَب للمُستَنصِر العُبيدي المِصري، وانتَقَم البساسيري من أَعيانِ أَهلِ بغداد انتِقامًا عَظيًما، وغَرَّقَ خَلْقًا ممن كان يُعادِيه، وبَسَطَ على آخرين الأرزاقَ ممن كان يُحبُّه ويُواليه، وأَظهرَ العَدلَ، ثم إنَّه عَلَّقَ ابنَ المسلمة رَئيسَ الرُّؤساءِ بِكَلُّوبٍ في شِدْقَيْهِ، ورُفِعَ إلى الخَشبةِ، إلى أن مات."},{"id":1574,"title":"المُرابِطون يَبنُونَ مَدينةَ مَراكِش .","date":["العام الهجري :451","العام الميلادي :1059"],"text":"قَصدَ يُوسفُ بن تاشفِين الملتوني اللَّمْتُوني أَميرُ المُرابِطين مَوضِعَ مَدينةِ مَراكِش، وهو قاعٌ صَفْصَفٌ، لا عِمارةَ فيه، وهو مَوضِعٌ مُتوسِّطٌ في بِلادِ المَغربِ كالقَيروانِ في إفريقية، فاخْتَطَّ هناك مَدينةَ مَراكِش لِيَقوَى على قَمعِ أَهلِ تلك الجِبالِ إن هَمُّوا بفِتنةٍ، فجعلها يُوسفُ مَقَرًّا له ولِعَسكرِهِ وللتمترّس للتَّتَرُّسِ بقَبائلِ المَصامِدَة المصيفة بمَواطنِهم بها في جَبلِ درن، فلم إذ لم يكن في قبائل المغرب أشدُّ منهم، ولا أَكثرُ جَمْعًا، وأَمنعُهم مَعْقَلًا, ونَزلَها بالخِيامِ وأَدارَ سُورهَا على مَسجدٍ وقَصبَةٍ صَغيرةٍ لاختِزانِ أَموالِه وسِلاحِه،، فلم يَتحرَّك أَحدٌ مِن تلك القَبائل بفِتنةٍ، ومَلَكَ البِلادَ المُتَّصِلَة بالمَجازِ مثل سَبْتَة، وطَنْجَة، وسلا، وغَيرَها، وكَثُرت عَساكرُه, وكَمَّل تَشييدَها وأَسوارَها عَلِيُّ بنُ يُوسف بن تاشفين من بَعدِه سَنةَ 526هـ, وقِيلَ: بدأَ ببِنائِها أبو بكرِ بن عُمرَ وأَكملَ بِناءَها يُوسفُ بن تاشفين. وقِيلَ: إن بِناءَها سَنةَ 454هـ."},{"id":1575,"title":"حَريقٌ هائلٌ ببغداد .","date":["العام الهجري :451","العام الميلادي :1059"],"text":"احتَرقَت بغداد، الكَرخُ وغَيرهُ، وبين السُّورَينِ، واحتَرقَت فيه خَزانَةُ الكُتُبِ التي وَقَفَها أردشيرُ الوزيرُ، ونُهِبَت بَعضُ كُتُبِها، وجاء عَميدُ المُلْكِ الكندريُّ، فاختارَ من الكُتُبِ خَيرَها، وكان بها عَشرةُ آلاف وأربعمائة مُجلَّد من أَصنافِ العُلومِ، منها مائةُ مُصحَفٍ بخُطوطِ ابنِ مُقْلَة، وكان العامَّةُ قد نَهَبوا بَعضَها لمَّا وَقعَ الحَريقُ، فأَزالَهم عَميدُ المُلْكِ، وقَعدَ يَختارُها، فنُسِبَ ذلك إلى سُوءِ سِيرَتِه، وفَسادِ اختِيارِه، وشَتَّانَ بين فِعلِه وفِعلِ نِظامِ المُلْكِ الذي عَمَّرَ المَدارِسَ، ودَوَّنَ العِلمَ في بِلادِ الإسلامِ جَميعِها، ووَقَفَ الكُتُبَ وغَيرَها."},{"id":1576,"title":"وَفاةُ فَرَّخ زاد الغَزنَوي صاحبِ غَزنَة ومِلْكُ أَخيهِ إبراهيمَ بعده .","date":["العام الهجري :451","الشهر القمري : صفر","العام الميلادي :1059"],"text":"هو المَلِكُ فَرَّخ زاد بن مسعودِ بن محمودِ بن سُبكتكين، صاحبُ غَزنَة، كان مَلِكًا شُجاعًا مَهيبًا، واسعَ البِلادِ. وكان قد ثار به مَماليكُه سَنةَ خمسين وأربعمائة واتَّفَقوا على قَتلِه، فقَصَدوهُ وهو في الحَمَّامِ، وكان معه سَيفٌ، فأَخذَهُ وقاتَلَهم، ومنعهم عن نَفسِه حتى أَدرَكهُ أَصحابُه وخَلَّصوهُ، وقَتَلوا أولئك الغِلمانَ. وصار بعد أن نَجا من هذه الحادِثَةِ يُكثِر ذِكْرَ الموتِ ويَحتَقِر الدُّنيا ويَزدَريها، وبَقِيَ كذلك إلى هذه السَّنَةِ، فأَصابهُ قولنج فمات منه، ومَلَكَ بعدهُ أَخوهُ إبراهيمُ بن مسعودِ بن محمود، فأَحسنَ السِّيرةَ، فاستَعَدَّ لجِهادِ الهِندِ، ففَتحَ حُصونًا امتَنعَت على أَبيهِ وجَدِّهِ، وكان يَصومُ رَجبًا وشَعبانَ ورَمضان."},{"id":1577,"title":"مَقتَل إبراهيمَ ينال على يَدِ أَخيهِ السُّلطانِ طُغرلبك لِكَثرَةِ تَمَرُّدِهِ .","date":["العام الهجري :451","الشهر القمري : جمادى الآخرة","العام الميلادي :1059"],"text":"كان السُّلطانُ طُغرلبك في قِلَّةٍ مِن العَسكرِ، بينما إبراهيمُ ينال كان قد اجتَمعَ معه كَثيرٌ من الأَتراكِ، وحَلفَ لهم أنَّه لا يُصالِح أَخاهُ طُغرلبك، ولا يُكَلِّفُهم المَسيرَ إلى العراقِ، وكانوا يَكرهونَه لِطُولِ مَقامِهم وكَثرةِ إخراجاتِهم، فلم يَقوَ به طُغرلبك، وأتى إلى إبراهيمَ محمدٌ وأَحمدُ ابنا أَخيهِ أرتاش في خَلْقٍ كَثيرٍ، فازداد بهم قُوَّةً، وازداد طُغرلبك ضَعْفًا، فانزاحَ من بين يَديهِ إلى الرَّيِّ، وكاتَبَ ألبَ أرسلان وإخوتَه وهُم أولادُ أَخيهِ داودَ، يَستَدعِيهم إليه، فجاؤوا بالعَساكِر الكَثيرةِ، فلَقِيَ إبراهيمَ بالقُربِ مِن الرَّيِّ، فانهزَمَ إبراهيمُ ومن معه وأُخِذَ أَسيرًا هو ومحمدٌ وأَحمدُ وَلَدا أَخيهِ، فأَمَرَ به فخُنِقَ بِوَتَرِ قَوسِه تاسعَ جُمادى الآخِرة، وقَتَلَ وَلَدا أَخيهِ معه، وكان إبراهيمُ قد خَرجَ على طُغرلبك مِرارًا، فعَفَا عنه، وإنَّما قَتلهُ في هذه الدَّفعةِ لأنَّه عَلِمَ أنَّ جميعَ ما جَرى على الخَليفةِ كان بِسَببهِ، فلهذا لم يَعْفُ عنه، ولمَّا قَتَلَ إبراهيمَ أَرسلَ طُغرلبك إلى هزارسب بالأهوازِ يُعرِّفهُ ذلك، وعنده عَميدُ المُلْكِ الكندرِيُّ، فسار إلى السُّلطانِ."},{"id":1578,"title":"تَوَلِّي ألب أرسلان مُلْكَ حَرَّان بعدَ أَبيهِ .","date":["العام الهجري :451","الشهر القمري : رجب","العام الميلادي :1059"],"text":"تُوفِّي جغري بك داود بن ميكائيل بن سلجوق، أخو السُّلطانِ طُغرلبك، وقِيلَ: كان مَوتُه في صفر سنة 452هـ، وعُمُرُه نحوَ سبعين سَنةٍ، وكان صاحبَ خُراسان، وهو مُقابلَ آل سُبكتكين ومُقاتِلُهم، ومانِعُهم عن خُراسان، فلمَّا تُوفِّي مَلَكَ بَعدهُ خُراسانَ ابنُه السُّلطانُ ألب أرسلان."},{"id":1579,"title":"السَّلاجِقَة يَقضُونَ على فِتنَةِ البساسيري في بغداد .","date":["العام الهجري :451","الشهر القمري : ذي القعدة","العام الميلادي :1060"],"text":"لمَّا فَرغَ السُّلطانُ طُغرلبك مِن أَمرِ أَخيهِ إبراهيمَ ينال عاد يَطلُب العِراقَ، فأَرسلَ إلى البساسيري وقُريشٍ في إعادةِ الخَليفةِ إلى دارهِ على أن لا يَدخُل طُغرلبك العِراقَ، ويَقنَع بالخُطبةِ والسِّكَّةِ، فلم يُجِب البساسيري إلى ذلك، فرَحلَ طُغرلبك إلى العِراقِ، فانحَدرَ حَرَمُ البساسيري وأَولادُه، ورَحلَ أَهلُ الكَرخِ بنِسائِهم وأَولادِهم في دِجلةَ وعلى الظَّهرِ، وكان دُخولُ البساسيري وأَولادِه بغداد سادِسَ ذي القعدةِ سَنةَ خمسين وأربعمائة، وخَرَجوا منها سادِسَ ذي القعدة سَنةَ إحدى وخمسين وأربعمائة، ووَصلَ طُغرلبك إلى بغداد، ثم قام طُغرلبك على إعادةِ الخَليفةِ إلى بغداد، ثم اعتَذرَ من الخَليفةِ على التَّأَخُّرِ وقال: أنا أمضي خَلفَ هذا الكَلبِ -يعني البساسيري- وأَقصُدُ الشَّامَ، وأَفعلُ في حَقِّ صاحبِ مِصر ما أُجازي به فِعلَه. وقَلَّدَهُ الخَليفةُ بِيَدهِ سَيفًا، وعَبَرَ السُّلطانُ إلى مُعسكَرهِ، وكانت السَّنَةُ مُجْدِبَةً، ولم يَرَ النَّاسُ فيها مَطرًا."},{"id":1580,"title":"مَقتلُ البساسيري  .","date":["العام الهجري :451","الشهر القمري : ذي الحجة","العام الميلادي :1060"],"text":"هو أبو الحارثِ أرسلانُ بن عبدِ الله البساسيري مَملوكٌ تُركيٌّ، مُقَدَّمُ التُّركِ ببغداد، وهو الذي خَرجَ على الخَليفةِ القائمِ بأَمرِ الله ببغداد، وكان قد قَدَّمَهُ على جَميعِ التُّركِ، وقَلَّدَهُ الأمور بأَسرِها، وخُطِبَ له على مَنابرِ العِراقِ وخوزستان، فعَظُمَ أَمرُه وهابَتهُ المُلوكُ، ثم خَرجَ على الخَليفةِ القائمِ، في فِتنةٍ عَظيمةٍ شارَكهُ فيها قُريشُ بنُ بَدران العُقيليُّ، وخَطبَ البساسيري للمُستَنصِر العُبيدي الفاطِمي صاحبِ مِصر، ثم أَخرَج الخَليفةَ القائمَ بالله القائم بأمر الله إلى أَميرِ العَربِ مُحيي الدِّين أبي الحارثِ مهارش بن مجلي النَّدوي صاحبِ الحَديثَةِ وعانَة –أخو قُريشِ بنِ بَدران- فآواهُ وقام بجَميعِ ما يَحتاجُ إليه مُدَّةَ سَنَةٍ كاملةٍ حتى جاء طُغرلبك السلجوقي, فقاتل البساسيري, وقَتلهُ وعاد القائمُ بأَمرِ الله إلى بغداد، وكان دُخولُه إليها في مِثلِ اليَومِ الذي خَرجَ منها بعدَ حَوْلٍ كاملٍ، ثم حَملَ عَسكرُ طُغرلبك على البساسيري،حتى سَقطَ عن الفَرَسِ، ووَقعَ في وَجهِه ضَربةٌ، ودَلَّ عليه بَعضُ الجَرْحَى، فأَخذهُ كمشتكين دواتي عَميدُ المُلْكِ الكندريُّ وقَتلَهُ، وحَملَ رَأسَه إلى السُّلطانِ طُغرلبك، ودَخلَ الجُنْدُ في الظَّعْنِ، فساقُوهُ جَميعَه، وأُخذِت أَموالُ أَهلِ بغداد المَنهوبةُ وأَموالُ البساسيري مع نِسائِه وأَولادِه، وهَلكَ مِن النَّاسِ الخَلْقُ العَظيمُ، وأَمرَ السُّلطانُ بِحَملِ رَأسِ البساسيري إلى دارِ الخِلافةِ، فحُمِلَ إليها، فوَصلَ مُنتصفَ ذي الحجَّةِ سَنةَ إحدى وخمسين وأربعمائة، فنُظِّفَ وغُسِلَ وجُعِلَ على قَناةٍ وطِيفَ به، وصُلِبَ قُبالةَ بابِ النوبي، وكان في أَسْرِ البساسيري جَماعةٌ مِن النِّساءِ المُتَعَلِّقات بدارِ الخِلافةِ، فأُخِذْنَ، وأُكرِمْنَ، وحُمِلْنَ إلى بغداد. كان البساسيري من مماليك بهاءِ الدَّولةِ بن عَضُدِ الدَّولةِ البويهي، تَقَلَّبت به الأُمورُ حتى بلغَ هذا المقامَ المشهورَ، وهو مَنسوبٌ إلى بَسَا مدينةٍ بفارس."},{"id":1581,"title":"القَضاءِ على فِتنةِ البساسيري والخَليفةِ القائمِ بأَمرِ الله يدخل بغداد .","date":["العام الهجري :452","الشهر القمري : صفر","العام الميلادي :1060"],"text":"بعدَ أن فَرغَ طُغرلبك من أَخيهِ إبراهيمَ وغيرِ ذلك من المَشاغلِ أَسرعَ بالعَوْدِ إلى بغداد وليس له هم إلَّا إِعادةُ الخَليفةِ لدارهِ، وكان قد راسلَ البساسيري على أن يُعيدوا الخَليفةَ ويَقنَع هو بعَدمِ العَودةِ إلى بغداد فلم يَرضَ البساسيري، فتَمكَّنَت عَساكرُ طُغرلبك مِن قَتلِه في ذي الحجَّةِ سَنةَ451هـ. أَرسلَ طُغرلبك مِن الطَّريقِ الإمامَ أبا بكرٍ أحمدَ بن محمدِ بن أيوبَ المعروف بابنِ فورك، إلى قُريشِ بن بَدران يَشكُرهُ على فِعلِه بالخَليفةِ، وحِفظِه على صِيانَتِه ابنةِ أَخيهِ امرأةِ الخليفةِ،  ويُعرِّفهُ أنَّه قد أَرسلَ أبا بكرِ بن فورك للقيامِ بخِدمةِ الخليفةِ، وإحضارِهِ، وإحضارِ أرسلان خاتون ابنةِ أَخيهِ امرأةِ الخليفةِ، ولمَّا سَمِعَ قُريشٌ بِقَصدِ طُغرلبك العِراقَ أَرسلَ إلى مهارش بن مجلي الندوي يُحَرِّضُهُ على عَدمِ تَسليمِ الخَليفةِ حتى يَستَطيعوا أن يَشرُطوا ما يريدون؛ لكنَّهُ أَبَى عليهم ذلك، وسار مهارش ومعه الخليفةُ حادي عشر ذي القعدةِ سَنةَ إحدى وخمسين وأربعمائة إلى العِراقِ، وجَعَلا طَريقَهما على بَلدِ بَدرِ بن مهلهل لِيَأمَنَا مَن يَقصِدهُما، ووَصلَ ابنُ فورك إلى حلَّةِ بدرِ بن مهلهل، وطلبَ منه أن يُوصِلَهُ إلى مهارش، فجاء إنسانٌ سوادي إلى بدرٍ وأَخبرهُ أنَّه رأى الخليفةَ ومهارشًا بتل عكبرا، فسُرَّ بذلك بَدرٌ ورَحلَ ومعه ابنُ فورك، وخَدَماهُ، وحَملَ له بَدرٌ شَيئًا كَثيرًا، وأَوصلَ إليه ابنُ فورك رِسالةَ طُغرلبك وهَدايا كَثيرةً أَرسلَها معه، ولمَّا سَمِعَ طُغرلبك بوُصولِ الخليفةِ إلى بَلدِ بَدرٍ أَرسلَ وَزيرَه الكندريَّ، والأُمراءَ، والحُجَّابَ، وأَصحبَهم الخِيامَ العَظيمةَ، والسُّرادِقات، والتُّحَف مِن الخَيلِ بالمَراكِب الذَّهبِ وغيرِ ذلك، فوَصَلوا إلى الخليفةِ وخَدموهُ ورَحَلوا، ووَصلَ الخليفةُ إلى النَّهروان في الرابعِ والعشرين من ذي القعدةِ، وخَرجَ السُّلطانُ إلى خِدمتِه، واعتَذرَ مِن تَأَخُّرِه بعِصيانِ إبراهيمَ، وأنه قَتَلَهُ عُقوبةً لِمَا جَرى منه من الوَهَنِ على الدَّولةِ العبَّاسيَّة، وبِوَفاةِ أَخيهِ داودَ بخُراسان، وأنه اضطرَّ إلى التَّرَيُّثِ حتى يُرَتِّبَ أَولادَهُ بعدَه في المملكةِ، ثم إنَّ الخليفةَ لم يَدخُل بغدادَ إلَّا في هذه السَّنَةِ في صفر في السابع عشر منها."},{"id":1582,"title":"استيلاءُ المِرداسِيِّين على حَلَبَ ومَوقعةُ الفُنَيْدِق .","date":["العام الهجري :452","الشهر القمري : شعبان","العام الميلادي :1060"],"text":"حَصَرَ عِزُّ الدَّولةِ محمودُ بن شِبْلِ الدَّولةِ نَصرِ بن صالحِ بن مِرداس الكِلابي مدينةَ حَلَب، وضَيَّقَ عليها، واجتَمعَ مع جَمعٍ كَثيرٍ من العَربِ، فأَقامَ عليها، فلم يَتمكَّن مِن فَتحِها، فرَحلَ عنها، ثم عاوَدَها فحَصرَها، فمَلَكَ المدينةَ عَنوةً، بعدَ أن حَصرَها، وامتَنعَت القَلعةُ عليه. -كانت حَلبُ أوَّلًا بِيَدِ ثمالِ بن صالحِ بن مِرداس؛ لكنَّ أَهلَ حَلبَ لمَّا خَرجَ ثمالٌ إلى مِصرَ سَلَّموها إلى مَكينِ الدَّولةِ الحَسنِ بن عَليِّ بن ملهمٍ والي المُستَنصِر الفاطمي-. أَرسلَ مَن بِحَلبَ إلى المُستَنصِر، صاحبِ مِصر ودِمشق، يَستَنجِدونَه، فأَمرَ ناصرُ الدولةِ أبا محمد الحسينَ بنَ الحسنِ بن حمدان، الأميرَ بِدِمشق، أن يَسيرَ بمَن عندَه مِن العَساكرِ إلى حَلبَ يَستَردَّها من محمود، فسار إلى حَلبَ، فلمَّا سَمِعَ محمودٌ بِقُربِه منه خَرجَ مِن حَلبَ، ودَخلَها عَسكرُ ناصرِ الدولةِ فنَهَبوها، ثم إنَّ الحربَ وقعت بين محمود وناصرِ الدولةِ بظاهرِ حَلبَ، واشتَدَّ القِتالُ بينهم، فانهَزمَ ناصرُ الدولةِ وعاد مَقهورًا إلى مِصر، ومَلَكَ محمود حَلبَ، واستقام أَمرُه بها، وهذه الوقعة تُعرَف بوقعة الفُنَيْدِق، وهي مشهورة، وكان ذلك في شعبان."},{"id":1583,"title":"يُوسفُ بن تاشفين يَتولَّى شُؤونَ دَولةِ المُرابطين .","date":["العام الهجري :453","العام الميلادي :1061"],"text":"قام أبو بكرِ بن عُمرَ اللَّمتُوني زَعيمُ المُرابطين بالمَغرِب بِتَولِيَةِ ابنِ عَمِّهِ يُوسفَ بن تاشفين شُؤونَ المُرابطين، وتَوجَّه أبو بكرٍ إلى الجنوبِ على رَأسِ جَيشٍ مُختَرِقًا بِلادَ سجلماسة، ثم قَصدَ بِلادَ السُّودانَ السِّنغالَ مُتوغِّلًا فيها ناشِرًا للإسلام."},{"id":1584,"title":"وَفاةُ نَصرِ الدَّولةِ الكُردي صاحبِ دِيارِ بَكرٍ .","date":["العام الهجري :453","الشهر القمري : شوال","العام الميلادي :1061"],"text":"هو نَصرُ الدَّولةِ أحمدُ بن مَروان الكُردي، صاحبُ دِيارِ بِكرٍ، ولَقَبُه القادرُ بالله نَصرُ الدولةِ، واستَولى على الأُمورِ ببِلادهِ استِيلاءً تامًّا، وعَمَّرَ الثُّغورَ وضَبطَها، وتَنَعَّم تَنَعُّمًا لم يُسمَع بمِثلِه عن أَحدٍ مِن أَهلِ زَمانِه، ومَلَكَ خمسمائة سُرِّيَّةٍ سوى تَوابعهنَّ، وخمسمائة خادم، وكان في مَجلسِه من الآلاتِ ما تَزيدُ قَيمتُه على مائتي ألف دينارٍ، وتَزوَّج من بناتِ المُلوكِ جُملةً، وأَرسلَ طبَّاخين إلى الدِّيارِ المِصريَّة، وغَرِمَ على إرسالِهم جُملةً وافرةً حتى تَعلَّموا الطَّبْخَ من هناك، وأَرسلَ إلى السُّلطانِ طُغرلبك هَدايا عظيمةً، مِن جُملتِها الجَبلُ الياقوتُ الذي كان لِبَنِي بُويه، اشتَراهُ مِن المَلِكِ العزيزِ أبي منصورِ بن جَلالِ الدَّولةِ، وأَرسلَ معه مائةَ ألف دينارٍ سوى ذلك، ووَزَرَ له أبو القاسمِ بن المغربي، وفَخرُ الدَّولةِ بن جَهيرٍ، ورَخُصَت الأَسعارُ في أَيَّامِه، وتَظاهَر النَّاسُ بالأموالِ، ووَفدَ إليه الشُّعراءُ، وأَقامَ عندَه العُلماءُ والزُّهَّادُ. قال ابنُ خلكان: \"قال ابنُ الأزرقِ في تاريخِه: إنَّه لم يُصادِر أحدًا مِن رَعِيَّتِه سوى رَجُلٍ واحدٍ، ولم تَفُتْهُ صلاةُ الفَجرِ مع كَثرةِ مُباشرَتِه للَّذاتِ، وكان له ثلاثمائة وسِتُّون حَظِيَّةً، يَبيتُ عند كُلِّ واحدةٍ لَيلةً في السَّنَةِ، وخَلَّفَ أَولادًا كَثيرةً\"، ولم يَزل على ذلك إلى أن تُوفِّي في التاسع والعشرين من شَوَّال من هذه السَّنةِ. تُوفِّي نَصرُ الدَّولةِ عن عُمُرِ نَيِّفٍ وثمانين سَنةٍ، وإمارتُه اثنتين وخمسين سَنةً. ولمَّا مات اتَّفقَ وَزيرُه فَخرُ الدولةِ بن جَهيرٍ وابنُه نَصرُ، فرَتَّبَ نَصرًا في المُلْكِ بعدَ أَبيهِ، وجَرى بينه وبين أَخيهِ سَعيدٍ حُروبٌ شَديدةٌ كان الظَّفَرُ في آخرِها لنَصرٍ، فاستَقرَّ في الإمارةِ بميافارقين وغيرِها، ومَلَكَ أَخوهُ سَعيدٌ آمد."},{"id":1585,"title":"دخول قبائل المَغربِ الأقصى في طاعة يُوسف بن تاشفين .","date":["العام الهجري :454","العام الميلادي :1062"],"text":"بعد أن قامَ يُوسفُ بن تاشفين بِفَتحِ مدينةِ فاس، أَخضعَ مُعظمَ نواحي المَغربِ الجَنوبيَّة والوُسطى، ودَخلَ في طاعتِه قبائلُ مغراتة وزناتة وبني يفرن."},{"id":1586,"title":"بِدايةُ الخِلافِ بين العَسكرِ الأَتراكِ والعُبيديين (الفاطميين) .","date":["العام الهجري :454","الشهر القمري : جمادى الآخرة","العام الميلادي :1062"],"text":"خَرجَ المُستَنصِرُ الفاطمي على عادَتهِ في كلِّ سَنَةٍ يَركبُ على النُّجُبِ ومعه النِّساءُ والحَشَمُ إلى جب عميرة، وهو موضع نُزهَةٍ، ويُغيِّر هَيئتَه، كأنَّه خارجٌ يُريدُ الحَجَّ على سَبيلِ الهَزْرِ والمَجانَةِ، ومعه الخَمْرُ مَحمولٌ في الرَّوايا عِوَضًا عن الماءِ، ويَدورُ به سُقاتِه عليه وعلى مَن معه كأنَّه بِطريقِ الحِجاز أو كأنه ماءُ زمزم؛ واتَّفقَ أن بعضَ الأَتراكِ جَرَّدَ سَيْفًا في سَكْرَةٍ منه على بَعضِ عَبيدِ الشِّراءِ، فاجتَمعَ عليه عِدَّةٌ من العَبيدِ وقَتلوهُ. فغَضِبَ لذلك جَماعةُ الأَتراكِ واجتَمَعوا بأَسرِهم ودَخَلوا على المُستَنصِر، وقالوا: إن كان هذا الذي قُتِلَ مِنَّا على رِضاكَ فالسَّمعُ والطَّاعة، وإن كان قَتْلُه عن غيرِ رِضا أَميرِ المؤمنين فلا صَبرَ لنا على ذلك. وأَنكرَ المُستَنصِر أن قَتْلَه بِرضاهُ أو أَمرِه؛ فخَرجَ الأتراكُ واشتَدُّوا على العَبيدِ يُريدون مُحاربَتَهم، فبَرَزَت العَبيدُ إليهم؛ وكانت بين الفَريقينِ حُروبٌ بِناحِيَةِ كَومِ شَريكٍ قُتِلَ فيها عِدَّةٌ، وانهَزمَ العَبيدُ وقَوِيَت الأتراكُ؛ هذا وأُمُّ المُستَنصِر تَمُدُّ العَبيدَ بالأَموالِ والسِّلاحِ، فاتَّفقَ في بعضِ الأيامِ أن بعضَ الأَتراكِ وقفَ على شيءٍ ممَّا تَبْعَثُ به أُمُّ المُستَنصِر إلى العَبيدِ لِتُعينَهم به على مُحاربةِ الأَتراكِ، فاجتَمَعوا وصاروا إلى المُستَنصِر وتَجَرَّءُوا عليه بالقَولِ وأَغلَظوا في المُخاطبةِ؛ فأَنكرَ أن يكون عندَه مِن ذلك خَبَرٌ، وصار السَّيفُ قائمًا. فدَخلَ على أُمِّه وأَنكرَ عليها ما تَعتمِدهُ مِن تَقويَةِ العَبيدِ وإعانتِهم على مُحاربةِ الأَتراكِ، ثم انتَدبَ وَزيرَهُ أبا الفَرجِ ابن المغربي، فخَرجَ ولم يَزل يَسعى بين الأتراكِ والعَبيدِ حتى أَوقعَ الصُّلحَ بين الفَريقين. فاجتَمعَ العَبيدُ وساروا إلى ناحيةِ شبرا دمنهور. فكانت هذه الكائنةُ أوَّلَ الاختلافِ بين طَوائفِ العَسكر."},{"id":1587,"title":"وَفاةُ المُعِزِّ بن باديس ووِلايةُ ابنهِ تَميم .","date":["العام الهجري :454","الشهر القمري : شعبان","العام الميلادي :1062"],"text":"هو المُعِزُّ بن باديس بن المنصور بن بلكين بن زيري بن مناد الحِميريُّ الصَّنهاجيُّ، صاحبُ إفريقية وما والاها مِن بلادِ المَغرب، وكانت وِلادتُه بالمَنصوريَّة، ويُقال لها صبرة، من أَعمالِ إفريقية، يومَ الخميسِ لِخَمسٍ مَضَيْنَ من جمادى الأُولى سنةَ 398هـ، ومَلَكَ بعدَ أَبيهِ باديس سنةَ 406هـ, وكان الحاكمُ العُبيدي صاحبُ مصر قد لَقَّبَهُ شَرَفَ الدَّولةِ، وسَيَّرَ له تَشريفًا وسِجِلًّا يَتضمَّن اللَّقب سنةَ 447هـ, وكان مَلِكًا جَليلًا عالي الهِمَّة، مُحِبًّا لأهلِ العِلمِ كَثيرَ العَطاءِ، وكان واسطة عقد بيته, ومَدحَه الشُّعراءُ وانتَجعَه الأُدباءُ، وكانت حَضرتُه مَحَطَّ الآمالِ. وكان مَذهبُ أبي حنيفة بإفريقية أَظهرَ المذاهِب، فحَمَلَ المُعِزُّ جميعَ أَهلِ المَغربِ على التَّمَسُّكِ بمَذهبِ الإمامِ مالك، وحَسَمَ مادةَ الخِلافِ في المَذاهبِ, خَلَعَ طاعةَ العُبيديِّين الإسماعيلية، وخَطَبَ للقائمِ بأَمرِ الله العبَّاسي، فبَعَثَ إليه المُستَنصِر يَتهدَّدهُ، فلم يَخَفْهُ، فجَهَّزَ لمُحارَبتِه من مصر العَربَ، فخَرَّبوا حُصونَ برقة وإفريقية، وأَخذوا أماكنَ، واستَوطَنوا تلك الدِّيارَ, من هذا الزمانِ لم يُخطَب لِبَني عُبيدٍ بعدَها. تُوفِّي من مَرضٍ أَصابهُ، وهو ضَعْفُ الكَبِدِ، وكانت مُدَّةُ مُلكِه سبعًا وأربعين سنةً، ولمَّا تُوفِّي مَلَكَ بعدَه ابنُه تُميمٌ، ولمَّا استَبَدَّ بالمُلْكِ بعدَ أَبيهِ سَلَكَ طَريقَه في حُسْنِ السِّيرةِ، ومُحَبَّةِ أَهلِ العِلمِ، إلَّا أنه كان أصحاب البلاد إلَّا أنَّ أصحابَ البِلادِ قد طَمِعوا بَسببِ العَربِ، وزالت الهَيبةُ والطَّاعةُ عنهم في أَيامِ المُعِزِّ، فلمَّا مات ازدادَ طَمعُهم، وأَظهرَ كَثيرٌ منهم الخِلافَ."},{"id":1588,"title":"زَواجُ السُّلطانِ طُغرلبك من ابنةِ الخليفةِ العبَّاسي .","date":["العام الهجري :454","الشهر القمري : شعبان","العام الميلادي :1062"],"text":"خَطَبَ السُّلطانُ طُغرلبك ابنةَ الخليفةِ، فانزَعجَ الخليفةُ من ذلك، وقال: هذا شيءٌ لم تَجْرِ العادةُ بمِثلهِ، ثم طَلَبَ شيئًا كَثيرًا كهَيئةِ الفِرارِ، من ذلك أنه طَلبَ ما كان لِزَوجتِه التي تُوفِّيت من الإقطاعات بأرضِ واسط، و300 ألف دينارٍ، وأن يُقيمَ السُّلطانُ طُغرلبك ببغداد لا يَرحل عنها ولا يومًا واحدًا، فوقعَ الاتِّفاقُ على بعضِ ذلك، وأَرسلَ إليها بمائةِ ألف دينارٍ مع أرسلان خاتون ابنةِ أَخيهِ داودَ وزَوجةِ الخليفةِ، وأشياءَ كثيرةٍ من آنيةِ الذَّهَبِ والفِضَّة، والنِّثارِ والجَواري، ومِن الجواهرِ ألفانِ ومائتي قِطعةٍ، من ذلك سبعمائة قِطعةٍ من جَوهرٍ، وزنُ القِطعةِ ما بين الثلاثِ مَثاقيل إلى المِثقالِ، وأشياءَ أُخرى، فتَمَنَّع الخليفةُ لِفَواتِ بَعضِ الشُّروطِ، فغَضِبَ عَميدُ المُلْكِ الوزيرُ لِمَخدُومهِ السُّلطان، وجَرَت شُرورٌ طويلةٌ اقتَضَت أن أَرسلَ السُّلطانُ كِتابًا يَأمرُ الخليفةَ بانتِزاعِ ابنةِ أَخيهِ السيدة أرسلان خاتون، ونَقلِها من دارِ الخِلافةِ إلى دار المَملكةِ، حتى تَنفصِل هذه القَضيَّة، فعَزَم الخَليفةُ على الرَّحيلِ من بغداد، فانزَعجَ النَّاسُ لذلك، وجاء كِتابُ السُّلطانِ إلى رئيسِ شِحْنَةِ – القَيِّم لِضَبطِ البَلدِ- بغداد برشتق يَأمُره بعدمِ المُراقبةِ وكَثرةِ العَسْفِ في مُقابلةِ رَدِّ أصحابِه بالحِرمانِ، ويَعزِم على نَقلِ الخاتون إلى دارِ المُلْكِ، وأَرسلَ مَن يَحمِلها إلى البلدِ التي هو فيها، كل ذلك غَضَبًا على الخَليفةِ، ووَرَدَت الكُتبُ الكثيرةُ من السُّلطانِ طُغرلبك يشكو من قِلَّةِ إنصافِ الخليفةِ، وعَدمِ مُوافقَتِه له، ويَذكُر ما أَسداهُ إليه من الخيرِ والنِّعَمِ إلى مُلوكِ الأَطرافِ، وقاضي القُضاة الدَّامغاني، فلمَّا رأى الخليفةُ ذلك، وأنَّ السُّلطان أَرسلَ إلى نُوَّابِه بالاحتياطِ على أَموالِ الخليفةِ، كَتبَ إلى السُّلطانِ يُجيبُه إلى ما سألَ، فلمَّا وَصلَ ذلك إلى طُغرلبك فَرِحَ فَرحًا شَديدًا، وأَرسلَ إلى نُوَّابِه أن يُطلِقوا أَملاكَ الخَليفةِ، واتَّفقَت الكَلِمةُ بعدَ أن كادت تَتَفرَّق، فوَكَلَ الخَليفةُ في العَقْدِ، فوَقعَ العَقْدُ بمدينةِ تبريز بحَضرةِ السُّلطانِ طُغرلبك، وعَمِلَ سِماطًا عظيمًا، فلمَّا جيءَ بالمُوكِلة قام لها السُّلطانُ وقَبَّلَ الأرضَ عند رُؤيتِها، ودعا للخَليفةِ دُعاءً كثيرًا، ثم أَوجبَ العَقْدَ على صَداقِ أربعمائة ألف دينارٍ، وذلك في يوم الخميس الثالث عشر من شعبان، ثم بَعثَ ابنةَ أَخيهِ الخاتون زوجةَ الخليفةِ في شوال بتُحَفٍ كثيرةٍ، وجَوهرٍ وذَهَبٍ كَثيرٍ، وجَواهرَ عديدةٍ ثَمينةٍ، وهدايا عَظيمةٍ لأُمِّ العَروسِ وأَهلِها، ولمَّا استَقرَّ السُّلطانُ ببغداد أَرسلَ وَزيرَه عَميدَ المُلْكِ إلى الخليفةِ يُطالِبه بِنَقْلِ ابنتِه إلى دارِ المملكةِ فتَمنَّع الخليفةُ من ذلك وقال: إنَّكم إنَّما سألتُم أن يُعقَد العَقْدُ فقط بحُصولِ التَّشريفِ، والتَزمتُم لها بِعَوْدِ المُطالبةِ، فتَردَّد النَّاسُ في ذلك بين الخليفةِ والسُّلطانِ، وأَرسلَ السُّلطانُ زيادةً على النَّقْدِ مائةَ ألف دينارٍ ومائة وخمسين ألف درهمٍ، وتُحَفًا أُخَرَ، وأشياءَ لطيفةً، فلمَّا كان ليلة الاثنين الخامس عشر من صفر سنة455هـ زُفَّت السيدةُ ابنةُ الخليفةِ إلى دارِ المملكةِ، فضُرِبَت لها السُّرادِق من دِجلة إلى دارِ المملكةِ، وضُرِبت الدَّبادِبُ والبُوقاتُ عند دُخولِها إلى الدارِ."},{"id":1589,"title":"وَفاةُ القاضي المُؤَرِّخ أبي عبدِالله محمدِ بن سَلامةَ المعروف بالقَضاعي .","date":["العام الهجري :454","الشهر القمري : ذي القعدة","العام الميلادي :1062"],"text":"هو الفَقيهُ، العلَّامةُ، القاضي المُؤرِّخ أبو عبدِالله محمدُ بن سَلامةَ بن جَعفرٍ المعروفُ بالقَضاعي، المِصري، الشافعي، كان من الثِّقاتِ الأثباتِ, إمامًا في الفِقهِ والحديثِ، وكان يَنوبُ في القَضاءِ بمصر أيامَ المُستَنصِر الفاطمي, وكان المُستَنصِر قد أَرسلَهُ في سِفارةٍ للتَّفاوُضِ مع إمبراطورِ الرُّومِ في القسطنطينية بشأنِ العِلاقة بين الدَّولتينِ. وهو صاحبُ كتابِ (الشِّهاب) مُجرَّدًا ومُسنَدًا، وتَولَّى القَضاءَ بمصر, واشتَغلَ بالتَّاريخِ وله عِدَّةُ تَصانيف: منها كتاب (أخبار الشافعي) وكتاب (الإنباء عن  الأنبياء) و(تَواريخ الخُلفاء) وله كتاب (خطط مصر) اعتَمدَ عليه المَقريزي في خططه, وكان مُفَنَّنًا في عِدَّةِ عُلومٍ. تُوفِّي بمصر، وصُلِّيَ عليه يومَ الجُمعةِ بعدَ العَصرِ في مُصَلَّى النَّجَّارِ."},{"id":1590,"title":"العُبيدِيُّون (الفاطِميُّون) يُعاوِدونَ بَسْطَ نُفوذِهم على الحِجازِ .","date":["العام الهجري :455","العام الميلادي :1063"],"text":"قَدِمَ الصليحي اليمني مكَّةَ بعدَ ما مَلَكَ اليمنَ كُلَّهُ سَهْلَهُ وجَبَلَهُ، وبَرَّهُ وبَحْرَهُ، وأقامَ بها وبمَكَّةَ دَعوةً المُستَنصِر، وكَسَا الكعبةَ حَريرًا أبيضَ، ورَدَّ حِليةَ البَيتِ إليه؛ وكان بنو حسنٍ قد أَخذوها ومَضوا بها إلى اليمنِ، فاشتَراها منهم، وأَعادَها في هذه السَّنةِ. واستَخلفَ على مكَّةَ محمدَ بن أبي هاشم، وعاد إلى اليمنِ."},{"id":1591,"title":"وُقوعُ زَلزلةٍ عَظيمةٍ بالشَّامِ .","date":["العام الهجري :455","الشهر القمري : شعبان","العام الميلادي :1063"],"text":"وَقعَت بالشَّامِ زَلزلةٌ عَظيمةٌ خَرِبَ منها كَثيرٌ من البلادِ، وانهَدمَ سُورُ طرابلس."},{"id":1592,"title":"وَفاةُ السُّلطانِ طُغرلبك وتَوَلِّي ابنِ أَخيهِ ليمان بن داودَ بعدَه .","date":["العام الهجري :455","الشهر القمري : رمضان","العام الميلادي :1063"],"text":"هو السُّلطانُ الكبيرُ، رُكْنُ الدِّين، أبو طالبٍ، طُغرلبك محمدُ بن ميكائيل بن سَلجوق بن دقاق أوَّلُ مُلوكِ السَّلاجِقة, وأَصلُ السَّلاجِقة مِن بَرِّ بُخارى؛ لهم عددٌ وقُوَّةٌ وإِقدامٌ، وشَجاعةٌ وشَهامةٌ وزَعارةٌ، فلا يَدخُلون تحتَ طاعةٍ، وإذا قَصدَهُم مَلِكٌ دَخَلوا البَرِّيَّة, ثم إن طُغرلبك عَظُمَ سُلطانُه، وطَوَى المَمالِكَ، واستولى على العِراقِ في سنة 447هـ، وتَحبَّبَ إلى الرَّعيَّةِ بِعَدْلٍ مَشُوبٍ بِجَوْرٍ، وكان حَليمًا كَثيرَ الاحتمالِ، شَديدَ الكِتمانِ للسِّرِّ، مُحافِظًا على الصَّلواتِ، وعلى صَومِ الاثنينِ والخَميسِ، مُواظِبًا على لُبْسِ البَياضِ، ويبني المَساجِد، ويَتصدَّق، سار السُّلطانُ طُغرلبك من بغداد، في رَبيعٍ الأوَّل، إلى بلدِ الجَبَلِ، فوَصلَ إلى الرَّيِّ واستَصحَب معه أرسلان خاتون ابنةَ أَخيهِ، زَوجةَ الخليفةِ، لأنَّها شَكَت إطراحَ الخليفةِ لها، فأَخذَها معه، فمرضَ، فلمَّا كانت ليلةُ الأحدِ الرابع والعشرين من رمضان جاء الخبرُ بأنَّه تُوفِّي في ثامنِ الشهرِ، فثار العَيَّارُون فقَتَلوا وَزيرَ السُّلطانِ عَميدَ المُلْكِ  الكندريَّ وسبعمائة من أصحابِه، ونَهَبوا الأموالَ، وجَعَلوا يأكلون ويشربون على القَتْلَى نهارًا، حتى انسلخَ الشهرُ وأُخِذَت البَيْعَةُ بعدَه لِوَلَدِ أخيهِ سُليمان بن داودَ، وكان طُغرلبك قد نَصَّ عليه وأَوصَى إليه، لأنَّه كان قد تَزَوَّج بأُمِّهِ، واتَّفَقَت الكَلمةُ عليه، ولم يبق عليه خَوْفٌ إلَّا مِن جِهَةِ أَخيهِ المَلِكِ عَضُدِ الدَّولةِ ألب أرسلان محمد بن داود، وكان مُدَّةُ مُلْكِ طُغرلبك بحَضرةِ القائمِ بأمرِ الله سبعَ سنين وإحدى عشر شهرًا، واثني عشر يومًا وكان عُمُرُهُ يومَ مات سبعين سنة."},{"id":1593,"title":"ألب أرسلان يَخْلُف عَمَّهُ طُغرلبك السلجوقي .","date":["العام الهجري :455","الشهر القمري : رمضان","العام الميلادي :1063"],"text":"لمَّا خُطِبَ لسُليمانَ بن داودَ بالسَّلْطَنَةِ اختَلفَ الأُمراءُ، فمَضَى باغي سيان وأردم إلى قَزوين، وخَطَبا لأَخيهِ عَضُدِ الدَّولةِ ألب أرسلان محمدِ بن داودَ جغري بك بن ميكائيل بن سلجوق، ابن أخي طُغرلبك وهو حينئذٍ صاحبُ خُراسان، ومعه نِظامُ المُلْكِ وَزيرُه، والناسُ مائِلونَ إليهِ، وكذلك الجَيشُ كانوا يَميلونَ إليهِ، وقد خَطَبَ له أَهلُ الجَبَلِ ومعه نِظامُ المُلْكِ أبو عليٍّ الحَسنُ بن عَلِيِّ بن إسحاقَ وَزيرُه، ولمَّا رأى الكندريُّ قُوَّةَ أَمرِه خَطَبَ له بالرَّيِّ، ثم مِن بَعدِه لأَخيهِ سُليمانَ بنِ داودَ."},{"id":1594,"title":"ألب أرسلان يسيطر على مدينة ختلان وهراة وصغانيان .","date":["العام الهجري :456","العام الميلادي :1063"],"text":"لمَّا مَلَكَ ألب أرسلان عَصَى عليه أَميرُ ختلان بِقَلعَتِه، ومَنعَ الخَراجَ، فقَصدَهُ السُّلطانُ، فرأى الحِصْنَ مَنيعًا على شاهقٍ، فأَقامَ عليه وقاتَلَهُ، فلم يَصِل منه إلى مُرادِه، ففي بَعضِ الأيَّامِ باشَرَ ألب أرسلان القِتالَ بِنَفسِه، وتَرَجَّلَ، وصَعَدَ في الجَبلِ، فتَبِعَهُ الخَلْقُ، وتَقدَّموا عليه في المَوقِف، وأَلَحُّوا في الزَّحْفِ والقِتالِ، وكان صاحبُ القَلعَةِ على شُرْفَةٍ من سُورِها يُحَرِّضُ الناسَ على القِتالِ، فأَتتهُ نُشَّابَةٌ من العَسكرِ فقَتَلَتْهُ، وتَسلَّم ألب أرسلان القَلعةَ وصارت في جُملةِ مَمالِكِه، وكان عَمُّهُ فَخْرُ المُلْكِ بيغو بن ميكائيل في هراة، فعَصَى أيضًا عليه، وطَمِعَ في المُلْكِ لِنَفسِه، فسار إليه ألب أرسلان في العَساكِرِ العَظيمةِ، فحَصَرَهُ وضَيَّقَ عليه، وأَدامَ القِتالَ لَيلًا ونَهارًا، فتَسَلَّمَ المَدينةَ، وخَرجَ عَمُّهُ إليه، فأَبقى عليه وأَكرَمَهُ وأَحسَنَ صُحبَتَهُ، وسار من هناك إلى صغانيان، وأَميرُها اسمُه موسى، وكان قد عَصَى عليه، فلمَّا قارَبَهُ ألب أرسلان صَعَدَ موسى إلى قَلعةٍ على رَأسِ جَبلٍ شاهِقٍ، ومعه مِن الرِّجالِ الكُماةِ جَماعةٌ كَثيرةٌ، فوَصَل السُّلطانُ إليه، وباشَر الحَربَ لِوَقتِه، فلم يَنتَصِف النَّهارُ حتى صَعدَ العَسكرُ الجَبلَ، ومَلَكوا القَلعةَ قَهْرًا، وأُخِذَ موسى أَسِيرًا، فأَمَر بِقَتلِه، فبَذَلَ في نَفسِه أَموالًا كَثيرةً، فقال السُّلطانُ: ليس هذا أوانَ تِجارَةٍ. واستَولَى على تلك الوِلايةِ بأَسْرِها، وعاد إلى مرو، ثم منها إلى نيسابور."},{"id":1595,"title":"فَتْحُ ألب أرسلان مدينةَ آني وغَيرَها مِن بِلادِ النَّصرانِيَّة .","date":["العام الهجري :456","العام الميلادي :1063"],"text":"سار السُّلطانُ ألب أرسلان من الرَّيِّ إلى أذربيجان، فوَصلَ إلى مرند عازِمًا على قِتالِ الرُّومِ وغَزْوِهِم، فلمَّا فَرَغَ مِن جَمعِ العساكرِ والسُّفُنِ سار إلى بلادِ الكرج، وجَعلَ مَكانَه في عَسكرِه وَلَدَهُ ملكشاه، ونِظامَ المُلْكِ وَزيرَه، فسار ملكشاه ونِظامُ المُلْكِ إلى قَلعةٍ فيها جَمعٌ كَثيرٌ مِن الرُّومِ، فنَزلَ أَهلُها منها، وتَخَطَّفُوا من العَسكرِ، وقَتَلوا منهم فِئَةً كَثيرةً، فنَزلَ نِظامُ المُلْكِ وملكشاه، وقاتَلوا مَن بالقَلعةِ، وزَحَفوا إليهم، فقُتِلَ أَميرُ القَلعةِ ومَلَكَها المُسلِمون، وساروا منها إلى قَلعةِ سرماري، وهي قَلعةٌ فيها من المِياهِ الجاريةِ والبَساتين، فَقاتَلوها ومَلَكوها، وأَنزَلوا منها أَهلَها، وكان بالقُربِ منها قَلعةٌ أُخرى، ففَتَحَها ملكشاه، وأَرادَ تَخريبَها، فنَهاهُ نِظامُ المُلْكِ عن ذلك، وقال: هي ثَغْرٌ للمُسلِمين، وشَحَنَها بالرِّجالِ والذَّخائِر والأَموالِ والسِّلاحِ، وسَلَّمَ هذه القِلاعَ إلى أَميرِ نقجوان، وسار ملكشاه ونِظامُ المُلْكِ إلى مَدينةِ مريم نشين، وهي مَدينةٌ حَصينَةٌ، سُورُها مِن الأَحجارِ الكِبارِ الصَّلْبَةِ، المَشدُودةِ بالرَّصاصِ والحَديدِ، وعندَها نَهْرٌ كَبيرٌ، فأَعَدَّ نِظامُ المُلْكِ لِقِتالِها ما يَحتاجُ إليه من السُّفُنِ وغَيرِها، وقاتَلَها، فضَجِرَ الكُفَّارُ، وأَخذَهم الإعياءُ والكَلالُ، فوَصلَ المسلمون إلى سُورِها، ونَصَبوا عليه السَّلاليمَ، وصَعَدوا إلى أَعلاهُ، فلمَّا رأى أَهلُها المسلمين على السُّورِ فَتَّ ذلك في أَعضادِهِم، وسُقِطَ في أيديهِم، ودَخلَ ملكشاه البلدَ، ونِظامُ المُلْكِ، وأَحرَقوا البِيَعَ، وخَرَّبوها، وقَتَلوا كَثيرًا من أَهلِها، وأَسلمَ كَثيرٌ فنَجَوْا من القَتلِ، واستَدعَى ألب أرسلان إليه ابنَه، ونِظامَ المُلْكِ، وفَرِحَ بما يَسَّرَهُ الله من الفَتحِ على يَدِ وَلَدِه. وفَتَحَ ملكشاه في طَريقِه عِدَّةً من القِلاعِ والحُصونِ، وأَسَرَ من النَّصارَى ما لا يُحصَونَ كَثْرَةً. وساروا إلى سبيذ شهر، فجَرَى بين أَهلِها وبين المسلمين حُروبٌ شَديدةٌ استُشهِدَ فيها كَثيرٌ من المسلمين، ثم إنَّ الله تعالى يَسَّرَ فَتْحَها فمَلَكَها ألب أرسلان، وسار منها إلى مَدينةِ أعآل لآل، وهي حَصينةٌ، عاليةُ الأَسوارِ، شاهِقةُ البُنيانِ، وهي من جِهَةِ الشَّرقِ والغَربِ على جَبلٍ عالٍ، وعلى الجَبلِ عِدَّةٌ من الحُصونِ، ومن الجانِبينِ الآخرينِ نَهْرٌ كَبيرٌ لا يُخاض، فلمَّا رآها المسلمون عَلِموا عَجزَهم عن فَتْحِها والاستيلاءِ عليها، وكان مَلِكُها من الكرج، وعَقَدَ السُّلطانُ جِسْرًا على النَّهْرِ عَريضًا، واشتَدَّ القِتالُ، وعَظُمَ الخَطْبُ، فخَرَجَ من المدينةِ رَجُلانِ يَستَغيثانِ، ويَطلُبانِ الأَمانَ، والتَمَسا من السُّلطانِ أن يُرسِلَ معهما طائفةٌ من العَسكرِ، فسَيَّرَ جَمْعًا صالحًا، فلمَّا جاوَزُوا الفَصِيلَ أَحاطَ بهم الكرجُ من أَهلِ المدينةِ وقاتَلوهُم فأَكثَروا القَتْلَ فيهم، ولم يَتمَكَّن المسلمون من الهَزيمَةِ لِضِيقِ المَسْلَكِ، وخَرجَ الكَرجُ من البَلدِ وقَصَدوا العَسكرَ، واشتَدَّ القِتالُ، وكَبَّرَ المسلمون عليهم، فوَلَّوْا مُنهَزِمينَ، فدخلوا البلدَ والمسلمون معهم، ودَخلَها السُّلطانُ ومَلَكَها، واعتَصمَ جَماعةٌ من أَهلِها في بُرْجٍ من أَبراجِ المدينةِ، فقاتَلهُم المسلمون، فأَمَرَ السُّلطانُ بإلقاءِ الحَطَبِ حَولَ البُرجِ وإحراقِه، ففعل ذلك، وأَحرَق البُرجَ ومَن فيه، وعاد السُّلطانُ إلى خِيامِه، وغَنِمَ المسلمون من المدينةِ ما لا يُحَدُّ ولا يُحصَى، ولمَّا جَنَّ اللَّيلُ عَصَفَت رِيحٌ شَديدةٌ، وكان قد بَقِيَ من تلك النَّارِ التي أَحرَق بها البُرجَ بَقِيَّةٌ كَثيرةٌ، فأَطارَتها الرِّيحُ، فاحتَرقَت المَدينةُ بأَسْرِها، وذلك في رجب، ومَلَكَ السُّلطانُ قَلعةً حَصينةً كانت إلى جانبِ تلك المدينةِ، وأَخذَها، وسار منها إلى ناحيةِ قرس، ومدينة آني وبالقُربِ منها ناحيتان يُقال لهما: سيل ورده، ونورة، فخَرجَ أَهلُهما مُذعِنينَ بالإسلامِ، وخَرَّبوا البِيَعَ، وبَنوا المساجِدَ، وسار منها إلى مَدينةِ آني فوَصلَ إليها فرآها مَدينةً حَصينةً، شَديدةَ الامتِناعِ، لا تُرام، ثلاثةُ أَرباعِها على نَهرِ أرس، والرُّبعُ الآخرُ نَهْرٌ عَميقٌ شَديدُ الجَرْيَةِ، لو طُرِحَت فيه الحِجارةُ الكِبارُ لدَحاها وحَملَها، والطَّريقُ إليها على خَندقٍ عليه سُورٌ من الحِجارةِ الصُّمِّ، فحَصَرَها وضَيَّقَ عليها، إلا أنَّ المسلمين قد أَيِسُوا من فَتْحِها لِمَا رَأَوا من حَصانَتِها، فعَمِلَ السُّلطانُ بُرْجًا من خَشَبٍ، وشَحَنَهُ بالمُقاتِلَةِ، ورَماهُ بالنُّشَّابِ، ونَصَبَ عليه المِنْجَنيقَ، فكَشَفوا الرُّومَ عن السُّورِ، وتَقدَّم المسلمون إليه لِيَنقُبوهُ، فأَتاهُم مِن لُطْفِ الله ما لم يكُن في حِسابِهم، فانهَدَمت قِطعةٌ كَبيرةٌ من السُّورِ بغيرِ سَبَبٍ، فدَخَلوا المدينةَ وقَتَلوا من أَهلِها ما لا يُحصَى بحيث إنَّ كَثيرًا من المسلمين عَجَزوا عن دُخولِ البلدِ من كَثرةِ القَتلى، وأَسَروا نَحوًا مما قَتَلوا، وسارت البُشرَى بهذه الفُتوحِ في البلادِ، فسُرَّ المسلمون، وقُرِئ كِتابُ الفَتْحِ ببغداد في دارِ الخِلافةِ، ورَتَّبَ فيها السُّلطانُ أَميرًا في عَسكرٍ جَرَّارٍ، وعاد عنها، وقد راسَلهُ مَلِكُ الكرجِ في الهُدْنَةِ، فصالَحَهُ على أَداءِ الجِزْيَةِ كلَّ سَنَةٍ، فقَبِلَ ذلك."},{"id":1596,"title":"النورمانديون يَذبَحون المسلمينَ في مَدينةِ ببشتر الأَندلُسِيَّة  .","date":["العام الهجري :456","العام الميلادي :1063"],"text":"قام جيوم دي مونري النورماندي بقِيادَةِ حَملَةٍ بَحرِيَّةٍ نَزلَت بِساحلِ قطلونية ثم سارت إلى الشَّرْقِ حتى وَصلَت إلى مَدينةِ ببشتر جنوب إسبانيا وكانت من أَعمالِ يُوسفَ بن سُليمانَ بن هود فحاصَروها حتى استَسلَمت فدَخَلها وأَمْعَنَ جُنْدُهُ في أَهلِها قَتْلًا ونَهْبًا وسَبْيًا، ولم يُبادِر أَحدٌ من أُمراءِ الطَّوائفِ بِنَجْدَتِه، ثم غادَرَ النورمانديون المدينةَ بعدَ أن تَركوا فيها حامِيةً من خَمسةِ آلافِ رَجُلٍ، حتى قام في السَّنَةِ التاليةِ أحمدُ بن سُليمانَ بن هود باستِنهاضِ هِمَمِ المسلمين وخَلَّصَ المدينةَ من الحامِيَةِ وتَلَقَّبَ بعدَها بالمُقتَدِر بالله."},{"id":1597,"title":"الحربُ بين ألب أرسلان وقُتلمش .","date":["العام الهجري :456","الشهر القمري : محرم","العام الميلادي :1064"],"text":"سَمِعَ ألب أرسلان أن شهابَ الدَّولةِ قُتلمش السلجوقي، قد عَصَى عليه، وجَمعَ جُموعًا كَثيرةً، وقَصدَ الرَّيَّ ليَستَولي عليها، فجَهَّزَ ألب أرسلان جَيشًا عَظيمًا وسَيَّرَهُم على المَفازَةِ إلى الرَّيِّ، فسَبَقوا قُتلمش إليها، وسار ألب أرسلان من نيسابور أَوَّلَ المُحرَّم من هذه السَّنَةِ، فلمَّا وَصلَ إلى دامغان أَرسَل إلى قُتلمش يُنكِر عليه فِعلَه، ويَنهاهُ عن ارتكابِ هذا الحالِ، ويَأمرُه بِتَركِها، فإنَّه يَرعَى له القَرابةَ والرَّحِمَ، فأجابَ قُتلمش جوابَ مُغْتَرٍّ بمَن معه مِن الجُموعِ، ونَهَبَ قُرَى الرَّيِّ، وأَجرَى الماءَ على وادي المِلْحِ، وهي سَبِخَةٌ، فتَعَذَّرَ سُلوكُها، وقَرُبَ السُّلطانُ من قُتلمش، فلَبِسَ المَلِكُ السِّلاحَ، وعَبَّأَ الكتائِبَ، واصطَفَّ العَسكرانِ فقَصدَ قُتلمش المحاجزة، وجَعلَ السَّبِخَة بينه وبين ألب أرسلان لِيَمتَنِعَ من اللِّقاءِ, فسَلكَ ألب أرسلان طَريقًا في الماءِ، وخاضَ غَمْرَتَهُ، وتَبِعَهُ العَسكرُ، فطَلَعَ منه سالِمًا هو وعَسكرُه، فصاروا مع قُتلمش واقتَتَلوا، فلم يَثبُت عَسكرُ قُتلمش لِعَسكرِ السُّلطانِ، وانهَزَموا لِساعَتِهم، ومَضَى مُنهَزِمًا إلى قَلعةِ كردكوه، وهي مِن جُملةِ حُصونِه ومَعاقِلِه، وكَثُرَ القَتلُ والأَسْرُ في عَسكرِه، وأراد السُّلطانُ قَتلَ الأَسْرَى، فشَفَعَ فيهم نِظامُ المُلْكِ فعَفَا عنهم وأَطلقَهم، ولمَّا سَكَنَ الغُبارُ، ونَزلَ العَسكرُ، وُجِدَ قُتلمش مَيِّتًا مُلقًى على الأرضِ لا يُدرَى كيف كان مَوتُه، قيلَ: إنَّه مات من الخَوفِ، والله أَعلمُ، فبَكَى السُّلطانُ لِمَوتِه، وقَعَدَ لِعَزائِه، وعَظُمَ عليه فَقْدُهُ، فسَلَّاهُ نِظامُ المُلْكِ، ودَخلَ ألب أرسلان إلى مدينة الرَّيِّ آخرَ المُحرَّم من السَّنَةِ."},{"id":1598,"title":"وَفاةُ الإمامِ ابنِ حَزْمٍ الظاهري الأَندلُسي القُرطُبي .","date":["العام الهجري :456","الشهر القمري : شعبان","العام الميلادي :1064"],"text":"هو الإمامُ الأَوحدُ، البَحرُ، ذو الفُنونِ والمَعارِف، العَلَّامَةُ أبو مُحمدٍ عليُّ بن أحمدَ بن سَعيدِ بن حَزْمِ بن غالبِ بن صالحِ بن خَلَفِ بن معد بن سُفيانَ بن يَزيدَ (مَولى يَزيدَ بن أبي سُفيانَ) الأُمَويُّ الفَقيهُ الحافظُ، المُتَكَلِّمُ، الأَديبُ، الوَزيرُ، الظَّاهريُّ، صاحبُ التَّصانيفِ. أَصلُ جَدِّهِ يَزيدَ من فارس، وهو أَوَّلُ مَن أَسلَم من أَجدادِه، وجَدُّهُ خَلَفٌ أَوَّلُ مَن دَخَلَ بِلادَ المَغرِب من آبائهِ زَمنَ عبدِالرحمن الدَّاخِل، وكانت بَلدُهم قُرطبةَ، ووُلِدَ ابنُ حَزمٍ بها في رمضان، سنة 384هـ، وكان والِدُه من كُبَراءِ أَهلِ قُرطُبة؛ عَمِلَ في الوِزارةِ للدَّولةِ العامِريَّة، فنَشأَ ابنُ حَزمٍ في تَنَعُّمٍ ورَفاهِيَةٍ، ورُزِقَ ذَكاءً مُفرِطًا، وذِهْنًا سَيَّالًا. فقَرأَ القُرآنَ واشتَغَلَ بالعُلومِ النَّافِعَةِ الشَّرعيَّةِ، وبَرَزَ فيها وَفاقَ أَهلَ زَمانِه. كان حافِظًا عالِمًا بعُلومِ الحَديثِ وفِقْهِهِ، مُستَنبِطًا للأَحكامِ من الكِتابِ والسُّنَّةِ بعدَ أن كان شافِعيَّ المَذهبِ، انتَقلَ إلى مَذهبِ أَهلِ الظَّاهرِ، وكان مُتَفَنِّنًا في عُلومٍ جَمَّةٍ، عامِلًا بِعِلمِه، زاهِدًا في الدُّنيا بعدَ الرِّياسَةِ التي كانت له ولأَبيهِ مِن قَبلِه في الوزارةِ وتَدبيرِ المَمالِكِ، مُتواضِعًا ذا فَضائلَ جَمَّةٍ. قال الذَّهبيُّ: \"كان قد مَهَرَ أوَّلًا في الأَدبِ والأَخبارِ والشِّعْرِ، وفي المَنطِقِ وأَجزاءِ الفَلسفَةِ، فأَثَّرَت فيه تَأثيرًا لَيْتَهُ سَلِمَ من ذلك، ولقد وَقفتُ له على تَأليفٍ يَحُضُّ فيه على الاعتِناءِ بالمَنطِقِ، ويُقَدِّمُه على العُلومِ، فتَألَّمتُ له، فإنَّه رَأسٌ في عُلومِ الإسلامِ، مُتَبَحِّرٌ في النَّقْلِ، عَديمُ النَّظيرِ على يُبْسٍ فيه، وفَرْطِ ظاهِريَّةٍ في الفُروعِ لا الأُصولِ\". وله تَصانيفُ وكُتُبٌ مَشهورةٌ كَثيرةٌ أَهَمُّها ((المُحَلَّى))، و((الفَصلُ في المِلَل والنِّحَل)).  ويُقال: إنَّه صَنَّفَ أربعمائةَ مُجَلَّدٍ في قَريبٍ من ثمانين ألف وَرَقَةٍ. وكان أَديبًا طَبيبًا شاعِرًا فَصيحًا، له في الطِبِّ والمَنطِقِ كُتُبٌ، كان مُصاحِبًا للشَيخِ أبي عُمرَ بن عبدِ البَرِّ النمري، ومُناوِئًا للشيخِ أبي الوليدِ سُليمانَ بن خَلفٍ الباجيِّ، وقد جَرَت بينهما مُناظراتٌ كَثيرةٌ، وكان ابنُ حَزمٍ كَثيرَ الوَقيعةِ في العُلماءِ بِلِسانِه وقَلَمِه لا يَكادُ يَسلَمُ أَحَدٌ من لِسانِه من العُلماءِ المُتقَدِّمين والمُتأخِّرين، حتى قيلَ: \"كان لِسانُ ابنِ حَزمٍ وسَيفُ الحَجَّاجِ بن يوسفَ شَقِيقَينِ, لكَثرةِ وُقوعِه في الأئمةِ\" فنَفَرَت عنه القُلوبُ،، فتَمالَأَ العُلماءُ على بُغضِه ورَدُّوا قَولَه واجمَعوا على تَضليلِه وشَنَّعُوا عليه, وحَذَّروا السَّلاطِينَ من فِتنَتهِ, ونَهوا عَوامَّهُم عن الدُّنُوِّ إليه والأَخذِ منه, فأَورَثَهُ ذلك حِقدًا في قُلوبِ أَهلِ زَمانِه، وما زالوا به حتى بَغَّضوهُ إلى مُلوكِهم، فطَردوهُ عن بلادِه حتى تَشَرَّدَ في الباديةِ ومع ذلك لم يرجِع عن أَقوالِه وأَفعالِه. كان ظاهِريًّا لا يقولُ بشيءٍ من القِياسِ لا الجَلِيِّ ولا غَيرِه، وهذا الذي وَضَعهُ عند العُلماءِ، وأَدخَلَ عليه خَطأً كَبيرًا في نَظَرِه وتَصرُّفِه وكان مع هذا مِن أَشَدِّ الناسِ تَأويلًا في باب الأُصولِ، وآياتِ الصِّفاتِ وأحاديثِ الصِّفاتِ، لأنَّه كان أَوَّلًا قد تَضَلَّع من عِلْمِ المَنطِق، أَخذَهُ عن محمدِ بن الحسنِ المُذحجيِّ الكِناني القُرطُبي، ففَسَدَ بذلك حالُه في بابِ الصِّفاتِ، قال الذَّهبيُّ: \"قيلَ: إنَّه تَفَقَّهَ أوَّلًا للشافعيِّ، ثم أَدَّاهُ اجتِهادُه إلى القَوْلِ بنَفْيِ القِياسِ كُلِّهِ جَلِيِّهِ وخَفِيِّهِ، والأَخْذِ بظاهرِ النَّصِّ وعُمومِ الكتابِ والحديثِ، والقَولِ بالبَراءةِ الأصليَّة، واستِصحابِ الحالِ، وصَنَّفَ في ذلك كُتُبًا كَثيرةً، وناظَرَ عليه، وبَسَطَ لِسانَه وقَلَمَه، ولم يَتأَدَّب مع الأئمةِ في الخِطابِ، بل فَجَّجَ العِبارةَ، وسَبَّ وجَدَّعَ، فكان جَزاؤُه من جِنْسِ فِعْلِه، بحيث إنَّه أَعرَض عن تَصانيفِه جَماعةٌ من الأئمةِ، وهَجرُوها، ونَفَروا منها، وأُحرِقَت في وَقتٍ، واعتَنَى بها آخرون من العُلماءِ، وفَتَّشُوها انتِقادًا واستِفادةً، وأَخْذًا ومُؤاخَذةً، ورَأوا فيها الدُّرَّ الثَّمينَ مَمْزوجًا في الرَّصْفِ بالخَرزِ المهينِ، فتارةً يطربون، ومَرَّةً يعجبون، ومِن تَفَرُّدِه يَهزَؤون. وفي الجُملةِ فالكمالُ عَزيزٌ، وكلُّ أَحَدٍ يُؤخذُ من قَولِه ويُتركُ، إلَّا رَسولَ الله صلَّى الله عليه وسلَّم, وكان يَنهضُ بِعُلومٍ جَمَّةٍ، ويُجيدُ النَّقْلِ، ويُحسِن النَّظْمَ والنَثْرَ. وفيه دِينٌ وخَيْرٌ، ومَقاصِدُه جَميلةٌ، ومُصنَّفاتُه مُفيدةٌ، وقد زَهِدَ في الرِّئاسَةِ، ولَزِمَ مَنزِلَه مُكِبًّا على العِلْمِ، فلا نَغلُو فيه، ولا نَجفُو عنه، وقد أَثنَى عليه قَبلَنا الكِبارُ. قال أبو حامد الغزالي: \"وجدتُ في أَسماءِ الله تعالى كِتابًا أَلَّفَهُ ابنُ حَزمٍ يَدُلُّ على عِظَمِ حِفظِه وسَيَلانِ ذِهْنِهِ\". وقال الإمامُ أبو القاسمِ صاعدُ بن أحمدَ: \"كان ابنُ حَزمٍ أَجْمَعَ أَهلِ الأندَلُسِ قاطِبةً لِعُلومِ الإسلامِ، وأَوْسَعَهُم مَعرِفَةً مع تَوَسُّعِهِ في عِلْمِ اللِّسانِ، ووُفورِ حَظِّهِ من البَلاغةِ والشِّعْرِ، والمَعرِفَةِ بالسِّيَرِ والأَخبارِ\". قال الحافظُ أبو عبدِ الله محمدُ بن فتوح الحُميدي: \"ما رأينا مِثلَه فيما اجتَمَع له من الذَّكاءِ وسُرعَةِ الحِفظِ وكَرَمِ النَّفْسِ والتَّدَيُّنِ، وما رأيتُ مَن يقولُ الشِّعْرَ على البَديهةِ أَسرعَ منه\". قال أبو القاسمِ صاعدٌ: \"كان أَبوهُ مِن وُزَراءِ المَنصورِ محمدِ بن أبي عامرٍ، ثم وَزَرَ للمُظَفَّرِ، ووَزَرَ أبو محمدٍ للمُسْتَظْهِر عبدِ الرحمن بن هشامٍ، ثم نَبَذَ هذه الطَّريقَة، وأَقبلَ على العُلومِ الشَّرعيَّة، وعَنِيَ بِعِلْمِ المَنطِقِ وبَرَعَ فيه، ثم أَعرَض عنه\". قُلتُ (الذهبي): \"ما أَعرَض عنه حتى زَرَعَ في باطِنِه أُمورًا وانحِرافًا عن السُّنَّةِ\". وقد حَطَّ أبو بكر بن العربي على أبي محمدٍ وعلى الظاهريَّةِ في كِتابِ القَواصِم والعَواصِم، فقال: \"هي أُمَّةٌ سَخِيفةٌ، تَسَوَّرَت على مَرتَبةٍ ليست لها، وتَكلَّمَت بكَلامٍ لم نَفهَمهُ\". قلتُ (الذهبي): \"لم يُنصِف القاضي أبو بكرٍ شَيْخَ أَبيهِ في العِلْمِ، ولا تَكلَّم فيه بالقِسْطِ، وبالَغَ في الاستِخفافِ به، وأبو بكرٍ فعَلَى عَظَمَتِه في العِلْمِ لا يَبلُغ رُتْبَةَ أبي محمدٍ، ولا يَكادُ، فرَحِمَهُما الله وغَفَرَ لهُما\". ثم قال (الذهبي): \"وَلِي أنا مَيْلٌ إلى أبي محمدٍ لِمَحَبَّتِهِ في الحَديثِ الصَّحيحِ، ومَعرِفَتِه به، وإن كنتُ لا أُوافِقُه في كَثيرٍ مما يَقولُه في الرِّجالِ والعِلَلِ، والمَسائِلِ البَشِعَةِ في الأُصولِ والفُروعِ، وأَقطعُ بخَطَئِه في غيرِ ما مَسألةٍ، ولكن لا أُكَفِّرُه، ولا أُضَلِّلُه، وأرجو له العَفْوَ والمُسامَحةَ وللمسلمين. وأَخضَعُ لِفَرْطِ ذَكائِه وسِعَةِ عُلومِه، ورَأيتُه قد ذَكَرَ – أي ابن حزم- قولَ مَن يقول: أَجَلُّ المُصنَّفاتِ (المُوطَّأ). فقال: بل أولى الكُتُبِ بالتَّعظيمِ (صَحيحا) البُخاريِّ ومُسلمٍ\" وكانت وَفاتُه شَريدًا في البادِيَةِ بعدَ أن أَقْصَتْهُ المُلوكُ وشَرَّدَتْهُ عن بِلادِه حتى انتهى إلى بادِيَةِ لبلة فتُوفِّي بها آخرَ نهارِ الأحدِ للَيلتينِ بَقِيَتا من شعبان، وقيلَ: إنَّه تُوفِّي في منت ليشم، وهي قَريةٌ له، وقد جاوَزَ التِّسعين."},{"id":1599,"title":"وَفاةُ الوَزيرِ عَميدِ المُلْكِ الكندريِّ .","date":["العام الهجري :456","الشهر القمري : ذي الحجة","العام الميلادي :1064"],"text":"الوَزيرُ عَميدُ المُلْكِ، أبو نَصرٍ محمدُ بن منصورِ بن محمدٍ الكندريُّ، وَزيرُ السُّلطانِ طُغرلبك. كان أَحَدَ رِجالِ الدَّهرِ شَهامةً وكتابةً وكَرَمًا. وُلِدَ سنة 415هـ بقَريةِ كندر في نيسابور. تَفَقَّهَ لأبي حنيفةَ، وتَأَدَّبَ، ثم صَحِبَ رَئيسًا بنيسابور، فاستَخدَمهُ في ضِياعِه، ثم استَنابَهُ عنه في خِدمَةِ السُّلطانِ طُغرلبك، فطَلَبَه منه، فوَصَل في خِدمَتِه، وصار صاحِبَ خِبْرَةٍ. ثم وَلَّاهُ خوارزم، وعَظُمَ جاهُهُ. وعَصَى بخوارزم، ثم ظَفَرَ به السُّلطانُ، ونَقَمَ عليه أنَّه تَزَوَّج امرأةَ مَلِكِ خوارزم فخَصاهُ, ثم رَقَّ له فدَاوَاهُ وعُوفِيَ, واستَوْزَرهُ وله إحدى وثلاثون سنةً, فقَدِمَ بغداد، وأقامَ بها مُدَّةً، ولَقَّبَهُ الخليفةُ بسَيِّدِ الوُزراءِ, ونالَ من الجاهِ والحُرْمَةِ ما لم يَنَلْهُ أَحَدٌ. قال الذهبيُّ: \"كان كَريمًا جَوادًا، مُتَعَصِّبًا لِمَذهَبِه، مُعتَزِليًّا، مُتكَلِّمًا له النَّظْمُ والنَّثْرُ\". قال ابنُ الأثيرِ: \"كان شديدَ التَّعَصُّبِ على الشافعيَّةِ، كَثيرَ الوَقيعَةِ في الشافعيِّ رضي الله عنه، بَلَغَ مِن تَعَصُّبِه أنه خاطَبَ السُّلطانِ في لَعْنِ الرَّافِضَةِ على مَنابر خُراسان، فأَذِنَ في ذلك، فأَمَرَ بِلَعْنِهِم، وأَضافَ إليهم الأَشعريَّة، فأَنِفَ من ذلك أَئمَّةُ خُراسان، منهم الإمام أبو القاسم القشيري، والإمام أبو المعالي الجويني، وغيرُهما، ففارقوا خُراسان، وأقامَ إمامُ الحَرمينِ بمَكَّةَ أربعَ سنين إلى أن انقَضَت دَولتُه، فلما جاء الوزيرُ نِظامُ المُلكِ، أَحضرَ مَن انتَزحَ منهم وأَكرَمَهم، وأَحسنَ إليهم, وقيلَ: إن الكندريَّ تابَ مِن الوَقيعةِ في الشافعيِّ، فإن صَحَّ فقد أَفلحَ، وإلَّا فَعَلَى نَفسِها براقش تَجنِي\" في هذه السَّنَةِ قَبَضَ عليه ألب أرسلان، وسَجنَهُ ببَيتِه ثم أرسل إليه مَن قَتَلهُ. قُتِلَ بمروالروذ في ذي الحجَّةِ. وكان قد قُطِعَت مَذاكِرُه ودُفِنَت بخوارزم، فلمَّا قُتِلَ حُمِلَ رَأسُه إلى نيسابور. ولهذا قال ابنُ الأثير: \"ومِن العَجَبِ أن ذَكَرَهُ دُفِنَ بخوارزم لمَّا خُصِيَ، ودَمُهُ مَسفوحٌ بمرو، وجَسَدُه مَدفونٌ بكندر، ورَأسُه مَدفونٌ بنيسابور، فاعتَبِروا يا أولي الأبصار\"."},{"id":1600,"title":"الحَربُ بين بني حَمَّادٍ والعَربِ في أفريقية .","date":["العام الهجري :457","العام الميلادي :1064"],"text":"كانت حَرْبٌ بين الناصرِ بن علناس بن حمَّادٍ ومَن معه مِن رِجالِ المَغارِبَةِ مِن صنهاجة ومِن زناتة ومِن العَربِ: عَدِيّ والأَثبَج، وبين رِياحٍ، وزُغْبَة، وسُلَيم، ومع هؤلاء المُعِزُّ بن زيري الزناتي، على مَدينةِ سَبتَة، ولمَّا رَحلَ المُعِزُّ من القيروان وصبرة إلى المَهدِيَّة تَمكَّنَت العَربُ، ونَهبَت النَّاسَ، وخَرَّبَت البِلادَ، فانتَقلَ كَثيرٌ مِن أَهلِها إلى بِلادِ بني حمَّاد لِكَونِها جِبالًا وَعْرَةً يُمكِن الامتِناعُ بها من العَربِ، فعُمِّرَت بِلادُهم، وكَثُرَت أَموالُهم، وفي نُفوسِهم الضَّغائِنُ والحُقودُ مِن باديس، ومَن بَعدَه مِن أَولادِهم، يَرِثُه صَغيرٌ عن كَبيرٍ، ووَلِيَ تَميمُ بنُ المُعِزِّ بعدَ أَبيهِ، فاستَبدَّ كلُّ مَن هو ببَلدٍ وقَلعةٍ بمَكانِه، وتَميمٌ صابرٌ يُدارِي ويَتَجَلَّد، واتَّصلَ بتَميمٍ أن الناصرَ بنَ علناس يَقَعُ فيه في مَجلسِه ويَذُمُّهُ، وأنَّه عَزَمَ على المَسيرِ إليه لِيُحاصِرَهُ بالمَهديَّة. وأنَّه قد حالَفَ بعضَ صنهاجة، وزناتة، وبني هلال؛ لِيُعينُوهُ على حِصارِ المَهديَّة. فلمَّا صَحَّ ذلك عنده أَرسلَ إلى أُمراءِ بني رِياحٍ، فحينئذٍ رَحلَت رِياحٌ وزناتة جَميعُها، وسار إليهم الناصرُ بصنهاجة، وزناتة، وبني هلال، فالتَقَت العَساكرُ بمَدينةِ سَبْتَة، فحَمَلَت رِياحٌ على بني هِلالٍ، وحَمَلَ ابنُ المُعِزِّ على زناتة، فانهَزَمت الطائفتانِ، وتَبِعَهُم عَساكرُ الناصرِ مُنهزِمينَ، ووَقعَ فيهم القَتْلُ، فقُتِلَ فيمَن قُتِلَ القاسمُ بن علناس، أخو الناصرِ في نَفَرٍ يَسيرٍ، وغَنِمَت العَرَبُ جَميعَ ما كان في العَسكرِ مِن مالٍ وسِلاحٍ ودَوابٍّ وغيرِ ذلك، فاقتَسموها على ما استَقرَّ بينهم، وبهذهِ الوَقعَةِ تَمَّ للعَربِ مُلْكُ البِلادِ، وأَرسَلوا الأَلوِيَةَ والطُّبولَ وخِيَمَ النَّاصرِ بِدَوابِّها إلى تَميمٍ، فرَدَّها وقال: يَقْبُحُ بي أن آخُذَ سَلَبَ ابنِ عَمِّي! فأَرْضَى العَربَ بذلك."},{"id":1601,"title":"الإعلانُ عن سَبِّ الصَّحابَةِ وإظهارُ البِدَعِ في الكرخِ .","date":["العام الهجري :458","العام الميلادي :1065"],"text":"في يومِ عاشُوراءَ أَغلَقَ الشِّيعةُ مِن أَهلِ الكَرخِ دَكاكِينَهم، وأَحضَرُوا نِساءً يَنُحْنَ على الحُسينِ، كما جَرَت به بِدعَتُهم، فحين وَقعَ ذلك أَنكرَتهُ العامَّةُ، وطَلبَ الخَليفةُ أبا الغَنائمِ ابن المحلبان وأَنكرَ عليه ذلك، فاعتَذرَ إليه بأنَّه لم يَعلَم به، وأنَّه حين عَلِمَ أَزالَهُ، وتَردَّدَ أَهلُ الكرخِ إلى الديوانِ يَعتَذِرون من ذلك، وخَرجَ التَّوقيعُ بِكُفْرِ مَن سَبَّ الصَّحابةَ وأَظهرَ البِدَعَ."},{"id":1602,"title":"حُدوثُ زِلزالٍ عَظيمٍ بخُراسان .","date":["العام الهجري :458","العام الميلادي :1065"],"text":"حَدثَ بخُراسان زَلزلةٌ مَكثَت أيَّامًا، تَصدَّعَت منها الجِبالُ، وهَلكَ جَماعةٌ، وخُسِفَ بعِدَّةِ قُرى، وخَرجَ الناسُ إلى الصحراءِ وأقاموا هنالك، ووَقعَ حَريقٌ بنهر معلى فاحتَرقَ مائةُ دُكَّانٍ وثلاثةُ دُورٍ، وذهبَ للناس شيءٌ كَثيرٌ، ونَهبَ بَعضُهم بَعضًا."},{"id":1603,"title":"ألب أرسلان يأخذ ولاية العَهْدَ لابنِه ملكشاه من بعده .","date":["العام الهجري :458","العام الميلادي :1065"],"text":"سار ألب أرسلان من مرو إلى رايكان، فنَزلَ بظاهِرِها، ومعهُ جَماعةُ أُمراءِ دَولتِه، فأَخَذَ عليهم العُهودَ والمَواثِيقَ لِوَلَدِهِ ملكشاه بأنَّه السُّلطانُ بعدَه، وأَركبَه، ومشى بين يَديهِ يَحمِلُ الغاشيةَ، وخَلعَ السُّلطانُ على جَميعِ الأُمراءِ، وأَمرَهُم بالخُطبةِ له في جميعِ البلادِ التي يَحكُم عليها، ففعل ذلك، وأَقطَع البِلادَ، فأَقطَع مازندران للأَميرِ إينانج بيغو، وبلخ لأخيه سُليمان بن داود جغري بك، وخوارزم لأخيه أرسلان أرغو، ومرو لابنِه الآخر أرسلان شاه، وصغانيان وطخارستان لأخيه إلياس، ووِلايةَ بغشور ونواحيها لِمَسعودِ بن أرتاش، وهو من أَقاربِ السُّلطانِ، ووِلايةَ أسفرار لِمَوْدُودِ بن أرتاش."},{"id":1604,"title":"استِيلاءُ تَميمٍ صاحبِ إفريقية على القَيروان وقابس .","date":["العام الهجري :458","العام الميلادي :1065"],"text":"سَيَّرَ تَميمٌ، صاحبُ إفريقية، عَسكرًا كَثيفًا إلى مَدينةِ قابس، وبها أحمدُ بن خُراسان قد أَظهرَ عليه الخِلافُ، وسَببُ ذلك أنَّ المُعِزَّ بن باديس، أبا تَميمٍ، لمَّا فارَقَ القَيروانَ والمَنصوريَّةَ ورَحلَ إلى المَهديَّة، استَخلفَ على القَيروان وعلى قابس قائدَ بنَ مَيمونٍ الصنهاجيَّ، وأَقامَ بها ثلاثَ سنين، ثم غَلبَتهُ هوارةُ عليها، فسَلَّمَها إليهم وخَرجَ إلى المَهدِيَّة، فلمَّا وَلِيَ المُلْكَ تَميمُ بن المُعِزِّ بعدَ أَبيهِ رَدَّهُ إلى قائدِ بنِ ميمونٍ، وأَقامَ عليها، ثم أَظهرَ الخِلافُ على تَميمٍ والْتَجأَ إلى طَاعةِ الناصرِ بن علناس بن حمَّادٍ، فسَيَّرَ إليه تَميمٌ عَسكرًا كَثيرًا، فلمَّا سَمِعَ بهم قائدُ بن مَيمونٍ عَلِمَ أنَّه لا طَاقةَ له بهم، فتَركَ القَيروانَ وسار إلى الناصرِ، فدَخلَ عَسكرُ تَميمٍ القَيروانَ، وخَرَّبوا دُورَ قائدٍ، وسار العَسكرُ إلى قابس، وبها ابنُ خُراسان، فحَصَروهُ بها سَنةً وشَهرينِ، ثم أَطاعَ ابنُ خُراسان تَميمًا وصالَحهُ."},{"id":1605,"title":"وَفاةُ العالم اللُّغوِيِّ ابنِ سِيدَه .","date":["العام الهجري :458","الشهر القمري : ربيع الأول","العام الميلادي :1066"],"text":"هو إمامُ اللُّغةِ، أبو الحُسينِ عَلِيُّ بن إسماعيلَ المرسي نِسبةً إلى مَدينةِ مرسية في شَرقِ الأَندَلُس المُعروفُ بابنِ سِيدَه، وأَحَدُ مَن يُضرَب بِذَكائِه المَثَلُ. كان إمامًا حافِظًا في اللُّغةِ، وكان ضَريرَ البَصَرِ، أَخذَ عِلمَ العَربيَّةِ واللُّغةِ عن أَبيهِ، وكان أَبوهُ ضَريرًا أَيضًا، واشتَغلَ على أبي العَلاءِ صاعدٍ البغداديِّ، وله ((المُحكَم في لِسانِ العَربِ)) في مُجلَّداتٍ عَديدةٍ، وله ((شَرحُ الحَماسَةِ)) في سِتِّ مُجلَّداتٍ، وغيرُ ذلك، وقَرأَ على الشيخِ أبي عُمَرَ الطلمنكي كِتابَ ((الغريب)) لأبي عُبيدٍ سَرَدَها مِن حِفظِه، قال الطلمنكي: \"دَخلتُ مرسية فتَشَبَّثَ بي أَهلُها يَسمَعون عَلَيَّ \"غَريب المُصَنَّف\" فقلتُ لهم: انظُروا لي مَن يَقرأُ لكم وأُمسِكُ أنا كِتابي، فأَتوني برَجُلٍ أَعمَى يُعرَف بابنِ سِيدَه، فقَرأهُ عَليَّ مِن أَوَّلِه إلى آخرِهِ، فتَعجَّبتُ مِن حِفظِه\". وكان الشيخُ يُقابِل بما يَقرأُ في الكِتابِ، فسَمِعَ الناسُ بقِراءتِه مِن حِفظِه، فتَعجَّب الناسُ لذلك، وكان له في الشِّعْرِ حَظٌّ وتَصَرُّفٌ. قال اليسعُ بنُ حزمٍ: \"كان ابنُ سِيدَه شُعوبِيًّا يُفضِّل العَجَمَ على العَربِ\". قال الذهبيُّ: \"وحَطَّ عليه السّهيليُّ في ((الرَّوْض الأَنِف)) فقال: \"تَعَثَّر في ((المُحكَم)) وغَيرِه عَثراتٍ يَدْمَى منها الأَظَلّ، ويَدْحَضُ دَحَضاتٍ تُخرِجُه إلى سَبيلِ مَن ضَلّ، حتى إنَّه قال في الجِمارِ: هي التي تُرمَى بِعَرفَة. قلتُ (الذَّهبيُّ): هو حُجَّةٌ في نَقلِ اللُّغةِ، وله كِتابُ ((العالم في اللُّغةِ)) نحو مائة سِفْرٍ، بَدأَ بالفَلَكِ، وخَتَمَ بالذَّرَّةِ\" تُوفِّي وله سِتُّونَ سَنَةً ولم يَتَيَسَّر له الحَجُّ."},{"id":1606,"title":"وَفاةُ البَيهقيِّ صاحبِ السُّنَنِ .","date":["العام الهجري :458","الشهر القمري : جمادى الأولى","العام الميلادي :1066"],"text":"هو العَلَّامةُ، الثَّبْتُ، الفَقيهُ، شَيخُ الإسلامِ، أبو بكرٍ أَحمدُ بنُ الحُسينِ بن عَلِيِّ بن عبدِ اللهِ بن موسى البَيهقيُّ، الخسرو جردي الشافعيُّ الخُرسانيُّ الحافظُ الكَبيرُ المَشهورُ، المُحَدِّثُ الأُصوليُّ. وُلِدَ سَنةَ 384هـ. أَخَذَ الفِقهَ عن أبي الفَتحِ المروزيِّ، ثم غَلَبَ عليه الحَديثُ، واشتَهرَ به، وهو أوَّلُ مَن جَمعَ نُصوصَ الإمامِ الشافعيِّ في عَشرِ مُجلَّداتٍ. قال إمامُ الحَرمينِ في حَقِّهِ: \"ما من شافعيِّ المَذهبِ إلَّا وللشافعيُّ عليه مِنَّةٌ، إلَّا أحمدَ البيهقيَّ فإنَّ له على الشافعيِّ مِنَّةً، وكان مِن أَكثرِ الناسِ نَصرًا لِمَذهبِ الشافعيِّ\". كان له التَّصانيفُ التي سارَت بها الرُّكبانُ إلى سائرِ الأمصارِ، أَخذَ العِلمَ عن الحاكمِ أبي عبدِ الله النيسابوري، وسَمِعَ على غَيرِه شيئًا كَثيرًا، وجَمعَ أَشياء كَثيرةً نافعةً، لم يُسبَق إلى مِثلِها، ولا يُدرَك فيها، منها كتاب: ((السُّنَن الكبير))، و((السُّنَن الصغير))، و((مَعرِفَة السُّنَن والآثار))، و((المَدْخَل))، و((الآداب)) و((شُعَب الإيمان))، و((الخِلافِيَّات))، و((دَلائِل النُّبُوَّة))، و((البَعْث والنُّشُور))، وغيرُ ذلك من المُصَنَّفاتِ الكِبارِ والصِّغارِ المُفيدَةِ، وكان زاهدًا مُتقَلِّلًا من الدُّنيا، كَثيرَ العِبادَةِ والوَرَعِ. قال الحافظُ عبدُ الغافِر بن إسماعيل: \"كان البيهقيُّ على سِيرَةِ العُلماءِ، قانِعًا باليَسيرِ، مُتجَمِّلًا في زُهدِهِ ووَرَعِه, الفَقيهَ، الحافظَ الأُصوليَّ، الدَّيِّنَ الوَرِعَ، واحدَ زَمانِه في الحِفْظِ، وفَرْدَ أَقرانِه في الإتقانِ والضَّبْطِ، مِن كِبارِ أَصحابِ الحاكمِ، ويَزيدُ على الحاكمِ بأَنواعٍ مِن العُلومِ، كَتَبَ الحَديثَ، وحَفِظَهُ مِن صِباهُ، وتَفَقَّه وبَرَعَ، وأَخَذَ فَنَّ الأُصُولِ، وارتَحَلَ إلى العراقِ والجبالِ والحِجازِ، ثم صَنَّفَ، وتَواليفُه تُقارب ألفَ جُزءٍ مما لم يَسبِقهُ إليه أَحدٌ، جَمَعَ بين عَلْمِ الحديثِ والفِقْهِ، وبَيانِ عِلَلِ الحَديثِ، ووَجْهِ الجَمْعِ بين الأحاديثِ، طَلبَ منه الأئمَّةُ الانتقالِ من بَيهَق إلى نيسابور، لِسَماعِ الكُتُبِ، فأتى في سَنةِ 441هـ، وعَقَدوا له المَجلِسَ لِسَماعِ كِتابِ ((المعرفة)) وحَضَرهُ الأئمَّة\"  تُوفِّي بنيسابور، ونُقِلَ تابوتُه إلى بَيهَق."},{"id":1607,"title":"وَفاةُ القاضي أبي يَعلى الفَرَّاء شَيخِ الحَنابِلَة .","date":["العام الهجري :458","الشهر القمري : رمضان","العام الميلادي :1066"],"text":"هو الإمامُ، العلامةُ، شَيخُ الحنابلةِ، القاضي، أبو يَعلى محمدُ بن الحُسينِ بن محمدِ بن خَلَفِ بن أحمدَ البغداديُّ، الحَنبليُّ، ابنُ الفَرَّاءِ، وُلِدَ في مُحرَّم سنةَ 380هـ، صاحبُ التَّعليقَةِ الكُبرى، والتَّصانيفِ المُفيدةِ في المَذهَبِ, ومُمَهِّدُ مَذْهَبِهم في الفُروعِ، أَفْتَى ودَرسَ، وتَخَرَّجَ به الأصحابُ، وانتهت إليه الإمامةُ في الفِقْهِ، وكان عالِمَ العراقِ في زَمانهِ، مع مَعرفةٍ بعُلومِ القُرآنِ وتَفسيرِه، والنَّظَرِ والأُصولِ، وكان أبوه مِن أَعيانِ الحَنفيَّة، مات ولأبي يَعلَى عَشرةُ أَعوامٍ، فلَقَّنَهُ مُقرِئُه العِباداتِ مِن (مُختَصَر) الخِرَقِي، فلَذَّ له الفِقْهُ، وتَحوَّل إلى حَلَقَةِ أبي عبدِالله بن حامدٍ البغداديِّ الوَرَّاق، شَيخِ الحنابلةِ، فصَحِبَهُ أَعوامًا، وبَرعَ في الفِقهِ عنده، وتَصدَّر بأَمرِه للإفادةِ سنةَ 402هـ، قال ابنُ الجوزي: \"كان مِن ساداتِ العُلماءِ الثِّقاتِ، وشَهِدَ عند ابنِ ماكولا وابنِ الدَّامغاني فقَبِلَاهُ، وتَوَلَّى النَّظَرَ في الحُكمِ بِحَريمِ الخِلافةِ، وكان إمامًا في الفِقْهِ، له التَّصانيفُ الحِسانُ الكَثيرةُ في مَذهَبِ أحمد، ودَرَّسَ وأَفتَى سِنينَ، وانتهت إليه رِياسةُ المَذهبِ، وانتشرت تَصانيفُه وأَصحابُه، وجَمعَ الإمامةَ والفِقهَ والصِّدقَ، وحُسْنَ الخُلُقِ، والتَّعَبُّدَ والتَّقَشُّفَ والخُشوعَ، وحُسْنَ السَّمْتِ، والصَّمْتَ عمَّا لا يَعْنِي. اتَّهَمَهُ بعضُهم بالتَّجسيمِ بسَببِ كِتابهِ ((الصِّفات))، وله مِن المُصنَّفاتِ: ((الأحكام السُّلطانِيَّة)) و((الكِفاية في أُصولِ الفِقهِ)). قال الذهبيُّ: \"وَلِيَ أبو يَعلَى القَضاءَ بدارِ الخِلافةِ والحَريمِ، مع قَضاءِ حران وحلوان، وقد تَلَا بالقِراءاتِ العَشْرِ، وكان ذا عِبادةٍ وتَهَجُّدٍ، ومُلازَمَةٍ للتَّصنيفِ، مع الجَلالَةِ والمَهابَةِ، ولم تكن له يَدٌ طُولَى في مَعرفةِ الحَديثِ، فرُبَّما احتَجَّ بالواهي\". تُوفِّي في العشرين من رمضان عن ثَمانٍ وسبعين سَنةً، \"واجتَمَع في جَنازَتهِ القُضاةُ والأَعيانُ، وكان يومًا حارًّا، فأَفطَرَ بعضُ مَن اتَّبَعَ جَنازَتَه\""},{"id":1608,"title":"استِعادةُ ألب أرسلان سُلطَتِهِ على كرمان واصطخر .","date":["العام الهجري :459","العام الميلادي :1066"],"text":"عَصَى مَلِكُ كرمان، وهو \"قرا أرسلان\"، على السُّلطانِ ألب أرسلان، وسببُ ذلك أنَّه كان له وَزيرٌ جاهلٌ سَوَّلَت له نَفسُه الاستِبدادَ بالبِلادِ عن السُّلطانِ، وأن صاحِبَه إذا عَصَى احتاجَ إلى التَّمَسُّكِ به، فحَسُنَ لصاحِبِه الخِلافُ على السُّلطانِ، فأجابَ إلى ذلك، وخَلعَ الطَّاعةَ، وقَطعَ الخُطبةَ، فسَمِعَ ألبُ أرسلان، فسارَ إلى كرمان، فلمَّا قارَبَها وَقعَت طَليعَتُه على طَليعَةِ قرا أرسلان، فانهزمت طَليعَةُ قرا أرسلان بعدَ قِتالٍ، فلمَّا سَمِعَ قرا أرسلان وعَسكرُه بانهِزامِ طَليعَتِهم، خافوا وتَحَيَّرُوا، فانهَزَموا لا يَلوِي أَحدٌ على آخر، فدَخلَ قرا أرسلان إلى جيرفت وامتَنعَ بها، وأَرسلَ إلى السُّلطانِ ألب أرسلان يُظهِر الطَّاعةَ ويَسألُ العَفْوَ عن زَلَّتِه، فعَفَا عنه، وأَعادهُ إلى مَملَكتِه، ولم يُغَيِّر عليه شيئًا مِن حالِه، ثم سار منها إلى فارس فوَصلَ إلى إصطخر، وفَتحَ قَلعتَها، واستَنزلَ وَالِيَهَا، فحَملَ إليه الوالي هَدايا عَظيمةً جَليلةَ المِقدارِ، وأَطاعهُ جَميعُ حُصونِ فارس، وبَقِيَت قَلعةٌ يُقالُ لها: بهنزاد، فسار نِظامُ المُلْكِ إليها، وحَصرَها تحتَ جَبلِها، وأعطى كُلَّ مَن رَمَى بسَهمٍ وأصابَ قَبضةً مِن الدَّنانيرِ، ومَن رَمَى حَجرًا ثَوْبًا نَفيسًا، ففَتحَ القَلعةَ في اليومِ السادس عشر مِن نُزولِه، ووَصلَ السُّلطانُ إليه بعدَ الفَتحِ، فعَظُمَ مَحَلُّ نِظامِ المُلْكِ عِندَه، فأَعلَى مَنزِلَتَهُ، وزادَ في تَحكِيمِه."},{"id":1609,"title":"الانتهاءُ من بِناءِ المَدرسَةِ النِّظامِيَّة ببغداد وبَدءُ التَّدريسِ فيها .","date":["العام الهجري :459","الشهر القمري : ذي القعدة","العام الميلادي :1067"],"text":"كان الشُّروعُ ببِناءِ المَدرسَةِ النِّظامِيَّة نِسبةً إلى الوَزيرِ نِظامِ المُلْكِ، وَزيرِ ملكشاه في مَدينةِ بغداد، في ذي الحجَّةِ من عام 457هـ ونُقِضَ لأَجلِها دُورٌ كَثيرةٌ مِن مَشرعَةِ الزَّوايا وبابِ البَصرةِ، ثم في ذي القَعدةِ من سَنةِ 459هـ، فَرغَت عِمارةُ المَدرسَةِ النِّظامِيَّة، وتَقرَّر التَّدريسُ بها للشيخِ أبي إسحاقَ الشِّيرازيِّ الشافعيِّ، فجَمعَ العَميدُ أبو سعدٍ القاضي الناسَ على طَبقاتِهم إلى المَدرسةِ، وجَعَلَها بِرَسْمِ أبي إسحاقَ الشيرازيِّ الفيروزآبادي، صاحبِ كِتابِ ((التَّنْبيهُ)) في الفِقهِ على مَذهبِ الإمامِ الشافعيِّ بعدَ أن وَافَقَهُ على ذلك، فلمَّا كان يومُ اجتِماعِ الناسِ فيها وتَوقَّعوا مَجيءَ أبي إسحاقَ فلم يَحضُر، فطُلِبَ فلم يَظهَر، وكان السببُ أن شابًّا لَقِيَه فقال: يا سيدنا، تُريدُ تُدَرِّسُ في المدرسةِ؟ فقال: نعم. فقال: وكيف تُدَرِّسُ في مَكانٍ مَغصُوبٍ؟ فغَيَّرَ نِيَّتَه فلم يَحضُر، فلمَّا ارتَفعَ النَّهارُ، وأَيِسَ الناسُ مِن حُضورِه، أشارَ الشيخُ أبو منصورِ بن يُوسُف بأبي نَصرِ بن الصَّبَّاغِ، صاحبِ كتابِ ((الشامل))، وقال: لا يجوزُ أن يَنفَصِلَ هذا الجَمْعُ إلَّا عن مُدَرِّسٍ، ولم يَبقَ ببغداد مَن لم يَحضُر غيرَ الوَزيرِ، فجلسَ أبو نَصرٍ للدَّرْسِ، ثم ظَهرَ الشيخُ أبو إسحاقَ بعدَ ذلك، ولمَّا بَلغَ نِظامَ المُلْكِ الخَبَرُ أَقامَ القِيامةَ على العَميدِ أبي سعدٍ، ولم يَزَل يُرفِق بالشيخِ أبي إسحاقَ حتى دَرَّسَ بالمدرسةِ، وكانت مُدَّةُ تَدريسِ ابنِ الصَّبَّاغِ عشرين يومًا فقط. أَجرَى نِظامُ المُلْكِ للمُتَفَقِّهَةِ لِكلِّ واحدٍ أَربعةَ أَرطالِ خُبزٍ كلَّ يَومٍ, وقد أَشارَ ابنُ الجوزيِّ الى وَقْفِ هذه المدرسة ومُسْتَحِقِّيهِ بقَولِه: \"هذه المَدرسةُ وسُقوفُها المَوقُوفُ عليها، وفي كِتابِ شَرْطِها أنَّها وُقِفَت على أَصحابِ الشافعيِّ أَصلًا، وكذلك الأَملاكُ المَوقوفةُ عليها شَرطٌ فيها أن تكونَ على أَصحابِ الشافعيِّ أَصلًا، وكذلك شَرْطٌ في المُدَرِّسِ الذي يكون فيها، والواعِظِ الذي يَعِظُ فيها ومُتَوَلِّي الكُتُبِ, وشَرْطٌ أن يكونَ فيها مُقرئٌ يَقرأُ القُرآنَ، ونَحْوِيٌّ يُدَرِّس العَربيَّةَ، وفُرِضَ لِكلٍّ قِسْطٌ مِن الوَقْفِ\" ووَصفَها المَقرِيزيُّ بقَولِه: \"أَشهَرُ ما بُنِيَ في القَديمِ المَدرسةُ النِّظامِيَّة ببغداد، لأنَّها أوَّلُ مَدرسةٍ قُرِّرَ بها للفُقهاءِ مَعاليمُ – أي مِقدار مِن المالِ-\""},{"id":1610,"title":"وَفاةُ أبي جَعفرٍ الطُّوسيِّ فَقِيهِ الشِّيعَةِ .","date":["العام الهجري :460","الشهر القمري : محرم","العام الميلادي :1067"],"text":"هو شَيخُ الشِّيعةِ، وصاحِبُ التَّصانيفِ، أبو جَعفرٍ محمدُ بن الحسنِ بن عليٍّ الطُّوسيُّ، فَقيهُ الإِمامِيَّة وعالِمُهُم، انتَقلَ مِن خُراسان إلى بغداد وأقامَ فيها أربعين سَنةً، تَفَقَّهَ فيها أوَّلًا للشافعيِّ, ثم أَخذَ الكلامَ وأُصولَ الشِّيعةِ عن الشيخِ المُفيدِ رَأسِ الإماميَّةِ ولَزِمَهُ حتى تَحوَّل رافِضِيًّا، وعَمِلَ التَّفسيرَ، وأَملَى أحاديثَ ونَوادِرَ في مُجلَّدينِ، عامَّتُها عن شَيخِه المُفيدِ، ثم رَحلَ إلى النَّجفِ واستَقرَّ بها حتى تُوفِّي فيها، أُحرِقَت كُتبُه عِدَّةَ مَرَّاتٍ، له مِن التَّصانيفِ ((البيان الجامع لعلوم القرآن))، و((الاستبصار فيما اختُلِفَ فيه من الأخبار))، و((الاقتصاد في الاعتقاد))، وله أمالي وغيرُ ذلك، قال الذهبيُّ: \"أَعرضَ عنه الحُفَّاظُ لِبِدعَتِه، وقد أُحرِقَت كُتبُه عِدَّةَ نُوَبٍ في رَحْبَةِ جامعِ القَصْرِ، واستَتَر لمَّا ظَهَرَ عنه مِن التَّنَقُّصِ بالسَّلَفِ، وكان يَسكُن بالكرخِ، مَحَلَّةِ الرَّافِضَةِ، ثم تَحوَّل إلى الكوفةِ، وأقامَ بالمَشهَدِ يُفَقِّهُهم, وكان يُعَدُّ مِن الأذكياءِ لا الأزكياءِ\" تُوفِّي بمَشهدِ عليِّ بن أبي طالبٍ ودُفِنَ فيهِ، عن 75 عامًا."},{"id":1611,"title":"حُدوثُ زِلازلٍ بالمَدينةِ والرَّملةِ  .","date":["العام الهجري :460","الشهر القمري : جمادى الأولى","العام الميلادي :1068"],"text":"كانت زَلزلةٌ بأَرضِ فِلسطينَ، أَهلكَت بَلدَ الرَّملةِ، ورَمَت شَراريفَ -الشراريف ما يُوضَع في أَعلى البناء يحلَّى به- من مَسجدِ رَسولِ الله صلَّى الله عليه وسلَّم، ولَحِقَت وادي الصَّفْرَ وخَيبرَ، وانشَقَّت الأرضُ عن كُنوزٍ كَثيرةٍ مِن المالِ، وبَلغَ حِسُّها إلى الرَّحبةِ والكوفةِ، وجاء كِتابُ بَعضِ التُّجَّارِ فيه ذِكْرُ هذه الزَّلزلةِ، وذَكرَ فيه أنَّها خَسفَت الرَّملةَ جَميعًا حتى لم يَسلَم منها إلا داران فقط، وهَلكَ منها خمس عشرة ألف نَسَمةٍ، وغارَ البحرُ مَسيرةَ يَومٍ، وساخَ في الأرضِ وظَهرَ في مَكانِ الماءِ أشياءُ مِن جواهرَ وغَيرِها، ودَخلَ الناسُ في أَرضهِ يَلتَقِطُونَه، فرَجعَ عليهم فأَهلكَ كَثيرًا منهم."},{"id":1612,"title":"قِراءةُ الاعتِقادِ القادريِّ الذي فيه إِظهارُ السُّنَّةِ وإِنكار على أَهلِ البِدَعِ .","date":["العام الهجري :460","الشهر القمري : جمادى الآخرة","العام الميلادي :1068"],"text":"يومَ النِّصفِ من جُمادى الآخرة قُرِئَ الاعتقادُ القادريُّ الذي فيه مَذهبُ أَهلِ السُّنَّةِ والجَماعةِ، والإنكارُ على أَهلِ البِدَعِ، وقَرأَ أبو مُسلمٍ الكجيُّ البخاريُّ المُحَدِّثُ كِتابَ ((التَّوحيدِ)) لابنِ خُزيمةَ على الجَماعةِ الحاضرين، وذُكِرَ بمَحضرٍ مِن الوَزيرِ ابنِ جَهيرٍ وجَماعةِ الفُقهاءِ وأَهلِ الكَلامِ، واعتَرَفوا بالمُوافَقةِ، ثم قُرِئَ الاعتِقادُ القادريُّ على الشَّريفِ أبي جَعفرِ بن المُقتدِي بالله ببابِ البَصرةِ، وذلك لِسَماعِه له مِن مُصَنِّفِه الخَليفَةِ القادرِ بالله."},{"id":1613,"title":"وَفاةُ عبدِ المَلِكِ بن محمدٍ المُلَقَّبِ بالشَّيخِ الأَجَلِّ .","date":["العام الهجري :461","العام الميلادي :1068"],"text":"هو الصَّدرُ الأَنبلُ الرَّئيسُ القُدوةُ أبو منصورٍ عبدُ المَلِكِ بن محمدِ بن يُوسُفَ البغداديُّ، سِبْطُ الإمامِ أبي الحسينِ أحمدَ بن عبدِ الله السوسنجردي, وُلِدَ سنةَ 395هـ وكان يُلقَّب بالشَّيخِ الأَجَلِّ، كان أَوْحَدَ زَمانِه في الأمرِ بالمَعروفِ والنهيِ عن المُنكرِ، والمُبادَرةِ إلى فِعلِ الخَيراتِ، واصطِناعِ الأَيادي عند أَهلِها، مِن أَهلِ السُّنَّةِ، مع شِدَّةِ القِيامِ على أَهلِ البِدَعِ ولَعْنِهِم، قال الخَطيبُ البغداديُّ: كان أَوْحَدَ وَقتِه في فِعلِ الخَيرِ، وافتِقادِ المَستُورِينَ بالبِرِّ، ودَوامِ الصَّدقَةِ، والإفضالِ على أَهلِ العِلمِ، والقِيامِ بأُمورِهم والتَّحَمُّلِ لِمُؤَنِهِم، والاهتمامِ بما عادَ مِن مَصالِحِهم، والنُّصرَةِ لأَهلِ السُّنَّةِ، والقَمعِ لأَهلِ البِدَعِ\" تُوفِّي عن خمسٍ وسِتِّين سنةً، وكان يومُ مَوتِه يومًا مَشهودًا، حَضرَهُ خَلْقٌ لا يَعلمُ عَددَهم إلَّا الله عز وجل. قال أبي النرسي: \"لم أرَ خَلْقًا قَطُّ مِثلَ مَن حَضرَ جَنازَتَه\" دُفِنَ بمَقبَرَةِ بابِ حَربٍ إلى جَنْبِ جَدِّهِ لأُمِّهِ أبي الحُسينِ ابن السوسنجردي. قال الذهبيُّ: \"كان ذا جاهٍ عَريضٍ واتِّصالٍ بالخَليفَةِ, وأَرَّخَ له ابنُ خيرون، وقال: دُفِنَ عند جَدِّهِ لأُمِّهِ، وحَضرَهُ جَميعُ الأَعيانِ، وكان صالحًا، عَظيمَ الصَّدقَةِ، مُتعصِّبًا للسُّنَّةِ، قد كَفَى عامَّةَ العُلماءِ والصُّلَحاءِ\"."},{"id":1614,"title":"بَدْءُ ضَعفِ الحُكمِ العُبيديِّ الفاطِميِّ بمِصرَ .","date":["العام الهجري :461","العام الميلادي :1068"],"text":"بَدأَت الدَّولةُ الفاطِمِيَّةُ بمصر يُصيبُها الضَّعفُ بسَببِ عِدَّةِ أُمورٍ كان مِن أَهمِّها حُصولُ الشِّقاقِ بين التُّركِ والعَبيدِ، وحُصولُ الاقتِتالِ بينهم، وفي هذه السَّنَةِ خَرجَ ناصرُ الدولةِ بن حمدان من عند الوزيرِ أبي عبدِ الله الماشلي وَزيرِ المُستَنصِر بمصر فوَثبَ عليه رَجلٌ صَيْرَفِيٌّ وضَربَه بسِكِّينٍ؛ فأُمسِكَ الصَّيرفيُّ وشُنِقَ في الحالِ، وحُمِلَ ناصرُ الدولةِ بن حمدان إلى دارِه جَريحًا، فعُولِجَ فبَرِئَ بعدَ مُدَّةٍ. فقِيلَ: إن المُستَنصِر ووالدَتَهُ كانا دَسَّا الصَّيرفِيَّ عليه، وفي هذه الأيامِ اضمَحلَّ أَمرُ المُستَنصِر بالدِّيارِ المِصريَّة لِتَشاغُلِه باللَّهوِ والشُّربِ والطَّرَبِ. فلمَّا عُوفِيَ ابنُ حمدان اتَّفقَ مع مُقدَّمِي المَشارِقَة، مثل سنان الدولةِ وسُلطانِ الجُيوشِ وغَيرِهما، فرَكِبوا وحَصَروا القاهرةَ، فاستَنجدَ المُستَنصِر وأُمُّهُ بأَهلِ مصر، وذَكَّرَهم بحُقوقِه عليهم، ووَعدَهم بالإحسانِ؛ فقاموا معه ونَهَبوا دُورَ أَصحابِ ابن حمدان وقاتَلوهُم. فخاف ابنُ حمدان وأَصحابُه، ودَخَلوا تحتَ طاعةِ المُستَنصِر، بعدَ أُمورٍ كَثيرةٍ صَدرَت بين الفَريقَينِ."},{"id":1615,"title":"وَفاةُ المُعتَضِد بالله عَبَّادِ بن القاضي محمد مَلِكِ إشبيلية .","date":["العام الهجري :461","الشهر القمري : جمادى الآخرة","العام الميلادي :1069"],"text":"هو المُعتَضِدُ بالله أبو عَمرٍو عَبَّادُ بن الظَّافرِ المُؤَيَّدِ بالله أبي القاسمِ محمد قاضي إشبيلية بن أبي الوَليدِ إسماعيلَ بن قُريشِ بن عَبَّادِ بن عَمرِو بن أَسلمَ بن عَمرِو بن عَطَّافِ بن نُعيمٍ، اللخميُّ، مِن وَلَدِ النُّعمانِ بن المُنذِر اللخميِّ، آخر مُلوكِ الحِيرَةِ, لمَّا تُوفِّي محمدٌ القاضي سَنةَ 433هـ قامَ مَقامَه وَلَدُه عَبَّادٌ، قال أبو الحسنِ عليُّ بن بَسَّامٍ في حَقِّهِ: \" ثم أَفضَى الأَمرُ إلى عَبَّادٍ ابنِه سَنةَ ثلاثٍ وثلاثين, وتَسمَّى أَوَّلًا بِفَخرِ الدولةِ ثم المُعتَضِد، قُطْبُ رَحَى الفِتنَةِ، ومُنتَهى غايةِ المِحْنَةِ، مِن رَجُلٍ لم يَثبُت له قائمٌ ولا حَصيدٌ، ولا سَلَّمَ عليه قَريبٌ ولا بَعيدٌ، جَبَّارٌ، أَبرمَ الأُمورَ وهو مُتناقِض، وأسد فرس الطلى وهو رابض، مُتهَوِّرٌ تَتحاماهُ الدُّهاةُ، وجَبَّارٌ لا تَأمَنُه الكماو، مُتَعَسِّفٌ اهتدى، ومنبت قطع فما أَبقَى، ثارَ والناسُ حَرْبٌ، وكل شيءٍ عليه إلب، فكَفَى أَقرانَه وهُم غيرُ واحدٍ، وضبط شانه بين قائمٍ وقاعد، حتى طالت يَدُه، واتَّسعَ بَلدُه، وكَثُرَ عَديدُه وعَدَدُه؛ افتَتحَ أَمرَهُ بِقَتلِ وَزيرِ أَبيهِ حبيب المذكور، طَعنةً في ثَغرِ الأيامِ، مَلَكَ بها كَفَّهُ، وجَبَّارًا مِن جَبابِرَةِ الأنامِ، شُرِّدَ به مَن خَلْفَه، فاستمر يَفرِي ويُخلِق، وأَخَذَ يَجمَعُ ويُفَرِّق، له في كل ناحيةٍ مَيدان، وعلى كل رابِيَةٍ خُوان، حَرْبُه سُمٌّ لا يُبطِئ، وسَهْمٌ لا يُخطِئ، وسِلْمُه شَرٌّ غيرُ مَأمون، ومَتاعٌ إلى أدنى حين\". ولم يَزل المُعتَضِدُ في عِزِّ سُلطانِه واغتِنامِ مَسارِّهِ، حتى أَصابَتهُ عِلَّةُ الذَّبْحَة، فلم تَطُل مُدَّتُها، وتُوفِّي يومَ الاثنينِ غُرَّةَ جُمادى الآخرة، ودُفِنَ ثاني يوم بمَدينةِ إشبيلية، وقام بالمَملَكةِ بَعدَه وَلَدُه المُعتَمِدُ على الله أبو القاسمِ محمدٌ."},{"id":1616,"title":"احتِراقُ الجامعِ الأُمَويِّ بدِمَشق .","date":["العام الهجري :461","الشهر القمري : شعبان","العام الميلادي :1069"],"text":"في لَيلةِ النِّصفِ من شعبان كان حَريقُ جامعِ دِمشق، وكان سَببُه أنَّ غِلمانَ الفاطِميِّين والعَبَّاسِيِّين اختَصَموا فأُلقِيَت نارٌ بِدارِ المُلْكِ، وهي الخَضراءُ المُتاخِمَةِ للجامعِ مِن جِهَةِ القِبلَةِ، فاحتَرقَت، وسَرَى الحَريقُ إلى الجامعِ فسَقطَت سُقُوفُه وتَناثَرت فُصوصُه المُذَهَّبَةُ، وتَغيَّرَت مَعالِمُه، وتَقَلَّعَت الفُسَيْفِساءُ التي كانت في أَرضِه، وعلى جُدرانِه، وتَبدَّلَت بِضِدِّها، وقد كانت سُقوفُه مُذهَّبَةً كُلَّها، والجَمَلُونات مِن فَوقِها، وجُدرانُه مُذَهَّبَة مُلَوَّنَة مُصَوَّرٌ فيها جَميعُ بلادِ الدنيا، بحيث إنَّ الإنسانَ إذا أراد أن يَتَفرَّج في إقليمٍ أو بَلدٍ وَجدَه في الجامعِ مُصَوَّرًا كهَيئَتِه، فلا يُسافِر إليه ولا يُعنَى في طَلَبِه، فقد وَجدَهُ من قرب الكعبة ومكة فوق المحراب والبلاد كلها شَرقًا وغَربًا، كلُّ إقليمٍ في مكانٍ لائقٍ به، ومُصَوَّر فيه كل شَجرةٍ مُثمِرةٍ وغيرِ مُثمِرة، مصور مشكل في بُلدانِه وأَوطانِه، والسُّتورُ مُرخاةٌ على أَبوابِه النافذةِ إلى الصَّحْنِ، وعلى أُصولِ الحِيطانِ إلى مِقدارِ الثُّلُثِ منها سُتورٌ، وباقي الجُدرانِ بالفُصوصِ المُلوَّنَة، وأَرضُه كُلُّها بالفُصوصِ، ليس فيها بَلاطٌ، بحيث إنَّه لم يكن في الدنيا بِناءٌ أَحسنَ منه، لا قُصورَ المُلوكِ ولا غَيرَها، ثم لمَّا وَقعَ هذا الحَريقُ فيه تَبدَّلَ الحالُ الكاملُ بِضِدِّهِ، وصارت أَرضُه طِينًا في زَمنِ الشِّتاءِ، وغُبارًا في زَمنِ الصَّيفِ، مَحفورةً مَهجورةً، ولم يَزَل كذلك حتى بُلِّطَ في زَمنِ المَلِكِ العادلِ بن أيوبَ، أخي صَلاحِ الدين الأيوبي."},{"id":1617,"title":"تَوَجُّهُ مَلِكِ الرُّومِ مِن القُسطنطينيَّة إلى الشام ونُزولُه مدينة منبج .","date":["العام الهجري :462","العام الميلادي :1069"],"text":"أَقبلَ مَلِكُ الرُّومِ مِن القُسطنطينِيَّة في عَسكرٍ كَثيفٍ إلى الشامِ، ونَزلَ على مَدينةِ منبج بسوريا ونَهبَها وقَتلَ أَهلَها، وهَزمَ محمودَ بن صالحِ بن مرداس، وبني كِلابٍ، وابنَ حسَّان الطائيَّ، ومَن معهما مِن جُموعِ العَربِ، ثم إنَّ مَلِكَ الرُّومِ ارتَحلَ وعادَ إلى بِلادِه، ولم يُمكِنهُ المَقامُ لِشِدَّةِ الجُوعِ."},{"id":1618,"title":"وَفاةُ أبي بكرٍ اللَّمْتوني مُؤَسِّس دَولةِ المُرابطين .","date":["العام الهجري :462","العام الميلادي :1069"],"text":"أبو بكرِ بن عُمرَ بن تكلاكين اللَّمتوني، أَميرُ المُلَثَّمِين، وهو ابنُ عَمِّ يُوسفَ بنِ تاشفين أَميرِ المُرابطين، كان في أَرضِ فرغانة، خَلَفَ أَخاهُ يحيى بن عُمرَ في زَعامةِ صنهاجة وتَقَلَّدَ أُمورَ الحَربِ، اتَّفقَ له مِن النَّاموسِ ما لم يَتَّفِق لِغيرهِ مِن المُلوكِ، كان يَركَبُ معه إذا سار لِقِتالِ عَدُوٍّ خمسُمائةِ ألفِ مُقاتلٍ، كان يعتقد طاعته، لمَّا قَدِمَ عبدُالله بن ياسين للصحراء لصحراء أفريقية لِدَعوةِ قَبائلِها وتَعليمِهم أُمورَ دِينِهم وإقامةِ شَرعِ الله فيهم؛ فلمَّا قَدِمَ على لتمونة لمتونة قَبيلةِ يُوسفَ بنِ تاشفين, فأَكرَموه، وفيهم أبو بكرِ بن عُمرَ، فذَكَر لهم قواعدَ الإسلامِ، وفَهَّمَهُم، فقالوا: أمَّا الصلاةُ والزَّكاةُ فقَريبٌ، وأمَّا مَن قَتَلَ يُقتَل، ومَن سَرقَ يُقطَع، ومَن زَنَى يُجلَد، فلا نَلتَزِمُه، فذَهَبَا في تلك الصحارى المُتَّصِلَةِ بإقليمِ السُّودانِ حتى انتَهَيَا إلى جدالة، قَبيلةِ جوهر، فاستجابَ بَعضُهم، فقال ابنُ ياسين للذين أَطاعُوه: قد وَجَبَ عليكم أن تُقاتِلوا هؤلاء الجاحِدين، وقد تَحَزَّبُوا لكم، فانْصُبوا رايةً وأَميرًا. قال جوهر: فأنت أَميرُنا. قال: لا، أنا حامِلُ أَمانةِ الشَّرعِ؛ بل أنت الأميرُ. قال: لو فعلتُ لَتَسَلَّطَت قَبيلَتِي، وعاثُوا. قال: فهذا أبو بكر بن عُمرَ رَأسُ لَمتونَة، فسِرْ إليهِ وعرض واعرض عليه الأَمرَ، فبايَعُوا أبا بكرٍ، ولَقَّبُوه أَميرَ المُسلمين، وقام معه طائفةٌ مِن قَومهِ وطائفةٌ مِن جدالة، وحَرَّضَهم ابنُ ياسين على الجِهادِ، وسَمَّاهُم المُرابِطين، فثارت عليهم القَبائلُ، فاستَمالَهم أبو بكرٍ، وكَثُرَ جَمعُه، وبَقِيَ أَشرارٌ، فتَحَيَّلُوا عليهم حتى زَرَبوهُم في مكانٍ، وحَصَرُوهُم، فهَلَكوا جُوعًا، وضَعُفُوا، فقَتَلوهُم، وقَوِيَ أَمرُ أبي بكر بن عُمرَ وظَهرَ، ودانت له الصحراءُ، ونَشأَ حول ابنِ ياسين جَماعةٌ فُقهاءُ وصُلَحاءُ، وظَهرَ الإسلامُ هناك، وكان مع هذا يُقيمُ الحُدودَ ويَحفظُ مَحارِمَ الإسلامِ، ويَحوطُ الدِّينَ ويَسيرُ في الناسِ سِيرَةً شَرعِيَّةً، مع صِحَّةِ اعتِقادِه ودِينِه، ومُوالاةِ الدولةِ العبَّاسِيَّةِ، في سَنةِ 453هـ قام أبو بكر بن عُمرَ بِتَوْلِيَةِ ابنِ عَمِّهِ يُوسف بن تاشفين شُؤونَ المُرابِطين، وتَوَجَّهَ هو إلى الجنوبِ على رَأسِ جَيشٍ مُختَرِقًا بِلادَ سجلماسة ثم قَصدَ بِلادَ السُّودانِ السِّنغالَ مُتَوَغِّلًا فيها ناشِرًا للإسلامِ إلى أن أَصابَتهُ نُشَّابَةٌ في بَعضِ غَزَواتِه في حَلْقِه فقَتَلَتْهُ وهُم في قِتالٍ مع السُّودانِ السِّنغالِ."},{"id":1619,"title":"غَلاءٌ شَديدٌ، ومَجاعةٌ عَظيمةٌ في مصر .","date":["العام الهجري :462","العام الميلادي :1069"],"text":"كان بمصر غَلاءٌ شَديدٌ، ومَجاعةٌ عَظيمةٌ حتى أَكلَ الناسُ بَعضُهم بَعضًا، وفارَقوا الدِّيارَ المِصريَّة، فوَرَدَ بغدادَ منهم خَلْقٌ كَثيرٌ هَرَبًا مِن الجوعِ، ووَرَدَ التُّجَّارُ، ومعهم ثِيابُ صاحبِ مصر وآلاتُه، نُهِبَت مِن الجوعِ، وكان فيها أشياءُ كَثيرةٌ كانت قد نُهِبَت من دارِ الخِلافةِ وقتَ القَبضِ على الطائعِ لله سنة 381هـ، وممَّا نُهِبَ أيضًا في فِتنةِ البساسيري وخَرَجَ من خَزائنِهم ثمانون ألف قِطعةِ بِلَّوْر كِبار، وخمسة وسبعون ألف قِطعةٍ من الدِّيباج، وعشرون ألف سَيفٍ مُحَلًّى، وغيرُ ذلك كثيرٌ ممَّا يَتَعَجَّبُ المرءُ مِن سَماعِه لِكَثرَتِه وعِظَمِه، وكُلُّه كان في قُصورِ المُستَنصِر، وأَكلَ أهلُ مصر الجِيَفَ والمَيْتَةَ والكِلابَ، فكان يُباع الكَلبُ بخَمسةِ دنانير، وماتت الفِيَلَةُ فأُكِلَت مَيتَتُه، وأُفْنِيَت الدَّوابُّ فلم يَبقَ لصاحبِ مصر سوى ثلاثةُ أَفراس، بعدَ أن كان له العددُ الكثيرُ من الخَيْلِ والدَّوابِّ، ونَزلَ الوزيرُ يومًا عن بَغلتِه فغَفَلَ الغُلامُ عنها لِضَعْفِه من الجوعِ فأَخذَها ثلاثةُ نَفَرٍ فذَبَحوها وأَكلوها فأُخِذُوا فصُلِبُوا فما أَصبَحوا إلَّا وعِظامُهم بادِيَةٌ، قد أَخذَ الناسُ لُحومَهم فأَكَلوها، وظُهِرَ على رَجُلٍ يَقتُل الصِّبيانَ والنِّساءَ ويَدفِن رُؤوسَهم وأَطرافَهم، ويَبيع لُحومَهم، فقُتِلَ وأُكِلَ لَحمُه، وكانت الأعرابُ يَقدَمون بالطعامِ يَبيعونَه في ظاهرِ البلدِ، لا يَتجاسرون يَدخلون لِئلَّا يُخطَف ويُنهَب منهم، وكان لا يَجسُر أَحدٌ أن يَدفِن مَيِّتَهُ نهارًا، وإنَّما يَدفِنه ليلًا خُفيةً، لِئلَّا يُنبَش فيُؤكَل، وبِيعَت ثِيابُ النِّساءِ والرِّجالِ وغيرُ ذلك بأَرخصِ ثَمَنٍ، وكذلك الأملاكُ وغيرُها."},{"id":1620,"title":"قَطْعُ الخُطبةِ للعبيديين في مكة والمدينة وإِقامةُ الخُطبةِ للعبَّاسيِّين .","date":["العام الهجري :462","العام الميلادي :1069"],"text":"وَرَدَ رسولُ صاحبِ مكَّةَ محمدِ بن أبي هاشمٍ، ومعه وَلَدُه، إلى السُّلطانِ ألب أرسلان، يُخبِرُه بإقامةِ الخُطبةِ للخَليفةِ القائمِ بأَمرِ الله وللسُّلطانِ بمكَّةَ، وإِسقاطِ خُطبَةِ الفاطميِّ صاحبِ مصر، وتَرْكِ الأَذانِ بِحَيَّ على خَيرِ العَملِ، فأَعطاهُ السُّلطانُ ثلاثينَ ألف دِينارٍ، وخِلَعًا نَفيسَةً، وأَجرَى له كلَّ سَنَةٍ عَشرةَ آلاف دِينارٍ، وقال: إذا فَعلَ أَميرُ المَدينَةِ مهنأ كذلك، أَعطَيناهُ عشرينَ ألف دِينارٍ، وكلَّ سَنةٍ خَمسةَ آلاف دِينارٍ. فلم يَلتَفِت المُستَنصِر لذلك لِشُغلِه بِنَفسِه ورَعِيَّتِه مِن عِظَمِ الغَلاءِ والجوعِ، عِلمًا بأنه في هذه السَّنَةِ ضاقت النَّفَقَةُ على أَميرِ مكَّةَ فأَخذَ الذَّهَبَ من أَستارِ الكَعبةِ والمِيزابِ وبابِ الكَعبةِ، فضَرَبَ ذلك دَراهِمَ ودَنانيرَ، وكذا فَعلَ صاحبُ المَدينةِ بالقَناديلِ التي في المَسجدِ النَّبَوِيِّ."},{"id":1621,"title":"نِهايةُ الدَّولةِ الجَهْوَرِيَّةِ بِقُرطُبة .","date":["العام الهجري :462","العام الميلادي :1069"],"text":"قام يحيى المأمون بن إسماعيل بن ذي النون أَميرُ طُليطلة بالمَسيرِ إلى قُرطُبة للاستِيلاءِ عليها، فاستَنجدَ أَميرُها عبدُالملك بن جَهور بالمُعتَمِد بن عبَّادٍ الذي أَرسلَ إليه جَيشًا للنَّجدَةِ فاحتَلَّ قُرطُبة واعتَقلَ عبدَالملك بن جَهور ووَالِدَهُ وأَخاهُ ونَفاهُم إلى جَزيرةِ شلطيش، ووَلَّى ابنَه سِراجَ الدَّولةِ حاكِمًا على قُرطُبة فأنهى بذلك دَولةَ الجَهوريِّينَ على قُرطُبة التي دامت قَريبًا من خمسٍ وثلاثين سَنةً."},{"id":1622,"title":"وَفاةُ ابنِ عبدِ البَرِّ القُرطُبيِّ .","date":["العام الهجري :463","الشهر القمري : ربيع الآخر","العام الميلادي :1071"],"text":"هو الإمامُ، العَلَّامةُ، حافظُ المَغرِب، شيخُ الإسلامِ، أبو عُمرَ يُوسُف بنُ عبدِ الله بن محمدِ بن عبدِ البَرِّ بن عاصمٍ النمريُّ، الأَندَلُسيُّ، القُرطُبيُّ, فَقِيهٌ مالكيٌّ مَشهورٌ، صاحبُ التَّصانيفِ المَلِيحَةِ الهائِلَة، منها ((التمهيد))، و((الاستذكار)) و((الاستيعاب))، وغير ذلك، مِن كِبارِ حُفَّاظِ الحَديثِ، يُقالُ عنه: حافِظُ المَغرِب، وُلِدَ سَنةَ 368هـ. طَلَبَ العِلمَ بعدَ 390هـ وأَدرَكَ الكِبارَ، وطال عُمرُه، وعَلَا سَنَدُه، وتَكاثَر عليه الطَّلَبَةُ، وجَمَعَ وصَنَّفَ، ووَثَّقَ وضَعَّفَ، وسارت بِتَصانيفِه الرُّكبانُ، وخَضَعَ لِعِلمِه عُلماءُ الزَّمانِ، وَفَاتَهُ السَّماعُ مِن أَبيهِ الإمامِ أبي محمدٍ، فإنه ماتَ قديمًا في سَنةِ 380هـ قبل أن يَبدأ ابنُه أبو عُمرَ في الطَّلَبِ، وله رِحلاتٌ طَويلةٌ في طَلَبِ العِلمِ. قال الحُميديُّ: \"أبو عُمرَ فَقِيهٌ حافظٌ مُكْثِرٌ، عالِمٌ بالقِراءاتِ وبالخِلافِ، وبِعُلومِ الحَديثِ والرِّجالِ، قَديمُ السَّماعِ، يَميلُ في الفِقْهِ إلى أَقوالِ الشافعيِّ\".قال الذهبيُّ: \"كان إمامًا دَيِّنًا، ثِقَةً، مُتْقِنًا، عَلَّامةً، مُتَبَحِّرًا، صاحبَ سُنَّةٍ واتِّباعٍ، وكان أَوَّلًا أَثَرِيًّا ظاهِرِيًّا فيما قِيلَ، ثم تَحوَّل مالِكيًّا مع مَيْلٍ بَيِّنٍ إلى فِقهِ الشافعيِّ في مَسائلَ، ولا يُنكَر له ذلك، فإنه ممَّن بَلَغَ رُتبةَ الأئمَّةِ المُجتهِدين، ومَن نَظرَ في مُصنَّفاتِه، بانَ له مَنزِلَتُه مِن سِعَةِ العِلمِ، وقُوَّةِ الفَهمِ، وسَيَلانِ الذِّهنِ, وكان مُوَفَّقًا في التَّأليفِ، مُعانًا عليه، ونَفَعَ الله بِتَواليفِه، وكان مع تَقَدُّمِه في عِلمِ الأَثَرِ وبَصَرِه بالفِقهِ ومعاني الحَديثِ له بَسْطَةٌ كَبيرةٌ في عِلمِ النَّسَبِ والخَبَرِ, وكان حافِظَ المَغربِ في زَمانِه, وذَكَرَ جَماعةٌ أنه وَلِيَ قَضاءَ الأشبونة وشنترين\". تُوفِّيَ في شاطبة عن 95 عامًا."},{"id":1623,"title":"انتِزاعُ الأَميرِ أتسز الخوارزميِّ الرَّمْلَةَ وبَيتَ المَقْدِس من اتباعِ العُبيديِّين .","date":["العام الهجري :463","الشهر القمري : جمادى الأولى","العام الميلادي :1071"],"text":"قَصَدَ أتسز بن أوق الخوارزميُّ -وهو من أُمراءِ السُّلطانِ ملكشاه السلجوقي- بِلادَ الشامِ، فجَمعَ الأَتراكَ وسار إلى فِلسطين، ففَتحَ مَدينةَ الرَّمْلَةَ، وسار منها إلى بَيتِ المَقدِس وحَصرَه، وفيه عَساكرُ المِصريِّين التابِعينَ للدولةِ الفاطِميَّة، ففَتَحَهُ، ومَلَكَ ما يُجاوِرُهُما من البِلادِ، ما عدا عَسقلان، وقَصَدَ دِمشقَ فحَصرَها، وتابَعَ النَّهْبَ لِأَعمالِها حتى خَرَّبَها، وقَطعَ الميرةَ عنها، فضاقَ الأَمرُ بالناسِ، فصَبَروا، ولم يُمَكِّنُوه مِن مُلْكِ البلدِ، فعاد عنه، وأَدامَ قَصْدَ أَعمالِه وتَخريبها حتى قَلَّتِ الأَقواتُ عندهم."},{"id":1624,"title":"استِيلاءُ السُّلطانِ ألب أرسلان على حَلَب .","date":["العام الهجري :463","الشهر القمري : جمادى الأولى","العام الميلادي :1071"],"text":"بَعثَ ناصرُ الدولةِ حُسينُ بن حمدان الفقيه أبا جَعفرٍ محمدَ بن أحمدَ بن البُخاريِّ رَسولًا منه إلى السُّلطانِ ألب أرسلان، مَلِكِ العِراقِ، يَسألهُ أن يُسَيِّرَ إليه العَساكرَ لِيُقيمَ الدَّعوةَ العبَّاسيَّةَ بدِيارِ مصر، وتكون مصر له. فتَجَهَّزَ ألب أرسلان مِن خُراسان في عِساكرَ عَظيمةٍ، وبَعثَ إلى محمودِ بن ثمال بن صالحِ بن مرداس، صاحبِ حَلَب، أن يَقطعَ دَعوةَ المُستَنصِر ويُقيمَ الدَّعوةَ العبَّاسيَّة، فقُطِعَت دَعوةُ المُستَنصِر من حَلَب ولم تَعُد بعدَ ذلك. وانتهى ألب أرسلان إلى حَلَب في جُمادى الأُولى سَنةَ 463هـ وحاصَرَها شَهرًا، فخَرجَ إليه صاحبُها محمودُ بن ثمال بن صالحِ بن مرداس، فأَكرَمه وأَقَرَّهُ على وِلايَتِه. وأَخذَ يُريدُ المَسيرَ إلى دِمشقَ لِيَمُرَّ منها إلى مصر، وإذا بالخَبَرِ قد طَرَقَهُ أنَّ مُتَمَلِّكَ الرُّومِ قد قَطعَ بِلادَ أرمينية يُريدُ أَخْذَ خُراسان، فشَغَلهُ ذلك عن الشامِ ومصر ورَجعَ إلى بِلادِه؛ فواقَعَ جَمائِعَ الرُّومِ على خلاط وهَزمَهُم. وكان قد تَركَ طائفةً من عَسكرِه الأتراكِ ببلادِ الشامِ فامتَدَّت أَيدِيهم إليها ومَلَكَتْهَا كُلَّها، فخَرجَت عن أَيدِي الفاطِميِّين ولم تَعُد إليهم."},{"id":1625,"title":"وَفاةُ الشاعِرِ ابنِ زَيدونَ الأندَلُسي  .","date":["العام الهجري :463","الشهر القمري : رجب","العام الميلادي :1071"],"text":"هو الصاحبُ، الوَزيرُ، العَلَّامَةُ، أبو الوَليدِ أحمدُ بن عبدِ الله بن أحمدَ بن غالبِ بن زَيدونَ المَخزُومِيُّ، القُرشيُّ، الأندَلُسيُّ، القُرطُبيُّ، الشاعرُ الماهرُ، حاملُ لِواءِ الشِّعْرِ في عَصرِه. اتَّصلَ بالأَميرِ المُعتَمِدِ بن عبَّادٍ، صاحبِ إشبيلية، فحَظِيَ عنده وصار مُشاوِرًا في مَنزِلَةِ الوَزيرِ، كان بارِعًا أَديبًا شاعرًا مُجيدًا، كان يُشعِر لِنَفسِه لا للتَّكَسُّبِ، أُفْعِمَ بِحُبِّ وَلَّادَة بِنتِ المُستَكْفِي المرواني أَميرِ الأندَلُس، سُجِنَ بِتُهمَةِ مَيْلِه لِبَني أُمَيَّةَ، قال ابنُ بَسَّام: \" كان أبو الوَليدِ غايةَ مَنثورٍ ومَنظومٍ، وخاتِمةَ شُعراءِ بني مَخزومٍ، أَحدُ مَن جَرَّ الأيامَ جَرًّا، وفاتَ الأنامَ طُرًّا، وصَرَّفَ السُّلطانَ نَفْعًا وضُرًّا، ووَسَّعَ البيانَ نَظْمًا ونَثْرًا؛ إلى أَدبٍ ليس للبَحرِ تَدَفُّقُهُ، ولا للبَدرِ تَأَلُّقُهُ، وشِعْرٍ ليس للسِّحْرِ بَيانُه، وللنُّجومِ الزُّهْرِ اقتِرانُه. وحَظٍّ مِن النَّثْرِ غَريبِ المَباني، شِعريِّ الألفاظِ والمعاني\", وكان من أَبناءِ وُجوهِ الفُقَهاءِ بقُرطُبة، فانتَقلَ منها إلى عند صاحبِ إشبيلية المُعتَضِدِ بن عبَّادٍ، بعد الأربعين وأربع مائة، فجَعَلَهُ مِن خَواصِّه، وبَقِيَ معه في صُورةِ وَزيرٍ. تُوفِّي في إشبيلية ثم نُقِلَ إلى قُرطُبة ودُفِنَ فيها."},{"id":1626,"title":"مَوقِعةُ ملازكرد بقِيادَةِ السُّلطانِ ألب أرسلان .","date":["العام الهجري :463","الشهر القمري : ذي القعدة","العام الميلادي :1071"],"text":"في هذه السَّنَةِ خَرجَ أرمانوس مَلِكُ الرُّومِ في مائتي ألفٍ من الرُّومِ، والفِرنجِ، والغَربِ، والرُّوسِ، والبجناك، والكرج، وغَيرِهم، من طوائفِ تلك البِلادِ، فجاءوا في تَجَمُّلٍ كَثيرٍ، وزِيٍّ عَظيمٍ، وقَصدَ بِلادَ الإسلامِ، فوَصلَ إلى ملازكرد من أَعمالِ خلاط. فبَلغَ السُّلطانَ ألب أرسلان الخَبرُ. وهو بمَدينةِ خوي من أذربيجان، قد عاد من حَلَب. وسَمِعَ بكَثرَةِ الجُموعِ التي  مع مَلِكِ الرُّومِ، فلم يَتَمَكَّن من جَمْعِ العَساكرِ لبُعدِها وقُرْبِ العَدُوِّ، فسَيَّرَ الأَثقالَ مع زَوجتِه ونِظامِ المُلْكِ إلى همذان، وسار هو فيمن عنده من العَساكرِ، وهُم خَمسة عشر ألف فارس. وَجَدَّ في السَّيْرِ وقال لهم: إنَّني أُقاتِلُ مُحتَسِبًا صابرًا، فإن سَلِمْتُ فنِعمةٌ مِن الله تعالى، وإن كانت الشهادةُ فإنَّ ابني ملكشاه وَلِيُّ عَهْدِي. وساروا فلمَّا قارَبَ العَدُوَّ جَعلَ له مُقدِّمةً، فصادَفَت مُقدِّمَتُه، عند خلاط، مُقدِّمَ الرُّوسِيَّة في نَحوِ عشرة آلاف من الرُّومِ، فاقتَتَلوا، فانهَزمَت الرُّوسِيَّةُ، وأَسَرَ مُقدِّمَهم، وحُمِلَ إلى السُّلطانِ، فجَدَعَ أَنْفَهُ، وأَنْفَذَ بالسَّلَبِ إلى نِظامِ المُلْكِ، وأَمرَهُ أن يُرسِلَهُ إلى بغداد، فلمَّا تَقارَب العَسكرانِ أَرسلَ السُّلطانُ إلى مَلِكِ الرُّومِ يَطلُب منه المُهادَنة، فقال: لا هُدْنَةَ إلَّا بالرَّيِّ. فانزَعجَ السُّلطانُ لذلك، فقال له إِمامُه وفَقِيهُه أبو نصرٍ محمدُ بن عبدِ المَلِكِ البُخاريُّ، الحَنَفيُّ: إنَّك تُقاتِل عن دِينٍ وَعَدَ الله بِنَصْرِهِ وإِظهارِهِ على سائرِ الأديانِ، وأَرجو أن يكون الله تعالى قد كَتبَ باسمِك هذا الفَتحَ، فالْقِهِم يومَ الجُمعةِ، بعدَ الزَّوالِ، في الساعةِ التي تكون الخُطباءُ على المنابرِ، فإنَّهم يَدعُون للمُجاهِدين بالنَّصرِ، والدُّعاءُ مَقرونٌ بالإجابةِ. فلمَّا كانت تلك الساعةُ صلَّى بهم، وبَكَى السُّلطانُ، فبَكَى الناسُ لِبُكائِه، وَدَعا ودَعَوا معه وقال لهم: مَن أَرادَ الانصرافَ فليَنصَرِف، فما هاهنا سُلطانٌ يأمرُ ويَنهى، وأَلقَى القَوْسَ والنِّشابَ، وأَخذَ السَّيفَ والدَّبُّوسَ – الدَّبُّوس آلة من آلاتِ الحَربِ تُشبِه الإِبْرَة-، وعَقَدَ ذَنَبَ فَرَسِه بِيَدِه، وفَعلَ عَسكرُه مِثلَه، ولَبِسَ البَياضَ وتَحَنَّطَ، وقال: إن قُتِلتُ فهذا كَفَني. وزَحَفَ إلى الرُّومِ وزَحَفوا إليه، فلمَّا قارَبَهم نَزلَ السُّلطانُ عن فَرَسِه وسَجَدَ لله عزَّ وجلَّ، ومَرَّغَ وَجهَه في التُّرابِ وَدَعا الله واستَنصَرَهُ، فأَنزلَ الله نَصرَهُ على المُسلمينَ، ومَنَحَهم أَكتافَهم فقَتَلوا منهم خَلْقًا كَثيرًا، وأُسِرَ مَلِكُهم أرمانوس، أَسَرَهُ غُلامٌ رُومِيٌّ، فلمَّا أُوقِفَ بين يدي المَلِكِ ألب أرسلان ضَرَبَهُ بِيَدِه ثلاثَ مَقارِع وقال: لو كنتُ أنا الأَسيرَ بين يَديكَ ما كنتَ تفعل؟ قال: كلَّ قَبيحٍ. قال: فما ظَنُّكَ بي؟ فقال: إمَّا أن تقتل تَقتُلَني وتُشْهِرَني في بِلادِك، وإمَّا أن تَعفُو وتَأخُذ الفِداءَ وتُعيدَني. قال: ما عَزمتُ على غَيرِ العَفوِ والفِداءِ. فافتَدَى نَفسَه منه بألف ألف دِينارٍ وخمسمائة ألف دينار، فلما انتهى إلى بِلادِه وَجدَ الرُّومَ قد مَلَّكوا عليهم غَيرَه، فأَرسلَ إلى السُّلطانِ يَعتَذِر إليه، وبَعثَ من الذَّهبِ والجَواهِر ما يُقارِب ثلاثمائة ألف دينار، وتَزَهَّدَ ولَبِسَ الصُّوفَ ثم استغاث بملك الأرمن فأَخذَه وكحله وأَرسلَه إلى السُّلطانِ يَتَقَرَّبُ إليه بذلك."},{"id":1627,"title":"وَفاةُ الخَطيبِ البَغداديِّ صاحبِ تاريخِ بغداد .","date":["العام الهجري :463","الشهر القمري : ذي الحجة","العام الميلادي :1071"],"text":"هو الحافِظُ أبو بكرٍ أَحمدُ بن عليِّ بن ثابتِ بن أَحمدَ بن مَهدِيٍّ، الخَطيبُ البغداديُّ، أَحدُ الحُفَّاظِ الأَعلامِ المَشهورِينَ، صاحبُ ((تاريخ بغداد)) وغَيرِه من المُصنَّفاتِ العَديدةِ المُفيدةِ، وُلِدَ سَنةَ 392هـ، وكان أبوه أبو الحَسنِ الخَطيبُ قد قَرأَ على أبي حَفصٍ الكِتَّانيِّ، وصار خَطيبَ قَريةِ درزيجان، إحدى قُرى العِراقِ، فحَضَّ وَلدَه أبا بكرٍ على السَّماعِ في صِغَرِه، فسَمِعَ وله إحدى عشرة سَنةً، نَشأَ ببغداد، وتَفَقَّهَ على أبي طالبٍ الطَّبريِّ وغَيرِه من أَصحابِ الشيخِ أبي حامدٍ الأسفراييني، وسَمِعَ الحَديثَ الكَثيرَ، ورَحلَ إلى البَصرةِ, ونيسابور, وأصبهان، وهمذان, والشامِ, والحِجازِ. وسُمِّيَ الخَطيبَ لأنه كان يَخطُب بدرزيجان، ولمَّا وقعت فِتنةُ البساسيري ببغداد سَنةَ 450هـ خَرجَ الخَطيبُ إلى الشامِ فأَقامَ بدِمشقَ بالمأذَنةِ الشرقيَّةِ مِن جامِعِها، وكان يَقرأُ على الناسِ الحَديثَ، وكان جَهورِيَّ الصوتِ، يُسمَع صَوتُه من أَرجاءِ الجامعِ كُلِّها، فاتَّفَق أنه قَرأَ على الناسِ يومًا فَضائلَ العبَّاسِ فثَارَ عليه الرَّوافِضُ من أَتباعِ الفاطِميِّين، فأَرادوا قَتْلَه فتَشَفَّعَ بالشَّريفِ الزَّينبيِّ فأَجارَهُ، وكان مَسكَنُه بدارِ العقيقي، ثم خَرجَ من دِمشقَ فأَقامَ بمَدينةِ صور، فكَتبَ شَيئًا كَثيرًا من مُصنَّفاتِ أبي عبدِ الله الصوري بِخَطِّهِ كان يَستَعيرُها من زَوجَتِه، فلم يَزَل مُقيمًا بالشامِ إلى سَنةِ 462هـ، ثم عاد إلى بغداد فحَدَّثَ بأَشياءَ من مَسمُوعاتِه، وله مُصنَّفاتٌ كَثيرةٌ مُفيدةٌ، نحو من سِتِّينَ مُصَنَّفًا، ويُقالُ: بل مائة مُصَنَّف، منها كتاب ((تاريخ بغداد))، وكتاب ((الكفاية))، و((الجامع))، و((شرف أصحاب الحديث))، و((المتفق والمفترق))، و((السابق واللاحق))، و((تلخيص المتشابه في الرسم))، و((اقتضاء العلم للعمل))، و((الفقيه والمتفقه))، وغير ذلك، ويُقال: إن هذه المُصَنَّفات أَكثرُها لأبي عبدِ الله الصوري، أو ابتَدأَها فتَمَّمَها الخَطيبُ، وجَعَلَها لِنَفسِه، قال الذهبيُّ: \"ما الخَطيبُ بِمُفْتَقِرٍ إلى الصوري، هو أَحْفَظُ وأَوْسَعُ رِحلةً وحَديثًا ومَعرِفةً\" كان الخَطيبُ أولا أَوَّلَ أَمرِهِ يَتكلَّم بمَذهبِ الإمامِ أَحمدَ بن حَنبلٍ، فانتَقلَ عنه إلى مَذهبِ الشافعيِّ. كان مَهيبًا وَقورًا، ثِقَةً مُتَحَرِّيًا، حُجَّةً، حَسَنَ الخَطِّ، كَثيرَ الضَّبْطِ، فَصيحًا، خُتِمَ به الحُفَّاظِ، قال ابنُ ماكولا: \"كان أبو بكرٍ آخِرَ الأَعيانِ، ممَّن شاهَدناه مَعرِفةً، وحِفظًا، وإتقانًا، وضَبطًا لِحَديثِ رسولِ الله صلَّى الله عليه وسلَّم، وتَفَنُّنًا في عِلَلِهِ وأَسانيدِه، وعِلمًا بصَحيحِه وغَريبِه، وفَرْدِه ومُنكَرِه ومَطروحِه، ولم يكُن للبَغداديِّينَ بعدَ أبي الحَسنِ الدَّارقطنيِّ مِثلُه\". كان الخَطيبُ يقول: \"مَن صَنَّفَ فقد جَعلَ عَقلَهُ على طَبَقٍ يُعرِضُه على الناسِ\", \"كان للخَطيبِ ثَروةٌ من الثِّيابِ والذَّهبِ، وما كان له عَقِبٌ، فكَتبَ إلى القائمِ بأَمرِ الله قال له: إنَّ مالي يَصيرُ إلى بَيتِ مالٍ، فَأْذَنْ لي حتى أُفَرِّقَهُ فيمَن شِئتُ. فأَذِنَ له، ففَرَّقَها على المُحَدِّثين\". تُوفِّيَ يومَ الاثنين ضُحًى، وله ثِنتانِ وسَبعون سَنةً، في حُجرَةٍ كان يَسكُنها بِدَربِ السلسلةِ، جِوارَ المَدرسةِ النِّظاميَّةِ، واحتَفلَ الناسُ بجِنازَتِه، وكان فيمَن حَملَ نَعشَه الشيخُ أبو إسحاقَ الشِّيرازيُّ، ودُفِنَ إلى جانبِ قَبرِ بِشْرٍ الحافيِّ."},{"id":1628,"title":"إِنكارُ الشيخِ الشِّيرازيِّ مع عَددٍ من الحَنابِلَةِ على المُفسِدِينَ .","date":["العام الهجري :464","العام الميلادي :1071"],"text":"قام الشيخُ أبو إسحاقَ الشِّيرازيُّ مع الحَنابِلَةِ في الإنكارِ على المُفسِدِينَ، والذين يَبيعُونَ الخُمورَ، وفي إِبطالِ المُؤاجِراتِ وَهُنَّ البَغايا، وكَتَبوا إلى السُّلطانِ في ذلك، فجاءَت كُتُبُه في الإنكارِ."},{"id":1629,"title":"حُدوثُ زَلزَلةٍ عَظيمةٍ ببغداد .","date":["العام الهجري :464","العام الميلادي :1071"],"text":"حدوث حَدَثَت زَلزلةٌ عَظيمةٌ ببغداد ارتَجَّت لها الأَرضُ سِتَّ مَرَّاتٍ، وفيها كان مَوتٌ ذَرِيعٌ في الحيواناتِ، بحيث أنَّ بعضَ الرُّعاةِ بخُراسان قام وقتَ الصباحِ لِيَسرَحَ بِغَنَمِه فإذا هُنَّ قد مِتْنَ كُلُّهُنَّ، وجاء سَيْلٌ عَظيمٌ وبَرَدٌ كِبارٌ أَتلَفَ شَيئًا كَثيرًا من الزُّروعِ والثِّمارِ بخُراسان."},{"id":1630,"title":"السُّلطانِ ألب أرسلان يسيطر على قَلعةَ فضلون الكُرديِّ بفارِس .","date":["العام الهجري :464","العام الميلادي :1071"],"text":"سَيَّرَ السُّلطانُ ألب أرسلان وَزيرَهُ نِظامَ المُلْكِ في عَسكرٍ إلى بِلادِ فارِس، وكان بها حِصْنٌ من أَمنَعِ الحُصونِ والمَعاقِلِ، وفيه صاحبُه فضلون الكُرديُّ، وهو لا يُعطِي الطَّاعةَ، فنازَلَهُ وحَصرَهُ، ودَعاهُ إلى طَاعةِ السُّلطانِ فامتَنَع، فقاتَلَهُ فلم يَبلُغ بقِتالِه غَرَضًا لِعُلُوِّ الحِصنِ وارتِفاعِه، فلم يَطُل مَقامُهم عليه حتى نادَى أَهلُ القَلعةِ بَطَلَبِ الأَمانِ لِيُسَلِّموا الحِصنَ إليه، فعَجبَ الناسُ من ذلك، وكان السببُ فيه أنَّ جَميعَ الآبارِ التي بالقَلعةِ غارَت مِياهُها في لَيلةٍ واحدةٍ فقادَتهُم ضُرورةُ العَطَشِ إلى التَّسليمِ، فلمَّا طَلَبوا الأَمانَ أَمَّنَهُم نِظامُ المُلْكِ، وتَسلَّمَ الحِصنَ، والْتَجَأَ فضلون إلى قُلَّةِ القَلعَةِ، وهي أَعلَى مَوضِعٍ فيها، وفيه بِناءٌ مُرتفِعٌ، فاحتَمَى فيها، فسَيَّرَ نِظامُ المُلْكِ طائِفةً من العَسكرِ إلى المَوضِعِ الذي فيه أَهلُ فضلون وأَقارِبُه لِيَحمِلوهُم إليه ويَنهَبوا مالَهم، فسَمِعَ فضلون الخَبَرَ، ففارَقَ مَوضِعَه مُستَخفِيًا فيمَن عنده من الجُنْدِ، وسار لِيمنَع عن أَهلِه، فاستَقبَلَتهُ طلائِعُ نِظامِ المُلْكِ، فخافَهُم فتَفَرَّقَ مَن معه، واختَفَى في نَباتِ الأَرضِ، فوَقعَ فيه بَعضُ العَسكرِ، فأَخذَه أَسيرًا، وحَملَه إلى نِظامِ المُلْكِ، فأَخَذَهُ وسارَ به إلى السُّلطانِ فأَمَّنَهُ وأَطلَقَهُ."},{"id":1631,"title":"مُحاوَلةُ ناصرِ الدَّولةِ ابنِ حمدان التَّغلبيِّ القَضاءَ على دَولةِ المُستَنصِر بالله الفاطِميِّ  .","date":["العام الهجري :464","العام الميلادي :1071"],"text":"وَقعَ نِزاعٌ بين فِرقَتينِ، فِرقةِ العَبيدِ وعَرَبِ الصَّعيدِ، وفِرقةِ الجُنْدِ مِن التُّركِ والمَغارِبَةِ، ورَأسُهم ناصرُ الدَّولةِ ابنُ حمدان التَّغلبيُّ، فالتَقوا بكومِ الريش، فهَزمَهم ابنُ حمدان، وقَتَلَ وغَرَّقَ نحوًا من أربعين ألفًا. ونَفَدَت خَزائنُ المُستَنصِر على التُّركِ، ثم اختَلَفوا، ودامت الحَربُ أيامًا، وطَمِعَ التُّركُ في المُستَنصِر، وطالبوه حتى بِيعَت فُرُشُ القَصرِ، وأَمتِعَتُه بأَبخَسِ ثَمَنٍ، وغَلَبَت العَبيدُ على الصَّعيدِ، وقَطَعوا الطُّرُقَ، وكان نَقْدُ الأَتراكِ في الشهرِ أربعَ مائة ألف دِينارٍ، واشتَدَّت وَطأةُ ناصرِ الدَّولةِ، وصار هو الكُلُّ، فحَسَده الأُمراءُ، وحارَبوهُ، فهَزَموه، ثم جَمَعَ وأَقبلَ فانتَصَر، واضمَحلَّ أَمرُ المُستَنصِر بالمَرَّةِ، وخَملَ ذِكْرُهُ. وبَعثَ ابنُ حمدان يُطالِبُه بالعَطاءِ، فَرآهُ رَسولُه على حَصيرٍ، وما حوله سِوى ثلاثةِ غِلمانٍ. فقال: أما يكفي ناصرَ الدَّولةِ أن أَجلِسَ في مثلِ هذا الحالِ؟ فبَكَى الرسولُ، ورَقَّ له ناصرُ الدَّولةِ، وقَرَّرَ له كلَّ يومٍ مائةَ دِينارٍ, وتَفرَّق عن المُستَنصِر أَولادُه، وأَهلُه من الجوعِ، وتقرفوا وتَفَرَّقوا في البلادِ، ودامَ الجَهْدُ عامين، ثم انحَطَّ السِّعْرُ في سَنةِ خمسٍ وسِتِّين. قال الذهبيُّ: \"كان ناصرُ الدَّولةِ، يُظهِر التَّسَنُّنَ، ويَعِيبَ المُستَنصِرَ لِخُبْثِ رَفْضِهِ وعَقِيدَتِه\" قال ابنُ الأَثيرِ: بالَغَ ابنُ حمدان في إهانَةِ المُستَنصِر، وفَرَّقَ عنه عامَّةَ أَصحابِه، وكان غَرضُه أن يَخطُبَ لأَميرِ المؤمنين القائمِ، ويُزيلَ دَولةَ الباطنِيَّة، وما زال حتى قَتَلَهُ الأُمراءُ، وقَتَلوا أَخوَيهِ فَخْرَ العَربِ، وتاجَ المعالي، وانقَطَع ذِكْرُ الحمدانية بمصر بالكُلِّيَّةِ\""},{"id":1632,"title":"وَفاةُ ناصِرِ الدَّولةِ ابنِ حمدان التُّركيِّ .","date":["العام الهجري :465","العام الميلادي :1072"],"text":"هو الأَميرُ الكَبيرُ، ناصِرُ الدَّولةِ، حُسينُ بنُ الأَميرِ ناصِرِ الدَّولةِ وسَيفِها حَسنِ بنِ الحُسينِ ابنِ صاحِبِ المَوصِل ناصِرِ الدَّولةِ، أبي مُحمدٍ الحَسنِ بنِ عبدِ الله بن حمدان، التَّغلبيُّ. كان أَبوهُ حَسنٌ قد عَمِلَ نِيابةَ دِمشقَ لصاحِبِ مصر المُستَنصِر، ونَشأَ ناصرُ الدَّولةِ، فكان أَحَدَ الأَبطالِ، شَهْمًا شُجاعًا، مِقدامًا مَهِيبًا، وافِرَ الحِشمَةِ، تَمَكَّنَ بمِصرَ، وتَقدَّم على أُمَرائِها، وجَرَت له حُروبٌ وخُطوبٌ وعَجائِبُ، وأَظهرَ بمصر السُّنَّةَ، وكان عازِمًا على إِقامَةِ الدَّعوةِ لِبَنِي العبَّاسِ، فإنَّه تَهَيَّأَت له الأَسبابُ، وقَهَرَ المُستَنصِرَ بالله العُبيديَّ، قال الذهبيُّ: \"كان عَمَّالًا على إِقامَةِ الدَّولةِ لِبَنِي العبَّاسِ، وقَهْرِ العُبيديَّة، وتَهَيَّأَت له الأَسبابُ، وتَرَكَ المُستَنصِر على بَرْدِ الدِّيارِ، وأَبادَ الكِبارَ، إلى أن وَثَبَ عليه أَتراكٌ، فقَتَلوهُ\" وكان قد وَلِيَ إِمْرَةَ دِمشقَ أيضًا، وكان قد رَاسلَ ناصِرُ الدَّولةِ السُّلطانَ ألب أرسلان لِيَنجِدَهُ بعَسكرٍ للقَضاءِ على العُبيديِّين فأَجابَه. فلمَّا خَشِيَ الأُمراءُ على أَنفُسِهم منه انتَدَبوا لاغتِيالِه وللفَتْكِ به إلدكزَ  التُّركيَّ في جَماعةٍ من الأُمراءِ، فقَتَلوهُ وقَتَلوا أَخويهِ تاجَ المعالي وفَخْرَ العَربِ، وانتهى ذِكْرُ بني حمدان في مصر."},{"id":1633,"title":"الحَربُ بين السُّلطانِ ملكشاه وعَمِّهِ قاورت بك .","date":["العام الهجري :465","العام الميلادي :1072"],"text":"لمَّا بَلغَ قاورت بك، وهو بكرمان، وَفاةُ أَخيهِ ألب أرسلان سارَ طالِبًا للرَّيِّ يُريدُ الاستِيلاءَ على المَمالِكِ، فسَبَقَهُ إليها السُّلطانُ ملكشاه ونِظامُ المُلْكِ، وسارا منها إليه، فالتَقوا بالقُربِ من همذان في شَعبانَ، وكان العَسكرُ يَمِيلون إلى قاورت بك، فحَمَلَت مَيسرةُ قاورت بك على مَيمَنَةِ ملكشاه، فهَزَموها، وحَمَلَ شَرفُ الدَّولةِ مُسلمُ بن قُريشٍ، وبَهاءُ الدَّولةِ مَنصورُ بن دبيس بن مزيد، وهُما مع ملكشاه، ومَن معهما من العَربِ والأَكرادِ، على مَيمَنَةِ قاورت بك فهَزَموها، ومَضَى المُنهَزِمون من أَصحابِ السُّلطانِ ملكشاه إلى حُلَلِ شَرفِ الدَّولةِ، وبَهاءِ الدَّولةِ، فنَهَبوها غَيْظًا منهم، حيث هَزَموا عَسكرَ قاورت بك، وجاءَ رَجلٌ سواديٌّ إلى السُّلطانِ ملكشاه، فأَخبرَهُ أنَّ عَمَّهُ قاورت بك في بَعضِ القُرَى، فأَرسلَ مَن أَخذَهُ وأَحضَرَهُ، فأَمَرَ سَعدَ الدَّولةِ كوهرائين فخَنَقَهُ، وأَقَرَّ كرمان بِيَدِ أَولادِه، وسَيَّرَ إليهم الخِلَعَ، وأَقطَعَ العَربَ والأَكرادَ إقطاعاتٍ كَثيرةً لِمَا فَعَلوهُ في الوَقعَةِ."},{"id":1634,"title":"وَفاةُ القُشيريِّ مصنف الرِّسالَةِ القُشيريَّة .","date":["العام الهجري :465","العام الميلادي :1072"],"text":"الفَقيهُ الشافعيُّ أبو القاسمِ عبدُ الكَريمِ بنُ هوازن القُشيريُّ، النَّيسابوريُّ، مُصَنِّفُ ((الرِّسالة القُشيريَّة)) المشهورة وغيرَها، كان عَلَّامةً في الفِقْهِ والتَّفسيرِ والحَديثِ والأُصولِ والكِتابَةِ والأَدبِ والشِّعْرِ وعِلْمِ التَّصَوُّفِ، جَمعَ بين الشَّريعَةِ والحَقيقَةِ، أَصلُه من ناحِيَةِ أستوا من العَربِ الذين قَدِموا خُراسان، وُلِدَ في شَهرِ رَبيعٍ الأَوَّلِ سَنةَ 376هـ. تُوفِّي أَبوهُ وهو صَغيرٌ، فَقرأَ واشتَغلَ بالأَدبِ والعَربيَّةِ في صِباهُ، وكان أَوَّلًا من أَبناءِ الدُّنيا، فجَذَبَهُ أبو عليٍّ الدَّقَّاقُ فصارَ من الصُّوفِيَّةِ, وتَفَقَّه على بكرِ بنِ محمدٍ الطُّوسيِّ، وأَخذَ الكَلامَ عن ابنِ فورك، وصَنَّفَ ((التَّفسير الكَبير)) و((لَطائِف الإشارات))، وكان يَعِظُ ويَتَكلَّم بكَلامِ الصُّوفيَّةِ, وبعدَ وَفاةِ أبي عليٍّ الدَّقَّاقِ سَلَكَ مَسلَكَ المُجاهَدَةِ والتَّجريدِ وأَخذَ في التَّصنيفِ، وخَرجَ إلى الحَجِّ في رُفقَةٍ فيها الشيخُ أبو محمدٍ الجوينيُّ والدُ إمامِ الحَرمَينِ، وأَحمدُ بنُ الحُسينِ البيهقيُّ وجَماعةٌ من المَشاهيرِ، فسَمِعَ معهم الحَديثَ ببغدادَ والحِجازِ, وكان له في الفُروسِيَّةِ واستِعمالِ السِّلاحِ يَدٌ بَيضاءُ، وأمَّا مَجالِسُ الوَعْظِ والتَّذكيرِ فهو إمامُها، وعَقَدَ لِنَفسِه مَجلِسَ الإملاءِ في الحَديثِ. ذَكَرَهُ الخَطيبُ في تاريخِه قال: \"قَدِمَ علينا في سَنةِ 448هـ، وحَدَّثَ ببغداد، وكَتَبنا عنه، وكان ثِقَةً، وكان يَقُصُّ، وكان حَسَنَ المَوعِظَةِ، مَلِيحَ الإشارةِ، وكان يَعرِف الأُصولَ على مَذهبِ الأَشعريِّ، والفُروعَ على مَذهبِ الشافعيِّ\" وتُوفِّيَ صَبيحةَ يومِ الأحدِ قبلَ طُلوعِ الشمسِ سادس عشر ربيعٍ الآخر سَنةَ 465هـ بمَدينةِ نَيسابور، عن 89 عامًا, ودُفِنَ بالمدرسةِ تحت شَيخِه أبي عليٍّ الدَّقَّاقِ."},{"id":1635,"title":"تَوبةُ أبي الوَفاءِ بن عَقيلٍ مِن الاعتِزالِ\n  .","date":["العام الهجري :465","الشهر القمري : محرم","العام الميلادي :1072"],"text":"قال ابنُ كَثيرٍ: \"في يومِ الخَميسِ حادي عشر المُحرَّمِ حَضرَ إلى الدِّيوانِ أبو الوَفا عليُّ بنُ محمدِ بنِ عَقيلٍ العَقيليُّ الحَنبليُّ، وقد كَتبَ على نَفسِه كِتابًا يَتضمَّن تَوبتَه من الاعتِزالِ، وأنَّه رَجعَ عن اعتِقادِ كَوْنِ الحَلَّاجِ من أَهلِ الحَقِّ والخَيرِ، وأنه قد رَجعَ عن الجُزءِ الذي عَمِلَه في ذلك، وأنَّ الحَلَّاجَ قد قُتِلَ بإجماعِ عُلماءِ أَهلِ عَصرِه على زَندَقتِه، وأنَّهم كانوا مُصِيبينَ في قَتلِه وما رَمَوْهُ بهِ، وهو مُخطِئٌ، وأَشهَدَ عليه جَماعةً من الكُتَّابِ، ورَجعَ من الدِّيوانِ إلى دارِ الشَّريفِ أبي جَعفرٍ فسَلَّمَ عليه وصالَحه واعتَذرَ إليه، فعَظَّمَه\""},{"id":1636,"title":"وَفاةُ ألب أرسلان سُلطانِ السَّلاجِقَة .","date":["العام الهجري :465","الشهر القمري : ربيع الأول","العام الميلادي :1072"],"text":"هو سُلطانُ العالَم عَضُدُ الدَّولةِ أبو شُجاعٍ، المُلَقَّبُ بالعادِل محمد، ألب أرسلان بن جغريبك داود بن ميكائيل بن سلجوق بن دقاق بن سلجوق التُّركيُّ, واسمُه بالعربي محمدُ بنُ داودَ وألب أرسلان اسمٌ تُركيٌّ مَعناهُ شُجاع أَسَد، فألب: شُجاع، وأرسلان: أَسَد. وهو ابنُ أخي السُّلطانِ طغرلبك، أَصلُه من قَريةٍ يُقال لها: النور. وُلِدَ سَنةَ 424هـ, وَجَدُّهُ دقاق، هو أَوَّلُ مَن دَخلَ في الإسلامِ, وألب أرسلان أَوَّلُ مَن ذُكِرَ بالسُّلطانِ على مَنابِرِ بغداد, وكان مَلِكًا عادِلًا، مَهِيبًا، مُطاعًا، مُعَظَّمًا. وَلِيَ السَّلْطَنَةَ بعدَ وَفاةِ عَمِّهِ طغرلبك بن سلجوق في سَنةِ 457هـ. لمَّا ماتَ السُّلطانُ طُغرلبك نَصَّ على تَوْلِيَةِ الأَمرِ لسُليمانَ بنِ داودَ أخي ألب أرسلان، ولم يَنُصَّ على ألب أرسلان؛ لأنَّ أُمَّ سُليمانَ كانت عنده فتَبِعَ هَواها في وَلَدِها، فقام سُليمانُ بالأَمرِ وثارَ عليه أَخوهُ ألب أرسلان، وجَرَت بينهم خُطوبٌ فلم يَتِمَّ لِسُليمانَ الأَمرُ، وكانت النُّصرةُ لألب أرسلان. فاستَولَى على المَمالِكِ، وعَظُمَت مَملكَتُه ورُهِبَت سَطوتُه، وفَتحَ من البِلادِ ما لم يكُن لِعَمِّهِ طُغرلبك مع سِعَةِ مُلْكِ عَمِّهِ، وقَصدَ بِلادَ الشامِ فانتَهَى إلى مَدينةِ حَلَب، وهو أَوَّلُ مَن عَبَرَ الفُراتَ من مُلوكِ التُّركِ. وكاد أن يَتَمَلَّكَ مصر. أَعزَّ الله بهِ الإسلامَ وأَذَلَّ الشِّرْكَ. كان ألب أرسلان مِن أَعدَلِ الناسِ، وأَحسَنِهم سِيرَةً، وأَرغَبِهِم في الجِهادِ وفي نَصرِ الدِّينِ. وعَظُمَ أَمرُ السُّلطانِ ألب آرسلان، وخُطِبَ له على مَنابرِ العِراقِ والعَجَمِ وخُراسان، ودانَت له الأُمَمُ، وأَحَبَّتْهُ الرَّعايا، ولا سيما لمَّا هَزَمَ العَدُوَّ، طاغِيةَ الرُّومِ أرمانوس في مَعركةِ ملازكرد سَنةَ 463هـ, وقَنعَ من الرَّعِيَّةِ بالخَراجِ في قِسطَينِ، رِفْقًا بهم, وكان كَثيرَ الصَّدَقاتِ، يَتَفقَّد الفُقراءَ في كلِّ رَمضانَ بأَربعةِ آلافِ دِينارٍ ببَلخ، ومَرو، وهراة، ونيسابور، ويَتَصدَّق بحَضرَتِه بعشرةِ آلافِ دِينارٍ. كَتبَ إليه بَعضُ السُّعاةِ في نِظامِ المُلْكِ وَزيرِهِ، وذَكَرَ مالَه في مَمالِكِه فاستَدعاهُ فقال له: خُذْ إن كان هذا صَحيحًا فهَذِّبْ أَخلاقَك وأَصلِح أَحوالَك، وإن كَذَبَ فاغْفِر له زَلَّتَهُ. وكان شديدَ الحِرصِ على حِفْظِ مالِ الرَّعايا، بَلَغَهُ أنَّ غُلامًا من غِلمانِه أَخذَ إِزارًا لبَعضِ أَصحابِه فصَلَبَهُ فارتَدعَ سائرُ المَماليكِ به خَوفًا من سَطوتِه. في أَوَّلِ سَنةِ 465هـ قَصدَ السُّلطانُ ألب أرسلان، ما وَراءَ النَّهرِ، وصاحبُه شَمسُ المُلْكِ تكين، فعَقدَ على جيحون جِسْرًا وعَبرَ عليه في نَيِّفٍ وعِشرينَ يومًا، وعَسكرُه يَزيدُ على مائتي ألف فارسٍ، فأَتاهُ أَصحابُه بمُسْتَحْفِظِ قَلعَةٍ يُعرفُ بيُوسُف الخوارزمي، في سادس شهرِ رَبيعٍ الأوَّل، وحُمِلَ إلى قُرْبِ سَريرِه مع غُلامَينِ، فقال له يُوسفُ: يا مُخَنَّث! مِثلي يُقتَل هذه القِتلَة؟ فغَضِبَ السُّلطانُ ألب أرسلان، وأَخذَ القَوْسَ والنِّشابَ، وقال للغُلامَينِ: خَلِّيَاهُ! ورَماهُ بِسَهمٍ فأَخطَأهُ، ولم يكُن يُخطِئ سَهمَه، فوَثبَ يُوسفُ يُريدُه، والسُّلطانُ على سُدَّةٍ، فلمَّا رأى يُوسفَ يَقصِدُه قام عن السُّدَّةِ ونَزلَ عنها، فعَثَرَ، فوَقعَ على وَجهِه، فبَرَكَ عليه يُوسفُ وضَربَهُ بسِكِّينٍ كانت معه في خاصِرَتِه، وكان سعدُ الدَّولةِ واقِفًا، فجَرَحَهُ يُوسفُ أيضًا جِراحاتٍ، ونَهضَ ألب أرسلان فدَخَل إلى خَيمةٍ أُخرَى، وضَرَبَ بَعضُ الفَرَّاشِين يُوسفَ بِمِرْزَبَّةٍ على رَأسِه، فقَتَلَه وقَطَّعَهُ الأتراكُ، ولمَّا جُرِحَ السُّلطانُ قال: ما مِن وَجهٍ قَصدتُه، وعَدُوٍّ أَردتُه، إلَّا استَعنتُ بالله عليه، ولمَّا كان أَمسُ صَعدتُ على تَلٍّ، فارتَجَّت الأرضُ تحتي مِن عِظَمِ الجَيشِ وكَثرَةِ العَسكرِ، فقلتُ في نفسي: أنا أَملِكُ الدُّنيا، وما يَقدِر أَحَدٌ عَلَيَّ، فعَجَّزَني الله تعالى بأَضعفِ خَلْقِه، وأنا أَستَغفِرُ الله تعالى، وأَستَقيلُه من ذلك الخاطرِ. فتُوفِّي عاشرَ رَبيعٍ الأوَّلِ من السَّنَةِ، فحُمِلَ إلى مَرو ودُفِنَ عند أَبيهِ. تُوفِّي عن إحدى وأربعين سَنَةً، وكانت مُدَّةُ مُلكِه منذ خُطِبَ له بالسَّلْطَنَةِ إلى أن قُتِلَ تِسعَ سِنينَ وسِتَّةَ أَشهُر وأيامًا، ولمَّا وَصلَ خَبرُ مَوتِه إلى بغداد جَلسَ الوَزيرُ فَخرُ الدَّولةِ بن جهير للعَزاءِ به في صَحنِ السَّلامِ. تَركَ ألب أرسلان من الأولادِ ملكشاه، وإياز، ونكشر, وبوري برس, وأرسلان، وأرغو، وسارة، وعائشة، وبِنتًا أُخرى, وتَولَّى بعده ابنُه ملكشاه."},{"id":1637,"title":"مِلْكُ ملكشاه بن ألب أرسلان بعدَ مَوتِ أَبيهِ .","date":["العام الهجري :465","الشهر القمري : ربيع الأول","العام الميلادي :1072"],"text":"لمَّا جُرِحَ السُّلطانُ ألب أرسلان أَوصَى لابنِه ملكشاه، وكان معه، وأَمرَ أن يَحلِف له العَسكرُ، فحَلَفوا جَميعُهم، وكان المُتَوَلِّي للأَمرِ في ذلك نِظامُ المُلْكِ، وأَرسلَ ملكشاه إلى بغداد يَطلُب الخُطبةَ له، فخُطِبَ له على مَنابِرِها، وأَوصَى ألب أرسلان ابنَه ملكشاه أيضًا أن يُعطِي أَخاهُ قاروت بك بن داود أَعمالَ فارس وكرمان، وشَيئًا عَيَّنَهُ من المالِ، وأن يُزَوَّجَ بِزَوجَتِه، وكان قاروت بك بكرمان، وأَوصَى أن يُعطَى ابنَه إياز بن ألب أرسلان ما كان لأَبيهِ داودَ، وهو خمسمائة ألف دِينارٍ، وقال: كلُّ مَن لم يَرضَ بما أَوصَيتُ له فقاتِلُوهُ، واستَعينوا بما جَعلتُه له على حَربِه، وعاد ملكشاه من بِلادِ ما وراءَ النَّهرِ، فعَبرَ العَسكرُ الذي قَطعَ النَّهرَ في نَيِّفٍ وعشرين يومًا في ثلاثة أيامٍ، وقام بوِزارَةِ ملكشاه نِظامُ المُلْكِ، وزاد الأَجنادَ في مَعايِشِهم سبعَ مائةِ ألفِ دِينارٍ، وعادوا إلى خُراسان، وقَصَدوا نَيسابور، وراسَلَ ملكشاه جَماعةَ المُلوكِ أَصحابَ الأَطرافِ يَدعوهُم إلى الخُطبَةِ له والانقِيادِ إليه، وأَقامَ إياز أرسلان بِبَلخ وسار السُّلطانُ ملكشاه في عَساكرِه من نَيسابور إلى الرَّيِّ."},{"id":1638,"title":"استِيلاءُ مَلِكِ التكين صاحِبِ سَمرقَند على مَدينةِ تِرمِذ .","date":["العام الهجري :465","الشهر القمري : ربيع الآخر","العام الميلادي :1073"],"text":"مَلَكَ التكينُ صاحبُ سَمرقَند مَدينةَ تِرمِذ، وسَببُ ذلك أنَّه لمَّا بَلغَهُ وَفاةُ ألب أرسلان، وعَوْدُ ابنِه ملكشاه عن خُراسان، طَمِعَ في البِلادِ المُجاوِرَةِ له، فقَصدَ تِرمِذَ أوَّلَ رَبيعٍ الآخر، وفَتحَها، ونَقلَ ما فيها من ذَخائِر وغَيرِها إلى سَمرقَند."},{"id":1639,"title":"دُخولُ عَسكرِ غَزْنَةَ إلى سكلكند .","date":["العام الهجري :465","الشهر القمري : جمادى الأولى","العام الميلادي :1073"],"text":"وَردَت طائِفةٌ كَثيرةٌ من عَسكرِ غَزنةَ إلى سكلكند، وبها عُثمانُ عَمُّ السُّلطانِ ملكشاه، ويُلقَّب بأَميرِ الأُمراءِ، فأَخَذوهُ أَسيرًا، وعادوا به إلى غَزنةَ مع خَزائِنه وحَشَمِه، فسَمِعَ الأَميرُ كمشتين بلكابك، وهو من أَكابرِ الأُمراءِ، فتَبِعَ آثارَهُم، وكان معه أنوشتكين جَدُّ مُلوكِ خوارزم، فنَهَبوا مَدينةَ سكلكند."},{"id":1640,"title":"ارتفاع ماء دجلة وغَرَقُ بغدادَ .","date":["العام الهجري :466","العام الميلادي :1073"],"text":"غَرِقَ الجانبُ الشرقيُّ وبعضُ الغربيِّ من بغداد، وسَببُه أن دِجلَة زادت زِيادةً عَظيمةً، وانفَتَح القَوْرَجِ عند المُسَنَّاةِ المُعِزِّيَّةِ، وجاء في الليلِ سَيْلٌ عَظيمٌ، وطَفحَ الماءُ من البَرِّيَّةِ مع رِيحٍ شَديدةٍ، وجاء الماءُ إلى المنازِلِ من فَوق، ونَبعَ من البَلاليعِ والآبارِ بالجانبِ الشرقيِّ، وهَلَكَ خَلْقٌ كَثيرٌ تحت الهَدْمِ، وشُدَّت الزَّواريقُ تحتَ التَّاجِ خَوْفَ الغَرَقِ، وقام الخَليفةُ يَتَضرَّع ويُصلِّي، وعليه البُردَةُ، وبِيَدِه القَضيبُ، وأتى ايتكين السُّليمانيُّ من عُكبرا، فقال للوَزيرِ: إنَّ المَلَّاحِينَ يُؤذونَ الناسَ في المَعابِر فأَحضَرَهم، وتَهدَّدَهُم بالقَتْلِ، وأَمرَ بِأَخْذِ ما جَرَت به العادةُ، وأُقيمَت الخُطبةُ للجُمعةِ في الطَّيَّارِ -نوع من الزَّوارِق سَريع الجَرَيان- مَرَّتينِ، وغَرِقَ من الجانبِ الغربيِّ مَقبرةُ أَحمدَ بنِ حَنبل، ومَشهدُ بابِ التِّبْنِ، وتَهدَّم سُورُهُ، فأَطلَقَ شَرفُ الدولةِ ألفَ دِينارٍ تُصرَف في عِمارَتِه، ودَخلَ الماءُ من شَبابيكِ البيمارستان العَضُدِيِّ."},{"id":1641,"title":"مِلْكُ السُّلطانِ ملكشاه تِرمِذ والهُدْنَةُ بينه وبين صاحبِ سَمرقَند .","date":["العام الهجري :466","العام الميلادي :1073"],"text":"إنَّ خاقان التكين صاحبَ سَمرقَند مَلَكَ تِرمِذَ بعدَ قَتْلِ السُّلطانِ ألب أرسلان، فلمَّا استَقامَت الأُمورُ للسُّلطانِ ملكشاه سار إلى تِرمِذ وحَصرَها، وطَمَّ العَسكرُ خَندَقها، ورَماها بالمجانيقِ، فخافَ مَن بها، فطَلَبوا الأَمانَ فأَمَّنَهم، وخَرَجوا منها وسَلَّموها، وكان بها أَخٌ لِخَاقان التكين، فأَكرَمَه السُّلطانُ، وخَلَعَ عليه وأَحسنَ إليه وأَطلَقَه، وسَلَّمَ قَلعةَ تِرمِذ إلى الأَميرِ ساوتكين، وأَمرَهُ بعِمارَتِها وتَحصِينِها وعِمارَةِ سُورِها بالحَجَرِ المُحْكَمِ، وحَفْرِ خَندَقِها وتَعمِيقِه، ففَعلَ ذلك. وسارَ السُّلطانُ ملكشاه يُريدُ سَمرقَند، ففارَقَها صاحِبُها، وأَنفذَ يَطلُب المُصالَحَةَ، ويَضرَع إلى نِظامِ المُلْكِ في إجابَتِه إلى ذلك، ويَعتَذِر مِن تَعَرُّضِه إلى تِرمِذ، فأُجِيبَ إلى ذلك، واصطَلَحوا، وعاد ملكشاه عنه إلى خُراسان، ثم منها إلى الرَّيِّ، وأَقطعَ بَلْخ وطخارستان لأَخيهِ شِهابِ الدِّينِ تكش."},{"id":1642,"title":"استِعانَةُ ملكشاه بالمُنَجِّمِين .","date":["العام الهجري :467","العام الميلادي :1074"],"text":"جَمَعَ نِظامُ المُلْكِ، والسُّلطانُ ملكشاه، جَماعةً من أَعيانِ المُنَجِّمِين، وجَعَلوا النَّيْروزَ أَوَّلَ نُقطَةٍ من الحَمَل، وكان النَّيروزُ قبلَ ذلك عند حُلولِ الشمسِ نِصفَ الحُوتِ. وصار ما فَعلَه السُّلطانُ مَبدأَ التَّقاويمِ، وفيها أيضًا عُمِلَ الرَّصْدُ للسُّلطانِ ملكشاه، واجتَمعَ من أَعيانِ المُنَجِّمِينَ في عَمَلِه وخَرَجَ عليه من الأَموالِ شَيءٌ عَظيمٌ، وبَقِيَ الرَّصدُ دائِرًا إلى أن مات السُّلطانُ سَنةَ 485هـ، فبَطُلَ بعدَ مَوتِه."},{"id":1643,"title":"وُقوعُ حَربٍ بين بَنِي رِياحٍ وزُغبةَ ببِلادِ إفريقية .","date":["العام الهجري :467","العام الميلادي :1074"],"text":"وَقَعَت حَربٌ شَديدةٌ بين بَنِي رِياحٍ وزُغبةَ ببِلادِ إفريقية، فقَوِيَت بَنُو رِياحٍ على زُغبةَ فهَزَموهُم وأَخرَجوهُم عن البِلادِ, وهذه القَبائلُ هي التي شَجَّعَها المُستَنصِرُ بالله صاحبُ مصر العُبيديُّ سَنةَ 444هـ للانتِقالِ إلى أفريقية وأَطلَق يَدَها فيما تَحْتَلَّهُ من دِيارِها. نِكايةً بالمُعِزِّ بن باديس الصنهاجي الذي قَطعَ الخُطبةَ للمُستَنصِر العُبيديِّ وخَطبَ للخَليفةِ العبَّاسيِّ في أفريقية."},{"id":1644,"title":"وَفاةُ الخَليفةِ العبَّاسيِّ القائمِ بأَمرِ الله وتَوَلِّي حَفيدِه المُقتَدِي الخِلافَةَ .","date":["العام الهجري :467","الشهر القمري : شعبان","العام الميلادي :1075"],"text":"هو الخَليفةُ، أبو جَعفرٍ القائمُ بأَمرِ الله أَميرُ المؤمنين، عبدُ الله أبو جَعفرِ بن القادرِ بالله أبي العبَّاسِ أَحمدَ ابنِ الأَميرِ إسحاقَ بن المُقتَدِر بالله أبي الفَضلِ جَعفرِ بن المُعتَضِد بالله أبي العبَّاسِ أَحمدَ. وُلِدَ سَنةَ إحدى وتِسعينَ وثلاثِ مائة في نِصفِ ذي القعدةِ، وأُمُّهُ بَدرُ الدُّجَى الأرمنية. وقِيلَ: قَطْرُ النَّدَى، بَقِيَت إلى أَثناءِ خِلافَتِه. وكان مَليحًا وَسيمًا أَبيضَ بِحُمْرَةٍ، قَوِيَّ النَّفْسِ، دَيِّنًا وَرِعًا مُتصَدِّقًا. بُويِعَ يومَ مَوتِ أَبيهِ بِعَهْدٍ له منه في ذي الحجَّةِ، سَنةَ 422هـ. وله إحدى وثلاثون سَنةً، وأَبوهُ هو الذي لَقَّبَهُ: القائمَ بأَمرِ الله.  كان من خِيارِ بَنِي العبَّاسِ دِينًا واعتِقادًا ودَولَةً، وقد امتُحِنَ من بَينِهم بفِتنَةِ البساسيري التي اقتَضَت إخراجَه من دارِه ومُفارَقَتَه أَهلَه وأَولادَه ووَطَنَه، فأَقامَ بحديثة عانة سَنةً كامِلةً ثم أَعادَ الله تعالى نِعمَتَه وخِلافَتَه  على يَدِ السُّلطانِ طُغرلبك مَلِكِ الغُزِّ بعدَ أن استَنْهَضَه القائمُ. في صَفَر من هذه السَّنةِ مَرِضَ الخَليفةُ القائمُ بأَمرِ الله مَرضًا شَديدًا انتَفخَ منه حَلْقُه، وامتَنَع من الفَصْدِ، فلم يَزَل الوَزيرُ فَخرُ الدولةِ عليه حتى افتَصَدَ وانصَلَح الحالُ، وكان الناسُ قد انزَعَجوا ففَرِحوا بعافِيَتِه وفي شَعبانَ انفَجرَ فَصادُه، وخَرجَ منه دَمٌ كَثيرٌ ولم يَشعُر، فاستَيقظَ وقد ضَعُفَ وسَقطَت قُوَّتُه، فأَيقَنَ بالمَوتِ، فأَحضَر وَلِيَّ العَهْدِ، ووَصَّاهُ بوَصايا، وأَحضرَ النَّقيبين وقاضي القُضاةِ وغَيرَهم مع الوَزيرِ ابن جهير، وأَشهَدهُم على نَفسِه أنَّه جَعلَ ابنَ ابنِه أبا القاسمِ عبدَ الله بن محمدِ بن القائمِ بأَمرِ الله وَلِيَّ عَهْدِه, ولَقَّبَه: بالمُقتَدِي بأَمرِ الله، وكان أَبوهُ الذَّخيرَةُ محمدُ بن القائمِ قد تُوفِّي أيامَ القائمِ، ولم يكُن له غَيرُه، فأَيقنَ الناسُ بانقِراضِ نَسلِ القائمِ، وانتِقالِ الخِلافَةِ من البيتِ القادريِّ. وكان للذَّخيرَةِ جارِيةٌ تُسَمَّى أرجوان، فلمَّا ماتَ، ورَأَت أَباهُ قد جَزعَ ذَكرَت له أنَّها حامِلٌ، فتَعَلَّقَت الآمالُ بذلك الحَمْلِ. فوَلدَت هذا بعدَ مَوتِ أَبيهِ بسِتَّةِ أَشهُرٍ، فاشتَدَّ سُرورُ القائمِ به، وبالَغَ في الإشفاقِ عليه والمَحَبَّةِ له. وكان ابنَ أربعِ سِنين في فِتنَةِ البساسيري، فأَخفاهُ أَهلَهُ، وحَملَهُ أبو الغَنائمِ بن المحلبان إلى حرَّان، ولمَّا عاد القائمُ إلى بغداد أُعِيدَ المُقتدي، فلمَّا بَلغَ الحُلُمَ جَعلَهُ وَلِيَّ عَهْدِه، ولمَّا تُوفِّي القائمُ غَسَّلَهُ الشَّريفُ أبو جَعفرِ بن أبي موسى الهاشميُّ، وصلَّى عليه أبو القاسمِ المُقتدِي بأَمرِ الله، وكانت خِلافتُه أَربعًا وأَربعين سَنةً وثمانيةَ أَشهُر وأيامًا، ولمَّا تُوفِّي القائمُ بأَمرِ الله بُويِعَ المُقتدِي بأَمرِ الله عبدُ الله بن محمدِ بن القائمِ بالخِلافَةِ، وحَضرَ مُؤَيِّدُ المُلْكِ بن نِظامِ المُلْكِ، والوَزيرُ فَخرُ الدولةِ بن جهير وابنُه عَميدُ الدولةِ، والشيخُ أبو إسحاقَ، وأبو نَصرِ بن الصَّبَّاغِ، ونَقيبُ النُّقَباءِ طراد، والنَّقيبُ الطاهِرُ المعمر بن محمدٍ، وقاضي القُضاةِ أبو عبدِ الله الدَّامغاني، وغَيرُهم من الأَعيانِ والأماثِل، فبَايَعُوهُ، وقِيلَ: كان أَوَّلَ مَن بايَعهُ الشَّريفُ أبو جَعفرِ بن أبي موسى الهاشميُّ."},{"id":1645,"title":"أَمْرُ المُقتدِي بأَمرِ الله بإزالَةِ المُنكَراتِ في بغداد .","date":["العام الهجري :467","الشهر القمري : شعبان","العام الميلادي :1075"],"text":"كان مِن أَوَّلِ أَعمالِ المُقتدِي بأَمرِ الله أنَّه أَمَرَ بإخراجِ المُفْسِداتِ مِن الخَواطِئ من بغداد، وأَمَرَهُنَّ أن يُنادِينَ على أَنفُسِهِنَّ بالعارِ والفَضيحَةِ، وخَرَّبَ الخَمَّاراتِ ودُورَ الزَّوانِي والمَغانِي، وأَسكنَهُنَّ الجانِبَ الغَربيَّ مع الذُّلِّ والصَّغارِ، وخَرَّبَ أبرجةَ الحمامِ، ومَنعَ اللَّعِبَ بها، وأَمرَ الناسَ باحتِرازِ عَوراتِهِم في الحَمَّاماتِ ومَنعَ أَصحابَ الحَمَّاماتِ أن يَصرِفوا فَضَلاتِها إلى دِجلَة، وأَلزَمَهم بحَفْرِ آبارٍ لتلك المِياهِ القَذِرَة صِيانةً لماءِ الشُّرْبِ."},{"id":1646,"title":"حُدوثُ نِيرانٍ عَظيمةٍ في سوق بغداد .","date":["العام الهجري :467","الشهر القمري : شوال","العام الميلادي :1075"],"text":"في شوَّال وَقعَت نارٌ ببغداد في دُكَّانِ خَبَّازٍ بِنَهْرِ المُعَلَّى، فاحتَرقَت من السُّوقِ مائةٌ وثمانون دُكَّانًا سِوى الدُّورِ، ثم وَقعَت نارٌ في المَأمونِيَّة، ثم في الظَّفَرِيَّة، ثم في دَربِ المَطبَخِ، ثم في دارِ الخَليفَةِ، ثم في حَمَّامِ السمرقندي، ثم في بابِ الأزج ودَربِ خُراسان، ثم في الجانبِ الغربيِّ في نَهرِ طابق، ونَهرِ القلائين، والقطيعة، وبابِ البَصرَةِ، واحتَرقَ ما لا يُحصَى"},{"id":1647,"title":"إِعادةُ الخُطبَةِ بمَكَّةَ للمُستَنصِر بالله العُبيديِّ (الفاطِميِّ) .","date":["العام الهجري :467","الشهر القمري : ذي الحجة","العام الميلادي :1075"],"text":"أَرسلَ المُستَنصِرُ بالله الفاطِميُّ صاحبُ مصر، إلى صاحبِ مَكَّةَ ابنِ أبي هاشمٍ رِسالةً وهَدِيَّةً جَليلةً، وطَلبَ منه أن يُعيدَ له الخُطبةَ بمَكَّةَ، وقال: إن أَيْمانَك وعُهودَك كانت للقائمِ، وللسُّلطانِ ألب أرسلان، وقد ماتَا، فخَطَبَ به بمَكَّةَ وقَطعَ خُطبةَ المُقتَدِي، وكانت مُدَّةُ الخُطبَةِ العبَّاسيَّة بمَكَّةَ أربعَ سنين وخَمسةَ أَشهُر."},{"id":1648,"title":"النِّزاعُ بين مُلوكِ الطَّوائفِ على حُكمِ مُدُنِ الأندَلُسِ .","date":["العام الهجري :468","العام الميلادي :1075"],"text":"قام أبو بكرٍ محمدُ بن عبدِالعزيزِ المَنصورُ نائبُ يحيى المَأمونِ بن ذي النُّونِ في بلنسية بإعلانِ استِقلالِه فيها بعدَ أن بَلَغَه وَفاةُ يحيى المَأمونِ، وقام بمُحالَفَةِ ألفونسو السادس مَلِكِ قشتالة وليون وجيليقية مُقابِلَ دَفْعِ جِزْيَةٍ له، كما قام المُعتَمِدُ بن عبَّادٍ بانتِهازِ وَفاةِ يحيى المَأمونِ لِيُغِيرَ على قُرطُبة ويَستَولِي عليها ويَقتُل حاكِمَها ابنَ عُكاشةَ، وكان المأمونُ قد وَلَّاهُ عليها حينما احتَلَّها السَّنَةَ الماضيةَ وقَتَلَ الفَتحَ بنَ المُعتَمِد، أمَّا أحمدُ بن سُليمانَ بن هود أَميرُ سرقسطة والثغر الأعلى فاستَولَى على دانية وقَضَى على الدولةِ المُجاهِديَّة التي أَسَّسَها عامرٌ المُجاهِديُّ، وحَمَلَ أَميرَها عليَّ بنَ مُجاهدٍ إلى سرقسطة، وأمَّا عليٌّ المُرتَضَى أَميرُ الجزائرِ الشرقيَّةِ البليار فقد أَعلَن استِقلالَهُ فيها بعدَ سُقوطِ دانية بِيَدِ المُقتَدِر أحمدَ بنِ سُليمانَ بن هود."},{"id":1649,"title":"وَباءٌ وجَرادٌ وغَلاءٌ بِدِمَشقَ .","date":["العام الهجري :468","الشهر القمري : شعبان","العام الميلادي :1076"],"text":"جاء جَرادٌ في شَعبانَ بعَددِ الرَّملِ والحَصَا، فأَكلَ الغَلَّاتِ وآذَى الناسَ، وجاعوا فطُحِنَ الخَرُّوبُ بِدَقيقِ الدُّخْنِ فأَكلوهُ، ووَقعَ الوَباءُ، ثم مَنعَ اللهُ الجَرادَ من الفَسادِ، وكان يَمُرُّ ولا يَضُرُّ، فرَخُصَت الأَسعارُ، ووَقعَ غَلاءٌ شَديدٌ بدِمشق واستَمرَّ ثلاثَ سِنين."},{"id":1650,"title":"السَّلاجِقَةُ يُسيطِرونَ على الشامِ ودِمشقَ .","date":["العام الهجري :468","الشهر القمري : ذي القعدة","العام الميلادي :1076"],"text":"في سَنةِ 463هـ مَلَكَ أتسز الرَّمْلَةَ، والبيتَ المُقدَّسَ، وحَصرَ مَدينةَ دِمشقَ، فلمَّا عادَ عنها جَعلَ يَقصِد أَعمالَها كلَّ سَنةٍ عند إدراكِ الغَلَّاتِ فيَأخُذها، فيَقوَى هو وعَسكرُه، ويَضعُف أَهلُ دِمشقَ وجُندُها، فلمَّا كان رَمضانُ سَنةَ 467هـ سار إلى دِمشقَ فحَصرَها، وأَميرُها المُعَلَّى بن حَيدرَة مِن قِبَلِ المُستَنصِر العُبيدي صاحبِ مصر، فلم يَقدِر عليها، فانصَرفَ عنها في شوَّال، فهَربَ أَميرُها المُعلَّى في ذي الحجَّةِ، وكان سببُ هَرَبِه أنَّه أَساءَ السِّيرَةَ مع الجُنْدِ والرَّعِيَّةِ وظَلَمَهم، فكَثُرَ الدُّعاءُ عليه، وثار به العَسكرُ، وأَعانَهُم العامَّةُ، فهَرَبَ منها إلى بانياس، ثم منها إلى صور، ثم أُخِذَ إلى مصر فحُبِسَ بها، فماتَ مَحبوسًا، فلمَّا هَربَ من دِمشقَ اجتَمعَت المصامدة -والمصامدة قَبيلَة من المَغارِبَة- ووَلَّوْا عليهم انتِصارَ بنَ يحيى المَصموديَّ، المَعروف برَزِينِ الدَّولةِ، وغَلَت الأَسعارُ بها حتى أَكلَ الناسُ بَعضُهم بَعضًا، ووَقعَ الخُلْفُ بين المصامدة وأَحداثِ البَلدِ، وعَرفَ أتسز ذلك، فعادَ إلى دِمشقَ، فنَزلَ عليها في شَعبانَ من هذه السَّنَةِ، فحَصرَها، فعُدِمَت الأَقواتُ، فبِيعَت الغرارة، إذا وُجِدَت، بأَكثرَ من عِشرين دِينارًا، فسَلَّموها إليه بأَمانٍ، وعوض عنها بقَلعَةِ بانياس، ومَدينةِ يافا من الساحِلِ، ودَخلَها هو وعَسكرُه في ذي القعدةِ، وخَطَبَ بها يومَ الجُمعةِ لخَمسٍ بَقِينَ من ذي القعدةِ، للمُقتدِي بأَمرِ الله الخَليفةِ العبَّاسيِّ، وكان آخرَ ما خُطِبَ فيها للعَلويِّينَ المِصريِّينَ، ومَنَعَ الأذانَ بحيَّ على خَيرِ العَمَلِ، ففَرِحَ أَهلُها به فَرَحًا عَظيمًا، وتَغَلَّبَ على أَكثرِ الشامِ وعَظُمَ شَأنُه، وخافَهُ المِصريُّونَ، وظَلَمَ أَهلَها، وأَساءَ السِّيرَةَ فيهم. حتى أَهلَكَ الناسَ وأَفقَرَهُم."},{"id":1651,"title":"طَرْدُ الرُّومِ مِن مَدينةِ منبج .","date":["العام الهجري :468","الشهر القمري : ذي القعدة","العام الميلادي :1076"],"text":"مَلَكَ نَصرُ بن محمودِ بن صالحِ بن مرداس مَدينةَ منبج، وأَجلَى عنها الرُّومَ."},{"id":1652,"title":"ابتِداءُ عِمارَةِ قَلعةِ دِمشقَ .","date":["العام الهجري :469","العام الميلادي :1076"],"text":"لما انتَزعَ المَلِكُ المُعَظَّمُ أتسز بن أوف الخوارزمي دِمشقَ من أَيدِي العُبيديِّين سَنةَ 468هـ، شَرعَ في بِناءِ هذا الحِصْنِ المَنيعِ بدِمشقَ وكان في مكانِ القَلعةِ -أَحَدِ أَبوابِ البَلدِ- بابٌ يُعرفُ ببابِ الحَديدِ، وهو البابُ المُقابلُ لدارِ رضوان، وقد ارتَفعَ بعضُ أَبرجتِها فلم يتَكامل حتى انتَزعَ مُلْكَ البَلدِ منه المَلِكُ المُظفَّرُ تاجُ المُلوكِ تتش بن ألب أرسلان السلجوقي، فأَكمَلَها وأَحسنَ عِمارَتَها، وابتَنَى بها دارَ رضوان للمُلْكِ، واستَمرَّت على ذلك البِناءِ في أيامِ نورِ الدِّين محمودِ بن زِنكي، فلمَّا كان المَلِكُ صَلاحُ الدِّينِ بن يُوسفَ بن أيوبَ الأيوبيُّ جَدَّدَ فيها شَيئًا، وابتَنَى له نائِبُه ابنُ مُقدَّمٍ فيها دارًا هائِلةً لمملكة للمَملكةِ، ثم إنَّ المَلِكَ العادلَ أخا صلاحِ الدِّينِ، اقتَسمَ هو وأولادُه أَبرجتَها، فبَنَى كلُّ مَلِكٍ منهم بُرْجًا منها جَدَّدَهُ وعَلَّاهُ وأَطَّدَهُ وأَكَّدَهُ، ثم جَدَّدَ المَلِكُ الظَّاهِرُ بِيبَرسُ منها البُرجَ الغربيَّ القِبليَّ، ثم ابتَنَى بعده في دَولةِ المَلِكِ الأَشرفِ خليلِ بن المنصورِ، نائِبُه الشُّجاعيُّ، الطارمةَ الشماليَّةَ والقُبَّةَ الزَّرقاءَ وما حولَها."},{"id":1653,"title":"مُحاولةُ أتسز الخوارزميِّ انتِزاعَ مصر مِن العُبيديِّينَ  .","date":["العام الهجري :469","العام الميلادي :1076"],"text":"سار أتسز –ويُقال: أقسيس- الخوارزميُّ التُّركيُّ من دِمشقَ إلى مصر وحَصرَها، وضَيَّقَ على أَهلِها، ولم يَبقَ غير أن يَملِكَها، فاجتَمعَ أَهلُها مع ابنِ الجوهريِّ الواعظِ في الجامعِ، وبَكَوا وتَضرَّعوا ودَعَوا، فانهَزمَ أتسز من غيرِ قِتالٍ، فوَصلَ إلى دِمشقَ وقد تَفرَّق أَصحابُه، فرَأَى أَهلَها قد صانوا مُخَلَّفِيهِ وأَموالَه، فشَكرَهُم، ورَفعَ عنهم الخَراجَ تلك السَّنَةَ، وأَتَى البَيتَ المُقدَّسَ، فرَأَى أَهلَه قد قَبَّحُوا على أَصحابِه ومُخَلَّفِيهِ، وحَصَروهُم في مِحرابِ داودَ، عليه السَّلامُ، فلمَّا قارَبَ البلدَ تَحصَّن أَهلُه منه وسَبُّوهُ، فقاتَلَهم، ففَتحَ البلدَ عُنوةً ونَهَبَهُ، وقَتلَ مِن أَهلِه فأَكثَرَ حتى قَتَلَ مَن التَجأَ إلى المَسجدِ الأقصى، وكَفَّ عمَّن كان عند الصَّخرةِ وَحدَها. وقِيلَ: إن أتسز لمَّا وَصلَ مصر, جَمعَ أَميرَ الجُيوشِ بَدرَ العَساكرِ، واستَمدَّ العَربَ وغيرَهم من أَهلِ البِلادِ، فاجتَمعَ معه خَلْقٌ كَثيرٌ، واقتَتَلوا، فانهَزمَ أتسز، وقُتِلَ أَكثرُ أَصحابِه، وقُتِلَ أَخٌ له، وقُطِعَت يَدُ أَخٍ آخرَ، وعادَ مُنهزِمًا إلى الشامِ في نَفَرٍ قَليلٍ من عَسكرِه، فوَصلَ إلى الرَّملةِ، ثم سار منها إلى دِمشقَ، وقِيلَ: إن أتسز انهَزمَ في مصر وعاد منها بدون قِتالٍ."},{"id":1654,"title":"وُقوعُ فِتنَةٍ بين الحَنابِلَةِ وفُقَهاءِ النِّظامِيَّةِ  الأَشاعِرَةِ في بغداد .","date":["العام الهجري :469","العام الميلادي :1076"],"text":"قَدِم ابنُ القُشيريُّ بغدادَ فجَلسَ يَتكلَّم في النِّظاميَّةِ وأَخذَ يَذُمُّ الحَنابلةَ ويَنسُبُهم إلى التَّجسِيمِ، وساعَدهُ أبو سعدٍ الصُّوفيُّ، ومالَ معه الشيخُ أبو إسحاقَ الشِّيرازيُّ، وكَتبَ إلى نِظامِ المُلْكِ يَشكُو إليه الحَنابلةَ ويَسأَلُه المَعونةَ عليهم، وذَهبَ جَماعةٌ إلى الشَّريفِ أبي جَعفرِ بن أبي موسى شَيخِ الحَنابلةِ، وهو في مَسجدِه فدافَعَ عنه آخرون، واقتَتَل الناسُ بسَببِ ذلك، وقُتِلَ رَجلٌ خَيَّاطٌ من سُوقِ التِّبنِ، وجُرِحَ آخرون، وثارَت الفِتنةُ بين الحَنابلَةِ وبين فُقهاءِ النِّظاميَّةِ، وحَمِيَ لكلٍّ مِن الفَريقينِ طائفةٌ من العوامِّ، وقُتِلَ بينهم نحوٌ من عِشرينَ قَتيلًا، وكَتبَ الشيخُ أبو إسحاقَ وأبو بكرٍ الشاشيُّ إلى نِظامِ المُلْكِ في كِتابِه إلى فَخرِ الدولةِ يُنكِر ما وَقعَ، ويَكرَهُ أن يُنسَب إلى المَدرسةِ التي بناها شيءٌ من ذلك، وعَزمَ الشيخُ أبو إسحاقَ على الرِّحلَةِ من بغدادَ غَضَبًا ممَّا وَقعَ من الشَّرِّ، فأَرسلَ إليه الخَليفةُ يُسَكِّنُهُ، ثم جَمعَ بينه وبين الشَّريفِ أبي جعفرٍ وأبي سعدٍ الصُّوفيِّ، وأبي نصرِ بنِ القُشيريِّ، عند الوَزيرِ، فأَقبلَ الوَزيرُ على أبي جعفرٍ يُعَظِّمُهُ في الفِعالِ والمَقالِ، وقام إليه الشيخُ أبو إسحاقَ فقال: أنا ذلك الذي كنتَ تَعرِفُه وأنا شابٌّ، وهذه كُتُبِي في الأُصُولِ، ما أقولُ فيها خِلافًا للأَشعَرِيَّةِ. ثم قَبَّلَ رَأسَ أبي جَعفرٍ، فقال له أبو جَعفرٍ: صَدقتَ، إلَّا أنَّك لمَّا كُنتَ فَقيرًا لم تُظهِر لنا ما في نَفسِك، فلمَّا جاءَ الأَعوانُ والسُّلطانُ وخواجه بزك - يعني نِظام المُلْكِ- وشَبِعتَ، أَبدَيتَ ما كان مُختَفِيًا في نَفسِك، وقام الشيخُ أبو سعدٍ الصُّوفيُّ وقَبَّلَ رَأسَ الشَّريفِ أبي جَعفرٍ أيضًا وتَلطَّفَ به، فالتَفتَ إليه مُغضَبًا وقال: أيها الشيخُ، أمَّا الفُقهاءُ إذا تَكلَّموا في مَسائلِ الأُصولِ فلهم فيها مَدخَلٌ، وأمَّا أنت فصاحِبُ لَهْوٍ وسَماعٍ وتَغْبِيرٍ، فمَن زاحَمَكَ مِنَّا على باطلِك؟! ثم قال: أيها الوَزيرُ أَنَّى تُصلِح بيننا؟ وكيف يَقعُ بيننا صُلْحٌ ونحن نُوجِبُ ما نَعتَقِدُه وهُم يُحَرِّمُون ويُكَفِّرُون؟! وهذا جَدُّ الخَليفةِ القائم والقادر قد أَظهرَا اعتِقادَهُما للناسِ على رُؤوسِ الأَشهادِ على مَذهبِ أَهلِ السُّنَّةِ والجَماعةِ والسَّلَفِ، ونحن على ذلك كما وَافقَ عليه العِراقِيُّونَ والخُراسانِيُّونَ، وقُرِئَ على الناسِ في الدَّواوينِ كلِّها، فأَرسلَ الوَزيرُ إلى الخَليفةِ يُعلِمُه بما جَرَى، فجاءَ الجَوابُ بِشُكرِ الجَماعةِ وخُصوصًا الشَّريفَ أبا جَعفرٍ، ثم استَدعَى الخَليفةُ أبا جَعفرٍ إلى دارِ الخِلافةِ للسلامِ عليه، والتَّبَرُّكِ بِدُعائِه."},{"id":1655,"title":"ابتِداءُ دَولةِ بَيتِ خوارزم شاه\n  .","date":["العام الهجري :470","العام الميلادي :1077"],"text":"كان أَوَّلَهم محمدُ خوارزم شاه بن أنوشتكين، وكان أنوش تكين مَملوكًا لِرَجلٍ من غرشتان ولذلك قِيلَ له: أنوش تكين غرشه، فاشتَراهُ منه أَميرٌ من السَّلجوقيَّة اسمُه بلكابل، وكان أنوشتكين حَسَنَ الطَّريقةِ فكَبُرَ وعَلَا مَحِلُّهُ، وصار أنوشتكين مُقَدَّمًا مَرجُوعًا إليه، ووُلِدَ له محمد خوارزم شاه المذكور، فرَبَّاهُ والِدُه أنوشتكين وأَحسَنَ تَأدِيبَه، فانتَشَأ محمدٌ عارِفًا أَدِيبًا، وتَقدَّم بالعِنايَةِ الأَزَلِيَّةِ، واشتُهِرَ بالكِفايَةِ وحُسْنِ التَّدبيرِ، فلمَّا قَدِمَ الأَميرُ داذا الحبشيُّ إلى خُراسان وهو مِن أُمراءِ بركيارق؛ كان قد أَرسلَهُ بركيارق لِتَهدِئَةِ أَمرِ خُراسان؛ بسَببِ فِتنَةٍ كانت قد وَقعَت فيها من الأَتراكِ، قُتِلَ فيها النائِبُ علي خوارزم، فوَصلَ داذا وأَصلحَ أَمرَ خوارزم، واستَعملَ على خوارزم في هذه السَّنَةِ محمدَ بن أنوشتكين المذكورَ، ولَقَّبَهُ خوارزم فقَصَرَ محمدٌ أَوقاتَهُ على مَعْدَلَةٍ يَنشُرُها ومَكْرَمَةٍ يَفعلُها، وقَرَّبَ أَهلَ العِلمِ والدِّينِ، فَعَلَا مَحِلُّهُ وعَظُمَ ذِكرُه، ثم أَقَرَّهُ السُّلطانُ سنجر على وِلايَةِ خوارزم، وعَظُمَت مَنزِلَةُ محمد خوارزم شاه المذكور عند السُّلطانِ سنجر، ولمَّا تُوفِّي خوارزم شاه محمد، وَلِيَ بعدَه ابنُه أطسز فمَدَّ غِلالَ الأَمنِ وأَفاضَ العَدلَ."},{"id":1656,"title":"نِهايةُ دَولةِ القَرامِطَةِ وقيام الدَّولةُ العيونيَّةُ مكانها .","date":["العام الهجري :470","العام الميلادي :1077"],"text":"انتَصرَ عليهم عبدُ الله العيوني بمُساعدَةِ العبَّاسيِّين والسَّلاجِقَةِ فأَخرَجَهُم من أوال ثم من البَحرَيْنِ، وأخيرًا حَدثَت في الأَحساءِ مَعركةُ الخَندَقِ فقَضَت على دَولةِ القَرامِطَةِ نِهائِيًّا، وحَلَّت مَحِلَّها الدَّولةُ العيونيَّةُ.  والعيوني، مِن بَنِي عبدِ القَيْسِ: رَأسُ العيونيين في الأَحساءِ، نَشأَ بها، في مشارف \"العيون\" ونِسْبَتُه إليها. وأَدرَك ضَعْفَ القِرامِطَةِ فيها، فاتَّصلَ ببغداد (سَنةَ 466هـ) وشَرحَ أَمرَهم لِجَلالِ الدَّولةِ أبي الفَتحِ ملكشاه السلجوقي، والخَليفةُ يومئذٍ أبو جَعفرٍ القائمُ بأَمرِ الله، والوَزيرُ أبو عليٍّ الحَسنُ بن عليِّ بن إسحاقَ نِظامُ المُلْكِ.وقد وَرَدَ كِتابُ ارتق بك على الخَليفةِ المُقتَدِي العبَّاسيِّ بأَخْذِه بِلادَ القَرامِطَة."},{"id":1657,"title":"وَفاةُ الشَّريفِ أبي جَعفرِ بن أبي موسى الهاشميِّ الفَقيهِ الحَنبليِّ .","date":["العام الهجري :470","العام الميلادي :1077"],"text":"هو الفَقيهُ العالِمُ، إِمامُ الحَنابِلَةِ، الشَّريفُ أبو جَعفرٍ عبدُ الخالقِ بن عيسى بن أحمدَ بن محمدِ بن عيسى بن أحمدَ بن موسى بن محمدِ بن إبراهيمَ بن عبدِ الله بن معبدِ بن العبَّاسِ بن عبدِ المُطَّلِبِ, الهاشميُّ الفَقيهُ. إِمامُ الطائفةِ الحَنبليَّةِ في زَمانِه بلا مُدافَعَةٍ. وُلِدَ سَنةَ 411هـ, وهو أَجَلُّ أَصحابِ القاضي أبي يَعلَى. كان حَسَنَ الكَلامِ في المُناظَرَةِ، وَرِعًا زاهِدًا، مُتقِنًا، عالِمًا بأَحكامِ القُرآنِ والفَرائضِ، مَرْضِيَّ الطَّريقةِ. وقال أبو الحُسينِ بن الفَرَّاءِ: \"لَزِمتُه خمسَ سنين، فكان إذا بَلغَهُ مُنكرٌ قد ظَهرَ عَظُمَ ذلك عليه جِدًّا، وكان شَديدًا على المُبتَدِعَةِ، لم تَزَل كَلِمتُه عاليةً عليهم، وأَصحابُه يَقمَعونَهُم، ولا يَرُدُّ يَدَهُ عنهم أَحَدٌ\"، وكان عَفيفًا نَزيهًا، يُدَرِّسُ بمَسجِدِه، ثم انتَقلَ إلى الجانبِ الشرقيِّ من بغداد يُدَرِّسُ في مَسجدٍ آخرَ، ثم انتَقلَ في سَنةِ 466هـ لأَجلِ ما لَحِقَ نَهرَ المُعَلَّى من الغَرَقِ إلى بابِ الطَّاقِ، ودَرَّسَ بجامعِ المَهديِّ. لمَّا احتَضرَ القاضي أبو يَعلَى أَوصَى أن يُغَسِّلَهُ الشَّريفُ أبو جَعفرٍ، ولمَّا احتَضرَ القائمُ بأَمرِ الله أَوصَى أيضًا أن يُغَسِّلَهُ، ففَعَلَ. وكان قد وَصَّى له القائمُ بأَمرِ الله بأَشياءَ كَثيرةٍ، فلم يَأخُذها، فقِيلَ له: خُذْ قَميصَ أَميرِ المُؤمنينَ للبَركةِ، فأَخذَ فُوطَتَه فنَشَّفَ بها القائمَ، وقال: قد لَحِقَ الفُوطةَ بَركةُ أَميرِ المُؤمنينَ. ثم استَدعاهُ المُقتَدِي، فبايَعَهُ مُنفرِدًا. ولمَّا تُوفِّي كان يومُ جَنازَتِه يومًا مَشهودًا، وحُفِرَ له إلى جانبِ قَبرِ الإمامِ أحمدَ، ولَزِمَ الناسُ قَبرَهُ ليلًا نَهارًا، حتى قِيلَ: خُتِمَ على قَبرِه أَكثرُ من عشرةِ آلافِ خَتمَةٍ. قال الذهبيُّ: \"وطَوَّلَ تَرجمتَه ابنُ الفَرَّاءِ إلى أن قال فيها: وأُخِذَ الشَّريفُ أبو جعفرِ بن أبي موسى في فِتنَةِ أبي نصرِ بن القُشيريِّ، وحُبِسَ أيامَا، فسَرَدَ الصَّومَ وقال: ما آكلُ لأَحَدٍ شَيئًا. ودَخلتُ عليه في تلك الأيامِ، فرَأيتُه يقرأُ في المُصحفِ، فقال لي: قال الله تعالى: {واستعينوا بالصبر والصلاة} الصَّبْرُ: الصَّوْمُ. ولم يُفطِر إلى أن بَلغَ منه المَرضُ، فلمَّا ثَقُلَ وضَجَّ الناسُ من حَبسِه، أُخرِجَ إلى الحَريمِ الطَّاهريِّ، فمات هناك\" قال عنه ابنُ كَثيرٍ: \"كان أَحدَ الفُقهاءِ العُلماءِ العُبَّادِ الزُّهَّادِ المَشهورِينَ بالدِّيانَةِ والفَضلِ والعِبادةِ والقِيامِ في الله بالأَمرِ بالمعروفِ والنهيِ عن المُنكرِ، لا تَأخذُه في الله لَوْمَةُ لائمٍ، وكان مَشهورًا بالصَّلاحِ والدِّيانةِ، وحين وَقعَت الفِتنةُ بين الحَنابلةِ والأَشعريَّةِ بسَببِ ابنِ القُشيريِّ اعتُقِلَ هو في دارِ الخِلافةِ مُكَرَّمًا مُعَظَّمًا، يَدخلُ عليه الفُقهاءُ وغَيرُهم، ويُقبِّلون يَدَهُ ورَأسَه\"."},{"id":1658,"title":"وَفاةُ الإمام ابنِ مَنْدَه .","date":["العام الهجري :470","العام الميلادي :1077"],"text":"هو الشيخُ، الإمامُ، المُحَدِّثُ، المُفِيدُ، الكَبيرُ، المُصَنِّفُ، أبو القاسمِ عبدُ الرحمن بن الحافظِ الكَبيرِ أبي عبدِ الله  محمدِ بن إسحاقَ بن محمدِ بن يحيى بن إبراهيمَ بن أبي عبدِ الله بن مَنده  العَبدِيُّ الأصبهانيُّ. وُلِدَ سَنةَ 381هـ. سَمِعَ أَباهُ وابنَ مَرْدَوَيْهِ وخَلْقًا في أقاليمَ شَتَّى، سافَر إليها وجَمعَ شَيئًا كَثيرًا، وكان ذا وَقارٍ وسَمْتٍ حَسَنٍ، واتِّباعٍ للسُّنَّةِ وفَهْمٍ جَيِّدٍ، كَثيرَ الأَمرِ بالمَعروفِ والنَّهيِ عن المُنكرِ، لا يَخافُ في الله لَوْمَةَ لائِمٍ، وكان صاحِبَ خُلُقٍ وفُتُوَّةٍ وسَخاءٍ وبَهاءٍ، وكانت الإجازةُ عنده قَوِيَّةً، وكان يقول: \"ما حَدَّثتُ بحَديثٍ إلَّا على سَبيلِ الإجازَةِ كَيْلَا أُوبَق\". وله تَصانيفُ كَثيرةٌ، ورُدودٌ على المُبتَدِعَةِ وكان سعدُ الزنجانيُّ يقول: حَفِظَ الله الإسلامَ بهِ، وبعبدِ الله الأنصاريِّ الهَرويِّ\"، كان عبدُ الرحمن بن مَندَه يقول: \"قد عَجِبتُ من حالي، فإنِّي قد وَجدتُ أَكثرَ من لَقيتُه إنْ صَدَّقتُه فيما يقوله مُداراةً له؛ سَمَّاني مُوافِقًا، وإنْ وَقفتُ في حَرفٍ مِن قَولِه أو في شيءٍ مِن فِعلِه؛ سَمَّاني مُخالِفًا، وإنْ ذَكرتُ في واحدٍ منهما أنَّ الكِتابَ والسُّنَّةَ بخِلافِ ذلك سَمَّاني خارِجِيًّا، وإنْ قُرئَ عليَّ حَديثٌ في التَّوحيدِ؛ سَمَّاني مُشَبِّهًا، وإنْ كان في الرُّؤْيَةِ؛ سَمَّاني سالِمِيًّا..., وأنا مُتَمسِّكٌ بالكِتابِ والسُّنَّةِ، مُتَبَرِّئٌ إلى الله مِن الشَّبَهِ والمِثْلِ والنِّدِّ والضِّدِّ والأعضاءِ والجِسْمِ والآلاتِ، ومِن كلِّ ما يَنسُبهُ النَّاسِبون إليَّ، ويَدَّعِيه المُدَّعونَ عليَّ من أنْ أَقولَ في الله تعالى شَيئًا من ذلك، أو قُلتهُ، أو أَراهُ، أو أَتَوَهَّمهُ، أو أَصِفهُ به\" قال يحيى بن مَندَه: \"كان عَمِّي سَيْفًا على أَهلِ البِدَعِ، وهو أَكبرُ من أن يُثنِي عليه مِثلي، كان والله آمِرًا بالمعروفِ، ناهِيًا عن المُنكرِ، كَثيرَ الذِّكْرِ، قاهرًا لِنَفسِه، عَظيمَ الحِلْمِ، كَثيرَ العِلمِ\"، تُوفِّي بأصبهان عن سبعٍ وثمانين سَنةً، وحَضرَ جَنازتُه خَلْقٌ كَثيرٌ لا يَعلمُهم إلَّا الله عزَّ وجلَّ."},{"id":1659,"title":"السُّلطانِ تُتُش أرسلان يمتلك دِمشقَ ومَقتلُ مَلِكِها أتسز الخوارزميِّ .","date":["العام الهجري :471","العام الميلادي :1078"],"text":"أَقطعَ السُّلطانُ ملكشاه أَخاهُ تاجَ الدولةِ تتش الشامَ، وما يَفتَحُه في تلك النَّواحي، سَنةَ 470هـ، فأَتَى حَلَب وحَصرَها، ولَحِقَ أَهلَها مَجاعةٌ شَديدةٌ، وكان معه جَمعٌ كَثيرٌ من التُّركمان، فأَنفذَ إليه أتسز صاحِبُ دِمشقَ، يَستَنجِدُه، ويُعرِّفُه أن عَساكِرَ مصر قد حَصرَتهُ بدِمشقَ، وكان أَميرُ الجُيوشِ بَدرٌ قد سَيَّرَ عَسكرًا من مصر، ومُقَدِّمُهم قائدٌ يُعرَف بنَصرِ الدولةِ، فحَصَرَ دِمشقَ، فسار تتش إلى نُصرَةِ أتسز فلمَّا سَمِعَ المِصريُّون أَتباعُ الفاطِميِّين بقُربِه أَجفَلوا من بين يَديهِ شِبْهَ المُنهَزِمين، وخَرجَ أتسز إليه يَلتَقيهُ عند سُورِ البلدِ، فاغتاظَ منه تتش حيث لم يُبعِد في تَلَقِّيهِ، وعاتَبَهُ على ذلك، فاعتَذرَ بأُمورٍ لم يَقبَلها تتش، فقَبَضَ عليه في الحالِ، وقَتَلَه مِن ساعتِه، ومَلَكَ البلدَ، وقِيلَ: إن تتش مَلَكَ دِمشقَ سَنةَ 472هـ."},{"id":1660,"title":"النِّزاعُ بين مُلوكِ الطَّوائفِ على حُكمِ مُدُنِ الأندَلُس .","date":["العام الهجري :471","العام الميلادي :1078"],"text":"جَهَّزَ المُعتَمِدُ بن عَبَّادٍ جَيشًا بقِيادَةِ وَزيرِه أبي بكرِ بن عَمَّارٍ ووَجَّهَهُ للاستِيلاءِ على مَدينةِ مرسية، فاستَعانَ ابنُ عَمَّار بالكونت برنجيه أَميرِ برشلونه لِقاءَ المال، كما استَعانَ بعبدِالرحمن بن رشيق حاكمِ حِصْنِ بلج، فتَمَّ له ما أَرادَ من احتِلالِ مرسية وبَقِيَ ابنُ عَمَّارٍ على أَعمالِها، ثم قام بعدَ فَترَةٍ بالخُروجِ على المُعتَمِدِ وطَعَنَ فيه وفي زَوجتِه فقامَ ابنُ رشيق على ابنِ عمَّارٍ وأَخرَجَه من مرسية فلَجأَ ابنُ عمَّارٍ إلى ألفونسو مَلِكِ قشتالة ثم قَصَدَ سرقسطة ولَجأَ إلى أَميرِها ابنِ هود، فاستَقَلَّ ابنُ رشيق بحُكمِ مرسية إلى أن استَولَى عليها المُرابِطون عام 483هـ."},{"id":1661,"title":"مقَتْلُ ضامِنِ البَصرَةِ ابنِ عَلَّان اليَهودِيِّ .","date":["العام الهجري :472","العام الميلادي :1079"],"text":"كان خمارتكين وكوهرائين يَسعَيانِ في قَتْلِ ابنِ عَلَّان اليَهوديِّ، ضامِنِ البَصرَةِ، وكان مُلتَجِئًا إلى نِظامِ المُلْكِ، وكان بين نِظامِ المُلْكِ وبين خمارتكين الشرابي وكوهرائين عَداوَةٌ، فسَعَيا باليهوديِّ لذلك، فأَمَرَ السُّلطانُ ملكشاه بتَغرِيقِه فغُرِّقَ، وانقَطعَ نِظامُ المُلْكِ الوَزيرُ عن الرُّكوبِ ثلاثةَ أيامٍ، وأَغلقَ بابَه، ثم أُشِيرَ عليه بالرُّكوبِ فرَكِبَ، وعَمِلَ للسُّلطانِ دَعوةً عَظيمةً قَدَّمَ له فيها أَشياءَ كَثيرةً، وعاتَبَهُ على فِعلِه، فاعتَذرَ إليه، وكان أَمْرُ اليهوديِّ قد عَظُمَ إلى حَدِّ أنَّ زَوجتَه تُوفِّيَت، فمَشَى خَلفَ جَنازَتِها كلُّ مَن في البَصرَةِ، إلَّا القاضي، وكانت له نِعمةٌ عَظيمةٌ، وأَموالٌ كَثيرةٌ، فأَخذَ السُّلطانُ منه مائةَ ألفِ دِينارٍ، وضَمِنَ خمارتكين البَصرةَ كلَّ سَنَةٍ بمائةِ ألفِ دِينارٍ ومائةِ فَرَسٍ."},{"id":1662,"title":"ذِكْرُ فُتُوحِ إبراهيمَ بن مَسعودٍ الغَزنويِّ صاحِبِ غَزْنَةَ في بِلادِ الهِنْدِ .","date":["العام الهجري :472","الشهر القمري : صفر","العام الميلادي :1079"],"text":"غَزا المَلِكُ إبراهيمُ بن مَسعودِ بن محمودِ بن سبكتكين بِلادَ الهندِ، فحَصرَ قَلعةَ أجود، وهي قَلعةٌ حَصينةٌ، في غايَةِ الحَصانَةِ، كَبيرةٌ، تَحوِي عشرةَ آلافِ رجلٍ من المُقاتِلَةِ، فقاتَلوهُ، وصَبَروا تحت الحِصارِ، وزَحفَ إليهم غيرَ مَرَّةٍ، فرأوا من شِدَّةِ حَربِه ما مَلأَ قُلوبَهم خَوفًا ورُعبًا، فسَلَّموا القَلعةَ إليه في الحادي والعشرين من صَفَر هذه السَّنَةِ. وكان في نَواحي الهندِ قَلعةٌ يُقالُ لها: قَلعةُ روبال، على رَأسِ جَبلٍ شاهقٍ، وتحتها غِياضٌ أَشِبَةٌ، وخَلفَها البحرُ، وليس عليها قِتالٌ إلَّا من مكانٍ ضَيِّقٍ، وهو مَملوءٌ بالفِيَلَةِ المُقاتِلَةِ، وبها من رِجالِ الحَربِ ألوفٌ كَثيرةٌ، فتابَع المَلِكُ إبراهيمُ عليهم الوَقائعَ، وأَلَحَّ عليهم بالقِتالِ بجَميعِ أَنواعِ الحَربِ، ومَلَكَ القَلعةَ، واستَنزَلَهم منها وفي مَوضِعٍ يُقالُ له: دره نوره أَقوامٌ من أَولادِ الخُراسانيِّين الذين جَعَلَ أَجدادَهم فيها أفراسيابُ التُّركيُّ من قَديمِ الزَّمانِ، ولم يَتعَرَّض إليهم أَحَدٌ من المُلوكِ، فسار إليهم إبراهيمُ، ودَعاهُم إلى الإسلامِ أوَّلًا، فامتَنَعوا من إجابَتِه، وقاتَلوهُ، فظَفَرَ بهم، وأَكثرَ القَتْلَ فيهم، وتَفرَّق مَن سَلِمَ في البلادِ، وسَبَى واستَرَقَّ من النِّسوانِ والصِّبيانِ مائةَ ألفٍ. وفي هذه القَلعةِ حوضٌ للماءِ قُطْرُهُ نحو نِصفِ فَرسخٍ لا يُدرَك قَعْرُهُ، يَشربُ منه أَهلُ القَلعةِ وما عندهم من دابَّةٍ، ولا يَظهرُ فيه نَقصٌ. وفي بلادِ الهندِ مَوضِعٌ يُقالُ له: وره، وهو بَرٌّ بين خَليجَيْنِ، فقَصدَهُ المَلِكُ إبراهيمُ، فوَصلَ إليه في جُمادى الأُولى، وفي طَريقِه عَقَباتٌ كَثيرةٌ، وفيها أَشجارٌ مُلْتَفَّةٌ، فأَقامَ هناك ثلاثةَ أَشهُر ولَقِيَ الناسَ من الشِّتاءِ شِدَّةٌ، ولم يُفارِق الغَزوَةَ حتى أَنزلَ الله نَصرَهُ على أَوليائِه، وذُلَّهُ على أَعدائِه، وعاد إلى غَزْنَة سالِمًا مُظَفَّرًا."},{"id":1663,"title":"وَفاةُ نَصرِ بنِ مَرْوانَ، صاحِبِ دِيارِ بَكرٍ، ومِلْكُ ابنِه مَنصورٍ بَعدِه .","date":["العام الهجري :472","الشهر القمري : ذي الحجة","العام الميلادي :1080"],"text":"هو نَصرُ بن أحمدَ بن مَروانَ بن دوستك الكُرديُّ، صاحِبُ دِيارِ بَكرٍ، كان مَلِكًا عادِلًا، خَفيفَ الوَطْأَةِ، حَسَنَ السِّيرَةِ، كَثيرَ الإحسانِ إلى الناسِ. وعَمُرَت ميافارقين في أيَّامِه أَحسنَ عِمارَةٍ، ولَقِيَ الناسُ منه الخيرَ والبَركةَ في وِلايَتِه. وكان يَتفقَّد أَحوالَ الناسِ ويَسألُ عن أَحوالِهم ومَن غابَ منهم، وما شُوهِدَت ميافارقين أَعمَرَ ممَّا كانت في أيامِ نِظامِ الدِّينِ، ولا أَغنَى من أَهلِها في أَيامِه، وعلا في سُورِ ميافارقين وسُورِ آمد مَواضِعَ عَديدةً، واسمُه على المَواضِعِ ظاهِرًا وباطِنًا، وبَنَى الجِسرَ على دِجلةَ شرقيَّ آمد تحت الصَّخرةِ وبابِ التَّلِّ، وغَرُم عليه من مالِه, ومَلَكَ بعدَه ابنُه مَنصورٌ، ودَبَّرَ دَولتَه ابنُ الأنباري."},{"id":1664,"title":"نِهايةُ الدَّولةِ المرداسية بِحَلَب  .","date":["العام الهجري :473","العام الميلادي :1080"],"text":"مَلَكَ شَرفُ الدولةِ مُسلمُ بن قُريشٍ العقيليُّ، صاحبُ المَوصِل، مَدينةَ حَلَب؛ وسَببُ ذلك أنَّ تاجَ الدولةِ تتش بن ألب أرسلان حَصرَها مَرَّةً بعدَ أُخرى، فاشتَدَّ الحِصارُ بأَهلِها، وكان شَرفُ الدولةِ يُواصِلُهم بالغَلَّاتِ وغَيرِها. ثم إنَّ تتش حَصرَها هذه السَّنَةَ، وأَقامَ عليها أيامًا ورَحلَ عنها ومَلَكَ بزاعة والبيرة، وأَحرقَ ربض عزاز، وعادَ إلى دِمشقَ. فلمَّا رَحلَ عنها تاجُ الدولةِ استَدعَى أَهلُها شَرفَ الدولة لِيُسلِّموها إليه، فلمَّا قارَبَها امتَنَعوا من ذلك، وكان مُقدِّمُهم يُعرفُ بابنِ الحتيتي العباسيِّ، فاتَّفقَ أنَّ وَلَدَهُ خَرجَ يَتصيَّد بِضَيْعَةٍ له، فأَسَرَهُ أَحدُ التُّركمان، وهو صاحبُ حِصنٍ بنواحي حَلَب، وأَرسلَه إلى شَرفِ الدولةِ، فقَرَّرَ معه أن يُسلِّم البلدَ إليه إذا أَطلقَه، فأَجابَ إلى ذلك، فأَطلَقَه، فعادَ إلى حَلَب، واجتَمعَ بأَبيهِ، وعَرَّفَه ما أَقَرَّ به لشَرفِ الدولةِ، فأَذعَن إلى تَسليمِ البلدِ، ونادَى بشِعارِ شَرفِ الدولةِ، وسَلَّمَ البلدَ إليه، فدَخلَه سَنةَ 473هـ، وحَصرَ القَلعةَ، واستَنزلَ منها سابقًا ووَثَّابًا ابني محمودِ بن مرداس، فلمَّا مَلَكَ البلدَ أَرسلَ وَلدَه -وهو ابنُ عَمَّةِ السُّلطانِ- إلى السُّلطانِ يُخبِرُه بمُلْكِ البلدِ، وأَنفذَ معه شَهادةً فيها خُطوطُ المعدلين بحَلَب بضَمانِها، وسألَ أن يُقرِّر عليه الضَّمانَ، فأَجابهُ السُّلطانُ إلى ما طَلَبَ، وأَقطعَ ابنَ عَمَّتِه مَدينةَ بالس."},{"id":1665,"title":"خُروجُ تكش على السُّلطانِ ملكشاه .","date":["العام الهجري :473","الشهر القمري : شعبان","العام الميلادي :1081"],"text":"سار السُّلطانُ ملكشاه إلى الرَّيِّ، وعَرضَ العَسكرَ، فأَسقطَ منهم سبعةَ آلافِ رجُلٍ لم يَرضَ حالَهم، فمَضوا إلى تكش -قِيلَ: إنه مملوك لملكشاه. وقِيلَ: إنه لَصيق له وإن أبوه النُّعمان-، وهو ببوشنج، فقَوِيَ بهم، وأَظهرَ العِصيانَ على أَخيهِ ملكشاه، واستَولَى على مرو الروذ، ومرو الشاهجان، وترمذ، وغيرَها، وسار إلى نيسابور طامِعًا في مُلْكِ خُراسان، وقِيلَ: إن نِظامَ المُلْكِ قال للسُّلطانِ لمَّا أَمرَ بإسقاطِهِم من العَطاءِ: إنَّ هؤلاء ليس فيهم كاتبٌ، ولا تاجرٌ، ولا خَيَّاطٌ، ولا مَن له صَنعَةٌ غير الجُندِيَّة، فإذا أُسقِطوا لا نأَمَن أن يُقيموا منهم رجُلًا ويقولوا: هذا السُّلطانُ، فيكون لنا منهم شُغلٌ، ويَخرُج عن أَيدِينا أَضعافُ ما لهم من الجاري إلى أن نَظفرَ بهم. فلم يَقبَل السلطانُ قَولَه، فلمَّا مَضوا إلى تكش وأَظهرَ العِصيانَ نَدِمَ على مُخالفةِ وَزيرِه حيث لم يَنفَع الندمُ, فسارَ ملكشاه مُجِدًّا إلى خُراسان، فوَصلَ إلى نيسابور قبلَ أن يَستَولِي تكش عليها، فلمَّا سَمِعَ تكش بقُربِه منها سار عنها، وتَحصَّن بتِرمِذ، وقَصدَه السلطانُ، فحَصرَه بها، وكان تكش قد أَسَرَ جَماعةً من أَصحابِ السلطانِ، فأَطلَقَهم، واستَقرَّ الصُّلحُ بينهما، ونَزلَ تكش إلى السلطانِ ملكشاه، ونَزلَ له عن تِرمِذ."},{"id":1666,"title":"اغتِيالُ عليٍّ الصُّليحيِّ زَعيمِ اليَمنِ الشِّيعيِّ القُرمطيِّ .","date":["العام الهجري :473","الشهر القمري : ذي القعدة","العام الميلادي :1081"],"text":"هو أبو الحَسنِ عليُّ بن محمدِ بن عليٍّ المُلقَّب بالصليحيِّ، كان أَبوهُ قاضِيًا باليَمنِ سُنِّيًّا، أمَّا الصليحيُّ فتَعلَّم العِلمَ وبَرعَ في أَشياءَ كَثيرةٍ من العُلومِ، وكان شِيعِيًّا على مَذهبِ القَرامِطَةِ، ثم كان يَدُلُّ بالحَجِيجِ مُدَّةَ خمس عشرة سَنَةً، استَحوذَ على بلادِ اليمنِ بكمالها بكاملها في أَقصرِ مُدَّةٍ، واستَوثقَ له المُلْكُ بها سَنةَ خمسٍ وخمسين وأربعمائة، وخَطبَ للمُستَنصِر العُبيديِّ صاحبِ مصر، وقد حَجَّ في سَنةِ 473هـ، واستَخلفَ مَكانَه وَلدَه المَلِكَ المُكرَّمَ أحمدَ. فلمَّا نَزلَ بظاهرِ المهجم وَثَبَ عليه جَيَّاشُ بن نَجاحٍ وأَخوهُ سَعيدٌ فقَتَلاهُ بأَبيهِما نَجاحٍ الذي سَمَّهُ الصُّليحيُّ بواسطةِ جاريةٍ كان قد أَهداهُ إيَّاها لهذا الغَرضِ، فانذَعرَ الناسُ، وكان الأَخَوانِ قد خَرَجا في سبعين راجِلًا بلا مَركوبٍ ولا سِلاحٍ بل مع كلِّ واحدٍ جَريدةٌ - سَعَفةٌ طويَلة تُقَشَّر من خُوصِها- في رَأسِها مِسمارُ حَديدٍ، وساروا نحوَ السَّاحلِ. وسَمِعَ بهم الصُّليحيُّ فسَيَّرَ خمسةَ آلافِ حَربةٍ مِن الحَبشَةِ الذين في رِكابِه لِقِتالِهم فاختَلَفوا في الطريقِ. ووَصلَ السبعون إلى طَرفِ مُخيَّمِ الصُّليحيِّ، وقد أَخذَ منهم التَّعَبُ والحَفَا، فظَنَّ الناسُ أنَّهم مِن جُملةِ عَبيدِ العَسكرِ، فتَمَكَّنا من قَتلِه وقَطْعِ رَأسِه, ثم أَرسلَ ابنُ نَجاحٍ إلى الخَمسةِ الآفٍ فقال: إنَّ الصُّليحيَّ قد قُتِلَ، وأنا رَجلٌ منكم، وقد أَخذتُ بثَأرِ أبي، فقَدِموا عليه وأَطاعُوهُ. فقَاتلَ بهم عَسكرَ الصُّليحيِّ، فاستَظهرَ عليهم قَتْلًا وأَسْرًا، ورَفعَ رَأسَ الصُّليحيِّ على رُمحٍ، وقَرأَ القارئُ: {قل اللهم مالك الملك تؤتي الملك من تشاء وتنزع الملك ممَّن تشاء} ورَجعَ ابنُ نَجاحٍ فمَلَكَ زبيد، وتهامة."},{"id":1667,"title":"فَتْحُ أنطرطوس على يَدِ تتش بنِ ألب أرسلان .","date":["العام الهجري :474","العام الميلادي :1081"],"text":"سار تتش بنُ ألب أرسلان صاحِبُ دِمشقَ، بعدَ عَوْدِ شَرفِ الدولةِ عن دِمشقَ، وقَصدَ الساحِلَ الشاميَّ، فافتَتحَ أنطرطوس، وبَعضًا مِن الحُصونِ، وعادَ إلى دِمشقَ."},{"id":1668,"title":"حِصارُ الأَميرِ تَميمِ بنِ المُعِزِّ بن باديس مَدينةَ قابس .","date":["العام الهجري :474","العام الميلادي :1081"],"text":"حَصَرَ الأَميرُ تَميمُ بنُ المُعِزِّ بن باديس، صاحبُ إفريقية، مَدينةَ قابس حِصارًا شَديدًا، وضَيَّقَ على أَهلِها، وعاثَ عَساكِرُه في بَساتِينِها المَعروفَةِ بالغابَةِ فأَفسَدوها."},{"id":1669,"title":"النِّزاعُ بين مُلوكِ الطَّوائفِ على حُكمِ مُدُنٍ بالأندَلُس\n  .","date":["العام الهجري :474","العام الميلادي :1081"],"text":"بعدَ أن أَصبحَ أحمدُ بن سُليمانَ بن هود أَميرًا لسرقسطة بعَهدِ أَبيهِ تُوفِّي في هذا العامِ وكان يُلقَّب بالمُقتَدِر باللهِ، وكان قبلَ وَفاتِه قد قَسَّمَ مَملكَتَه بين وَلدَيهِ فأَعطَى المُؤتَمن سرقسطة وأَعمالَها، وأَعطَى المُنذِرَ بلادَ الثَّغرِ الأعلى دانية ولاردة، ولكنَّ المُؤتَمن أَعلَن الحَربَ على أَخيهِ للاستِيلاءِ على حِصَّتِه مُستعينًا بكمبيادرو النَّصرانيِّ حَليفَ أَبيهِ فقامَ المُنذِرُ بالاستِنصارِ بسانشو مَلِكِ أراجون لكنَّه انهَزمَ أَمامَ أَخيهِ، أما طليطلة فإنَّ أَهلَها ثاروا على أَميرِها القادرِ ذي النونِ فهَربَ من المدينةِ ولَجأَ إلى قونكة، وكَتبَ إلى ألفونسو مَلِكِ قشتالة وطَلبَ المَعونةَ منه فاستَجابَ له وأَعادَهُ إلى طليطلة."},{"id":1670,"title":"وَفاةُ داودَ بنِ السُّلطانِ ملكشاه .","date":["العام الهجري :474","العام الميلادي :1081"],"text":"هو داودُ بنُ السُّلطانِ ملك شاه، جَزَعَ عليه والدُه جَزَعًا شَديدًا، وحَزِنَ حُزنًا عَظيمًا، ومَنعَ مِن أَخْذِهِ وغَسْلِه، حتى تَغيَّرت رائحتُه، وأَرادَ قَتْلَ نَفسِه مَرَّاتٍ، فمَنَعهُ خَواصُّه، وأَمرَ بالنِّياحَةِ عليه في البلدِ، ففُعِلَ ذلك عِدَّةَ أيامٍ، وجَلسَ له وَزيرُ الخَليفةِ في العَزاءِ ببغداد."},{"id":1671,"title":"وَفاةُ أبي الوَليدِ الباجي المالكيِّ .","date":["العام الهجري :474","الشهر القمري : رجب","العام الميلادي :1082"],"text":"هو الإمامُ، العَلَّامةُ، الحافظُ، ذو الفُنونِ، القاضي أبو الوَليدِ سُليمانُ بنُ خَلَفِ بنِ سعدِ بن أيُّوبَ التَّجيبيُّ الأندَلُسيُّ، القُرطُبيُّ، الباجيُّ، الفَقِيهُ المالكيُّ، صاحبُ التَّصانيفِ. وَلِدَ سَنةَ 403هـ أَصلُه من مَدينةِ بطليوس، فتَحوَّل جَدُّهُ إلى باجةَ -بُليدَة بقُربِ إشبيلية- فنُسِبَ إليها، وليست باجة المدينةَ التي بإفريقية، التي يُنسَب إليها الحافظُ أبو محمدٍ عبدُ الله بنُ محمدِ بن عليٍّ الباجيُّ، وابنُه الحافظُ الأَوحَدُ أبو عُمرَ أحمدُ بنُ عبدِ الله بن الباجيِّ، وهُما من عُلماءِ الأندَلُس أيضًا. كان أبو الوَليدِ أَحَدَ الحُفَّاظِ المُكثِرينَ في الفِقهِ والحَديثِ، سَمِعَ الحَديثَ ورَحلَ فيه إلى بِلادِ المَشرقِ فسَمِعَ هناك الكَثيرَ، واجتَمعَ بأَئمَّةِ ذلك الوَقتِ، كالقاضي أبي الطَّيِّبِ الطَّبريِّ، وأبي إسحاقَ الشِّيرازيِّ، وجاوَرَ بمكَّةَ ثلاثَ سِنينَ مع الشيخِ أبي ذَرٍّ الهَرويِّ، وأَقامَ ببغدادَ ثلاثَ سِنينَ، وبالمَوصِل سَنةً عند أبي جَعفرٍ السمنانيِّ قاضِيها، فأَخذَ عنه الفِقهَ والأُصولَ، وسَمِعَ الخَطيبَ البغداديَّ وسَمِعَ منه الخَطيبُ أيضًا، ثم عاد إلى بَلدِه بعدَ ثلاث عشرة سَنةً بِعِلمِ غَزيرٍ، حَصَّلَهُ مع الفَقرِ والتَّقَنُّعِ باليَسيرِ، وتَولَّى القَضاءَ هناك، ويُقالُ: إنَّه تَولَّى قَضاءَ حَلَب أيضًا. له مُصنَّفاتٌ عَديدةٌ منها: ((المُنتقَى في الفِقْه)), و((المعاني في شرح الموطأ))، و((إحكام الفُصول في أَحكام الأُصول))، و((الجَرْح والتَّعديل))، وغيرُ ذلك، قال القاضي عِياض: \"آجَرَ أبو الوَليدِ نَفسَه ببغداد لِحِراسَةِ دَربٍ، وكان لمَّا رَجعَ إلى الأندَلُسِ يَضرِب وَرَقَ الذَّهَبِ للغَزْلِ، ويَعقِد الوَثائقَ، قال لي أَصحابُه: كان يَخرُج إلينا للإقراءِ وفي يَدهِ أَثَرُ المَطرَقَةِ، إلى أن فَشَا عِلمُه، وهَيَّتَت الدنيا به -أي شَهَرَتهُ وأَظهرَت اسمَه-، وعَظُمَ جاهُه، وأُجزِلَت صِلاتُه، حتى تُوفِّي عن مالٍ وافرٍ، وكان يَستَعمِلُه الأَعيانُ في تَرَسُّلِهم، ويَقبلُ جَوائِزَهم، وَلِيَ القَضاءَ بمَواضِعَ من الأندَلُس\" قال الأَميرُ أبو نصرٍ: \"أمَّا الباجي ذو الوِزارَتَينِ فَفَقِيهٌ مُتكَلِّمٌ، أَديبٌ شاعِرٌ، سَمِعَ بالعراقِ، ودَرَسَ الكلامَ، وصَنَّفَ, وكان جَليلًا رَفيعَ القَدرِ والخَطَرِ، قَبْرُه بالمرية\", وقال القاضي أبو عليٍّ الصَّدَفيُّ: \"ما رَأيتُ مِثلَ أبي الوليدِ الباجي، وما رَأيتُ أَحدًا على سَمْتِه وهَيئَتِه وتَوقيرِ مَجلِسِه\". وقد جَرَت بينه وبين ابنِ حَزمٍ مُناوَأَةٌ شَديدةٌ كما جَرَت بينهما مُناظراتٌ كَثيرةٌ، قال القاضي عِياض: \"كَثُرَت القالةُ في أبي الوليدِ لِمُداخَلَتِه للرُّؤساءِ\" تُوفِّي بالمرية ليلةَ الخميسِ بين العِشاءَينِ التاسع والعشرين من رجب وعُمرُه إحدى وسبعون سَنةً."},{"id":1672,"title":"الفِتنَةُ ببغداد بين الشافِعيَّةِ والحَنابِلَةِ .","date":["العام الهجري :475","العام الميلادي :1082"],"text":"وَرَدَ إلى بغداد الشَّريفُ أبو القاسمِ البكريُّ، المغربيُّ، الواعظُ، وكان أَشعريَّ المَذهبِ، وكان قد قَصَدَ نِظامَ المُلْكِ، فأَحَبَّهُ ومالَ إليه، وسَيَّرَهُ إلى بغداد، وأَجرَى عليه الجِرايةَ الوافِرةَ، فوَعظَ بالمدرسةِ النِّظاميَّةِ، وكان يَذكُر الحَنابِلَةِ ويَعِيبُهم، ويقول: \"وما كَفَرَ سُليمانُ ولكنَّ الشياطين كَفَروا، والله ما كَفَرَ أَحمدُ ولكنَّ أَصحابَه كَفَروا، ثم إنَّه قَصَدَ يومًا دارَ قاضي القُضاةِ أبي عبدِ الله الدَّامغاني بنَهرِ القلائين، فجَرَى بين بَعضِ أَصحابِه وبين قَومٍ من الحَنابلةِ مُشاجرةٌ أَدَّت إلى الفِتنَةِ، وكَثُرَ جَمعُه، فكَبَسَ دُورَ بَنِي الفَرَّاءِ الحَنابلةِ، وأَخذَ كُتُبَهم، وأَخذَ منها كِتابَ ((الصِّفاتِ)) لأبي يَعلَى، فكان يَقرأُ بين يدي البَكريِّ وهو جالسٌ على الكُرسيِّ للوَعظِ، فيُشَنِّعُ به عليهم، وجَرَى له معهم خُصوماتٌ وفِتَنٌ. ولُقِّبَ البَكريُّ من الدِّيوانِ بِعَلَمِ السُّنَّةِ."},{"id":1673,"title":"استِيلاءُ المُرابطين على مُعظَمِ بِلادِ المَغرِب. .","date":["العام الهجري :475","العام الميلادي :1082"],"text":"كان يوسفُ بن تاشفين قد استَفحلَ أَمرُه بالمَغربِ واستَولَى على أَكثرِ البلادِ, فلمَّا سَمِعَ الأَميرُ أبو بكرِ بن عُمرَ بما آلَ إليه أَمرُ يوسفَ بن تاشفين وما مَنحَه الله من النصرِ أَقبلَ من الصحراءِ لِيَختَبِرَ أَحوالَه، ويُقالُ: إنه كان مُضمِرًا لِعَزلِه وتَولِيَةِ غَيرِه فأَحَسَّ يوسفُ بذلك فشاوَرَ زَوجتَه زينبَ بنت إسحاقَ -كان قد تَزوَّجَها بعدَ أبي بكر بن عُمرَ- فقالت له: إنَّ ابنَ عَمِّك مُتَوَرِّع عن سَفْكِ الدِّماءِ، فإذا لَقِيتَه فاترُك ما كان يَعهدُه منك من الأدبِ والتَّواضُع معه، وأَظهِر أَثَرَ التَّرَفُّعِ والاستبدادِ حتى كأنَّك مُساوٍ له ثم لاطِفْهُ مع ذلك بالهَدايا من الأَموالِ والخِلَعِ وسائرِ طرف المغربِ واستَكثِر من ذلك, فأَخذَ برَأيِها, فأَظهرَ له القُوةَّ وقَدَّمَ له الهَدايا المُستَطرفَة فأَدرَك أبوبكرٍ حالَ ابنِ تاشفين وأنَّه  لن يَتخلَّى له عن الأَمرِ, فقال له: يا بنَ عَمِّ، انزِل أُوصِيكَ. فنَزَلا مَعًا وجَلَسا، فقال أبو بكرٍ إنِّي قد وَلَّيْتُكَ هذا الأَمرَ، وإنِّي مَسؤولٌ عنه، فاتَّقِ الله تعالى في المسلمين، وأَعتِقْنِي وأَعتِق نَفسَك من النارِ، ولا تُضَيِّع من أُمورِ رَعِيَّتِك شيئًا، فإنَّك مَسؤولٌ عنه، والله تعالى يُصلِحُك ويَمُدُّك ويُوفِّقُك للعَملِ الصالِحِ والعَدلِ في رَعِيَّتِك، وهو خَليفَتِي عليك وعليهم. وقد مَلَكَ ابنُ تاشفين بعدوَةِ المغربِ من جزائر بَنِي مذغنة إلى طنجة إلى آخر السوسِ الأقصى إلى جِبالِ الذَّهَبِ من بلادِ السُّودان."},{"id":1674,"title":"مَسيرُ أبي إسحاقَ الشِّيرازيِّ بِرِسالةٍ من الخَليفَةِ إلى ملكشاه .","date":["العام الهجري :475","العام الميلادي :1082"],"text":"نَفَذَ الشيخُ أبو إسحاقَ الشِّيرازيُّ رَسولًا إلى السُّلطانِ ملكشاه والوَزيرِ نِظامِ المُلْكِ بِرسالةٍ مَضمونُها تتضمن الشَّكوَى من العَميدِ أبي الفَتحِ بن أبي اللَّيثِ، عَميدِ العِراقِ، وأَمرَهُ أن يُنهِي ما يجري على البلادِ من النُّظَّارِ، وقد جَرَى بينه وبين إمامِ الحَرَمينِ أبي المَعالي الجُوينيِّ مُناظرَةٌ بِحَضرَةِ نِظامِ المُلْكِ، وأُجِيبَ إلى جَميعِ ما التَمسَهُ، ولمَّا عاد أُهِينَ العَميدُ، وكُسِرَ عمَّا كان يَعتَمِدُه، ورُفِعَت يَدُه عن جَميعِ ما يَتعلَّق بحواشي الخَليفَةِ."},{"id":1675,"title":"استِيلاءُ مالِكِ بن عَلَويٍّ على القَيروانِ ثم استعادتها منه .","date":["العام الهجري :476","العام الميلادي :1083"],"text":"جَمعَ مَالكُ بن عَلويٍّ الصَّخريُّ العَربَ فأَكثرَ، وسارَ إلى المَهدِيَّةِ فحَصرَها، فقامَ الأَميرُ تَميمُ بن المُعِزِّ قِيامًا تامًّا، ورَحَّلَهُ عنها، ولم يَظفَر منها بشيءٍ، فسار مالِكُ منها إلى القَيروانِ فحَصرَها ومَلِكَها، فجَرَّدَ إليه تَميمٌ العَساكرَ العَظيمةَ، فحَصَروهُ بها، فلمَّا رأى مالِكٌ أنَّه لا طاقةَ له بتَميمٍ خَرجَ عنها وتَركَها، فاستَولَى عليها عَسكرُ تَميمٍ وعادَت إلى مُلكِه كما كانت."},{"id":1676,"title":"حِصارُ شَرفِ الدَّولةِ صاحِبِ حَلَب لِدِمشقَ .","date":["العام الهجري :476","الشهر القمري : محرم","العام الميلادي :1083"],"text":"جَمعَ تاجُ الدولةِ تتش جَمْعًا كَثيرًا، وسار عن بغداد، وقَصدَ بِلادَ الرُّومِ أنطاكية وما جاوَرَها، فسَمِعَ صاحِبُ حَلَب، شَرفُ الدولةِ أبو المَكارِم مُسلمُ بن قُريشٍ أَميرُ بَنِي عُقيلٍ الخَبرَ، فخافَهُ، فجَمعَ العَربَ من عُقيلٍ، والأَكرادَ، وغَيرَهم، فاجتَمعَ معه جَمْعٌ كَثيرٌ، فراسَلَ صاحِبَ مصر الفاطميَّ يَطلُب منه إِرسالَ نَجدَةٍ إليه لِيَحصُرَ دِمشقَ، فوَعَدهُ ذلك فسار إليها. فلمَّا سَمِعَ تتش الخَبرَ عاد إلى دِمشقَ، فوَصلَها أَوَّلَ المُحرَّم سَنةَ 476هـ، ووَصلَ شَرفُ الدولةِ أواخِرَ المُحرَّم، وحَصرَ المدينةَ وقاتَلَهُ أَهلُها، وفي بَعضِ الأيامِ خَرجَ إليه عَسكرُ دِمشقَ وقاتَلوهُ، وحَملَ على عَسكرِه حَملةً صادِقةً، فانكَشَفوا وتَضَعْضَعوا، وانهَزمَت العَربُ، وثَبَتَ شَرفُ الدولةِ، وأَشرَفَ على الأَسْرِ، وتَراجَع إليه أَصحابُه، فلمَّا رَأى شَرفُ الدولةِ ذلك، ورَأى أيضًا أنَّ مصر لم يَصِل إليه منها عَسكرٌ، وأَتاهُ عن بِلادِه الخَبرُ أنَّ أَهلَ حران عَصَوا عليه رَحَلَ عن دِمشقَ إلى بِلادِه، وأَظهرَ أنَّه يُريدُ البِلادَ بفِلسطين، فرَحلَ أوَّلًا إلى مرج الصفرِ، فارتاعَ أَهلُ دِمشقَ وتتش واضطَرَبوا، ثم إنَّه رَحلَ من مرج الصفرِ مُشَرِّقًا في البَرِّيَّةِ وجَدَّ في مَسيرِه، فهَلَكَ من المواشي الكَثيرُ مع عَسكرِه، ومن الدَّوابِّ شَيءٌ كَثيرٌ، وانقَطعَ خَلْقٌ كَثيرٌ."},{"id":1677,"title":"وَفاةُ الشيخِ أبي إسحاقَ الشِّيرازيِّ .","date":["العام الهجري :476","الشهر القمري : جمادى الآخرة","العام الميلادي :1083"],"text":"هو الشيخُ، الإمامُ، القُدوَةُ، المُجتَهِد، شيخُ الإسلامِ، أبو إسحاقَ إبراهيمُ بن عليِّ بن يوسفَ الفيروزاباذي الشِّيرازيُّ، الشافعيُّ، الأشعريُّ, نَزيل بغدادَ، قِيلَ: لَقَبُه جَمالُ الدِّينِ، وُلِدَ سَنةَ 393هـ  في قَريةِ فيروزباذ من قُرَى فارس، وقِيلَ: هي مَدينَة خوارزم، وهو شيخُ الشافعيةِ في عَصرِه, ومُدَرِّسُ النِّظاميَّةِ ببغداد، تَفَقَّه بفارس على أبي عبدِ الله البَيضاوي، ثم قدم بغداد سَنةَ خَمس عشرة وأربعمائة، فتَفَقَّه على القاضي أبي الطَّيِّبِ الطَّبريِّ، وبَرَعَ على يَدِه، وصار مُعيدَهُ، وكان يُضرَب المَثَلُ بفَصَاحَتِه وقُوَّةِ مُناظَرتِه. وسَمِعَ الحَديثَ من ابنِ شاذان  والبرقاني، وكان عابِدًا وَرِعًا، مُتواضِعًا، ظَريفًا، كَريمًا، جَوَادًا، طَلْقَ الوَجْهِ، دائِمَ البِشْرِ، مَليحَ المُحاوَرَةِ، زاهِدًا، جاءَتهُ الدُّنيا صاغِرةً، فأَبَاهَا، واقتَصرَ على خُشونَةِ العَيْشِ أيامَ حَياتِه. كان كَبيرَ القَدْرِ مُعَظَّمًا مُحتَرمًا إمامًا في الفِقْهِ والأُصولِ والحَديثِ، وفُنونٍ كَثيرةٍ. رَحلَ الناسُ إليه من البلادِ، وقَصَدوهُ، وتَفَرَّدَ بالعِلمِ الوافرِ مع السِّيرَةِ الجَميلةِ، والطَّريقَةِ المَرْضِيَّةِ. قال السَّمعانيُّ: سَمعتُ جَماعةً يقولون: \"لمَّا قَدِمَ أبو إسحاقَ نيسابور رَسولًا تَلَقَّوهُ، وحَملَ إمامُ الحَرمَينِ غاشِيَتَهُ، ومَشَى بين يَديِه وقال: أَفتَخِرُ بهذا\". وكان عامَّةُ المُدَرِّسِينَ بالعِراقِ والجِبالِ تَلامِذتَهُ وأَتباعَهُ, وكان يُنشِد الأَشعارَ المَلِيحَةَ، ويُورِدُها، ويَحفَظ منها الكَثيرَ. قال محمدُ بن عبدِ المَلِكِ الهمذانيُّ: حَكَى أبي قال: \"حَضرتُ مع قاضي القُضاةِ أبي الحَسنِ الماوردي عَزاءً، فتَكلَّم الشيخُ أبو إسحاقَ واجلا وأَجادَ، فلمَّا خَرَجنا، قال الماورديُّ: ما رَأيتُ كأبي إسحاقَ! لو رَآهُ الشافعيُّ لتَجَمَّلَ به\" قال خَطيبُ المَوصِل أبو الفضلِ: \"حَدَّثنِي أبي قال: تَوجَّهتُ من المَوصِل سَنةً إلى أبي إسحاقَ، فلمَّا حَضرتُ عنده رَحَّبَ بي، وقال: مِن أين أنت؟ فقلتُ: من المَوصِل. قال: مرحبًا أنت بَلدِيِّي. فشاهدتُ من حُسْنِ أَخلاقِه ولَطافَتِه وزُهدِه ما حَبَّبَ إليَّ لُزومَه، فصَحِبتُه إلى أن مات\" له مُصنَّفاتٌ كَثيرةٌ نافعةٌ، كـ((المُهَذَّبِ)) في المَذهبِ، و((التنبيه))، و((النكت في الخِلاف))، و((اللمع في أصول الفقه))، و((التبصرة))، و((طبقات الشافعية)) وغيرِ ذلك، تُوفِّي لَيلةَ الأَحدِ الحادي والعشرين في دارِ أبي المُظَفَّرِ ابنِ رَئيسِ الرُّؤساءِ، وغَسَّلَهُ أبو الوَفاءِ بن عقيل الحنبليُّ وصَلَّى عليه ببابِ الفردوس من دارِ الخِلافةِ، وشَهِدَ الصلاةَ عليه المُقتدِي بأَمرِ الله، وتَقدَّم للصلاةِ عليه أبو الفَتحِ المُظفَّر ابنُ رَئيسِ الرُّؤساءِ، ثم صُلِّيَ عليه مَرَّةً ثانيةً بجامعِ القَصرِ، ودُفِنَ ببابِ إبرز في تُربَةٍ مُجاورةٍ للناحيةِ."},{"id":1678,"title":"عِصيانُ تكش على السُّلطانِ ملكشاه .","date":["العام الهجري :477","العام الميلادي :1084"],"text":"عاوَدَ تكش العِصيانَ -قِيلَ: إن تكش مَملوكٌ لملكشاه. وقِيلَ: إنه لَصيقٌ له وإن أَباهُ النُّعمانُ- وكان أَصحابُ تكش يُؤثِرون الاختلاطَ، فحَسَّنوا له مُفارقةَ طاعَةِ ملكشاه، فأَجابَهم، وسارَ معهم، فمَلَكَ مرو الروذ وغيرَها إلى قَلعةٍ تُقارِب سرخس وهي لمسعودِ ابنِ الأَميرِ ياخز، وقد حَصَّنَها جُهْدَهُ، فحَصَروهُ بها، ولم يَبقَ غيرُ أَخْذِها منه، فاتَّفقَ أبو الفُتوحِ الطُّوسيُّ، صاحبُ نِظامِ المُلْكِ، وهو بنيسابور، وعَميدُ خراسان، وهو أبو عليٍّ، على أن يَكتُب أبو الفُتوحِ مُلَطِّفًا إلى مَسعودِ بن ياخز، وكان خَطُّ أبي الفُتوحِ أَشْبَهَ شَيءٍ بخَطِّ نِظامِ المُلْكِ، يقول فيه: كَتبتُ هذه الرُّقعَةَ من الرَّيِّ يومَ كذا، ونحن سائرونَ من الغَدِ نَحوَك، فاحفَظ القَلعةَ، ونحن نَكبِسُ العَدُوَّ في لَيلةِ كذا، فاسْتَدْعَيَا فَيْجًا –أي خادِم- يَثِقون به، وأَعطَياهُ دَنانيرَ صالحةً، وقالا: سِرْ نحوَ مَسعودٍ، فإذا وَصلتَ إلى المكانِ الفُلانيِّ فأَقِم به ونَمْ وأَخْفِ هذا المُلَطِّفَ في بعضِ حِيطانِه، فسَتأخُذك طلائِعُ تكش، فلا تَعتَرِف لهم حتى يَضرِبوكَ، فإذا فَعَلوا ذلك وبالَغوا فأَخرِجهُ لهم، وقُل: إنَّكَ فارَقتَ السُّلطانَ بالرَّيِّ ولك مِنَّا الحِباءُ والكَرامةُ، ففَعَلَ ذلك، وجَرَى الأَمرُ على ما وَصَفا، وأُحضِر بين يدي تكش وضُرِبَ، وعُرِّضَ على القَتلِ، فأَظهَرَ المُلَطِّفَ وسَلَّمَه إليهم، وأَخبَرهم أنَّه فارَقَ السُّلطانَ ونِظامَ المُلْكِ بالرَّيِّ في العَساكرِ، وهو سائرٌ، فلمَّا وَقَفوا على المُلَطِّف، وسَمِعوا كَلامَ الرَّجُلِ، وساروا ساروا مِن وَقتِهم، وتَركوا خِيامَهم ودَوابَّهم، والقُدورَ على النارِ، فلم يَصبِروا على ما فيها، وعادوا إلى قَلعةِ ونج. وكان هذا مِن الفَرَجِ العَجيبِ، فنَزلَ مسعودٌ وأَخذَ ما في المُعَسكَرِ، ووَرَدَ السُّلطانُ إلى خُراسان بعدَ ثلاثةِ أَشهُر، ولولا هذا الفِعلُ لنهب لذهب تكش إلى بابِ الرَّيِّ، ولمَّا وَصلَ السُّلطانُ قَصَدَ تكش وأَخَذَهُ، وكان قد حَلَفَ له بالأَيمانِ أنَّه لا يُؤذِيَه، ولا يَنالُه منه مَكروهٌ، فأَفتاهُ بَعضُ مَن حَضَرَ بأن يَجعلَ الأَمرَ إلى وَلَدِه أَحمدَ، ففَعَلَ ذلك، فأَمَرَ أَحمدَ بِتَسميلِ عَيْنَيْهِ، فسُمِلَتَا ثم سُجِنَ."},{"id":1679,"title":"فَتحُ سُليمانَ بنِ قتلمش أنطاكيةَ .","date":["العام الهجري :477","الشهر القمري : شعبان","العام الميلادي :1084"],"text":"سار سُليمانُ بن قتلمش، صاحِبُ قونية وأقصرا وأَعمالِها من بلادِ الرُّومِ، إلى الشم الشام، فمَلَكَ مَدينةَ أنطاكية من أرضِ الشامِ، وكانت بَيَدِ الرُّومِ من سَنةِ 358هـ، وسَببُ مُلْكِ سُليمانَ المدينةَ أن صاحِبَها الفردوس الرُّوميَّ كان قد سار عنها إلى بِلادِ الرُّومِ، ورَتَّبَ بها شِحْنَةً – مَسؤول عن ضَبْطِ المدينة-، وكان الفردوس مُسيئًا إلى أَهلِها، وإلى جُنْدِه أيضًا، فاتَّفقَ ابنُه والشِّحْنَةِ على تَسليمِ البَلدِ إلى سُليمانَ بن قتلمش، وكاتَبوهُ يَستَدعونه، فرَكِبَ البحرَ وأَخذَ البلدَ في شعبانَ، فقاتَلهُ أَهلُ البلدِ، فهَزَمهم مَرَّةً بعدَ أُخرى، وقَتلَ كَثيرًا من أَهلِها، ثم عَفَا عنهم، وتَسلَّم القَلعةَ المعروفة بالقسيان، وأَخذَ من الأَموالِ ما يُجاوِز الإحصاءَ، وأَحسنَ إلى الرَّعِيَّةِ، وعَدَلَ فيهم، وأَمرَهم بعِمارَةِ ما خُرِّبَ، ومَنعَ أَصحابَه من النُّزولِ في دُورِهم ومُخالَطَتِهم، ولمَّا مَلَكَ سُليمانُ أنطاكية أَرسلَ إلى السُّلطانِ ملكشاه يُبَشِّرُهُ بذلك، ويَنسُب هذا الفَتحَ إليه لأنَّه من أَهلِه، وممَّن يَتولَّى طاعتَه، فأَظهرَ ملكشاه البِشارةَ به، وهَنَّأَهُ الناسُ."},{"id":1680,"title":"وَفاةُ أبي المَعالِي الجُوينيِّ إِمامِ الحَرَمَين .","date":["العام الهجري :478","العام الميلادي :1085"],"text":"هو أبو المَعالِي عبدُ المَلِكِ ابنِ الشيخِ أبي محمدٍ عبدِ الله بن يوسفَ بن محمدِ بن حيويهِ، الجُوينيُّ، الفَقيهُ الشافعيُّ، المُلَقَّب ضِياءَ الدِّين، المعروف بإمامِ الحَرمَينِ؛ أَعلمُ المُتأخِّرين مِن أَصحابِ الإمامِ الشافعيِّ على الإطلاقِ، المُجْمَع على إِمامَتِه، المُتَّفَق على غَزارَةِ مادَّتِه، وتَفَنُّنِه في العُلومِ من الأُصولِ والفُروعِ والأَدَبِ وغَيرِ ذلك، وُلِدَ في مُحرَّم سَنةَ 419هـ, وقد رُزِقَ مِن التَّوَسُّعِ في العِبارَةِ ما لم يُعهَد مِن غَيرِه، وكان يَذكُر دُروسًا يَقعُ كلُّ واحدٍ منها في عِدَّةِ أَوراقٍ ولا يَتَلَعْثَم في كَلمةٍ منها، وتَفَقَّهَ في صِباهُ على والدِهِ أبي محمدٍ، وكان يُعْجَبُ بِطَبْعِه وتَحصيلِه وجَودَةِ قَريحَتِه، وما يَظهَر عليه من مخايلِ الإقبالِ، فأَتَى على جَميعِ مُصنَّفاتِ والدِه وتَصرَّف فيها، حتى زاد عليه في التَّحقيقِ والتَّدقيقِ. ولمَّا تُوفِّي والدُه قَعَدَ مَكانَه للتَّدريسِ، وإذا فَرغَ منه مضى إلى الأستاذِ أبي القاسمِ الإسكافيِّ الإسفرايني بمَدرسةِ البَيهقيِّ حتى حَصَّلَ عليه عِلْمَ الأُصولِ، ثم سافرَ إلى بغداد ولَقِيَ بها جَماعةً من العُلماءِ، ثم خَرجَ إلى الحِجازِ وجاوَرَ بمكَّةَ أربعَ سِنينَ، ثم انتَقلَ إلى المدينةِ، يُدَرِّسُ ويُفتِي ويَجمَع طُرُقَ المَذهبِ، فلهذا قِيلَ له: إمام الحَرمَين، ثم عادَ إلى نيسابور في أَوائلِ وِلايَةِ السُّلطانِ ألب أرسلان السلجوقي، والوَزيرُ يَومئذٍ نِظامُ المُلْكِ، فبَنَى له  فيها المَدرسةَ النِّظاميَّةَ، وتَولَّى الخَطابةَ بها، وكان يَجلِس للوَعظِ والمُناظَرةِ، وظَهرَت تَصانيفُه، وحَضرَ دُروسَه الأكابرُ من الأئمَّةِ وانتَهَت إليه رِياسَةُ الأصحابِ، وفُوِّضَ إليه أُمورُ الأوقافِ، وبَقِيَ على ذلك قَريبًا من ثلاثين سَنَةً غيرَ مُزَاحَمٍ ولا مُدَافَع، مُسَلَّم له المِحرابُ والمِنبرُ والخَطابةُ والتَّدريسُ ومَجلِسُ التَّذكيرِ يومَ الجُمعةِ. تُوفِّي بنيسابور عن 59 عامًا، له من التَّصانيفِ: العديدة ((العقيدة النِّظاميَّة))، و((الشامل)) و((الإرشاد إلى قواطع الأدلة)) في أصول الدين، و((البرهان في أصول الفقه))، وغيرُها من الكُتبِ، وكان من فُقهاءِ الشَّافعيَّة المُبرَزين في الأُصولِ والفِقهِ."},{"id":1681,"title":"سُقوطُ طُليطِلَة المُسلِمَة في أَيدِي القشتاليين .","date":["العام الهجري :478","العام الميلادي :1085"],"text":"في هذه السَّنَةِ استَولَى الفِرنجُ على مَدينةِ طُليطِلة من بِلادِ الأندلس، وأَخذُوها من المسلمين، وهي من أَكبرِ البلادِ وأَحصَنِها. وسببُ ذلك أن الأذفونش، (ألفونسو السادس) مَلِكَ قشتالة، كان قد قَوِيَ شَأنُه، وعَظُمَ مُلكُه، وكَثُرت عَساكِرُه، مُذ تَفرَّقَت بِلادُ الأندلس، وصار كلُّ بَلدٍ بِيَدِ مَلِكٍ، كما دَبَّ النِّزاعُ بينهم واستَعانوا بالفِرنجَةِ على بَعضٍ، فحينئذٍ طَمِعَ الفِرنجُ فيهم، وأَخَذوا كَثيرًا من ثُغورِهم. وكان ألفونسو خَدَمَ صاحِبَ طُليطلة القادرَ بالله بنَ المأمونِ بن يحيى بن ذي النونِ، وعاش في طُليطلة سَنواتٍ، فعَرِفَ مِن أين يُؤتَى البلدُ، وكيف الطريقُ إلى مُلْكِها, ولم يكن أحدٌ من مُلوكِ الطَّوائفِ قادِرًا على نَجْدَتِها، حتى إنَّ المُعتَمِدَ بن عبَّاد صاحِبَ أشبيلية وهو أَقوَى مُلوكِ الطَّوائفِ لمَّا رَأى استِفحالَ أَمرِ ألفونسو وقُوَّتَه رَأى أن يَعقِدَ مُهادَنةً وصُلْحًا معه يَأمَن بها على أَراضِيه، فبَعَثَ وَزيرَهُ ابنَ عمَّارٍ لِيَتفاوَضَ مع ألفونسو، وتَمَّت المُعاهدَةُ والاتِّفاقُ على بُنودٍ منها: أن يُؤَدِّي المُعتَمِدُ الجِزيةَ سَنويًّا, ويُسمَح للمُعتَمِد بِغَزْوِ أراضي طُليطلة الجنوبية على أن يُسَلِّم منها إلى ألفونسو الأراضي الواقعةَ شمالي طليطلة, و لا يَعتَرِض المُعتَمِد على استِيلاءِ ألفونسو على طُليطلة, وفي شَوَّال سَنةَ 474هـ ضَربَ ألفونسو الحِصارَ على طُليطلة، وشَدَّدَ غاراتَه عليها، وظلَّ على ذلك أَربعَ سَنواتٍ كاملةً؛ يُخَرِّب في الزُّروعِ والأراضي والقُرى، وعاشَ الناسُ في ضِيقٍ وكَربٍ، وليس بين المسلمين مُجِيرٌ، قال ابنُ بسام: \"دَخلَ على الأذفونش يومئذٍ جَماعةٌ فوَجَدوه يَمسَح الكرى من عَينيهِ، ثائرَ الرَّأسِ، خَبيثَ النَّفْسِ، فأَقبلَ عليهم بوَجهٍ كَريهٍ، وقال لهم: إلى متى تَتَخادَعون، وبأيِّ شَيءٍ تَطمعون؟ قالوا: بِنا بُغيَةٌ، ولنا في فُلانٍ وفُلانٍ أُمنِيَّةٌ، وسَمُّوا له بَعضَ مُلوكِ الطَّوائفِ، فصَفَّقَ بِيَديهِ، وتَهافَت حتى فَحَصَ برِجلَيهِ، ثم قال: أين رُسُلُ ابنِ عبَّادٍ؟ فجِيءَ بهم يَرفُلون في ثِيابِ الخَناعَةِ، وينبسون بأَلسِنَةِ السَّمعِ والطَّاعةِ. فقال لهم: مُذ كم تَحُومون عليَّ، وتَرومون الوصولَ إليَّ؟ ومتى عَهْدِكم بفُلانٍ؟ وأين ما جِئتُم به ولا كُنتم ولا كان؟ فجاءوا بجُملَةِ مِيرَةٍ، وأَحضَروها, ثم ما زادَ على أن رَكَلَ ذلك برِجلِه، وأَمَرَ بانتِهابِه كُلِّهِ؛ ولم يَبقَ مَلِكٌ من مُلوكِ الطَّوائفِ إلا أَحضرَ يَومئذٍ رُسُلَه، وكانت حالُه حالَ مَن كان قَبلَه. وجَعلَ أَعلاجَه يَدفَعون في ظُهورِهم، وأَهلُ طُليطلة يَعجَبون مِن ذُلِّ مَقامِهم ومَصيرِهم، فخَرجَ مَشيَختُها من عندِه وقد سُقِطَ في أَيدِيهم. وطَمِعَ كلُّ شيءٍ فيهم. وخَلُّوا بينه وبين البلدِ، ودَخلَ طُليطلة على حُكمِه، وأَثبَتَ في عَرصَتِها قَدَمَ ظُلمِه، حُكْمٌ مِن الله سَبَقَ به القَدَرُ، وخَرجَ ابنُ ذي النون خائبًا مما تَمَنَّاهُ، حدَّثنِي مَن رَآهُ يَومئذٍ بتلك الحالِ وبِيَدِه اصطرلاب يَرصُد فيه أيَّ وَقتٍ يَرحَل، وعلى أيِّ شَيءٍ يُعَوِّل، وأيَّ سَبيلٍ يَتَمَثَّل، وقد أَطافَ به النَّصارَى والمسلمون، أولئك يَضحَكون مِن فِعْلِه، وهؤلاء يَتَعجَّبون مِن جَهلِه. وعَتَا الطاغِيةُ الأذفونش -قَصَمَهُ الله- لحين استِقرارِه بطُليطلة واستَكبَر، وأَخَلَّ بمُلوكِ الطَّوائفِ في الجَزيرَةِ وقَصَّرَ، وأَخذَ يَتَجنَّى ويَتَعتَّب، وطَفِقَ يَتَشَوَّف إلى انتِزاعِ سُلطانِهم والفَراغِ مِن شانِهم\" في الوقتِ الذي كانت قُوَّاتُ ألفونسو تُحاصِر فيه طُليطلة كان مُلوكُ الطَّوائفِ يُقَدِّمُون مِيثاقَ الوَلاءِ والمَحَبَّةِ له؛ مُمَثَّلَةً في الجِزيَةِ والإتاوَةِ، ولم يَجرُؤ أَحدٌ منهم على الاعتِراضِ عليه في ذلك إلاَّ المُتَوكِّل بن الأَفطَس الذي أُخْرِج من طُليطلة قُبيلَ دُخولِ الطَّاغيةِ، وفي الوقتِ نَفسِه الذي تُحَاصَر فيه طُليطلة كانت مَمالكُ الطَّوائفِ الأُخرى تَتَنازَع فيما بينها، أو تَرُدُّ غاراتِ النَّصارَى المُتواصِلَة عليها. ثم قام ألفونسو باتِّخاذِ طُليطلة عاصِمةً له وحَوَّلَ مَسجِدَها إلى كَنيسةً."},{"id":1682,"title":"استِنجادُ مُلوكِ الطَّوائفِ بيُوسفَ بنِ تاشفين .","date":["العام الهجري :478","العام الميلادي :1085"],"text":"بعدَ أن قامَ ألفونسو السادسُ –أدفونش- بالاستِيلاءِ على طُليطلة بدأَ بتَهديدِ إشبيلية، فأَرسلَ كِتابًا لصاحِبِها المُعتَمِد بن عبَّاد قال فيه: \"مِن الإمبراطورِ ذي الملتين المَلِكِ أدفونش بن شانجة، إلى المُعتَمِد بالله، سَدَّدَ الله آراءَه، وبَصَّرَهُ مَقاصِدَ الرَّشادِ. قد أَبصرتَ تَزَلزُلَ أَقطارِ طُليطلة، وحِصارَها في سالفِ هذه السِّنين، فأَسلَمتُم إخوانَكم، وعَطَّلتُم بالدَّعَةِ زَمانَكم، والحَذِرُ مَن أَيقظَ بالَه قبلَ الوُقوعِ في الحِبالَة. ولولا عَهدٌ سَلَفَ بيننا نَحفظُ ذِمامَه نَهَضَ العَزمُ، ولكنَّ الإنذارَ يَقطَع الأعذارَ، ولا يَعجَل إلَّا مَن يَخاف الفَوْتَ فيما يَرومُه، وقد حَمَّلنَا الرِّسالةَ إليك البرهانس، وعندَه مِن التَّسديدِ الذي يَلقَى به أَمثالَك، والعَقلِ الذي يُدَبِّر به بِلادَك ورِجالَك، ما أَوجَبَ استِنابَتَه فيما يَدِقُّ ويَجِلُّ\". فلمَّا قَدِمَ الرَّسولُ أَحضرَ المُعتَمِدُ الأكابرَ، وقُرئ الكِتابُ، بَكَى أبو عبدِ الله بنُ عبدِ البَرِّ وقال: قد أَبصرَنا ببَصائِرِنا أن مآلَ هذه الأَموالِ إلى هذا، وأن مُسالَمَةَ اللَّعينِ قُوَّةٌ بلاده لبلاده، فلو تَضافَرنا لم نُصبِح في التلافِ تحتَ ذُلِّ الخِلافِ، وما بَقِيَ إلا الرُّجوعُ إلى الله والجِهادُ. وأمَّا ابن زيدون وابن لبون فقالا: الرَّأيُ مُهادَنتُه ومُسالمَتُه. فجَنَحَ المُعتَمِدُ إلى الحَربِ، وإلى استِمدادِ مَلِكِ البَربرِ ابنِ تاشفين، فقال جَماعةٌ: نَخافُ عليك من استِمدادِه. فقال: رَعْيُ الجِمالِ خَيرٌ مِن رَعْيِ الخَنازيرِ\". فرَدَّ على الأدفونش يَتهدَّدهُ و يَتَوعَّدهُ, ثم اتَّفقَ المُعتَمِدُ بن عبَّاد صاحِبُ أشبيلية والمُتوكِّلُ بن الأَفطَس صاحِبُ بطليموس وعبدُالله بن بلقين أَميرُ غِرناطة، على إرسالِ وَفْدٍ من القُضاةِ والأَعيانِ إلى يُوسفَ بن تاشفين يَدعونَهُ إلى الحُضورِ إلى الأندلسِ لِقِتالِ النَّصارَى ويَستَنصِرونَه على ألفونسو السادس، فلمَّا استَجابَ ابنُ تاشفين لِطَلَبِهم إرسال أَرسلَ رِسالةً إلى ألفونسو يَدعوهُ فيها إلى الإسلامِ أو الجِزيَةِ أو الحَربِ، فاختارَ الحَربَ."},{"id":1683,"title":"مُلوكُ الفِرنجَةِ يَجمَعون جُنودَهم لِلِقاءِ ابنِ تاشفين زَعيمِ المُرابِطين .","date":["العام الهجري :478","العام الميلادي :1085"],"text":"بعدَ أن رَدَّ ألفونسو على رِسالَةِ يوسف بن تاشفين واختارَ الحَربَ بَدأَ بالتَّجهيزِ فحاصَرَ مَدينةَ سَرقُسطة بعدَما استَولَى على طُليطلة، كما قامَ سانشو راميرو بمُحاصَرةِ مَدينةِ طرطوشة ثم لم يَلبَث أن فَكَّا الحِصارَ وتَداعَى مُلوكُ الفِرنجِ وجَمَعوا جُنودَهم وفيهم المُرتَزَقَة للِقاءِ يوسفَ بنِ تاشفين."},{"id":1684,"title":"نِهايَةُ الدَّولةِ العامِريَّةِ في الأندلس على يَدِ دَولةِ ابن ذي النُّونِ .","date":["العام الهجري :478","العام الميلادي :1085"],"text":"تُوفِّي أبو بكرٍ محمدُ بن عبدِالعزيز بنِ المنصورِ بن أبي عامرٍ أَميرُ بلنسية، واستُخلِفَ بعدَه ابنُه عُثمانُ أبو عَمرٍو، ولكنَّ القادِرَ بن ذي النونِ الذي انتَهَت دَولتُه في طُليطلة على يَدِ ألفونسو يَمُدُّهُ ألفونسو نَفسُه ويُساعِدُه على الاستِيلاءِ على بلنسية فيُسَيِّرُ له سَرِيَّةً قَويَّةً فيقومُ باستِخلاصِ بلنسية من عُثمانَ ويُقيمُ فيها دَولةَ بني ذي النون."},{"id":1685,"title":"انتِهاءُ دَولةِ بَنِي مَرْوان في الأندَلُسِ على يَدِ ابن جَهيرٍ .","date":["العام الهجري :478","العام الميلادي :1085"],"text":"قام ابنُ جَهيرٍ بإنهاءِ دَولةِ بَنِي مَروان في كلٍّ مِن آمد التي سَلَّمَها أَهلُها إليه بعدَ حِصارِها وكانوا قد سَئِموا مِن المُعامَلَةِ السَّيِّئَةِ من وُلاتِها وكان بينهم كَثيرٌ من النَّصارَى المتحكمين، كما تَمَلَّكَ ميافارقين وأَنهَى فيها حُكمَ بَنِي مَروان، وهي أيضًا سَلَّمَها أَهلُها، ثم مَلَكَ جَزيرةَ ابنِ عُمرَ وهي أيضا لبَنِي مَروان فحاصَروها ودَخَلوا حِصنَها عُنوةً ومَلَكوها، فكان هذا إنهاءً لدَولةِ بَنِي مَروان."},{"id":1686,"title":"مَقتَلُ شَرَفِ الدَّولةِ صاحِبِ حَلَب وتَوَلِّي أَخيهِ بعدَه  .","date":["العام الهجري :478","الشهر القمري : صفر","العام الميلادي :1085"],"text":"هو السُّلطانُ الأَميرُ شَرفِ الدَّولةِ أبو المَكارِمِ مُسلِمُ بن مَلِكِ العَربِ أبي المعالي قُريشِ بن بدران بن مُقَلَّدٍ حُسام الدَّولةِ أبي حَسَّان بن المُسَيِّب بنِ رافعٍ العقيليُّ, كان يَتَرَفَّض كأَبيهِ, ونَهَبَ أَبوهُ دارَ الخِلافَةِ في فِتنَةِ البساسيري، وأَجارَ القائمَ بالله, وماتَ سَنةَ 453هـ كَهْلًا، فقامَ شَرفُ الدولةِ بعدَه، واستَولَى على دِيارِ رَبيعةَ، ومُضَر، وتَمَلَّكَ حَلَب، وأَخذَ الحملَ والإتاوةَ من بلادِ الرُّومِ في أنطاكية، ونَحوِها. وسار إلى دِمشقَ فحاصَرَها. وكان قد تَهَيَّأَ له أَخذُها، فبَلغَه أنَّ حران قد عَصَى عليه أَهلُها، فسار إليهم، فحارَبَهم وحارَبوهُ، فافتَتَحها وبَذلَ السَّيْفَ، وقَتَلَ بها خِلْقًا من أَهلِ السُّنَّةِ. قال الذهبيُّ: \"كان رافِضِيًّا خَبِيثًا، أَظهرَ ببِلادِه سَبَّ السَّلَفِ، واتَّسَعَت مَملكتُه، وأَطاعَتهُ العَربُ، واستَفحلَ أَمرُه حتى طَمِعَ في الاستِيلاءِ على بغداد بعدَ وَفاةِ طُغرلبك. وكان فيه أَدَبٌ، وله شِعرٌ جَيِّدٌ. وكان له في كلِّ قَريةٍ قاضٍ، وعاملٌ، وصاحِبُ خَبَرٍ. وكان أَحْوَلَ، له سِياسَةٌ تامَّةٌ. وكان لِهَيْبَتِه الأَمنُ وبعضُ العَدلِ في أيامِه مَوجودًا. وكان يَصرِف الجِزيةَ في بِلادِه إلى العَلَوِيِّين\". وهو الذي عَمَّرَ سُورَ المَوصِل وشَيَّدَها في سِتَّةِ أَشهُر من سَنةِ 474هـ. ثم إنه جَرَى بينه وبين السُّلطانِ سُليمان بن قتلمش السلجوقي مصاف على بابِ أنطاكية، كان سُليمانُ بن قتلمش قد مَلَكَ مَدينةَ أنطاكية، فلمَّا أَرسلَ إليه شَرفُ الدولةِ مُسلمَ بن قريش يَطلُب منه ما كان يَحمِلُه إليه الفردوس من المالِ، أَجابهُ بأن المالَ الذي كان يَحمِلُه صاحِبُ أنطاكية فإنَّما هو لِكَونِه كافرًا، وكان يَحمِل جِزيةَ رَأسِه وأَصحابِه، وهو بِحَمدِ الله مُؤمنٌ، فنَهَبَ شَرفُ الدولةِ بَلدَ أنطاكية، فنَهبَ سُليمانُ أيضًا بَلدَ حَلَب، فلَقِيَهُ أَهلُ السَّوادِ يَشكُون إليه نَهْبَ عَسكرِه، فقال:أنا كنتُ أَشَدَّ كَراهِيةً لما يَجرِي، ولكنَّ صاحِبَكم أَحوَجَني إلى ما فَعلتُ، ولم تَجرِ عادَتي بنَهبِ مالِ مُسلمٍ، ولا أَخْذِ ما حَرَّمَتهُ الشَّريعةُ. وأَمَرَ أَصحابَه بإعادَةِ ما أَخذوهُ منهم، فأَعادَهُ، ثم إن شَرفَ الدولةِ جَمعَ الجُموعَ من العَربِ والتُّركمانِ، وسار إلى أنطاكية لِيَحصرَها، فلمَّا سَمِعَ سُليمانُ الخَبرَ جَمعَ عَساكِرَه وسار إليه، فالتَقَيا في طَرفٍ من أَعمالِ أنطاكية، واقتَتَلوا، فانهَزمَت العَربُ، فتَبِعَهم شَرفُ الدولةِ مُنهَزِمًا، ثم قُتِلَ، وله بِضعٌ وأَربعون سَنَةً. ولما قُتِلَ قَصدَ بَنُو عُقيلٍ أَخاهُ إبراهيمَ بنَ قُريشٍ، وهو مَحبوسٌ، فأَخرَجوهُ ومَلَّكوهُ أَمرَهُم، وكان قد مَكثَ في الحَبسِ سِنينَ كَثيرةً بحيث إنَّه لم يُمكِنهُ المَشيُ والحَركةُ لمَّا أُخرِجَ، ثم سار سُليمانُ بن قتلمش إلى حَلَب فحَصرَها مُستَهلَّ رَبيعٍ الأوَّلِ، فأَقامَ عليها إلى خامسِ رَبيعٍ الآخرَ، فلم يَبلُغ منها غَرَضًا، فرَحلَ عنها."},{"id":1687,"title":"حِصارُ دِمشقَ مِن قِبَلِ العُبَيدِيِّينَ الفاطِمِيِّين .","date":["العام الهجري :478","الشهر القمري : ربيع الأول","العام الميلادي :1085"],"text":"سارَ أَميرُ الجُيوشِ في عَساكرِ مصر إلى الشامِ، فحَصَرَ دِمشقَ، وبها صاحِبُها تاجُ الدولةِ تتش، فضَيَّقَ عليه، وقاتَلَهُ، فلم يَظفَر منها بشيءٍ، فرَحلَ عنها عائِدًا إلى مصر."},{"id":1688,"title":"وَفاةُ أبي عبدِالله الدَّامغاني .","date":["العام الهجري :478","الشهر القمري : رجب","العام الميلادي :1085"],"text":"هو العَلَّامةُ، البارِعُ، مُفتِي العِراقِ، قاضي القُضاةِ، أبو عبدِ الله محمدُ بن عليِّ بن محمدِ بن حَسنِ بن عبدِ الوهاب بن حسويهِ الدَّامغاني الحَنفيُّ. وُلِدَ بدامغان، سَنةَ 398هـ, وتَفَقَّهَ بخُراسان، وقَدِمَ بغدادَ شابًّا، فأَخَذَ عن القدوريِّ، وحَصَّل المَذهبَ على فَقْرٍ شَديدٍ. فكان يَحرُس في دَربِ الرِّياحِ، تَفَقَّهَ بدامغان على أبي صالحٍ الفَقيهِ، ثم قَصدَ نيسابور، فأقم فأَقامَ أَربعةَ أَشهُر بها، وصَحِبَ أبا العَلاءِ صاعِدَ بنَ محمدٍ قاضِيَها، ثم وَرَدَ بغدادَ, ووَلِيَ القَضاءَ للقائمِ بأَمرِ الله، فدامَ في القَضاءِ ثلاثين سَنَةً وأَشهُرًا. كان القاضي أبو الطَّيِّبِ يقول: \"الدَّامغاني أَعرَفُ بمَذهَبِ الشافعيِّ مِن كَثيرٍ مِن أَصحابِنا\". كان بَهِيَّ الصُّورَةِ، حَسَنَ المعاني في الدِّينِ والعِلْمِ والعَقلِ والحِلمِ وكَرَمِ العِشرَةِ والمُروءَةِ، له صَدَقاتٌ في السِّرِّ، وكان مُنصِفًا في العِلمِ، وكان يُورِدُ في دَرسِه من المُداعَباتِ والنَّوادِرِ نَظيرَ ما يُورِد الشيخُ أبو إسحاقَ الشيرازيُّ، فإذا اجتَمَعا، صار اجتِماعُهُما نُزهةً. قال الذهبيُّ: \"كان ذا جَلالةٍ وحِشمَةٍ وافِرَةٍ إلى الغايَةِ، يُنظَر بالقاضي أبي يوسف في زَمانِه, وفي أَولادِه أئمَّةٌ وقُضاة\". وَلِيَ قَضاءَ القُضاةِ بعدَ أبي عبدِ الله بن ماكولا، سَنةَ 447هـ، وله خمسون سَنةً. ماتَ في رَجب، ودُفِنَ بِدارِه، ثم نُقِلَ ودُفِنَ بِقُبَّةِ الإمامِ أبي حَنيفةَ إلى جانِبِه. عاشَ ثمانينَ سَنَةً وثلاثة أَشهُر وخمسة أيام، وغَسَّلَهُ أبو الوَفاءِ بن عَقيلٍ وأبو ثابتٍ الرَّازيُّ تِلميذُه. وصَلَّى عليه وَلَدُه قاضي القُضاةِ أبو الحَسنِ, وله أَصحابٌ كَثيرون عُلماء، انتَشَروا في البِلاد."},{"id":1689,"title":"الوَقعَةُ بين تتش وبين سُليمانَ بنِ قتلمش صاحِبِ حَلَب .","date":["العام الهجري :479","العام الميلادي :1086"],"text":"كانت الوَقعةُ بين تتش بن ألب أرسلان صاحِبِ دِمشقَ وبين سُليمانَ بن قتلمش صاحِبِ حَلَب وأنطاكية وتلك الناحيَةِ، فانهَزمَ أَصحابُ سُليمانَ وقَتَلَ هو نَفسَه بخِنجَر كان معه، وقِيلَ: بل جاءَهُ سَهمٌ على وَجهِه فسَقطَ مَيِّتًا مِن فَوْرِه، ويُذكَر أنَّه دُفِنَ بجانبِ مُسلمِ بنِ قُريشٍ صاحبِ حَلَب قَبلَه وهو مَن قَتلَه في أَحداثِ السَّنَةِ سابقة السَّابقةِ."},{"id":1690,"title":"ضَمُّ ملكشاه حَلَب والرها وحران لِمُلْكِه .","date":["العام الهجري :479","العام الميلادي :1086"],"text":"سارَ السُّلطانُ ملكشاه من أصبهان إلى حَلَب فمَلَكَها، ومَلَكَ ما بين ذلك من البلادِ التي مَرَّ بها، مثل حران والرها وقَلعَة جعبر، وكان جعبر شَيخًا كبيرًا قد عَمِيَ، وله وَلَدان، وكان قُطّاعُ الطَّريقِ يَلجَأون إليها فيَتَحصَّنون بها، فرَاسَلَ السُّلطانُ سابقَ بن جعبر في تَسليمِها فامتَنَع عليه، فنَصَبَ عليها المناجيق المجانيق والعرادات ففَتَحَها وأَمَرَ بِقَتْلِ سابق."},{"id":1691,"title":"مَوقِعَةُ الزَّلَّاقَة وهَزيمَةُ النَّصارَى أَمامَ المُرابِطين .","date":["العام الهجري :479","الشهر القمري : رمضان","العام الميلادي :1087"],"text":"وكان المُعتَمِدُ على الله أبو عبدِ الله محمدُ بن عَبَّاد أَعظمَ مُلوكِ الأندلسِ من المسلمين، وكان يَملِك أكثرَ البلادِ مثل قُرطُبة وإشبيلية، وكان يُؤدِّي إلى الفونسو السادس -الأذفونش- ضَريبةً كلَّ سَنَةٍ. فلمَّا مَلَكَ الفونسو طليطلة أَرسلَ إليه المُعتَمِدُ الضَّريبةَ على عادَتِه، فرَدَّها عليه ولم يَقبَلها منه، فأَرسلَ إليه يَتهدَّدهُ ويَتوعَّدهُ أنَّه يَسيرُ إلى مَدينةِ قُرطُبة ويَتملَّكها إلَّا أن يُسلِّم إليه جَميعَ الحُصونِ التي في الجَبلِ، ويُبقِي السهلَ للمُسلمين، وكان الرسولُ في جَمعٍ كَثيرٍ كانوا خمسمائة فارس، فأَنزَله محمدُ بن عبَّاد، وفَرَّقَ أَصحابَه على قُوَّادِ عَسكرِه، ثم أَمَرَ كلَّ مَن عنده منهم رَجُل أن يَقتُلَه، وأَحضرَ الرَّسولَ وصَفَعَهُ، وسَلِمَ من الجَماعةِ ثلاثةُ نَفَرٍ، فعادوا إلى ألفونسو فأَخبَروه الخَبرَ وكان مُتوجِّهًا إلى قُرطُبة لِيُحاصِرَها، فلمَّا بَلَغَهُ الخَبَرُ عادَ إلى طُليطلة ليَجمعَ آلاتَ الحِصارِ، ورَحلَ المُعتمدُ إلى إشبيلية فلمَّا عاد إليها، وسَمِعَ مَشايخَ قُرطبة بما جَرَى، ورأوا قُوَّةَ الفِرنج، وضَعفَ المُسلمين، واستِعانَةَ بَعضِ مُلوكِهم بالفِرنج على بعضٍ، اجتَمَعوا وقالوا: هذه بلادُ الأندلسِ قد غَلَبَ عليها الفِرنجُ، ولم يَبقَ منها إلَّا القليلُ، وإن استَمرَّت الأَحوالُ على ما نَرَى عادت نَصرانيةً كما كانت. وساروا إلى القاضي عبدِ الله بن محمدِ بن أدهم، فقالوا له: ألا تَنظُر إلى ما فيه المسلمون من الصَّغارِ والذِّلَّةِ، وعَطائِهم الجِزيةَ بعدَ أن كانوا يَأخُذونَها، وقد رأينا رَأيًا نَعرِضُه عليك. قال: ما هو؟ قالوا: نَكتُب إلى غَربِ إفريقية ونَبذُل لهم، فإذا وَصَلوا إلينا قاسَمناهُم أَموالَنا، وخَرَجنا معهم مُجاهِدين في سبيلِ الله. قال: نخافُ، إذا وَصَلوا إلينا، يُخَرِّبون بِلادَنا، كما فَعَلوا بإفريقية، ويَتركون الفِرنجَ ويَبدؤون بكم، والمُرابِطون أَصلَحُ منهم وأَقربُ إلينا. قالوا له: فكاتب أَميرَ المُسلمين، وارغَب إليه لِيَعبُرَ إلينا، ويُرسِل بعضَ قُوَّادِه. وقَدِمَ عليهم المُعتمِدُ بن عبَّاد، وهُم في ذلك، فعَرَضَ عليه القاضي ابنُ أدهم ما كانوا فيه، فقال له ابنُ عبَّاد: أنت رسولي إليه في ذلك، فامتَنَع، وإنَّما أرادَ أن يُبرِّئ نَفسَه من تُهمةٍ، فأَلَحَّ عليه المُعتمِدُ ابنُ عبَّاد وقال: \"إنْ دُهِينَا من مُداخَلَةِ الأضدادِ، فأَهْوَنُ الأَمرينِ أَمرُ المُلَثَّمين، ورِعايةُ أولادِنا جِمالَهم أَهوَنُ من أن يَرعوا خَنازيرَ الفِرنج\". فسارَ إلى أَميرِ المسلمين يوسفَ بنِ تاشفين، فأَبلغَه الرِّسالةَ، وأَعلَمهُ ما فيه المسلمون من الخَوفِ من ألفونسو. وما زالت وُفودُ الأندلسِ تَفِدُ على يوسفَ بنِ تاشفين مُستَعطِفين مُجهَشِينَ بالبُكاءِ ناشِدينَ بالله, ومُستَنجِدينَ بفُقهاءِ حَضرتِه ووُزراءِ دَولتِه فيَسمَع إليهم ويُصغِي لِقَولِهم وتَرِقُّ نَفسُه لهم, ولمَّا انتَهَت الرُّسُلُ إلى ابنِ تاشفين أَقبلَ عليهم وأَكرمَ مَثواهُم وجَرَت بينه وبينهم مُراوضاتٌ ثم انصَرَفوا إلى مُرسِلِهم ثم عَبَرَ يوسفُ البحرَ عُبورًا سَهلًا حتى أتى الجَزيرةَ الخَضراءَ فخَرجَ إليه أَهلُها بما عندهم من الأقواتِ والضِّيافاتِ وأَقاموا له سُوقًا جَلَبوا إليه ما عندهم من سائرِ المَرافِقِ وأَذِنوا للغُزاةِ في دُخولِ البلدِ والتَّصَرُّفِ فيها, ثم أَرسلَ ابنُ تاشفين لألفونسو يَدعوهُ للإسلامِ أو الجِزيَةِ أو الحَربِ فاختارَ الحربَ، فقام يوسفُ بن تاشفين في الحالِ وكان بمَدينةِ سَبتَة، فأَمرَ بعُبورِ العَساكرِ إلى الأندَلُسِ، وأَرسلَ إلى مراكش في طَلبِ مَن بَقِيَ مِن عَساكرِه، فأَقبلَت إليه يَتلُو بَعضُها بَعضًا، فلمَّا تَكامَلَت عنده عَبَرَ البحرَ وسارَ، فاجتَمعَ بالمُعتَمِدِ بن عبَّاد بإشبيلية، وكان قد جَمعَ عَساكرَه أيضًا، وخَرجَ من أَهلِ قُرطُبة عَسكرٌ كَثيرٌ. وقَصدَهُ المُتَطَوِّعَةُ من سائرِ بلادِ الأندلسِ، ووَصَلت الأَخبارُ إلى ألفونسو فجَمعَ فِرسانَه وسارَ من طُليطلة، وكَتبَ إلى أَميرِ المسلمين كِتابًا كَتَبَهُ له بعضُ أُدباءِ المُسلِمين، يُغلِظ له القَولَ، ويَصِفُ ما عنده من القُوَّةِ والعَددِ، وبالَغَ الكاتِبُ في الكِتابِ. فأَمَرَ أَميرُ المُسلمين أبا بكرِ بن القَصيرَةِ أن يُجيبَهُ، وكان كاتِبًا مُفْلِقًا، فكَتبَ فأَجادَ، فلمَّا قَرأهُ على أَميرِ المُسلِمين قال: هذا كِتابٌ طَويلٌ، أَحضِر كِتابَ ألفونسو واكتُب في ظَهرِه: الذي يكون سترا له الذي سَيكونُ سَتَراهُ. فلمَّا عادَ الكِتابُ إلى ألفونسو ارتاعَ لذلك، وعَلِمَ أنَّه بُلِيَ بِرَجُلٍ له عَزْمٌ وحَزْمٌ، فازداد استِعدادًا, فجَمعَ ألفونسو فِرسانَه ثم سارَ من طُليطِلة، وسارَ أَميرُ المُسلِمين ابنُ تاشفين، والمُعتَمِدُ بن عبَّاد، حتى أَتوا أَرضًا يُقال لها: الزَّلَّاقَة، من بَلدِ بطليوس، فأَرسلَ ابنُ تاشفين للمُعتَمِد يَأمُرُه أن يكونَ في المُقدِّمَةِ، ففَعلَ، وقد ضَربَ الفونسو خِيامَه في لَحْفِ جَبَلٍ، والمُعتَمِدُ في سَفْحِ جَبَلٍ آخرَ، يَتَراءونَ، ويَنزِلُ أَميرُ المُسلِمين ابنُ تاشفين وَراءَ الجَبَلِ الذي عنده المُعتَمِد، وظَنَّ ألفونسو أنَّ عَساكِرَ المُسلِمين ليس إلَّا الذي يَراهُ. وكان الفِرنجُ في خمسين ألفًا، فتَيَقَّنوا الغَلَبَ، ثم أَقبَلَت الجُيوشُ، ونَزلَت تِجاهَ الفِرنجِ، فاختارَ ابنُ عبَّادٍ أن يكونَ هو المُصادِمُ للفِرنجِ أوَّلًا، وأن يكون ابنُ تاشفين رِدْفًا له. ففَعَلوا ذلك، وأَرسلَ ألفونسو إلى المُعتَمِد في مِيقاتِ القِتالِ، فقال: غَدًا الجُمعةُ، وبَعدَه الأحدُ، فيكونُ اللِّقاءُ يومَ الاثنينِ، فقد وَصلنا على حالِ تَعَبٍ، واستَقرَّ الأَمرُ على هذا، وركب ليلة الجمعة سَحَرًا، وصَبَّحَ بجَيشِه جَيشَ المُعتَمِد بُكرَةَ الجُمعَةِ، غَدْرًا، وظَنًّا منه أن ذلك المُخَيَّم هو جَميعُ عَسكرِ المُسلِمين، فوَقعَ القِتالُ بينهم فصَبرَ المسلمون، فأَشرَفوا على الهَزيمَةِ، وكان المُعتَمِد قد أَرسلَ إلى أَميرِ المُسلِمين ابنِ تاشفين يُعلِمه بمَجيءِ الفِرنجِ للحربِ، فقال: احمِلوني إلى خِيامِ الفِرنجِ، فسار إليها، فبينما هُم في القِتالِ وَصَلَ أَميرُ المُسلِمين إلى خِيامِ الفِرنجِ، فنَهَبَها، وقَتَلَ مَن فيها، فلمَّا رأى الفِرنجُ ذلك لم يَتَمالَكوا أن انهَزَموا، وأَخَذَهم السَّيفُ، وتَبِعَهم المُعتَمِدُ مِن خَلفِهم، ولَقِيَهم أَميرُ المُسلِمين من بين أَيدِيهم، ووَضَعَ فيهم السَّيفَ، فلم يُفلِت منهم أَحَدٌ، ونَجَا ألفونسو في نَفَرٍ يَسيرٍ قِيلَ: 30 رَجُلًا, وجَعلَ المُسلِمون من رُؤوسِ القَتلَى كُوَمًا كَثيرةً، فكانوا يُؤذِّنون عليها إلى أن جِيفَت فأَحرَقوها، وكانت الوَقعَةُ يومَ الجُمعةِ في العَشْرِ الأُوَلِ من شَهرِ رَمضان، وغَنِمَ المسلمون غَنيمةً عَظيمةً, وعَفَّ يوسفُ عن الغَنائمِ، وآثَرَ بها مُلوكَ الأندلسِ لِيَتِمَّ له الأَجرُ، فأَحَبُّوه وشَكَروا له, ورَجعَ أَميرُ المُسلِمين إلى الجَزيرةِ الخَضراء، وعَبرَ إلى سَبتَة، وسار إلى مراكش، فأقامَ بها إلى العامِ المُقبِل."},{"id":1692,"title":"دُخولُ ملكشاه بَغدادَ لأَوَّلِ مَرَّةٍ .","date":["العام الهجري :479","الشهر القمري : ذي الحجة","العام الميلادي :1087"],"text":"دَخَلَ السُّلطانُ ملكشاه بغدادَ في ذي الحجَّةِ، بعدَ أن فَتَحَ حَلَبَ وغَيرَها من بلادِ الشَّامِ والجَزيرةِ، وهي أَوَّلُ مَرَّةٍ يَدخُل فيها بغدادَ، ونَزلَ بدارِ المَملكةِ، وأَرسلَ إلى الخَليفةِ هَدايا كَثيرةً، فقَبِلَها الخَليفةُ، ومِن الغَدِ أَرسلَ نِظامُ المُلْكِ إلى الخَليفَةِ خَدمةً كَثيرةً، فقَبِلَها، وزارَ السُّلطانُ ونِظامُ المُلْكِ مَشهدَ موسى بن جَعفرٍ، وقَبْرَ مَعروفٍ، وأحمدَ بن حَنبلٍ وأبي حَنيفةَ، وغيرَها من القُبورِ المَعروفَةِ، وطُلِبَ نِظامُ المُلْكِ إلى دارِ الخِلافَةِ لَيلًا، فمَضَى في الزَّبْزَبِ-سفينة صغيرة- وعاد من لَيلتِه، ومَضَى السُّلطانُ ونِظامُ المُلْكِ إلى الصَّيدِ في البَرِّيَّةِ، فزارا مَشهدَ أَميرِ المؤمنينَ عَلِيٍّ، ومَشهدَ الحُسينِ، ودَخلَ السُّلطانُ البَرَّ، فاصطادَ شَيئًا كَثيرًا من الغِزلان وغَيرِها، وأَمرَ ببِناءِ مَنارةَ القُرونِ بالسبيعيِّ، وعاد السُّلطانُ إلى بغدادَ، ودَخلَ الخَليفةُ، فخَلَعَ عليه الخِلَعَ السُّلطانيَّةَ، ولمَّا خَرجَ من عندِه لم يَزَل نِظامُ المُلْكِ قائمًا يُقدِّم أَميرًا أَميرًا إلى الخَليفةِ، وكلَّما قَدَّمَ أَميرًا يقول: هذا العَبدُ فلان بن فلان، وأَقطاعُه كذا وكذا، وعِدَّةُ عَسكرِه كذا وكذا، إلى أن أتى على آخرِ الأُمراءِ، وفَوَّضَ الخَليفةُ إلى السُّلطانِ أَمْرَ البلادِ والعِبادِ، وأَمَرَهُ بالعَدلِ فيهم، وطَلَبَ السُّلطانُ أن يُقَبِّلَ يَدَ الخَليفةِ، فلم يُجِبهُ، فسأل أن يُقَبِّلَ خاتَمَه، فأَعطاهُ إيَّاهُ فقَبَّلَهُ، ووَضعَهُ على عَينِه، وأَمَرَهُ الخَليفةُ بالعَوْدِ فعادَ، وخَلَعَ الخَليفةُ أيضًا على نِظامِ المُلْكِ، ودَخلَ نِظامُ المُلْكِ إلى المدرسةِ النِّظاميَّةِ، وجَلسَ في خَزانَةِ الكُتُبِ، وطالَعَ فيها كُتُبًا، وسَمِعَ الناسُ عليه بالمدرسةِ جُزْءَ حَديثٍ، وأَمْلَى جُزءًا آخرَ، وأَقامَ السُّلطانُ ببغداد إلى صَفَر سَنةَ 480هـ وسارَ منها إلى أصبهان."},{"id":1693,"title":"الخَليفةُ العبَّاسي المُقتَدِي يَتَزوَّج ابنةَ السُّلطان السلجوقي ملكشاه .","date":["العام الهجري :480","الشهر القمري : محرم","العام الميلادي :1087"],"text":"تَزوَّج الخَليفةُ المُقتَدِي بابنةِ السُّلطانِ ملكشاه فاشتَرطَت عليه أن لا يُبقِي تَحتَه لا زَوجةً ولا سُرِّيَّةً إلا هي وَحدَها، فأُجِيبَت رَغبتُها. فنُقِلَ جِهازُها إلى دارِ الخِلافَةِ على مائةٍ وثلاثين جَمَلًا مُجَلَّلَةً بالدِّيباجِ الرُّوميِّ، وكان أَكثرَ الأحمالِ الذهبُ والفِضَّةُ وعلى أربعٍ وسبعين بَغْلًا مُجَلَّلَةً بأَنواعِ الدِّيباجِ المَلَكِيِّ، وأَجراسُها وقَلائدُها من الذهبِ والفِضَّةِ، وكان على سِتَّةٍ منها اثنا عشر صُندوقًا من فِضَّةٍ لا يُقَدَّر ما فيها من الجَواهرِ والحُلِيِّ، وبين يدي البِغالِ ثلاثةٌ وثلاثون فَرَسًا من الخَيْلِ الرَّائقَةِ، عليها مَراكِبُ الذهبِ مُرَصَّعَةً بأَنواعِ الجَوهَرِ، ومَهْدٌ عَظيمٌ كَثيرُ الذَّهبِ، وسار بين يدي الجِهازِ سعدُ الدولةِ كوهرائين، والأَميرُ برسق، وغيرُهما، ونَثَرَ أَهلُ نَهرِ معلى عليهم الدَّنانيرَ والثِّيابَ، وكان السُّلطانُ قد خَرجَ عن بغدادَ مُتَصَيِّدًا، ثم أَرسلَ الخَليفةُ الوَزيرَ أبا شُجاعٍ إلى تركان خاتون، زَوجَةِ السُّلطانِ، وبين يَديهِ نحو ثلاثمائة مَوْكِبِيَّةٍ، ومِثلُها مَشاعِلُ، ولم يَبقَ في الحَريمِ دُكَّانٌ إلَّا وقد أُشعِل فيها الشَّمعةُ والاثنتانِ وأكثرُ من ذلك، وأَرسلَ الخَليفةُ مع ظُفَر خادمِه مَحِفَّةً لم يُرَ مِثلُها حُسْنًا، وقال الوَزيرُ لتركان خاتون: سيدنا ومولانا أَميرُ المؤمنين يقول: {إن الله يأمركم أن تؤدوا الأمانات إلى أهلها}، وقد أَذِنَ في نَقلِ الوَديعَةِ إلى دارِه. فأَجابَت بالسَّمعِ والطَّاعةِ، وحَضَرَ نِظامُ المُلْكِ فمَن دُونَه مِن أَعيانِ دَولةِ السُّلطانِ، ثم جاءَت الخاتون ابنةُ السُّلطانِ بعدَ الجَميعِ، في مَحِفَّةٍ مُجَلَّلَةٍ، عليها من الذهبِ والجَواهرِ أكثرُ شيءٍ، وقد أَحاطَ بالمَحِفَّةِ مائتا جاريةٍ من الأتراكِ بالمَراكبِ العَجيبةِ، وسارَت إلى دارِ الخِلافةِ، وكانت ليلةً مَشهودَةً لم يُرَ ببغدادَ مِثلُها، فلمَّا كان الغَدُ أَحضرَ الخَليفةُ أُمراءَ السُّلطانِ لِسِماطٍ أَمَرَ بِعَمَلِهِ وخَلَعَ عليهم كُلِّهم، وعلى كلِّ مَن له ذِكْرٌ في العَسكرِ، وأَرسلَ الخِلَعَ إلى الخاتون زَوجةِ السُّلطانِ، وإلى جَميعِ الخَواتين."},{"id":1694,"title":"فَتحُ الرُّومِ مَدينةَ زويلة من إفريقية .","date":["العام الهجري :481","العام الميلادي :1088"],"text":"كان الأَميرُ تَميمُ بن المُعِزِّ بن باديس صاحِب المَهدِيَّةِ قد أَكثرَ غَزْوَ بِلادِ الرُّومِ في البَحرِ، فخَرَّبَها، وشَتَّتَ أَهلَها، فاجتَمَعوا من كلِّ جِهَةٍ، واتَّفَقوا على إنشاءِ الشواني -سُفُن حَربيَّة ضَخمَة - لِغَزوِ المَهدِيَّة، ودَخلَ معهم البيشانيون، والجنوبيون، وهما من الفِرنج، فأَقاموا يُعمِّرون الأُسطولَ أَربعَ سِنين، واجتَمَعوا بجَزيرَةِ قوصرة في أَربعِ مائةِ قطعةٍ، فأَرادَ تَميمٌ أن يُسَيِّر عُثمانَ بنَ سَعيدٍ المَعروف بالمُهْرِ، مُقَدَّم الأُسطولِ الذي له، لِيَمنَعَهم من النُّزولِ، فمَنعَه من ذلك بعضُ قُوَّادِه، فجاءَت الرُّومُ، وأَرسَلوا، وطَلَعوا إلى البَرِّ، ونَهَبوا، وخَرَّبوا، وأَحرَقوا، ودَخَلوا زويلةَ ونَهَبوها، وكانت عَساكرُ تَميمٍ غائبةً في قِتالِ الخارجِين عن طاعَتِه، ثم صالَحَ تَميمٌ الرُّومَ على ثلاثين ألف دِينارٍ، وَرَدِّ جَميعِ ما حَووهُ مِن السَّبْيِ."},{"id":1695,"title":"الفِتنَةُ ببغداد .","date":["العام الهجري :481","الشهر القمري : صفر","العام الميلادي :1088"],"text":"شَرَعَ أَهلُ بابِ البَصرَةِ في بِناءِ القَنطرَةِ الجَديدةِ، واتُّفِقَ أن كوهرائين سار في سميرية -نوع من السُّفُن-، وأَصحابُه يَسيرونَ على شاطئِ دِجلَة بسميريه، فوَقفَ أَهلُ بابِ الأزج على امرأةٍ كانت تَسقِي الناسَ من مُزَمَّلَةٍ لها على دِجلَة، فحَمَلوا عليها، على عادةٍ لهم، وجَعَلوا يَكسِرونَ الجِرارَ، ويَقولون: الماءُ للسَّبيلِ! فلما رَأت سعدَ الدولةِ كوهرائين استَغاثَت به، فأَمَرَ بإبعادِهم عنها، فضرَبَهم الأتراكُ بالمقارِعِ، فسَلَّ العامَّةُ سُيوفَهم ثم إن كوهرائين خَرجَ من السميرية إليهم راجِلًا، فحَمَل أَحدُهم عليه، فطَعَنَه بأَسفلَ رُمحِه، فأَلقاهُ في الماءِ والطِّينِ، فحَمَلَ أَصحابُه على العامَّةِ، فقاتَلوهُم، وحَرَصوا على الظَّفَرِ بالذي طَعَنَهُ، فلم يَصِلوا إليه، وأَخذَ ثَمانيةَ نَفَرٍ، فقَتَلَ أَحدَهم، وقَطعَ أَعصابَ ثَلاثةِ نَفَرٍ، وأَرسلَ قَباءَه إلى الدِّيوانِ وفيه أَثَرُ الطَّعنَةِ والطِّينِ يَستَنفِر على أَهلِ بابِ الأزج. ثم إن أهلَ الكَرخِ عَقَدوا لِأَنفُسِهم طاقًا آخرَ على بابِ طاقِ الحراني، وفَعَلوا كفِعلِ أَهلِ البَصرَةِ."},{"id":1696,"title":"فَتْحُ ملكشاه مَدينةَ سمرقند .","date":["العام الهجري :482","العام الميلادي :1089"],"text":"كان قد مَلَكَ سمرقند أحمدُ خان بن خضر خان، وهو ابنُ أخي تركان خاتون، زَوجةِ السُّلطانِ ملكشاه، وكان صَبِيًّا ظالِمًا، قَبيحَ السِّيرَةِ، يُكثِر مُصادَرةَ الرَّعيَّةِ، فنَفَروا منه، وكَتَبوا إلى السُّلطانِ سِرًّا يَستَغيثون به، ويَسأَلونَه القُدومَ عليهم لِيَملِك بِلادَهم، فتَحرَّكَت دَواعي السُّلطانِ إلى مُلْكِها، فسار من أصبهان، وجَمعَ العَساكرَ من البلادِ جَميعِها، فعَبَرَ النهرَ فلمَّا قَطعَ النهرَ قَصَدَ بُخارى، وأَخذَ ما على طَريقِه، ثم سار إليها ومَلَكَها وما جاوَرَها من البلادِ، وقَصَدَ سمرقند ونازَلَها، وحَصرَ البلدَ، وضَيَّقَ عليه، وأَعانَه أَهلُ البلدِ بالإقاماتِ، وفَرَّقَ أحمد خان، صاحِبُ سمرقند، أَبراجَ السُّورِ على الأُمراءِ ومَن يَثِقُ بهِ مِن أَهلِ البَلدِ، فرَمَى السُّلطانُ ملكشاه السُّورَ بالمنجنيقات، فأَحدثَ فيه عِدَّةَ ثُلَمٍ، وأَخَذَ أَحدَ الأَبراجِ، فلمَّا صَعدَ عَسكرُ السُّلطانِ إلى السُّورِ هَربَ أحمدُ خان، واختَفَى في بُيوتِ بَعضِ العامَّةِ فدُلَّ عليه وأُخِذَ وحُمِلَ إلى السُّلطانِ وفي رَقَبَتِه حَبلٌ، فأَكرَمَه السُّلطانُ، وأَطلَقَه وأَرسلَه إلى أصبهان، ومعه مَن يَحفَظهُ، ورَتَّبَ بسمرقند الأَميرَ العَميدَ أبا طاهرٍ عَميدَ خوارزم."},{"id":1697,"title":"غَزْوُ السُّلطانِ ملكشاه كاشغرَ .","date":["العام الهجري :482","العام الميلادي :1089"],"text":"وسار السُّلطانُ قاصِدًا كاشغر، فبَلَغَ إلى يوزكند، وأَرسلَ منها رُسُلًا إلى مَلِكِ كاشغر يَأمُرهُ بإقامَةِ الخُطبَةِ، وضَرْبِ السِّكَّةِ باسمِه ويَتوَعَّدهُ إن خالَفَ بالمَسيرِ إليه. ففَعلَ ذلك وأَطاعَ، وحَضرَ عند السُّلطانِ، فأَكرَمَه وعَظَّمَه، وتابَعَ الإنعامَ عليه، وأَعادَهُ إلى بَلدِه."},{"id":1698,"title":"غَلاءٌ وقَحْطٌ بإفريقية .","date":["العام الهجري :482","العام الميلادي :1089"],"text":"كان بإفريقية هذه السَّنَةَ غَلاءٌ شَديدٌ، وبَقِيَ كذلك إلى سَنةِ أربعٍ وثمانين، وصَلُحَت أَحوالُ أَهلِها، وأَخصَبَت البلادُ، ورَخُصَت الأسعارُ، وأَكثرَ أَهلُها الزَّرعَ."},{"id":1699,"title":"فَتْحُ عَساكِر صاحِبِ مصر العُبيدِيِّ عَكَّا وغَيرَها من الشامِ .","date":["العام الهجري :482","العام الميلادي :1089"],"text":"خَرجَت عَساكرُ صاحبِ مصر العُبيديِّ بقِيادَةِ بَدرٍ أَميرِ الجُيوشِ إلى الشامِ في جَماعةٍ من المُقدِّمين، فحَصَروا مَدينةَ صُور، وكان قد تَغلَّبَ عليها القاضي عَيْنُ الدولةِ بن أبي عَقيلٍ، وامتَنعَ عليهم، ثم تُوفِّي، ووَلِيَها أَولادُه، فحَصرَهُم العَسكرُ المصريُّ فلم يكُن لهم من القُوَّةِ ما يَمتَنِعون بها، فسَلَّموها إليهم، ثم سار بدرُ بالعَسكرِ عنها إلى مَدينةِ صَيْدا، ففَعلوا بها كذلك، ثم ساروا إلى مَدينةِ عَكَّا، فحَصَروها، وضَيَّقوا على أَهلِها، فافتَتَحوها، وقَصَدوا مَدينةَ جُبيل، فمَلَكوها أيضًا، وأَصلَحوا أَحوالَ هذه البلادِ، وقَرَّروا قَواعِدَها، وساروا عنها إلى مصر عائدِينَ، واستَعملَ أَميرُ الجُيوشِ على هذه البلادِ الأُمراءَ والعُمَّالَ."},{"id":1700,"title":"عِصيانُ أَهلِ سمرقند على نائبِ السُّلطانِ ملكشاه .","date":["العام الهجري :482","العام الميلادي :1089"],"text":"لمَّا رَجعَ السُّلطانُ ملكشاه من كاشغر إلى خُراسان، وأَبعدَ عن سمرقند لم يَتَّفِق أَهلُها وعَسكرُها المعروفون بالجَكلِيَّة مع العَميدِ أبي طاهرٍ، نائبِ السُّلطانِ عندهم، حتى كادوا يَثِبونَ عليه، فاحتالَ حتى خَرجَ مِن عندهم، ومَضَى إلى خوارزم. كان مُقدِّم الجَكلِيَّة واسمُه عَيْنُ الدولةِ، قد خافَ السُّلطانَ لهذا الحادثِ، فكاتَبَ يعقوبَ تكين أخا مَلِكِ كاشغر، ومَملَكَتُه تُعرَف بآب نباشي، وبِيَدِه قَلعتُها، واستَحضَرهُ، فحَضرَ عنده بسمرقند، واتَّفَقا، ثم إن يعقوبَ عَلِمَ أن أَمرَهُ لا يَستَقيم مع عَيْنِ الدولةِ، فقَتَلَه، اتَّصلَت الأَخبارُ بعِصيانِ سمرقند بالسُّلطانِ ملكشاه، وقَتْلِ عَيْنِ الدولةِ، مُقدِّم الجَكليَّة، عادَ السُّلطانُ إلى سمرقند، فلمَّا وَصلَ إلى بُخارَى هَربَ يَعقوبُ المُستَولِي على سمرقند، ومَضَى إلى فرغانة، ولَحِقَ بوِلايَتِه، ووَصلَ جَماعةٌ من عَسكرِه إلى السُّلطانِ مُسْتَأْمِنِينَ، ولمَّا وَصلَ السُّلطانُ إلى سمرقند مَلَكَها، ورَتَّب بها الأَميرَ أبر."},{"id":1701,"title":"طَلَبُ السُّلطانِ ملكشاه يعَقوبَ أخي مَلِكِ كاشغر  .","date":["العام الهجري :482","العام الميلادي :1089"],"text":"سارَ السُّلطانُ ملكشاه في إثْرِ يعقوبَ لِقَتلِه مُقدِّمَ الجَكليَّة, والذي دَخلَ إلى أَخيهِ بكاشغر مُستجِيرًا به، فسَمِعَ السُّلطانُ بذلك، فأَرسلَ إلى مَلِكِ كاشغر يَتوعَّدُه، إن لم يُرسِلهُ إليه، أن يَقصِد بِلادَه، ويَصيرُ هو العَدُوَّ، فخافَ أن يَمنَع السُّلطانَ، فأَدَّاهُ اجتِهادُه إلى أن قَبَضَ على أَخيهِ يعقوبَ، وأَظهرَ أنه كان في طَلَبِه، فظَفَرَ به، وسَيَّرَهُ مع وَلَدِه، وجَماعةٍ من أَصحابِه، وكَّلَهم بيعقوب، وأَرسلَ معهم هَدايا كَثيرةً للسُّلطانِ، وأَمَرَ وَلدَه أنه إذا وَصلَ إلى قَلعةٍ بقُربِ السُّلطانِ أن يَسْمُلَ يعقوبَ ويَتركهُ، فإن رَضِيَ السُّلطانُ بذلك، وإلَّا سَلَّمَه إليه، فحَدثَ أن طغرل بن ينال استَولى على كاشغر وأَخَذَ صاحبَها أخا يعقوب, فأَطلَقوا يعقوبَ، فلمَّا رأى السُّلطانُ ذلك ورأى طَمَعَ طغرل بن ينال، ومَسيرَه إلى كاشغر، وقَبْضَ صاحِبِها، ومِلْكِه لها مع قُرْبِه منه، خاف أن يَنحَلَّ بَعضُ أَمرِه وتَزولَ هَيبتُه، وعَلِمَ أنه متى قَصدَ طغرل سار من بين يَديهِ، فإن عادَ عنه رَجعَ إلى بِلادِه، وكذلك يعقوب أخو صاحِبِ كاشغر، وأنه لا يُمكِنُه المَقامُ لِسِعَةِ البِلادِ وراءَهُ وخَوْفِ الموتِ بها، فوَضعَ تاجَ المُلْكِ على أن يَسعَى في إصلاحِ أَمرِ يعقوب معه، ففَعلَ ما أَمرَهُ به السُّلطانُ، فاتَّفَقَ هو ويعقوبُ، وعاد إلى خراسان، وجَعلَ يعقوبَ مُقابِلَ طغرل يَمنعُه من القُوَّةِ، ومِلْكِ البلادِ، وكلٌّ منهما يقوم في وَجهِ الآخرِ."},{"id":1702,"title":"عُدوانُ ابنِ عَلَوِيٍّ  مَلِكِ العَربِ على مَدينةِ سوسة بإفريقية  .","date":["العام الهجري :482","العام الميلادي :1089"],"text":"نَقَضَ ابنُ عَلَوِيٍّ ما بينه وبين تَميمِ بن المُعِزِّ بن باديس أَميرِ إفريقية من العَهْدِ، وسار في جَمْعٍ مِن عَشيرَتِه العَربِ، فوَصلَ إلى مَدينةِ سوسة من بلادِ إفريقية، وأَهلُها غارُّونَ لم يَعلَموا به، فدَخلَها عُنوةً، وجَرَى بينه وبين مَن بها من العَسكرِ والعامَّةِ قِتالٌ، فقُتِلَ من الطَّائِفَتينِ جَماعةٌ وكَثُرَ القَتلُ في أَصحابِه والأَسْرُ، وعَلِمَ أنه لا يَتِمُّ له مع تَميمٍ حَالٌ، ففارَقَها، وخَرجَ منها إلى حِلَّتَهُ من الصَّحراءِ."},{"id":1703,"title":"وَفاةُ أبي بكرٍ السَّرخسي الحنفيِّ .","date":["العام الهجري :482","العام الميلادي :1089"],"text":"هو شَمسُ الأئمَّةِ أبو بكرٍ محمدُ بن أحمدَ بن سَهلِ السَّرخسي، صاحِبُ ((المبسوط)) بَرَعَ في الفِقهِ وعِلْمِ الكلامِ والأُصولِ والمُناظَرَةِ، أَحدُ الفُحولِ الأئمَّةِ الكِبارِ أَصحابِ الفُنونِ، لَزِمَ الإمامُ شَمسُ الأئمَّةِ أبا محمدٍ عبدَ العزيز الحلوانيَّ حتى تَخرَّجَ به وصارَ أَنظَرَ أَهلِ زَمانِه وأَخذَ في التَّصنيفِ وناظَرَ الأَقرانَ فظَهرَ اسمُه وشاعَ خَبرُه. سُجِنَ بسَببِ فَتوى له وبَقِيَ في سِجنِه خمس عشرة سَنةً تقريبًا، وكان يُملِي على طُلَّابِه من سِجنِه كِتابَه ((المَبسوط)) في الفِقهِ وهو كِتابٌ كَبيرٌ جِدًّا في الفِقهِ الحَنَفيِّ، وله شَرح ((السير الكبير))، ثم ذَهبَ إلى سمرقند بعد خُروجِه من السِّجنِ وبَقِيَ فيها. قال ابنُ قطلوبغا: \"قال في ((المسالك)): حُكِيَ عنه أنه كان جالسًا في حَلَقةِ الاشتِغالِ فقِيلَ له: حُكِيَ عن الشافعيِّ أنه كان يَحفَظُ ثلاثمائة كَرَّاس. فقال: حفظ الشافعي زكوة ما أحفظ. فحُسِبَ حِفظُه فكان اثنى عشر ألف كَرَّاس. قلتُ: وقد شاع عنه أنه أَملَى ((المبسوط)) من حِفظِه وهو أربعة عشر مُجلَّدًا، أَملاهُ من خاطِرِه من غَيرِ مُراجَعةٍ إلى شيءٍ من الكُتُبِ\" وشَرحَ ((السير الكبير)) في جُزأَينِ ضَخمَينِ، أَملاهُما وهو في الجُبِّ كان مَحبوسًا فيه بسَببِ كَلمةٍ نَصَحَ بها. وكان يُملِي عليهم وهم على أعلى الجُبِّ يَكتُبون ما يُملِي عليهم. فلمَّا وَصلَ إلى بابِ الشروطِ حَصَلَ الفَرجُ فأُطلِقَ؛ فخَرَجَ في آخرِ عُمرِه من \"أوزكند\" إلى \"فرغانة\" فأَنزَلهُ الأَميرُ حَسَنٌ بمَنزِلِه، فوَصلَ إليه الطَلَبةُ، فأَكملَ الإملاءَ في دِهليزِ الأَميرِ.\" وقد اختُلِفَ في سَنةِ وَفاتِه فقِيلَ: في هذه السَّنَةِ، وقِيلَ: في سَنةِ 486هـ."},{"id":1704,"title":"الفِتنَةُ بين السُّنَّةِ والشِّيعَةِ ببغداد .","date":["العام الهجري :482","الشهر القمري : صفر","العام الميلادي :1089"],"text":"كَبَسَ أَهلُ بابِ البَصرَةِ السُّنَّةُ الكَرخَ، فقَتَلوا رَجلًا وجَرَحوا آخرَ، فأَغلقَ الشِّيعةُ من أَهلِ الكَرخِ الأَسواقَ، ورَفَعوا المَصاحِفَ، وحَمَلوا ثِيابَ الرَّجُلينِ وهي بالدَّمِ، ومَضوا إلى دارِ العَميدِ كَمالِ المُلْكِ أبي الفَتحِ الدهستاني مُستَغيثينَ، فأَرسلَ إلى النَّقيبِ طِرادِ بن محمدٍ يَطلُب منه إِحضارَ القاتِلين، فقَصَدَ طِرادٌ دارَ الأميرِ بوزان بقَصرِ ابنِ المأمونِ، فطالَبَه بُوزان بهم، ووَكَّلَ به، فأَرسلَ الخَليفةُ إلى بُوزان يُعرِّفهُ حالَ النَّقيبِ طِرادٍ، ومَحِلَّه، ومَنزِلَتَه، فخَلَّى سَبيلَه واعتَذرَ إليه، فسَكَّنَ العَميدُ كَمالُ المُلْكِ الفِتنةَ، وكَفَّ الناسُ بَعضُهم عن بعضٍ، ثم سار إلى السُّلطانِ، فعادَ الناسُ إلى ما كانوا فيه من الفِتنَةِ، ولم يَنقَضِ يومٌ إلا عن قَتْلَى وجَرْحَى. وسَبَّ أَهلُ الكَرخِ الصَّحابةَ وأَزواجَ النبيِّ صلَّى الله عليه وسلَّم."},{"id":1705,"title":"الفِتنَةُ الثانيةُ بين السُّنَّةِ والشِّيعَةِ ببغداد .","date":["العام الهجري :482","الشهر القمري : جمادى الأولى","العام الميلادي :1089"],"text":"كَثُرَت الفِتَنُ ببغداد بين الشِّيعةِ من أَهلِ الكَرخِ وغَيرِها من المَحالِّ مِن أَهلِ السُّنَّةِ، وقُتِلَ بينهم عَددٌ كَثيرٌ، واستَولَى أَهلُ المَحالِّ على قِطعَةٍ كَبيرةٍ من نَهرِ الدَّجاجِ، فنَهَبوها، وأَحرَقوها، فنَزل شِحْنَةُ بغداد -المسؤول عن ضبط بغداد- وهو خمارتكين النائبُ عن كوهرائين، على دِجلَة في خَيْلِه ورَجِلِه، لِيَكُفَّ الناسَ عن الفِتنةِ، فلم يَنتَهوا، وكان أهلُ الكَرخِ يَجرُون عليه وعلى أَصحابِه الجِراياتِ والإقاماتِ، وفي بعضِ الأيامِ وَصَلَ أَهلُ بابِ البَصرَةِ إلى سُويقَةِ غالبٍ، فخَرجَ مِن أَهلِ الكَرخِ مَن لم تَجرِ عادَتُه بالقِتالِ، فقاتَلوهُم حتى كَشَفوهُ،. فرَكِبَ خَدَمُ الخَليفةِ، والحُجَّابُ، والنُّقَباءُ، وغَيرُهم من أَعيانِ الحَنابِلَةِ، إلى خمارتكين، وساروا معه إلى أَهلِ الكَرخِ، فقَرأَ عليهم كِتابًا من الخَليفةِ يَأمُرهم بالكَفِّ، ومُعاوَدَةِ السُّكونِ، وحُضورِ الجَماعةِ والجُمعةِ، والتَّدَيُّنِ بمَذهبِ أَهلِ السُّنَّةِ، فأجابوا إلى الطاعةِ، فبينما هم كذلك أَتاهُم الصَّارِخُ من نَهرِ الدَّجاجِ بأن السُّنَّةَ قد قَصَدوهُم، والقِتالُ عندهم، فمَضوا مع خمارتكين، ومُنِعوا من الفِتنَةِ، وسَكَنَ الناسُ، وكَتَبَ سُنَّةٌ مِن أَهلِ الكَرخِ على أَبوابِ مَساجِدِهم: \"خَيرُ الناسِ بعدَ رَسولِ الله صلَّى الله عليه وسلَّم أبو بكرٍ ثم عُمَرُ ثم عُثمانُ ثم عَلِيٌّ، ومِن عند هذا اليومِ ثارَ شِيعَةٌ من أَهلِ الكَرخِ، وقَصَدوا شارعَ ابنِ أبي عَوفٍ ونَهَبوهُ، ورَفعَ العامَّةُ الصُلبانَ وهَجَموا على الوَزيرِ في حُجرَتِه، وأَكثَروا من الكَلامِ الشَّنيعِ، وقُتِلَ ذلك اليومَ رَجلٌ هاشِميٌّ مِن أَهلِ بابِ الأزج بسَهمٍ أَصابَهُ، فثارَ العامَّةُ هناك بعَلَوِيٍّ كان مُقِيمًا بينهم، فقَتَلوهُ وحَرَقوهُ، وجَرَى مِن النَّهْبِ، والقَتْلِ، والفَسادِ أُمورٌ عَظيمةٌ، فأَرسلَ الخَليفةُ إلى سَيفِ الدَّولةِ صَدَقةَ بنِ مزيد، فأَرسلَ عَسكرًا إلى بغداد، فطَلَبوا المُفسِدين والعَيَّارِين، فهَرَبوا منهم، فهُدِمَت دُورُهم، وقُتِلَ منهم ونُفِيَ وسَكنَت الفِتنةُ، وأَمِنَ الناسُ."},{"id":1706,"title":"عَودَةُ يُوسفَ بنِ تاشفين للأندَلُسِ ونِهايَةُ مُلوكِ الطَّوائِف .","date":["العام الهجري :483","العام الميلادي :1090"],"text":"جازَ يوسفُ بن تاشفين ثانِيةً وتَثاقَلَ أُمراءُ الطَّوائفِ عن لِقائِه لِمَا أَحَسُّوا مِن نَكيرِه عليهم أَخذَهُم المُكوسَ، فوَجَدَ عليهم، وعَهِدَ بِرَفعِ المُكوسِ وتَحرِّى العَدل، فلمَّا أَجازَ انقَبَضوا عنه إلا ابنَ عبَّادٍ فإنه بادَرَ إلى لِقائِه, وتَوافَقَ مُلوكُ الطَّوائفِ على قَطْعِ المَدَدِ عن عَساكرِه ومحلاتِه فساءَ نَظرُه، قال ابنُ خَلدون: \"وأَفتاهُ الفُقهاءُ وأَهلُ الشُّورَى من المَغرِب والأَندَلُس بخَلعِهم وانتِزاعِ الأَمرِ من أَيدِيهم، وصارَت إليه بذلك فَتاوَى أَهلِ الشرقِ الأَعلامِ مثل: الغَزَالي والطَّرطوشي\"، فاتَّجَهَ إلى غرناطة واستَنزَل صاحِبَها عُبيدَ الله بن بلكّين بن باديس وَأخاهُ تَميمًا من مالقة بعدَ أن كان منهما مُداخلةُ الطَّاغِيَة ألفونسو في عَداوَةِ يوسف بن تاشفين، وبَعَثَ بهما إلى المَغرِب فخافَ ابنُ عبَّادٍ عند ذلك منه وانقَبَضَ عن لِقائِه وفَشَت السِّعاياتُ بينهما. ونَهَضَ يُوسفُ بن تاشفين إلى سَبتَة فاستَقرَّ بها، وعَقَدَ للأَميرِ سير بن أبي بكر بن محمد وركوت على الأَندلسِ وأَجازَهُ فقَدِمَ عليها، وقَعَدَ ابنُ عبَّادٍ عن تَلَقِّيهِ ومَبَرَّتِه فأَحفَظَهُ ذلك، وطالَبَهُ بالطَّاعَةِ للأَميرِ يوسف والنُّزولِ عن الأَمرِ، ففَسَدَ ذاتُ بينِهما، وغَلَبَهُ على جَميعِ عَمَلِه. واستَنزَلَ أَولادَ المأَمونِ من قُرطبة، ويَزيدَ الرائضَ من رندة وقرمونة، واستَولَى على جَميعِها وقَتَلَهم. وصَمَدَ إلى إشبيليّة فحاصَرَ المُعتَمِد بها وضَيَّقَ عليه، واستَنجَدَ الطاغِيَة فعَمَدَ الى استِنقاذِه من هذا الحِصارِ، فلم يُغنِ عنه شَيئًا، وكان دِفاعُ لمَتونَة ممَّا فَتَّ في عَضُدِه، ودَخلَ المُرابِطون قُرطبة سَنةَ 484هـ, واقتَحمَ والمُرابِطون إشبيليّة عليه عُنوةً سَنةَ 484هـ وتقبّض وقَبَضَ على المُعتَمِد وقادَهُ أَسيرًا إلى مَراكش، فلم يَزَل في اعتِقالِ يوسف بن تاشفين إلى أن هَلَكَ في مَحبَسِه بأغمات سَنةَ 490هـ، ثم عَمَدَ إلى بطليوس وتقبّض وقَبَضَ على صاحبها عُمرَ بنَ الأَفطَس فقَتَلَه وابنَيْهِ يومَ الأضحى سَنةَ 489هـ بما صَحَّ عنده مِن مُداخَلَتِهم الطاغية، وأن يُمَلِّكوهُ مَدينةَ بطليوس، ثم أجازَ يوسفُ بن تاشفين الجوازَ الثالثَ سَنةَ 490هـ وزَحَفَ إليه الطاغية فبَعثَ عَساكرَ المُرابِطين لنظر محمد بن الحاج فانهَزمَ النَّصارَى أَمامَه، وكان الظهورُ للمُسلِمين. ثم أَجازَ الأَميرُ يحيى بن أبي بكر بن يوسف بن تاشفين سَنةَ 493هـ، وانضَمَّ إليه محمدُ بن الحاج، وسيرُ بنُ أبي بكر، واقتَحَموا عامَّةَ الأندلسِ من أَيدِي مُلوكِ الطَّوائفِ، ولم يَبقَ منها إلا سرقسطة في يَدِ المُستَعينِ بن هود الذى كان قد أَبلَى بَلاءً حَسَنًا في جِهادِ النَّصارَى جَعلَت ابنُ تاشفين يُبقِيه في مُلكِه، وصار سَدًّا مَنيعًا في حِمايَةِ الثُّغورِ الشماليَّةِ من هَجَماتِ النَّصارَى, قال الذهبيُّ: \"سالَمَ المُستَعِينُ بالله ابنُ هود صاحِبُ شَرقِ الأندلسِ ابنَ تاشفين، وكان يَبعَثُ إليه بالتُّحَفِ. وكان هو وأَجنادُه ممَّن يُضرَب بهم المَثَلُ في الشَّجاعَةِ، فلمَّا احتَضَر يوسفُ بن تاشفين أَوْصَى وَلَدَهُ عَلِيًّا بِبَنِي هود، وقال: اترُكهُم بينَك وبين العَدُوِّ، فإنَّهم شُجعانٌ\" وغَزَا الأَميرُ مزدلي صاحِبُ بلنسية إلى بَلدِ برشلونة فأَثخَنَ بها وبَلَغَ إلى حيث لم يَبلُغ أَحدٌ قَبلَهُ، ورَجَعَ."},{"id":1707,"title":"الخَليفةُ العبَّاسيُّ المُقتَدِي يُلزِم أَهلَ الذِّمَّةِ بلِباسٍ يُمَيِّزهُم عن المسلمين .","date":["العام الهجري :483","الشهر القمري : صفر","العام الميلادي :1090"],"text":"كَتَبَ الوَزيرُ أبو شُجاعٍ محمدُ بن حُسينٍ الروذراوريُّ إلى الخَليفةِ يُعرِّفهُ باستِطالَةِ أَهلِ الذِّمَّةِ على المسلمين، وأن الواجِبَ تَمييزُهم عنهم؛ فأَمرَهُ الخَليفةُ أن يَفعلَ ما يَراهُ. فأَلزَمَهم الوَزيرُ لُبْسَ الغيارِ والزَّنانيرِ وتَعليقَ الدَّراهِم الرصاص في أَعناقِهم، مَكتوبٌ على الدَّراهِم \"ذِمِّي\" وتُجعَل هذه الدَّراهِم أيضًا في أَعناقِ نِسائِهم في الحَمَّاماتِ ليُعرَفنَ بها، وأن يَلبَسنَ الخِفافَ فَرْدًا أَسوَد وفَرْدًا أَحمَر، وجُلْجُلًا في أَرجُلِهِنَّ. فذُلُّوا وانقَمَعوا بذلك. وأَسلَم حينئذ عَدَدٌ منهم."},{"id":1708,"title":"نَهْبُ العَربِ البَصرَةَ .","date":["العام الهجري :483","الشهر القمري : جمادى الأولى","العام الميلادي :1090"],"text":"نَهَبَ العَربُ البَصرةَ نَهْبًا قَبيحًا، وسَببُ ذلك أنَّه وَرَدَ إلى بغداد، في بَعضِ السِّنين، رَجلٌ أَشقرُ مِن سَوادِ النِّيلِ يَدَّعِي الأَدبَ، والنَّظَرَ في النُّجومِ، ويَستَجرِي الناسَ، فلَقَّبَهُ أَهلُ بغداد تليا –أي التابع-، وكان نازلًا في بَعضِ الخاناتِ، فسَرَقَ ثِيابًا من الدِّيباجِ وغَيرِه، وأَخفَاها في خلفا، وسار بهم، فرَآها الذين يَحفَظون الطَّريقَ، فمَنَعوهُ من السَّفَر اتِّهامًا له، وحَمَلوهُ إلى المُقَدَّم عليهم، فأَطلَقَه لِحُرمَةِ العِلْمِ، فسار إلى أَميرٍ من أُمراءِ العَربِ مِن بَنِي عامرٍ، وبِلادُه مُتاخِمَة الأَحساء، وقال له: أنت تَملِك الأرضَ، وقد فَعلَ أَجدادُك بالحاج كذا وكذا، وأَفعالُهم مَشهورَةٌ، مَذكورَةٌ في التَّواريخِ، وحَسَّنَ له نَهْبَ البَصرَةِ وأَخْذَها، فجَمعَ مِن العَربِ ما يَزيدُ على عشرةِ آلافِ مُقاتلٍ، وقَصدَ البَصرَةَ، وبها العَميدُ عصمة، وليس معه من الجُنْدِ إلا اليَسيرُ، لِكَوْنِ الدنيا آمِنَةً مِن ذاعِرٍ، ولأنَّ الناسَ في جِنَّةٍ مِن هَيبَةِ السُّلطانِ، فخَرجَ إليهم في أَصحابِه، وحارَبَهم، ولم يُمَكِّنهُم من دُخولِ البَلدِ، فأَتاهُ مَن أَخبَرهُ أنَّ أَهلَ البَلَدِ يُريدونَ أن يُسلِّموهُ إلى العَرَبِ، فخاف، ففارَقَهم، وقَصدَ الجَزيرةَ التي هي مكانُ القَلعةِ بنَهرِ معقل، فلمَّا عاد أَهلُ البَلدِ بذلك فارَقوا دِيارَهم وانصَرَفوا، ودَخلَ العَربُ حينئذٍ البَصرَةَ، وقد قَوِيَت نُفوسُهم، ونَهَبوا ما فيها نَهْبًا شَنيعًا، فكانوا يَنهَبون نَهارًا، وأَصحابُ العَميدِ عصمة يَنهَبون لَيلًا، وأَحرَقوا مَواضِعَ عِدَّةً، وفي جُملَةِ ما أَحرَقوا دارانِ للكُتُبِ إحداهما وُقِفَت قبلَ أيامِ عَضُدِ الدولةِ بن بويه، وهي أَوَّلُ دارٍ وُقِفَت في الإسلامِ. والأُخرى وَقَفَها الوَزيرُ أبو مَنصورِ بن شاه مردان، وكان بها نَفائِسُ الكُتُبِ وأَعيانُها، وأَحرَقوا أيضًا النَّحَّاسِينَ وغَيرَها من الأماكنِ، وخُرِّبَت وُقوفُ البَصرَةِ التي لم يكُن لها نَظيرٌ، وكان فِعْلُ العَربِ بالبَصرَةِ أَوَّلَ خَرْقٍ جَرَى في أيامِ السُّلطانِ ملكشاه. فلمَّا فَعَلوا ذلك، وبَلغَ الخَبرُ إلى بغداد، انحَدرَ سَعدُ الدولةِ كوهرائين، وسَيفُ الدولةِ صَدقةُ بن مزيد إلى البَصرَةِ لإصلاحِ أُمورِها، فوَجَدوا العَربَ قد فارَقوها، ثم إن تليا أُخِذَ بالبَحرَينِ، وأُرسِلَ إلى السُّلطانِ، فشَهَرَهُ ببغداد سَنةَ أربع وثمانين وأربعمائة على جَمَلٍ، وعلى رَأسِه طرطور، وهو يُصفَع بالدِّرَّةِ، والناسُ يَشتُمونَه، ويَسُبُّهم، ثم أُمِرَ به فصُلِبَ."},{"id":1709,"title":"دُخولُ المُرابِطين مَدينةَ غرناطة .","date":["العام الهجري :483","الشهر القمري : رجب","العام الميلادي :1090"],"text":"دَخلَ المُرابِطون بقِيادَةِ القائدِ يوسف بن تاشفين مَدينةَ غرناطة وذلك بعدَ أن عَزَلَ سُلطانَها عبدَالله بن بلقين، وأَصبَحت المَدينةُ تابِعَةً لدَولةِ المُرابِطين التي امتَدَّ نُفوذُها من المَغرِب إلى بلادِ الأندلسِ."},{"id":1710,"title":"ظُهورُ دَولةِ الحَشَّاشِين الإسماعيلية النزارية .","date":["العام الهجري :483","الشهر القمري : شعبان","العام الميلادي :1090"],"text":"قدم الحَسنُ بن الصَّبَّاحِ، رَئيسُ الطائفةِ الباطِنيَّةِ من الإسماعيليةِ، إلى مصر في زِيِّ تاجرٍ، واتَّصلَ بالمُستَنصِر واختَصَّ به، والتَزَمَ أن يُقيمَ له الدَّعوةَ في بلادِ خراسان وغيرِها من بلادِ المَشرِق. وكان الحسنُ هذا كاتِبًا للرَّئيسِ عبدِ الرَّزَّاق بن بهرام بالرَّيِّ، فكاتَبَ المُستَنصِر، ثم قَدِمَ عليه، ثم إن المُستَنصِر بَلغَه عنه كلامٌ، فاعتَقَلَه، ثم أَطلَقَه. وسَألهُ ابنُ الصَّبَّاحِ عن عِدَّةِ مَسائلَ مِن مَسائلِ الإسماعِيليَّة فأَجابَ عنها بِخَطِّهِ. ويُقالُ: إنه قال له: يا أَميرَ المؤمنين، مَن الإمامُ مِن بَعدِك؟ فقال له: وَلَدِي نزار. ثم إنه سار من مصر بعدَ ما أَقامَ عند المُستَنصِر مُدَّةً وأَنعمَ عليه بِنِعَمٍ وافِيَةٍ. فلمَّا وَصلَ إلى بِلادِه نَشَرَ بها دَعوةَ المُستَنصِر وبَثَّهَا في تلك الأَقطارِ، وحَدَثَ منه مِن البَلاءِ بالخَلْقِ ما لا يُوصَف، وأَخذَ ابنُ الصَّبَّاح أَصحابَه بجَمْعِ الأَسلِحَةِ ومُواعَدتِهم، حتى اجتَمَعوا له في شعبان سنة 483هـ، ووَثَبَ بهم فأَخذَ قَلعةَ ألموت، وكانت لِمُلوكِ الديلم قبلَ ظُهورِ الإسلام، وهي مِن الحَصانَةِ في غايةٍ، واجتَمعَ الباطِنيَّةُ بأصبهان مع رَئيسِهم وكَبيرِ دُعاتِهم أحمدَ بن عبدِ المَلِكِ بن عطاش، ومَلَكوا قَلعَتَينِ عَظيمَتينِ؛ إحداهما يُقال لها: قَلعةُ الدر. وكانت لأبي القاسم دلف العجلي، وجَدَّدَها وسَمَّاها ساهور؛ والقَلعةُ الأُخرى تُعرَف بقَلعَةِ جان، وهما على جَبلِ أصبهان. وبَثَّ الحَسنُ بنُ الصَّبَّاح دُعاتَه، وأَلقَى عليهم مَسائلَ الباطِنيَّة، فساروا من قَلعةِ ألموت، وأَكثروا من القَتلِ في الناسِ غَيْلَةً، وكان إذ ذاك مَلِكُ العِراقِيِّين السُّلطانَ ملكشاه المُلَقَّبُ جَلالُ الدِّين بن ألب أرسلان، فاستَدعَى الإمامُ أبا يوسف الخازن لِمُناظَرَةِ أَصحابِ ابنِ الصَّبَّاح؛ فناظَرَهم؛ وأَلَّفَ كِتابَه المُسَمَّى بـ((المستظهري))، وأَجابَ عن مَسائِلِهم. واجتَهَدَ ملكشاه في أَخذِ قَلعَتِهم فأَعياهُ المَرضُ وعَجَزَ عن نَيْلِها."},{"id":1711,"title":"الفَقيهُ الشافعيُّ مَسعودُ الخجنديُّ يقضي على دعاة الباطنية .","date":["العام الهجري :484","العام الميلادي :1091"],"text":"في أيامِ السُّلطانِ ملكشاه، فإنه اجتَمعَ منهم ثمانية عشر رجلًا، فصَلُّوا صلاةَ العِيدِ في ساوة، ففَطَنَ بهم الشِّحْنَةُ –المسؤول عن ضبط أمن ساوة-، فأَخَذَهم وحَبَسَهم، ثم سُئِلَ فيهم فأَطلَقَهم، فهذا أَوَّلُ اجتِماعٍ كان لهم، ثم إنهم دَعوا مُؤذِّنًا من أَهلِ ساوة كان مُقيمًا بأصبهان، فلم يُجِبهُم إلى دَعوَتِهم، فخافوه أن يَنِمَّ عليهم، فقَتَلوه، فهو أَوَّلُ قَتيلٍ لهم، وأَوَّلُ دَمٍ أَراقوهُ، فبَلغَ خَبرُه إلى نِظامِ المُلْكِ، فأَمَرَ بأَخْذِ مَن يُتَّهَم بِقَتلِه، فوَقعَت التُّهمَةُ على نَجَّارٍ اسمُه طاهِر، فقُتِلَ، ومُثِّلَ به، وجَرُّوا بِرِجْلِه في الأَسواقِ، فهو أَوَّلُ قَتيلٍ منهم، وأَوَّلُ مَوضِعٍ غَلَبوا عليه وتَحصَّنوا به بَلدٌ عند قاين، كان مُتَقَدِّمُه على مَذهَبِهم، فاجتَمَعوا عنده، وُقُووا به، فتَجَرَّدَ للانتِقامِ منهم أبو القاسم مَسعودُ بنُ محمدٍ الخجنديُّ، الفَقيهُ الشافعيُّ، وجَمَعَ الجَمَّ الغَفيرَ بالأَسلِحَةِ، وأَمَرَ بحَفْرِ أخاديد، وأَوْقَدَ فيها النِّيرانَ، وجَعلَ العامَّةَ يَأتون بالباطِنيَّة أَفواجًا ومُنفَرِدين، فيُلقَونَ في النارِ، وجَعَلوا إنسانًا على أخاديد النِّيران وسَمَّوهُ مالِكًا، فقَتَلوا منهم خَلْقًا كَثيرًا."},{"id":1712,"title":"حُدوثُ زَلازِل كَثيرةٍ بالشامِ وغَيرِها .","date":["العام الهجري :484","الشهر القمري : شعبان","العام الميلادي :1091"],"text":"وَقعَت بالشامِ وكَثيرٍ من البلادِ زَلازلُ كَثيرةٌ، وكان أَكثرُها بالشامِ، ففارَقَ الناسُ مَساكِنَهم، وانهَدَم بأنطاكية كَثيرٌ من المَساكِن، وهَلَكَ تحتها عالَمٌ كَثيرٌ، وخَرِبَ من سُورِها تسعون بُرْجًا، فأَمَرَ السُّلطانُ ملكشاه بعِمارَتِها."},{"id":1713,"title":"وَقعَةُ جَيَّان بين المُسلِمين والفِرنِج بجَيَّان .","date":["العام الهجري :485","العام الميلادي :1092"],"text":"جَمعَ ألفونسو عَساكِرَه، وجُموعَه، وغَزَا بِلادَ جَيَّان من الأندلسِ، فلَقِيَهُ المُرابِطون وقاتَلوهُ، واشتَدَّت الحَربُ، فكانت الهَزيمةُ أوَّلًا على المسلمين، ثم إن الله تعالى رَدَّ لهم الكَرَّةَ على الفِرنجِ، فهَزَموهم، وأَكثَروا القَتْلَ فيهم، ولم يَنجُ إلا ألفونسو في نَفَرٍ يَسيرٍ، وكانت هذه الوَقعةُ من أَشهُر الوَقائعِ، بعدَ الزَّلَّاقَة، وأَكثرُ الشُّعراءِ ذَكرَها في أَشعارِهم."},{"id":1714,"title":"استِيلاءُ تتش على حِمصَ وغَيرِها مِن ساحِلِ الشَّامِ .","date":["العام الهجري :485","العام الميلادي :1092"],"text":"لمَّا كان السُّلطانُ ببغداد قَدِمَ إليه أَخوهُ تاجُ الدولةِ تتش من دِمشقَ، وقَسِيمُ الدولةِ أتسز من حَلَب، وبوزان من الرها، فلمَّا أَذِنَ لهم السُّلطانُ في العَوْدِ إلى بِلادِهم أَمَرَ قَسِيمُ الدولةِ وبوزان أن يَسِيرا مع عَساكِرهِما في خِدمَةِ أَخيهِ تاجِ الدولةِ، حتى يَستولِيَ على ما للمُستَنصِر الفاطميِّ حاكمِ مصر بساحِلِ الشامِ، من البلادِ، ويَسيرُ، وهُم معه، إلى مصر لِيَملِكَها، فساروا أجمعون إلى الشامِ، ونَزلَ على حِمصَ، وبها ابنُ ملاعب صاحبُها، وكان الضَّرَرُ به وبأَولادِه عَظيمًا على المسلمين، فحَصَروا البلدَ، وضَيَّقوا على مَن بِه، فمَلَكَهُ تاجُ الدولةِ، وأَخَذَ ابنَ ملاعب ووَلدَيهِ، وسار إلى قَلعةِ عرقة فمَلَكَها عُنوةً، وسار إلى قَلعةِ أفامية فمَلَكَها أيضًا، وكان بها خادِمٌ للمُستَنصِر، فنَزلَ بالأمانِ فأَمَّنَهُ، ثم سار إلى طرابلس فنازَلَها، فرأى صاحبُها جلالُ المُلْكِ ابنُ عمَّارٍ جَيشًا لا يُدفَعُ إلا بِحِيلَةٍ، فأَرسلَ إلى الأُمراءِ الذين مع تاجِ الدَّولةِ، وأَطمَعَهم لِيُصلِحوا حالَه، فلم يَرَ فيهم مَطمَعًا، وكان مع قَسيمِ الدولةِ أتسز وَزيرٌ له اسمُه زرين كمر، فراسَلَهُ ابنُ عمَّارٍ فرأى عنده لِينًا، فأَتحَفَهُ وأَعطاهُ، فسَعَى مع صاحبِه قَسيمِ الدولةِ في إصلاحِ حالِه لِيَدفَعَ عنه، وحَمَلَ له ثلاثين ألف دينارٍ، وتُحَفًا بمِثلِها، وعَرَضَ عليه المَناشِيرَ التي بِيَدِه من السُّلطانِ بالبلدِ، والتَّقَدُّم إلى النُّوَّابِ بتلك البلادِ بمُساعَدتِه، والشَّدَّ بيَدِه، والتَّحذيرَ من مُحارَبَتِه، فقال أتسز لتاجِ الدولةِ تتش: لا أُقاتِلُ مَن هذه المَناشيرُ بِيَدِه. فأَغلَظَ له تاجُ الدولةِ، وقال: هل أنت تابِعٌ لي؟ فقال أتسز أنا أُتابِعُك إلَّا في مَعصِيَةِ السُّلطانِ، ورَحَلَ من الغَدِ عن مَوضِعِه، فاضطرَّ تاجُ الدولةِ إلى الرَّحيلِ، فرَحَلَ غَضبانًا، وعاد بوزان أيضًا إلى بلاده، فانتُقِضَ هذا الأَمرُ."},{"id":1715,"title":"قتال الأَعرابُ لحُجَّاجِ أهل بغداد ونهبهم بالكُوفَةِ .","date":["العام الهجري :485","العام الميلادي :1092"],"text":"سار الحُجَّاجُ من بغداد، فقَدِموا الكُوفةَ، ورَحَلوا منها، فخَرَجت عليهم خَفاجَةٌ، وقد طَمِعوا بمَوتِ السُّلطانِ وبُعْدِ العَسكرِ، فأَوقَعوا بهم، وقَتَلوا أَكثرَ الجُندِ الذين معهم، وانهَزمَ باقيهم، ونَهَبوا الحُجَّاجَ، وقَصَدوا الكوفةَ فدَخَلوها، وأغاروا عليها، وقَتَلوا في أَهلِها، فرَماهُم الناسُ بالنُّشَّابِ، فخَرَجوا بعدَ أن نَهَبوا، وأَخَذوا ثِيابَ مَن لَقوهُ من الرِّجالِ والنِّساءِ، وَصَلَ الخَبرُ إلى بغداد، فسُيِّرَت العَساكرُ منها، فلمَّا سَمِعَ بَنُو خَفاجَةَ انهَزَموا، فأَدرَكَهم العَسكرُ، فقُتِلَ منهم خَلْقٌ كَثيرٌ، ونُهِبَت أَموالُهم، وضَعُفَت خَفاجَةُ بعدَ هذه الوَقعَةِ."},{"id":1716,"title":"اغتِيالُ الوَزيرِ السَّلجوقيِّ نِظامِ المُلْكِ على يد الباطنية .","date":["العام الهجري :485","الشهر القمري : رمضان","العام الميلادي :1092"],"text":"هو الوَزيرُ الكَبيرُ، نِظامُ المُلْكِ، قِوامُ الدِّينِ، أبو عليٍّ الحَسنُ بن عليِّ بن إسحاقَ الطُّوسيُّ، وَزيرُ السُّلطانِ ملكشاه السلجوقي، عاقِلٌ، سائِسٌ، خَبيرٌ، سَعيدٌ، مُتَدَيِّنٌ، مُحتَشِمٌ، عامِرُ المَجلِس بالقُرَّاءِ والفُقَهاءِ. أَنشأَ المَدرسةَ النِّظامِيَّة الكُبرى ببغداد، ثم أَنشأَ مَدارسَ أُخرى في عَددٍ من البُلدانِ, ورَغَّبَ في العِلمِ، وأَدَرَّ على الطَّلَبَةِ الصِّلاتِ، وأَملَى الحَديثَ، وبَعُدَ صِيتُه. وُلِدَ سَنةَ 408هـ بنوقان، إحدى مَدينَتي طُوس، وكان من أَولادِ الدَّهَّاقِين بناحِيَةِ بيهق، وكان فَقيرًا مَشغولًا بسَماعِ الحَديثِ والفِقْهِ، وقَرأَ النَّحْوَ، خَتَمَ القُرآنَ وله إحدى عشرة سَنَةً، وعَمِلَ بالكِتابَةِ والدِّيوانِ، وخَدَمَ بغزنةَ، ثم بعدَ حينٍ اتَّصَلَ بداود بن ميكائيل السلجوقيِّ فظَهَرَ له منه النُّصْحُ والمَحَبَّةُ،، فأَخذَهُ بِيَدِهِ وسَلَّمَهُ إلى وَلَدِه ألب أرسلان، وقال له: يا محمد، هذا حَسَنٌ الطُّوسيُّ اتَّخِذهُ والِدًا ولا تُخالِفهُ. فلمَّا وَصَلَ المُلْكُ إلى ألب أرسلان استَوزَرَهُ، فدَبَّرَ مُلكَه عشر سنين. ولمَّا ماتَ ألب أرسلان، ازدَحَم أَولادُه على المُلْكِ، فقام بأَمْرِ ملكشاه حتّى تَمَّ أَمرُه ومَلَكَ السَّلطَنَةَ. كان نِظامُ المُلْكِ عاليَ الهِمَّةِ، وافِرَ العَقلِ، عارِفًا بتَدبيرِ الأُمورِ، وخَفَّفَ المَظالِمَ، ورَفَقَ بالرَّعايا، وبَنَى الوُقوفَ، وهاجَرَت الكِبارُ إلى جَنابِه، وازدادَت رِفعَتُه. قال الذهبيُّ: \"كان شافِعيًّا أَشعَريًّا. سار إلى غزنة، فصار كاتِبًا نَجيبًا، إليه المُنتَهى في الحِسابِ، وبَرَعَ في الإنشاءِ، وكان ذَكِيًّا، لَبيبًا، يَقِظًا، كامِلَ السُّؤدَدِ. قيل: إنه ما جَلَسَ إلا على وُضوءٍ، وما تَوضَّأ إلا تَنَفَّلَ، ويَصومُ الاثنين والخميس، جَدَّدَ عِمارةَ خوارزم، ومَشهدَ طوس، وعَمِلَ بيمارستانا، وبَنَى مَدارِسَ بمَرو، وهراة، وبلخ، والبَصرَة، وأصبهان، وكان حَلِيمًا رَزينًا جَوادًا، صاحِبَ فُتُوَّةٍ واحتِمالٍ ومَعروفٍ كَثيرٍ إلى الغايَةِ، ويُبالِغ في الخُضوعِ للصَّالِحين\". قال ابنُ عَقيلٍ: \"بَهَرَ العُقولَ سِيرَةُ النِّظامِ جُودًا وكَرمًا وعَدلًا، وإحياءً لِمَعالِمِ الدِّين، كانت أيامُه دَولةَ أَهلِ العِلمِ، ثم خُتِمَ له بالقَتلِ وهو مارٌّ إلى الحَجِّ، في رمضان، فماتَ مَلِكًا في الدنيا، مَلِكًا في الآخرة\" في عاشر رمضان قُتِلَ نِظامُ المُلْكِ أبو عليٍّ الحَسنُ بن عليِّ بن إسحاقَ الوَزيرُ بالقُرْبِ من نهاوند، وكان هو والسُّلطانُ في أصبهان، وقد عاد إلى بغداد، فلمَّا كان بهذا المكان، بعد أن فَرَغَ من إفطارِه، وخَرجَ في مَحِفَّتِه إلى خَيمةِ حَرَمِه، أَتاهُ صَبِيٌّ دَيلميٌّ من الباطِنيَّةِ، في صورة مُستَميحٍ، أو مُستَغيثٍ، فضَرَبَهُ بِسِكِّينٍ كانت معه، فقَضَى عليه وهَرَبَ، فعَثَرَ بطُنُبِ خَيمَةٍ، فأَدرَكوهُ فقَتَلوهُ، فسَكَنَ عَسكرُه وأَصحابُه، وقيل: إن قَتْلَهُ كان بتَدبيرِ السُّلطانِ، فلم يُمهَل بعدَه إلا نحوَ شَهرٍ، وبقي كانت وِزارتُه لبَنِي سلجوق أربعًا وثلاثين سَنةً- وقيل: أربعين سَنةً- تُوفِّي عن سِتٍّ وسبعين سَنةً."},{"id":1717,"title":"وَفاةُ السُّلطانِ السلجوقي ملكشاه وتَفَكُّكُ الدَّولةِ السلجوقية .","date":["العام الهجري :485","الشهر القمري : شوال","العام الميلادي :1092"],"text":"هو أبو الفَتحِ ملكشاه بن ألب أرسلان محمد بن داود بن ميكائيل بن سلجوق بن دقاق، المُلَقَّب بجَلالِ الدولة. لمَّا تُوفِّي أَبوهُ كان ملكشاه وَلِيَّ الأَمرِ مِن بَعدِه بِوَصِيَّةِ والِدِه وتَحليفِ الأُمراءِ والأَجنادِ على طاعَتِه، ووَصَّى وَزيرَه نِظامَ المُلْكِ أبا عليٍّ الحَسنَ على تَفرِقَةِ البِلادِ بين أَولادِه، ويكون مَرجِعُهم إلى ملكشاه، ففَعَلَ ذلك، وعَبَرَ بهم نَهرَ جيحون راجِعًا إلى البلادِ, فلمَّا وَصَلَ وَجَدَ عَمَّهُ قاروتبك صاحِبَ كرمان قد خَرَجَ عليه، فعاجَلَهُ وتَصافَّا بالقُرْبِ من همذان، فهَزَمهُ، فتَبِعَه بَعضُ جُنْدِ ملكشاه فأَسَروهُ وحَمَلوهُ إلى ملكشاه، فبَذَلَ التَّوبَةَ ورَضِيَ بالاعتِقالِ وأن لا يُقتَل، فلم يُجِبهُ ملكشاه إلى ذلك، فأَمَرَ بقَتلِه فخُنِقَ بوَتَرِ قَوسِه، واستَقرَّت القَواعدُ للسُّلطانِ وفَتَحَ البِلادَ واتَّسعَت عليه المَملكَةُ، ومَلَكَ ما لم يَملِكهُ أَحدٌ من مُلوكِ الإسلامِ بعدَ الخُلفاءِ المُتقدِّمين، فكان في مَملَكتِه جَميعُ بلادِ ما وراءَ النهرِ وبلادُ الهياطلة وبابُ الأبوابِ والرُّومُ ودِيارُ بَكرٍ والجَزيرةُ والشامُ، وخُطِبَ له على جَميعِ مَنابرِ الإسلامِ سِوى بلادِ المَغرِب، فإنه مَلَكَ مِن كاشغر وهي مَدينةٌ في أَقصَى بلادِ التُّركِ إلى بَيتِ المَقدِس طُولًا، ومِن القُسطنطينيَّة إلى بلادِ الخزر وبَحرِ الهِندِ عَرضًا، وكأن قد قُدِّرَ لِمالِكِه مُلْكُ الدنيا. وكان من أَحسنِ المُلوكِ سِيرَةً حتى كان يُلَقَّب بالسُّلطانِ العادِل، وكان مَنصورًا في الحُروبِ، ومُغرَمًا بالعَمائِرِ، حَفَرَ كَثيرًا من الأَنهارِ، وعَمَّرَ على كَثيرٍ من البُلدانِ الأَسوارَ، وأَنشأَ في المَفاوِزِ رِباطاتٍ وقَناطِرَ، وهو الذي عَمَّرَ جامِعَ السُّلطانِ ببغداد ابتَدأَ بعِمارَتِه في المُحرَّم من سَنَةِ خمسٍ وثمانين وأربعمائة، وزادَ في دارِ السَّلطَنَةِ بها، وصَنَعَ بطَريقِ مكَّةَ مَصانِعَ، وغَرِمَ عليها أَموالًا كَثيرةً خارِجةً عن الحَصرِ، وأَبطلَ المُكوسَ والخَفاراتِ في جَميعِ البلادِ. وكان لَهِجًا بالصَّيْدِ، حتى قيل: إنه ضُبِطَ ما اصطادَهُ بِيَدِه فكان عشرة آلاف، وكانت السبيلُ في أيامِه ساكِنةً والمَخاوِفُ آمِنةً، تَسيرُ القَوافلُ مِن ما وَراءَ النهرِ إلى أَقصَى الشامِ وليس معها خَفيرٌ، ويُسافِر الواحِدُ والاثنانِ من غَيرِ خَوفٍ ولا رَهَبٍ. سارَ السُّلطانُ ملكشاه، بعدَ قَتلِ نِظامِ المُلْكِ، إلى بغداد، ودَخَلَها في الرابع والعشرين من شَهرِ رمضان، ولَقِيَهُ وَزيرُ الخَليفةِ عَميدُ الدولةِ ابنُ جَهيرٍ، وكان السُّلطانُ قد أَمَرَ أن تُفصَّل خِلَعُ الوِزارَةِ لتاجِ المُلْكِ، وكان هو الذي سَعَى بنِظامِ المُلْكِ، فلمَّا فَرَغَ من الخِلَعِ، ولم يَبقَ غيرُ لُبْسِها والجُلوسُ في الدستِ، اتَّفَقَ أن السُّلطانَ خَرجَ إلى الصَّيدِ، وعادَ ثالثَ شَوَّال مَريضًا، وكان سَبَبُ مَرَضِه أنه أَكَلَ لَحمَ صَيْدٍ فَحُمَّ وافتُصِدَ، ولم يَستَوفِ إخراجَ الدَّمِ، فثَقُلَ مَرضُه، وكانت حُمَّى مُحرِقَةً، فتُوفِّي ليلةَ الجُمعةِ، النصفَ من شَوَّال، ولمَّا ثَقُلَ نَقَلَ أَربابُ دَولتِه أَموالَهم إلى حَريمِ دارِ الخِلافَةِ، ولمَّا تُوفِّي سَتَرَت زَوجتُه تركان خاتون المعروفة بخاتون الجلالية مَوْتَه وكَتَمَتهُ، وأَرسَلَت إلى الأُمراءِ سِرًّا فأَرضَتهُم، واستَحلَفَتهُم لِوَلَدِها محمود، وعُمرُه أربع سنين وشهور، وبِمَوتِ السُّلطان ملكشاه انقَضَى العصر عَصرُ القُوَّةِ للسُّلطَةِ السلجوقية وبَدأَ عَهدُ الانقِساماتِ السياسيَّة والحُروبِ بين وَرَثَةِ العَرشِ السلجوقي ممَّا أَدَّى إلى تَشتيتِ صُفوفِهم وإضعافِ سُلطَتِهم."},{"id":1718,"title":"القِتالُ على السُّلطَةِ بعدَ ملكشاه  .","date":["العام الهجري :485","الشهر القمري : شوال","العام الميلادي :1092"],"text":"بعدَ وَفاةِ ملكشاه أَخذَت زَوجتُه تركان خاتون الجلالية البَيْعَةَ لِوَلَدِها محمود وله أربع سنوات وعِدَّةُ أَشهُر, ثم  أَرسلَت إلى أصبهان في القَبضِ على بركيارق ابنِ السُّلطانِ، وهو أَكبرُ أَولادِه، خافَتْهُ أن يُنازِعَ وَلدَها في السَّلطَنَةِ، فقُبِضَ عليه، فلمَّا ظَهرَ مَوتُ ملكشاه وَثَبَ المَماليكُ النِّظامِيَّةُ على سِلاحٍ كان لنِظامِ المُلْكِ بأصبهان، فأَخَذوهُ وثاروا في البلدِ، وأَخرَجوا بركيارق من الحَبسِ، وخَطَبوا له بأصبهان ومَلَّكوهُ، وسارت تركان خاتون من بغداد إلى أصبهان، فسَيَّرَت خاتون العِساكِرَ إلى قِتالِ بركيارق، فالتَقَى العَسكرانِ بالقُربِ من بروجرد، فانحازَ جَماعةٌ من الأُمراءِ الذين في عَسكرِ خاتون إلى بركيارق، فقَوِيَ بهم، وجَرَت الحَربُ بينهم أواخِرَ ذي الحجَّةِ، واشتَدَّ القِتالُ، فانهَزَم عَسكرُ خاتون وعادوا إلى أصبهان، وسار بركيارق في إثْرِهِم فحَصَرهُم بأصبهان. ثم استَقرَّ الأَمرُ له بعدَ أن فَشَلَ عَمُّهُ تتش في أَخْذِ بغداد وعاد إلى الشامِ."},{"id":1719,"title":"قِتالُ تتش بن ألب أرسلان مِن أَجلِ السَّلطَنَةِ .","date":["العام الهجري :486","العام الميلادي :1093"],"text":"كان تتش بن ألب أرسلان صاحِبُ دِمشقَ وما جاوَرَها من بلادِ الشامِ، سار من دِمشقَ إلى أَخيهِ السُّلطانِ ملكشاه ببغداد، فلمَّا كان بهيت بَلَغَهُ مَوتُه، فأَخَذَ هيت، واستَولَى عليها، وعاد إلى دِمشقَ يَتجهَّزَ لِطَلَبِ السَّلطَنَة، فجَمعَ العَساكِرَ، وأَخرجَ الأَموالَ وسار نحوَ حَلَب، وبها قَسيمُ الدولةِ أتسز فرأى قَسيمُ الدولةِ اختِلافَ أَولادِ صاحِبِه ملكشاه، وصِغَرَهُم، فعَلِمَ أنه لا يَطيقُ دَفْعَ تتش، فصالَحَهُ، وصار معه، وأَرسلَ إلى باغي سيان، صاحِبِ أنطاكية، وإلى بوزان، صاحِبِ الرها وحران، يُشيرُ عليهما بطَاعةِ تاجِ الدولةِ تتش حتى يَروا ما يكون مِن أَولادِ ملكشاه، ففَعَلوا، وصاروا معه، وخَطَبوا له في بِلادِهم، وقَصَدوا الرحبةَ، فحَصَروها، ومَلَكوها في المُحرَّم من هذه السَّنَةِ، وخَطَبَ تتش لِنَفسِه بالسَّلطَنَةِ، ثم ساروا إلى نصيبين، فحَصَروها، ففَتَحَها عُنوةً وقَهرًا، ثم سَلَّمَها إلى الأَميرِ محمدِ بن شرفِ الدولةِ العقيلي، وسار يُريد المَوصِلَ، وأَتاهُ الكافي بن فَخرِ الدولةِ بن جَهيرٍ، وكان في جَزيرةِ ابن عُمرَ، فأَكرَمهُ، واسْتَوْزَرَهُ، فلمَّا مَلَكَ تتش نصيبين أَرسلَ إليه يَأمرُه أن يَخطُبَ له بالسَّلطَنَةِ، ويُعطِيهُ طَريقًا إلى بغداد لِيَنحَدِرَ، ويَطلُب الخُطبةَ بالسَّلطنَةِ، فامتَنعَ إبراهيمُ من ذلك، فسار تتش إليه، وتَقدَّم إبراهيمُ أيضًا نَحوَهُ، فالتَقوا بالمُضَيَّعِ، من أَعمالِ المَوصِل، في رَبيعٍ الأَوَّل، فحَمَلَ العَربُ على بوزان، فانهَزمَ، وحَمَلَ أتسز على العَربِ فهَزَمَهم، وتَمَّت الهَزيمةُ على إبراهيمَ والعَربِ، وأُخِذَ إبراهيمُ أَسيرًا وجَماعةٌ مِن أُمراءِ العَربِ، فقُتِلوا صَبرًا، ومَلَكَ تتش بِلادَهم المَوصِلَ وغَيرَها، واستَنابَ بها عليَّ بنَ شَرفِ الدولةِ مُسلمٍ، وأَرسلَ إلى بغداد يَطلُب الخُطبةَ، وساعَدَهُ كوهرائين على ذلك، فقِيلَ لِرَسولِه: إنَّا نَنتظِر وُصولَ الرُّسُلِ من العَسكرِ، فعاد إلى تتش بالجوابِ، فانتَهَى خَبَرُه إلى ابنِ أَخيهِ رُكنِ الدِّين بركيارق، وكان قد استَولَى على كَثيرٍ من البِلادِ، منها: الرَّيُّ، وهمذان، وما بينهما، فلمَّا تَحقَّقَ الحال سارَ في عَساكرِه لِيَمنعَ عَمَّهُ عن البِلادِ، فلمَّا تَقارَب العَسكرانِ قال قَسيمُ الدولةِ أتسز لبوزان: إنَّما أَطَعنا هذا الرَّجُلَ لنَنظُرَ ما يكون مِن أَولادِ صاحبِنا، والآن فقد ظَهرَ ابنُه، ونُريدُ أن نكون معه. فاتَّفَقا على ذلك وفارَقَا تتش، وصارا مع بركيارق، فلمَّا رأى تاجُ الدولةِ تتش ذلك عَلِمَ أنه لا قُوَّةَ له بهم، فعادَ إلى الشامِ، واستَقامَت البِلادُ لبركيارق."},{"id":1720,"title":"نِهايَةُ مُلوكِ الطَّوائفِ وقِيامُ دَولةِ المُرابِطين  بالأندَلُسِ .","date":["العام الهجري :486","العام الميلادي :1093"],"text":"انتَظَمَت جَميعُ بلادِ المُسلِمين في الأندلسِ تحت مُلْكِ يوسفَ بنِ تاشفين، وانقَرضَ عَهدُ مُلوكِ الطَّوائفِ منها أَجمَع كأنْ لم يكُن، واستَولَى على العَدوَتَينِ، وتَسَمَّى بأَميرِ المسلمين، وخاطَبَ المُستَنصِر العبَّاسيَّ الخَليفةَ لِعَهْدِه ببغداد، وبَعثَ إليه عبدَ الله بنَ محمدِ بنِ العَربِ على يَدِ المعافري الإشبيلي ووَلَدَه القاضي أبا بكرٍ، فتَلَطَّفا في القَولِ وأَحسَنا في الإبلاغِ، وطَلَبا من الخَليفةِ أن يَعقِدَ له على المَغربِ والأندَلسِ، فعَقَدَ له وتَضَمَّن ذلك مَكتوبُ الخَليفةِ بذلك مَنقولًا في أَيدِي الناس، وانقَلَبا إليه بتَقليدِ الخَليفةِ وعَهْدِه على ما إلى نَظَرِه مِن الأَقطارِ والأَقاليم."},{"id":1721,"title":"وَقعَةُ المُضَيَّعِ بين إبراهيمُ بن بدران وتتش بن ألب أرسلان .","date":["العام الهجري :486","الشهر القمري : ربيع الأول","العام الميلادي :1093"],"text":"كان إبراهيمُ بن قُريشِ بن بدران، أَميرُ بني عُقيلٍ، قد استَدعاهُ السُّلطانُ ملكشاه سَنةَ اثنتين وثمانين وأربعمائة لِيُحاسِبَه، فلمَّا حَضَرَ عنده اعتَقَلهُ، وأَنفَذَ فَخرَ الدولةِ بنَ جَهيرٍ إلى البِلادِ، فمَلَكَ المَوصِلَ وغَيرَها، وبَقِيَ إبراهيمُ مع ملكشاه، وسارَ معه إلى سمرقند، وعاد إلى بغداد، فلمَّا ماتَ ملكشاه أَطلقَتهُ تركان خاتون من الاعتِقالِ، فسارَ إلى المَوصِل, وكان ملكشاه قد أَقطعَ عَمَّتَهُ صَفِيَّة مَدينةَ بلد، وكانت زَوجةَ شَرفِ الدَّولةِ، ولها منه ابنُها عليٌّ، وكانت قد تَزوَّجَت بعد شَرفِ الدولةِ بأَخيهِ إبراهيمَ، فلمَّا مات ملكشاه قَصدَت المَوصِلَ، ومعها ابنُها عليٌّ، فقَصَدَها محمدُ بن شَرفِ الدولةِ، وأَرادَ أَخْذَ المَوصِل، فافتَرَق الناسُ فِرقَتينِ: فِرقَةٌ معه، وأُخرى مع صَفِيَّة وابنِها عليٍّ، واقتَتَلوا بالمَوصِل عند الكُنَّاسَةِ، فظَفَرَ عَلِيٌّ، وانهَزمَ مُحمدٌ، ومَلَكَ عليٌّ المَوصِلَ, فلمَّا وَصلَ إبراهيمُ إلى جهينة، وبينه وبين المَوصِل أربعةُ فَراسِخ، سَمِعَ أن الأَميرَ عَلِيًّا ابنَ أَخيهِ شَرفِ الدولةِ قد مَلَكَها، ومعه أُمُّهُ صَفِيَّة، عَمَّةُ ملكشاه، فأَقامَ مكانه، وراسلَ صَفِيَّة خاتون، وتَردَّدَت الرُّسُلُ، فسَلَّمَت البلدَ إليهِ، فأَقامَ به. فلما ملك تتش نصيبين أرسل إليه يأمره أن يخطب له بالسلطنة، ويعطيه طريقا إلى بغداد لينحدر، ويطلب الخطبة بالسلطنة، فامتنع إبراهيم من ذلك، فسار تتش إليه، وتقدم إبراهيم أيضًا نحوه، فالتقوا بالمضيع، من أعمال الموصل، في ربيع الأول، وكان إبراهيم في ثلاثين ألفًا، وكان تتش في عشرة آلاف، وكان اتسز على ميمنته، وبوزان على ميسرته، فحمل العرب على بوزان، فانهزم، وحمل اتسز عليهم فهزمهم، وتمت الهزيمة على إبراهيم والعرب، وأخذ إبراهيم أسيرًا وجماعة من أمراء العرب، فقتلوا صبرًا، ونهبت أموال العرب وما معهم من الإبل والغنم والخيل وغير ذلك، وقتل كثير من نساء العرب أنفسهن خوفًا من السبي والفضيحة, وملك تتش بلادهم الموصل وغيرها، واستناب بها علي بن شرف الدولة، وأمه صفية عمة تتش، وأرسل إلى بغداد يطلب الخطبة، وساعده كوهرائين على ذلك، فقيل لرسوله: إنا ننتظر وصول الرسل من العسكر، فعاد إلى تتش بالجواب."},{"id":1722,"title":"الجَيشِ العُبيديِّ الفاطِميِّ يحاصر مدينة صور .","date":["العام الهجري :486","الشهر القمري : جمادى الآخرة","العام الميلادي :1093"],"text":"مَلَكَ عَسكرُ المُستَنصِر بالله العُبيديِّ، صاحِبِ مصر، مَدينةَ صور، وسَببُ ذلك ما كان سَنةَ 482هـ أن أَميرَ الجُيوشِ بَدرًا، وَزيرَ المُستَنصِر، سَيَّرَ العَساكِرَ إلى مَدينةِ صور، وغَيرِها، من ساحِلِ الشامِ، وكان مَن بها قد امتَنعَ مِن طاعَتِهم، فمَلَكَها، وقَرَّرَ أُمورَها، وجَعَلَ فيها الأُمراءَ، وكان قد وَلَّى مَدينةَ صور الأَميرَ الذي يُعرَف بمُنيرِ الدولةِ الجُيوشيِّ، فعَصَى على المُستَنصِر وأَميرِ الجُيوشِ، وامتَنعَ بصور، فسُيِّرَت العِساكرُ من مصر إليه، وكان أَهلُ صور قد أَنكَروا على مُنيرِ الدولةِ عِصيانَه على سُلطانِه، فلمَّا وَصلَ العَسكرُ المصريُّ إلى صور وحَصَروها وقاتَلوها ثارَ أَهلُها، ونادوا بشِعارِ المُستَنصِر وأَميرِ الجُيوشِ، وسَلَّموا البلدَ، وهَجمَ العَسكرُ المصريُّ بغَيرِ مانعٍ ولا مُدافِعٍ، ونَهَبَ من البلدِ شَيئًا كَثيرًا، وأُسِرَ مُنيرُ الدولةِ ومَن معه مِن أَصحابِه، وحُمِلُوا إلى مصر، وقُطِعَ على أَهلِ البلدِ سِتُّون ألف دِينارٍ، فأَجحَفَت بهم، ولمَّا وَصلَ مُنيرُ الدولةِ إلى مصر ومعه الأَسرَى قُتِلُوا جَميعُهم ولم يَعفُ عن واحدٍ منهم."},{"id":1723,"title":"الخَليفَةُ العبَّاسيُّ يُقَلِّد يوسفَ بن تاشفين البِلادَ التي فَتَحَها .","date":["العام الهجري :487","العام الميلادي :1094"],"text":"طَلَبَ يوسفُ بن تاشفين من الخَليفَةِ العبَّاسيِّ المُستَظهِر بالله أن يُقَلِّدَهُ البِلادَ التي فَتحَها وبَعثَ إليه بهذا الطَّلَبَ مع عبدِالله بن العربي الإشبيلي ووَلَدِه القاضي أبي بكرِ بن العربي الإمامِ المَشهورِ، فعَهِدَ الخَليفةُ لابنِ تاشفين بما طَلَبَ."},{"id":1724,"title":"بركيارق يَتوَّلى حُكمَ الدَّولةِ السَّلجوقِيَّة بفارس .","date":["العام الهجري :487","الشهر القمري : محرم","العام الميلادي :1094"],"text":"يومَ الجُمعةِ رابع عشر المُحرَّم، خُطِبَ ببغداد للسُّلطانِ بركيارق بن ملكشاه، وكان قَدِمَها أَواخِرَ سَنَةِ سِتٍّ وثَمانين وأربعمائة، وأَرسلَ إلى الخَليفةِ المُقتدِي بأَمرِ الله يَطلُب الخُطبةَ، فأُجِيبَ إلى ذلك، وخَطَبَ له، ولُقِّبَ رُكنَ الدِّين، وحَملَ الوَزيرُ عَميدُ الدَّولةِ بن جَهيرٍ الخِلَعَ إلى بركيارق، فلَبِسَها، وعُرِضَ التَّقليدُ على الخَليفةِ لِيُعَلِّمَ عليه، فعَلَّمَ فيه، وتُوفِّي فَجأَةً، ووُلِّيَ ابنُه الإمامُ المُستَظهِر بالله الخِلافةَ، فأَرسلَ الخِلَعَ والتَّقليدَ إلى السُّلطانِ بركيارق، فأَقامَ ببغداد إلى رَبيعٍ الأَوَّل مِن السَّنَةِ، وسار عنها إلى المَوصِل."},{"id":1725,"title":"وَفاةُ الخَليفَةِ العبَّاسيِّ المُقتَدِي بالله وحُكْمُ ابنِه المُستَظهِر بالله .","date":["العام الهجري :487","الشهر القمري : محرم","العام الميلادي :1094"],"text":"هو أَميرُ المؤمنين المُقتَدِي بالله أبو القاسمِ عبدُ الله بنُ الأَميرِ ذَخيرةِ الدِّين أبي العبَّاس محمدِ بن القائمِ بأمرِ الله عبدِ الله بنِ القادرِ بالله أحمدَ بن إسحاقَ بن جَعفرٍ المُقتَدِر بن المُعتَضِد الهاشميُّ العبَّاسيُّ، تُوفِّي أَبوهُ الذَّخيرَةُ والمُقتدِي حَمْلٌ وأُمُّهُ أُمُّ وَلَدٍ اسمُها: أرجوان، أرمنية عاشَت إلى خِلافَةِ ابنِ ابنِها المُستَرشِد بالله. بُويِعَ المُقتدِي بالخِلافة في ثالث عشر شعبان سَنةَ 467هـ، وهو ابنُ تسع عشرة سَنةً وثلاثة أَشهُر. كان المُقتدِي أَبيضَ حُلْوَ الشَّمائلِ، عُمِّرَت في أَيامِه مَحالٌّ كَثيرةٌ من بغداد، ظَهرَت في أَيامِه خَيراتٌ كَثيرةٌ، وآثارٌ حَسَنةٌ في البُلدان. قال عنه الذهبيُّ: \"كانت قَواعِدُ الخِلافَةِ في أَيامِه باهِرَةً، وافِرَةَ الحُرمَةِ. بخِلافِ مَن تَقدَّمَه, ومِن مَحاسِنِه أنه أَمَرَ بنَفيِ المُغَنِّيات والخواطي من بغداد، وأن لا يَدخُل أَحدٌ الحَمَّامَ إلا بمِئزَرٍ. وضرب أَبراجَ الحَمامِ صِيانَةً لِحُرُمِ الناسِ. وكان دَيِّنًا خَيِّرًا، قَوِيَّ النَّفسِ، عاليَ الهِمَّةِ، مِن نُجَباءَ بَنِي العبَّاسِ\". وفي يوم الجُمعةِ الرابع عشر المُحرَّم تُوفِّي الخَليفةُ المُقتدِي بأَمرِ الله فَجأَةً، فلمَّا عَلِمَ الوُزراءُ بذلك شَرَعوا في البَيْعَةِ لِوَلِيِّ العَهدِ ووَلَدِه أبي العبَّاسِ أَحمدَ المُستَظهِر بالله، وأُحضِرَ المُستَظهِر بالله لبغداد، وأُعلِمَ بمَوتِ أَبيهِ، وحَضَرَ الوَزيرُ فبايَعَهُ، ورَكِبَ إلى السُّلطانِ بركيارق، فأَعلَمَهُ الحالَ، وأَخَذَ بَيْعَتَه للمُستَظهِر بالله، فلمَّا كان اليومُ الثالث مِن مَوتِ المُقتدِي أُظهِرَ خَبرُ وَفاةِ الخَليفةِ وجُهِّزَ، ثم صَلَّى عليه ابنُه المُستَظهِر، ودُفِنَ، وكانت خِلافَةُ المُقتدِي تِسعَ عشرة سَنةً وثمانية أَشهُر غير يومين."},{"id":1726,"title":"مَقتَلُ قَسيمِ الدَّولةِ أتسز السَّلجوقيِّ .","date":["العام الهجري :487","الشهر القمري : جمادى الأولى","العام الميلادي :1094"],"text":"قُتِلَ قَسيمُ الدَّولةِ أتسز، وسَببُ قَتلِه أن تاجَ الدَّولةِ تتش لمَّا عاد من أذربيجان مُنهزِمًا لم يَزل يَجمَع العَساكرَ، فكَثُرت جُموعُه، وعَظُمَ حَشدُه، فسار في هذا التاريخِ عن دِمشقَ نحوَ حَلَب لِيَطلُب السَّلطنةَ، فاجتَمعَ قَسيمُ الدولةِ أتسز وبوزان، وأَمَدَّهُما رُكنُ الدِّينِ بركيارق بالأَميرِ كربوقا الذي صار بعدَ صاحِبِ المَوصِل، فلمَّا اجتَمَعوا ساروا إلى طَريقِه، فلَقوهُ عند نَهرِ سبعين قَريبًا من تَلِّ السُّلطانِ، بينه وبين حَلَب سِتَّةُ فَراسِخ، واقتَتَلوا، واشتَدَّ القِتالُ، فخامَرَ بَعضُ العَسكرِ الذين مع أتسز، فانهَزَموا، وتَبِعَهم الباقون، فتَمَّت الهَزيمةُ، وثَبَتَ أتسز، فأُخِذَ أَسيرًا، فقَتَلَهُ صَبْرًا، وسار نحوَ حَلَب، وكان قد دَخلَ إليها كربوقا، وبوزان، فحَفِظاها منه، وحَصَرَها تتش وأَلَحَّ في قِتالِها حتى مَلَكَها، وسَلَّمَها إليه المُقيمُ بقَلعةِ الشَّريفِ، ومنها دَخلَ البلدَ، وأَخذَهُما أَسِيرَيْنِ، وأَرسلَ إلى حران والرها لِيُسلِّموهُ مَن بهما وكانتا لبوزان، فامتَنَعوا من التَّسليمِ عليه، فقَتَلَ بوزان، وأَرسلَ رَأسَهُ إليهم وتَسَلَّم البَلدَينِ، وأمَّا كربوقا فإنه أَرسلَه إلى حِمصَ، فسَجَنهُ بها إلى أن أَخرَجهُ المَلِكُ رضوان بعدَ قَتْلِ أَبيهِ تتش، فلمَّا مَلَكَ تتش حران والرها سار إلى الدِّيارِ الجَزريَّةِ فمَلَكَها جَميعَها، ثم مَلَكَ دِيارَ بَكرٍ وخلاط، وسار إلى أذربيجان فمَلَكَ بِلادَها كُلَّها، ثم سار منها إلى همذان فمَلَكَها، وأَرسلَ إلى بغداد يَطلُب الخُطبةَ من الخَليفةِ المُستظهِر بالله، وكان شِحنَتُه –الشحنة يعني القَيِّم لضَبطِ البلد- ببغداد ايتكين جب، فلازَمَ الخِدمَةَ بالدِّيوانِ، وأَلَحَّ في طَلَبِها، فأُجيبَ إلى ذلك، بعدَ أن سَمِعوا أن بركيارق قد انهَزَم من عَسكرِ عَمِّهِ تتش."},{"id":1727,"title":"انهِزامُ بركيارق بنِ ملكشاه على يد عَمِّهِ تتش .","date":["العام الهجري :487","الشهر القمري : شوال","العام الميلادي :1094"],"text":"انهَزمَ بركيارق مِن عَسكرِ عَمِّهِ تتش. وكان بركيارق بنصيبين، فلمَّا سَمِعَ بمَسيرِ عَمِّهِ إلى أذربيجان، سار هو من نصيبين، وعَبَرَ دِجلةَ مِن بَلدٍ فوقَ المَوصِل، وسار إلى إربل، ومنها إلى بلدِ سرخاب بن بدرٍ إلى أن بَقِيَ بينه وبين عَمِّهِ تِسعةُ فَراسِخ، ولم يكُن معه غيُر ألف رَجُلٍ، وكان عَمُّه في خمسين ألف رَجُلٍ، فسارَ الأَميرُ يعقوبُ بن آبق مِن عَسكرِ عَمِّه، فكَبَسَهُ وهَزَمهُ، ونَهبَ سَوادَه، ولم يَبقَ معه إلا برسق، وكمشتكين الجاندار، واليارق، وهُم مِن الأُمراءِ الكِبارِ، فسار إلى أصبهان. فمَنَعَه مَن بِها مِن الدُّخولِ إليها، ثم أَذِنوا له خَديعةً منهم لِيَقبِضوا عليه، فلمَّا قارَبَها خَرجَ أَخوهُ المَلِكُ محمودٌ فلَقِيَهُ، ودَخلَ البلدَ، واحتاطوا عليه، فاتَّفقَ أنَّ أَخاهُ مَحمودًا حُمَّ وجُدِرَ، فأرادَ الأُمراءُ أن يَكحَلوا بركيارق، فماتَ محمودٌ آخر شَوَّال، فكان هذا مِن الفَرَجِ بعدَ الشِّدَّةِ، وجَلسَ بركيارق للعَزاءِ بأَخيهِ، ثم إن بركيارق جُدِرَ، بعدَ أَخيهِ، وعُوفِيَ وسَلِمَ، فلمَّا عُوفِيَ كاتَبَ مُؤَيِّدُ المُلْكِ وَزيرُه أُمراءَ العِراقيِّين، والخُراسانيِّين، واستَمالَهم، فعادوا كُلُّهم إلى بركيارق، فعَظُمَ شَأنُه وكَثُرَ عَسكرُه."},{"id":1728,"title":"وَفاةُ حاكِمِ مصر العُبيديِّ المُستَنصِر بالله وتَوَلِّي ابنِه المُستَعلِي بَعدَه .","date":["العام الهجري :487","الشهر القمري : ذي الحجة","العام الميلادي :1095"],"text":"هو المُستَنصِر بالله أبو تَميمٍ مَعَدُّ بنُ أبي الحَسنِ عليٍّ الظاهر بن الحاكم الفاطِميُّ العُبيديُّ صاحِبُ مصر والشام، وُلِدَ سَنةَ 420هـ, ووَلِيَ الأَمرَ بعدَ أَبيهِ الظاهرِ وله سَبعُ سنين، في شعبان سنة 427هـ، وفي وَسطِ دَولتِه خُطِبَ له بإَمْرَةِ المؤمنين على مَنابرِ العِراقِ. قال ابنُ خلكان: \"جَرَى في أَيامِه ما لم يَجرِ على أَيامِ أَحَدٍ مِن أَهلِ بَيتِه ممَّن تَقدَّمهُ ولا تَأخَّرهُ: منها قَضيةُ البساسيري فإنه لمَّا عَظُمَ أَمرُه، وكَبُرَ شأنُه ببغداد قَطعَ خُطبةَ الخَليفةِ العبَّاسيِّ القائمِ بأَمرِ الله، وخَطبَ للمُستَنصِر العُبيديِّ سَنةَ 450هـ، ودَعَا له على مَنابِرِها مُدَّةَ سَنَةٍ, ومنها أنه ثار في أَيامِه عليُّ بنُ محمدٍ الصليحيُّ ومَلَكَ بِلادَ اليَمنِ، ودَعَا للمُستَنصِر على مَنابِرِها, ومنها أنه أقامَ في الأَمرِ سِتِّينَ سَنَةً، وهذا أَمرٌ لم يَبلُغه أَحدٌ مِن أَهلِ بَيتِه ولا مِن بَنِي العبَّاسِ, ومنها أنه وَلِيَ الأَمرَ وهو ابنُ سَبعِ سِنين. ومنها أن دَعوتَهم لم تَزل قائمةً بالمَغربِ منذ قام جَدُّهُم المَهديُّ إلى أَيامِ المُعِزِّ ولمَّا تَوَجَّه المُعِزُّ إلى مصر واستَخلَف بلكين بن زيري، كانت الخُطبةُ في تلك النواحي لا زالت للعُبيديِّين، إلى أن قَطَعَها المُعِزُّ بن باديس في أَيامِ المُستَنصِر سَنةَ 443هـ، وفي سَنةِ 449هـ قُطِعَ اسمُ المُستَنصِر واسمُ آبائِه مِن الخُطبةِ في الحَرَمينِ، وذُكِرَ اسمُ المُقتدِي بأَمرِ الله خَليفةِ بغداد، ومنها أنه حَدَثَ في أَيامِه الغَلاءُ العَظيمُ الذي ما عُهِدَ مِثلُه منذ زَمانِ يوسف عليه السلام، وأقامَ سَبعَ سِنينَ، وأَكلَ الناسُ بَعضُهم بَعضًا، حتى قِيلَ: إنه بِيعَ رَغيفٌ واحدٌ بخَمسين دِينارًا، وكان المُستَنصِر في هذه الشِّدَّةِ يَركَب وَحدَه، وكلُّ مَن معه من الخَواصِّ مُتَرَجِّلون ليس لهم دَوابٌّ يَركَبونَها، وكانوا إذا مَشوا تَساقَطوا في الطُّرُقاتِ من الجُوعِ، وآخِرُ الأمرِ تَوجَّهَت أُمُّ المُستَنصِر وبَناتُه إلى بغداد من فَرْطِ الجُوعِ سَنةَ 462هـ، وتَفَرَّق أَهلُ مصر في البِلادِ وتَشتَّتوا\"، وتُوفِّي المُستَنصِر لَيلةَ الخميسِ لاثنتي عشرة لَيلةً بَقِينَ من ذي الحجَّةِ سَنةَ 487هـ وكانت مُدَّةُ حُكمِه سِتِّينَ سَنةً وأربعةَ أَشهُر، ولمَّا مات وَلِيَ بَعدَه ابنُه أبو القاسمِ أحمدَ المُستَعلِي بالله، وكان قد عَهِدَ في حَياتِه لابنِه نزار، فخَلَعهُ الأفضلُ أبو القسمِ شاهنشاه بن أَميرِ الجُيوشِ وبايَعَ المُستَعلِي بالله، وسَببُ خَلعِه أن الأفضلَ رَكِبَ مَرَّةً، أَيامَ المُستَنصِر، ودَخلَ دِهليزَ القَصرِ من بابِ الذَّهبِ راكِبًا، ونزار خارِجٌ، والمَجازُ مُظلِمٌ، فلم يَرَهُ الأفضلُ، فصاحَ به نزار: انزِل، يا أرمني، كلب، عن الفَرَسِ، ما أَقَلَّ أَدَبَك! فحَقَدَها عليه، فلمَّا مات المُستَنصِر خَلَعهُ خَوفًا منه على نَفسِه، وبايَعَ المُستَعلي، فهَرَب نزار إلى الإسكندريةِ، وبها ناصِرُ الدولةِ أفتكين، فبايَعَهُ أَهلُ الإسكندريةِ وسَمَّوهُ المُصطفَى لدِينِ الله، فخَطَبَ الناسَ، ولَعنَ الأَفضلَ، وأَعانَه أيضًا القاضي جَلالُ الدولةِ بنُ عَمَّارٍ، قاضي الإسكندريةِ، فسار إليه الأَفضلُ، وحاصَرَهُ بالإسكندريةِ، فعاد عنه مَقهورًا، ثم ازدادَ عَسكرًا، وسار إليه، فحَصَرهُ وأَخَذهُ، وأَخذَ أفتكين فقَتَلهُ، وتَسلَّم المُستعلِي نزارًا فبَنَى عليه حائِطًا فماتَ، وقَتَلَ القاضيَ جَلالَ الدولةِ بنَ عَمَّارٍ ومَن أَعانَه."},{"id":1729,"title":"استِفحالُ أَمْرِ بركيارق بنِ ملكشاه .","date":["العام الهجري :488","العام الميلادي :1095"],"text":"لمَّا مَلَكَ بركيارق بعدَ أَبيهِ وكان ما كان مِن قِتالِه مع عَمِّهِ تتش، ومُحاولَةِ بَعضِ العَسكرِ بالتَّحريضِ أن يَكحَلوهُ ويَسمُلوا عَينَيهِ فنَجَّاهُ الله من ذلك، ثم إنه مَرَضَ بالجُدَرِي وعاد عَمُّهُ لقِتالِه ثم شُفِيَ وقَتَلَ عَمَّهُ فأَصبحَ يَعلُو كَعبُه ويَقوَى شَأنُه ويَستَفحِل أَمرُه."},{"id":1730,"title":"وَفاةُ المُحَدِّثِ الحُمَيدِيِّ .","date":["العام الهجري :488","العام الميلادي :1095"],"text":"الإمامُ، القُدوَةُ، الأَثَرِيُّ المُتقِنُ، الحافِظُ، شَيخُ المُحَدِّثينَ، أبو عبدِ الله محمدُ بنُ أبي نَصرٍ فتوح بن عبدِ الله بن فتوحِ بن حُميدِ بن يصل الأزديُّ، الحُمَيدِيُّ، الأندلسيُّ؛ الميورقيُّ، الفَقِيهُ، الظاهِريُّ، مُؤَرِّخٌ ومُحَدِّثٌ أَندلسيٌّ من أَهلِ الجَزيرَةِ، صاحِبُ ابنِ حَزمٍ وتِلميذُه. وُلِدَ قبلَ سَنةِ 420هـ، بَدأَ بِطَلَبِ العِلمِ صَغيرًا قال عن نَفسِه: \"كُنتُ أُحمَلُ للسَّماعِ على الكَتِفِ، وذلك في سَنةِ 425هـ، فأَوَّلُ ما سَمِعتُ مِن الفَقيهِ أَصبغَ بنِ راشِدٍ، وكُنتُ أَفهمُ ما يُقرأُ عليه، وكان قد تَفَقَّهَ على أبي محمدِ بن أبي زَيدٍ، وأَصلُ أبي من قُرطبة مِن مَحِلَّةٍ تُعرفُ بالرصافة، فتَحوَّل وسَكَنَ جَزيرةَ ميورقة، وميورقة جَزيرةٌ فيها بَلدَةٌ حَصينَةٌ تِجاهَ شَرقِ الأَندلسِ، فوُلِدتُ بها\". رَحلَ إلى مكَّةَ ومصر والشامِ والعِراقِ واستَوطَنَ بغداد وفيها تُوفِّي، له تَصانيفٌ أَشهرُها: ((الجَمْعُ بين الصحيحين))، و((تاريخ الأندلس)) المُسَمَّى ((جذوة المقتبس في ذكر ولاة الأندلس)) و((الذهب المسبوك في وعظ الملوك)) وغَيرُها من المُصنَّفاتِ، قال يحيى بنُ إبراهيمَ السلماسيُّ: قال أبي: \"لم تَرَ عَيناي مِثلَ الحُميديِّ في فَضلِه ونُبلِه، وغَزارَةِ عِلمِه، وحِرصِه على نَشرِ العِلمِ، وكان وَرِعًا تَقِيًّا، إمامًا في الحَديثِ وعِلَلِهِ ورُواتِه، مُتَحَقِّقًا بعِلمِ التَّحقيقِ والأُصولِ على مَذهبِ أَصحابِ الحَديثِ بمُوافَقَةِ الكِتابِ والسُّنَّةِ، فَصيحَ العِبارَةِ، مُتَبَحِّرًا في عِلمِ الأَدبِ والعَربيَّةِ والتَّرَسُّلِ\" قال القاضي عِياض: \"محمدُ بنُ أبي نَصرٍ الحُمَيدِيُّ الأَزديُّ الأَندلسيُّ، سَمِعَ بميورقة من ابنِ حَزمٍ قَديمًا، وكان يَتَعَصَّب له، ويَميلُ إلى قَولِه، وأَصابَتهُ فِيه فِتنَةٌ، ولمَّا شُدِّدَ على ابنِ حَزمٍ، خَرجَ الحُميدِيُّ إلى المَشرقِ\" تُوفِّي الحُميديُّ: في سابع عشر ذي الحجَّةِ، عن 68 عامًا، وصَلَّى عليه أبو بكرٍ الشاشيُّ، ودُفِنَ بمَقبرَةِ بابِ أبرز، ثم إنهم نَقَلوهُ بعدَ سَنتَينِ إلى مَقبرَةِ بابِ حَربٍ، فدُفِنَ عندَ بِشْرٍ الحافي.  وقد اختُلِفَ في تاريخِ وَفاتِه؛ فقِيلَ: في هذه السَّنَةِ. وقِيلَ: 491هـ."},{"id":1731,"title":"دُخولُ الأَتراكِ أفريقية عُنوَةً ثم خُروجُهم منها .","date":["العام الهجري :488","العام الميلادي :1095"],"text":"غَدَرَ شاهملك التُّركيُّ بِيَحيى بنِ تَميمِ بنِ المُعِزِّ بنِ باديس، وقَبَضَ عليه، وكان شاهملك هذا من أَولادِ بَعضِ الأُمراءِ الأَتراكِ ببلادِ الشَّرقِ، فنالَهُ في بَلدِه أَمْرٌ اقتَضى خُروجَه منه، فسار إلى مصر في مائةِ فارسٍ، فأَكرَمَهُ الأَفضلُ أَميرُ الجُيوشِ، وأَعطاهُ إِقطاعًا ومَالًا، ثم بَلَغَهُ عنه أَسبابٌ أَوجبَت إِخراجَه من مصر، فخَرجَ هو وأَصحابُه هارِبينَ، فاحتالوا حتى أَخَذوا سِلاحًا وخَيْلًا وتَوجَّهوا إلى المغربِ، فوَصَلوا إلى طرابلس الغَربِ، وأَهلُ البَلدِ كارِهونَ لِوالِيها، فأَدخَلوهُم البَلدَ، وأَخرَجوا الوالي، وصار شاهملك أَميرَ البلدِ، فسَمِعَ تَميمٌ الخَبرَ، فأَرسلَ العَساكِرَ إليها، فحَصَروها، وضَيَّقوا على التُّركِ ففَتَحوها، ووَصَلَ شاهملك معهم إلى المَهدِيَّةِ، فسُرَّ بهِ تَميمٌ وبمَن معه، فخَرجَ يحيى بنُ تَميمٍ إلى الصَّيْدِ في جَماعةٍ من أَعيانِ أَصحابِه نحوَ مائةٍ فارسٍ، ومعه شاهملك، فغَدَرَ به شاهملك فقَبَضَ عليه، وسار به وبمَن أُخِذَ معه مِن أَصحابِه إلى مَدينةِ سفاقس، وبَلغَ الخَبرُ تَميمًا، فرَكِبَ، وسَيَّرَ العَساكرَ في إثرِهِم، فلم يُدرِكوهُم، ووَصلَ شاهملك بِيَحيى بنِ تَميمٍ إلى سفاقس، ثم إن صاحِبَ سفاقس خاف يحيى على نَفسِه أن يَثُورَ معه الجُنْدُ وأَهلُ البَلدِ ويُمَلِّكوهُ عليهم، فأَرسلَ إلى تَميمٍ كِتابًا يَسألُه في إِنفاذِ الأَتراكِ وأَولادِهم إليه لِيُرسِلَ ابنَه يحيى، ففَعلَ ذلك بعدَ امتِناعٍ، وقَدِمَ يَحيى، فحَجَبَهُ أَبوهُ عنه مُدَّةً، ثم أَعادَهُ إلى حالِه، ورَضِيَ عنه، ثم جَهَّزَ تَميمٌ عَسكرًا إلى سفاقس، ويحيى معهم، فساروا إليها وحَصَروها بَرًّا وبَحرًا، وضَيَّقوا على الأَتراكِ بها، وأَقاموا عليها شَهرَينِ، واستَولُوا عليها، وفارَقَها الأَتراكُ إلى قابس."},{"id":1732,"title":"البابا (أوربان الثاني) يُعلِن الحَربَ الصَّليبيَّة الأُولى على الأَتراكِ .","date":["العام الهجري :488","العام الميلادي :1095"],"text":"تَلَقَّى البابا أوربان الثاني نِداءً من الإمبراطورِ البِيزنطي إلكسيس كومنين يَطلُب منه العَوْنَ ضِدَّ السَّلاجِقَةِ الأَتراكِ، فيَعقِد البابا مَجْمَعًا كَنَسِيًّا في مَدينةِ كليرمون فران في فرنسا ويُعلِن الحَربَ الصَّليبيَّة الأُولى على الأَتراكِ، ويَدعُو إلى وَقْفِ الحَربِ بين المُلوكِ والأُمراءِ المَسيحِيِّينَ في أوربا، وتَوَجُّهِهِم بأَسلِحَتِهم لِحَربِ الكَفَرَةِ على حَدِّ تَعبيرِهِم، ويُعلِن أن كلَّ مَن يَشتَرِك في هذه الحَربِ تُغفَر له ذُنوبُه وتَتَوَلَّى الكَنيسةُ حِمايةَ مَمْلَكَتِه، وكان ريمون الرابع أَميرُ تولوز أَوَّلَ مَن لَبَّى النِّداءَ وتَوَلَّى قِيادةَ الحَملةِ الصَّليبيَّة الأُولى، كما طَلَبَ البابا من أَساقِفَةِ الكَنيسَةِ الكاثوليكيَّة الدَّعوةَ للحَربِ الصَّليبيَّة بين العامَّةِ، وكان أَبرزَ مَن تَوَلَّى الدَّعوةَ الأَسقفُ بُطرس النَّاسِك."},{"id":1733,"title":"وَفاةُ تتش بن ألب أرسلان صاحِبِ دِمشقَ .","date":["العام الهجري :488","الشهر القمري : صفر","العام الميلادي :1095"],"text":"هو المَلِكُ أبو سَعيدٍ تاجُ الدَّولةِ تتش بنُ محمد ألب أرسلان بن داود بن ميكال بن سلجوق بن دقاق السلجوقي، وَلَدُ سُلطانٍ وأَخو سُلطانٍ. صاحِبُ البِلادِ الشرقيَّةِ. وُلِدَ في رمضان سَنةَ 458هـ. تُركِيٌّ مُحتَشِمٌ، شُجاعٌ، مَهِيبٌ جَبَّارٌ، ذا سَطْوَةٍ، مِن بَيتِ مُلْكٍ، وله فُتوحاتٌ ومصافاتٌ، وتَمَلَّكَ عِدَّةَ مَدائنَ، وخُطِبَ له ببغداد، وصار مِن كِبارِ مُلوكِ الزَّمانِ وتقدم. مَرَّ كَثيرٌ مِن سِيرَتِه وفُتوحاتِه العَظيمةِ في الحَوادثِ.  تَمَلَّكَ بِضعَ عَشرةَ سَنةً. وكان يُغالِي في حُبِّ شَيخِ الإسلامِ أبي الفَرجِ الحَنبليِّ، ويَحضرُ مَجلِسَه، فعَقَدَ له ولِخُصومِه في مَسألَةِ القُرآنِ مَجلِسًا، قَدِمَ لبِلادِ الشامِ لمَّا حاصَرَ أَميرُ الجُيوشِ بَدرٌ الجماليُّ مَدينةَ دِمشقَ مِن جِهَةِ صاحبِ مصر العُبيديِّ, وكان صاحِبُ دِمشقَ يَومئذٍ أتسز بن أوق بن الخوارزميَّ التركيَّ, فاستَنجَدَ بتتش فأَنجَدَه وسار إليه بنَفسِه، فلمَّا وَصلَ إلى دِمشقَ خَرجَ إليه أتسز، فقَبَضَ عليه تتش وقَتلَه واستَولَى على مَملَكَتِه وذلك في سَنةِ 471هـ، ثم مَلَكَ حَلَب بعدَ ذلك في سَنةِ 478هـ، ثم استَولَى على مُعظَمِ البلادِ الشاميَّةِ، وجَرَت له أُمورٌ وحُروبٌ مع المِصريِّينَ، ثم جَرَى  بينه وبين ابنِ أَخيهِ بركياروق مُنافراتٌ ومُشاجراتٌ بعدَ وَفاةِ ملكشاه أَدَّت إلى المُحارَبَةِ بينهما، فتَوجَّه إليه تتش وتَصافَّا بالقُربِ من مَدينةِ الرَّيِّ في يَومِ الأَحدِ سابع عشر صَفَر سَنةَ 488هـ، فانكَسرَ تتش، وقُتِلَ في المَعركةِ ذلك النهارَ."},{"id":1734,"title":"وَفاةُ أبي شُجاعٍ الوَزيرِ الروذراوريِّ .","date":["العام الهجري :488","الشهر القمري : جمادى الآخرة","العام الميلادي :1095"],"text":"هو أبو شُجاعٍ الوَزيرُ محمدُ بن الوَزيرِ حُسينِ بن عبدِ الله بن إبراهيمَ، الروذراوريُّ، أَهوازيُّ الأَصلِ من همذان. كان أبو شُجاعٍ قد قَرأَ الفِقهَ والعَربيَّةَ، وسَمِعَ الحَديثَ من جَماعةٍ منهم: أبو إسحاقَ الشِّيرازيُّ، وصَنَّفَ كُتُبًا منها كِتابُه الذي ذَيَّلَهُ على ((تجارب الأمم)) ووَزَرَ للمُقتدِي بالله سَليمًا مِن طَمَعٍ، وكان يَملِك حِينئذٍ عَيْنًا ستمائة ألف دِينارٍ، فأَنفَقَها في الخَيراتِ والصَّدقاتِ. قال أبو جَعفرِ بن الخِرقيِّ: \"كُنتُ أنا مِن أَحَد عشر يَتَولَّون إِخراجَ صَدَقاتِه، فحَسِبتُ ما خَرَجَ على يَدِي فكان مائة ألف دِينارٍ، ووَقَّفَ الوُقوفَ، وبَنَى المَساجِدَ، وأَكثَرَ الإنعامَ على الأَرامِلِ واليَتامَى، وكان يَبيعُ الخُطوطَ الحَسَنَة، ويَتصدَّق بثَمَنِها ويقول: أَحَبُّ الأَشياءِ إليَّ الدِّينارُ والخَطُّ الحَسَن، فأنا أُخرِجُ للَّه مَحبوبي. ووَقَعَ مَرَضٌ في زَمانِه، فبَعَثَ إلى جَميعِ أَصقاعِ البَلدِ أَنواعَ الأَشرِبَةِ والأَدوِيَةِ، وكان يُخرِج العُشْرَ من جَميعِ أَموالِه النَّباتيَّة على اختِلافِ أَنواعِه. حَكَى حاجِبُه الخاصُّ بهِ قال: استَدعاني لَيلةً، وقال: إنِّي أَمَرتُ بعَمَلِ قَطائفَ، فلمَّا حَضَرَ بين يديَّ ذَكرتُ نُفوسًا تَشتَهيهِ فلا تَقدِرُ عليه، فنَغَّصَ ذلك عليَّ أَكْلَهُ، ولم أَذُق منه شَيئًا، فاحمِل هذه الصُّحونَ إلى أَقوامٍ فُقراءَ. فحَمَلَها الفَرَّاشُونَ معه، وجَعَلَ يَطرُق أَبوابَ المَساجِد ببابِ المَراتِبِ، ويَدفَع ذلك إلى الأَضِرَّاءِ المُجاوِرينَ بها\"  وكان يُبالِغُ في التَّواضُع، حتى تَرَكَ الاحتِجابَ فيُكَلِّم المَرأَةَ والطِّفلَ، وأَوْطَأَ العَوامَّ والصَّالِحينَ مَجلِسَه، وكان يُحضِر الفُقهاءَ الدِّيوانَ في كلِّ مُشكِلٍ، وكانوا إذا أَفتَوا في حَقِّ شَخصٍ بوُجوبِ حَقِّ القَصاصِ عليه سَأَلَ أَولياءَ الدَّمِ أَخْذَ شَيءٍ من مالِه وأن يَعفُوا، فإن فَعَلوا وإلَّا أَمَرَ بالقَصاصِ، وأَعطَى ذلك المالَ وَرَثَةَ المَقتُولِ الثاني، وفي زَمانِه أُسقِطَت المُكوسُ، وأُلبِسَ أَهلُ الذِّمَّةِ الغِيارَ، وتَقدَّم إلى الخِرَقيِّ المُحتَسِب أن يُؤَدِّبَ كلَّ مَن فَتَحَ دُكَّانَه يَومَ الجُمعةِ ويُغلِقَه يومَ السبتِ مِن البَزَّازينَ وغَيرِهم، وقال: هذه مُشارَكةٌ لليَهودِ في حِفْظِ سَبتِهم. وكان قد سَمِعَ أن النَّفَّاطِينَ والكِلابزيَّة -مَن يَتَولَّى تَربيَةَ الكِلابِ وبَيعَها- يَقِفونَ على دَكاكِين المُتعيِّشين فيَأخُذون منهم كلَّ أُسبوعٍ شَيئًا، فنَفَذَ مَن يَمنعُهم مِن الاجتِيازِ بهم. وحَجَّ في وِزارَتِه سَنةَ ثمانين، فبَذَلَ في طَريقِه الزَّادَ والأَدوِيَةَ، وعَمَّ أَهلَ الحَرمَينِ بصَدَقاتٍ، وساوَى الفُقراءَ في إِقامَةِ المَناسِك والتَّعَبُّد، وكان كَثيرَ البِرِّ للخَلْقِ، كَثيرَ التَّلَطُّفِ بهم، ولمَّا عُزِلَ خَرجَ إلى الجامِعِ يومَ الجُمعةِ فانثالَت عليه العامَّةُ تُصافِحُه وتَدعُو له، فكان ذلك سَبَبًا لالتِزامِه بَيتَه، والإنكارِ على مَن صَحِبَهُ، وبَنَى في دِهليزِ دارِهِ مَسجِدًا وكان يُؤَذِّن ويُصلِّي فيه، ثم وَرَدَت كُتُبُ نِظامِ المُلْكِ بإخراجِه من بغداد، فأُخرِجَ إلى بَلدةٍ، فأَقامَ مُدَّةً، ثم استَأذَنَ في الحَجِّ فأُذِنَ له فخَرجَ, وجاوَرَ بالمَدينَةِ، فلمَّا مَرِضَ مَرْضَ المَوتِ حُمِلَ إلى مَسجدِ رَسولِ الله صلَّى الله عليه وسلَّم, وتُوفِّي مِن يَومِه ودُفِنَ بالبَقيعِ بعدَ أن صُلِّيَ عليه بمَسجدِ رَسولِ الله صلَّى الله عليه وسلَّم، في مُنتَصفِ جُمادَى الآخِرَة من هذه السَّنَةِ وهو ابنُ إحدى وخمسين سَنةً، وكان له شِعْرٌ حَسَنٌ."},{"id":1735,"title":"وَفاةُ المُعتَمِد بنِ عَبَّادٍ مَلِك الأَندلسِ .","date":["العام الهجري :488","الشهر القمري : شوال","العام الميلادي :1095"],"text":"هو مَلِكُ الأَندلسِ المُعتَمِدُ على الله أبو القاسمِ محمدُ بنُ المُعتَضِد بالله أبي عَمروٍ عَبَّادِ بنِ الظافرِ المُؤيَّدِ بالله أبي القاسمِ محمدِ قاضي إشبيلية بن أبي الوليدِ إِسماعيلَ بن قُريشِ بن عَبَّاد بنِ عَمرِو بن أَسلمَ بنِ عَمرِو بنِ عَطَّاف بنِ نعيمٍ، اللخميُّ، مِن وَلَدِ النُّعمانِ بن المُنذِر اللخميِّ، آخرِ مُلوكِ الحِيرَةِ؛ كان المُعتَمِدُ صاحِبَ قُرطبةَ وإشبيلية وما والاهُما مِن جَزيرةِ الأندلسِ. كان بِدءُ أَمرِ عائِلَةِ المُعتَمِد في بِلادِ الأندلسِ أن نعيمًا وابنَه عَطَّافًا أَوَّلُ مَن دَخلَ إليها من بِلادِ المَشرقِ، وهُما مِن أَهلِ العريشِ، المَدينَة القَديمَة الفاضِلَة بين الشامِ والدِّيارِ المِصريَّة في أَوَّلِ الرَّملِ من جِهَةِ الشامِ، وأقامَا بها مُستَوطِنين بقَريَةٍ بقُربِ يَومينِ مِن إقليم طشانة من أَرضِ إشبيلية. نَشأَ المُعتَمِدُ بنُ عبَّادٍ في الأَندلسِ كغَيرِه مِن أَبناءِ المُلوكِ على المُيولِ والدِّعَةِ والتَّرَفِ، كان مَوصوفًا بالكَرمِ والأَدَبِ والحِلمِ، حَسَنَ السِّيرَةِ والعِشرَةِ والإحسانِ إلى الرَّعيَّةِ، والرِّفقِ بهم. تُوفِّي والدُه المُعتَضِد سَنةَ 464هـ فخَلَفَهُ في الحُكمِ، فكان فارِسًا شُجاعًا، عالِمًا أَديبًا، ذَكِيًّا شاعِرًا، مُحسِنًا جَوادًا مُمْدَحًا، كَبيرَ الشَّأنِ، خَيرًا مِن أَبيهِ. كان أَندَى المُلوكِ راحَةً، وأَرحَبَهُم ساحَةً، كان بابُه مَحَطَّ الرِّحالِ، وكَعبَةَ الآمالِ, ومَألَفَ الفُضلاءِ، حتى إنه لم يَجتمِع ببابِ أَحدٍ مِن مُلوكِ عَصرِه مِن أَعيانِ الشُّعراءِ وأَفاضِلِ الأُدباءِ ما كان يَجتَمِع ببابِه. قال أبو بكر محمدُ بن اللَّبَّانة الشاعِرُ: \"مَلَكَ المُعتَمِدُ مِن مُسَوَّراتِ البِلادِ مائتي مُسَوَّر، ووُلِدَ له مائةٌ وثلاثةٌ وسبعون وَلَدًا، وكان لِمَطبَخِه في اليوم ثَمانيةُ قَناطيرَ لَحمٍ، وكُتَّابُه ثَمانية عشر\".  ولمَّا قَوِيَ أَمرُ الأذفونش بعدَ أَخذِه طُليطلة، اجتَمعَ العُلماءُ، واتَّفَقوا مع ابنِ عَبَّادٍ على أن يُكاتِبوا الأَميرَ ابنَ تاشفين صاحِبَ مراكش لِيُنجِدَهُم، فقال جَماعةٌ لابنِ عبَّادٍ: نَخافُ عليك من استِمدادِه. فقال: رَعْيُ الجِمالِ خَيرٌ مِن رَعْيِ الخَنازيرِ. فلمَّا عَبَرَ ابنُ تاشفين بجُيوشِه إلى الجَزيرَةِ، اجتَمعَ به المُعتَمِد، وأَقبَلَت المُطَّوِّعَةُ من النَّواحي، وقاتَلَ المُعتَمِدُ بن عبَّادٍ في الزَّلَّاقَةِ وثَبَتَ في ذلك اليوم ثَباتًا عَظيمًا، وأَصابَهُ عِدَّةُ جِراحاتٍ في وَجهِه وبَدَنِه، وشُهِدَ له بالشَّجاعَةِ، وغَنِمَ المسلمون دَوابَّ الفِرنجَةِ وسِلاحَهم، ورَجَعَ ابنُ تاشفين إلى بِلادِه والمُعتَمِد إلى بِلادِه. ثم إن الأَميرَ يوسفَ عادَ إلى الأندلسِ بعدَ أن وَصلَتهُ فَتاوَى العُلماءِ بخَلعِ مُلوكِ الطَّوائفِ قال ابنُ خلدون: \"وأَفتاهُ الفُقهاءُ وأَهلُ الشُّورَى من المَغربِ والأَندلسِ بِخَلْعِهِم وانتِزاعِ الأَمرِ مِن أَيدِيهم، وصارَت إليه بذلك فَتاوَى أَهلِ الشَّرقِ الأَعلامِ مثل: الغزاليِّ والطَّرطوشيِّ\". فلمَّا أَجازَ ابنُ تاشفين انقَبَضوا عنه إلَّا ابنَ عَبَّادٍ فإنه بادَرَ إلى لِقائِه. استَعانَ بالأذفونش مَلِكُ اشتاله وطَلَبَ منه المَدَدَ، فقَدَّمَ ابنُ تاشفين سيرَ بنَ أبي بكر الأندلسي، فوَصَلَ إلى إشبيلية وبها المُعتَمِدُ فحاصَرَهُ أَشَدَّ مُحاصَرةٍ، وظَهرَ مِن مُصابَرةِ المُعتَمدِ وَشِدَّةِ بَأسِه وتَرامِيه على المَوتِ بنَفسِه ما لم يُسمَع بمِثلِه، والناسُ بالبلدِ قد استَولَى عليهم الفَزَعُ وخامَرَهُم الجَزَعُ, فلمَّا كان يومُ الأَحدِ العشرين من رجب سَنةَ 484هـ هَجَمَ عَسكرُ الأَميرِ ابنِ تاشفين البَلدَ وشَنُّوا فيه بالغاراتِ، وقُبِضَ على المُعتَمِد وأَهلِه، وكان قد قُتِلَ له وَلدانِ قبلَ ذلك، أَحدُهما: المأمون، نائِبُه في قُرطبة والثاني الرَّاضي، كان نائِبًا عن أَبيهِ في رندة، وهي مِن الحُصونِ المَنيعَةِ, ولمَّا أُخِذَ المُعتَمِد قَيَّدوهُ من ساعَتِه، وأُودِعَ سِجْناً في أغمات بالعَدوَةِ وتَشَرَّدَ أَهلُه وافتَقَروا في بلادِ المَغربِ, ودَخَلَ عليه يَومًا بَناتُه السِّجنَ، وكان يَومَ عِيدٍ، وكُنَّ يَغزِلنَ للناسِ بالأُجرَةِ في أغمات، فرآهُنَّ في أَطمارٍ رَثَّةٍ وحالَةٍ سَيِّئَةٍ، فصَدَّعنَ قَلبَه وأَنشدَ:\"فيما مضى كنت بالأعياد مسرورا فساءك العيد في أغمات مأسورنرى بناتك في الأطمار جائعةًيغزلن للناس لا يملكن قطميرابرزن نحوك للتسليم خاشعةًأبصارهن حسيراتٍ مكاسيرايطأن في الطين والأقدام حافيةٌكأنها لم تطأ مسكًا وكافورا\"زالت دَولةُ المُعتَمِد بن عبَّادٍ على يَدِ شَريكِه في النَّصرِ بعدَ أن دَخلَ قُرطبة، ومات غَريبًا في مَنفاهُ بـأغمات بالمغربِ, وقد حَزِنَ الناسُ عليه، وقال في مُصابِه الشُّعراءُ فأَكثَروا, ويُعتَبر مِن أَشهرِ مُلوكِ دَولةِ الطَّوائفِ التي قامَت في الأَندلسِ في القَرنِ الخامسِ الهِجريِّ، بعدَ انهِيارِ دَولةِ الخِلافةِ الأُمويَّة."},{"id":1736,"title":"وَفاةُ أَميرِ الجُيوشِ بَدرِ بنِ عبدِ الله الجمالي .","date":["العام الهجري :488","الشهر القمري : ذي القعدة","العام الميلادي :1095"],"text":"هو أَميرُ الجُيوشِ، الوَزيرُ الأَرمَنيُّ، بَدرُ بنُ عبدِ الله الجمالي، اشتَراهُ جَمالُ المُلْكِ بنُ عمَّارٍ الطَّرابلسيُّ، ورَبَّاهُ، فتَرَقَّت به الأَحوالُ إلى المُلْكِ. وَلِيَ نِيابَةَ دِمشقَ للمُستَنصِر الفاطميِّ سَنَةَ 455هـ، إلى أن هاجَ أَحداثُ دِمشقَ وشُطَّارُها سَنةَ 460هـ, فتَحَوَّل إلى مصر, وقِيلَ: لمَّا ضَعُفَ حالُ المُستَنصِر في مصر واختَلَّت دَولتُه وُصِفَ له بَدرٌ الجمالي، فاستَدعاهُ فرَكِبَ البَحرَ ووَصلَ القاهِرةَ عَشِيَّةَ يَومِ الأَربعاءِ للَيلَتَينِ بَقِيَتَا من جُمادَى الأُولى، فوَلَّاهُ المُستَنصِر تَدبيرَ أُمورِه، وقامَت بوُصولِه الحُرمَةُ وأَصلَحَ الدَّولةَ؛ وكان وَزيرَ السَّيْفِ والقَلَمِ، وإليه قَضاءُ القُضاةِ والتَّقَدُّمُ على الدُّعاةِ، وساس الأُمورَ أَحسَنَ سِياسَةٍ، ويُقال: إن وُصولَه كان أَوَّلَ سَعادَةِ المُستَنصِر، وكان يُلَقَّب: أَميرَ الجُيوشِ؛ وأَنشأَ بالإسكندريَّةِ جامِعَ العَطَّارِينَ، وكان بَدرٌ الجمالي بَطَلًا شُجاعًا مَهِيبًا، مِن رِجالِ العالَمِ، قَصَدَهُ عَلقمةُ العليميُّ الشاعِرُ، فعَجَزَ عن الدُّخولِ إليه، فوَقَفَ على طَريقِه، وفي رَأسِه رِيشُ نَعامٍ، ثم أَنشَدَهُ أَبياتًا وَقَعَت منه بمَوقِع، ووَقَفَ له، ثم أَمَرَ الحاشِيةَ أن يَخلَعوا عليه، وأَمَرَ له بعَشرةِ آلافٍ، فذَهَبَ بخِلَعٍ كَثيرَةٍ إلى الغايَةِ، وَهَبَ منها لِجَماعَةٍ من الشُّعَراءِ\". مات بَدرٌ بمصر سَنةَ 488هـ وخَلَّفَ أَموالًا عَظيمَةً. وقام بَعدَه ابنُه الأَفضلُ المُلَقَّب أيضًا بأَميرِ الجُيوشِ, ولمَّا مَرِضَ واشتَدَّ مَرَضُه في شَهرِ رَبيعٍ الأَوَّل من سَنةِ 487هـ، وَزَرَ وَلدُه الأَفضلُ مَوضِعَه في حَياتِه، وقِيلَ: عاش بَدرٌ نَحوًا من ثمانين سَنَةً."},{"id":1737,"title":"عُدوانُ قبيلة خَفاجَة العربية على سَيفِ الدَّولَةِ بنِ مزيد .","date":["العام الهجري :489","العام الميلادي :1095"],"text":"أَغارَت خَفاجَةُ على بَلدِ سَيفِ الدولةِ صَدَقَة بنِ مزيد، فأَرسلَ في إِثْرِهِم عَسكَرًا، مُقَدِّمُه ابنُ عَمِّهِ قُريشُ بن بدران بن دبيس بن مزيد، فأَسَرَتهُ خَفاجةُ، وأَطلَقوهُ، وقَصَدوا مَشهدَ الحُسينِ بنِ عليٍّ، فتَظاهَروا فيه بالفَسادِ والمُنكَرِ، فوَجَّهَ إليهم صَدقةُ جَيشًا، فكَبَسوهُم، وقَتَلوا منهم خَلْقًا كَثيرًا في المَشهدِ، حتى عند الضَّريحِ، وأَلقَى رَجلٌ منهم نَفسَه وهو على فَرَسِه من على السُّورِ، فسَلِمَ هو والفَرَسُ."},{"id":1738,"title":"الدَّعوةُ لِقِيامِ الحَملَةِ الصَّلِيبيَّةِ الأُولى .","date":["العام الهجري :489","العام الميلادي :1095"],"text":"دَعا البابا أوربان الثاني إلى حَربٍ صَليبيَّةٍ ضِدَّ المسلمين واستَجابَ أُمراءُ أوربا لهذا النِّداءِ فأَوقَفوا الحُروبَ بينهم وأَعَدُّوا حَملَةً صَليبيَّةً مُنَظَّمَةً اشتَركَ فيها الدوق جودفري بويون أَميرُ مُقاطَعَةِ اللورين السُّفلَى، وأَخوهُ بودوان، وريمون أَميرُ تولوز، وبروفانس وبوهمند النورماندي أَميرُ تارانت، وابنُ أُختِه تانكرد، وروبير أَميرُ نورماندي وهو ابنُ وليم الفاتح، وصِهرُه اتيان أَميرُ مُقاطَعةِ بلوا وشارتر، وبَدَأوا بالمَسيرِ من مَدينةِ كولونيا إلى بِلادِ البَلقان. ونُفوسُهم تَسمُوا للوُصولِ للشامِ ثم بَيتِ المَقدِس مَسجِدِ أَنبِيائِهِم ومَطلَعِ دِينِهم، فتَتابَعوا إليه نِهايةَ القَرنِ الخامس الهِجريِّ، وتَواثَبوا على أَمصارِ الشامِ وحُصونِه وسَواحِلِه. ويُقال: \"إنَّ المُستَنصِرَ العُبيديَّ هو الذي دَعاهُم لذلك وحَرَّضَهم عليه لِمَا رَجَى فيه مِن اشتِغالِ مُلوكِ السَّلجوقيَّةِ بأَمرِهِم، وإقامَتِهم سَدًّا بينه وبينهم عندما سَمَوا إلى مُلْكِ الشامِ ومصر\" وقد ذَكَرَ السيوطيُّ في تاريخِ الخُلفاءِ: \"أن صاحِبَ مصر لمَّا رأى قُوَّةَ السَّلجوقيَّةِ واستِيلائِهِم على الشامِ كاتَبَ الفِرنجَ يَدعوهُم إلى المَجيءِ إلى الشامِ لِيَملكُوها، وكَثُرَ النَّفيرُ على الفِرنجِ مِن كُلِّ جِهَةٍ\""},{"id":1739,"title":"مِلْكُ تَميمِ بنِ المُعِزِّ مَدينةَ قابس .","date":["العام الهجري :489","العام الميلادي :1095"],"text":"في هذه السَّنَةِ مَلَكَ تَميمُ بنُ المُعِزِّ مَدينةَ قابس، وأَخرَجَ منها أَخاهُ عَمْرًا, وسَببُ ذلك أنه كان بها إنسانٌ يُقال له قاضي بن إبراهيمَ بن بلمونه فماتَ، فوَلَّى أَهلُها عليهم عَمرَو بنَ المُعِزِّ، فأَساءَ السِّيرَةَ، وكان قاضي بن إبراهيمَ عاصِيًا على تَميمٍ، وتَميمٌ يُعرِض عنه، فعَصَى عَمرٌو على أَخيهِ كقاضي بن إبراهيم، فأَخرجَ تَميمٌ العَساكِرَ إلى أَخيهِ عَمرٍو لِيَأخُذَ المَدينةَ منه، فقال بَعضُ أَصحابِه: يا مَولانا لمَّا كان فيها قاضي تَوانَيتَ عنه وتَركتَهُ، فلمَّا وَلِيَها أَخوكَ جَرَرتَ إليه العَساكِرَ! فقال: لمَّا كان فيها غُلامٌ مِن عَبيدِنا كان زَوالُه سَهلًا علينا، وأمَّا اليومَ، وابنُ المُعِزِّ بالمَهدِيَّةِ، وابنُ المُعِزِّ بقابس، فهذا ما لا يُمكِن السُّكوتُ عليه."},{"id":1740,"title":"وَفاةُ مَنصورِ بنِ نِظامِ الدِّينِ بنِ نَصرِ الدَّولَةِ بنِ مَروانَ .","date":["العام الهجري :489","الشهر القمري : محرم","العام الميلادي :1096"],"text":"هو أبو المُظَفَّرِ مَنصورُ بن نِظامِ الدِّينِ نَصرِ بنِ نَصيرِ الدَّولةِ مَروانَ بنِ دوستك الكُرديُّ، صاحِبُ دِيارِ بَكرٍ، تَوَلَّى الحُكمَ بعدَ وَالدِه نِظامِ الدِّين في ذي الحجَّةِ سَنةَ 472هـ، ودَبَّرَ دَولتَهُ ابنُ الأَنبارِيِّ، ولم يَزَل في مُلكِه إلى أن انقَرَضَ أَمرُ بَنِي مَروانَ على يَدِ فَخرِ الدَّولةِ بنِ جَهيرٍ حين حارَبَهُ، وكان جكرمش قد قَبَضَ عليه بالجَزيرَةِ، وتَرَكَهُ عند رَجلٍ يَهوديٍّ، فمات في دارِه، وحَمَلَتهُ زَوجتُه إلى تُربَةِ آبائِه، فدَفَنَتهُ ثم حَجَّت، وعادَت إلى بَلدِ البَشْنَوِيَّة. قال ابنُ الأَثيرِ: \" كان مَنصورٌ شُجاعًا، شَدِيدَ البُخْلِ، له في البُخْلِ حِكاياتٌ عَجيبَة، فتَعْسًا لِطالِبِ الدُّنيا، المُعرِض عن الآخِرَةِ، ألا يَنظُر إلى فِعلِها بأَبنائِها، بينما مَنصورٌ هذا مَلِكٌ مِن بَيتِ مَلِكٍ آلَ أَمرُه إلى أن ماتَ في بَيتِ يَهودِيٍّ، نَسألُ الله تعالى أن يُحسِن أَعمالَنا، ويُصلِح عاقِبَةَ أَمرِنا في الدنيا والآخرة، بمَنِّهِ وكَرَمِه\"."},{"id":1741,"title":"وَفاةُ مَنصورِ بنِ مُحمدٍ السَّمعانيِّ .","date":["العام الهجري :489","الشهر القمري : ربيع الأول","العام الميلادي :1096"],"text":"هو أبو المُظَفَّرِ مَنصورُ بنُ محمدِ بنِ عبدِ الجَبَّارِ بنِ أَحمدَ بنِ محمدٍ، السَّمعانيُّ، التَّميميُّ المَروَزِيُّ، الفَقِيهُ الحَنفيُّ ثم الشافعيُّ. الحافِظُ، مِن أَهلِ مَرْو، وُلِدَ في ذي الحجَّةِ 426هـ, وتَفَقَّهَ أَوَّلًا على أَبيهِ في مَذهَبِ أبي حَنيفَةَ، حتى بَرَعَ فيه وبَرَزَ على أَقرانِه, ثم انتَقَل إلى مَذهَبِ الشافعيِّ فأَخَذَ عن أبي إسحاقَ الشِّيرازيِّ وابنِ الصَّبَّاغِ. ذَكرَهُ أبو الحَسنِ عبدُ الغافِر فقال: \"هو وَحيدُ عَصرِه في وَقتِه فَضلًا، وطَريقَةً، وزُهْدًا، ووَرَعًا، من بَيتِ العِلمِ والزُّهدِ. تَفَقَّه بأَبيهِ، وصار من فُحولِ أَهلِ النَّظَرِ، وأَخَذَ يُطالِع كُتُبَ الحَديثِ، وحَجَّ، فلمَّا رَجَعَ إلى وَطَنِه تَرَكَ طَريقَتَهُ التي ناظَرَ عليها أَكثرَ من ثلاثين سَنةً، وتَحَوَّلَ شافِعِيًّا. أَظهَرَ ذلك في سَنةِ ثَمانٍ وسِتِّين وأربعمائة. واضطَرَبَ أَهلُ مَرو لذلك، وتَشَوَّشَ العَوامُّ، إلى أن وَرَدَت الكُتُبُ مِن جِهَةِ بلكابك من بَلخ في شَأنِه والتَّشديدِ عليه، فخَرجَ مِن مَرو، ورافَقَهُ ذو المَجدَينِ أبو القاسمِ الموسويُّ، وطائِفةٌ من الأَصحابِ، وخَرجَ في خِدمَتِه جَماعةٌ من الفُقهاءِ وصار إلى طُوس، وقَصَدَ نيسابور، فاستَقبَلَهُ الأَصحابُ استِقبالًا عَظيمًا, وكان في نَوبَةِ نِظامِ المُلْكِ وعَميدِ الحَضرَةِ أبي سعدٍ محمدِ بنِ مَنصورٍ، فأَكرَموا مَورِدَه، وأَنزَلوه في عِزٍّ وحِشمَةٍ، وعُقِدَ له مَجلِسُ التَّذكيرِ في مَدرسةِ الشافعيَّةِ\", وكان بَحرًا في الوَعظِ، حافِظًا لكَثيرٍ من الرِّواياتِ والحِكاياتِ والنُّكَتِ والأَشعارِ، فظَهرَ له القَبولُ عند الخاصِّ والعامِّ. واستَحكَمَ أَمرُه في مَذهبِ الشافعيِّ. ثم عاد إلى مَرو، ودَرَّسَ بها في مَدرسةِ أَصحابِ الشافعيِّ، وقَدَّمَهُ نِظامُ المُلْكِ على أَقرانِه، وعَلَا أَمرُه، وظَهرَ له الأَصحابُ. وخَرجَ إلى أصبهان، ورَجعَ إلى مَرو. وكان قَبولُه كلَّ يَومٍ في عُلُوٍّ, وتَعَصَّبَ للسُّنَّةِ والجَماعَةِ وأَهلِ الحَديثِ. وكان شَوْكًا في أَعيُنِ المُخالِفين، وحُجَّةً لأَهلِ السُّنَّةِ. قال أبو المعالي الجُويني: \"لو كان مِن الفِقْهِ ثَوْبًا طاوِيًا لكان أبو المُظَفَّر بن السمعاني طَرَّازَهُ\".قال الإمامُ أبو عليِّ بن أبي القاسمِ الصَّفَّارِ: \"إذا ناظَرتَ أبا المُظَفَّر السمعانيَّ، فكأنِّي أُناظِرُ رَجُلًا من أئِمَّةِ التَّابِعين، ممَّا أَرَى عليه من آثارِ الصَّالِحين سَمْتًا، وحُسْنًا، ودِينًا\".كانت له يَدٌ طُولَى في فُنونٍ كَثيرةٍ، وصَنَّفَ التَّفسيرَ وكِتابَ ((الانتصار)) في الحَديثِ، و((البرهان)) و((القواطع)) في أصول الفقه، و((الاصطلام)) وغيرَ ذلك، ووَعَظَ في مَدينةِ نيسابور. كان يقول: \"ما حَفِظتُ شَيئًا فنَسيتُه، وسُئِلَ عن أَخبارِ الصِّفاتِ فقال: عليكم بِدِينِ العَجائِزِ وصِبيانِ الكَتاتيبِ. وسُئِلَ عن الاستِواءِ فأَنشدَ قائِلًا: جِئتُماني لِتَعلَما سِرَّ سُعْدَى تَجِداني بِسِرِّ سُعْدَى شَحيحاإن سُعْدَى لَمُنْيَةُ المُتَمَنِّيجَمَعَت عِفَّةً ووَجْهًا صَبيحا\"دُفِنَ في مَقبَرةِ مَرو."},{"id":1742,"title":"نِهايَةُ الدَّولَةِ العُقَيلِيَّةِ بالمَوصِل .","date":["العام الهجري :489","الشهر القمري : ذي القعدة","العام الميلادي :1096"],"text":"مَلَكَ قِوامُ الدَّولةِ أبو سَعيدٍ كربوقا التُّركيُّ مَدينةَ المَوصِل، فأَسَرَهُ تاجُ الدولةِ تتش لمَّا قَتَلَ أتسز وبوزان، فلمَّا أَسَرَهُ أَبقَى عليه، ولم يكُن له بلدٌ يَملِكُه إذا قَتلَه، كما فَعلَ الأُميرُ بوزان، فإنه قَتَلَهُ واستَولَى على بِلادِه الرها وحران. ولم يَزَل قِوامُ الدولةِ مَحبوسًا بحَلَب إلى أن قُتِلَ تتش، ومَلَكَ ابنُه المَلِكُ رضوان حَلَب فأَرسلَ السُّلطانُ بركيارق رَسولًا يَأمُرهُ بإطلاقِه وإطلاقِ أَخيهِ التونتاش، فلمَّا أُطلِقَا سارا واجتَمَع عليهما كَثيرٌ من العَساكِر البَطَّالين، فأَتَيَا حران فتَسَلَّماها، وكاتَبَهُما محمدُ بنُ شَرفِ الدولةِ مُسلمِ بنِ قُريشٍ العُقيليُّ، وهو بنصيبين، ومعه ثروانُ بنُ وهيب، وأبو الهَيْجاءِ الكُرديُّ، يَستَنصِرونَ بهما على الأَميرِ عليِّ بنِ شَرفِ الدولةِ العُقيليِّ، وكان بالمَوصِل قد جَعلَهُ بها تاجُ الدولةِ تتش بعدَ وَقعَةِ المُضَيَّع, فسار قِوامُ الدولةِ إليهم، فلَقِيَهُ محمدُ بنُ شَرفِ الدولةِ على مَرحَلتَينِ من نصيبين، واستَحلَفَهُما لِنَفسِه، فقَبَضَ عليه قِوامُ الدولةِ بعدَ اليَمينِ، وحَمَلَهُ معه، وأَتَى نصيبين، فامتَنَعت عليه، فحَصَرَها أربعين يومًا، وتَسَلَّمها، وسار إلى المَوصِل فحَصَرَها، فلم يَظفَر منها بشيءٍ، فسار عنها إلى بلدٍ، وقَتَلَ بها محمدَ بنَ شَرفِ الدولةِ، وغَرَّقَهُ، وعاد إلى حِصارِ المَوصِل، ونَزلَ على فَرسَخٍ منها بقَريَةِ باحلافا، وتَركَ التونتاش شَرقيَّ المَوصِل، فاستَنجَد عليُّ بنُ مُسلمِ بن قُريشٍ العُقيليُّ صاحِبُها بالأَميرِ جكرمش، صاحِبِ جَزيرَةِ ابنِ عُمَرَ، فسار إليه نَجدَةً له، فلمَّا عَلِمَ التونتاش بذلك سار إلى طَريقِه، فقاتَلَهُ، فانهَزَم جكرمش، وعاد إلى الجَزيرَةِ مُنهَزِمًا، وصار في طاعَةِ قِوامِ الدولةِ، وأَعانَهُ على حَصْرِ المَوصِل، وعُدِمَت الأَقواتُ بها وكلُّ شيءٍ، حتى ما يُوقِدونَه، فأَوقَدوا القِيرَ، وحَبَّ القُطنِ. فلمَّا ضاقَ بصاحِبِها عليٍّ الأَمرُ وفارَقَها وسار إلى الأَميرِ صَدقَةَ بن مزيد الأَسَديِّ، أَميرِ العَربِ بالحِلَّةِ، وتَسَلَّم قِوامُ الدولةِ البلدَ بعدَ أن حَصَرَهُ تِسعةَ أَشهُر، وخافَهُ أَهلُه لأنه بَلَغَهم أن التونتاش يُريدُ نَهبَهم، وأن قِوامَ الدولةِ يَمنَعهُ من ذلك، فاشتَغَل التونتاش بالقَبضِ على أَعيانِ البَلدِ، ومُطالَبَتِهم بوَدائِع البلدِ، واستَطالَ على قِوامِ الدولةِ، فأَمَرَ بقَتْلِ التونتاش، فقُتِلَ في اليومِ الثالثِ، وأَمِنَ الناسُ شَرَّهُ، وأَحسَنَ قِوامُ الدولةِ السِّيرَةَ فيهم، وسارَ نحوَ الرَّحبَة، فمُنِعَ عنها، فمَلَكَها ونَهَبَها واستَنابَ بها وعاد."},{"id":1743,"title":"الفِتنَةُ بنيسابور بين طائفة الكَرامِيَّة والطَّوائفِ الأخرى .","date":["العام الهجري :489","الشهر القمري : ذي الحجة","العام الميلادي :1096"],"text":"جَمَعَ أَميرٌ كَبيرٌ مِن أُمراءِ خراسان جَمْعًا كَثيرًا، وسار بهم إلى نيسابور، فحَصَرَها، فاجتَمَع أَهلُها وقاتَلوهُ أَشَدَّ قِتالٍ، ولازَمَ حِصارَهم نحوَ أربعين يومًا، فلمَّا لم يَجِد له مَطْمَعًا فيها سار عنها في المُحرَّمِ سَنةَ 489هـ، فلمَّا فارَقَها وَقَعَت الفِتنَةُ بها بين الكَرامِيَّة وسائرِ الطَّوائفِ من أَهلِها، فقُتِلَ بينهم قَتلَى كَثيرةٌ، وكان مُقَدَّمُ الشافعيَّةِ أبا القاسمِ بن إمامِ الحَرمَينِ أبي المعالي الجُويني، ومُقَدَّمُ الحَنفيَّةِ القاضي محمدَ بنَ أَحمدَ بنِ صاعِد، وهُما مُتَّفِقان على الكَرامِيَّةِ، ومُقَدَّمُ الكَرامِيَّةِ محمشاد، فكان الظَّفَرُ للشافعيَّةِ والحَنفيَّةِ على الكَراميَّةِ، فخَرِبَت مَدارِسُهم، وقُتِلَ كَثيرٌ منهم ومن غَيرِهم، وكانت فِتنَةٌ عَظيمةٌ."},{"id":1744,"title":"هزيمة قلج بن أرسلان صاحب قونية على يد الصليبيين .","date":["العام الهجري :490","العام الميلادي :1096"],"text":"لَمَّا زحف الإفرنجُ إلى سواحل الشام جعلوا طريقَهم على القسطنطينية، فمنعهم من ذلك ملك الروم حتى شرَطَ عليهم أن يعطوه أنطاكية إذا ملكوها، فأجابوا لذلك، وعبروا خليجَ القسطنطينية، ومروا ببلاد قلج أرسلان بن سليمان بن قطلمش السلجوقي فلَقِيَهم في جموعه قريبًا من قونية، فهزموه."},{"id":1745,"title":"عصيان يارقطاش وقدون على السلطان بركيارق .","date":["العام الهجري :490","العام الميلادي :1096"],"text":"كان الأميرُ قودن صار في جملة الأمير قماج، فلما توفي قماج، والسلطان بمرو، فاستوحش قودن، وأظهر المرض، وتأخَّرَ بمروٍ بعد مسير السلطان بركيارق إلى العراق، وكان من جملة أمراء السلطان أمير اسمه اكنجي، وقد ولاه السلطان خوارزم، ولقَّبه خوارزمشاه، فجمع عساكِرَه وسار في عشرة آلاف فارس ليلحقَ السلطان، فسبق العسكر إلى مرو في ثلاثمائة فارس، وتشاغل بالشُّرب، فاتفق قودن وأمير آخر اسمه يارقطاش على قتله، فجمعا خمسمائة فارس وكبسوه وقتلوه، وساروا إلى خوارزم، وأظهروا أنَّ السلطان قد استعملهما عليها فتسلَّماها، وبلغ الخبر إلى السلطان، فأعاد أمير داذ حبشي بن التونتاق في جيش إلى خراسان لقتالهما، فسار إلى هراة، وأقام ينتظر اجتماعَ العساكر معه، فعاجلاه في خمسة عشر ألفًا، فعَلِمَ أمير داذ أنَّه لا طاقة له بهما، فعبَرَ جيحون، فسارا إليه، وتقدَّم يارقطاش ليلحقه قودن، فعاجله يارقطاش وحده وقاتله، فانهزم يارقطاش وأُخذ أسيرًا، وبلغ الخبر إلى قودن، فثار به عسكرُه، ونهبوا خزائنَه وما معه، فبقيَ في سبعة نفر، فهرب إلى بخارى، فقَبَض عليه صاحبُها، ثم أحسن إليه، وبقِيَ عنده، وسار من هناك إلى الملك سنجر ببلخ، فقَبِله أحسنَ قبول، وبذل له قودن أن يكفيَه أمورَه، ويقومَ بجمع العساكر على طاعته، فقُدِّرَ أنه مات عن قريبٍ، وأما يارقطاش فبقِيَ أسيرًا إلى أن قتل أمير داذ."},{"id":1746,"title":"مقتل أرسلان أرغون السلجوقي ملك خراسان .","date":["العام الهجري :490","الشهر القمري : محرم","العام الميلادي :1097"],"text":"هو صاحبُ خراسانَ أرسلان أرغون بن ألب أرسلان السلجوقي: أخو السلطان ملكشاه. لما مات أخوه السلطان ملكشاه بادر أرسلان أرغون واستولى على خراسان، وتمكَّن من تملُّك بلخ ومرو وترمذ، وخرَّبَ سورَ نيسابور وغيرَها من المدائن، ووزَر له عمادُ الملك بن نظام الملك، ثم قَبَض عليه وأخذ منه ثلاثمائة ألف دينار وذبحه. وكان ظالِمًا شرس الأخلاق, قتل أرسلان أرغون بمرو، وكان سبب قتله أنه كان شديدًا على غلمانه، كثيرَ الإهانة لهم والعقوبة، وكانوا يخافونه خوفًا عظيمًا، فاتفق أنَّه طلب غلامًا له فدخل عليه وليس معه أحدٌ، فأنكر عليه تأخُّرَه عن الخدمة فاعتذَرَ، فلم يقبَلْ عُذرَه وضربه، فأخرج الغلامُ سكينًا معه وقتَلَه، وأُخِذَ الغلام، فقيل له: لمَ فعلتَ هذا؟ فقال: لأريحَ الناسَ مِن ظُلمِه. وكانت دولته أربع سنين، فلما عَلِمَ بمقتله السلطان بركيارق بن ملكشاه سار إلى خراسان واستولى عليها، وخطب لبركيارق أيضًا ببلاد ما وراء النهر، واستناب على خراسان أخاه الملك سنجر الذي امتدَّت أيامه."},{"id":1747,"title":"حملة الصليبيين العامة (الشعبية)\n  .","date":["العام الهجري :490","الشهر القمري : صفر","العام الميلادي :1097"],"text":"على إثر دعوة البابا قامت حركة شعبية ضخمة ارتبطت باسم بطرس الناسك الذي أخذ يتجول غرب أوربا، بثيابه الرثَّة وقدميه العاريتين وحمارِه الأعرج، يدعو العامةَ والدهماءَ، وقد استجاب له في سرعة غريبة الفلاحون والمعدِمون بسبب الظروف القاسية التي كانوا يعيشون فيها، وقد وصف وِل ديورَانت هذه الحملةَ والمنضمِّين لها في قصة الحضارة بقوله: \"وانضوت جماعاتٌ لا عدد لها تحت لواء هذه الحرب مدفوعة إلى هذا بمغريات جمَّة، منها: أنَّ كل من يخرُّ صريعًا في الحرب قد وُعِد بأن تُغفَرَ له جميعُ ذنوبِه، وأُذِن لأرقَّاءِ الأرض أن يغادروا الأراضيَ التي كانوا مرتبطين بها، وتوسَّع البابا في سلطاته توسعًا جريئًا فأطلق سراحَ المسجونين، وخفَّف أحكامَ القتل عن المحكوم عليهم بها إذا خدموا طوالَ حياتهم في فلسطين، وانضمَّ آلافٌ من المتشردين إلى القائمين بهذه الرحلة المقدَّسة؛ ليخلِّصوا الأراضيَ التي وُلِدَ فيها المسيح ومات، منهم رجالٌ سَئِموا الفقر الذي كانوا يعانونه، ومنهم الأبناء الصغار الذين يرجون أن تكون لهم إقطاعياتٌ في تلك البلاد، ومنهم ذوو النفوس الضعيفة الذين يخشون أن يرميَهم الناسُ بالجبن وخور العزيمة. ونشطت الدعايةُ المُغرِضة والمألوفة في الحروب فأخذَت تؤكِّدُ الاضطهادَ الذي يلقاه المسيحيون في فلسطين، والمعاملاتِ الوحشيةَ التي يلقونَها على أيدي المسلمين، والأكاذيبَ عَمَّا في العقيدةِ الإسلاميَّةِ مِن زَيغٍ وضَلالٍ؛ فكان المسلمون يُوصَفون بأنَّهم يعبدون تمثالًا للنبيَّ محمد! وكان البابا إربان الثاني قد حدَّد لبدء رحيل الحملة شهر أغسطس من عام 1096، ولكِنَّ الفلاحين القلقين الذين كانوا أوائِلَ المتطوعين لم يستطيعوا الانتظارَ إلى هذا الموعد، فسار جحفلٌ منهم عدتُه نحو اثني عشر ألفًا لم يكن من بينهم إلَّا ثمانية من الفرسان, وبدؤوا رحلتهم من فرنسا شهر مارس بقيادة بطرس الناسك, وولتر المفلس. كانت هذه الجموعُ غير النظامية هي التي قامت بأكثر الاعتداءات على يهود ألمانيا ويوهيميا، وكان قادتُهم تعوزهم التجاربَ فلم يعدُّوا العُدَّة لإطعامهم، وقدَّرَ كثيرون من الزاحفين المسافةَ بأقَلَّ منِ قدرها الصحيحِ، وكانوا وهم يسيرون على ضفاف الرين والدانوب كلَّما عرجوا على بلدة من البلدان يسألُهم أبناؤهم في لهفةٍ: أليست هذه أورشليم؟ ولَمَّا فرغت أموالهم وعضَّهم الجوع، اضطروا إلى نَهبِ من في طريقهم من الحقول والبيوت، وسرعان ما أضافوا الفِسقَ إلى السَّلبِ والنهب، وقاومهم أهلُ البلاد مقاومةً عنيفة، وأغلَقَت بعضُ المدن أبوابَها في وجوهِهم، وأمرهم بعضُها أن يرحلوا عنها بلا مَهلٍ، ولما بلغوا آخِرَ الأمرِ مدينةَ القسطنطينية رحَّب بهم ألكسيوس، ولكنه لم يقدِّم لهم كفايتَهم من الطعام، فانطلقوا في أرباضِ المدينة، ونهبوا الكنائسَ والمنازلَ والقصورَ, وأراد ألكسيوس أن ينقِذَ عاصمته من هذه الجموع الفتَّاكة التي أهلكت الحرثَ والنسلَ، فأمدها بالسفُنِ التي عبَرَت بهم البسفور، وأرسل إليهم المؤنَ، وأمرهم بالانتظار حتى تصِلَ إليهم فِرَقٌ أخرى أحسَنُ سلاحًا وعتادًا. ولكنَّهم لم يستمعوا إلى هذه الأوامر، فزحفوا على نيقية، وخرجت عليهم قوةٌ منظَّمةٌ من الترك من مَهَرةِ الرماة، وأبادوا هذه الطليعةَ مِن فِرَق الحرب الصليبية الأولى، فلم تكَدْ تبقي على أحدٍ منهم. وكان ولتر المفلِس من بين القتلى. وأما بطرس الناسك فكانت نفسُه قد اشمأزَّت من هذه الجموع التي لا تخضع لقيادة، وعاد قبل المعركة إلى القسطنطينية، وأقام فيها سالِمًا حتى عام 1115م\"."},{"id":1748,"title":"استيلاء عسكر مصر على مدينة صور .","date":["العام الهجري :490","الشهر القمري : ربيع الأول","العام الميلادي :1097"],"text":"وصل عسكرٌ كثيرٌ من مصر إلى ثغر صور بساحل الشام، فحصرها وملَكَها، وسبب ذلك أنَّ الواليَ بها -ويعرف بكتيلة- أظهر العصيانَ على المستعلي الفاطمي العبيدي صاحب مصر، والخروجَ عن طاعته؛ فسيَّرَ إليه جيشًا، فحصروه بها وضيقوا عليه وعلى من معه من جنديٍّ وعامي، ثم افتتحها عَنوةً بالسيف، وقُتِل بها خلقٌ كثير، ونُهِب منها المال الجزيل، وأُخذ الوالي أسيرًا بغير أمان، وحُمِل إلى مصر فقُتِل بها."},{"id":1749,"title":"سقوط مدينة نيقية عاصمة دولة السلاجقة في أيدي الصليبيين .","date":["العام الهجري :490","الشهر القمري : رجب","العام الميلادي :1097"],"text":"كانت أوَّل حركة الفرنج لأخذ سواحل المسلمين وخروجهم إليها في هذه السنة، ساروا إليها، وأوَّل ما أخذوا نيقية، وهو أوَّلُ بلد فتحوه وأخذوه من المسلمين. ثمَّ فتحوا حصونَ الدروب شيئًا بعد شيء، ووصلوا إلى البارة، وجبل السَّمَّاق، وفامية، وكفر طاب، ونواحيها. واستباح الفرنج تلك النواحي، فكان هذا أولَ مظهر للفرنج بالشام، قَدِموا في بحر القسطنطينية في جمعٍ عظيم، وانزعجت الملوك والرعية، وعَظُم الخَطبُ، وقيل: \"إنَّ صاحب مصر لما رأى قوة السلجوقية واستيلاءَهم على الشام، كاتب الفرنجَ يدعوهم إلى المجيءِ إلى الشام ليملكوها، وكثُرَ النفيرُ على الفرنج من كل جهة\"؛ فأسفرت حملتهم الأولى عن قيام 4 إمارات صليبية، هي: إمارة الرها، وأنطاكية، وطرابلس، ومملكة بيت المقدس."},{"id":1750,"title":"احتلال الإفرنج مدينة أنطاكية .","date":["العام الهجري :491","الشهر القمري : جمادى الأولى","العام الميلادي :1098"],"text":"سار الفرنجةُ إلى أنطاكية ولم ينازلوها، وجاؤوا إلى المعرَّة فنصبوا عليها السَّلالم فنزلوا إليها فقَتَلوا من أهلها مائة ألف إنسان، وسَبَوا مثلها. ثمَّ دخلوا كفر طاب وفعلوا مثل ذلك، وعادوا إلى أنطاكية، وكان بها الأميرُ باغي سيان، وكان على الفرنج صنجيل، فحاصرها مدَّة، فنافق رجلٌ من أنطاكية يقال له فيروز,, وفتح لهم في الليل شبَّاكًا فدخلوا منه, قال أبو يعلى بن القلانسي: \"في جمادى الأولى ورد الخبر بأنَّ قومًا من أهل أنطاكية عملوا عليها وواطؤوا الفرنجَ على تسليمها إليهم لإساءة تقدَّمت من حاكم البلد في حقِّهم ومصادرته لهم، ووجدوا الفرصةَ في برج من الأبراج التي للبلد مما يلى الجبل، فباعوهم إيَّاه، وأصعدوا منه في السَّحَر وصاحوا، فانهزم ياغي سيان وخرج في خلقٍ عظيمٍ، فلم يسلم منهم شخصٌ! فسقط الأمير عن فرسه عند معرَّة مصرين، فحمله بعضُ أصحابه وأركبه فلم يَثبُت على ظهر الفرس وسقط ثانيًا فمات. وأمَّا أنطاكية فقتل منها وسُبي من الرجال والنساء والأطفال ما لا يدرِكُه حصر، وهرب إلى القلعة قدر ثلاثة آلاف تحصَّنوا بها\"."},{"id":1751,"title":"العبيديون الفاطميون يستولون على القدس من السلاجقة .","date":["العام الهجري :491","الشهر القمري : رمضان","العام الميلادي :1098"],"text":"خرج أمير الجيوش الأفضل بن بدر الجمالي في عساكِرَ جمة، ورحل من القاهرة في شعبان، وسار يريدُ أخذ بيت المقدِسِ من الأمير سكمان وإيلغازي بني أرتق، وكانا به في كثير من أصحابهما، فبعث إليهما يلتمِسُ منهما أن يسَلِّما البلدَ ولا يحوِجاه إلى الحرب، فأبيا عليه، فنزل على البلدِ ونصَب عليها من المجانيقَ نيِّفًا وأربعين منجنيقًا، وأقام عليها يحاصِرُها نيِّفًا وأربعين يومًا، حتى هدم جانبًا من السورِ، ولم يبقَ إلا أخذُها، فسيَّرَ إليه من بها ومكَّناه من البلد. فخلع على ولدي أرتق وأكرمهما، وأخلى عنهما، فمضيا بمن معهما. وملك البلدَ في شهر رمضان لخمسٍ بَقِين منه، وولَّى فيه من قبله."},{"id":1752,"title":"الصليبيون يستولون على معرة النعمان  .","date":["العام الهجري :491","الشهر القمري : ذي الحجة","العام الميلادي :1098"],"text":"كان أخذُ المعرَّة بعد أخذ أنطاكية. ولَمَّا وقع ذلك اجتمع ملوكُ الإسلام بالشام، وهم رضوان صاحِبُ حلب، وأخوه دقماق، وطغتكين صاحب دمشق، وصاحب الموصل، وسكمان بن أرتق صاحب ماردين، وأرسلان شاه صاحب سنجار, ولم ينهَضْ أمير الجيوش الأفضل بن بدر بإخراج عساكِرِ مِصرَ مع قدرته على المال والرجال, فاجتمع الجميعُ ونازلوا أنطاكية وضيَّقوا على الفرنجَ حتَّى أكلوا ورق الشجر. وكان صنجيل مقدَّم الفرنج عنده دهاءٌ ومكر، فرتَّب مع راهب حيلة وقال: اذهب فادفن هذه الحربةَ في مكان كذا، ثم قُلْ للفرنج بعد ذلك: رأيتُ المسيحَ في منامي وهو يقولُ: في المكان الفلاني حربةٌ مدفونة فاطلبوها، فإن وجدتموها فالظَّفَرُ لكم، وهي حربتي، فصوموا ثلاثةَ أيَّامٍ وصلُّوا وتصدَّقوا، ثم قام وهم معه إلى المكان ففتَّشوه فظهرت الحَربةُ؛ فصاحوا وصاموا وتصدَّقوا وخرجوا إلى المسلمين من الباب متفرِّقين من خمسة، وستة، ونحو ذلك، فقال المسلمون لكربوقا: ينبغي أن تقِفَ على الباب، فتقتُلَ كُلَّ من يخرج، فإنَّ أمْرَهم الآن وهم متفرقون سَهلٌ. فقال: لا تفعلوا، أمهلوهم حتى يتكامَلَ خروجُهم فنقتُلَهم! ولم يمكِنْ من معاجلتِهم، فقَتَل قومٌ من المسلمين جماعةً من الخارجين، فجاء إليهم هو بنفسه ومنعهم ونهاهم، فلما تكامل خروجُ الفرنج ولم يبق بأنطاكية أحدٌ منهم، ضربوا مصافًّا عظيمًا، فولى المسلمون منهزِمين؛ لِما عاملهم به كربوقا أولًا من الاستهانة بهم والإعراض عنهم، وثانيًا: مِن مَنعِهم عن قتل الفرنج، وتمت الهزيمةُ عليهم، ولم يضرِبْ أحدٌ منهم بسيف، ولا طعَنَ برُمحٍ، ولا رمى بسهمٍ! وآخِرُ من انهزم سقمان بن أرتق، وجناح الدولة؛ لأنهما كانا في الكمين، وانهزم كربوقا معهم. فلما رأى الفرنجُ ذلك ظنُّوه مكيدة؛ إذ لم يجرِ قِتالٌ يُنهزَمُ مِن مِثلِه! وخافوا أن يتبعوهم، وثبت جماعةٌ من المجاهدين، وقاتلوا حِسبةً، وطلبًا للشهادة، فقَتَل الفرنجُ منهم ألوفًا، وغَنِموا ما في العسكرِ مِن الأقوات والأموال والأثاث والدواب والأسلحة، فصلحت حالهم، وعادت إليهم قوَّتُهم، فلما فعل الفرنجُ بالمسلمين ما فعلوا ساروا إلى معرَّة النعمان، فنازلوها وحصروها، وقاتلهم أهلها قتالًا شديدًا، ورأى الفرنجُ منهم شدةً ونكاية، ولقُوا منهم الجِدَّ في حربهم، والاجتهادَ في قتالهم، فعملوا عند ذلك برجًا من خشب يوازي سورَ المدينة، ووقع القتالُ عليه، فلم يضُرَّ المسلمين ذلك، فلما كان الليل خاف قومٌ من المسلمين، وانتابهم الفشَلُ والهلع، وظنُّوا أنهم إذا تحصنوا ببعضِ الدور الكبار امتنعوا بها، فنزلوا من السورِ وأخلَوا الموضِعَ الذي كانوا يحفظونه، فرآهم طائفةٌ أخرى، ففعلوا كفِعلِهم، فخلا مكانُهم أيضًا من السور، ولم تزَلْ تتبَعُ طائفةٌ منهم التي تليها في النزولِ حتى خلا السور! فصعد الفرنجُ إليه على السلاليم، فلما علوه تحيَّر المسلمون، ودخلوا دورَهم، فوضع الفرنجُ فيهم السيفَ ثلاثة أيام، فقتلوا ما يزيد على مائة ألف، وسَبَوا السبيَ الكثير، وملكوه، وأقاموا أربعين يومًا! وساروا إلى عرقة فحصروها أربعةَ أشهر، ونقبوا سورَها عدةَ نُقوبٍ، فلم يقدروا عليها، وراسلهم منقذ صاحب شيزر، فصالحهم عليها، وساروا إلى حمص وحصروها فصالحهم صاحبها جناح الدولة، وخرجوا على طريق النواقير إلى عكا فلم يقدروا عليها. ثم كتب دقماق ورضوان والأمراء إلى الخليفة المستظهر العباسي يستنصِرونَه، فأخرج الخليفةُ أبا نصر ابن الموصلايا إلى السلطان بركيارق بن السلطان ملكشاه السلجوقي يستنجده. كلُّ ذلك وعساكر مصر لم تُهيَّأ للخروج!!"},{"id":1753,"title":"وفاة السلطان إبراهيم الغزنوي صاحب غزنة .","date":["العام الهجري :492","العام الميلادي :1098"],"text":"هو السلطانُ إبراهيم بن مسعود بن محمود بن سبكتكين صاحب غزنة وغيرها من بلاد الهند. وكان ملِكًا عادلًا مُنصِفًا منقادًا إلى الخيرِ، كثير الصدقات، كريمًا مجاهدًا، عاقلًا شُجاعًا حازِمًا، حسنَ السيرة، ذا رأيٍ ودهاء متين. كان يقول: \"لو كنتُ بعد وفاة جدي محمود لما ضعف مُلكُنا، ولكني الآن عاجِزٌ أن أستردَّ ما أُخِذَ منا من البلاد؛ لكثرة جيوشهم\". كان لا يبني لنفسه مكانًا حتى يبنيَ لله مسجدًا أو مدرسة. قال الفقيه أبو الحسن الطبري: \"أرسلني إليه بركيارق في رسالة، فرأيتُ في مملكته ما لا يتأتى وصفُه\"، وقيل: كان يكتب بخطِّ يده كل سنة مصحفًا يرسِلُه مع الصدقات إلى مكة، ومات وقد جاوز السبعين. وأقام مَلِكًا ثنتين وأربعين سنة، ولما توفي خلفه ابنُه علاء الدولة أبو سعيد مسعود الثالث زوج بنت السلطان ملكشاه."},{"id":1754,"title":"تفاقم أمر الباطنيين وقتلهم الأمراء والسلاطين والعوام .","date":["العام الهجري :492","العام الميلادي :1098"],"text":"تفاقم أمرُ الباطنيين كثيرًا حتى أصبحت لهم يدٌ طولى في اغتيال الأمراء والسلاطين، كما ساعد على ذلك كثرةُ الحروب بين السلاطين أنفُسِهم، فأصبح كثيرٌ منهم لا يفارقه درعُه وسلاحُه، وقد قتل الباطنيون نظامَ الملك، وأرسلان أرغون بن ألب أرسلان، والأمير برسق، وقتلوا الأميرَ بلكابك سرمز رئيس شحنة أصبهان، ضربه باطنيٌّ بسكين في خاصرته بأصبهان في دار السلطان محمد، وكان بلكابك كثير الاحتياط من الباطنية لا يفارقه لُبسُ الدرع ومن يمنع عنه، ففي ذلك اليوم الذي قُتِلَ فيه لم يلبس دِرعًا، ودخل دارَ السلطان في قِلَّةٍ، فقتله الباطنية، ومات من أولادِه في هذه الليلة جماعة، خرج من داره خمسُ جنائز في صبيحتها, وقتلوا غيرَهم من الأكابر في السلطنة، ثم كانوا سببًا لقتل مجد الملك البلاساني؛ فقد زعموا أنه هو الذي يحرِّضُهم على القتل، وقد ظهرت مقالةُ الباطنية بعد عودة السلطان بركيارق من حصاره لأخيه محمود، وأمه خاتون الجلالية، في أصبهان، وانتشرت قوتُهم بها، وكانوا متفرِّقين في المحالِّ مِن قَبلُ، فاجتمعوا وصاروا يسرقون من قدروا عليه من مخالفيهم ويقتلونَهم، فعلوا هذا بخلق كثير، وزاد الأمر، حتى إن الإنسان كان إذا تأخر عن بيته عن الوقت المعتاد تيقَّنوا قتْلَه، وقعدوا للعزاءِ به، فحَذِرَ الناسُ وصاروا لا ينفرِدُ أحد منهم."},{"id":1755,"title":"الصليبيون يستولون على بيت المقدس ويذبحون سبعين ألف مسلم .","date":["العام الهجري :492","الشهر القمري : شعبان","العام الميلادي :1099"],"text":"كان بيتُ المقدِسِ تحت حُكمِ الفاطميين، ولهم فيه رجلٌ نائِبٌ يُعرَفُ بافتخار الدولة، وبقِيَ فيه إلى الآن، فقصده الفرنجُ بعد أن حصروا عكَّا، فلم يقدِروا عليها، فلما وصلوا إليه حصروه نيفًا وأربعين يومًا، ونصبوا عليه برجين أحدهما من ناحية صهيون، وأحرقه المسلمون، وقتلوا كلَّ من به، فلمَّا فرغوا من إحراقه أتاهم المستغيثُ بأن المدينة قد مُلِكت من الجانب الآخر، وملكوها من جهة الشمال منه ضحوةَ نهار يوم الجمعة لسبعٍ بقين من شعبان، وركب الناسَ السيفُ، ولبث الفرنجُ في البلدة أسبوعًا يقتلون فيه المسلمين، واحتمى جماعةٌ من المسلمين بمحرابِ داود، فاعتصموا به، وقاتلوا فيه ثلاثةَ أيام، فبذل لهم الفرنجُ الأمانَ، فسَلَّموه إليهم، ووفى لهم الفرنج، وخرجوا ليلًا إلى عسقلان فأقاموا بها، وقَتَل الفرنجُ بالمسجد الأقصى ما يزيدُ على سبعين ألفًا، منهم جماعة كثيرة من أئمة المسلمين وعلمائهم، وعبَّادهم وزُهَّادهم! وغنموا منه ما لا يقع عليه الإحصاء، وجمعوا اليهودَ في الكنيسة وأحرقوها عليهم، وهدَموا المشاهِدَ, وورد المستنفِرون من الشام في رمضان إلى بغداد، ولكِنْ قَدَّر اللهُ أن اختلف السلاطين فتمكَّن الفرنج من البلاد. قال ابن الأثير في دخول الإفرنج بيت المقدس: \"سارت الإفرنجُ ومقَدَّمُهم كندفري في ألف ألف، بينهم خمسمائة ألف مقاتل، عملوا برجين من خشب مُطِلَّينِ على السور، فأحرق المسلمون البرجَ الذي كان بباب صهيون، وقتلوا من فيه. وأما الآخر فزحفوا به حتى ألصقوه بالسورِ وحكموا به على البلد، وكشفوا من كان بإزائهم، ورموا بالمجانيقِ والسهام رميةَ رجل واحد، فانهزم المسلمون من السور. وكان عدد خيلِهم ستةَ آلاف ومائة فارس، والرَّجَّالة ثمانية وأربعون ألفًا. ولم تزل دارَ الإسلام منذ فتحها عمر رضى الله عنه\". وكان الأفضلُ ابن أمير الجيوش القائد الفاطمي لَمَّا بلغه نزولهم على القدس تجهَّز وسار من مصر في عشرين ألفًا، فوصل إلى عسقلان ثاني يوم الفتح، ولم يعلم. وراسل الإفرنجَ. فأعادوا الرسولَ بالجوابِ إليه، ولم يعلم المصريون بشيءٍ، فبادروا السلاحَ والخيل، وأعجلتهم الإفرنجُ فهزموهم، وقتلوا منهم من قُتل، وغنموا خيامَهم بما فيها. ودخل الأفضلُ عسقلان وتمزَّق أصحابه. فحاصرته الإفرنجُ بعسقلان، فبذل لهم ذهبًا كثيرًا. وورد المستنفرون من الشام في رمضان إلى بغداد صحبة القاضي أبي سعد الهروي، فأوردوا في الديوان كلامًا أبكى العيون، وأوجع القلوب، وقاموا بالجامع يوم الجمعة فاستغاثوا، وبكَوا وأبكَوا، وذكر ما دهم المسلمين بذلك البلدِ الشريف المعظَّم مِن قَتلِ الرجال، وسبيِ الحريم والأولاد، ونَهْب الأموال؛ فلشدة ما أصابهم أفطَروا، فأمر الخليفة أن يسير القاضي أبو محمد الدامغاني، وأبو بكر الشاشي، وأبو القاسم الزنجاني، وأبو الوفا بن عقيل، وأبو سعد الحلواني، وأبو الحسين بن سماك، فساروا إلى حلوان، فبلغهم قتلُ مجد الملك البلاساني، فعادوا من غير بلوغ أرب، ولا قضاء حاجة. واختلف السلاطين، فتمكن الفرنجُ من البلاد، فقال أبو المظفر الآبيوردي في هذا المعنى أبياتًا، منها:مزجنا دماء بالدموع السواجمفلم يبقَ منا عرضة للمراحم وشرُّ سلاح المرء دمع يُفيضُهإذا الحربُ شَبَّت نارها بالصوارم فإيهًا، بني الإسلامِ، إنَّ وراءكموقائعَ يلحقن الذرى بالمناسم أتهويمة في ظل أمن وغبطةوعيش كنوار الخميلة ناعموكيف تنام العينُ ملءَ جفونهاعلى هفوات أيقظت كلَّ نائم وإخوانكم بالشام يضحى مقيلهمظهور المذاكي أو بطون القشاعم تسومهم الرومُ الهوانَ وأنتمتجرُّون ذيل الخفض فِعلَ المُسالِم وكم من دماء قد أبيحت ومن دميتوارى حياء حسنها بالمعاصم بحيث السيوف البيض محمرة الظبىوسمر العوالي داميات اللهاذم وبين اختلاس الطعن والضربوقفة تظل لها الولدان شيبَ القوادم وتلك حروب من يغِبْ عن غمارهاليسلَمَ يقرَعْ بعدها سِنَّ نادم سللن بأيدي المشركين قواضبًاستغمد منهم في الطلى والجماجميكاد لهن المستجن بطيبة ينادي بأعلى الصوت يا آل هاشم\"."},{"id":1756,"title":"حرب العبيديين الفاطميين للصليبيين في عسقلان  .","date":["العام الهجري :492","الشهر القمري : رمضان","العام الميلادي :1099"],"text":"كانت وقعةٌ بين العساكر المصرية والفرنج، قيل في سببِها: إن المصريين لما بلغهم ما تمَّ على أهل القدس جمع الأفضل أميرُ الجيوش بن بدر الجمالي العساكِرَ وحَشَد، وسار إلى عسقلان، وأرسل إلى الفرنج ينكِرُ عليهم ما فعلوا، ويتهدَّدهم، فأعادوا الرسولَ بالجواب ورحلوا على إثرِه، وطلعوا على المصريين عَقيبَ وصول الرسول، ولم يكُنْ عند المصريين خبَرٌ من وصولهم، ولا من حركتِهم، ولم يكونوا على أُهْبةِ القتال، فنادَوا إلى ركوب خيولهم، ولَبِسوا أسلحتَهم، وأعجلهم الفرنجُ فهزموهم، وقتلوا منهم من قُتِل، وغنموا ما في المعسكر من مالٍ وسلاح وغير ذلك، وانهزم الأفضلُ، فدخل عسقلان، ومضى جماعةٌ من المنهزمين فاستتروا بشجرِ الجميز، فأحرق الفرنجُ بعضَ الشجر، حتى هلك من فيه، وقتلوا من خرج منه، وعاد الأفضلُ في خواصِّه إلى مصر، ونازل الفرنج عسقلان، وضايقوها، فبذل لهم أهلُها قطيعة اثني عشر ألف دينار، وقيل: عشرين ألف دينار، ثم عادوا إلى القدس."},{"id":1757,"title":"ابتداء أمر السلطان محمد بن ملكشاه واقتتاله مع أخيه بركيارق .","date":["العام الهجري :492","الشهر القمري : ذي الحجة","العام الميلادي :1099"],"text":"كان ابتداءُ أمر السلطان محمد بن ملكشاه، وهو أخو السلطان سنجر لأبيه وأمه، واستفحل إلى أن خُطِب له ببغداد في ذي الحجة من هذه السنة، ثمَّ في صفر من السنة التالية دخل السلطان بركيارق بن ملكشاه أخو السلطان محمد إلى بغداد، ونزل بدار الملك، وأعيدت له الخُطبة، وقُطِعت خُطبة أخيه محمد، ثم سار فالتقى هو وأخوه محمد بمكانٍ قريب من همدان، فهزمه أخوه محمد ونجا هو بنفسِه في خمسين فارسًا، ولَمَّا جرى ما جرى في هذه الوقعة ضَعُف أمر السلطان بركيارق، ثم تراجع إليه جيشُه وانضاف إليه الأميرُ داود في عشرين ألفًا، فالتقى هو وأخوه مع أخيه سنجر فهزمهم سنجر أيضًا، وهرب بركيارق في شرذمةٍ قليلة، وأُسِر الأمير داود فقتله الأميرُ برغش أحد أمراء سنجر، فضَعُف بركيارق وتفرَّقت عنه رجاله، وقُطِعَت خطبته من بغداد في رابع عشر رجب وأعيدت الخُطبة للسلطان محمد، ثم اصطلح الأخوان على أن يحتَفِظَ بركيارق بأصبهان وفارس وعراق العجم، ويكون لأخيه محمد أذربيجان وأرمينية وديار بكر."},{"id":1758,"title":"المرابطون بالأندلس يستردون مدينة بلنسية .","date":["العام الهجري :493","العام الميلادي :1099"],"text":"كانت بلنسية قد سقطت بيد النصراني إلكمبيادور بعد حصرها عام 487، وطلب أهلُها في حينها النزولَ بالأمان، فنقض الفرنجُ الأمانَ فورَ دُخولِهم وقتلوا وحرقوا، وبَقِيَت بيَدِهم إلى هذا العام؛ حيث قام المرابطون بحصارها بقيادة محمد بن تاشفين ومعه القائد المزدلي اللمتوني، ثم في فترة الحصار هلك إلكمبيادور وتولَّت زوجته شيمانه الدفاعَ عن المدينة، ولكِنَّ الحصار الذي دام سبعة أشهر اضطرها لتسليم المدينة؛ حيث انتشر الجوعُ وبدأ الموتُ، فخرجت من المدينة بعد أن أمرت بحرق المدينة بكاملها إظهارًا لخُبثِها وحنقِها على المسلمين، فدخلها المرابطون فوجدوها دمارًا."},{"id":1759,"title":"انتصار كمشكين السلجوقي على الصليبيين قرب ملطية .","date":["العام الهجري :493","العام الميلادي :1099"],"text":"لقي كمشتكين بن الدانشمند طايلو السلجوقي بن صاحب ملطية وسيواس - وإنما قيل له ابن الدانشمند -معنى الدانشمند المعلم- لأن أباه كان معلمًا للتركمان وتقلبت به الأحوال، حتى مَلضك، وهو صاحِبُ ملطية وسيواس وغيرهما- بيمند الفرنجي، وهو من مقدَّمي الفرنج، قريبَ ملطية، وكان صاحبُها قد كاتبه، واستقدمه إليه، فورد عليه في خمسةِ آلاف، فلقيهم ابن الدانشمند، فانهزم بيمند وأُسِر. ثم وصل من البحر سبعةُ قمامصة -كبار القساوسة- من الفرنج، وأرادوا تخليص بيمند، فأتوا إلى قلعة تسمى أنكورية، فأخذوها وقَتَلوا من بها من المسلمين، وساروا إلى قلعة أخرى فيها إسماعيل بن الدانشمند، وحصروها، فجمع ابن الدانشمند جمعًا كثيرًا، ولقي الفرنجَ، وجعل له كمينًا، وقاتلهم، وخرج الكمينُ عليهم، فلم يُفلتْ أحد من الفرنج -وكانوا ثلاثمائة ألف- غيرُ ثلاثة آلاف، هربوا ليلًا وأفلتوا مجروحين. وسار ابن الدانشمند إلى ملطية، فملكها وأسر صاحبها، ثم خرج إليه عسكر الفرنج من أنطاكية، فلقِيَهم وكسرهم، وكانت هذه الوقائع في شهور قريبة."},{"id":1760,"title":"القتال بين السلطانين بركيارق ومحمد وإعادة الخطبة لمحمد ببغداد .","date":["العام الهجري :493","الشهر القمري : رجب","العام الميلادي :1100"],"text":"سار بركيارق من بغداد على شهرزور، فأقام بها ثلاثةَ أيام، والتحق به عالَمٌ كثير من التركمان وغيرهم، فسار نحو أخيه السلطان محمد ليحاربَه، فكاتبه رئيس همذان ليسير إليها ويأخُذَ أقطاع الأمراء الذين مع أخيه، فلم يفعل، وسار نحو أخيه، فوقعت الحرب بينهما رابع رجب، وهو المصافُّ الأول بين بركيارق وأخيه السلطان محمد بإسبيذروذ -النهر الأبيض- وهو على عدَّةِ فراسِخَ من همذان. وكان مع محمد نحو عشرين ألف مقاتل، وكان محمد في القلب، ومعه الأمير سرمز، وعلى ميمنته أميرٌ آخُر، وابنه إباز، على ميسرته مؤيد الملك، والنظامية، وكان السلطانُ بركيارق في القلبِ، ووزيره الأعز أبو المحاسن، وعلى ميمنته كوهرائين وعز الدولة بن صدقة بن مزيد، وسرخاب بن بدر، وعلى ميسرته كربوقا وغيره، فحمل كوهرائين من ميمنة بركيارق على ميسرة محمد، وبها مؤيَّد الملك بن نظام الملك، والنظامية، فانهزموا، ودخل عسكرُ بركيارق في خيامِهم، فنهبوهم، وحملت ميمنةُ محمد على ميسرة بركيارق، فانهزمت الميسرةُ، وانضافت ميمنةُ محمد إليه في القلب على بركيارق ومن معه، فانهزم بركيارق، ووقف محمد مكانه، وعاد كوهرائين من طلب المنهزمين الذين انهزموا بين يديه، وكبا به فرسُه، فأتاه خراسانيٌّ فقتَلَه، وأخذ رأسَه، وتفرَّقت عساكر بركيارق، وبقي في خمسين فارسًا, وأما وزيره الأعز أبو المحاسن فإنه أُخذ أسيرًا، فأكرمه مؤيد الملك، ونصب له خِيَمًا وخركاة، وحمل إليه الفرش والكسوة، وضمَّنه عمادة بغداد، وأعاده إليها، وأمره بالمخاطبة في إعادة الخطبة للسلطان محمد ببغداد، فلما وصل إليها خاطب في ذلك، فأجيب إليه وخطب له يومَ الجمعة رابع عشر رجب."},{"id":1761,"title":"استفحال أمر الباطنية الحشاشين .","date":["العام الهجري :494","العام الميلادي :1100"],"text":"كثُرَت الباطنية بالعراق والجبل، وزعيمُهم الحسن بن صباح، فملكوا القلاعَ، وقطعوا السبيل، وأهمَّ النَّاسَ شأنُهم، واستفحل أمرُهم لاشتغال أولاد ملكشاه بالنزاع على السلطة والاقتتال من أجلها."},{"id":1762,"title":"الصليبيون يستولون على حيفا ويافا ويحاصرون مدينة عكا .","date":["العام الهجري :494","العام الميلادي :1100"],"text":"سار كندفري ملك الفرنج بالشام -وهو صاحب بيت المقدس- إلى مدينة عكا بساحل الشام، فحصرها فأصابه سهم فقتله، وكان قد عمَرَ مدينة يافا وسلَّمَها إلى قمص -كبير القساوسة- من الفرنج اسمه طنكري، فلما قُتِل كندفري سار أخوه بغدوين إلى بيت المقدس في خمسمائة فارس وراجل، فبلغ الملك دقاق- صاحب دمشق- خبره، فنهض إليه في عسكره، ومعه الأمير جناح الدولة في جموعه، فقاتله، فنُصِر على الفرنج، ومَلَك الفرنجُ مدينةَ سروج من بلاد الجزيرة، وسببُ ذلك أن الفرنج كانوا قد ملكوا مدينة الرها بمكاتبة من أهلِها؛ لأن أكثرَهم أرمن، وليس بها من المسلمين إلا القليل، فلما كان الآن جمع سقمان بن أرتق التركماني بسروج جمعًا كثيرًا من التركمان، وزحف إليهم، فلَقُوه وقاتلوه، فهزموه في ربيع الأول. فلما تمَّت الهزيمة على المسلمين سار الفرنجُ إلى سروج، فحصروها وتسلَّموها، وقتلوا كثيرًا من أهلِها وسَبَوا حريمَهم، ونهَبوا أموالهم، ولم يسلَمْ إلَّا من مضى منهَزِمًا، وملك الفرنجُ مدينة حيفا، وهي بالقربِ مِن عكا على ساحل البحر، ملكوها عَنوةً، وملكوا أرسوف بالأمان، وأخرجوا أهلَها منها، وفي رجب ملكوا مدينة قيسارية بالسيف، وقتلوا أهلَها، ونهبوا ما فيها."},{"id":1763,"title":"العالم الإدريسي يزور ملك صقلية ويرسم الأرض على كرة من فضة .","date":["العام الهجري :494","العام الميلادي :1100"],"text":"اختار الإدريسيُّ الانتقالَ إلى صقلية بعد سقوط الحكومة الإسلامية؛ لأنَّ الملك النورماني في ذلك الوقت روجر الثاني كان محبًّا للمعرفة، شرح الإدريسي لروجر موقعَ الأرض في الفضاء مستخدِمًا في ذلك البيضةَ لتمثيل الأرض، شبَّهَ الإدريسي الأرضَ بصفار البيضة المحاط ببياضها تمامًا كما تهيم الأرضُ في السماء محاطة بالمجرَّات. أمر الملك الصقلي روجر الثاني له بالمال لينقُشَ خارطة العالم والمعروف باسم لوح الترسيم على دائرة من الفضة تزن 400 رطل رومي في كل رطل 112 درهمًا. ويُعرَف لوح الترسيم أيضًا عند العرب بخريطة الإدريسي، ويقال: إنها أول خريطة سليمة (أي صحيحة) نعرف عنها. ساعده في ذلك رسَّام رافقه في كل رحلاته الاستكشافية المموَّلة من روجر الثاني للحصول على معلومات جغرافية."},{"id":1764,"title":"السلطان بركيارق يشن حملة على الباطنية الإسماعيلية ويبيح قتلهم .","date":["العام الهجري :494","الشهر القمري : شعبان","العام الميلادي :1101"],"text":"في هذه السَّنة قَتَل السلطان بركيارق خلقًا من الباطنية ممن تحقَّق مذهبَه، ومن اتُّهِم به، فبلغت عدتُهم ثمانمائة ونيِّفًا، ووقع التتبُّعُ لأموال من قُتِل منهم، فوُجِد لأحدهم سبعون بيتًا من الزوالي المحفور، وكُتب بذلك كتابٌ إلى الخليفة، فتقدَّم بالقبض على قومٍ يُظَنُّ فيهم ذلك المذهَبُ، ولم يتجاسر أحدٌ أن يشفع في أحدٍ لئلَّا يُظَنَّ مَيلُه إلى ذلك المذهب، وزاد تتبُّعُ العوام لكل من أرادوا، وصار كلُّ من في نفسه شيءٌ من إنسانٍ يرميه بهذا المذهب، فيُقصَد ويُنهَب حتى حُسِم هذا الأمر فانحسم في أيام السلطان ملكشاه، فإنه اجتمع منهم ثمانية عشر رجلًا، فصلَّوا صلاة العيد في ساوة، ففَطِنَ بهم الشحنة فأخذهم وحبَسَهم، ثم سُئِلَ فيهم فأطلقهم، فهذا أول اجتماع كان لهم، ثمَّ إنهم دَعَوا مؤذِّنًا من أهل ساوة كان مقيمًا بأصبهان، فلم يُجِبْهم إلى دعوتهم، فخافوه أن ينمَّ عليهم، فقتلوه، فهو أوَّلُ قتيل لهم، وأوَّلُ دم أراقوه، فبلغ خبَرُه إلى نظام الملك، فأمر بأخذِ من يُتَّهَمَ بقتله، فوقعت التهمةُ على نجارٍ اسمه طاهر، فقُتِل ومُثِّل به، وجَرُّوا برِجْلِه في الأسواق، فهو أولُ قتيل منهم، وأولُ موضع غُلِبوا عليه وتحصَّنوا به بلدٌ عند قاين، كان متقدَّمُه على مذهبهم، فاجتمعوا عنده، وقَوُوا به، فتجرد للانتقام منهم أبو القاسم مسعود بن محمد الخجندي، الفقيه الشافعي، وجمع الجمَّ الغفير بالأسلحة، وأمر بحفرِ أخاديد، وأوقد فيها النيرانَ، وجعل العامةُ يأتون بالباطنية أفواجًا ومنفَرِدين، فيُلقَون في النار، وجعلوا إنسانًا على أخاديد النيران وسمَّوه مالكًا، فقتلوا منهم خلقًا كثيرًا، وكان السببُ في قتل بركيارق الباطنيةَ أنَّه لما اشتد أمرُ الباطنية، وقَوِيت شوكتهم، وكثُرَ عددهم، صار بينهم وبين أعدائهم إحَنٌ، فلما قتلوا جماعةً من الأمراء الأكابر، وكان أكثَرُ من قتلوا من هو في طاعة محمد، مخالِفٌ للسلطان بركيارق، مثل شحنة أصبهان سرمز، وأرغش، وكمش النظاميين، وصهره، وغيرهم، نَسَب أعداءُ بركيارق ذلك إليه، واتهموه بالميلِ إليهم. فلما ظفر السلطان بركيارق، وهزم أخاه السلطان محمدًا، وقتل مؤيد الملك وزيره، انبسط جماعةٌ منهم في العسكر، واستغووا كثيرًا منهم، وأدخلوهم في مذهبهم، وكادوا يظهرون بالكثرة والقوَّة، وحصل بالعسكر منهم طائفة من وجوههم، وزاد أمرهم، فصاروا يتهددون من لا يوافقهم بالقتل، فصار يخافهم من يخالِفُهم، حتى إنهم لم يتجاسَرْ أحد منهم، لا أمير ولا متقدِّم، على الخروج من منزله حاسِرًا، بل يلبس تحت ثيابه درعًا، وأشاروا على السلطان أن يفتك بهم قبل أن يعجِزَ عن تلافي أمرهم، وأعلموه ما يتَّهِمُه الناس به من الميل إلى مذهبهم، حتى إن عسكر أخيه السلطان محمد يشنِّعون بذلك، وكانوا في القتال يكبرون عليهم، ويقولون: يا باطنية. فاجتمعت هذه البواعِثُ كلها فأذن السلطانُ في قتلهم، والفتكِ بهم، وركب هو والعسكرُ معه، وطلبوهم وأخذوا جماعةً من خيامهم ولم يُفلِتْ منهم إلا من لم يُعرَف، وكان ممن اتُّهِم بأنه مقدَّمُهم الأمير محمد بن دشمنزيار بن علاء الدولة أبي جعفر بن كاكويه، صاحب يزد، فهرب وسار يومه وليلته، فلما كان اليوم الثاني وجَدَّ في العسكر قد ضَلَّ الطريق ولا يَشعُر، فقُتِل، ونُهِبَت خيامه، فوُجِد عنده السلاح المعَدِّ، وأخرج الجماعة المتهمون إلى الميدان فقُتِلوا، وقُتِل منهم جماعة برآء لم يكونوا منهم سعى بهم أعداؤهم، وكتب إلى بغداد بالقبض على أبي إبراهيم الأسداباذي الذي كان قد وصل إليها رسولًا من بركيارق ليأخذ مال مؤيد الملك، وكان من أعيانهم ورؤوسهم، فأُخذ وحُبِس، فلما أرادوا قتله قال: هَبُوا أنكم قتلتموني، أتقدرون على قَتْلِ من بالقلاع والمدُن؟ فقُتِل، ولم يُصَلِّ عليه أحد، وألقِيَ خارج السور، واتُّهِم أيضًا الكيا الهرَّاسي، المدَرِّس بالنظامية بأنَّه باطنيٌّ، ونُقِل ذلك عنه إلى السلطان محمد، فأمر بالقبض عليه، فأرسل المستظهر بالله من استخلصه، وشَهِدَ له بصحة الاعتقاد، وعلوِّ الدرجةِ في العلم، فأُطلِقَ."},{"id":1765,"title":"محاولة وزير الفاطميين الأفضل بن أمير الجيوش استرداد القدس .","date":["العام الهجري :494","الشهر القمري : رمضان","العام الميلادي :1101"],"text":"جهَّز الأفضلُ بن أمير الجيوش عسكرًا كثيفًا لغزو الفرنج، فساروا إلى عسقلان ووصلوا إليها في أول رمضان، فأقاموا بها إلى ذي الحِجَّة؛ فنهض إليهم من الفرنج ألفُ فارس وعشرة آلاف راجل، فخرج إليهم المسلمون وحاربوهم. فكانت بين الفريقين عدةُ وقائع آلت إلى كسر الميمنة والميسرة وثبات سعد الدولة الطواشي -مقدَّم العسكر- في القلب، وقاتل قتالًا شديدًا، فتراجع المسلمون عند ثبات المذكور وقاتلوا الفرنج حتى هزموهم إلى يافا، وقتلوا منهم خلقًا كثيرًا وأسروا الكثير. وقُتِل كندفري ملك الفرنج بالقدس، فجاء أخوه بغدوين من القدس وملك بعده، وسار بالفرنج إلى أرسوف."},{"id":1766,"title":"الصليبيون يحاصرون طرابلس .","date":["العام الهجري :495","العام الميلادي :1101"],"text":"كان صنجيل الفرنجي قد لقي قلج أرسلان بن سليمان بن قتلمش، صاحب قونية، وكان صنجيل في مائة ألف مقاتل، وكان قلج أرسلان في عدد قليل، فاقتتلوا، فانهزم الفرنجُ وقُتِلَ منهم وأُسِرَ الكثير، وعاد قلج أرسلان بالغنائم والظَّفَر الذي لم يحسَبْه. ومضى صنجيل مهزومًا في ثلاثمائة، فوصل إلى الشام، فأرسل فخر الملك بن عمار، صاحب طرابلس، إلى الأمير ياخز، خليفة جناح الدولة على حمص، يقول: من الصواب أن يُعاجل صنجيل إذ هو في هذه العدة القريبة، فخرج الأمير ياخز بنفسه، وسيَّرَ دقاق ألفي مقاتل، وأتتهم الأمداد من طرابلس، فاجتمعوا على باب طرابلس، وصافُّوا صنجيل هناك، فأخرج مائةً من عسكره إلى أهل طرابلس، ومائة إلى عسكر دمشق، وخمسين إلى عسكر حمص، وبقي هو في خمسين. فأما عسكر حمص فإنهم انكسروا عند المشاهدة، وولَّوا منهزمين، وتبعهم عسكر دمشق. وأما أهل طرابلس فإنهم قاتلوا المائة الذين قاتلوهم، فلما شاهد ذلك صنجيل حمل في المائتين الباقيتين، فكسروا أهل طرابلس، وقتلوا منهم الكثير، ونازل صنجيل طرابلس وحصرها. وأتاه أهلُ الجبل فأعانوه على حصارها، وكذلك أهل السواد، وأكثرهم نصارى، فقاتل مَن بها أشدَّ قتال، فقتل من الفرنج ثلاثمائة، ثم إنَّه هادنهم على مال وخيل، فرحل عنهم إلى مدينة أنطرسوس، وهي من أعمال طرابلس، فحصرها وفتحها وقتل مَن بها من المسلمين، ورحل إلى حصن الطوبان، وهو يقارب رفنية، ومُقَدَّمُه يقال له ابن العريض، فقاتلهم، فنُصِر عليه أهل الحصن، وأسر ابن العريض منه فارسًا من أكابر فرسانه، فبذل صنجيل في فدائه عشرة آلاف دينار وألف أسير، فلم يجِبْه ابن العريض إلى ذلك."},{"id":1767,"title":"قيام الدولة الأرتقية .","date":["العام الهجري :495","العام الميلادي :1101"],"text":"تنتسب هذه الدولة إلى زعيم عشيرة من التركمان يُدعى أرتق بن أكسب جد الملوك الأرتقية.كان أميرًا شُجاعًا مُطاعًا، تغلَّب على حلوان والجبل، وكثُرَ أتباعه، فسار إلى الشام. وملك ولدُه سقمان بيتَ المقدس. وذريتُه هم ملوك ماردين من مائتي سنة, وكان أرتق قد التحق عام 449 بخدمة السلطان السلجوقي تتش بن ألب أرسلان صاحب بلاد الشام فأقطعه القدسَ وما حولها. ولما توفِّيَ أرتق سنة 484خلفه ولداه معين الدين سقمان, ونجم الدين إيلغازي. وفي سنة 491 احتلَّ الفاطميون القدس فأخرجوهما منها, فتوجَّها بقومهما من التركمان إلى الجزيرة الفراتية فتملَّك معين الدين سقمان ديار بكر (آمد) وتملَّك نجم الدين إيلغازي (ماردين) وأقام كلٌّ منهما فيما تملَّك سنة 495 دولة أرتقية. وفي سنة 511 حاصر الصليبيون مدينة حلب فاستنجد أهلُها بنجم الدين إيلغازي فأنجدهم وقاتل الصليبيين في معركة جرت في (سهل بلاط) سنة 513، وأسر زعيمهم روجيه ده سالرنو أمير أنطاكية، وتملك نجم الدين إيلغازي حلب, وتعاقب أبناؤه عليها إلى أن استولى عليها عماد الدين زنكي سنة 521 وأقام فيها دولة أتابكية."},{"id":1768,"title":"وفاة حاكم مصر العبيدي المستعلي بالله وولاية ابنه المنصور .","date":["العام الهجري :495","الشهر القمري : صفر","العام الميلادي :1101"],"text":"هو المستعلي بالله أبو القاسم أحمد بن معد المستنصر بالله الفاطمي العبيدي، حاكم مصر، حكمها مدة سبع سنين وقريبًا من الشهرين، وكان المدبِّر لدولته أمير الجيوش الأفضل بن بدر الجمالي، ولما توفِّيَ وَلِيَ بعده ابنُه أبو علي المنصور، وبويع له في اليوم الذي مات فيه أبوه، وله خمس سنين وشهر وأربعة أيام، ولُقِّب الآمر بأحكام الله، ولم يقدر يركبُ وحده على الفرس لصِغَرِ سنه، وقام بتدبير دولته الأفضل أحسن قيام، ولم يزل كذلك يدبِّرُ الأمرَ إلى أن قُتِلَ الآمر سنة خمس عشرة وخمسمائة."},{"id":1769,"title":"فتنة بين شحنة بغداد إيلغازي والعامة .","date":["العام الهجري :495","الشهر القمري : شعبان","العام الميلادي :1102"],"text":"كانت فتنةٌ كبيرة بين شحنة بغداد -شحنة: أي القَيِّم لضبط البلد- إيلغازي بن أرتق، وبين العامة. أتى جنديٌّ من أصحابه ملاحًا ليعبر به وبجماعة، فتأخَّر فرماه بنشَّابه فقتله، فأخذت العامة القاتِلَ، فجَرُّوه إلى باب النوبي، فلقيهم ابن إيلغازي فخلَّصه، فرجمتهم العامةُ. فتألم إيلغازي وعبر بأصحابه إلى محلة الملاحين فنهبوها، وانتشرت الشطَّار، فعاثوا هناك وبدعوا، وغرق جماعة، وقُتِل آخرون. وجمع إيلغازي التركمان، وأراد نهبَ الجانب الغربي من بغداد، ثم لطف اللهُ تعالى."},{"id":1770,"title":"المصريون بقيادة شرف المعالي يهزمون الصليبيين قرب الرملة .","date":["العام الهجري :496","العام الميلادي :1102"],"text":"كان الأفضلُ أمير الجيوش بمصر قد أنفذ مملوكًا لأبيه -لَقَبه سعد الدولة، ويعرف بالطواشي- إلى الشام لحرب الفرنج، فلقِيَهم بين الرملة ويافا، ومقَدَّم الفرنج يعرف ببغدوين، تصافوا واقتتلوا، فحملت الفرنج حملةً صادقة، فانهزم المسلمون، فلما كانت هذه الوقعة انهزم سعد الدولة، فتردى به فرسه فسقط ميتًا، وملك الفرنجُ خيمتَه وجميعَ ما للمسلمين. فأرسل الأفضلُ بعده ابنَه شرف المعالي في جمعٍ كثير، فالتقوا هم والفرنج بالقرب من الرملة، فانهزم الفرنج، وقُتِل منهم مقتلةٌ عظيمة، وعاد من سلم منهم مغلولين، فلما رأى بغدوين شدة الأمر، وخاف القتل والأسر؛ ألقى نفسه في الحشيش واختفى فيه، فلما أبعد المسلمون خرج منه إلى الرملة. وسار شرف المعالي بن الأفضل من المعركة، ونزل على قصر بالرملة، وبه سبعمائة من أعيان الفرنج، وفيهم بغدوين، فخرج متخفيًا إلى يافا، وقاتل ابن الأفضل من بقي من الفرنج خمسة عشر يومًا، ثم أخذهم، فقتل منهم أربعمائة صبرًا، وأسر ثلاثمائة إلى مصر. ثم اختلف أصحابُه في مقصدهم، فقال قوم: نقصِدُ بيت المقدس ونتملَّكُه، وقال قوم: نقصد يافا ونملكها، فبينما هم في هذا الاختلاف إذ وصل إلى الفرنج خلق كثير في البحر قاصدين زيارة البيت المقدس، فندبهم بغدوين للغزوِ معه، فساروا إلى عسقلان، وبها شرف المعالي فلم يكن يقوى بحربهم، فلطف الله بالمسلمين، فرأى الفرنجُ البحرية حصانة عسقلان، وخافوا البيات، فرحلوا إلى يافا، وعاد ولد الأفضل إلى أبيه، فسيَّرَ رجلًا يقال له تاج العجم في البر، وهو من أكبر مماليك أبيه، وجهز معه أربعة آلاف فارس، وسيَّر في البحر رجلًا يقال له القاضي ابن قادوس، في الأسطول على يافا، ونزل تاج العجم على عسقلان، فاستدعاه ابن قادوس إليه ليتفقا على حرب الفرنج، فقال تاج العجم: ما يمكنني أن أنزل إليك إلا بأمر الأفضل، ولم يحضر عنده ولا أعانه، فأرسل ابن قادوس إلى قاضي عسقلان وشهودها وأعيانها، وأخذ خطوطهم بأنه أقام على يافا عشرين يومًا، واستدعى تاج العجم فلم يأتِه ولا أرسل رجلًا، فلما وقف الأفضل على الحال أرسل من قبض على تاج العجم وأرسل رجلًا لقبه جمال الملك، فأسكنه عسقلان، وجعله متقَدِّم العساكِرِ الشامية."},{"id":1771,"title":"يوسف بن تاشفين يعود إلى قرطبة للمرة الرابعة .","date":["العام الهجري :496","العام الميلادي :1102"],"text":"عاد يوسف بن تاشفين إلى قرطبة للمرة الرابعة، وقاتل ألفونسو وانتهت المعركة بانهزام ألفونسو، ثم قام يوسف بن تاشفين بأخذ البيعة لابنه علي فجعله ملِكًا على قرطبة، وعاد هو إلى مراكش."},{"id":1772,"title":"عودة الاقتتال بين الأخوين السلطان محمد بن ملكشاه وبركيارق .","date":["العام الهجري :496","الشهر القمري : جمادى الآخرة","العام الميلادي :1103"],"text":"كان الخليفة العباسي قد ولَّى السلطان محمدًا المُلكَ، واستنابه في جميع ما يتعلَّقُ بأمر الخلافة دون ما أغلق عليه الخليفةُ بابَه، ثم خرج السلطانُ محمد ومعه أخوه سنجر قاصدًا قتال أخيه بركيارق، وفي هذه السنة ثامن جمادى الآخرة كان المصاف الخامس بين السلطان بركيارق والسلطان محمد, فأقبل بركيارق في خمسة عشر ألفًا فحاصره في أصبهان وعددُ أصحاب محمد قليل، فضاقت الميرةُ على محمد، فقسط على أهل البلد على وجه القرض فأخذ مالًا عظيمًا، ثم عاود عسكره الشغب، فأعاد التقسيطَ بالظلم والعذاب، وبلغ الخبز عشرةَ أَمْناء بدينار، ورطل لحم بربع دينار، ومائة منًا تبنًا بأربعة دنانير، وقُلِعت أخشاب المساجد وأبواب الدكاكين، هذا والقتالُ على أبواب البلد، وينال صاحِبُ محمد يحرق الناسَ بالمصادرة، وعسكر بركيارق في رُخصٍ كثير، فاجتمع على أهل أصبهان الخوف والجوع، ونقص من الأموال والأنفس والثمرات، ثم خرج السلطان محمد من أصبهان هاربًا فأرسل أخوه في أثره مملوكَه إياز، فلم يتمكَّن من القبض عليه، ونجا بنفسه سالمًا، وعاد إياز فأخبر بركيارق فلم يَسُرَّه سلامة أخيه, وفي يوم الاثنين ثالث عشرين ربيع الأول أعيدت الخطبة لبركيارق فخطب في الديوان، ثم تقدم إلى الخطباء في السابع والعشرين من هذا الشهر بأن يقتصروا على ذِكرِ الخليفة، ولا يذكروا أحدًا من السلاطين المختلفين, ثم التقى السلطان محمد وبركيارق في يوم الأربعاء في جمادي الآخرة، فوقعت الحربُ بينهما فانهزم محمد إلى بعض بلاد أرمينية على أربعين فرسخًا من الوقعة، ثم سار منها إلى خلاط ثم عاد إلى تبريز، ومضى بركيارق إلى زنجان، ثم في العام التالي صار الصلحُ بينهما بعدما تحوَّل الأمن إلى خوفٍ، وبدا السلبُ والنهب والقتلُ والضعفُ."},{"id":1773,"title":"احتلال الفرنج جبيل وعكا من الشام .","date":["العام الهجري :497","العام الميلادي :1103"],"text":"وصلت مراكب من بلاد الفرنج إلى مدينة اللاذقية فيها التجار والأجناد والحُجَّاج، وغير ذلك، واستعان بهم صنجيل الفرنجي على حصار طرابلس، فحصروها معه برًّا وبحرًا، وضايقوها وقاتلوها أيامًا، فلم يروا فيها مطمعًا، فرحلوا عنها إلى مدينة جبيل، فحصروها، وقاتلوا عليها قتالًا شديدًا. فلما رأى أهلُها عجزهم عن الفرنج أخذوا أمانًا وسلموا البلد إليهم، فلم يفِ الفرنج لهم بالأمان، وأخذوا أموالهم، واستنقذوها بالعقوباتِ وأنواع العذاب، فلما فرغوا من جبيل وساروا إلى مدينة عكا استنجدهم الملك بغدوين، ملك الفرنج، صاحب بيت المقدس على حصارها، فنازلوها وحصروها في البر والبحر، وكان الوالي بها اسمه بنا -ويعرف بزهر الدولة الجيوشي- نسبة إلى ملك الجيوش الأفضل، فقاتلهم أشد قتال، فزحفوا إليه غير مرة، فعجز عن حفظ البلد، فخرج منه وملك الفرنجُ البلد بالسيف قهرًا، وفعلوا بأهلِه الأفعال الشنيعة، وسار الوالي بها إلى دمشق، فأقام بها، ثم عاد إلى مصر واعتذر إلى الأفضل فقَبِلَ عُذرَه."},{"id":1774,"title":"وفاة أبي سعد العلاء بن الموصلايا .","date":["العام الهجري :497","العام الميلادي :1103"],"text":"هو أمين الدولة أبو سعد العلاء بن حسن بن وهب الموصلايا البغدادي، الكاتب المنشئ بدار الخلافة. ذو الترسُّل الفائق، المنشئ، البليغ. كان نصرانيًّا وأسلم على يد الخليفة المقتدي بأمر الله، وحَسُن إسلامه، أسلم عندما خرج توقيعُ الخليفة سنة 484 بإلزامِ الذَّمَّةِ بلُبسِ الغيار -لبس خاص كوضع الزُّنَّار، وغيره - فأسلم بعضُهم وهرب طائفة. وفي ثاني يوم أسلم الرئيسان أبو سعد بن الموصلايا صاحب ديوان الإنشاء، وابن أخته أبو نصر هبة الله بن الحسن، على يد الخليفة، بحيث يريانه ويسمعانِ كلامَه. كان أبو سعد له باعٌ مديد في النظم والنثر، عُمِّر دهرًا، وكُفَّ بصَرُه، بعد أن كتب الإنشاء نيفًا وستين سنة، ولما أسلم كان قد شاخ، وقد ناب في الوزارة غيرَ مرة، وكان أفصح أهل زمانه، وفيه مكارم وآداب وعقل, وكان كثير الصدقات، وأوقف أملاكه، وله الرسائل المشهورة الرائقة، والأشعار الفائقة. كان يملي على ابن أخته العلامة أبي نصر الإنشاءَ إلى أن مات فجأة. وكان الوزير عميد الدولة بن جهير: \"يثني عليه وعلى تفهُّمِه، ويقول: هو يمين الدولة وأميناها\". ناب أبو سعد في الوزارة عدة نُوَب, قال ابن الأثير: \"كان بليغًا فصيحًا، وكان ابتداء خدمته للقائم بأمر الله سنة اثنتين وثلاثين وأربعمائة، خدم الخلفاء خمسًا وستين سنة، كل يوم تزداد منزلته، وكان نصرانيًّا فأسلم، وكان كثير الصدقة، جميل المحضر، صالح النية. أوقف أملاكَه على أبواب البر، ومكاتباته مشهورة حسنة\" مات فجأة، فخلفه على ديوان الإنشاء ابن أخته أبو نصر، ولُقِّب نظام الحضرتين."},{"id":1775,"title":"انتصار المسلمين على الصليبيين في معركة حران  .","date":["العام الهجري :497","العام الميلادي :1103"],"text":"كانت حران لمملوك من مماليك ملكشاه اسمه قراجه، فاستخلف عليها إنسانًا يقال له محمد الأصبهاني، وخرج في العام الماضي، فعصى الأصبهاني على قراجه، ثم قُتل محمد الأصبهاني، قتَلَه غلامٌ لقراجه، فعند ذلك سار الفرنج إلى حران وحصروها، فلما سمع مُعين الدولة سقمان وشمس الدولة جكرمش ذلك، وكان بينهما حرب، أرسل كلٌّ منهما إلى صاحبه يدعوه إلى الاجتماع معه لتلافي أمر حران، ويُعلِمه أنه قد بذل نفسه لله تعالى وثوابه، فكل واحد منهما أجاب صاحبه إلى ما طلب منه، وسارا فاجتمعا على الخابور وتحالفا، وسارا إلى لقاء الفرنج، فالتقوا على نهر البليخ، وكان المصاف بينهم هناك فاقتتلوا، فأظهر المسلمون الانهزام، فتبعهم الفرنج نحو فرسخين، فعاد عليهم المسلمون فقتلوهم كيف شاؤوا، وامتلأت أيدي التركمان من الغنائم، ووصلوا إلى الأموال العظيمة؛ لأن سواد الفرنج كان قريبًا، وكان بيمند صاحبُ أنطاكية، وطنكري صاحِبُ الساحل، قد انفردا وراء جبل ليأتيا المسلمين من وراء ظهورهم إذا اشتدت الحرب، فلما خرجا رأيا الفرنج منهزمين، وسوادهم منهوبًا، فأقاما إلى الليل وهربا، فتبعهما المسلمون، وقتلوا من أصحابهما كثيرًا، وأسَروا كذلك، وأفلتا في ستة فرسان، وكان القمص كبير القساوسة- بردويل، صاحب الرها، قد انهزم مع جماعةٍ من قمامصتهم، وخاضوا نهر البليخ، فوَجِلت خيولهم، فجاء تركماني من أصحاب سقمان فأخذهم، وحمل بردويل إلى خيم صاحبه، وقد سار فيمن معه لاتباع بيمند، فرأى أصحاب جكرمش أن أصحاب سقمان قد استولوا على مال الفرنج، ويرجعون هم من الغنيمة بغير طائل، فقالوا لجكرمش: أي منزلة تكون لنا عند الناس، وعند التركمان إذا انصرفوا بالغنائم دوننا؟ وحَسَّنوا له أخذَ القُمص، فأنفذ فأخذ القمص من خيم سقمان، فلما عاد سقمان شقَّ عليه الأمر، وركب أصحابُه للقتال، فردَّهم، وقال لهم: لا يقوم فرح المسلمين في هذه الغزاة بغَمِّهم باختلافنا، ولا أؤثر شفاء غيظي بشماتة الأعداء بالمسلمين. ورحل لوقته، وأخذ سلاح الفرنج، وراياتهم، وألبس أصحابَه لُبسَهم، وأركبهم خيلَهم، وجعل يأتي حصون شيحان، وبها الفرنج، فيَخرُجون ظنًّا منهم أن أصحابهم نُصِروا، فيقتُلهم ويأخذ الحصن منهم، فعل ذلك بعدة حصون. وأما جكرمش فإنه سار إلى حران فتسلمها، واستخلف بها صاحبه. وسار إلى الرها، فحصرها خمسة عشر يومًا، وعاد إلى الموصل ومعه القمص الذي أخذه من خيام سقمان، ففاداه بخمسة وثلاثين دينارًا، ومائة وستين أسيرًا من المسلمين، وكان عدة القتلى من الفرنج يقارب اثني عشر ألف قتيل!"},{"id":1776,"title":"انتزاع بلك بن بهرام مدينة عانة من بني يعيش .","date":["العام الهجري :497","الشهر القمري : محرم","العام الميلادي :1103"],"text":"استولى بلك بن بهرام بن أرتق على مدينة عانة، والحديثة، وكانت له مدينة سروج، فأخذها الفرنجُ منه، فسار عنها إلى عانة وأخذها من بني يعيش بن عيسى بن خلاط، فقصد بنو يعيش سيف الدولة صدقة بن مزيد، ومعهم مشايخهم، فسألوه الإصعادَ إليها، وأن يتسلَّمَها منهم، ففعل وأصعد معهم, فرحل التركمان وبهرام عنها، وأخذ صدقة رهائنَهم، وعاد إلى حلته، فرجع بلك إليها ومعه ألفا رجل من التركمان، فمانعه أصحابه قليلًا، واستدلَّ على المخاضة إليها، فخاضها وعبر، وملكهم ونهبهم، وسبى جميع حرمهم وانحدر طالبًا هيت من الجانب الشامي، فبلغ إلى قريب منها، ثم رجع من يومه."},{"id":1777,"title":"غارة الفرنج على الرقة وقلعة جعبر .","date":["العام الهجري :497","الشهر القمري : صفر","العام الميلادي :1103"],"text":"أغار الفرنج من الرها على مرج الرقة وقلعة جعبر، وكانوا لما خرجوا من الرها افترقوا فرقتين، وتواعدوا يومًا واحدًا تكون الغارة على البلدين فيه، ففعلوا ما استقرَّ بينهم، وأغاروا، واستاقوا المواشيَ، وأسَروا من وقع بأيديهم من المسلمين، فكانت قلعة جعبر والرقة لسالم بن مالك بن بدران بن المقلد بن المسيب، سلَّمها إليه السلطان ملكشاه سنة تسع وسبعين وأربعمائة."},{"id":1778,"title":"الصلح بين السلطان بركيارق وأخيه محمد .","date":["العام الهجري :497","الشهر القمري : ذي القعدة","العام الميلادي :1104"],"text":"في هذه السنة وقع الصلح بين الأخوين السلطانين بركيارق ومحمد ابني ملكشاه. وكان سببه أن الحروب تطاولت بينهما، وعمَّ الفساد، فصارت الأموال منهوبة، والدماء مسفوكة، والبلاد مخربة، والقرى محرقة، والسلطنة مطموعًا فيها، محكومًا عليها، فلما رأى السلطانُ بركيارق المالَ عنده معدومًا، والطمع من العسكر زائدًا، أرسل القاضي أبا المظفر الجرجاني الحنفي، وأبا الفرج الهمذاني، المعروف بصاحب قراتكين، إلى أخيه محمد في تقرير قواعد الصلح، فسار إليه وهو بالقرب من مراغة، فذكرا له ما أُرسِلا فيه، ورغَّباه في الصلح وفضيلته، وما شمل البلادَ من الخراب، وطَمَع عدوِّ الإسلام في أطراف الأرض، فأجاب إلى ذلك، وأرسل فيه رسلًا، واستقر الأمر، وحلف كلُّ واحد منهما لصاحبه، وتقررت القاعدة: أن السلطان بركيارق لا يعترض أخاه محمدًا في الطبل -كان من شعائر السلطنة أن تضرب الطبلخانات للسلطان خمس مرات في اليوم- وألَّا يُذكَر معه على سائر البلاد التي صارت له، وألَّا يكاتب أحدهما الآخرَ، بل تكون المكاتبة من الوزيرين، ولا يعارض أحدٌ من العسكر في قصد أيِّهما شاء، فأجاب بركيارق إلى هذا، وزال الخلاف والشغب، وأرسل السلطان محمد إلى أصحابه بأصبهان يأمرهم بالانصراف عن البلد، وتسليمه إلى أصحاب أخيه، وسار السلطان بركيارق إلى أصبهان، فلما سلمها إليه أصحاب أخيه دعاهم إلى أن يكونوا معه وفي خدمته، فامتنعوا ورأوا لزوم خدمة صاحبهم، فسمَّاهم أهل العسكرين جميعًا: أهل الوفاء، وتوجهوا من أصبهان، ومعهم حريم السلطان محمد إليه، وأكرمهم بركيارق، وحمل لأهل أخيه المالَ الكثير، ومن الدواب ثلاثمائة جمل، ومائة وعشرين بغلًا تحمِلُ الثِّقلَ، وسَيَّرَ معهم العساكر يخدمونهم. ولما وصلت رسل السلطان بركيارق إلى الخليفة المستظهر بالله بالصلح، وما استقرت القواعد عليه، حضر إيلغازي بالديوان، وسأل في إقامة الخطبة لبركيارق، فأجيب إلى ذلك، وفي ذي القعدة سُيِّرَت الخِلَع من الخليفة للسلطان بركيارق، وللأمير إياز، ولوزير بركيارق، والعهد بالسلطنة، وحلفوا جميعهم للخليفة وعادوا."},{"id":1779,"title":"أخبار الباطنيين في خراسان .","date":["العام الهجري :498","العام الميلادي :1104"],"text":"في خراسان سار جمعٌ كثير من الإسماعيلية الباطنية من طريثيت، عن بعض أعمال بيهق، وشاعت الغارة في تلك النواحي، وأكثروا القتلَ في أهلها، والنهبَ لأموالهم، والسبيَ لنسائهم، واشتدَّ أمرهم، وقَوِيَت شوكتهم، ولم يكفُّوا أيديَهم عمن يريدون قتْلَه؛ لاشتغال سلاطين السلاجقة بالاقتتال فيما بينهم عن خطر الباطنية. فمن جملة فعلهم لما تجمع حُجَّاج هذه السنة، مما وراء النهر، وخراسان، والهند، وغيرها من البلاد، فوصلوا إلى جوار الري؛ أتاهم الباطنية وقت السَّحَر، فوضعوا فيهم السيفَ، وقتلوهم كيف شاؤوا، وغَنِموا أموالهم ودوابَّهم، ولم يتركوا شيئًا، كما قتلوا هذه السنة أبا جعفر بن المشاط، وهو من شيوخ الشافعية."},{"id":1780,"title":"وفاة السلطان بركيارق بن ملكشاه .","date":["العام الهجري :498","الشهر القمري : جمادى الأولى","العام الميلادي :1105"],"text":"هو السلطان ركن الدولة بركيارق بن السلطان ملكشاه بن السلطان ألب أرسلان بن داود بن سلجوق بن دقماق السلجوقي أبو المظفر، كانت سلطنته اثنتي عشرة سنة وأربعة أشهر، جرت له خطوبٌ طويلة وحروب هائلة، خُطِب له ببغداد ست مرات, فقاسى من الحروب واختلاف الأمور عليه ما لم يقاسِه أحد، واختلفت به الأحوال بين رخاء وشدة، ومُلكٍ وزواله، وأشرفَ في عدة نُوَب بعد إسلام النعمة على ذَهاب المُهجة, ولم يُهزَم في حروبه غيرَ مرَّة واحدة، وكان أمراؤه قد طمعوا فيه للاختلاف الواقع بينه وبين أخيه محمد، حتى إنهم كانوا يطلبون نوَّابَه ليقتلوهم، فلا يمكِنُه الدفعُ عنهم، وكان متى خطب له ببغداد وقع الغلاءُ، ووقفت المعايشُ والمكاسِبُ، وكان أهلها مع ذلك يحبُّونه، ويختارون سلطانه, وكان حليمًا كريمًا، صبورًا عاقلًا كثيرَ المداراة، حَسَنَ القدرة، لا يبالِغُ في العقوبة، وكان عفوُه أكثر من عقوبته. ولما قويَ أمره هذه السنة وأطاعه المخالِفون وانقادوا له؛ أدركته منيته. كان قد مرض بأصبهان بالسلِّ والبواسير، فسار منها في محفة طالبًا بغداد، فلما وصل إلى بروجرد ضَعُف عن الحركة، فأقام بها أربعين يومًا، فاشتدَّ مرضه، فلما أيس من نفسِه خلع على ولده ملكشاه، وعمره حينئذ أربع سنين وثمانية أشهر، وخلع على الأمير إياز، وأحضر جماعةً من الأمراء، وأعلمهم أنه قد جعل ابنَه وليَّ عهده في السلطنة، وجعل الأميرَ إياز أتابكه -الأمير الوالد- وأمرهم بالطاعةِ لهما، ومساعدتهما على حفظ السلطنة لولده، والذب عنها، فأجابوا كلهم بالسمع والطاعة لهما، وبَذْل النفوس والأموال في حفظ ولده وسلطنته عليه، واستحلفهم على ذلك، فحلفوا، وأمرهم بالمسير إلى بغداد فساروا، فلما كانوا على اثني عشر فرسخًا من بروجرد وصلهم خبر وفاته، فلما سمع الأمير إياز بموته أمر وزيره الخطير المبيذي وغيره بأن يسيروا مع تابوته إلى أصبهان، فحُمِل إليها ودُفِن فيها، مات بركيارق عن عمر أربع وعشرين سنة وشهور. ثم خُطِب لملكشاه بن بركيارق ببغداد في جمادى الأولى، فلم يتِمَّ أمرُه، عدا عليه عمُّه محمد الذي كان ينازع أخاه بركيارق، فانتزع السلطنة وقتل الوصيَّ إياز."},{"id":1781,"title":"احتلال الفرنج حصن أرتاح بالشام .","date":["العام الهجري :498","الشهر القمري : شعبان","العام الميلادي :1105"],"text":"كانت وقعة بين طنكري الفرنجي، صاحب أنطاكية، وبين الملك رضوان، صاحب حلب، انهزم فيها رضوان وسببها أن طنكري حصر حصن أرتاح، وبه نائب الملك رضوان، فضيق الفرنجُ على المسلمين، فأرسل النائِبُ بالحصن إلى رضوان يعرِّفه ما هو فيه من الحصر الذي أضعف نفسَه، ويطلب النجدة، فسار رضوان في عسكر كثير من الخيَّالة، وسبعة آلاف من الرجَّالة، منهم ثلاثة آلاف من المتطوِّعة، فساروا حتى وصلوا إلى قِنَّسرين، وبينهم وبين الفرنج قليل، فلما رأى طنكري كثرة المسلمين أرسل إلى رضوان يطلب الصلح، فأراد أن يجيبَ فمنعه أصبهبذ صباوة، وكان قد قصده وصار معه بعد قتل إياز، فامتنع من الصلح واصطفُّوا للحرب، فانهزمت الفرنجُ من غير قتال، ثم قال الفرنج: نعود ونحمِلُ عليهم حملة واحدة، فإن كانت لنا، وإلا انهزمنا، فحملوا على المسلمين فلم يثبتوا وانهزموا، وقُتِل من المسلمين وأُسِر الكثير، وأما الرَّجَّالة فإنهم كانوا قد دخلوا معسكر الفرنج لما انهزموا، فاشتغلوا بالنهب، فقتلهم الفرنج، ولم ينجُ إلا الشريد فأُخِذ أسيرًا، وهرب من في أرتاح إلى حلب، وملكه الفرنج، وهرب أصبهبذ صباوة إلى طغتكين أتابك بدمشق، فصار معه ومن أصحابه."},{"id":1782,"title":"حرب الفرنج والمصريين .","date":["العام الهجري :498","الشهر القمري : ذي الحجة","العام الميلادي :1105"],"text":"كانت وقعةٌ بين الفرنج والمسلمين كانوا فيها على السواء، وسببها أن أمير الجيوش الأفضل، وزير صاحب مصر، كان قد سيَّرَ ولده شرف المعالي في السنة الماضية إلى الفرنج فقهرهم وأخذ الرملة منهم، ثم اختلف المصريون والعرب وادَّعى كل واحد منهما أن الفتح له، فأتتهم سرية الفرنج فتقاعد كل فريق منهما بالآخر، حتى كاد الفرنج يظهرون عليهم، فرحل عند ذلك شرف المعالي إلى أبيه بمصر، فنفذ ولده الآخر، وهو سناء الملك حسين، في جماعة من الأمراء، منهم جمال الملك، والنائب بعسقلان للمصريين، وأرسلوا إلى طغتكين أتابك بدمشق -أتابك يعني الأمير الوالد- يطلبون منه عسكرًا، فأرسل إليهم أصبهبذ صباوة ومعه ألف وثلاثمائة فارس، وكان المصريون في خمسة آلاف، وقصدهم بغدوين الفرنجي، صاحب القدس وعكا ويافا، في ألف وثلاثمائة فارس، وثمانية آلاف راجل، فوقع المصاف بينهم بين عسقلان ويافا، فلم تظهر إحدى الطائفتين على الأخرى، فقُتل من المسلمين ألف ومائتان، ومن الفرنج مثلهم، وقُتِل جمال الملك، أمير عسقلان، فلما رأى المسلمون أنهم قد تكافؤوا في النكاية قطعوا الحرب وعادوا إلى عسقلان، وعاد صباوة إلى دمشق، وكان مع الفرنج جماعة من المسلمين، منهم بكتاش بن تتش، وكان طغتكين قد عدل في الملك إلى ولد أخيه دقاق، وهو طفل، فدعاه ذلك إلى قصد الفرنج؛ ليكون معهم."},{"id":1783,"title":"احتلال الفرنج حصن أفامية .","date":["العام الهجري :499","العام الميلادي :1105"],"text":"احتلَّ الفرنج حصن أفامية من بلد الشام، وسبب ذلك أن المتولي لأفامية من جهة الملك رضوان صاحب حلب أرسل إلى صاحب مصر العُبيدي الإسماعيلي، وكان يميل إلى مذهبهم، يستدعي منهم من يسلِّم إليه الحصن، وهو من أمنع الحصون، فطلب خلف بن ملاعب الكلابي -كان متغلبًا على حمص- من صاحب مصر العبيدي أن يكون هو المقيم به، وقال: إنني أرغب في قتال الفرنج وأوثرُ الجهاد. فسلموه إليه وأخذوا رهائنه، فلما ملكه خلع طاعتَهم ولم يرعَ حقهم، وأقام بأفامية يُخيف السبيل، ويقطع الطريق، واجتمع عنده كثيرٌ من المفسدين، فكثُرت أمواله، ثم إن الفرنج ملكوا سرمين، وهي من أعمال حلب، وأهلها غلاة في التشيع، فلما ملكها الفرنج تفرَّق أهلها، فتوجه القاضي الذي بها إلى ابن ملاعب وأقام عنده، فأكرمه وأحبه ووثق به، فأعمل القاضي الحيلةَ عليه، وكتب إلى أبي طاهر، المعروف بالصائغ، وهو من أعيان أصحاب الملك رضوان، ووجوه الباطنية ودعاتهم، ووافقهم على الفتك بابن ملاعب، وأن يسلِّمَ أفامية إلى الملك رضوان، وعاود القاضي مكاتبة أبي طاهر بن الصائغ، وأشار عليه أن يوافق رضوان على إنفاذ ثلاثمائة رجل من أهل سرمين، وينفذ معهم خيلًا من خيول الفرنج، وسلاحًا من أسلحتهم، ورؤوسًا من رؤوس الفرنج، ويأتوا إلى ابن ملاعب ويُظهروا أنهم غزاة ويَشكُوا من سوء معاملة الملك رضوان وأصحابه لهم، وأنهم فارَقوه، فلقِيَهم طائفة من الفرنج فظفروا بهم، ويحملوا جميع ما معهم إليه، فإذا أذِنَ لهم في المقام اتفقت آراؤهم على إعمال الحيلة عليه، ففعل ابن الصائغ ذلك، ووصل القوم إلى أفامية، وقَدِموا إلى ابن ملاعب بما معهم من الخيل وغيرها، فقبل ذلك منهم، وأمرهم بالمقام عنده، وأنزلهم في ربض أفامية، فلما كان في بعض الليالي نام الحرَّاس بالقلعة، فقام القاضي ومن بالحصن من أهل سرمين، ودلوا الحبال وأصعدوا أولئك القادمين جميعهم، وقصدوا أولاد ابن ملاعب، وبني عمه، وأصحابه، فقتلوهم، وأتى القاضي وجماعة معه إلى ابن ملاعب، فقتله وقتل أصحابه، وهرب ابناه، فقُتِل أحدهما، والتحق الآخر بأبي الحسن بن منقذ، ولما سمع ابن الصائغ خبر أفامية سار إليها، وهو لا يشكُّ أنها له، فقال له القاضي: إن وافقتَني وأقمتَ معي، فبالرحب والسعة، ونحن بحكمك، وإلا فارجع من حيث جئتَ. فأيِسَ ابن الصائغ منه، وكان أحد أولاد ابن ملاعب بدمشق عند طغتكين غضبان على أبيه، فولاه طغتكين حصنًا، وضَمِن على نفسه حِفظَ الطريق، وأخذ القوافل، فاستغاثوا إلى طغتكين منه، فأرسل إليه من طلبه، فهرب إلى الفرنج واستدعاهم إلى حصن أفامية، وقال: ليس فيه غيرُ قوت شهر، فأقاموا عليه يحاصرونه، فجاع أهله وملكه الفرنج، وقتلوا القاضيَ المتغلِّبَ عليه، وأخذوا الصائِغَ فقتلوه، وكان هو الذي أظهر مذهب الباطنية بالشام، هكذا ذكر بعضهم أن أبا طاهر الصائغ قتله الفرنج بأفامية، وقد قيل: إن ابن بديع، رئيس حلب، قتله سنة سبع وخمسمائة بعد وفاة رضوان."},{"id":1784,"title":"حال طرابلس الشام مع الفرنج .","date":["العام الهجري :499","العام الميلادي :1105"],"text":"كان صنجيل الفرنجي قد ملك مدينة جبلة، وأقام على طرابلس يحصرها، فحيث لم يقدر أن يملكها بنى بالقرب منها حصنًا وبنى تحته ربضًا، وأقام مراصد لها، منتظرًا وجود فرصة فيها، فخرج فخر الملك أبو علي بن عمار، صاحب طرابلس، فأحرق ربضه، ووقف صنجيل على بعض سقوفه المتحرقة، ومعه جماعة من القمامصة -كبار القساوسة- والفرسان، فانخسف بهم، فمرض صنجيل من ذلك عشرة أيام ومات، وحُمل إلى القدس فدُفن فيه، ثم إن ملك الروم أمر أصحابه باللاذقية ليحملوا الميرةَ إلى هؤلاء الفرنج الذين على طرابلس، فحملوها في البحر، فأخرج إليها فخر الملك بن عمار أسطولًا، فجرى بينهم وبين الروم قتال شديد، فظَفِر المسلمون بقطعة من الروم فأخذوها، وأسروا من كان بها وعادوا، ولم تزل الحرب بين أهل طرابلس والفرنج عدةَ سنين، فعدمت الأقوات بها، وخاف أهلها على نفوسهم وأولادهم وحرمهم، فجلا الفقراء وافتقر الأغنياء، وظهر من ابن عمار صبر عظيم وشجاعة ورأي سديد، ومما أضر بالمسلمين فيها أن صاحبها استنجد سقمان بن أرتق فجمع العساكر وسار إليه، فمات في الطريق وأجرى ابن عمار الجرايات على الجند والضَّعَفة، فلما قلَّت الأموال عنده شرع يقسط على الناس ما يخرجه في باب الجهاد، فأخذ من رجلين من الأغنياء مالًا مع غيرهما، فخرج الرجلان إلى الفرنج وقالا: إن صاحبنا صادَرَنا، فخرجنا إليكم لنكون معكم، وذكرا لهم أنه تأتيه الميرة من عرقة والجبل، فجعل الفرنج جميعًا على ذلك الجانب يحفظُه من دخول شيء إلى البلد، فأرسل ابن عمار وبذل للفرنج مالًا كثيرًا ليسَلِّموا الرجلين إليه فلم يفعلوا، فوضع عليهما مَن قتلهما غيلةً."},{"id":1785,"title":"الحرب بين طغتكين والفرنج .","date":["العام الهجري :499","الشهر القمري : صفر","العام الميلادي :1105"],"text":"حدثت وقعة بين طغتكين أتابك دمشق -أتابك يعني الأمير الوالد- وبين قمص -كبير القساوسة- كبير من قمامصة الفرنج، وسبب ذلك أنه تكررت الحروب بين عسكر دمشق وبغدوين، فتارة لهؤلاء وتارة لهؤلاء، ففي آخر الأمر بنى بغدوين حصنًا بينه وبين دمشق نحو يومين، فخاف طغتكين من عاقبة ذلك، وما يحدث به من الضرر؛ فجمع عسكره وخرج إلى مقاتلتهم، فسار بغدوين ملك القدس وعكا وغيرهما، إلى هذا القمص ليعاضده ويساعده على المسلمين، فعرَّفه القمص غناه عنه، وأنه قادر على مقارعة المسلمين إن قاتلوه، فعاد بغدوين إلى عكا، وتقدم طغتكين إلى الفرنج، واقتتلوا واشتد القتال، فانهزم أميران من عسكر دمشق، فتبعهما طغتكين وقتلهما، وانهزم الفرنج إلى حصنهم فاحتموا به، فقال طغتكين: مَن أحسنَ قتالَهم وطلب مني أمرًا فعلتُه معه، ومن أتاني بحجر من حجارة الحصن أعطيتُه خمسة دنانير، فبذل الرجَّالة نفوسهم، وصعدوا إلى الحصن وخربوه، وحملوا حجارته إلى طغتكين، فوفى لهم بما وعدهم، وأمر بإلقاء الحجارة في الوادي، وأسَروا من بالحصن، فأمر بهم فقُتلوا كلُّهم، واستبقى الفرسان أسراءَ، وكانوا مائتي فارس، ولم ينج ممَّن كان في الحصن إلا القليل، وعاد طغتكين إلى دمشق منصورًا، فزين البلد أربعة أيام وخرج منها إلى رفنية، وهو من حصون الشام، وقد تغلب عليه الفرنج، وصاحبه ابن أخت صنجيل المقيم على حصار طرابلس، فحصره طغتكين، وملكه، وقتل به خمسمائة رجل من الفرنج."},{"id":1786,"title":"نهب العرب للبصرة .","date":["العام الهجري :499","الشهر القمري : ذي القعدة","العام الميلادي :1106"],"text":"لَمَّا استولى الأمير صدقة بن مزيد صاحب الحلة على البصرة، واستناب بها مملوكًا اسمه التونتاش، وجعل معه مائة وعشرين فارسًا، اجتمعت ربيعة والمنتفق ومن انضم إليهم من العرب وقصدوا البصرة في جمع كثير، فقاتلهم التونتاش فأسروه وانهزم أصحابه، ولم يقدر من بها على حفظها، فدخلوها بالسيف أواخِرَ ذي القعدة، وأحرقوا الأسواق والدور الحسان، ونهبوا ما قدروا عليه، وأقاموا ينهبون ويحرقون اثنين وثلاثين يومًا، وتشرد أهلُها في السواد، ونُهِبت خزانة كتب كانت موقوفة، وقفها القاضي أبو الفرج بن أبي البقاء، وبلغ الخبر الأميرَ صدقة فأرسل عسكرًا، فوصلوا وقد فارقها العرب، ثم إن السلطان محمدًا أرسل شحنة وعميدًا إلى البصرة، وأخَذَها من صدقة، وعاد أهلها إليها وشرعوا في عمارتها."},{"id":1787,"title":"الحرب بين ملك القسطنطينية والفرنج .","date":["العام الهجري :500","العام الميلادي :1106"],"text":"كانت وحشةٌ مُستحكِمة بين ملك الروم، صاحب القسطنطينية، وبين بيمند الفرنجي؛ فسار بيمند إلى بلد ملك الروم ونهبه، وعزم على قصده، فأرسل ملك الروم إلى الملك قلج أرسلان بن سليمان صاحب قونية وأقصرا وغيرهما من تلك البلاد يستنجده، فأمده بجمع من عسكره، فقوي بهم وتوجه إلى بيمند، فالتقوا وتصافوا واقتتلوا، وصبر الفرنج بشجاعتهم، وصبر الروم ومن معهم لكثرتهم، ودامت الحرب، ثم أجلت الوقعة عن هزيمة الفرنج، وأتى القتلُ على أكثرهم، وأُسِر كثير منهم، والذين سَلِموا عادوا إلى بلادهم بالشام، وعاد عسكر قلج أرسلان إلى بلادهم عازمين على المسير إلى صاحبهم بديار الجزيرة، فأتاهم خبر قتله، فتركوا الحركة وأقاموا."},{"id":1788,"title":"تدمير السلطان محمد بن ملكشاه لقلاع الباطنية .","date":["العام الهجري :500","العام الميلادي :1106"],"text":"قام السلطان محمد بن ملكشاه بمحاصرة قلاع كثيرة من حصون الباطنية، فافتتح منها أماكن كثيرة، وقتل خلقًا منهم، منها قلعة شاه دز بأصبهان حصينة كان أبوه السلطان جلال الدولة ملكشاه قد بناها بالقرب من أصبهان في رأس جبل منيع هناك، وكان سبب بنائه لها أنه كان مرة في بعض صيوده فهرب منه كلب فاتَّبعه إلى رأس الجبل فوجده، وكان معه رجل نصراني من رسل الروم، فقال الرومي: لو كان هذا الجبل ببلادنا لاتخذنا عليه قلعة، فحدا هذا الكلام السلطان إلى أن ابتنى في رأسه قلعةً أنفق عليها ألف ألف دينار، ومائتي ألف دينار، ثم استحوذ عليها بعد ذلك رأس الباطنية ابن عطاش، فتعب المسلمون بسببها، فحاصرها السلطان محمد بن ملكشاه سنةً حتى افتتحها وقَتَل ابن عطاش, ثم نقض السلطان محمد هذه القلعة حجرًا حجرًا، وألقت امرأة ابن عطاش نفسها من أعلى القلعة فتلفت، وهلك ما كان معها من الجواهر النفيسة، وكان الناس يتشاءمون بهذه القلعة، يقولون: كان دليلها كلبًا، والمشيرُ بها كافرًا، والمتحصِّنُ بها زنديقًا."},{"id":1789,"title":"وفاة يوسف بن تاشفين مؤسس دولة المرابطين .","date":["العام الهجري :500","الشهر القمري : محرم","العام الميلادي :1106"],"text":"هو سلطان المغرب أبو يعقوب يوسف بن تاشفين بن إبراهيم بن ترقنت الصنهاجي اللمتوني المغربي البربري، الملقَّب بأمير المسلمين، وبأمير المرابطين، وبأمير الملثمين. ولد سنة 430. كان أحدَ من ملك البلاد ودانت بطاعته العباد، واتسعت ممالكه، وطال عمره. وقلَّ أن عُمِّرَ أحد من ملوك الإسلام ما عمر. تولى إمارة البربر واستولى على المغرب ثم الأندلس والسودان، وكان يخطب لبني العباس، وهو أول من تسمى بأمير المسلمين من المرابطين، ولم يزل على حاله وعِزِّه وسلطانه إلى أن توفي سنة 500. قال ابن خلدون: \"تسمَّى يوسف بن تاشفين بأمير المسلمين، وخاطَبَ الخليفة لعهده ببغداد، وهو أبو العباس أحمد المستظهر بالله العباسي، وبعث إليه عبد الله بن محمد بن العربي المعافري الإشبيلي وولده القاضي أبا بكر بن العربي الإمام المشهور، فتلطفا في القول وأحسنا في الإبلاغ وطلبا من الخليفة أن يعقد لأمير المسلمين بالمغرب والأندلس؛ فعَقَدَ له وتضمن ذلك مكتوبًا من الخليفة منقولًا في أيدي الناس، وانقلبا إليه بتقليد الخليفة وعهده على ما إلى نظره من الأقطار والأقاليم، وخاطبه الإمام الغزالي والقاضي أبو بكر الطرطوشي يحضانه على العدل والتمسك بالخير\". وإنما احتاج أمير المسلمين إلى التقليد من الخليفة المستظهر بالله مع أنه كان بعيدًا عنه وأقوى شوكةً منه؛ لتكون ولايته مستندة إلى الشرع، وهذا من ورعه، وإنما تسمى بأمير المسلمين دون أمير المؤمنين أدبًا مع الخليفة حتى لا يشارِكَه في لقبه؛ لأن لقب أمير المؤمنين خاص بالخليفة, وكان أمير المسلمين حين ورد عليه التقليد من الخليفة ضرب السكةَّ باسمه ونقش على الدينار لا إله إلا الله محمد رسول الله، وتحت ذلك أمير المسلمين يوسف بن تاشفين, وكتب على الصفحة الأخرى عبد الله أحمد أمير المؤمنين العباسي, وكان ملكه قد انتهى إلى مدينة أفراغة من قاصية شرق الأندلس، وإلى مدينة أشبونة على البحر المحيط من بحر الأندلس، وذلك مسيرة ثلاثة وثلاثين يومًا طولًا، وفي العرض ما يقرب من ذلك، وملك بعدوة المغرب من جزائر بني مذغنة إلى طنجة إلى آخر السوس الأقصى إلى جبال الذهب من بلاد السودان, ولم يُرَ في بلد من بلاده ولا عَمَلٍ من أعماله على طول أيامه رسمُ مَكسٍ ولا خَراجٌ، لا في حاضرة ولا في بادية إلا ما أمر الله به، وأوجب حكم الكتاب والسنة من الزكوات والأعشار وجزيات أهل الذمة وأخماس الغنائم, وقد جبى في ذلك من الأموال على وجهها ما لم يَجْبِه أحد قبله. يقال: إنه وُجِد في بيت ماله بعد وفاته ثلاثة عشر ألف ربع من الوَرِق، وخمسة آلاف وأربعون ربعًا من مطبوع الذهب, وكان زاهدًا في زينة الدنيا وزهرتها، وَرِعًا متقشِّفًا، لباسه الصوف لم يَلبَس قطُّ غيره، ومأكله الشعير ولحوم الإبل وألبانها مقتصرًا على ذلك، لم يُنقَل عنه مدة عمره على ما منحه الله من سعة الملك وخوَّله من نعمة الدنيا، وقد رد أحكام البلاد إلى القضاة وأسقط ما دون الأحكام الشرعية، وكان يسير في أعماله بنفسه فيتفقد أحوال الرعية في كل سنة، وكان محبًّا للفقهاء وأهل العلم والفضل مكرمًا لهم صادرًا عن رأيهم، يُجري عليهم أرزاقهم من بيت المال، وكان مع ذلك حسن الأخلاق متواضعًا كثير الحياء جامعًا لخصال الخير. هو الذي بنى مدينة مراكش في سنة خمس وستين وأربعمائة، اشتراها يوسف بماله الذي خرج به من الصحراء. وكان في موضعها غابة من الشجر وقرية فيها جماعة من البربر، فاختطها وبنى بها القصور والمساكن الأنيقة, وهو الذي أخذ الأندلس من ملوك الطوائف وأسر المعتمد بن عباد في أغمات.. توفي في قصره بمراكش يوم الاثنين لثلاث خلون من المحرم, وعاش سبعين سنة مَلَكَ منها مدة خمسين سنة, وكان قد عهد بالإمرة من بعده لولده علي الذي بويع له ولُقِب بأمير المسلمين كذلك."},{"id":1790,"title":"استحواذ سيف الدولة صدقة بن منصور على مدينة تكريت .","date":["العام الهجري :500","الشهر القمري : صفر","العام الميلادي :1106"],"text":"تسلَّم الأمير سيف الدولة صدقة بن منصور بن مزيد قلعةَ تكريت، وكانت لبني مقن العقيليين، ولما استقر السلطان محمد بعد موت أخيه بركيارق أقطعها للأمير أتسز البرسقي، فسار إليها وحصرها مدة تزيد على سبعة أشهر حتى تسلمها."},{"id":1791,"title":"مقتل ابن عطاش الباطني .","date":["العام الهجري :500","الشهر القمري : شعبان","العام الميلادي :1107"],"text":"هو الرئيس أحمد بن عبد الملك بن عطاش العجمي طاغية الإسماعيلية. كان أبوه من كبار دعاة الباطنية ومن أذكياء الأدباء، له بلاغة وسرعة جواب، استغوى جماعة ثم هلك، وخلفه في الرياسة ابنه أحمد، فكان جاهلًا شجاعًا مطاعًا، تجمع له أتباع وتحيلوا حتى ملكوا قلعة شاه دز بأصبهان، وكان الباطنية بأصبهان قد ألبسوا ابن عطاش تاجًا وجمعوا له أموالًا، وصار له عدد كثير وبأس شديد، واستفحل أمره بالقلعة، فكان يرسل أصحابَه لقطع الطريق، وأخْذ الأموال، وقَتْل من قدروا على قتله، فلما صَفَت السلطنة لمحمد بن ملكشاه ولم يبق له منازعٌ، لم يكن عنده أمر أهمُّ مِن قَصْدِ الباطنية وحَربِهم، والانتصافِ للمسلمين من جَورهم وعَسفِهم، فرأى البداية بقلعة شاه دز بأصبهان التي بأيديهم؛ لأن الأذى بها أكثر، وهي متسلطة على سرير ملكه، فخرج بنفسه فحاصرهم في سادس شعبان. وأطال عليها الحصار، ونزل بعض الباطنية بالأمان وساروا إلى باقي قلاعهم، وبقي ابن عطاش مع جماعة يسيرة، فزحف السلطان عليه وقتله وقتَلَ جماعة كثيرة من الباطنية، ثم أمر السلطان محمد بسلخ ابن عطاش وحَشْيِ جلده تبنًا وقَطْع رأسِه، وطيفَ به في الأقاليم."}]
